import{t as n}from"./contentLive-U71wAU_x.js";var t=await n("b:lib/skm-curriculum-patterns.js#SKM_PATTERNS","2eca7c2c60643290ac12",{51:[{pattern:"〜はずだ",meaning:'Suy luận khách quan: "lẽ ra phải ~", "chắc chắn là ~" (dựa trên logic/sự kiện đã biết)',priority:"core",explanation:"Mẫu ngữ pháp 「〜はずだ」 dùng để diễn đạt sự phán đoán, suy luận logic mang tính khách quan của người nói, có nghĩa là 'chắc chắn là ~' hoặc 'lẽ ra phải ~'. Người nói đưa ra khẳng định này dựa trên những căn cứ, lý do xác thực hoặc quy luật hiển nhiên đã biết trước đó. Mẫu này không dùng để diễn đạt phán đoán cảm tính vô căn cứ và cũng không dùng cho hành vi có ý chí của chính bản thân người nói.",examples:[{sentence:"電車はいつも時間通りに運行しているから、あと5分で駅に着くはずだ。",translation:"Tàu điện luôn chạy đúng giờ nên chắc chắn khoảng 5 phút nữa sẽ đến ga."},{sentence:"田中さんは日本に10年間も住んでいたので、日本語がとても上手なはずだ。",translation:"Anh Tanaka đã sống ở Nhật tận 10 năm nên chắc chắn tiếng Nhật của anh ấy phải rất giỏi."}],dialogue:{title:"Tìm chìa khóa",lines:[{speaker:"A",text:"家の鍵が見当たらないんだけど、どこにあるか知らない？",translation:"Tôi không thấy chìa khóa nhà đâu cả, bạn có biết nó ở đâu không?"},{speaker:"B",text:"さっきカバンのポケットに入れたのを見たから、まだそこにあるはずだよ。",translation:"Lúc nãy tôi thấy bạn cất vào ngăn cặp, chắc chắn vẫn còn ở đó đấy."},{speaker:"A",text:"あ、本当だ！奥のほうに入っていたよ。ありがとう。",translation:"A, đúng thật này! Nó nằm ở tận phía trong, cảm ơn bạn nhé."}]},commonMistake:{wrong:"彼は今日休みはずだから、電話しても出ないと思うよ。",correct:"彼は今日休みのはずだから、電話しても出ないと思うよ。",why:"Khi kết hợp với danh từ, mẫu này bắt buộc phải thêm 「の」（N + の + はずだ）chứ không được nối trực tiếp."},note:"Không dùng 「〜はずだ」 để nói về hành động dự định có chủ ý của chính mình (ví dụ: không nói 「私は明日行くはずだ」 mà phải dùng 「行く予定だ」 hoặc 「行くつもりだ」)."},{pattern:"〜はずがない",meaning:'Phủ định mạnh bằng logic: "không thể nào ~ được"',priority:"common",explanation:'Mẫu ngữ pháp 「〜はずがない」 dùng để biểu thị sự phán đoán phủ định mạnh mẽ mang tính logic, mang nghĩa "chắc chắn không thể nào..." hoặc "làm sao mà... có thể xảy ra được". Người nói dựa trên lý do, bằng chứng xác đáng hoặc quy luật hiển nhiên để khẳng định một sự việc tuyệt đối không có khả năng diễn ra. Cấu trúc này thể hiện niềm tin và lập luận chắc chắn của người nói, đồng thời không dùng để nói về hành động có chủ ý của chính bản thân mình.',examples:[{sentence:"毎日あんなに一生懸命勉強したんだから、彼が試験に落ちるはずがない。",translation:"Vì ngày nào anh ấy cũng học hành chăm chỉ đến thế nên không thể nào trượt kỳ thi được."},{sentence:"この店は高級ホテルの中にあるから、料理がまずいはずがない。",translation:"Nhà hàng này nằm trong khách sạn cao cấp nên đồ ăn không thể nào dở được."}],dialogue:{title:"Tìm chìa khóa",lines:[{speaker:"A",text:"鍵が見当たらないんだけど、どこかで見なかった？",translation:"Tôi không thấy chìa khóa đâu cả, bạn có thấy ở đâu không?"},{speaker:"B",text:"さっきカバンに入れたんだから、なくなるはずがないよ。",translation:"Lúc nãy cậu vừa cất vào cặp mà, không thể nào mất được đâu."},{speaker:"A",text:"あ、本当だ、ポケットの奥に入っていた！",translation:"A, đúng rồi, nó nằm ở tận đáy túi áo!"}]},commonMistake:{wrong:"彼はまだ子供だはずがないから、一人で帰れるよ。",correct:"彼はまだ子供のはずがないから、一人で帰れるよ。",why:"Khi kết hợp với danh từ, phải dùng 「N + のはずがない」 chứ không dùng 「だはずがない」."},note:"Trong giao tiếp thân mật thường ngày, 「〜はずがない」 có thể nói gọn thành 「〜はずない」 hoặc dùng tương đương với 「〜わけがない」."},{pattern:"はずだ ≠ べきだ",meaning:'はずだ = suy luận khách quan (có căn cứ); べきだ = bổn phận chủ quan ("đáng ra phải")',priority:"common",explanation:'「はずだ」dùng để biểu thị suy luận logic hoặc phán đoán có căn cứ khách quan của người nói, mang nghĩa "chắc chắn là / lẽ ra phải thế" theo tính toán hoặc quy luật. Trái lại, 「べきだ」thể hiện phán đoán mang tính chủ quan về bổn phận, đạo đức hoặc điều đương nhiên phải làm theo lẽ thường ("nên / đáng ra phải"). Điểm mấu chốt để phân biệt là 「はずだ」nhấn mạnh vào kết quả dự đoán theo logic, còn 「べきだ」nhấn mạnh vào trách nhiệm và hành vi cần thực hiện.',examples:[{sentence:"田中さんは10年も日本に住んでいたので、日本の習慣に詳しいはずだ。",translation:"Anh Tanaka đã sống ở Nhật tận 10 năm nên chắc chắn là sẽ am hiểu tập quán Nhật Bản."},{sentence:"借りたお金は約束した期日までにきちんと返すべきだ。",translation:"Tiền đã vay thì đáng ra phải trả đàng hoàng trước kỳ hạn đã hẹn."}],dialogue:{title:"Chuẩn bị thuyết trình",lines:[{speaker:"A",text:"明日のプレゼンの資料、もう全員に配った？",translation:"Tài liệu thuyết trình ngày mai, cậu đã phát cho mọi người chưa?"},{speaker:"B",text:"はい、昨日のうちにメールで送ったので、みんな確認したはずです。",translation:"Vâng, vì em đã gửi qua email từ hôm qua nên chắc chắn mọi người đã kiểm tra rồi ạ."},{speaker:"A",text:"念のため、重要なページは紙でも印刷しておくべきだよ。",translation:"Để cho chắc chắn, những trang quan trọng thì nên in sẵn ra giấy nữa đấy."}]},commonMistake:{wrong:"約束の時間に遅れそうなら、事前に連絡するはずです。",correct:"約束の時間に遅れそうなら、事前に連絡するべきです。",why:'Khi nêu lên bổn phận, phép lịch sự hoặc lời khuyên cần làm ("nên/phải liên lạc"), ta phải dùng 「べきだ」chứ không dùng 「はずだ」 (vốn chỉ dùng để suy đoán logic).'},note:"Động từ nhóm 3 「する」khi kết hợp với 「べきだ」có hai cách chia là 「するべきだ」hoặc「すべきだ」, trong đó dạng「すべきだ」mang sắc thái trang trọng hơn."},{pattern:"はずがない ≠ ないはずだ",meaning:'はずがない = "không thể nào ~" (mạnh, loại trừ hoàn toàn); ないはずだ = "suy luận rằng không ~" (nhẹ hơn)',priority:"common",explanation:'「はずがない」và「ないはずだ」đều biểu thị suy luận phủ định dựa trên căn cứ logic, nhưng mức độ quả quyết và sắc thái biểu đạt có sự khác biệt rõ rệt.「はずがない」mang sắc thái phủ định tuyệt đối, dùng khi người nói muốn bác bỏ hoàn toàn khả năng xảy ra của sự việc với ý nghĩa "không thể nào có chuyện đó". Trong khi đó,「ないはずだ」chỉ đơn thuần là một phán đoán mang tính phủ định nhẹ nhàng hơn với ý nghĩa "chắc là không / lẽ ra không...", thể hiện suy đoán khách quan chứ không mang tính bài trừ gay gắt. Vì vậy, tùy thuộc vào mức độ chắc chắn và việc có muốn bác bỏ ý kiến/khả năng nào đó hay không mà người nói lựa chọn cấu trúc phù hợp.',examples:[{sentence:"ちゃんと鍵を閉めたのだから、部屋に泥棒が入れるはずがない。",translation:"Vì đã khóa cửa cẩn thận rồi nên trộm không thể nào vào phòng được."},{sentence:"十分に対策を練ったので、今回の計画は失敗しないはずだ。",translation:"Vì đã lên phương án đối phó kỹ lưỡng nên kế hoạch lần này chắc là sẽ không thất bại đâu."}],dialogue:{title:"Tìm tài liệu quan trọng",lines:[{speaker:"A",text:"さっき机の上に置いた書類が見当たらないんだけど、誰か持っていった？",translation:"Tài liệu tôi vừa để trên bàn không thấy đâu nữa, có ai cầm đi không?"},{speaker:"B",text:"さっきまで誰も部屋にいなかったから、他の人が持って行くはずがないよ。",translation:"Nãy giờ không có ai trong phòng cả nên người khác không thể nào cầm đi được đâu."},{speaker:"A",text:"そうだよね。もう一度引き出しの中を探してみるよ。",translation:"Đúng thế nhỉ. Để tôi thử tìm lại trong ngăn kéo xem sao."}]},commonMistake:{wrong:"明日は雨だから、彼は来ないはずがない。",correct:"明日は雨だから、彼は来ないはずだ。",why:"「〜ないはずがない」là dạng phủ định kép mang nghĩa 'chắc chắn sẽ đến', muốn diễn đạt suy đoán 'chắc là không đến' thì phải dùng「〜ないはずだ」."},note:"「はずがない」mang sắc thái bác bỏ mạnh mẽ tương đương với「わけがない」, trong khi「ないはずだ」chỉ là dạng suy đoán phủ định nhẹ nhàng của cấu trúc「〜はずだ」."}],52:[{pattern:"〜にちがいない",meaning:"Chắc chắn là ~ (suy luận mạnh ≈90%, có căn cứ khách quan)",priority:"core",explanation:"Mẫu câu này dùng để thể hiện sự suy luận, phán đoán có độ chắc chắn rất cao (khoảng 90%) của người nói dựa trên căn cứ hoặc bằng chứng thực tế. Người nói tin tưởng tuyệt đối rằng nhận định của mình là đúng sự thật ('chắc chắn là...', 'không thể sai được'). Cần lưu ý mẫu này chỉ dùng để phán đoán về người khác hoặc sự việc khách quan, tuyệt đối không dùng cho bản thân.",examples:[{sentence:"明かりがついているから、田中さんはまだオフィスにいるにちがいない。",translation:"Vì đèn vẫn sáng nên chắc chắn anh Tanaka vẫn còn ở trong văn phòng."},{sentence:"これだけ長い行列ができているのだから、この店の料理はおいしいにちがいない。",translation:"Người xếp hàng dài đến mức này thì đồ ăn của quán này chắc chắn là rất ngon."}],dialogue:{title:"Tìm người để quên áo",lines:[{speaker:"A",text:"この高級そうなジャケット、誰の忘れ物かな。",translation:"Chiếc áo khoác trông sang trọng này là đồ của ai để quên nhỉ?"},{speaker:"B",text:"さっきまでそこに座っていた社長風の男性のものにちがいないよ。",translation:"Chắc chắn là của người đàn ông trông như giám đốc vừa ngồi ở đó lúc nãy rồi."},{speaker:"A",text:"そうだね、まだ遠くに行っていないはずだから届けてこよう。",translation:"Đúng thế, chắc bác ấy chưa đi xa đâu, mình đem trả lại thôi."}]},commonMistake:{wrong:"私は一生懸命練習したから、明日の試合で勝つにちがいない。",correct:"私は一生懸命練習したから、明日の試合で絶対に勝ってみせる。",why:"「〜にちがいない」chỉ dùng cho phán đoán suy luận về người khác hoặc sự việc khách quan, không dùng để nói về hành động hay ý chí của bản thân."},note:"So với「〜はずだ」(chắc chắn dựa trên logic, lý lẽ khách quan),「〜にちがいない」mang tính trực giác và sự quả quyết chủ quan mạnh mẽ hơn từ người nói."},{pattern:"〜かもしれない",meaning:"Có thể là ~ (khả năng ≈40%, không chắc chắn)",priority:"common",explanation:'Mẫu 「〜かもしれない」 dùng để diễn đạt suy đoán của người nói về một khả năng có thể xảy ra nhưng độ chắc chắn không cao (chỉ khoảng 30% - 50%). Mẫu này mang ý nghĩa "có thể", "có lẽ", "không chừng là...", dùng khi người nói không đủ chứng cứ xác thực để khẳng định chắc chắn. Trong hội thoại thân mật hàng ngày, người Nhật thường rút gọn thành 「〜かも」, còn trong hoàn cảnh trang trọng, lịch sự sẽ dùng 「〜かもしれません」.',examples:[{sentence:"毎日無理をして働き続けると、体を壊してしまうかもしれないよ。",translation:"Nếu cứ tiếp tục làm việc quá sức mỗi ngày thì có thể bạn sẽ bị đổ bệnh đấy."},{sentence:"この店はいつも人気だから、予約しないと入れないかもしれない。",translation:"Quán này lúc nào cũng đông khách nên nếu không đặt trước thì có thể sẽ không vào được."}],dialogue:{title:"Tìm chìa khóa để quên",lines:[{speaker:"A",text:"私の鍵が見当たらないんだけど、どこにあるか見なかった？",translation:"Tôi không thấy chìa khóa của mình đâu cả, cậu có thấy ở đâu không?"},{speaker:"B",text:"さっき会議室にいたから、そこに忘れてきたかもしれないよ。",translation:"Lúc nãy cậu ở phòng họp nên có thể đã để quên ở đó rồi đấy."},{speaker:"A",text:"あ、そうだった！今すぐ確認してくるね。",translation:"A, đúng rồi! Tớ đi kiểm tra ngay đây."}]},commonMistake:{wrong:"明日は暇だかもしれないから、一緒に買い物に行きませんか。",correct:"明日は暇かもしれないから、一緒に買い物に行きませんか。",why:"Với tính từ đuôi な và danh từ ở thể khẳng định hiện tại, phải bỏ 「だ」 rồi mới kết hợp trực tiếp với 「かもしれない」."},note:"Trong thang độ chắc chắn, 「〜かもしれない」 (khoảng 40%) thể hiện khả năng thấp hơn nhiều so với 「〜だろう／でしょう」 (khoảng 70-80%) và 「〜に違いない」 (khoảng 90%)."},{pattern:"確信[かくしん]の 度合[どあ]い：にちがいない ＞ だろう ＞ かもしれない",meaning:"Thang độ chắc chắn: にちがいない (≈90%) > だろう (≈60%) > かもしれない (≈40%)",priority:"common",explanation:'Ba mẫu ngữ pháp này dùng để thể hiện các mức độ phỏng đoán và sự chắc chắn giảm dần của người nói dựa trên bằng chứng hoặc cảm nhận cá nhân. Trong đó, 「〜に違いない」thể hiện sự tin tưởng mạnh mẽ (khoảng 90%) khi có căn cứ vững chắc, mang nghĩa là "chắc chắn là". 「〜だろう / でしょう」thể hiện suy đoán thông thường có cơ sở vừa phải (khoảng 60%), mang nghĩa "có lẽ / chắc là". Còn 「〜かもしれない」thể hiện khả năng thấp hoặc suy đoán dè dặt (khoảng 40%), mang nghĩa "có thể / biết đâu chừng".',examples:[{sentence:"あんなに 毎日[まいにち] 練習[れんしゅう]したのだから、彼[かれ]が 優勝[ゆうしょう]する にちがいない。",translation:"Đã luyện tập chăm chỉ mỗi ngày như thế thì chắc chắn anh ấy sẽ giành chức vô địch."},{sentence:"午後[ごご]から 雨[あめ]が 降[ふ]るかもしれないので、傘[かさ]を 持[も]って 行[い]った ほうが いいですよ。",translation:"Buổi chiều có thể trời sẽ mưa nên bạn nên mang theo ô đi nhé."}],dialogue:{title:"Dự đoán kết quả thi",lines:[{speaker:"A",text:"田中[たなか]さん、昨日[きのう]の テスト どうだった？ 合格[ごうかく]できそう？",translation:"Tanaka này, bài kiểm tra hôm qua thế nào rồi? Có vẻ đỗ được không?"},{speaker:"B",text:"全然[ぜんぜん] 自信[じしん]が ないよ。難[むずか]しかったから、不合格[ふごうかく]かもしれない。",translation:"Mình hoàn toàn không tự tin chút nào. Đề khó quá nên có thể trượt mất."},{speaker:"A",text:"ずっと 一生懸命[いっしょうけんめい] 勉強[べんきょう]していたから、合格[ごうかく]する にちがいないよ！ 元気[げんき]を 出[だ]して！",translation:"Cậu đã học hành chăm chỉ suốt mà, chắc chắn sẽ đỗ thôi! Vui lên đi!"}]},commonMistake:{wrong:"たぶん 彼[かれ]は 今日[きょう]の 飲[の]み会[かい]に 来[こ]ない にちがいない。",correct:"たぶん 彼[かれ]は 今日[きょう]の 飲[の]み会[かい]に 来[こ]ない だろう。",why:"Phó từ 「たぶん」 (có lẽ/chắc là) chỉ mức độ chắc chắn vừa phải nên không thể đi cùng mẫu phỏng đoán chắc nịch 「にちがいない」, mà phải dùng với 「だろう」 hoặc 「かもしれない」."},note:"「〜に違いない」 là sự suy đoán mang tính chủ quan dựa trên bằng chứng của người nói, không dùng cho sự thật hiển nhiên 100% hay hiện tượng tự nhiên có tính quy luật tuyệt đối."}],53:[{pattern:"〜べきだ ／ 〜べきではない",meaning:"Bổn phận / lẽ ra phải làm — phán xét đạo lý CHỦ QUAN",priority:"core",explanation:"Mẫu 「〜べきだ ／ 〜べきではない」 dùng để thể hiện quan điểm, phán đoán chủ quan của người nói rằng theo đạo lý, lương tâm hoặc lẽ thường thì một hành động là đúng đắn, nên làm hoặc không được phép làm. Ngữ pháp đi kèm với động từ thể từ điển (V-る), riêng động từ 「する」 có thể chia thành 「すべき」 hoặc 「するべき」. Mẫu này mang sắc thái phán xét đạo đức và tính áp đặt khá mạnh, do đó không dùng cho các quy định/luật pháp khách quan và tuyệt đối tránh dùng để khuyên bảo trực tiếp người bề trên.",examples:[{sentence:"親は子どもの話を最後までしっかり聞くべきだ。",translation:"Cha mẹ nên lắng nghe con cái nói một cách cẩn thận đến cùng."},{sentence:"他人の悪口をSNSに書き込むべきではない。",translation:"Không nên viết những lời nói xấu người khác lên mạng xã hội."}],dialogue:{title:"Báo cáo lỗi trong công việc",lines:[{speaker:"A",text:"今回のミス、部長にすぐ報告するべきかな？",translation:"Lỗi lần này, mình có nên báo cáo ngay cho trưởng phòng không nhỉ?"},{speaker:"B",text:"もちろん、問題が大きくなる前に早く相談すべきだよ。",translation:"Đương nhiên rồi, cậu nên trao đổi sớm trước khi vấn đề trở nên nghiêm trọng hơn."},{speaker:"A",text:"そうだね。隠さずに正直に話して謝るよ。",translation:"Ừ nhỉ. Mình sẽ không giấu giếm mà thẳng thắn nói ra và xin lỗi."}]},commonMistake:{wrong:"先生、体調が悪そうですね。今日は早く帰るべきですよ。",correct:"先生、体調が悪そうですね。今日はお早めにお帰りになったほうがいいですよ。",why:"「〜べきだ」 mang sắc thái phán xét đạo lý bề trên nên rất thất lễ nếu dùng để đưa ra lời khuyên trực tiếp cho người có vai vế cao hơn như giáo viên hay cấp trên."},note:"Khác với 「〜なければならない」 mang tính nghĩa vụ bắt buộc theo quy định hoặc luật pháp khách quan, 「〜べきだ」 hoàn toàn là nhận định đạo đức mang tính chủ quan của người nói."},{pattern:"〜ものだ（一般真理[いっぱんしんり]・感慨[かんがい]）",meaning:"Chân lý chung / lẽ thường KHÁCH QUAN; hoặc hồi tưởng cảm thán",priority:"common",explanation:"Mẫu ngữ pháp 「〜ものだ」 dùng để khẳng định một chân lý, quy luật tự nhiên hoặc bản chất vốn có của sự vật, sự việc mà xã hội hay mọi người đều coi là lẽ đương nhiên. Ngoài ra, khi kết hợp với thể quá khứ 「〜たものだ」, mẫu này thể hiện tâm trạng hoài niệm, hồi tưởng sâu sắc về một thói quen hoặc sự việc thường xuyên xảy ra trong quá khứ. Mẫu câu này mang sắc thái chiêm nghiệm, cảm thán khách quan hoặc cảm xúc chung, không dùng cho sự việc mang tính nhất thời, cá biệt.",examples:[{sentence:"人間は誰でもプレッシャーを感じると失敗するものだ。",translation:"Con người ta ai cũng vậy, khi cảm thấy áp lực thì thường sẽ dễ mắc sai lầm."},{sentence:"子供のころは、夏休みになると毎日近くの森へ虫捕りに行ったものだ。",translation:"Hồi còn nhỏ, hễ cứ đến kỳ nghỉ hè là ngày nào tôi cũng vào khu rừng gần nhà để bắt côn trùng."}],dialogue:{title:"Kỷ niệm thời học sinh",lines:[{speaker:"A",text:"この写真を見て。高校時代は放課後によくこの喫茶店でおしゃべりしたものだね。",translation:"Cậu nhìn tấm ảnh này đi. Hồi cấp ba tụi mình hay la cà tán gẫu ở quán cà phê này ghê."},{speaker:"B",text:"うわあ、懐かしい！テストが終わるたびにみんなでパフェを食べに行ったよね。",translation:"Oa, nhớ thật đấy! Cứ mỗi lần thi xong là cả bọn lại rủ nhau đi ăn kem parfait nhỉ."},{speaker:"A",text:"あれからもう10年も経ったなんて、本当に時間が経つのは早いものだね。",translation:"Thế mà đã 10 năm trôi qua rồi, thời gian trôi nhanh thật đấy."}]},commonMistake:{wrong:"昨日は久しぶりに高校時代の友達とお酒を飲んだものだ。",correct:"昨日は久しぶりに高校時代の友達とお酒を飲んだ。",why:"Mẫu 「〜たものだ」 chỉ dùng để hồi tưởng lại thói quen, hành động lặp đi lặp lại nhiều lần trong quá khứ, không dùng cho sự việc chỉ xảy ra một lần cụ thể như ngày hôm qua."},note:"Cần phân biệt 「〜ものだ」 (nói về lẽ đương nhiên/chân lý chung hoặc hồi tưởng thói quen cũ) với 「〜ことだ」 (đưa ra lời khuyên trực tiếp nên/không nên làm gì trong một tình huống cụ thể)."},{pattern:"〜ものではない（〜ものじゃない）",meaning:"Cấm / không nên — theo lẽ thường (nhẹ hơn べきではない)",priority:"common",explanation:"Mẫu「〜ものではない（〜ものじゃない）」được dùng để đưa ra lời khuyên, cảnh cáo mang tính đạo lý hoặc lẽ thường tình trong xã hội rằng 'không nên/không được' làm một việc gì đó. Cấu trúc này kết hợp với động từ thể từ điển (V辞書形 + ものではない) và thường do người lớn tuổi, người có kinh nghiệm nhắc nhở thế hệ sau. Trong giao tiếp thường nhật, dạng nói thân mật「〜ものじゃない」được sử dụng rất phổ biến. Mẫu câu không dùng để ra lệnh cấm đoán trực tiếp cho một hành vi cụ thể mang tính cấp bách.",examples:[{sentence:"目上の人に対して、そんな失礼な口の利き方をするものではない。",translation:"Không nên ăn nói thất lễ như thế đối với người bề trên."},{sentence:"借りたお金は期日までにきちんと返すべきで、そのまま放置しておくものではない。",translation:"Tiền đã vay thì phải trả đúng hạn, không nên cứ để mặc kệ như vậy."}],dialogue:{title:"Lời khuyên của tiền bối",lines:[{speaker:"A",text:"後輩の前で感情的になって大声で怒鳴るものではないよ。",translation:"Không nên mất bình tĩnh mà quát tháo lớn tiếng trước mặt cấp dưới đâu."},{speaker:"B",text:"すみません、注意しても同じミスを繰り返すのでついイライラしてしまって…。",translation:"Em xin lỗi, vì nhắc nhở rồi mà cậu ấy vẫn lặp lại lỗi cũ nên em lỡ bực mình quá..."},{speaker:"A",text:"気持ちは分かるけど、指導するときは冷静に理由を説明してあげよう。",translation:"Anh hiểu cảm giác đó, nhưng khi hướng dẫn thì hãy bình tĩnh giải thích lý do nhé."}]},commonMistake:{wrong:"他人の秘密を簡単に人に話さないものではない。",correct:"他人の秘密を簡単に人に話すものではない。",why:"Mẫu「〜ものではない」bản thân đã mang nghĩa phủ định (không nên làm gì) nên động từ đứng trước bắt buộc phải ở thể từ điển (V辞書形), không chia về thể phủ định (V-nai)."},note:"So với「〜べきではない」(mang tính trách nhiệm/nghĩa vụ mạnh mẽ),「〜ものではない」mang sắc thái khuyên răn nhẹ nhàng hơn dựa trên quan niệm đạo đức hoặc phép lịch sự chung."},{pattern:"する → すべき（書[か]き言葉[ことば]の注意[ちゅうい]）",meaning:"Dạng chuẩn: する→すべき (văn viết/thi JLPT); するべき cũng được nhưng ít chuẩn hơn",priority:"common",explanation:"Khi kết hợp động từ nhóm 3 (động từ đuôi する) với ngữ pháp べきだ, dạng chuẩn mực trong văn viết (書き言葉) và bài thi JLPT là chuyển thành 「〜すべきだ」 thay vì 「〜するべきだ」. Mẫu câu này diễn tả việc một người nên làm hoặc có nghĩa vụ đạo đức phải làm một hành động nào đó theo lẽ thường và quy chuẩn xã hội. Dù trong văn nói hàng ngày người Nhật vẫn có thể dùng 「〜するべき」, nhưng trong văn bản học thuật, báo chí và thi cử thì 「〜すべき」 luôn là hình thức chuẩn chỉnh nhất.",examples:[{sentence:"環境を守るために、私たちはプラスチックゴミを削減すべきだ。",translation:"Để bảo vệ môi trường, chúng ta nên cắt giảm rác thải nhựa."},{sentence:"重要な決定を下す前に、専門家の意見をよく検討すべきです。",translation:"Trước khi đưa ra quyết định quan trọng, chúng ta nên xem xét kỹ ý kiến của các chuyên gia."}],dialogue:{title:"Thảo luận kế hoạch mới",lines:[{speaker:"A",text:"このプロジェクトを進める前に、他部署とも情報共有すべきだと思います。",translation:"Tôi nghĩ trước khi triển khai dự án này, chúng ta nên chia sẻ thông tin với các phòng ban khác."},{speaker:"B",text:"そうですね。全員が納得した上で始めたほうがスムーズですしね。",translation:"Đúng vậy. Bắt đầu sau khi mọi người đã đồng thuận thì mọi việc sẽ suôn sẻ hơn."},{speaker:"A",text:"では、さっそく来週のミーティングを設定しましょう。",translation:"Vậy thì chúng ta hãy lên lịch họp vào tuần tới ngay nhé."}]},commonMistake:{wrong:"社会人として、約束の時間は守るように行動しますべきだ。",correct:"社会人として、約束の時間は守るように行動すべきだ。",why:"Ngữ pháp べきだ không kết hợp với thể ます, và đối với động từ nhóm 3 thì dạng chuẩn xác nhất là chuyển 「〜する」 thành 「〜すべき」."},note:"Mẫu 「〜すべき」 thể hiện đạo lý hoặc bổn phận chung mang tính khách quan, tuyệt đối không dùng để trực tiếp áp đặt hay sai bảo cấp trên."}],54:[{pattern:"〜というより（（むしろ）〜）",meaning:"Đúng hơn là ~ / Nói đúng hơn là ~ (đính chính, diễn đạt lại)",priority:"core",explanation:'Mẫu câu này mang ý nghĩa "nói đúng hơn là...", dùng khi người nói muốn đính chính hoặc đưa ra cách diễn đạt, nhận định chính xác và phù hợp hơn so với cách gọi trước đó. Cấu trúc thường được sử dụng linh hoạt trong cả giao tiếp hàng ngày lẫn văn viết khi muốn cân nhắc giữa hai cách nhìn nhận về cùng một sự vật, hiện tượng. Vế sau rất thường đi kèm với phó từ 「むしろ」(thực ra/đúng hơn) hoặc các cụm 「〜と言ったほうがいい／正しい」 để nhấn mạnh nhận định mới.',examples:[{sentence:"あの二人は恋人というより、むしろ親友のような関係に見える。",translation:"Hai người họ trông giống như bạn thân hơn là người yêu."},{sentence:"この仕事は難しいというより、やることが多すぎて時間が足りないだけだ。",translation:"Công việc này nói đúng hơn là quá nhiều việc nên không đủ thời gian, chứ không hẳn là khó."}],dialogue:{title:"Nhận xét đồng nghiệp mới",lines:[{speaker:"A",text:"新しく入った田中さんはとても真面目な人ですね。",translation:"Anh Tanaka mới vào là người rất nghiêm túc nhỉ."},{speaker:"B",text:"そうですね。でも真面目というより、むしろ恥ずかしがり屋なだけだと思いますよ。",translation:"Đúng vậy nhỉ. Nhưng tôi nghĩ nói đúng hơn là anh ấy chỉ ngại ngùng thôi chứ không hẳn là quá nghiêm túc đâu."},{speaker:"A",text:"なるほど。まだ職場に慣れていなくて緊張しているのかもしれませんね。",translation:"Ra là vậy. Có lẽ anh ấy chưa quen với nơi làm việc nên đang căng thẳng thôi nhỉ."}]},commonMistake:{wrong:"彼は頭がいいより、むしろ努力家だ。",correct:"彼は頭がいいというより、むしろ努力家だ。",why:"Khi muốn đính chính hoặc lựa chọn cách diễn đạt chính xác hơn cho sự việc ('nói đúng hơn là...'), bắt buộc phải dùng 「〜というより」 chứ không thể dùng riêng trợ từ 「より」 như câu so sánh hơn kém thông thường."},note:"Khác với 「〜にしては」 hay 「〜わりに」 dùng để biểu thị kết quả bất ngờ trái với tiêu chuẩn/kỳ vọng thông thường, 「〜というより」 thuần túy dùng để lựa chọn từ ngữ và định nghĩa lại sự việc cho chuẩn xác."},{pattern:"〜にしては",meaning:"Với tư cách là ~ mà / Xét ra thì ~ — so với mốc kỳ vọng từ chính chủ thể",priority:"common",explanation:"Mẫu ngữ pháp này dùng để diễn tả một sự việc, thực tế ở vế sau vượt ngoài dự đoán hoặc trái ngược với mức kỳ vọng thông thường sinh ra từ tiêu chuẩn ở vế trước. Vế trước thường là những dữ liệu, sự thật hoặc con số cụ thể (như tuổi tác, giá tiền, thời gian). Vế sau thể hiện cảm nhận, đánh giá mang tính ngạc nhiên của người nói và không đi cùng câu mệnh lệnh hay ý chí.",examples:[{sentence:"このアパートは、家賃が3万円にしては部屋が広くて綺麗だ。",translation:"Căn hộ này so với mức giá thuê chỉ 3 vạn yên thì phòng ốc vừa rộng rãi lại sạch sẽ."},{sentence:"山田さんは今年70歳にしては、とても若々しくて元気ですね。",translation:"Bác Yamada so với tuổi 70 năm nay thì trông rất trẻ trung và khỏe khoắn nhỉ."}],dialogue:{title:"Thưởng thức bánh tự làm",lines:[{speaker:"A",text:"これ、田中さんが一人で作ったケーキなんだって。食べてみて。",translation:"Nghe nói đây là bánh do anh Tanaka tự làm một mình đấy. Cậu ăn thử đi."},{speaker:"B",text:"わあ、初めてにしては見た目も綺麗だし、お店のみたいに美味しいね。",translation:"Oa, lần đầu làm mà hình thức vừa đẹp mắt, lại ngon như mua ở tiệm vậy nhỉ."},{speaker:"A",text:"本当だね。普段料理をしない人にしては完成度が高すぎるよ。",translation:"Công nhận luôn. So với một người bình thường không nấu nướng thì độ hoàn thiện này quá đỉnh rồi."}]},commonMistake:{wrong:"今日は冬だにしては、コートがいらないほど暖かいですね。",correct:"今日は冬にしては、コートがいらないほど暖かいですね。",why:"Khi kết hợp với Danh từ (N), mẫu「〜にしては」phải nối trực tiếp với danh từ chứ không thêm「だ」."},note:"So với「〜わりに（は）」có thể đi với các danh từ trừu tượng chỉ mức độ/phạm trù (như 年齢、値段),「〜にしては」thường ưu tiên đi với mốc hoặc con số cụ thể (như 70歳、1000円) để làm tiêu chuẩn đánh giá."},{pattern:"〜わりに（は）",meaning:"So với lẽ thường thì ~ / Tuy ~ mà ~ — so với mức kỳ vọng thống kê / trung bình",priority:"common",explanation:"Mẫu ngữ pháp 「〜わりに（は）」được dùng để diễn tả ý nghĩa 'tuy... nhưng / so với... thì...', thể hiện kết quả hoặc tình trạng ở vế sau khác biệt, bất ngờ so với mức độ kỳ vọng thông thường dựa trên tiêu chuẩn ở vế trước. Về mặt kết nối, mẫu đi với thể thông thường của Động từ và Tính từ đuôi -i, Tính từ đuôi -na giữ nguyên 「な」, và Danh từ đi kèm 「の」. Mẫu câu này thường mang sắc thái đánh giá, nhận định chủ quan của người nói khi so sánh với một mặt bằng chung (như độ tuổi, mức giá, thời gian luyện tập) và vế sau không dùng câu mệnh lệnh hay ý chí.",examples:[{sentence:"祖父は75歳という年齢のわりに、足腰が丈夫で毎日元気に散歩している。",translation:"Ông tôi tuy đã ở độ tuổi 75 nhưng chân tay vẫn rất chắc khỏe, ngày nào cũng khỏe khoắn đi dạo."},{sentence:"彼はあまり勉強しなかったわりには、試験でいい点数を取った。",translation:"Cậu ấy tuy không học mấy mà lại đạt điểm khá cao trong kỳ thi."}],dialogue:{title:"Trải nghiệm máy ảnh mới",lines:[{speaker:"A",text:"先週買ったこのカメラ、値段が安いわりに画質がすごく綺麗なんだよ。",translation:"Chiếc máy ảnh tớ mua tuần trước, giá rẻ thế mà chất lượng ảnh lại nét cực kỳ luôn."},{speaker:"B",text:"え、本当？操作も簡単そうだし、使いやすそうだね。",translation:"Ồ, thật sao? Thao tác trông cũng đơn giản, có vẻ dễ dùng ghê."},{speaker:"A",text:"うん、初心者が使う分には十分すぎるくらいだよ。",translation:"Ừ, đối với người mới bắt đầu dùng thì quá đủ rồi."}]},commonMistake:{wrong:"彼は子供わりに、難しい敬語を上手に使っている。",correct:"彼は子供のわりに、難しい敬語を上手に使っている。",why:"Khi kết hợp với Danh từ, trước 「わりに（は）」 bắt buộc phải có trợ từ 「の」 chứ không được ghép trực tiếp Danh từ."},note:"So với 「〜にしては」 (nhấn mạnh sự ngạc nhiên trước một mốc/sự thật cụ thể), 「〜わりに（は）」 so sánh với một khoảng tiêu chuẩn, mặt bằng chung mang tính thống kê như tuổi tác, giá cả, thời gian."}],55:[{pattern:"〜うちに",meaning:"Tranh thủ làm trong khi trạng thái vẫn còn (trước khi trạng thái đổi)",priority:"core",explanation:"Mẫu ngữ pháp này diễn tả ý nghĩa tranh thủ làm một hành động có chủ ý trong khi một trạng thái hoặc điều kiện thuận lợi vẫn đang duy trì. Hành động ở vế sau cần được thực hiện trước khi trạng thái ở vế trước thay đổi hoặc mất đi cơ hội tốt. Ngữ cảnh thường dùng trong đời sống hàng ngày để đưa ra lời khuyên, lời nhắc nhở hoặc bày tỏ dự định tận dụng thời điểm thích hợp.",examples:[{sentence:"記憶が新しいうちに、今日習った単語を復習しておきます。",translation:"Tranh thủ lúc trí nhớ còn mới, tôi sẽ ôn tập lại từ vựng đã học hôm nay."},{sentence:"日本に留学しているうちに、一度富士山に登ってみたいです。",translation:"Tranh thủ trong thời gian đang du học ở Nhật, tôi muốn thử một lần leo núi Phú Sĩ."}],dialogue:{title:"Lên kế hoạch dã ngoại",lines:[{speaker:"A",text:"週末、天気がいいうちに近所の公園へピクニックに行かない？",translation:"Cuối tuần này, tranh thủ lúc thời tiết còn đẹp thì mình đi dã ngoại ở công viên gần đây không?"},{speaker:"B",text:"いいね！最近ずっと雨予報が続いていたから、ぜひ行こう。",translation:"Hay đấy! Gần đây trời cứ mưa suốt nên nhất định phải đi thôi."},{speaker:"A",text:"じゃあ、お弁当のおかずを何にするか今から決めよう。",translation:"Vậy thì từ bây giờ chúng mình cùng quyết định xem làm món gì cho hộp cơm bento nhé."}]},commonMistake:{wrong:"独身うちに、やりたいことを全部やっておきたいです。",correct:"独身のうちに、やりたいことを全部やっておきたいです。",why:"Khi kết hợp Danh từ với「うちに」, bắt buộc phải có trợ từ「の」(công thức: N のうちに) chứ không được ghép trực tiếp như cách tư duy tiếng Việt."},note:"Khác với「〜間に」chỉ đơn thuần nêu mốc thời gian diễn ra sự việc,「〜うちに」nhấn mạnh cảm giác tranh thủ và tính cấp bách trước khi trạng thái thuận lợi kết thúc."},{pattern:"〜ないうちに",meaning:"Trước khi (điều gì đó) xảy ra — nhấn mạnh chưa xảy ra",priority:"common",explanation:'Mẫu câu「〜ないうちに」diễn tả ý nghĩa "trước khi sự việc hoặc trạng thái nào đó xảy ra, hãy tranh thủ làm gì đó". Cấu trúc này nhấn mạnh việc chủ động thực hiện hành động trước khi có sự biến đổi về hoàn cảnh hoặc trước khi tình huống bất lợi diễn ra. Vế sau thường đi cùng các hình thức thể hiện ý chí, lời khuyên, đề nghị hoặc mệnh lệnh như「〜てください」「〜ましょう」.',examples:[{sentence:"スープが冷めないうちに、どうぞ召し上がってください。",translation:"Xin mời bạn dùng súp trước khi nó bị nguội (tranh thủ khi còn nóng)."},{sentence:"外が暗くならないうちに、公園でのジョギングを終えましょう。",translation:"Chúng ta hãy kết thúc buổi chạy bộ ở công viên trước khi trời tối nhé."}],dialogue:{title:"Đi ăn trưa sớm",lines:[{speaker:"A",text:"12時になって店が混まないうちに、早めにお昼ご飯を食べに行きませんか。",translation:"Trước khi đến 12 giờ quán trở nên đông đúc, chúng ta đi ăn trưa sớm nhé?"},{speaker:"B",text:"いいですね！ちょうどお腹もすいてきたところです。",translation:"Được đấy! Tôi cũng vừa vặn đang thấy đói bụng."},{speaker:"A",text:"じゃあ、エレベーターが混雑する前にすぐ出発しましょう。",translation:"Vậy thì chúng ta xuất phát ngay trước khi thang máy đông người nhé."}]},commonMistake:{wrong:"スープが冷めない前に、早く飲んでください。",correct:"スープが冷めないうちに、早く飲んでください。",why:"Trong tiếng Nhật không kết hợp thể phủ định「Vない」với「前に」; để diễn đạt ý 'tranh thủ trước khi chuyển sang trạng thái nào đó' thì phải dùng「Vないうちに」."},note:"Khác với「〜前に」chỉ đơn thuần xác định mốc thời gian xảy ra trước một sự kiện,「〜ないうちに」nhấn mạnh vào quá trình biến đổi trạng thái (trời tối dần, thức ăn nguội đi...) và mang sắc thái tranh thủ thời gian."},{pattern:"うちに ≠ 間[あいだ]に",meaning:"Phân biệt: うちに (tranh thủ → kết quả tức thời) ≠ 間に (khoảng thời gian → hành động kéo dài song song)",priority:"common",explanation:"「〜うちに」nhấn mạnh ý thức tranh thủ thời gian hoặc trạng thái thuận lợi trước khi điều kiện thay đổi để thực hiện một hành động có chủ đích. Ngược lại,「〜間に」chỉ đơn thuần xác định một khoảng thời gian khách quan mà trong đó một hành động hoặc sự việc khác diễn ra. Do đó, khi muốn diễn tả hành động kéo dài song song hoặc sự việc xảy ra tự nhiên trong một khoảng thời gian, ta dùng「間に」chứ không dùng「うちに」.",examples:[{sentence:"スープが温かいうちに、早く召し上がってください。",translation:"Hãy dùng súp ngay khi còn đang nóng nhé."},{sentence:"電車を待っている間に、単語帳を見て勉強していた。",translation:"Trong khoảng thời gian chờ tàu điện, tôi đã xem sổ tay từ vựng để học bài."}],dialogue:{title:"Tranh thủ trước cơn mưa",lines:[{speaker:"A",text:"雨が降らないうちに、早くスーパーへ買い物に行こうよ。",translation:"Tranh thủ lúc trời chưa mưa, chúng ta mau đi siêu thị mua đồ đi."},{speaker:"B",text:"そうだね。さっき暗い雲が出てきたから、すぐ降るかもしれないね。",translation:"Ừ nhỉ. Lúc nãy thấy mây đen kéo đến rồi, chắc sắp mưa đấy."},{speaker:"A",text:"うん、降ってくる前に急いで行って戻ってこよう！",translation:"Ừ, mau đi rồi về trước khi trời đổ mưa nào!"}]},commonMistake:{wrong:"料理が温かい間に、どうぞ召し上がってください。",correct:"料理が温かいうちに、どうぞ召し上がってください。",why:"Khi muốn khuyên bảo hoặc thúc giục tranh thủ làm gì trước khi trạng thái thuận lợi mất đi (như khi đồ ăn còn ấm, khi còn trẻ...), ta phải dùng「うちに」thay vì「間に」."},note:"Vế sau của「〜うちに」thường chứa ý chí, lời rủ rê hoặc yêu cầu (〜たい、〜てください、〜よう), trong khi「〜間に」chủ yếu diễn tả hành động hoặc sự việc diễn ra một cách khách quan trong khung thời gian đó."}],56:[{pattern:"〜間[あいだ]に",meaning:"Trong khi (khoảng) — vị ngữ vế sau là sự kiện tức thời",priority:"core",explanation:"Mẫu câu 「〜間に」 dùng để diễn tả một hành động hoặc sự việc mang tính thời điểm, khoảnh khắc xảy ra tại một lúc nào đó trong khoảng thời gian vế trước diễn ra. Vế trước là một quá trình hay trạng thái có độ dài thời gian (thường đi với V-ている, V-ない, Nの), còn vế sau là động từ dứt khoát, tức thời và kết thúc ngay trong khoảng đó. Mẫu này thường mang sắc thái tranh thủ tận dụng thời gian để làm việc gì đó, hoặc diễn tả một sự việc bất ngờ chen ngang.",examples:[{sentence:"日本に留学している間に、ぜひ富士山に一度登ってみたいです。",translation:"Trong thời gian đang du học ở Nhật Bản, tôi nhất định muốn thử leo núi Phú Sĩ một lần."},{sentence:"雨が降らない間に、急いで近くのスーパーへ買い出しに行こう。",translation:"Trong lúc trời chưa mưa, chúng ta hãy nhanh chóng đi siêu thị gần đây mua đồ nhé."}],dialogue:{title:"Tranh thủ lúc nghỉ trưa",lines:[{speaker:"A",text:"昼休みの間に、近くの銀行へ行って手続きを済ませてくるね。",translation:"Trong giờ nghỉ trưa, tớ tranh thủ ra ngân hàng gần đây làm xong thủ tục nhé."},{speaker:"B",text:"いってらっしゃい。外はかなり暑いから気をつけてね。",translation:"Cậu đi nhé. Ngoài trời đang khá nóng nên cẩn thận đấy."},{speaker:"A",text:"ありがとう。午後の会議が始まる前には戻るよ。",translation:"Cảm ơn cậu. Tớ sẽ quay lại trước khi cuộc họp chiều bắt đầu."}]},commonMistake:{wrong:"電車を待っている間、急に友達から電話がかかってきた。",correct:"電車を待っている間に、急に友達から電話がかかってきた。",why:"Vì cuộc gọi đến là sự kiện xảy ra tại một thời điểm tức thời chứ không kéo dài liên tục suốt lúc đợi tàu, nên bắt buộc phải dùng 「間に」."},note:"Cần phân biệt với 「〜間」 (không có に), dùng khi hành động hoặc trạng thái ở vế sau diễn ra liên tục, kéo dài suốt toàn bộ thời gian của vế trước."},{pattern:"〜間[あいだ]（ずっと）",meaning:"Suốt cả khoảng thời gian — vị ngữ vế sau kéo dài",priority:"common",explanation:"Mẫu câu 「〜間（ずっと）」 dùng để diễn tả một hành động hoặc trạng thái ở vế sau diễn ra liên tục, kéo dài trong suốt toàn bộ khoảng thời gian của sự việc ở vế trước. Vế trước thường kết hợp với động từ thể ている, tính từ hoặc danh từ (N + の) biểu thị một khoảng thời gian. Điểm mấu chốt là vị ngữ vế sau bắt buộc phải là hành động hoặc trạng thái mang tính tiếp diễn, thường đi kèm phó từ 「ずっと」 để nhấn mạnh sự kéo dài không ngắt quãng.",examples:[{sentence:"子供たちが 昼寝をしている 間、母はずっと 読書をしていました。",translation:"Trong suốt lúc lũ trẻ ngủ trưa, mẹ đã đọc sách suốt."},{sentence:"夏休みの 間、兄はずっと カフェで アルバイトをしていました。",translation:"Suốt cả kỳ nghỉ hè, anh trai tôi đã liên tục làm thêm ở quán cà phê."}],dialogue:{title:"Chuyến bay dài",lines:[{speaker:"A",text:"昨日の 飛行機の中では どう過ごしましたか。",translation:"Hôm qua ở trên máy bay bạn đã làm gì thế?"},{speaker:"B",text:"飛行機に乗っている 間、ずっと 映画を見ていましたよ。",translation:"Suốt lúc ngồi trên máy bay, tôi đã xem phim suốt đấy."},{speaker:"A",text:"そうなんですか！退屈しなくて よかったですね。",translation:"Thế à! Không bị chán là tốt rồi."}]},commonMistake:{wrong:"夏休みの間に、ずっと日本で日本語を勉強していました。",correct:"夏休みの間、ずっと日本で日本語を勉強していました。",why:"Vì hành động ở vế sau kéo dài liên tục suốt kỳ nghỉ nên phải dùng 「間」, còn 「間に」 chỉ đi với hành động mang tính thời điểm, chớp nhoáng."},note:"Cần phân biệt rõ: 「〜間」 dùng khi vế sau là hành động kéo dài liên tục suốt khoảng thời gian, còn 「〜間に」 dùng khi hành động vế sau chỉ diễn ra tại một thời điểm hoặc khoảnh khắc nào đó trong khoảng thời gian ấy."},{pattern:"間[あいだ]に vs 間[あいだ]（比較[ひかく]）",meaning:"Phân biệt 間に (điểm trong khoảng) ≠ 間 (suốt khoảng)",priority:"common",explanation:"Cả hai mẫu đều biểu thị một khoảng thời gian làm bối cảnh, nhưng khác nhau ở tính chất hành động của vế sau. Mẫu 「〜間」 diễn tả hành động hoặc trạng thái ở vế sau diễn ra liên tục, kéo dài suốt toàn bộ quá trình của vế trước. Ngược lại, 「〜間に」 diễn tả một sự việc hay hành động mang tính khoảnh khắc, tức thời xảy ra tại một thời điểm bên trong khoảng thời gian đó.",examples:[{sentence:"彼女が日本に留学している間に、一度会いに行きたい。",translation:"Trong thời gian cô ấy đi du học ở Nhật Bản, tôi muốn sang thăm một lần."},{sentence:"夏休みの間、兄はずっと実家でゆっくり休んでいた。",translation:"Trong suốt kỳ nghỉ hè, anh trai tôi đã nghỉ ngơi thư thả ở quê suốt."}],dialogue:{title:"Tranh thủ lúc chờ đợi",lines:[{speaker:"A",text:"電車を待っている間に、ちょっとコンビニで飲み物を買ってきてもいい？",translation:"Trong lúc chờ tàu, tớ ghé cửa hàng tiện lợi mua chút đồ uống được không?"},{speaker:"B",text:"いいけど、あと5分で電車が来るから急いでね。",translation:"Được chứ, nhưng 5 phút nữa tàu đến rồi nên nhanh lên nhé."},{speaker:"A",text:"わかった！走ってすぐ戻ってくるよ。",translation:"Tớ biết rồi! Tớ sẽ chạy đi và quay lại ngay."}]},commonMistake:{wrong:"雨が降っている間に、ずっと家で本を読んでいました。",correct:"雨が降っている間、ずっと家で本を読んでいました。",why:"Hành động đọc sách ở vế sau diễn ra liên tục suốt khoảng thời gian trời mưa (có 「ずっと」) nên phải dùng 「間」 chứ không dùng 「間に」."},note:"Cần phân biệt thêm với 「〜うちに」: 「〜間に/間」 chỉ đơn thuần xác định khoảng thời gian khách quan, trong khi 「〜うちに」 mang sắc thái thúc giục tranh thủ làm việc gì đó trước khi trạng thái thay đổi."},{pattern:"間[あいだ]の 接続[せつぞく]",meaning:"Cách nối vào 間に・間: Vている間 / Nの間 / い形容詞い間 / な形容詞な間",priority:"common",explanation:"Mẫu ngữ pháp này thể hiện quy tắc kết hợp từ với 「間 / 間に」để diễn tả một hành động hoặc trạng thái diễn ra trong một khoảng thời gian kéo dài. Về mặt kết nối (接続), mẫu đi liền sau động từ thể tiếp diễn 「Vている」, danh từ kèm trợ từ「の」, tính từ đuôi い giữ nguyên và tính từ đuôi な bắt buộc phải giữ lại 「な」. Đặc trưng quan trọng là động từ chỉ hành động phải luôn chia ở thể tiếp diễn 「Vている」 để thể hiện sự kéo dài của khoảng thời gian đó.",examples:[{sentence:"子供[こども]が 昼寝[ひるね]をしている 間[あいだ]に、夕飯[ゆうはん]の 準備[じゅんび]を 済[す]ませました。",translation:"Trong lúc con đang ngủ trưa, tôi đã chuẩn bị xong bữa tối."},{sentence:"留守[るす]の 間[あいだ]に 荷物[にもつ]が 届[とど]いたようです。",translation:"Hình như có bưu kiện gửi tới trong khoảng thời gian tôi vắng nhà."}],dialogue:{title:"Tranh thủ trước cuộc họp",lines:[{speaker:"A",text:"田中[たなか]さん、次[つぎ]の 会議[かいぎ]が 始[はじ]まるまでの 間[あいだ]に、この 資料[しりょう]を 確認[かくにん]してもらえますか。",translation:"Anh Tanaka, trong khoảng thời gian trước khi cuộc họp tiếp theo bắt đầu, anh kiểm tra tài liệu này giúp tôi được không?"},{speaker:"B",text:"分[わ]かりました。今[いま]は 手[て]が 空[あ]いているので、すぐ 読[よ]んでおきます。",translation:"Tôi hiểu rồi. Bây giờ tôi đang rảnh nên sẽ đọc ngay ạ."},{speaker:"A",text:"助[たす]かります。よろしくお願[ねが]いしますね。",translation:"Cảm ơn anh nhiều. Nhờ anh nhé."}]},commonMistake:{wrong:"両親[りょうしん]が 元気[げんき]の 間[あいだ]に、一緒[いっしょ]に 海外旅行[かいがいりょこう]へ 行[い]きたいです。",correct:"両親[りょうしん]が 元気[げんき]な 間[あいだ]に、一緒[いっしょ]に 海外旅行[かいがいりょこう]へ 行[い]きたいです。",why:"Khi nối với tính từ đuôi な, bắt buộc phải dùng 「な」 (元気な間に) chứ không dùng trợ từ 「の」 như danh từ."},note:"Khi kết hợp với động từ diễn tả hành động, bắt buộc phải chia về thể tiếp diễn 「Vている間（に）」thay vì dùng thể từ điển 「Vる間（に）」."}],57:[{pattern:"〜たとたん（に）",meaning:"Vừa…thì ngay lập tức (kết quả bất ngờ / ngoài ý muốn)",priority:"core",explanation:"Mẫu câu 「〜たとたん（に）」diễn tả một sự việc ở vế sau xảy ra gần như ngay tức khắc sau khi hành động ở vế trước vừa hoàn tất. Điểm đặc trưng là vế sau luôn diễn tả một sự thay đổi bất ngờ, ngoài ý muốn hoặc ngoài dự tính của người nói. Do đó, vế sau tuyệt đối không dùng các cấu trúc thể hiện ý chí, nguyện vọng hay mệnh lệnh.",examples:[{sentence:"窓を開けたとたんに、冷たい風が部屋の中に吹き込んできた。",translation:"Vừa mở cửa sổ ra thì ngay lập tức một luồng gió lạnh ùa vào trong phòng."},{sentence:"とても疲れていたので、ベッドに入ったとたんに眠ってしまった。",translation:"Vì quá mệt mỏi nên vừa nằm xuống giường là tôi đã ngủ thiếp đi ngay lập tức."}],dialogue:{title:"Máy tính mới bị tắt nguồn",lines:[{speaker:"A",text:"昨日買ったばかりのパソコン、電源ボタンを押したとたんに画面が真っ暗になっちゃったんだ。",translation:"Chiếc máy tính mới mua hôm qua, vừa bấm nút nguồn một cái là màn hình tối đen luôn."},{speaker:"B",text:"えっ、本当？初期不良かもしれないから、すぐに買った店に連絡したほうがいいよ。",translation:"Hả, thật á? Có thể là lỗi của máy từ đầu đấy, cậu nên liên hệ cửa hàng đã mua ngay đi."},{speaker:"A",text:"うん、これからレシートと保証書を持ってお店に行ってくるよ。",translation:"Ừ, lát nữa mình sẽ mang hóa đơn và phiếu bảo hành ra cửa hàng xem sao."}]},commonMistake:{wrong:"家に帰ったとたんに、手を洗いなさい。",correct:"家に帰ったら、すぐに手を洗いなさい。",why:"Vế sau của 「〜たとたん（に）」chỉ diễn tả sự việc diễn ra tự nhiên hoặc bất ngờ, không được dùng câu mang tính mệnh lệnh hay ý chí của người nói."},note:"So với 「〜たらすぐ」dùng được cho hành động có chủ ý của con người, 「〜たとたん（に）」nhấn mạnh sự ngạc nhiên trước một kết quả xảy ra ngoài dự kiến."},{pattern:"〜か〜ないかのうちに",meaning:"Chưa kịp…đã… (hai sự kiện gần như đồng thời)",priority:"common",explanation:"Mẫu câu 「〜か〜ないかのうちに」 diễn tả một sự việc, hành động vừa mới bắt đầu hoặc chưa hoàn toàn kết thúc thì một hành động khác đã lập tức xảy ra kế tiếp. Cấu trúc này dùng cùng một động từ ở dạng khẳng định và phủ định「V-る／V-た ＋ か ＋ V-ない ＋ かのうちに」, tạo cảm giác hai sự việc diễn ra gần như đồng thời. Mẫu câu mang sắc thái nhấn mạnh tính tức thì, liên tiếp và bất ngờ, vế sau có thể đi kèm cả hiện tượng tự nhiên lẫn hành động có chủ ý.",examples:[{sentence:"目覚まし時計が鳴るか鳴らないかのうちに、彼はベッドから飛び起きた。",translation:"Chuông báo thức vừa mới reo (chưa kịp dứt) thì anh ấy đã bật dậy ngay khỏi giường."},{sentence:"デパートのドアが開くか開かないかのうちに、大勢の客がバーゲン会場へ駆け込んだ。",translation:"Cửa trung tâm thương mại vừa mở ra (chưa kịp mở hết) thì đông đảo khách hàng đã ùa ngay vào khu giảm giá."}],dialogue:{title:"Cơn mưa bất chợt",lines:[{speaker:"A",text:"家を出るか出ないかのうちに、急に大雨が降ってきたよ。",translation:"Vừa mới bước chân ra khỏi nhà thì trời đã đổ mưa lớn bất ngờ rồi."},{speaker:"B",text:"ええ、大丈夫だった？傘は持っていたの？",translation:"Thế à, cậu có sao không? Có mang theo ô không đấy?"},{speaker:"A",text:"幸い折りたたみ傘を持っていたから、濡れずに済んだよ。",translation:"May mà tớ có mang theo ô gấp nên không bị ướt."}]},commonMistake:{wrong:"電車が駅に着くか着くかのうちに、ドアが開いた。",correct:"電車が駅に着くか着かないかのうちに、ドアが開いた。",why:"Mẫu câu bắt buộc phải đi cùng một động từ ở hai vế khẳng định và phủ định (V-る/V-た か V-ないかのうちに), không lặp lại hai lần thể khẳng định."},note:"Khác với 「〜たとたん」 (vế sau không dùng câu thể hiện ý chí), 「〜か〜ないかのうちに」 có thể dùng cho hành động có ý chí ở vế sau để nhấn mạnh tính khẩn trương, tức thì."}],58:[{pattern:"〜たびに",meaning:"Mỗi lần ~ là (luôn xảy ra cùng)",priority:"core",explanation:"Mẫu ngữ pháp này dùng để diễn tả ý nghĩa 'cứ mỗi lần... thì lại...', nhấn mạnh việc mỗi khi một sự kiện hoặc hành động nào đó diễn ra thì một kết quả hoặc cảm xúc nhất định cũng luôn luôn lặp lại. Cấu trúc đi kèm với động từ thể từ điển (V-ru) hoặc danh từ có trợ từ の (N の たびに). Mẫu câu này không dùng cho các hiện tượng tự nhiên mang tính tất yếu hoặc các thói quen sinh hoạt thường nhật hiển nhiên.",examples:[{sentence:"この写真を見るたびに、楽しかった高校時代を思い出します。",translation:"Mỗi lần ngắm bức ảnh này, tôi lại nhớ về thời cấp ba vui vẻ."},{sentence:"彼は失敗のたびに落ち込むのではなく、次のチャンスに向けて前向きに行動している。",translation:"Cứ mỗi lần thất bại, anh ấy không hề chán nản mà luôn hành động tích cực hướng tới cơ hội tiếp theo."}],dialogue:{title:"Thói quen mua sách",lines:[{speaker:"A",text:"本屋さんに行くたびに、つい新しい本を買っちゃうんだよね。",translation:"Cứ mỗi lần đi hiệu sách là tớ lại lỡ mua thêm sách mới mất rồi."},{speaker:"B",text:"わかる！まだ家に読んでない本がたくさんあるのに買っちゃうよね。",translation:"Hiểu luôn! Dù ở nhà còn bao nhiêu sách chưa đọc mà vẫn cứ mua nhỉ."},{speaker:"A",text:"そうなんだよ。今月はもう本屋に行かないように気をつけるよ。",translation:"Đúng thế đấy. Tháng này tớ sẽ cố gắng không ghé hiệu sách nữa."}]},commonMistake:{wrong:"母は誕生日たびに、私に手紙を書いてくれます。",correct:"母は誕生日のたびに、私に手紙を書いてくれます。",why:"Khi kết hợp với danh từ, bắt buộc phải thêm trợ từ 「の」 thành dạng 「N ＋ の ＋ たびに」 chứ không được ghép trực tiếp."},note:"Khác với 「〜ごとに」 có thể đi cùng lượng từ chỉ chu kỳ (như 2時間ごとに - mỗi 2 tiếng), 「〜たびに」 chỉ đi với sự kiện hoặc hành động cụ thể để nhấn mạnh tính lặp lại của kết quả."},{pattern:"〜まま（で）",meaning:"Để nguyên / giữ nguyên trạng thái (không thay đổi)",priority:"common",explanation:"Mẫu ngữ pháp này dùng để diễn tả một hành động được thực hiện trong khi vẫn giữ nguyên trạng thái trước đó mà không có sự thay đổi. Cấu trúc thường thể hiện một trạng thái vốn dĩ cần được xử lý/thay đổi nhưng lại được duy trì liên tục hoặc bất thường. Cách kết hợp bao gồm động từ thể た/ない, tính từ đuôi い, tính từ đuôi な (giữ な), hoặc danh từ đi kèm trợ từ 「の」 trước まま.",examples:[{sentence:"昨夜はエアコンをつけたまま寝てしまい、風邪をひいてしまった。",translation:"Tối qua tôi lỡ để nguyên điều hòa bật mà đi ngủ nên đã bị cảm."},{sentence:"このトマトは加熱せず、生のままで食べたほうがおいしいです。",translation:"Quả cà chua này không cần nấu, ăn sống nguyên như vậy sẽ ngon hơn."}],dialogue:{title:"Nhắc nhở khi vào nhà",lines:[{speaker:"A",text:"ちょっと、靴を履いたまま部屋に入らないでよ！",translation:"Này, đừng có để nguyên cả giày mà bước vào phòng chứ!"},{speaker:"B",text:"あ、ごめん！うっかり脱ぐのを忘れてたよ。",translation:"A, xin lỗi! Tôi đãng trí nên quên khuấy việc cởi ra."},{speaker:"A",text:"次からは玄関でちゃんと脱いでね。",translation:"Từ lần sau nhớ cởi ở sảnh ra vào đàng hoàng nhé."}]},commonMistake:{wrong:"窓を開けてまま出かけてしまいました。",correct:"窓を開けたまま出かけてしまいました。",why:"Khi kết hợp với động từ để diễn tả hành động trong trạng thái đang giữ nguyên, phải chia về thể quá khứ 「V-たまま」 chứ không dùng thể 「V-てまま」."},note:"Khác với 「〜っぱなし」 chỉ đi với động từ và thường mang sắc thái tiêu cực, phê phán do sự bỏ mặc/bất cẩn, 「〜まま」 có tính trung tính hơn và dùng được cho cả tính từ lẫn danh từ."},{pattern:"〜たまま",meaning:"Giữ nguyên trạng thái sau khi hành động đã xảy ra",priority:"common",explanation:"Mẫu ngữ pháp 「〜たまま」 diễn tả việc thực hiện một hành động khác trong khi vẫn giữ nguyên trạng thái do hành động trước đó tạo ra mà không có sự thay đổi. Mẫu này thường được sử dụng khi hành động tiếp theo diễn ra trong một trạng thái bất thường, trái với thói quen thông thường hoặc lẽ ra phải thay đổi trạng thái đó. Cấu trúc đi kèm với động từ thể quá khứ (Vた + まま) để nhấn mạnh kết quả của hành động đã hoàn thành vẫn đang tiếp tục được duy trì.",examples:[{sentence:"昨晩はテレビをつけたまま寝てしまった。",translation:"Tối qua tôi lỡ ngủ quên trong khi vẫn để nguyên tivi bật."},{sentence:"靴を履いたまま部屋に入ってはいけません。",translation:"Không được để nguyên giày mà đi vào trong phòng."}],dialogue:{title:"Tìm kính mắt",lines:[{speaker:"A",text:"あれ？私のメガネ、どこにあるか見なかった？",translation:"Ủa? Cậu có thấy kính của tớ ở đâu không?"},{speaker:"B",text:"えっ、メガネなら頭の上にかけたままだよ。",translation:"Hả, kính thì cậu vẫn đang để nguyên trên đầu kìa."},{speaker:"A",text:"本当だ！探していたのに全然気づかなかったよ。",translation:"Thật này! Đang tìm mải miết mà không nhận ra chút nào luôn."}]},commonMistake:{wrong:"メガネをかけながら寝てしまった。",correct:"メガネをかけたまま寝てしまった。",why:"「〜ながら」dùng khi hai hành động diễn ra song song cùng lúc, còn khi muốn nói giữ nguyên trạng thái sau khi đã làm việc gì (kết quả sau khi đã đeo kính) để làm hành động khác thì phải dùng「〜たまま」."},note:"Khác với「〜っぱなし」thường mang sắc thái phê phán hay chê trách việc buông xuôi bỏ mặc,「〜たまま」chỉ đơn thuần miêu tả trạng thái được duy trì mà không nhất thiết mang hàm ý tiêu cực."},{pattern:"たびに ≠ まま ≠ ながら",meaning:"Phân biệt: たびに (lặp), まま (trạng thái bất biến), ながら (đồng thời)",priority:"common",explanation:"「〜たびに」dùng để diễn tả sự việc lặp lại mang tính quy luật, hễ mỗi lần A xảy ra thì B lại diễn ra theo. Trong khi đó,「〜まま」nhấn mạnh việc giữ nguyên một trạng thái vốn có để tiếp tục thực hiện hành động khác (để nguyên A mà làm B). Còn「〜ながら」dùng khi một chủ thể thực hiện song song hai hành động có chủ ý cùng một lúc (vừa làm A vừa làm B).",examples:[{sentence:"この写真を見るたびに、楽しかった学生時代を思い出します。",translation:"Mỗi lần nhìn bức ảnh này, tôi lại nhớ về thời học sinh vui vẻ."},{sentence:"窓を開けたまま出かけてしまい、部屋に雨が入ってしまいました。",translation:"Tôi lỡ để nguyên cửa sổ mở mà ra ngoài nên nước mưa đã hắt vào phòng."}],dialogue:{title:"Thói quen sinh hoạt",lines:[{speaker:"A",text:"山田さん、テレビをつけたまま寝てはいけませんよ。",translation:"Anh Yamada, không được để nguyên tivi bật mà đi ngủ đâu đấy."},{speaker:"B",text:"すみません。疲れていると、横になるたびにすぐ眠ってしまうんです。",translation:"Xin lỗi nhé. Cứ mệt là mỗi lần nằm xuống tôi lại ngủ thiếp đi mất."},{speaker:"A",text:"体に悪いですから、ちゃんと消してからベッドに入ってくださいね。",translation:"Không tốt cho sức khỏe đâu, anh hãy tắt cẩn thận rồi hẵng vào giường nhé."}]},commonMistake:{wrong:"くつをはきながら部屋に入ってはいけません。",correct:"くつをはいたまま部屋に入ってはいけません。",why:"Khi muốn diễn tả việc 'để nguyên trạng thái đang mang giày trên chân mà vào nhà' phải dùng 「〜たまま」, còn「ながら」chỉ hành động đang diễn ra đồng thời (vừa xỏ giày vừa bước vào) nên câu bị sai nghĩa."},note:"「〜たびに」không dùng cho những sự việc diễn ra hiển nhiên hằng ngày (như 'mỗi sáng thức dậy'), còn「〜ながら」bắt buộc hai vế phải cùng một chủ ngữ với trọng tâm rơi vào hành động ở vế sau."}],59:[{pattern:"〜おかげで",meaning:"Nhờ có ~ mà (kết quả tốt, biết ơn)",priority:"core",explanation:"Mẫu câu「〜おかげで」được dùng để diễn tả nguyên nhân, lý do dẫn đến một kết quả tốt đẹp, tích cực ngoài mong đợi. Mẫu này thể hiện sâu sắc thái độ biết ơn đối với sự giúp đỡ của người khác hoặc cảm giác may mắn vì một yếu tố khách quan thuận lợi. Vế sau của「〜おかげで」luôn là một kết quả mang lại lợi ích hoặc niềm vui, không dùng cho sự việc tiêu cực thông thường.",examples:[{sentence:"先生が丁寧に教えてくださったおかげで、無事にJLPT N3に合格できました。",translation:"Nhờ thầy cô tận tình chỉ bảo mà em đã đỗ kỳ thi JLPT N3 một cách thuận lợi."},{sentence:"薬を飲んでしっかり休んだおかげで、風邪がすっかり治りました。",translation:"Nhờ uống thuốc và nghỉ ngơi đầy đủ mà tôi đã khỏi hẳn cảm cúm."}],dialogue:{title:"Chuẩn bị bài thuyết trình",lines:[{speaker:"A",text:"先輩が手伝ってくれたおかげで、無事にプレゼンの資料が完成しました！",translation:"Nhờ có tiền bối giúp đỡ mà em đã hoàn thành tài liệu thuyết trình suôn sẻ rồi ạ!"},{speaker:"B",text:"よかったね。本番もその調子で落ち着いて頑張ってね。",translation:"Tốt quá rồi. Lúc thuyết trình thật cũng cứ giữ phong độ và bình tĩnh cố gắng nhé."},{speaker:"A",text:"はい、いい発表ができるように全力を尽くします！",translation:"Vâng, em sẽ dốc hết sức để có một bài thuyết trình thật tốt ạ!"}]},commonMistake:{wrong:"大雨のおかげで、電車が遅れて会社に遅刻してしまいました。",correct:"大雨のせいで、電車が遅れて会社に遅刻してしまいました。",why:"「〜おかげで」chỉ dùng khi dẫn đến kết quả tích cực, tốt đẹp; nếu nguyên nhân mang lại kết quả xấu hoặc gây phiền phức thì phải dùng「〜せいで」."},note:"Đôi khi「〜おかげで」được dùng với giọng điệu mỉa mai, châm biếm để trách móc một kết quả xấu (ví dụ: 'Nhờ ơn anh mà hỏng hết việc'), nhưng khi làm bài thi N3 bạn cần nhớ bản chất chuẩn của mẫu này luôn là biết ơn và kết quả tốt."},{pattern:"〜せいで",meaning:"Tại ~ mà / Do lỗi ~ (kết quả xấu, trách cứ)",priority:"common",explanation:"Mẫu 「〜せいで」 dùng để chỉ nguyên nhân, lý do dẫn đến một kết quả tiêu cực, không mong muốn hoặc thất bại. Mẫu câu này thể hiện rõ thái độ trách móc, đổ lỗi cho người khác, hoàn cảnh bên ngoài hoặc tự trách bản thân. Về kết nối, đi với thể thông thường (V普通形／Aい + せいで, Aな + なせいで, N + のせいで). Khi muốn nhấn mạnh kết luận quy trách nhiệm ở cuối câu, có thể dùng dạng 「〜のは〜せいだ」.",examples:[{sentence:"昨夜遅くまでスマホをいじっていたせいで、今朝は寝坊してしまった。",translation:"Tại tối qua mải nghịch điện thoại đến khuya mà sáng nay tôi đã ngủ quên mất."},{sentence:"連日の大雨のせいで、楽しみにしていたサッカーの試合が中止になった。",translation:"Do mưa lớn nhiều ngày liền mà trận đấu bóng đá tôi hằng mong đợi đã bị hủy bỏ."}],dialogue:{title:"Kết quả bài kiểm tra",lines:[{speaker:"A",text:"テストの結果はどうだった？あまり浮かない顔をしているね。",translation:"Kết quả bài thi thế nào rồi? Trông sắc mặt cậu có vẻ không vui nhỉ."},{speaker:"B",text:"全然ダメだったよ。隣の人の咳がうるさかったせいで、全然集中できなかったんだ。",translation:"Chán lắm cậu à. Tại tiếng ho của người ngồi cạnh ồn ào quá mà tớ chẳng thể nào tập trung được."},{speaker:"A",text:"それは災難だったね。でも次はきっと大丈夫だよ。",translation:"Thế thì xui xẻo thật đấy. Nhưng lần sau chắc chắn sẽ ổn thôi."}]},commonMistake:{wrong:"先生が熱心に教えてくれたせいで、JLPT N3に合格できました。",correct:"先生が熱心に教えてくれたおかげで、JLPT N3に合格できました。",why:"「〜せいで」 chỉ dùng khi dẫn đến kết quả xấu mang tính trách móc, còn khi kết quả tốt đẹp và muốn bày tỏ lòng biết ơn thì phải dùng 「〜おかげで」."},note:'Trường hợp không chắc chắn 100% nguyên nhân có phải do yếu tố đó hay không, người Nhật thường dùng biến thể 「〜せいか」 với nghĩa "không biết có phải do... hay không mà".'},{pattern:"〜ために (nguyên nhân[げんいん])",meaning:"Vì ~, do ~ (nguyên nhân trung tính, trang trọng)",priority:"common",explanation:"Mẫu ngữ pháp「〜ために」dùng để biểu thị nguyên nhân, lý do dẫn đến một kết quả khách quan (có thể là kết quả tốt hoặc xấu). Khác với các mẫu mang sắc thái đổ lỗi hay cảm xúc cá nhân, mẫu này hoàn toàn trung tính, mang tính trang trọng và thường dùng trong văn viết, báo cáo hoặc thông báo chính thức. Đặc biệt, vế sau của câu chỉ diễn tả sự việc xảy ra tự nhiên, tuyệt đối không dùng các mẫu câu biểu thị ý chí, mệnh lệnh, rủ rê hay nhờ vả.",examples:[{sentence:"システムに障害が発生したために、本日のサービスを一時停止いたします。",translation:"Do phát sinh sự cố hệ thống nên chúng tôi xin tạm dừng dịch vụ ngày hôm nay."},{sentence:"連日の猛暑のために、熱中症で病院に運ばれる人が急増しています。",translation:"Do nắng nóng gay gắt kéo dài nhiều ngày, số người phải nhập viện vì sốc nhiệt đang tăng nhanh chóng."}],dialogue:{title:"Hoãn cuộc họp",lines:[{speaker:"A",text:"田中さん、先ほどの人事部との会議はどうなりましたか。",translation:"Anh Tanaka, cuộc họp với phòng nhân sự lúc nãy thế nào rồi?"},{speaker:"B",text:"担当者が急病のために、来週の水曜日に延期となりました。",translation:"Do người phụ trách bị ốm đột xuất nên cuộc họp đã được hoãn sang thứ Tư tuần sau rồi ạ."},{speaker:"A",text:"そうですか。では、今のうちに資料を再確認しておきましょう。",translation:"Vậy à. Vậy trong lúc này chúng ta hãy rà soát lại tài liệu nhé."}]},commonMistake:{wrong:"雨が強くなったために、傘を持って行ってください。",correct:"雨が強くなったので、傘を持って行ってください。",why:"Vế sau của「〜ために」chỉ nguyên nhân không được đi với câu cầu khiến, mệnh lệnh hay nhờ vả (〜てください); trường hợp này phải dùng「〜ので / 〜から」."},note:"Cần phân biệt với「〜ために」chỉ mục đích (để làm gì): khi chỉ mục đích vế trước đi với động từ có ý chí, còn khi chỉ nguyên nhân thì diễn tả lý do dẫn đến kết quả diễn ra tự nhiên."}],60:[{pattern:"〜ように（目的[もくてき]：非意志[ひいし]・可能[かのう]・否定[ひてい]）",meaning:"ように mục đích — dùng với động từ KHÔNG ý chí hoặc khả năng/phủ định",priority:"core",explanation:'Mẫu 「〜ように」 dùng để biểu thị mục đích hướng tới một trạng thái mong muốn, có nghĩa là "để / để có thể / để không...". Vế trước 「ように」 bắt buộc đi với động từ thể khả năng, động từ phi ý chí hoặc động từ ở thể phủ định (〜ない). Mẫu câu này diễn tả việc người nói thực hiện hành động nhằm tạo điều kiện cho một kết quả khách quan diễn ra hoặc phòng tránh sự cố. Không dùng mẫu này trực tiếp với động từ thể từ điển mang tính ý chí có chủ đích của cùng một chủ ngữ.',examples:[{sentence:"後ろの席の人にもよく聞こえるように、マイクを使って話してください。",translation:"Xin hãy dùng micro để nói cho những người ở hàng ghế sau cũng có thể nghe rõ."},{sentence:"試験当日に遅刻しないように、いつもより30分早く家を出た。",translation:"Để không bị muộn vào ngày thi, tôi đã rời nhà sớm hơn thường ngày 30 phút."}],dialogue:{title:"Chuẩn bị bài thuyết trình",lines:[{speaker:"A",text:"来週のプレゼンのスライド、文字が小さすぎないかな？",translation:"Slide thuyết trình tuần tới chữ có bị nhỏ quá không nhỉ?"},{speaker:"B",text:"そうだね。後ろの人にも見えるように、フォントをもう少し大きくしたほうがいいよ。",translation:"Đúng rồi đấy. Cậu nên tăng cỡ chữ lên một chút để người ngồi phía sau cũng nhìn thấy được."},{speaker:"A",text:"アドバイスありがとう。早速修正しておくね。",translation:"Cảm ơn lời khuyên của cậu. Tớ sẽ sửa lại ngay đây."}]},commonMistake:{wrong:"新しい車を買うように、毎月お金を貯めています。",correct:"新しい車が買えるように、毎月お金を貯めています。",why:"Mẫu 「〜ように」 không kết hợp trực tiếp với động từ ý chí (買う) mà phải chuyển sang thể khả năng (買える) hoặc dùng 「〜ために」."},note:"Khác với 「〜ために」 (yêu cầu hai vế cùng chủ ngữ và mang ý chí mạnh mẽ), 「〜ように」 tập trung vào việc tạo ra điều kiện hoặc trạng thái và có thể dùng khi hai vế khác chủ ngữ."},{pattern:"〜ために（目的[もくてき]：意志[いし]動詞[どうし]）",meaning:"ために mục đích — dùng với động từ Ý CHÍ, thường cùng chủ thể",priority:"common",explanation:'Mẫu câu「〜ために」được dùng để biểu thị mục đích trực tiếp, rõ ràng của hành động, có nghĩa là "để / nhằm mục đích...". Trước「ために」bắt buộc là động từ thể từ điển mang tính ý chí (hành động người nói chủ động thực hiện hoặc kiểm soát được), đồng thời chủ ngữ của hai vế câu phải cùng là một đối tượng. Vế sau diễn tả hành động có chủ đích, nỗ lực hoặc chuẩn bị cụ thể nhằm hiện thực hóa mục đích ở vế trước.',examples:[{sentence:"新車を買うために、毎月５万円ずつ貯金しています。",translation:"Để mua một chiếc xe mới, mỗi tháng tôi đều tiết kiệm 5 vạn yên."},{sentence:"将来自分の店を開くために、有名なレストランで修行を積んでいる。",translation:"Để sau này mở quán của riêng mình, tôi đang tích lũy kinh nghiệm tu nghiệp tại một nhà hàng nổi tiếng."}],dialogue:{title:"Kế hoạch tương lai",lines:[{speaker:"A",text:"来年日本へ留学するために、今日本語学校に通っているんだ。",translation:"Để sang năm đi du học Nhật Bản, bây giờ tớ đang theo học tại trường tiếng Nhật đấy."},{speaker:"B",text:"そうなんだ！毎日アルバイトもして大変そうだけど、頑張ってね。",translation:"Vậy à! Thấy cậu vừa đi làm thêm mỗi ngày có vẻ vất vả, nhưng cố lên nhé."},{speaker:"A",text:"うん、自分の力で学費を払うためにも、諦めずに頑張るよ。",translation:"Ừ, cũng để tự mình chi trả học phí nên tớ sẽ không bỏ cuộc mà cố gắng hết sức."}]},commonMistake:{wrong:"車が買えるために、毎日一生懸命働いています。",correct:"車を買うために、毎日一生懸命働いています。",why:"「ために」chỉ kết hợp với động từ mang tính ý chí (như 買う), không đi cùng động từ thể khả năng (như 買える) hay động từ phi ý chí."},note:"Nếu vế mục đích là động từ thể khả năng, thể phủ định (V-ない) hoặc động từ vô ý chí, ta phải chuyển sang dùng mẫu「〜ように」thay vì「〜ために」."},{pattern:"ように ≠ ために の 使[つか]い分[わ]け",meaning:"Phân biệt: ように (phi ý chí / khả năng / phủ định) ≠ ために (ý chí rõ ràng)",priority:"common",explanation:"「〜ために」dùng khi vế trước là động từ mang tính ý chí rõ ràng, biểu thị mục đích mà người nói chủ động thực hiện hành động để đạt được (hai vế thường cùng chủ ngữ). Ngược lại, 「〜ように」đi với động từ khả năng, tự động từ hoặc thể phủ định (ない形) để biểu thị mục tiêu hướng tới sự thay đổi trạng thái hoặc kết quả mong muốn. Nói cách khác, 「ために」nhấn mạnh vào hành vi có chủ đích, còn 「ように」nhấn mạnh vào trạng thái hoặc khả năng được hình thành.",examples:[{sentence:"後ろの席の人にもよく聞こえるように、マイクを使って話しました。",translation:"Tôi đã dùng micro để nói sao cho người ngồi ở hàng ghế phía sau cũng có thể nghe rõ."},{sentence:"将来自分の店を持つために、毎月少しずつ貯金をしています。",translation:"Để tương lai mở được quán riêng của mình, mỗi tháng tôi đều tiết kiệm một ít tiền."}],dialogue:{title:"Luyện tập thuyết trình",lines:[{speaker:"A",text:"明日のプレゼン、緊張するね。準備は大丈夫？",translation:"Bài thuyết trình ngày mai hồi hộp thật đấy. Cậu chuẩn bị ổn chưa?"},{speaker:"B",text:"本番で落ち着いて話せるように、何度も録音して練習したよ。",translation:"Để có thể nói bình tĩnh khi vào buổi thuyết trình thật, tớ đã ghi âm và luyện tập nhiều lần rồi."},{speaker:"A",text:"すごい！良い発表をするために、私も今夜もう一度復習しておくね。",translation:"Tuyệt quá! Để có một bài phát biểu tốt, tối nay tớ cũng sẽ ôn lại lần nữa."}]},commonMistake:{wrong:"N2に合格できるために、毎日一生懸命勉強しています。",correct:"N2に合格できるように、毎日一生懸命勉強しています。",why:"Động từ thể khả năng (合格できる) là động từ phi ý chí biểu thị trạng thái nên bắt buộc phải kết hợp với ように chứ không đi với ために."},note:'Khi diễn đạt mục đích mang nghĩa phủ định "để không..." (V-ない), ta hầu như luôn dùng「〜ないように」thay vì「〜ないために」.'},{pattern:"〜ようにする・〜ようになる",meaning:"ようにする = cố gắng để đạt trạng thái; ようになる = dần dần trở thành",priority:"common",explanation:"「〜ようにする」dùng để diễn tả sự nỗ lực, cố gắng có ý chí nhằm thực hiện một hành động hoặc duy trì một thói quen tốt đều đặn. Ngược lại, 「〜ようになる」biểu thị sự biến đổi dần dần về mặt trạng thái, thói quen hoặc năng lực theo thời gian (từ chưa thể thành có thể) một cách tự nhiên. Về cách kết hợp, 「〜ようにする」thường đi với động từ thể từ điển hoặc thể ない biểu thị hành động có ý chí, trong khi 「〜ようになる」thường đi cùng động từ thể khả năng hoặc động từ không mang ý chí.",examples:[{sentence:"健康のために、野菜を多く食べて、塩分を控えるようにする。",translation:"Để giữ gìn sức khỏe, tôi cố gắng ăn nhiều rau và hạn chế lượng muối."},{sentence:"日本語学校で熱心に勉強を続ければ、誰でも半年ほどで日常会話ができるようになる。",translation:"Nếu chăm chỉ học tập tại trường tiếng Nhật, ai cũng sẽ dần nói được hội thoại hàng ngày sau khoảng nửa năm."}],dialogue:{title:"Luyện tập tiếng Nhật",lines:[{speaker:"A",text:"毎日シャドーイングを続ければ、本当に日本語が上手に話せるようになる？",translation:"Nếu ngày nào cũng luyện shadowing thì thực sự sẽ dần nói giỏi tiếng Nhật được chứ?"},{speaker:"B",text:"うん、僕も毎日欠かさず15分は声を出して練習するようにしているよ。",translation:"Ừ, tôi cũng đang cố gắng duy trì luyện phát âm ít nhất 15 phút mỗi ngày không nghỉ đấy."},{speaker:"A",text:"分かった、私も今日から発音を意識して練習するようにするね。",translation:"Tôi hiểu rồi, từ hôm nay tôi cũng sẽ cố gắng chú ý phát âm để luyện tập."}]},commonMistake:{wrong:"毎日練習したので、ピアノが上手に弾くようになりました。",correct:"毎日練習したので、ピアノが上手に弾けるようになりました。",why:"Khi diễn tả sự thay đổi về mặt năng lực (từ không thể sang có thể) với 「〜ようになる」, động từ phải chia ở thể khả năng (弾ける) thay vì thể từ điển thông thường."},note:"Phân biệt 「〜ようにする」(nỗ lực duy trì thói quen qua quá trình) với 「〜ことにする」(đưa ra quyết định dứt khoát thực hiện một hành động tại thời điểm nói)."}],61:[{pattern:"〜と（必然[ひつぜん]・自然[しぜん]）",meaning:"〜と: điều kiện tất yếu / tự nhiên — hệ quả tự động xảy ra, KHÔNG dùng mệnh lệnh/ý chí sau",priority:"core",explanation:"Mẫu ngữ pháp 「〜と」 dùng để diễn tả một điều kiện mà khi sự việc ở vế trước xảy ra thì vế sau sẽ tất yếu, tự nhiên hoặc tự động xảy ra theo quy luật. Cấu trúc này thường xuất hiện khi mô tả hiện tượng tự nhiên, thói quen bất di bất dịch, chỉ dẫn đường sá hoặc thao tác vận hành máy móc. Cần đặc biệt lưu ý rằng vế sau của 「〜と」 mang tính khách quan, tuyệt đối không đi kèm với ý chí, nguyện vọng, rủ rê hay mệnh lệnh của người nói.",examples:[{sentence:"この赤いボタンを押すと、機械が動きます。",translation:"Hễ nhấn chiếc nút màu đỏ này thì máy móc sẽ tự động hoạt động."},{sentence:"お酒をたくさん飲むと、すぐに顔が赤くなります。",translation:"Hễ uống nhiều rượu là mặt tôi lại đỏ bừng ngay lập tức."}],dialogue:{title:"Cách dùng máy pha cà phê",lines:[{speaker:"A",text:"すみません、このコーヒーメーカーの使い方を教えていただけますか。",translation:"Xin lỗi, anh có thể chỉ cho tôi cách dùng máy pha cà phê này được không?"},{speaker:"B",text:"ここに豆を入れてこのボタンを押すと、自動でおいしいコーヒーが入りますよ。",translation:"Vâng, hễ cho hạt vào đây rồi nhấn nút này là cà phê thơm ngon sẽ tự động được pha đấy."},{speaker:"A",text:"なるほど、とても簡単ですね。ありがとうございます！",translation:"Ra là vậy, thật đơn giản nhỉ. Cảm ơn anh!"}]},commonMistake:{wrong:"駅に着くと、電話してください。",correct:"駅に着いたら、電話してください。",why:"Vế sau của 「〜と」 tuyệt đối không đi cùng câu cầu khiến, nhờ vả hay mệnh lệnh (như 〜てください), trong ngữ cảnh này bắt buộc phải dùng 「〜たら」."},note:"Khác với 「〜たら」 dùng linh hoạt cho cả ý chí và lời mời, 「〜と」 chỉ giới hạn ở kết quả phát sinh tự nhiên mang tính tất yếu và khách quan."},{pattern:"〜ば（仮定[かてい]条件[じょうけん]）",meaning:"〜ば: điều kiện giả định chung — câu sau KHÔNG phải quá khứ cụ thể; không dùng tả trạng thái quá khứ",priority:"common",explanation:'Mẫu ngữ pháp「〜ば」dùng để biểu thị điều kiện giả định, mang nghĩa là "nếu... thì...". Mẫu này thường dùng khi nêu lên điều kiện cần thiết để một sự việc xảy ra, hoặc đưa ra các quy luật chung, giả định cho tương lai. Điểm lưu ý quan trọng là vế sau của「〜ば」không được dùng ở thì quá khứ để diễn tả một hành động, sự việc hay trạng thái cụ thể đã diễn ra trong thực tế.',examples:[{sentence:"安[やす]ければ、この 新[あたら]しい パソコンを 買[か]いたいです。",translation:"Nếu giá rẻ thì tôi muốn mua chiếc máy tính mới này."},{sentence:"明日[あした] 天気[てんき]が よければ、一緒[いっしょ]に 山登[やまのぼ]りに 行[い]きませんか。",translation:"Nếu ngày mai thời tiết đẹp, bạn có muốn đi leo núi cùng tôi không?"}],dialogue:{title:"Nhờ giúp đỡ công việc",lines:[{speaker:"A",text:"すみません、この 資料[しりょう]の 作成[さくせい]を 手伝[てつだ]ってもらえませんか。",translation:"Xin lỗi, bạn có thể giúp tôi làm tài liệu này được không?"},{speaker:"B",text:"いいですよ。私[わたし]で よければ、喜[よろこ]んで 手伝[てつだ]います。",translation:"Được chứ. Nếu tôi giúp được thì tôi rất sẵn lòng."},{speaker:"A",text:"助[たす]かります！今日中[きょうじゅう]に 終[お]われば 幸[さいわ]いです。",translation:"May quá! Nếu hoàn thành trong hôm nay thì tốt biết mấy."}]},commonMistake:{wrong:"昨日[きのう] 薬[くすり]を 飲[の]めば、熱[ねつ]が 下[さ]がりました。",correct:"昨日[きのう] 薬[くすり]を 飲[の]んだら、熱[ねつ]が 下[さ]がりました。",why:"Vế sau của「〜ば」không thể dùng ở thì quá khứ để tường thuật một kết quả hay sự việc đã thực tế xảy ra; trường hợp này phải dùng「〜たら」."},note:"Khác với「〜たら」,「〜ば」chỉ tập trung vào điều kiện giả định thuần túy, tuyệt đối không dùng cho sự việc đã phát sinh hay chuỗi hành động kế tiếp trong quá khứ."},{pattern:"〜たら（汎用[はんよう]条件[じょうけん]）",meaning:"〜たら: điều kiện linh hoạt nhất — dùng được với mệnh lệnh, ý chí, quá khứ, mọi loại vị ngữ",priority:"common",explanation:'Mẫu ngữ pháp 「〜たら」 biểu thị điều kiện giả định ("nếu...") hoặc điều kiện tất yếu/trình tự thời gian ("sau khi... thì..."). Đây là dạng câu điều kiện linh hoạt và đa năng nhất trong tiếng Nhật vì vế sau có thể thoải mái kết hợp với câu mệnh lệnh, nhờ vả, rủ rê hay ý chí của người nói. Mẫu này có tính khẩu ngữ cao và được sử dụng rất phổ biến trong giao tiếp hàng ngày.',examples:[{sentence:"分からないことがあったら、遠慮なく質問してください。",translation:"Nếu có điều gì không hiểu, bạn hãy thoải mái đặt câu hỏi nhé."},{sentence:"明日雨が降ったら、ハイキングはやめて映画を見に行きましょう。",translation:"Ngày mai nếu trời mưa thì chúng ta hãy hủy đi bộ dã ngoại và cùng đi xem phim nhé."}],dialogue:{title:"Kế hoạch đi ăn",lines:[{speaker:"A",text:"今日の会議が早く終わったら、一緒にご飯を食べに行かない？",translation:"Nếu cuộc họp hôm nay kết thúc sớm thì cùng đi ăn cơm không?"},{speaker:"B",text:"いいね！駅前の新しいイタリアンレストランに行ってみたい。",translation:"Hay đấy! Mình đang muốn thử đến nhà hàng Ý mới mở trước nhà ga."},{speaker:"A",text:"じゃあ、予約が取れたら、またメッセージを送るね。",translation:"Vậy đặt được bàn xong mình sẽ nhắn tin lại cho bạn nhé."}]},commonMistake:{wrong:"時間があると、手伝ってください。",correct:"時間があったら、手伝ってください。",why:"Vế sau của「〜と」không được đi cùng với câu nhờ vả, mệnh lệnh (〜てください) hay ý chí, vì vậy trong trường hợp này bắt buộc phải dùng「〜たら」."},note:"So với「〜と」hay「〜ば」, vế sau của「〜たら」hoàn toàn không bị giới hạn bởi ý chí, nhờ vả hay mệnh lệnh, đồng thời cũng mang sắc thái giao tiếp tự nhiên và linh hoạt nhất."},{pattern:"〜なら（前提[ぜんてい]条件[じょうけん]）",meaning:"〜なら: giả định dựa trên thông tin vừa nghe / tình huống đang đề cập — câu sau thường mang ý khuyên/đề xuất",priority:"common",explanation:'「〜なら」được dùng để đưa ra lời khuyên, đề xuất, yêu cầu hoặc phán đoán dựa trên thông tin mà đối phương vừa nhắc tới hoặc một tình huống đang diễn ra trước mắt. Cấu trúc này mang sắc thái "nếu đã định làm việc đó / nếu đúng là trường hợp như thế thì...". Vế sau của câu thường đi với các mẫu biểu thị ý chí, lời khuyên (〜ほうがいい, 〜てください, 〜はいかがですか), và hành động ở vế sau hoàn toàn có thể xảy ra trước hành động ở vế trước.',examples:[{sentence:"新しいパソコンを買うなら、秋葉原の専門店に行ってみてください。",translation:"Nếu bạn định mua máy tính mới thì hãy thử ghé các cửa hàng chuyên dụng ở Akihabara nhé."},{sentence:"頭が痛いなら、無理をしないで今日は早く休んだほうがいいですよ。",translation:"Nếu cậu đang bị đau đầu thì đừng cố quá, hôm nay nên nghỉ ngơi sớm đi."}],dialogue:{title:"Gợi ý khi đi du lịch",lines:[{speaker:"A",text:"来週、初めて京都へ旅行に行くんですよ。",translation:"Tuần sau tớ lần đầu tiên đi du lịch Kyoto đấy."},{speaker:"B",text:"京都に行くなら、金閣寺と伏見稲荷大社は絶対に行ったほうがいいよ！",translation:"Đã đi Kyoto thì cậu nhất định nên ghé chùa Kinkaku-ji và đền Fushimi Inari nhé!"},{speaker:"A",text:"分かりました。写真もたくさん撮ってきますね。",translation:"Tớ hiểu rồi. Tớ sẽ chụp thật nhiều ảnh mang về."}]},commonMistake:{wrong:"海外旅行に行く外国へ行ったら、事前にパスポートを作ってください。",correct:"海外旅行に行くなら、事前にパスポートを作っておいてください。",why:"「〜たら」bắt buộc hành động ở vế trước phải xảy ra xong rồi mới đến vế sau (đi nước ngoài rồi mới làm hộ chiếu là sai thực tế), còn「〜なら」dùng được cho hành động chuẩn bị diễn ra trước khi đi."},note:"Khác với「〜たら」hay「〜と」,「〜なら」cho phép hành động ở vế sau diễn ra TRƯỚC hành động ở vế trước (thường dùng để khuyên chuẩn bị trước)."}],62:[{pattern:"〜ても",meaning:'Giả định nhượng bộ — "dù … vẫn"',priority:"core",explanation:'Mẫu câu 「〜ても」 dùng để biểu thị sự nhượng bộ, diễn tả ý nghĩa "dù... thì vẫn...". Vế trước đưa ra một điều kiện (giả định hoặc có thật), nhưng vế sau vẫn dẫn đến một kết quả hoặc hành vi không bị ảnh hưởng, trái với suy đoán thông thường. Mẫu này thường kết hợp với các phó từ như 「たとえ」「どんなに」「いくら」 để nhấn mạnh mức độ của điều kiện nhượng bộ.',examples:[{sentence:"たとえ失敗しても、諦めずに最後までやり遂げます。",translation:"Cho dù có thất bại đi chăng nữa, tôi vẫn sẽ không bỏ cuộc mà làm tới cùng."},{sentence:"いくら安くても、必要のない物は買わないほうがいいですよ。",translation:"Dù có rẻ đến mức nào đi nữa thì những thứ không cần thiết cũng không nên mua đâu."}],dialogue:{title:"Kế hoạch đi leo núi",lines:[{speaker:"A",text:"明日のハイキング、雨が降っても行くつもりですか。",translation:"Chuyến đi bộ leo núi ngày mai, dù trời có mưa bạn vẫn định đi à?"},{speaker:"B",text:"はい、小雨くらいなら予定通り出発するつもりです。",translation:"Vâng, nếu chỉ là mưa nhỏ thì tôi vẫn định xuất phát theo đúng kế hoạch."},{speaker:"A",text:"そうですか。でも足元が滑りやすいので気をつけてくださいね。",translation:"Vậy à. Nhưng đường trơn dễ trượt ngã nên bạn nhớ cẩn thận nhé."}]},commonMistake:{wrong:"どんなに忙しいのに、毎日日本語を勉強するつもりです。",correct:"どんなに忙しくても、毎日日本語を勉強するつもりです。",why:"Khi vế sau thể hiện ý chí, nguyện vọng của người nói hoặc đi kèm với phó từ nhấn mạnh mức độ 「どんなに」 thì không được dùng 「〜のに」 mà phải dùng dạng nhượng bộ 「〜ても」."},note:"Phân biệt với 「〜のに」: 「〜ても」 dùng được cho cả giả định tương lai và vế sau đi được với ý chí/mệnh lệnh, trong khi 「〜のに」 chỉ dùng cho sự việc thực tế mang cảm xúc bất mãn, tiếc nuối và vế sau không đi với câu mệnh lệnh hay ý chí."},{pattern:"〜のに",meaning:"Thực tế trái kỳ vọng — tiếc/trách (thực tế đã xảy ra)",priority:"common",explanation:"Mẫu câu「〜のに」dùng để diễn tả sự việc ở vế sau diễn ra trái ngược hoàn toàn với dự đoán, kỳ vọng dựa trên vế trước. Mẫu này thể hiện rõ cảm xúc bất ngờ, tiếc nuối, bất mãn hoặc trách móc của người nói trước một thực tế không như mong muốn. Ngữ cảnh sử dụng thường là khi người nói đối diện với một sự thật khách quan ngoài ý muốn đã hoặc đang xảy ra.",examples:[{sentence:"約束の時間は3時だったのに、彼は4時になっても来なかった。",translation:"Rõ ràng đã hẹn lúc 3 giờ thế mà đến tận 4 giờ anh ấy vẫn chưa đến."},{sentence:"一生懸命に料理を作ったのに、家族はあまり食べてくれなかった。",translation:"Tôi đã cật lực nấu nướng vậy mà cả nhà lại chẳng ăn mấy."}],dialogue:{title:"Mua sắm qua mạng",lines:[{speaker:"A",text:"昨日届いたこの服、高かったのに、サイズが全然合わないんだよ。",translation:"Chiếc áo nhận hôm qua này, đắt tiền thế mà kích cỡ lại chẳng vừa chút nào."},{speaker:"B",text:"えっ、本当？違うサイズに交換してもらえないの？",translation:"Hả, thật á? Không nhờ đổi sang cỡ khác được sao?"},{speaker:"A",text:"セール品だから交換できないって言われて、本当にショックだよ。",translation:"Họ bảo là hàng giảm giá nên không đổi được, tôi thực sự sốc luôn."}]},commonMistake:{wrong:"今日は休みのに、朝早く会社に行かなければならない。",correct:"今日は休みなのに、朝早く会社に行かなければならない。",why:"Khi kết hợp với danh từ hoặc tính từ đuôi な ở thể khẳng định hiện tại, phải dùng 「〜なのに」 thay vì nối trực tiếp 「〜のに」."},note:"Khác với 「〜けれど」 hay 「〜ても」, vế sau của 「〜のに」 luôn là sự thật đã hoặc đang diễn ra nên không được dùng câu mệnh lệnh, nhờ vả hay ý chí (như 〜てください、〜ましょう)."},{pattern:"〜くせに",meaning:"Trách móc mạnh — cùng chủ thể, thân mật/chê bai",priority:"common",explanation:"Mẫu 「〜くせに」 dùng để diễn tả vế sau có kết quả hoặc hành động trái ngược với điều đáng lẽ phải có ở vế trước, thể hiện rõ thái độ bất mãn, trách móc, mỉa mai hoặc khinh thị. Ngữ pháp này yêu cầu hai vế phải cùng một chủ thể (thuộc ngôi thứ hai hoặc thứ ba) và không bao giờ dùng cho hành động của chính người nói. Mẫu câu chỉ phù hợp trong giao tiếp thân mật hàng ngày hoặc khi phê phán gay gắt đối phương, tuyệt đối không dùng với người bề trên.",examples:[{sentence:"彼は自分では何もしないくせに、人のやり方にばかり文句を言う。",translation:"Hắn ta bản thân chẳng chịu làm gì mà lại toàn cằn nhằn, bắt bẻ cách làm của người khác."},{sentence:"まだ子供のくせに、大人のような生意気な口をきかないで。",translation:"Mới chỉ là con nít mà đừng có ăn nói xấc xược như người lớn thế."}],dialogue:{title:"Trách bạn thất hứa",lines:[{speaker:"A",text:"田中くん、今日手伝ってくれるって約束したくせに、なんでゲームしてるの？",translation:"Tanaka, đã hứa là hôm nay sẽ phụ tớ cơ mà, sao giờ lại ngồi chơi game thế hả?"},{speaker:"B",text:"ごめん！このステージが終わったらすぐ手伝うから許して！",translation:"Xin lỗi mà! Qua xong màn này là tớ phụ liền, tha cho tớ đi!"},{speaker:"A",text:"いつも口先ばかりなんだから。早く片付け始めてよ。",translation:"Cậu lúc nào cũng toàn nói mồm thôi. Mau bắt tay vào dọn dẹp đi chứ."}]},commonMistake:{wrong:"私は昨日たくさん勉強したくせに、試験に落ちてしまった。",correct:"私は昨日たくさん勉強したのに、試験に落ちてしまった。",why:"「〜くせに」 mang sắc thái chê bai, chỉ trích đối phương nên không được dùng cho bản thân (ngôi thứ nhất), trường hợp này phải dùng 「〜のに」 để thể hiện sự tiếc nuối khách quan."},note:"So với 「〜のに」 dùng trung tính cho mọi đối tượng để biểu đạt sự tiếc nuối hay bất ngờ, 「〜くせに」 chứa cảm xúc tiêu cực rõ rệt và tuyệt đối tránh dùng trong hoàn cảnh trang trọng hoặc với người trên."}],63:[{pattern:"〜そうだ（様態[ようたい]）",meaning:"Trông có vẻ ~ (suy từ mắt thấy / ngoại hình)",priority:"core",explanation:"Mẫu ngữ pháp 〜そうだ (様態) dùng để biểu thị phán đoán, suy đoán của người nói dựa trên vẻ bề ngoài hoặc dấu hiệu quan sát trực tiếp bằng mắt với nghĩa 'trông có vẻ' hoặc 'dường như sắp'. Khi đi cùng động từ thể ます (bỏ ます), mẫu câu diễn tả một hành động, sự biến đổi sắp xảy ra ngay trước mắt. Khi đi cùng tính từ đuôi い (bỏ い) hoặc tính từ đuôi な (bỏ な), mẫu diễn đạt cảm nhận tức thì về tính chất, trạng thái bên ngoài của đối tượng. Lưu ý mẫu này không áp dụng cho những sự thật hiển nhiên nhìn vào biết ngay như màu sắc hay tuổi tác.",examples:[{sentence:"このレストランの料理はどれも本当に美味しそうだ。",translation:"Món ăn nào của nhà hàng này trông cũng có vẻ thực sự rất ngon."},{sentence:"荷物を詰め込みすぎて、紙袋の底が破れそうだ。",translation:"Nhồi nhét nhiều đồ quá, đáy túi giấy trông có vẻ sắp rách ra rồi."}],dialogue:{title:"Chọn bánh ngọt",lines:[{speaker:"A",text:"ショーケースのいちごタルト、とても美味しそうだね。",translation:"Chiếc bánh tart dâu trong tủ kính trông có vẻ ngon quá nhỉ."},{speaker:"B",text:"本当だね。でも、あっちの抹茶ケーキも良さそうだよ。",translation:"Đúng thật nhỉ. Nhưng mà bánh matcha đằng kia trông cũng có vẻ được đấy."},{speaker:"A",text:"じゃあ、両方一つずつ買って一緒に食べよう。",translation:"Vậy thì chúng mình mua mỗi loại một cái rồi cùng ăn nhé."}]},commonMistake:{wrong:"天気予報によると、明日は午後から雨が降りそうだ。",correct:"天気予報によると、明日は午後から雨が降るそうだ。",why:"Khi trích dẫn thông tin nghe được từ nguồn khác (dự báo thời tiết), phải dùng thể thông thường + そうだ (nghe nói), không dùng V-masu bỏ masu + そうだ (trông có vẻ/sắp xảy ra do mắt thấy)."},note:"Cần đặc biệt lưu ý biến thể bất quy tắc: いい đổi thành よさそうだ, ない đổi thành なさそうだ; còn dạng phủ định đối với động từ thường dùng dạng 〜そうにない hoặc 〜そうもない."},{pattern:"〜そうだ（伝聞[でんぶん]）",meaning:"Nghe nói ~ (truyền đạt lại thông tin nghe được từ nguồn ngoài)",priority:"common",explanation:"Mẫu ngữ pháp này dùng để truyền đạt lại thông tin, sự việc mà người nói tiếp nhận từ một nguồn bên ngoài (nghe người khác nói, đọc tin tức, xem báo đài...) mà không thêm bớt ý kiến hay đánh giá chủ quan. Trước 「そうだ」 luôn kết hợp với thể thông thường (普通形), đặc biệt danh từ và tính từ đuôi な sẽ có dạng 「〜だそうだ」. Câu thường kết hợp với cụm từ chỉ nguồn gốc thông tin như 「〜によると」 (theo...) hoặc 「〜の話では」 (theo lời của...).",examples:[{sentence:"天気予報によると、明日は午後から激しい雨が降るそうだ。",translation:"Theo dự báo thời tiết, nghe nói từ chiều mai trời sẽ có mưa to dữ dội."},{sentence:"田中さんの話では、駅前にできた新しいイタリアンレストランはとても美味しいそうだ。",translation:"Theo lời anh Tanaka, nghe nói nhà hàng Ý mới mở trước nhà ga ngon lắm."}],dialogue:{title:"Tin đồn ở công ty",lines:[{speaker:"A",text:"木村さん、噂で聞いたんだけど、鈴木さんは来月会社を辞めて留学するそうだよ。",translation:"Chị Kimura này, tôi nghe đồn là anh Suzuki tháng sau sẽ nghỉ việc để đi du học đấy."},{speaker:"B",text:"えっ、本当ですか？先週も楽しそうに仕事をしていましたよ。",translation:"Hả, thật vậy sao? Tuần trước tôi thấy anh ấy vẫn làm việc vui vẻ mà."},{speaker:"A",text:"うん、ご本人が部長に直接伝えたそうだから、本当の話だと思うよ。",translation:"Ừ, nghe nói chính cậu ấy đã báo trực tiếp với trưởng phòng rồi, nên tôi nghĩ đúng là chuyện thật đấy."}]},commonMistake:{wrong:"ニュースによると、明日は大雨が降りそうだ。",correct:"ニュースによると、明日は大雨が降るそうだ。",why:"Khi truyền đạt lại thông tin nghe nói từ nguồn khác, phải dùng động từ thể từ điển (降るそうだ), không được bỏ ます (降りそうだ chỉ dùng khi phán đoán theo quan sát trực quan rằng trời sắp mưa)."},note:"Cần phân biệt với mẫu 「〜そうだ」（trông có vẻ/sắp sửa）khi kết hợp với động từ bỏ ます hoặc tính từ bỏ đuôi; mẫu truyền văn 「〜そうだ」 (nghe nói) luôn giữ nguyên thể thông thường (tính từ い giữ nguyên い, danh từ và tính từ な phải thêm だ)."},{pattern:"特殊形[とくしゅけい]: よさそう ／ なさそう",meaning:"Dạng đặc biệt của 様態: いい→よさそう (không phải いいそう); ない→なさそう",priority:"common",explanation:"Mẫu ngữ pháp này là dạng biến đổi đặc biệt của thể phán đoán dáng vẻ 「～そうだ」 (trông có vẻ) khi đi với tính từ 「いい」 hoặc thể phủ định 「ない」. Theo quy tắc đặc biệt, 「いい」 chuyển thành 「よさそう」, còn 「ない」 chuyển thành 「なさそう」 (tính từ phủ định như 「よくない」 chuyển thành 「よくなさそう」). Mẫu câu được sử dụng khi người nói quan sát trực quan sự vật, hiện tượng hoặc người khác rồi đưa ra nhận xét, phán đoán cảm tính dựa trên vẻ bề ngoài.",examples:[{sentence:"この仕事[しごと]は 条件[じょうけん]が よさそうに見[み]えますが、実際[じっさい]はどうですか。",translation:"Công việc này nhìn điều kiện có vẻ tốt đấy, nhưng thực tế thì thế nào?"},{sentence:"彼[かれ]は プレゼンの 前[まえ]なのに、あまり 自信[じしん]が なさそうな 顔[かお]をしています。",translation:"Sắp đến giờ thuyết trình rồi mà anh ấy lại mang vẻ mặt trông có vẻ không tự tin lắm."}],dialogue:{title:"Chọn quán ăn trưa",lines:[{speaker:"A",text:"駅前[えきまえ]に 新[あたら]しい レストランが できたみたいだけど、雰囲気[ふんいき]が よさそうだね。",translation:"Nghe nói trước ga mới mở một nhà hàng mới, không gian trông có vẻ được đấy nhỉ."},{speaker:"B",text:"でも、今[いま]の 時間[じかん]は 混[こ]んでいて、空[あ]いている 席[せき]は なさそうだよ。",translation:"Nhưng giờ này đang đông khách lắm, có vẻ không còn chỗ trống đâu."},{speaker:"A",text:"そうだね、じゃあ 今日[きょう]は 別[べつ]の 店[みせ]に しよう。",translation:"Ừ nhỉ, vậy hôm nay chúng mình đi quán khác vậy."}]},commonMistake:{wrong:"田中[たなか]さんは 今日[きょう] あまり 元気[げんき]が ないそうですね。",correct:"田中[たなか]さんは 今日[きょう] あまり 元気[げんき]が なさそうですね。",why:"Khi nhận xét dáng vẻ trực quan (trông có vẻ không có năng lượng/khỏe khoắn), bắt buộc phải biến đổi 「ない」 thành 「なさそう」, vì 「ないそう」 là mẫu truyền văn (nghe nói là không có)."},note:"Phân biệt với dạng truyền văn (nghe nói): 「いいそうだ」（nghe nói là tốt） và 「ないそうだ」（nghe nói là không có） vẫn giữ nguyên thể thông thường chứ không đổi thành よさそう hay なさそう."},{pattern:"そうだ ／ ようだ ／ らしい の 違[ちが]い",meaning:"様態そう=mắt thấy nhận định; ようだ=suy từ bằng chứng tổng hợp; らしい=nghe đồn/điển hình",priority:"common",explanation:"「そうだ」(様態) thể hiện phán đoán trực giác tức thì dựa trên những gì mắt vừa nhìn thấy (trông có vẻ). 「ようだ」 là sự suy đoán mang tính logic dựa trên những chứng cứ, manh mối gián tiếp mà người nói thu thập và tổng hợp được (hình như, dường như). Trong khi đó, 「らしい」 được dùng khi suy đoán dựa trên thông tin nghe ngóng từ người khác hoặc biểu thị tính chất đặc trưng, điển hình (nghe nói là, đậm chất).",examples:[{sentence:"道がひどく混んでいるから事故があったようだが、ニュースによると工事をしているらしい。",translation:"Đường tắc nghẽn nghiêm trọng nên dường như đã có tai nạn, nhưng theo bản tin thời sự thì nghe nói là đang làm đường."},{sentence:"田中さんは顔色が悪くて今にも倒れそうだったが、病院の検査結果では特に問題はなかったらしい。",translation:"Anh Tanaka sắc mặt nhợt nhạt trông như sắp ngã quỵ đến nơi, nhưng nghe nói theo kết quả xét nghiệm ở bệnh viện thì không có vấn đề gì nghiêm trọng."}],dialogue:{title:"Tìm quán ăn trưa",lines:[{speaker:"A",text:"駅前に新しいラーメン屋ができたそうだけど、今日の昼ご飯に行ってみない？",translation:"Nghe nói trước ga mới mở quán ramen mới, trưa nay tụi mình ghé thử không?"},{speaker:"B",text:"あそこ、いつも長い行列ができているからかなり美味しいようですね。",translation:"Chỗ đó lúc nào cũng thấy xếp hàng dài nên dường như ngon lắm đấy."},{speaker:"A",text:"でも、同僚の話だとスープが少し濃すぎるらしいから、好みが分かれるかも。",translation:"Nhưng theo lời đồng nghiệp thì nghe nói nước súp hơi bị mặn quá, nên chắc cũng tùy khẩu vị."}]},commonMistake:{wrong:"彼は指輪をしているから、最近結婚したそうだ。",correct:"彼は指輪をしているから、最近結婚したようだ。",why:"Khi suy đoán về một sự việc đã xảy ra dựa trên dấu hiệu khách quan (đeo nhẫn), phải dùng 「ようだ」 chứ không thể dùng 「そうだ」 chỉ phán đoán bề ngoài (様態)."},note:"「そうだ」(様態) chỉ dùng cho phán đoán tức thì tại thời điểm nói và không đi với thể quá khứ, trong khi 「ようだ」 và 「らしい」 có thể kết hợp linh hoạt với thể quá khứ (〜たようだ／〜たらしい)."}],64:[{pattern:"〜ようだ（推量[すいりょう]）",meaning:"Suy đoán từ bằng chứng quan sát của chính mình",priority:"core",explanation:"Mẫu câu 「〜ようだ」 dùng để diễn đạt sự suy đoán, phán đoán có căn cứ của người nói dựa trên những thông tin thu nhận từ giác quan (thấy, nghe, ngửi, nếm, chạm) hoặc từ tình huống thực tế xung quanh. Cấu trúc kết nối: Thể thông thường (V/A/N) + ようだ (lưu ý: tính từ đuôi な giữ nguyên な, danh từ chuyển thành Nの). Sắc thái thể hiện sự suy luận khách quan, logic hơn nhưng vẫn mang tính phỏng đoán cá nhân, dùng được trong cả văn viết và hội thoại lịch sự.",examples:[{sentence:"外を歩いている人がみんな傘を差しているから、雨が降っているようだ。",translation:"Thấy mọi người đi ngoài đường ai cũng che ô nên có vẻ như trời đang mưa."},{sentence:"パソコンの画面が急に真っ暗になって動かない。どうやら故障したようだ。",translation:"Màn hình máy tính tự nhiên tối đen và không hoạt động được, có vẻ như đã bị hỏng rồi."}],dialogue:{title:"Quán ăn đông khách",lines:[{speaker:"A",text:"あのラーメン屋、店の前に長い行列ができているね。",translation:"Quán mì ramen đằng kia có hàng dài người đang xếp hàng trước quán kìa."},{speaker:"B",text:"本当だね。テレビやSNSで最近話題になっている人気の店のようだよ。",translation:"Đúng thật nhỉ. Có vẻ là quán nổi tiếng đang được quan tâm nhiều trên TV và mạng xã hội đấy."},{speaker:"A",text:"美味しそうだね。今度時間がある時に並んで食べてみよう。",translation:"Trông có vẻ ngon ghê. Hôm nào có thời gian tụi mình xếp hàng ăn thử nhé."}]},commonMistake:{wrong:"道がひどく渋滞しているから、前で事故ようだ。",correct:"道がひどく渋滞しているから、前で事故のようだ。",why:"Khi nối Danh từ với 「〜ようだ」 để đưa ra phán đoán, bắt buộc phải thêm trợ từ 「の」 thành dạng 「N + の ＋ ようだ」 chứ không được ghép trực tiếp."},note:"Khác với 「〜そうだ」 biểu thị cảm nhận trực quan tức thì ngay khi nhìn vào sự vật (trông có vẻ), 「〜ようだ」 thể hiện quá trình suy luận từ các dấu hiệu, bằng chứng gián tiếp mà người nói quan sát được."},{pattern:"まるで〜ようだ（比喩[ひゆ]）",meaning:'Ví von, so sánh: "Cứ như là…"',priority:"common",explanation:'Mẫu câu 「まるで〜ようだ」 được dùng để ví von, so sánh một sự vật, sự việc với một điều gì khác có nét tương đồng mang tính hình tượng (nghĩa là "cứ như là..."). Phó từ 「まるで」 có tác dụng nhấn mạnh mức độ giống nhau đến ngỡ ngàng, mặc dù thực tế không phải là như vậy. Cấu trúc này thường kết hợp với danh từ theo dạng 「まるで + N + のようだ」 hoặc mệnh đề thể thông thường trước 「ようだ」. Mẫu câu này rất phổ biến trong cả văn học miêu tả lẫn giao tiếp hàng ngày khi muốn biểu đạt cảm xúc ngạc nhiên, thích thú.',examples:[{sentence:"今日は4月なのにとても寒くて、まるで真冬のようだ。",translation:"Hôm nay dù đã là tháng 4 rồi mà trời rất lạnh, cứ như thể đang giữa mùa đông vậy."},{sentence:"合格通知を受け取った瞬間は嬉しすぎて、まるで夢を見ているようだった。",translation:"Khoảnh khắc nhận được giấy báo đỗ tôi vui sướng đến mức cứ như là đang nằm mơ vậy."}],dialogue:{title:"Trải nghiệm trò chơi VR",lines:[{speaker:"A",text:"このVRゲーム、本当にリアルで、まるで別の世界に入り込んだようだね。",translation:"Trò chơi VR này chân thực thật đấy, cứ như là mình vừa bước vào một thế giới khác vậy nhỉ."},{speaker:"B",text:"本当だね。映像も音も迫力があるから、ゲームの中にいると錯覚しちゃうよ。",translation:"Công nhận luôn. Hình ảnh và âm thanh sống động quá nên cứ ngỡ như đang ở trong game thật."},{speaker:"A",text:"うん、あまりに面白くて時間を忘れちゃうね。",translation:"Ừ, cuốn quá làm mình quên hết cả thời gian luôn."}]},commonMistake:{wrong:"彼女の肌は白くて、まるで雪そうだ。",correct:"彼女の肌は白くて、まるで雪のようだ。",why:"Khi dùng phó từ 「まるで」 để so sánh ví von (cứ như là...) thì phải kết hợp với 「〜のようだ / 〜みたいだ」, không kết hợp với 「〜そうだ」 (dùng phỏng đoán diện mạo/dấu hiệu)."},note:"Trong văn nói thân mật hàng ngày, người Nhật thường dùng 「まるで〜みたいだ」 thay cho 「まるで〜ようだ」 để câu chuyện trở nên tự nhiên, gần gũi hơn."},{pattern:"〜みたいだ（口語[こうご]）",meaning:"Tương đương ようだ nhưng khẩu ngữ thân mật; N+みたいだ (không cần の)",priority:"common",explanation:"「〜みたいだ」được dùng trong văn nói hàng ngày để diễn đạt suy đoán dựa trên cảm nhận trực tiếp (trông có vẻ, dường như) hoặc dùng để ví von, so sánh (giống như là). Mẫu này có ý nghĩa tương đương với「〜ようだ」nhưng mang sắc thái khẩu ngữ, thân mật và gần gũi hơn. Khi kết hợp, danh từ và tính từ đuôi な đi trực tiếp với「みたいだ」mà không cần thêm trợ từ「の」hay「な」.",examples:[{sentence:"隣の部屋から物音がしないね。山田さんはもう寝たみたいだ。",translation:"Không có tiếng động nào từ phòng bên cạnh nhỉ. Có vẻ như anh Yamada đã đi ngủ rồi."},{sentence:"彼女はいつも明るくて、まるで太陽みたいだ。",translation:"Cô ấy lúc nào cũng tươi sáng, hệt như mặt trời vậy."}],dialogue:{title:"Trời sắp mưa",lines:[{speaker:"A",text:"外が急に暗くなってきたね。雨が降り始めたみたいだ。",translation:"Ngoài trời bỗng nhiên tối sầm lại rồi nhỉ. Hình như trời bắt đầu mưa rồi."},{speaker:"B",text:"本当だ。今朝、傘を持ってきてよかったよ。",translation:"Thật đấy. May mà sáng nay mình đã mang ô theo."},{speaker:"A",text:"うん、予報通り夕方から大雨になるみたいだね。",translation:"Ừ, có vẻ đúng như dự báo là từ chiều tối sẽ mưa to đấy."}]},commonMistake:{wrong:"田中さんはプロの歌手のみたいに歌が上手ですね。",correct:"田中さんはプロの歌手みたいに歌が上手ですね。",why:"「みたいだ」kết hợp trực tiếp với danh từ mà không chèn thêm「の」như cấu trúc「〜のようだ」."},note:"「〜みたいだ」chỉ dùng trong khẩu ngữ thân mật hàng ngày; trong văn viết trang trọng, báo cáo hoặc khi nói lịch sự cần đổi sang「〜ようだ」."}],65:[{pattern:"〜らしい（伝聞[でんぶん]）",meaning:"Nghe nói ~ / Dường như ~ (thông tin gián tiếp, nguồn bên ngoài)",priority:"core",explanation:"Mẫu câu 「〜らしい」 dùng để truyền đạt lại thông tin nghe được gián tiếp từ người khác, tin đồn, hoặc qua các phương tiện truyền thông. Sắc thái của mẫu này thể hiện phán đoán dựa trên nguồn tin bên ngoài nhưng người nói không chịu trách nhiệm hay khẳng định 100% tính xác thực của thông tin. Cấu trúc này thường được dùng nhiều trong giao tiếp hàng ngày khi chia sẻ những chuyện nghe ngóng được một cách khách quan, dè dặt.",examples:[{sentence:"来月、駅の前に新しいカフェができるらしいよ。",translation:"Nghe nói tháng sau ở trước nhà ga sẽ mở một quán cà phê mới đấy."},{sentence:"田中さんは来週から大阪へ転勤するらしいです。",translation:"Nghe nói anh Tanaka sẽ chuyển công tác đến Osaka từ tuần sau."}],dialogue:{title:"Chuyện nghỉ việc của đồng nghiệp",lines:[{speaker:"A",text:"山田さん、今月末で会社を辞めるらしいよ。",translation:"Nghe nói anh Yamada cuối tháng này sẽ nghỉ việc đấy."},{speaker:"B",text:"えっ、本当？全然知らなかった。どうして辞めるの？",translation:"Hả, thật á? Tôi hoàn toàn không biết luôn. Sao anh ấy lại nghỉ thế?"},{speaker:"A",text:"自分で新しいビジネスを始めるらしいよ。",translation:"Nghe nói là anh ấy sẽ tự mình bắt đầu công việc kinh doanh mới."}]},commonMistake:{wrong:"天気予報によると、明日は雨だらしい。",correct:"天気予報によると、明日は雨らしい。",why:"Khi kết hợp với danh từ hoặc tính từ đuôi な, phải bỏ 「だ」 rồi mới ghép trực tiếp với 「らしい」 chứ không dùng 「〜だらしい」."},note:"Khác với 「〜そうだ」 (truyền đạt lại nguyên văn thông tin từ nguồn xác định), 「〜らしい」 mang sắc thái thông tin gián tiếp, mơ hồ và độ tin cậy thấp hơn."},{pattern:"〜らしい（典型[てんけい]）",meaning:"Đúng chất ~ / Ra dáng ~ (tiêu biểu, đặc trưng của loại đó)",priority:"common",explanation:'Mẫu 「〜らしい」 đi trực tiếp sau danh từ để diễn tả một người hay sự vật mang trọn vẹn đặc trưng, phẩm chất tiêu biểu vốn có của đối tượng đó ("đúng chất ~", "ra dáng ~"). Cấu trúc này được chia và sử dụng tương tự như một tính từ đuôi い (らしさ, らしく, らしくない). Điểm cốt lõi là chủ thể thực sự thuộc về danh từ đó và đang thể hiện đúng bản chất tốt đẹp, tự nhiên mà mọi người kỳ vọng.',examples:[{sentence:"学生なんだから、もっと学生らしく真面目に勉強しなさい。",translation:"Đã là học sinh thì hãy học hành chăm chỉ cho ra dáng học sinh đi chứ."},{sentence:"彼はどんなにピンチの時でも冷静で、実にリーダーらしい人だ。",translation:"Anh ấy dù trong hoàn cảnh nguy cấp đến đâu vẫn luôn bình tĩnh, quả thực là người đúng chất thủ lĩnh."}],dialogue:{title:"Chọn trang phục phỏng vấn",lines:[{speaker:"A",text:"面接に行くなら、その派手な服じゃなくて、もっと就活生らしいスーツを着たほうがいいよ。",translation:"Nếu đi phỏng vấn thì đừng mặc đồ sặc sỡ thế, cậu nên mặc vest cho ra dáng người đi xin việc hơn."},{speaker:"B",text:"そうだね。第一印象は大事だから、黒のリクルートスーツに着替えてくるよ。",translation:"Cậu nói đúng. Ấn tượng đầu tiên rất quan trọng nên tớ sẽ đi thay bộ vest đen dùng cho tuyển dụng."},{speaker:"A",text:"うん、それがいい。清潔感があって面接官にも好印象を与えられるはずだよ。",translation:"Ừ, thế là chuẩn đấy. Trông lịch sự sạch sẽ chắc chắn sẽ tạo được ấn tượng tốt với người phỏng vấn."}]},commonMistake:{wrong:"彼はもう20歳なのに、子供らしいわがままを言っている。",correct:"彼はもう20歳なのに、子供っぽいわがままを言っている。",why:"「〜らしい」chỉ dùng khi chủ thể thực sự là đối tượng đó (trẻ con đúng chất trẻ con), còn người lớn hành xử như trẻ con thì phải dùng「〜っぽい」."},note:"Cần phân biệt với 「〜っぽい」 (thường mang nghĩa chê bai hoặc tính chất giống bề ngoài) và 「〜みたい」 (dùng để so sánh ví von với đối tượng vốn dĩ không phải là nó)."},{pattern:"らしい（伝聞[でんぶん]）vs そうだ（伝聞[でんぶん]）",meaning:"らしい = thông tin lan truyền/mờ nguồn; そうだ = dẫn lời trực tiếp (TV/báo nói rõ)",priority:"common",explanation:"Cả 「らしい」 và 「そうだ」 đều dùng để truyền đạt lại thông tin nghe được từ người khác (truyền ngôn), nhưng khác nhau về mức độ rõ ràng của nguồn tin. 「らしい」 dùng khi tiếp nhận thông tin từ tin đồn, truyền miệng mơ hồ mà người nói không biết rõ hoặc không chắc chắn về nguồn gốc. Ngược lại, 「そうだ」 dùng khi trích dẫn lại thông tin từ nguồn xác thực, đáng tin cậy như báo đài, thời sự hoặc lời nói trực tiếp từ một người cụ thể (thường đi kèm 「～によると」, 「～では」). Do đó, khi muốn truyền đạt thông tin có căn cứ rõ ràng thì dùng 「そうだ」, còn khi chỉ là lời đồn đãi phong phanh thì dùng 「らしい」.",examples:[{sentence:"誰から聞いたかは覚えていないが、駅前に新しいラーメン屋ができるらしい。",translation:"Tôi không nhớ là nghe từ ai, nhưng nghe đồn hình như sắp có một quán ramen mới mở trước nhà ga."},{sentence:"噂ではコンサートが中止になるらしいが、公式発表によると予定通り行われるそうだ。",translation:"Nghe đồn là buổi hòa nhạc dường như sẽ bị hủy, nhưng theo thông báo chính thức thì nghe nói vẫn sẽ diễn ra theo đúng kế hoạch."}],dialogue:{title:"Tin đồn về đồng nghiệp",lines:[{speaker:"A",text:"噂で聞いたんだけど、鈴木さんは来月会社を辞めるらしいよ。",translation:"Nghe đồn phong phanh là hình như tháng sau anh Suzuki sẽ nghỉ việc đấy."},{speaker:"B",text:"えっ、本当？でも部長の話によると、別の部署に異動するだけだそうだよ。",translation:"Hả, thật á? Nhưng theo lời của trưởng phòng thì nghe nói anh ấy chỉ chuyển sang bộ phận khác thôi."},{speaker:"A",text:"そうなんだ。不確かな噂だったんだね、安心したよ。",translation:"Ra là vậy. Cứ tưởng là tin đồn không chuẩn, may mà yên tâm rồi."}]},commonMistake:{wrong:"新聞によると、明日は全国的に大雪が降るらしい。",correct:"新聞によると、明日は全国的に大雪が降るそうだ。",why:"Khi trích dẫn nguồn tin chính thức, xác thực bằng「～によると」thì phải dùng「そうだ」để dẫn lại trung thực, không dùng「らしい」vì「らしい」chỉ mang tính đồn đoán, mờ nguồn."},note:"Cần chú ý cách nối:「そうだ」(truyền ngôn) đi với thể thông thường bao gồm cả「だ」(N/Tính từ -na + だそうだ), trong khi「らしい」kết hợp trực tiếp với N và Tính từ -na mà không có「だ」."},{pattern:"らしい（伝聞[でんぶん]）vs ようだ（推量[すいりょう]）",meaning:"らしい = thông tin từ người khác; ようだ = bằng chứng mình tự quan sát thấy",priority:"common",explanation:"「らしい」 được dùng để truyền đạt lại thông tin nghe từ người khác, báo đài hoặc dư luận mà bản thân người nói không trực tiếp chứng kiến. Ngược lại, 「ようだ」 thể hiện sự suy đoán mang tính chủ quan của người nói dựa trên những bằng chứng, dấu hiệu cụ thể do chính mắt mình thấy hoặc cảm nhận qua các giác quan. Để chọn đúng, hãy nhớ: tiếp nhận tin tức từ nguồn bên ngoài dùng 「らしい」, còn tự quan sát hiện trường thấy dấu vết để phán đoán thì dùng 「ようだ」.",examples:[{sentence:"山田さんは来月アメリカの支社へ転勤するらしいですよ。",translation:"Nghe nói anh Yamada tháng sau sẽ chuyển công tác sang chi nhánh ở Mỹ đấy."},{sentence:"道が濡れて水たまりができているから、さっきまで強い雨が降っていたようだ。",translation:"Đường ướt và có vũng nước đọng nên dường như lúc nãy trời vừa mưa rất to."}],dialogue:{title:"Tình hình của đồng nghiệp",lines:[{speaker:"A",text:"田中さん、今日はずいぶん元気がないようですね。顔色も悪いですし。",translation:"Anh Tanaka hôm nay trông có vẻ không được khỏe nhỉ. Sắc mặt cũng nhợt nhạt nữa."},{speaker:"B",text:"ええ、さっき佐藤さんから聞いたんですが、昨日から高熱が出ているらしいですよ。",translation:"Vâng, lúc nãy tôi nghe chị Sato nói thì hình như từ hôm qua anh ấy đã bị sốt cao đấy."},{speaker:"A",text:"そうなんですか。無理をしないで早く帰って休むといいですね。",translation:"Thế à. Mong là anh ấy không gắng gượng mà về sớm nghỉ ngơi thì tốt."}]},commonMistake:{wrong:"窓ガラスが割れているのを見たから、泥棒が入ったらしい。",correct:"窓ガラスが割れているのを見たから、泥棒が入ったようだ。",why:"Khi đưa ra phán đoán dựa trên chứng cứ cụ thể do chính mình trực tiếp quan sát thấy (nhìn thấy kính vỡ) thì phải dùng 「ようだ」, còn 「らしい」 chỉ dùng cho thông tin nghe kể lại."},note:"Khi phán đoán không có nguồn tin bên ngoài mà chỉ dựa trên cảm giác, trực giác hoặc dấu hiệu trước mắt, hãy dùng 「ようだ」 thay vì 「らしい」."}],66:[{pattern:"〜ほど〜ない",meaning:"Không... đến mức như... (so sánh phủ định mức CAO)",priority:"core",explanation:'Mẫu câu 「〜ほど〜ない」 dùng để so sánh hai đối tượng, biểu thị ý nghĩa "A không đạt đến mức độ/tiêu chuẩn cao như B" (A không bằng B). Điểm mấu chốt là vị ngữ ở cuối câu luôn luôn phải chia ở thể phủ định (〜ない). Ngữ pháp này thể hiện sự đánh giá, cảm nhận chủ quan của người nói về mức độ, tính chất hoặc trạng thái khi lấy đối tượng B làm tiêu chuẩn so sánh.',examples:[{sentence:"今のアパートの家賃は、思っていたほど高くない。",translation:"Tiền thuê căn hộ hiện tại không đắt đến mức như tôi đã nghĩ."},{sentence:"今年の冬は、去年の冬ほど寒くない。",translation:"Mùa đông năm nay không lạnh bằng mùa đông năm ngoái."}],dialogue:{title:"Đánh giá quán ăn mới",lines:[{speaker:"A",text:"駅前に新しくできたラーメン屋、もう行ってみた？",translation:"Cậu đã đi thử quán ramen mới mở trước ga chưa?"},{speaker:"B",text:"昨日行ったけど、ネットの評判ほど美味しくないよ。",translation:"Hôm qua tớ đi rồi, nhưng không ngon như lời đồn trên mạng đâu."},{speaker:"A",text:"そうなんだ。じゃあ別の店に行こう。",translation:"Thế à. Vậy thì chúng mình đi quán khác nhé."}]},commonMistake:{wrong:"私の部屋は田中さんの部屋ほど広いです。",correct:"私の部屋は田中さんの部屋ほど広くないです。",why:"Mẫu 「〜ほど〜ない」 bắt buộc phải đi với vị ngữ ở thể phủ định để diễn tả so sánh kém, không được kết hợp với thể khẳng định."},note:"Để diễn tả so sánh kém (không bằng), tiếng Nhật dùng 「ほど〜ない」 chứ tuyệt đối không dùng 「より〜ない」."},{pattern:"〜くらい／〜ぐらい",meaning:"Khoảng... / ít nhất là... / chỉ cỡ... (mức THẤP hoặc tối thiểu)",priority:"common",explanation:'Mẫu ngữ pháp 「〜くらい／〜ぐらい」 dùng để biểu thị mức độ tối thiểu hoặc những việc rất đỗi đơn giản, cơ bản ("ít nhất là...", "chỉ cỡ..."). Cấu trúc này thường đi sau danh từ hoặc động từ nhằm đưa ra một tiêu chuẩn nhỏ nhặt mà người nói cho rằng hiển nhiên phải làm được. Trong giao tiếp, mẫu câu thường mang sắc thái xem nhẹ mức độ của sự việc, hoặc dùng để nhắc nhở, phê bình khi đối phương không thực hiện được ngay cả điều tối thiểu đó.',examples:[{sentence:"自分の部屋の掃除くらい、自分でやりなさい。",translation:"Chuyện như dọn dẹp phòng của mình thì ít nhất con cũng phải tự làm đi chứ."},{sentence:"挨拶されたら、笑顔で会釈するくらいはしてほしいものだ。",translation:"Khi được người khác chào hỏi, ít nhất tôi cũng muốn họ mỉm cười gật đầu đáp lại."}],dialogue:{title:"Nhắc nhở bạn cùng phòng",lines:[{speaker:"A",text:"ねぇ、食べた後の食器を水につけるくらいはやっておいてよ。",translation:"Này, ít nhất sau khi ăn xong thì cậu cũng ngâm bát đĩa vào nước giùm cái chứ."},{speaker:"B",text:"ごめんごめん、今朝は急いで出かけちゃって忘れてた。",translation:"Xin lỗi nhé, sáng nay tớ vội đi quá nên quên mất."},{speaker:"A",text:"次からはお互いに気持ちよく過ごせるように気をつけてね。",translation:"Từ lần sau chú ý hơn để cả hai cùng thoải mái nhé."}]},commonMistake:{wrong:"忙しくても、LINEの返信ほどしてください。",correct:"忙しくても、LINEの返信くらいしてください。",why:'「ほど」 không dùng để biểu thị mức độ tối thiểu hay xem nhẹ sự việc ("ít nhất là..."), trường hợp này bắt buộc phải dùng 「くらい／ぐらい」.'},note:"Khác với 「ほど」 thường nhấn mạnh mức độ cao hoặc so sánh tương đương, 「くらい／ぐらい」 có nét nghĩa đặc trưng là hạ thấp mức độ xuống mức tối thiểu, tầm thường."},{pattern:"〜ば〜ほど",meaning:"Càng... thì càng... (tỉ lệ thuận — ば-form + cùng từ + ほど)",priority:"common",explanation:'Mẫu câu này dùng để diễn đạt mối quan hệ tỉ lệ thuận: khi một hành động hoặc trạng thái ở vế trước thay đổi hay tăng mức độ, thì sự việc ở vế sau cũng thay đổi tương ứng (nghĩa là "càng... thì càng..."). Về mặt cấu trúc, ta lặp lại cùng một từ hai lần: lần đầu chia ở thể điều kiện (〜ば), lần thứ hai giữ ở dạng từ điển/nguyên thể đứng trước「ほど」(VばVるほど / AければAいほど / Naなら/であればNaなほど). Mẫu ngữ pháp này rất tự nhiên, được dùng phổ biến trong cả giao tiếp hàng ngày lẫn văn viết để chỉ các quy luật hoặc trải nghiệm tích lũy.',examples:[{sentence:"この本は読めば読むほど面白くなってきます。",translation:"Cuốn sách này càng đọc thì lại càng thấy thú vị."},{sentence:"アパートは駅から近ければ近いほど家賃が高くなります。",translation:"Căn hộ càng gần ga thì tiền thuê nhà càng đắt."}],dialogue:{title:"Chọn mua máy tính",lines:[{speaker:"A",text:"パソコンを買いたいんだけど、どんなスペックがいいかな。",translation:"Tôi muốn mua máy tính, không biết nên chọn thông số cấu hình thế nào thì tốt nhỉ?"},{speaker:"B",text:"性能は高ければ高いほど使いやすいけど、その分値段も高くなるよ。",translation:"Hiệu năng càng cao thì dùng càng mượt, nhưng kèm theo đó giá cũng sẽ đắt hơn đấy."},{speaker:"A",text:"そうだよね。予算と相談して、自分に合ったものを探してみるよ。",translation:"Đúng thế thật. Để tôi cân đối ngân sách rồi tìm cái vừa sức mình."}]},commonMistake:{wrong:"この小説は読めばほど面白くなります。",correct:"この小説は読めば読むほど面白くなります。",why:"Người học hay quên lặp lại động từ ở thể từ điển trước「ほど」, trong khi cấu trúc chuẩn bắt buộc phải có cả dạng「〜ば」và thể từ điển của cùng một từ đi liền trước「ほど」."},note:"Với tính từ đuôi な và danh từ, ngoài dạng thông thường như「静かなら静かなほど」, trong văn phong trang trọng người ta rất hay dùng biến thể「〜であればあるほど」."},{pattern:"N/Vほど〜(肯定[こうてい])",meaning:"Đến mức... (nhấn mạnh mức độ cực cao, câu khẳng định)",priority:"common",explanation:"Mẫu ngữ pháp này dùng để diễn tả mức độ của một hành động hay trạng thái cao đến mức gần như chạm tới tình trạng được nêu ở vế trước (thường mang tính ví von hoặc phóng đại cực độ). Vế trước đi kèm với danh từ hoặc động từ ở thể từ điển, thể khả năng hay thể mong muốn (-たい), vế sau là tính từ hoặc động từ thể hiện mức độ/cảm xúc ở thể khẳng định. So với 「くらい」, mẫu 「ほど」 mang sắc thái kịch tính, biểu cảm mạnh mẽ hơn và thường được dùng nhiều trong văn viết hoặc văn phong trang trọng.",examples:[{sentence:"昨日の夜はお腹が痛くて、死ぬほど苦しかったです。",translation:"Tối qua tôi bị đau bụng, khổ sở đến mức tưởng như chết đi được."},{sentence:"富士山の山頂から見た日の出は、言葉を失うほど美しかった。",translation:"Cảnh mặt trời mọc nhìn từ đỉnh núi Phú Sĩ đẹp đến mức khiến người ta nghẹn lời."}],dialogue:{title:"Áp lực công việc",lines:[{speaker:"A",text:"最近仕事はどう？体調は大丈夫？",translation:"Dạo này công việc thế nào rồi? Sức khỏe vẫn ổn chứ?"},{speaker:"B",text:"息つく暇もないほど忙しくて、毎日残業ばかりだよ。",translation:"Bận đến mức không có lấy một hơi để thở, ngày nào cũng phải tăng ca suốt."},{speaker:"A",text:"無理しないでね。今週末はゆっくり休んで。",translation:"Đừng cố quá sức nhé. Cuối tuần này nhớ nghỉ ngơi cho lại sức."}]},commonMistake:{wrong:"昨日転んで、泣いたほど痛かった。",correct:"昨日転んで、泣くほど痛かった。",why:"Khi dùng mẫu chỉ mức độ 「〜ほど」, động từ đứng trước dùng để làm chuẩn so sánh nên phải để ở thể nguyên dạng (hoặc -たい/khả năng), không được chia về thể quá khứ (-た)."},note:"Cả 「ほど」 và 「くらい」 đều dùng để chỉ mức độ, nhưng 「ほど」 diễn tả mức độ cực đoan hơn và mang tính biểu cảm, trang trọng hơn 「くらい」."}],67:[{pattern:"〜について（は）",meaning:"Về chủ đề ~, liên quan đến ~ (trung dung → trang trọng)",priority:"core",explanation:"Mẫu câu 「〜について（は）」 dùng để biểu thị chủ đề, nội dung mà người nói hướng tới để suy nghĩ, tìm hiểu, thảo luận hoặc truyền đạt thông tin. Vế sau thường đi cùng các động từ chỉ hoạt động ngôn ngữ hoặc tư duy như 話す (nói), 調べる (tra cứu), 考える (suy nghĩ), 質問する (hỏi). Mẫu này mang sắc thái từ trung tính đến trang trọng, được sử dụng rất phổ biến trong cả đời sống thường ngày, học thuật và công sở.",examples:[{sentence:"日本の伝統文化についての本を読んで、たくさんの知識を得ることができた。",translation:"Đọc cuốn sách về văn hóa truyền thống Nhật Bản, tôi đã tiếp thu được rất nhiều kiến thức."},{sentence:"来週の企画案について、チームの皆さんと意見を交換したいと考えております。",translation:"Tôi muốn trao đổi ý kiến với mọi người trong nhóm về bản kế hoạch tuần tới."}],dialogue:{title:"Thảo luận công việc",lines:[{speaker:"A",text:"先輩、新しいプロジェクトの進捗状況について少しご相談があるのですが、今お時間よろしいでしょうか。",translation:"Tiền bối ơi, em có chút việc muốn thảo luận về tiến độ dự án mới, hiện tại anh có thời gian không ạ?"},{speaker:"B",text:"ええ、いいですよ。何か困っていることでもあるの？",translation:"Ừ, được chứ. Em đang gặp khó khăn gì à?"},{speaker:"A",text:"はい、追加の予算についてクライアントから質問を受けまして、その対応をご相談したいです。",translation:"Dạ, em nhận được câu hỏi từ khách hàng về khoản ngân sách bổ sung, nên em muốn xin ý kiến anh về cách xử lý ạ."}]},commonMistake:{wrong:"これは将来の夢について作文です。",correct:"これは将来の夢についての作文です。",why:"Khi dùng 「〜について」 để bổ nghĩa trực tiếp cho một danh từ đứng liền sau, bắt buộc phải đổi sang dạng 「〜についての ＋ Danh từ」 chứ không được nối trực tiếp."},note:"Mẫu 「〜に関して」 có nghĩa tương tự nhưng mang sắc thái trang trọng hơn và bao hàm phạm vi liên quan rộng hơn so với 「〜について」."},{pattern:"〜に関して（は）・〜に関する",meaning:"Về vấn đề ~ (trang trọng — văn báo cáo / hội nghị / pháp lý)",priority:"common",explanation:'Mẫu câu này có nghĩa là "về / liên quan đến (vấn đề nào đó)", dùng khi muốn nêu ra một chủ đề, đối tượng để trình bày, thảo luận hoặc điều tra. Về cấu trúc, danh từ kết hợp trực tiếp thành 「N ＋ に関して」 khi bổ nghĩa cho vị ngữ phía sau, hoặc 「N ＋ に関する ＋ N」 khi bổ nghĩa trực tiếp cho danh từ. Đây là cách diễn đạt mang tính trang trọng, văn phong lịch sự, thường xuất hiện trong báo cáo, tin tức, hội thảo hoặc các văn bản chính thức (trang trọng hơn 「〜について」).',examples:[{sentence:"今回の不祥事に関して、現在詳しい調査を行っております。",translation:"Liên quan đến vụ việc bê bối lần này, hiện chúng tôi đang tiến hành điều tra chi tiết."},{sentence:"AI技術の活用に関する論文を執筆しています。",translation:"Tôi đang viết luận văn liên quan đến việc ứng dụng công nghệ AI."}],dialogue:{title:"Hỏi về thủ tục visa",lines:[{speaker:"A",text:"すみません、ビザの更新手続きに関して質問があるのですが。",translation:"Xin lỗi, tôi có thắc mắc liên quan đến thủ tục gia hạn visa ạ."},{speaker:"B",text:"はい、どのようなことでしょうか。こちらの窓口でお伺いします。",translation:"Vâng, có vấn đề gì vậy ạ? Tôi xin tiếp nhận tại quầy này."},{speaker:"A",text:"必要書類に関する詳しい案内をいただけますか。",translation:"Chị có thể cho tôi xin hướng dẫn chi tiết về các giấy tờ cần thiết được không ạ?"}]},commonMistake:{wrong:"新しい就労ビザに関して説明会が開催されます。",correct:"新しい就労ビザに関する説明会が開催されます。",why:"Khi bổ nghĩa trực tiếp cho danh từ đứng sau (説明会), bắt buộc phải dùng dạng 「〜に関する＋N」 chứ không được dùng 「〜に関して」."},note:"「〜に関して」 mang sắc thái trang trọng và bao hàm phạm vi vấn đề rộng hơn 「〜について」, không dùng cho các chủ đề đời thường hoặc giao tiếp thân mật hàng ngày."},{pattern:"〜についての ＋ N",meaning:"Danh ngữ hoá với について → phải thêm の trước danh từ",priority:"common",explanation:'Mẫu 「〜についての＋N」 mang ý nghĩa "về / liên quan đến...", dùng để bổ nghĩa trực tiếp cho một danh từ đứng phía sau. Đây là dạng bổ ngữ danh từ của 「〜について」, bắt buộc phải thêm trợ từ 「の」 khi kết nối với danh từ tiếp theo. Cấu trúc này thường xuất hiện trong văn viết, báo cáo, thuyết trình hoặc các ngữ cảnh công việc mang tính lịch sự, trang trọng.',examples:[{sentence:"日本の伝統文化についての本を何冊か読みました。",translation:"Tôi đã đọc vài cuốn sách về văn hóa truyền thống Nhật Bản."},{sentence:"新商品の開発についての意見を自由に出してください。",translation:"Xin hãy tự do đưa ra ý kiến về việc phát triển sản phẩm mới."}],dialogue:{title:"Chuẩn bị bài thuyết trình",lines:[{speaker:"A",text:"来週のプレゼンについての資料はもう準備できましたか。",translation:"Tài liệu về bài thuyết trình tuần tới cậu đã chuẩn bị xong chưa?"},{speaker:"B",text:"はい、大体まとまりましたが、グラフのデータをもう少し確認したいです。",translation:"Vâng, em đã tổng hợp hòm hòm rồi, nhưng muốn kiểm tra lại số liệu biểu đồ một chút ạ."},{speaker:"A",text:"分かりました。じゃあ、今日の午後一緒に見直しましょう。",translation:"Được rồi. Vậy chiều nay chúng ta cùng xem lại nhé."}]},commonMistake:{wrong:"明日の会議について連絡をメールで送りました。",correct:"明日の会議についての連絡をメールで送りました。",why:"Vì phía sau là danh từ 「連絡」 nên bắt buộc phải dùng 「についての」 để bổ nghĩa, không thể dùng trực tiếp 「について」."},note:"Cần tránh nhầm lẫn với 「〜に対しての＋N」 vốn nhấn mạnh vào thái độ, hành động hướng trực tiếp tới đối tượng tác động."},{pattern:"に関して ≠ について （文体[ぶんたい]の使[つか]い分[わ]け）",meaning:"Phân biệt văn phong: に関して chỉ dùng văn viết/hội nghị; について dùng cả hai",priority:"common",explanation:'Cả 「に関して」 và 「について」 đều mang nghĩa "về / liên quan đến" một chủ đề hoặc đối tượng nào đó. Tuy nhiên, 「について」 là cách diễn đạt phổ biến, dùng tự nhiên trong cả hội thoại đời thường lẫn văn phong trang trọng. Ngược lại, 「に関して」 mang sắc thái trang trọng, lịch sự và cứng cáp hơn, chủ yếu xuất hiện trong văn viết, báo cáo, tin tức hoặc hội nghị chính thức. Do đó, với những chủ đề thường ngày hoặc khi trò chuyện thân mật, việc dùng 「に関して」 sẽ tạo cảm giác thiếu tự nhiên và gượng gạo.',examples:[{sentence:"本日の会議では、新商品の開発計画に関して話し合います。",translation:"Trong cuộc họp hôm nay, chúng ta sẽ thảo luận về kế hoạch phát triển sản phẩm mới."},{sentence:"週末の旅行の予定について、友達と電話で相談した。",translation:"Tôi đã bàn bạc với bạn qua điện thoại về lịch trình chuyến du lịch cuối tuần."}],dialogue:{title:"Chuẩn bị bài thuyết trình",lines:[{speaker:"A",text:"来週の発表のテーマについて、何かアイデアはある？",translation:"Cậu có ý tưởng gì về chủ đề bài thuyết trình tuần tới chưa?"},{speaker:"B",text:"日本の伝統文化について話そうと思っているよ。",translation:"Tớ định nói về văn hóa truyền thống Nhật Bản đấy."},{speaker:"A",text:"いいね！じゃあ、今度のゼミで先生にも相談してみよう。",translation:"Hay đấy! Vậy buổi thảo luận tới tụi mình thử hỏi ý kiến thầy giáo xem sao."}]},commonMistake:{wrong:"昨日のサッカーの試合に関して話そうよ。",correct:"昨日のサッカーの試合について話そうよ。",why:"Với các chủ đề đời thường trong giao tiếp thân mật, dùng 「に関して」 sẽ quá trang trọng và cứng nhắc, cần đổi sang 「について」."},note:"Khi bổ nghĩa trực tiếp cho danh từ đứng sau, hai mẫu này sẽ chuyển thành dạng 「〜に関する＋Danh từ」 và 「〜についての＋Danh từ」."}],68:[{pattern:"N によって① ― 原因[げんいん]・要因[よういん]",meaning:"Do / vì ~ (nguyên nhân, yếu tố gây ra — văn trang trọng)",priority:"core",explanation:"Mẫu câu này dùng để biểu thị nguyên nhân hoặc yếu tố trực tiếp dẫn đến một sự việc, biến đổi hay hậu quả nào đó. Cấu trúc đi kèm là Danh từ + によって (hoặc Danh từ 1 + による + Danh từ 2 khi bổ nghĩa cho danh từ). Mẫu mang sắc thái trang trọng, khách quan, xuất hiện phổ biến trong văn viết, báo chí, thời sự hoặc các bản báo cáo. Vế sau biểu thị kết quả phát sinh mang tính tự nhiên hay ngoài ý muốn, không dùng cho hành vi mang tính chủ ý cá nhân hay câu cầu khiến.",examples:[{sentence:"大雨によって列車の運行に遅れが生じています。",translation:"Do mưa lớn nên lịch trình hoạt động của các chuyến tàu đang bị chậm trễ."},{sentence:"長時間のデスクワークによって、肩こりや腰痛に悩まされる人が増えています。",translation:"Do ngồi làm việc bàn giấy trong thời gian dài nên số người bị đau vai gáy và đau lưng đang tăng lên."}],dialogue:{title:"Báo cáo tiến độ công việc",lines:[{speaker:"A",text:"システムの不具合によって、データの移行作業が一時中断してしまいました。",translation:"Do sự cố hệ thống nên công tác chuyển đổi dữ liệu đã bị tạm dừng rồi ạ."},{speaker:"B",text:"そうでしたか。復旧までにどれくらい時間がかかりそうですか。",translation:"Vậy à. Dự kiến mất khoảng bao lâu để khắc phục xong?"},{speaker:"A",text:"担当部署の報告によると、本日中には再開できる見込みです。",translation:"Theo báo cáo của bộ phận phụ trách thì dự kiến trong hôm nay sẽ có thể tiến hành lại được ạ."}]},commonMistake:{wrong:"頭痛によって、今日の会議を休ませてください。",correct:"頭痛のため、今日の会議を休ませてください。",why:"「によって」chỉ nêu nguyên nhân khách quan nên vế sau không được dùng với câu biểu thị ý chí cá nhân, nhờ vả hay xin phép như「〜てください」."},note:"Khi muốn dùng cụm chỉ nguyên nhân này để bổ nghĩa trực tiếp cho một danh từ đứng sau, ta đổi sang dạng「N1 による N2」（ví dụ: 台風による被害 - thiệt hại do bão gây ra）."},{pattern:"N によって② ― 手段[しゅだん]・方法[ほうほう]",meaning:"Bằng / thông qua ~ (phương tiện, cách thức trừu tượng)",priority:"common",explanation:'Mẫu ngữ pháp này biểu thị ý nghĩa "bằng cách", "thông qua" một phương pháp hoặc phương tiện nào đó để đạt được kết quả. Khác với trợ từ 「で」thông thường, mẫu này thường đi với các danh từ chỉ cách thức mang tính trừu tượng, hệ thống hoặc có quy mô lớn (như điều tra, nghiên cứu, công nghệ...). Đây là cách diễn đạt mang sắc thái trang trọng, thường xuất hiện trong văn viết, báo cáo công việc, tin tức thời sự hoặc các bài thuyết trình.',examples:[{sentence:"アンケート調査によって、新商品に対する消費者の率直な意見を集めることができた。",translation:"Thông qua cuộc khảo sát bằng bảng câu hỏi, chúng tôi đã thu thập được những ý kiến thẳng thắn của người tiêu dùng về sản phẩm mới."},{sentence:"長年の研究と実験によって、新しいがん治療薬が開発された。",translation:"Thông qua nhiều năm nghiên cứu và thử nghiệm, một loại thuốc điều trị ung thư mới đã được phát triển."}],dialogue:{title:"Cách thu hút khách hàng",lines:[{speaker:"A",text:"今回の新商品は、SNS広告を活用することによって、若者層への認知度を高めたいと考えています。",translation:"Đối với sản phẩm mới lần này, tôi muốn nâng cao độ nhận biết trong giới trẻ bằng cách tận dụng quảng cáo trên mạng xã hội."},{speaker:"B",text:"いいアイデアですね。具体的にはどんなコンテンツを発信する予定ですか。",translation:"Ý kiến hay đấy. Cụ thể thì bạn dự định phát đi những nội dung như thế nào?"},{speaker:"A",text:"短い動画を中心にして、商品の魅力を分かりやすく伝えるつもりです。",translation:"Tôi dự định tập trung vào các video ngắn để truyền tải sức hút của sản phẩm một cách dễ hiểu."}]},commonMistake:{wrong:"私は毎日バスによって学校へ通っています。",correct:"私は毎日バスで学校へ通っています。",why:"「によって」không dùng cho các phương tiện đi lại hoặc dụng cụ sinh hoạt đời thường (như xe buýt, bút chì, đũa...), mà những trường hợp này phải dùng trợ từ「で」."},note:"Khi muốn dùng mẫu này để bổ nghĩa trực tiếp cho một danh từ đứng sau, cần chuyển thành dạng「〜による＋N」."},{pattern:"N によって③ ― 基準[きじゅん]・差異[さい] (〜によって違う)",meaning:"Tùy theo ~ (mỗi người/trường hợp khác nhau)",priority:"common",explanation:'Mẫu ngữ pháp này biểu thị ý nghĩa "tùy thuộc vào N mà sự việc có sự khác biệt hoặc thay đổi tương ứng". Vế sau thường đi kèm với các từ chỉ sự sai khác, đa dạng như 違う, 異なる, 様々だ, hoặc biến thể bổ nghĩa cho danh từ là「〜による＋N」. Mẫu câu mang sắc thái trang trọng, khách quan, được sử dụng rộng rãi từ đời sống hàng ngày, công việc cho đến văn viết và tin tức báo chí.',examples:[{sentence:"国や地域によって、挨拶の仕方やマナーが大きく異なります。",translation:"Tùy theo quốc gia và khu vực mà cách chào hỏi cũng như quy tắc ứng xử có sự khác biệt lớn."},{sentence:"同じ出来事でも、受け止め方は人によって様々です。",translation:"Dù cùng là một sự việc nhưng cách đón nhận ở mỗi người lại đa dạng khác nhau."}],dialogue:{title:"Chi phí du lịch",lines:[{speaker:"A",text:"連休に北海道へ旅行に行きたいんですが、予算はどれくらいかかりますか。",translation:"Tôi muốn đi du lịch Hokkaido vào kỳ nghỉ dài, chi phí dự tính khoảng bao nhiêu vậy?"},{speaker:"B",text:"時期や宿泊するホテルによって料金がかなり違いますよ。早めに予約したほうがいいですね。",translation:"Tùy thuộc vào thời điểm và khách sạn bạn ở mà giá cả khác nhau khá nhiều đấy. Bạn nên đặt sớm thì tốt hơn."},{speaker:"A",text:"わかりました。いくつかのプランを比べて検討してみます。",translation:"Tôi hiểu rồi. Tôi sẽ so sánh một vài gói lịch trình rồi cân nhắc xem sao."}]},commonMistake:{wrong:"人によると、幸せの定義はそれぞれ違います。",correct:"人によって、幸せの定義はそれぞれ違います。",why:'「〜によると」dùng để dẫn nguồn tin (theo như lời ai đó nói), còn để biểu thị sự khác biệt "tùy theo từng đối tượng/tiêu chuẩn" thì bắt buộc phải dùng「〜によって」.'},note:"Khi bổ nghĩa trực tiếp cho danh từ đứng sau, mẫu câu chuyển thành dạng「N1 による N2」(ví dụ: 季節による気温の変化), và có thể dùng「〜によっては」khi muốn nhấn mạnh một trường hợp cụ thể có thể xảy ra."},{pattern:"N によって④ ― 受[う]け身[み]の動作主[どうさしゅ] (組織・名人)",meaning:"Tác nhân bị động — tổ chức / danh nhân dùng によって (người cụ thể thân mật dùng に)",priority:"common",explanation:"Mẫu câu「N によって」ở dạng này được dùng để biểu thị tác nhân thực hiện hành động trong câu bị động, thường đi kèm với các động từ chỉ sự sáng tác, phát minh, xây dựng, phát hiện hoặc ban hành. Tác nhân đứng trước によって thường là một tổ chức, tập thể, quốc gia hoặc danh nhân, tác giả, nhà khoa học nổi tiếng. Mẫu ngữ pháp này mang sắc thái trang trọng, khách quan, xuất hiện phổ biến trong văn viết, báo chí, tài liệu học thuật và tin tức.",examples:[{sentence:"この有名な絵画はピカソによって描かれました。",translation:"Bức tranh nổi tiếng này đã được vẽ bởi danh họa Picasso."},{sentence:"この新薬は日本の研究チームによって開発された。",translation:"Loại thuốc mới này được phát triển bởi một nhóm nghiên cứu của Nhật Bản."}],dialogue:{title:"Tìm hiểu công trình lịch sử",lines:[{speaker:"A",text:"この歴史的な建物は誰によって設計されたのですか。",translation:"Tòa nhà mang tính lịch sử này được thiết kế bởi ai vậy ạ?"},{speaker:"B",text:"明治時代の有名な建築家によって設計されたそうですよ。",translation:"Nghe nói là được thiết kế bởi một kiến trúc sư nổi tiếng thời kỳ Meiji đấy."},{speaker:"A",text:"なるほど、だから今見てもモダンで美しいデザインなんですね。",translation:"Thì ra là vậy, thảo nào đến tận bây giờ nhìn thiết kế vẫn rất hiện đại và đẹp mắt."}]},commonMistake:{wrong:"昨日は先生によって厳しく叱られました。",correct:"昨日は先生に厳しく叱られました。",why:"Đối với hành động của cá nhân cụ thể, gần gũi trong đời sống hàng ngày (thầy cô, cha mẹ, bạn bè...) tác động trực tiếp lên người khác thì chỉ dùng trợ từ「に」chứ không dùng「によって」."},note:"Quy tắc cốt lõi cần nhớ: tác nhân cá nhân thông thường trong sinh hoạt dùng「に」, còn tác nhân là tổ chức hoặc danh nhân tạo ra phát minh, công trình, tác phẩm lớn mới dùng「によって」."}],69:[{pattern:"〜として（は）",meaning:"Với tư cách là / trong vai trò là ~",priority:"core",explanation:"Mẫu ngữ pháp này dùng để biểu thị tư cách, vai trò, lập trường của con người hoặc công dụng, mục đích của sự vật, sự việc. Đi trực tiếp sau danh từ, cấu trúc này mang ý nghĩa 'với tư cách là...', 'trong vai trò là...' hoặc 'dưới danh nghĩa là...'. Mẫu câu được sử dụng phổ biến trong cả giao tiếp đời sống lẫn các tình huống trang trọng khi muốn nhấn mạnh hành động, nghĩa vụ xuất phát từ vị thế đó.",examples:[{sentence:"彼は留学生として日本に来て、日本語学校で２年間勉強しました。",translation:"Anh ấy đã đến Nhật với tư cách là du học sinh và học tại trường tiếng Nhật trong 2 năm."},{sentence:"このお菓子はお土産として買ったので、皆さんで分けて食べてください。",translation:"Hộp bánh này tôi mua làm quà lưu niệm, nên mọi người hãy chia nhau ăn nhé."}],dialogue:{title:"Vai trò trong dự án mới",lines:[{speaker:"A",text:"山田さんは今回、リーダーとしてこのプロジェクトを担当するんですか。",translation:"Anh Yamada lần này sẽ phụ trách dự án này với tư cách là trưởng nhóm ạ?"},{speaker:"B",text:"はい、責任は重いですが、チームのために全力を尽くすつもりです。",translation:"Vâng, trách nhiệm khá nặng nề nhưng tôi sẽ nỗ lực hết mình vì cả nhóm."},{speaker:"A",text:"応援しています。私としてもできる限りのサポートをしますね。",translation:"Tôi luôn ủng hộ anh. Về phía tôi cũng sẽ hỗ trợ hết mức có thể nhé."}]},commonMistake:{wrong:"父は会社の代表にとって、式典でスピーチをしました。",correct:"父は会社の代表として、式典でスピーチをしました。",why:"Mẫu 〜にとって dùng để chỉ đối tượng tiếp nhận/đánh giá ('đối với...'), còn khi thực hiện hành động với vai trò hoặc danh nghĩa đại diện thì bắt buộc phải dùng 〜として."},note:"Khi muốn bổ nghĩa trực tiếp cho một danh từ đứng sau, mẫu này chuyển sang dạng 「〜としての ＋ Danh từ」 (ví dụ: 先生としての責任 - trách nhiệm với tư cách là một giáo viên)."},{pattern:"〜としての ＋ N",meaning:"~ với tư cách là … (bổ nghĩa danh từ — cần の)",priority:"common",explanation:'Mẫu ngữ pháp「〜としての＋N」được dùng để bổ nghĩa trực tiếp cho danh từ đứng sau, biểu đạt ý nghĩa "với tư cách, vai trò, lập trường hoặc danh nghĩa là...". Mẫu câu này thường đi kèm với các danh từ chỉ nghề nghiệp, chức vụ, tư cách xã hội hoặc thuộc tính của sự vật nhằm thể hiện thái độ, trách nhiệm, nghĩa vụ hoặc đặc trưng gắn liền với vị thế đó. Đây là cách diễn đạt mang sắc thái trang trọng, khách quan, rất phổ biến trong văn viết, báo chí và các tình huống giao tiếp công việc.',examples:[{sentence:"彼は医者としての誇りを持って、毎日患者の治療にあたっている。",translation:"Anh ấy luôn giữ niềm tự hào với tư cách là một bác sĩ và tận tụy điều trị cho bệnh nhân mỗi ngày."},{sentence:"京都は観光地としての魅力だけでなく、歴史的な価値も非常に高い。",translation:"Kyoto không chỉ có sức hút với tư cách là một điểm du lịch mà giá trị lịch sử cũng vô cùng to lớn."}],dialogue:{title:"Trách nhiệm trưởng dự án",lines:[{speaker:"A",text:"田中さん、次のプロジェクトのリーダーとしての役割をしっかり果たしてくださいね。",translation:"Anh Tanaka, hãy hoàn thành thật tốt vai trò với tư cách là trưởng dự án tiếp theo nhé."},{speaker:"B",text:"はい、プレッシャーもありますが、チームの期待に応えられるよう全力を尽くします。",translation:"Vâng, tuy có chút áp lực nhưng tôi sẽ nỗ lực hết mình để đáp ứng kỳ vọng của cả nhóm."},{speaker:"A",text:"応援していますよ。困ったことがあればいつでも相談してください。",translation:"Tôi luôn ủng hộ anh. Nếu có khó khăn gì cứ trao đổi với tôi bất cứ lúc nào nhé."}]},commonMistake:{wrong:"彼には先輩として自覚がまだ足りないようだ。",correct:"彼には先輩としての自覚がまだ足りないようだ。",why:"Khi muốn bổ nghĩa trực tiếp cho một danh từ (ở đây là「自覚」- ý thức/tự giác), bắt buộc phải có trợ từ「の」thành dạng「〜としての」chứ không được dùng trực tiếp「〜として」."},note:"Phân biệt với「〜として」:「〜として」đóng vai trò như trạng từ bổ nghĩa cho động từ/vị ngữ phía sau, còn khi đứng trực tiếp trước danh từ để làm định ngữ thì bắt buộc phải đổi sang「〜としての」."},{pattern:"〜にとって（は）",meaning:"Đối với ~ thì / theo lập trường của ~ (đánh giá chủ quan)",priority:"common",explanation:'Mẫu câu này đi sau danh từ chỉ người hoặc tổ chức để diễn đạt ý nghĩa "đối với / xét từ góc độ, lập trường của ai đó mà nói". Vế sau của câu luôn là những từ ngữ biểu thị sự đánh giá, phán đoán chủ quan hoặc cảm nhận về mức độ (như quan trọng, khó khăn, cần thiết...). Ngữ pháp này được dùng phổ biến cả trong văn nói và văn viết khi muốn nêu bật giá trị hay ảnh hưởng của một sự việc đối với chủ thể. Lưu ý rằng vế sau không đi cùng các động từ chỉ hành vi trực tiếp hướng vào đối tượng.',examples:[{sentence:"忙しい現代人にとって、十分な睡眠を取ることは何よりも大切です。",translation:"Đối với người hiện đại bận rộn, việc ngủ đủ giấc là điều quan trọng hơn bất cứ thứ gì."},{sentence:"漢字圏以外の国の学習者にとって、漢字を覚えるのは非常に難しい。",translation:"Đối với người học đến từ các quốc gia không dùng chữ Hán, việc ghi nhớ chữ Hán là vô cùng khó khăn."}],dialogue:{title:"Chọn mua điện thoại mới",lines:[{speaker:"A",text:"新しいスマホを買いたいんだけど、どれがいいと思う？",translation:"Tôi muốn mua điện thoại thông minh mới, bạn thấy chiếc nào tốt?"},{speaker:"B",text:"写真をよく撮るあなたにとっては、カメラの性能がいいこのモデルが一番おすすめだよ。",translation:"Đối với người hay chụp ảnh như bạn thì mẫu máy có hiệu năng camera tốt này là đáng mua nhất đấy."},{speaker:"A",text:"なるほどね！デザインも気に入ったし、これにするよ。",translation:"Ra là vậy! Tôi cũng thích thiết kế của nó nữa, tôi sẽ chọn cái này."}]},commonMistake:{wrong:"先生にとって、いつも丁寧に挨拶をしなければならない。",correct:"先生に対して、いつも丁寧に挨拶をしなければならない。",why:"「〜にとって」 chỉ đi với vế sau là câu phán đoán/đánh giá chủ quan (khó, dễ, quan trọng...), còn khi biểu thị hành động hoặc thái độ hướng đến đối tượng thì phải dùng 「〜に対して」."},note:"Cần phân biệt 「〜にとって」 (đứng trên góc độ ai đó để đưa ra đánh giá, vế sau không dùng động từ hành động) với 「〜に対して」 (hướng hành vi/thái độ tới đối tượng) và 「〜として」 (với tư cách, vai trò)."},{pattern:"〜にとっての ＋ N",meaning:"… đối với ~ (bổ nghĩa danh từ — bắt buộc の)",priority:"common",explanation:"Mẫu 「〜にとっての＋N」 dùng để bổ nghĩa trực tiếp cho danh từ đứng sau, biểu thị ý nghĩa hoặc giá trị của sự vật, sự việc từ lập trường và góc nhìn của đối tượng được nhắc đến. Mẫu câu thường mang sắc thái nhận định, đánh giá chủ quan của người nói hoặc chủ thể (như xem cái gì đó là quan trọng, là cơ hội, là thử thách...). Danh từ đứng sau thường là các từ chỉ giá trị, mục tiêu, thử thách như 存在, チャンス, 試練, 目標, 課題. Khi đứng liền trước danh từ để làm định ngữ, bắt buộc phải có trợ từ 「の」.",examples:[{sentence:"この大会での優勝は、彼らにとっての最大の目標です。",translation:"Việc vô địch ở giải đấu này là mục tiêu lớn nhất đối với họ."},{sentence:"海外生活は、私にとっての大きな挑戦でした。",translation:"Cuộc sống ở nước ngoài từng là một thử thách lớn đối với tôi."}],dialogue:{title:"Ước mơ khi sang Nhật",lines:[{speaker:"A",text:"JLPTのN1合格は、リンさんにとっての夢ですか。",translation:"Đỗ N1 JLPT là ước mơ lớn đối với Linh phải không?"},{speaker:"B",text:"はい、日本で働くための第一歩なんです。",translation:"Vâng, đó là bước đầu tiên để em có thể làm việc tại Nhật Bản ạ."},{speaker:"A",text:"とても素敵ですね。ぜひ最後まで頑張ってください。",translation:"Tuyệt vời quá. Bạn nhất định hãy cố gắng đến cùng nhé."}]},commonMistake:{wrong:"スマートフォンは現代人にとって必需品です。",correct:"スマートフォンは現代人にとっての必需品です。",why:"Khi cụm 「〜にとって」 bổ nghĩa trực tiếp cho danh từ đứng ngay sau (必需品) thì bắt buộc phải thêm 「の」 thành 「〜にとっての」."},note:"Tránh nhầm với 「〜に対しての＋N」 vốn dùng để chỉ đối tượng tiếp nhận hành vi hoặc thái độ, còn 「〜にとっての＋N」 chỉ đánh giá, quan điểm từ lập trường của chủ thể."}],70:[{pattern:"〜に対[たい]して",meaning:"Đối với (hướng đến đối tượng) / Trái lại (tương phản A対B)",priority:"core",explanation:'Mẫu ngữ pháp 「〜に対して」 dùng để chỉ đối tượng tiếp nhận hành động, thái độ hoặc cảm xúc (mang nghĩa "đối với"), hoặc dùng để nêu bật sự tương phản, đối lập rõ rệt giữa hai chủ thể (mang nghĩa "trái ngược với"). Khi bổ nghĩa trực tiếp cho một danh từ đứng sau, cấu trúc sẽ chuyển thành dạng 「〜に対する + N」. Mẫu này thường mang sắc thái trang trọng, khách quan, được sử dụng phổ biến trong văn viết, báo chí cũng như giao tiếp lịch sự.',examples:[{sentence:"店員はお客様に対して、常に丁寧な言葉遣いで対応しなければならない。",translation:"Nhân viên bán hàng phải luôn ứng xử bằng lời lẽ lịch sự đối với khách hàng."},{sentence:"兄が無口で大人しいのに対して、弟は明るくてとてもおしゃべりだ。",translation:"Trái ngược với người anh ít nói và trầm tính, người em trai lại rất hoạt bát và hay nói."}],dialogue:{title:"Ý kiến với cấp trên",lines:[{speaker:"A",text:"田中さんは上司に対しても、はっきりと自分の意見を言いますね。",translation:"Anh Tanaka ngay cả đối với cấp trên cũng thẳng thắn nói ra ý kiến của mình nhỉ."},{speaker:"B",text:"ええ、でも礼儀正しいので、失礼な印象は全く与えませんよ。",translation:"Vâng, nhưng vì anh ấy rất đúng mực nên hoàn toàn không gây cảm giác thất lễ đâu."},{speaker:"A",text:"確かに、相手に対する敬意がしっかり伝わってきますね。",translation:"Công nhận, sự tôn trọng đối với đối phương được thể hiện rất rõ ràng nhỉ."}]},commonMistake:{wrong:"私に対して、家族は何よりも大切な存在です。",correct:"私にとって、家族は何よりも大切な存在です。",why:'Khi muốn diễn đạt ý "đối với tôi" để đưa ra đánh giá, nhận xét từ lập trường bản thân thì phải dùng 「〜にとって」, còn 「〜に対して」 chỉ dùng khi có hành động, thái độ cụ thể hướng vào đối tượng.'},note:"Cần phân biệt rõ 「〜に対して」 (thái độ, hành động hướng tới đối tượng hoặc so sánh đối lập) với 「〜について」 (nói/nghĩ về chủ đề) và 「〜にとって」 (đánh giá theo góc nhìn của một đối tượng)."},{pattern:"〜に対[たい]する ＋ N",meaning:"Dạng liên thể (bổ nghĩa danh từ) của に対して",priority:"common",explanation:'Mẫu 「〜に対する＋N」 mang ý nghĩa "đối với...", "hướng về...", đóng vai trò là dạng liên thể bổ nghĩa trực tiếp cho danh từ đứng sau. Mẫu câu này dùng để diễn tả thái độ, hành vi, cảm xúc hoặc sự quan tâm hướng đến một đối tượng, sự việc cụ thể. Đây là ngữ pháp mang sắc thái trang trọng, thường xuất hiện nhiều trong văn viết, báo chí, tài liệu học thuật hoặc bối cảnh công việc chuyên nghiệp.',examples:[{sentence:"お客様[きゃくさま]からの ご意見[いけん]に 対[たい]する 返答[へんとう]を メールで 送[おく]りました。",translation:"Tôi đã gửi email phản hồi đối với ý kiến đóng góp từ khách hàng."},{sentence:"環境問題[かんきょうもんだい]に 対[たい]する 若者[わかもの]の 関心[かんしん]が 高[たか]まっています。",translation:"Sự quan tâm của giới trẻ đối với vấn đề môi trường đang ngày càng tăng cao."}],dialogue:{title:"Phản hồi về sản phẩm mới",lines:[{speaker:"A",text:"新商品[しんしょうひん]に 対[たい]する お客様[きゃくさま]の 反応[はんのう]は どうでしたか。",translation:"Phản ứng của khách hàng đối với sản phẩm mới như thế nào?"},{speaker:"B",text:"デザインは 好評[こうひょう]ですが、価格[かかく]が 高[たか]いという 意見[いけん]が 多[おお]かったです。",translation:"Thiết kế thì được đánh giá cao, nhưng có nhiều ý kiến cho rằng giá thành đắt."},{speaker:"A",text:"価格設定[かかくせってい]に 対[たい]する 不満[ふまん]を 解消[かいしょう]するために、改善案[かいぜんあん]を 検討[けんとう]しましょう。",translation:"Chúng ta hãy cùng xem xét phương án cải thiện để giải tỏa sự bất mãn đối với mức giá nhé."}]},commonMistake:{wrong:"店員[てんいん]の お客様[きゃくさま]に 対[たい]して 態度[たいど]が とても 丁寧[ていねい]でした。",correct:"店員[てんいん]の お客様[きゃくさま]に 対[たい]する 態度[たいど]が とても 丁寧[ていねい]でした。",why:"Khi đứng trước để bổ nghĩa trực tiếp cho danh từ (như 態度) thì bắt buộc phải chia về dạng liên thể 「に対する」, không được dùng 「に対して」 vì dạng này chỉ dùng để bổ nghĩa cho động từ hoặc vị ngữ."},note:"Cần phân biệt với 「〜についての＋N」: 「〜に対する」 nhấn mạnh vào hành động, thái độ hoặc phản ứng có tính định hướng tới một đối tượng đích, trong khi 「〜についての」 chỉ đơn thuần biểu thị nội dung, chủ đề của sự việc."},{pattern:"〜に比[くら]べて",meaning:"So với … (so sánh mức độ hơn kém, dùng tiêu chuẩn tham chiếu)",priority:"common",explanation:"Mẫu 「〜に比べて」（hoặc 「〜に比べ」）được dùng để lấy một đối tượng làm tiêu chuẩn đối chiếu, so sánh nhằm làm nổi bật mức độ hơn kém hoặc sự khác biệt. Cấu trúc kết nối trực tiếp với Danh từ hoặc Mệnh đề danh từ hóa (V/A thông thường + の), vế sau thường đi kèm với những từ ngữ biểu thị sự chênh lệch rõ rệt. Mẫu câu này mang tính nhận xét khách quan, được sử dụng phổ biến trong cả hội thoại thường ngày lẫn các bài báo cáo, văn viết trang trọng.",examples:[{sentence:"兄に比べて、弟のほうが社交的で友達を作るのが得意だ。",translation:"So với người anh, người em có tính cách cởi mở và giỏi kết bạn hơn."},{sentence:"紙の本に比べて、電子書籍は持ち運びが便利で場所を取らない。",translation:"So với sách giấy, sách điện tử tiện lợi khi mang theo và không chiếm diện tích."}],dialogue:{title:"Chọn mua máy tính mới",lines:[{speaker:"A",text:"新しいパソコン、前のに比べて軽くて持ち運びやすいね。",translation:"Chiếc máy tính mới này nhẹ và dễ mang theo hơn hẳn so với chiếc cũ nhỉ."},{speaker:"B",text:"うん、バッテリーの持ちもずっと良くなったよ。",translation:"Ừ, thời lượng pin cũng tốt hơn rất nhiều nữa đấy."},{speaker:"A",text:"デザインもおしゃれだし、買い替えて本当によかったね。",translation:"Thiết kế cũng thời trang nữa, đổi máy mới thật là sáng suốt."}]},commonMistake:{wrong:"車で行くに比べて、電車で行くほうが時間がかかりません。",correct:"車で行くのに比べて、電車で行くほうが時間がかかりません。",why:"Khi đi kèm với mệnh đề động từ, bắt buộc phải danh từ hóa bằng 「〜のに比べて」 chứ không được ghép trực tiếp động từ thể từ điển với 「に比べて」."},note:"Ngoài 「〜に比べて」 còn có dạng văn viết trang trọng là 「〜に比べ」, hoặc biến thể 「〜と比べて」 với ý nghĩa so sánh tương đương."}],71:[{pattern:"〜次第[しだい]",meaning:"Ngay khi ~ (ý chí, văn viết — vế sau là hành động có chủ ý)",priority:"core",explanation:"Mẫu ngữ pháp 「〜次第」 diễn tả ý nghĩa ngay sau khi một sự việc hoặc hành động phía trước kết thúc thì sẽ lập tức thực hiện hành động tiếp theo. Cấu trúc này đi với động từ thể Masu bỏ ます (V-stem ＋ 次第), mang sắc thái trang trọng và lịch sự, thường được sử dụng phổ biến trong văn viết, email thương mại hoặc giao tiếp công việc. Vế sau luôn là hành động có chủ ý, mang tính tương lai và thường đi kèm với các biểu hiện ý chí, dự định hoặc yêu cầu, nhờ vả.",examples:[{sentence:"詳しい日程が決まり次第、改めてメールにてご連絡いたします。",translation:"Ngay khi lịch trình cụ thể được quyết định, chúng tôi sẽ liên lạc lại qua email."},{sentence:"準備が整い次第、順番にご案内いたしますので、もう少々お待ちください。",translation:"Ngay sau khi chuẩn bị xong, chúng tôi sẽ hướng dẫn theo thứ tự nên xin quý khách vui lòng đợi thêm một chút."}],dialogue:{title:"Báo cáo tiến độ tài liệu",lines:[{speaker:"A",text:"部長、先ほどご指示いただいた企画書の修正が終わり次第、確認をお願いしてもよろしいでしょうか。",translation:"Trưởng phòng, ngay sau khi sửa xong bản kế hoạch như anh vừa chỉ đạo, em nhờ anh kiểm tra giúp được không ạ?"},{speaker:"B",text:"分かりました。できたら私のデスクに持ってきてください。",translation:"Tôi hiểu rồi. Làm xong thì mang lại bàn làm việc cho tôi nhé."},{speaker:"A",text:"承知いたしました。すぐに仕上げます。",translation:"Vâng, em rõ rồi ạ. Em sẽ hoàn thiện ngay."}]},commonMistake:{wrong:"会議の資料ができ次第、課長に見せました。",correct:"会議の資料ができ次第、課長にお見せします。",why:"Mẫu 「〜次第」 chỉ dùng cho hành động có chủ ý hướng tới tương lai, tuyệt đối không dùng cho sự việc đã hoàn thành trong quá khứ (vế sau không chia thể 〜た)."},note:"Cần tránh nhầm lẫn mẫu này với 「N ＋ 次第だ／次第で」(tùy thuộc vào N) hoặc 「〜次第です」(dùng ở cuối câu để trình bày lý do, sự tình trong thương mại)."},{pattern:"〜か〜ないかのうちに",meaning:"Chưa kịp … đã … (hai sự kiện gần như đồng thời, thường bất ngờ)",priority:"common",explanation:"Mẫu câu này dùng để diễn đạt ý 'vừa mới... thì đã...' hoặc 'chưa kịp... thì đã...', thể hiện hai sự việc diễn ra gần như đồng thời. Cấu trúc này nhấn mạnh khoảng cách thời gian giữa hai hành động cực kỳ ngắn, tạo cảm giác hành động trước còn chưa hoàn tất hẳn thì hành động sau đã lập tức xảy đến. Mẫu câu thường mang sắc thái bất ngờ, thường dùng cho các sự thật khách quan trong quá khứ và không dùng vế sau để thể hiện ý chí, mệnh lệnh hay rủ rê của người nói.",examples:[{sentence:"今朝は家を出るか出ないかのうちに、激しい雨が急に降り出しました。",translation:"Sáng nay tôi vừa bước chân ra khỏi nhà thì cơn mưa lớn đã bất ngờ đổ ập xuống."},{sentence:"終業のチャイムが鳴るか鳴らないかのうちに、生徒たちは一斉に教室を飛び出して行った。",translation:"Chuông báo tan học vừa mới reo thì các em học sinh đã đồng loạt lao ra khỏi lớp học."}],dialogue:{title:"Sau cuộc họp",lines:[{speaker:"A",text:"佐藤さん、会議が終わるか終わらないかのうちに席を立ってどこかへ行っちゃったね。",translation:"Anh Sato cuộc họp vừa mới kết thúc là đã vội đứng dậy rời đi đâu mất rồi nhỉ."},{speaker:"B",text:"あ、次のクライアントとの約束に遅れそうだったみたいですよ。",translation:"À, nghe đâu anh ấy sắp trễ hẹn với khách hàng tiếp theo đấy."},{speaker:"A",text:"なるほど、それでそんなに慌てていたんですね。",translation:"Ra là vậy, hèn chi anh ấy lại vội vàng đến thế."}]},commonMistake:{wrong:"授業が終わるか終わらないかのうちに、一緒に学食へ行きましょう。",correct:"授業が終わったら、一緒に学食へ行きましょう。",why:"Vế sau của mẫu「〜か〜ないかのうちに」chỉ dùng để trần thuật sự việc thực tế khách quan, tuyệt đối không dùng với các câu thể hiện ý chí, rủ rê (〜ましょう) hay mệnh lệnh."},note:"So với「〜たとたん」, mẫu「〜か〜ないかのうちに」tạo cảm giác hành động trước thậm chí còn chưa kịp kết thúc trọn vẹn thì hành động sau đã ập tới."},{pattern:"次第[しだい] ≠ とたん（に）",meaning:"次第 = ý chí/thông báo (vế sau chủ động); とたん = bất ngờ đã xảy ra (quá khứ/ngoài dự kiến)",priority:"common",explanation:'「次第」và「とたん（に）」đều mang nghĩa "ngay sau khi", nhưng khác biệt rõ rệt về sắc thái và cấu trúc vế sau.「〜次第」(V bỏ masu) dùng trong văn phong trang trọng hoặc công việc để thông báo, hứa hẹn một hành động có chủ ý sẽ làm ngay khi sự việc trước hoàn tất. Ngược lại,「〜たとたん（に）」(V-ta) dùng để diễn tả một sự việc bất ngờ, ngoài ý muốn xảy ra ngay sau hành động phía trước và vế sau tuyệt đối không mang tính ý chí hay yêu cầu.',examples:[{sentence:"詳しい日程が決まり次第、改めてメールでお知らせいたします。",translation:"Ngay khi lịch trình chi tiết được quyết định, tôi sẽ thông báo lại qua email."},{sentence:"疲れていたので、ベッドに横になったとたんに眠ってしまった。",translation:"Vì mệt quá nên vừa ngả lưng xuống giường là tôi đã ngủ thiếp đi ngay lập tức."}],dialogue:{title:"Giao nhận tài liệu họp",lines:[{speaker:"A",text:"部長、会議の資料を修正したのですが、ご確認いただけますか。",translation:"Thưa trưởng phòng, tôi đã sửa tài liệu cuộc họp rồi, trưởng phòng xem qua giúp tôi được không ạ?"},{speaker:"B",text:"分かった。印刷ができ次第、私のデスクに持ってきてくれ。",translation:"Được rồi. Ngay khi in xong thì mang sang bàn làm việc cho tôi nhé."},{speaker:"A",text:"承知いたしました。すぐに準備いたします。",translation:"Tôi hiểu rồi ạ. Tôi sẽ chuẩn bị ngay."}]},commonMistake:{wrong:"駅に着いたとたんに、私に電話してください。",correct:"駅に着き次第、私に電話してください。",why:"「〜とたん（に）」không bao giờ đi với câu nhờ vả, mệnh lệnh hoặc ý chí trong tương lai; trường hợp này bắt buộc dùng「〜次第」hoặc「〜たら」."},note:"「次第」chỉ dùng cho sự việc trong tương lai chưa xảy ra (cuối câu không chia thể quá khứ), trong khi「とたんに」thường kết thúc ở thì quá khứ để thuật lại một diễn biến bất ngờ."},{pattern:"次第[しだい]の接続[せつぞく]と制限[せいげん]",meaning:"Chỉ nối V-ます-stem; vế sau KHÔNG được dùng quá khứ (〜した ✗) hay mệnh lệnh thô lỗ",priority:"common",explanation:'Mẫu ngữ pháp「〜次第」mang ý nghĩa "ngay sau khi một việc kết thúc thì sẽ lập tức thực hiện hành động tiếp theo", thường dùng trong văn viết trang trọng, thư từ thương mại hoặc giao tiếp công việc. Cấu trúc này chỉ đi trực tiếp với động từ thể Masu bỏ ます (V-stem + 次第), tuyệt đối không kết hợp với thể từ điển hay thể quá khứ. Điểm hạn chế quan trọng nhất là vế sau chỉ được thể hiện ý chí, dự định hoặc yêu cầu lịch sự hướng tới tương lai, hoàn toàn không được dùng ở thì quá khứ (〜た) hay câu mệnh lệnh thô lỗ.',examples:[{sentence:"資料の準備ができ次第、メールにてお送りいたします。",translation:"Ngay sau khi tài liệu được chuẩn bị xong, tôi sẽ gửi qua email cho quý khách."},{sentence:"飛行機の到着時間が分かり次第、空港までお迎えに上がります。",translation:"Ngay khi biết được giờ máy bay hạ cánh, tôi sẽ đến sân bay để đón quý khách."}],dialogue:{title:"Trao đổi lịch họp",lines:[{speaker:"A",text:"部長、明日の打ち合わせの会場はもう決まりましたか。",translation:"Thưa trưởng phòng, địa điểm họp ngày mai đã quyết định xong chưa ạ?"},{speaker:"B",text:"今、総務部に確認しているところだから、分かり次第すぐに連絡するよ。",translation:"Tôi đang nhờ phòng tổng vụ kiểm tra, ngay khi biết rõ tôi sẽ liên lạc lại cho cậu ngay nhé."},{speaker:"A",text:"承知いたしました。それではご連絡をお待ちしております。",translation:"Vâng tôi đã rõ. Vậy tôi xin phép chờ liên lạc từ trưởng phòng ạ."}]},commonMistake:{wrong:"会場に到着し次第、すぐに担当者に連絡しました。",correct:"会場に到着してすぐに、担当者に連絡しました。",why:"Vế sau của「〜次第」tuyệt đối không dùng thì quá khứ (〜ました/〜た); nếu muốn diễn tả hành động đã xảy ra trong quá khứ thì phải dùng「〜てすぐ」hoặc「〜た後すぐに」."},note:"Khác với「〜たとたん」hay「〜やいなや」(chuyên dùng để thuật lại sự việc bất ngờ đã hoàn thành trong quá khứ),「〜次第」chỉ dùng cho hành động hướng tới tương lai với sắc thái trang trọng, lịch sự."}],72:[{pattern:"〜際[さい]（に）",meaning:"Vào lúc/dịp ~ (trang trọng — thông báo, lễ nghi, email công sở)",priority:"core",explanation:'Mẫu ngữ pháp 「〜際（に）」 có nghĩa là "vào lúc / khi / nhân dịp", biểu thị thời điểm diễn ra một sự kiện hoặc hành động cụ thể. Cấu trúc này mang sắc thái trang trọng, lịch sự hơn nhiều so với 「〜とき」, thường được sử dụng trong văn bản hành chính, thông báo chính thức, hợp đồng hoặc email công sở. Vế sau thường đi kèm với những lời chỉ dẫn, yêu cầu, lưu ý hoặc hành động có chủ ý hướng đến đối tác hay khách hàng.',examples:[{sentence:"パスポートを更新する際は、こちらの申請書と顔写真をご提出ください。",translation:"Khi làm thủ tục đổi hộ chiếu, xin vui lòng nộp đơn xin này cùng với ảnh thẻ."},{sentence:"先日のセミナーにご参加いただいた際にお配りした資料を、メールでもお送りいたします。",translation:"Tôi xin phép gửi qua email tài liệu đã phát vào dịp quý khách tham dự buổi hội thảo hôm trước."}],dialogue:{title:"Hướng dẫn thủ tục phỏng vấn",lines:[{speaker:"A",text:"面接にお越しいただく際は、受付にてお名前と担当者名をお伝えください。",translation:"Khi đến tham gia phỏng vấn, quý khách vui lòng thông báo tên của mình và tên người phụ trách tại quầy lễ tân."},{speaker:"B",text:"承知いたしました。履歴書は受付で提出したほうがよろしいでしょうか。",translation:"Tôi hiểu rồi. Tôi có nên nộp sơ yếu lý lịch ngay tại quầy lễ tân không?"},{speaker:"A",text:"いいえ、面接室にお入りになった後、直接面接官にお渡しください。",translation:"Dạ không, sau khi vào phòng phỏng vấn, xin quý khách hãy nộp trực tiếp cho người phỏng vấn."}]},commonMistake:{wrong:"毎朝、起きた際に必ずコップ一杯の水を飲むようにしています。",correct:"毎朝、起きたときに必ずコップ一杯の水を飲むようにしています。",why:"「〜際（に）」 mang sắc thái trang trọng nên không dùng cho các thói quen hay hành động sinh hoạt đời thường hàng ngày."},note:"So với 「〜とき」 dùng phổ thông, 「〜際（に）」 chỉ dùng trong văn cảnh trang trọng/công việc và hầu như không kết hợp trực tiếp với tính từ để chỉ trạng thái cảm xúc, tính chất thông thường."},{pattern:"〜にあたって（にあたり）",meaning:"Nhân dịp quan trọng ~ sắp bắt đầu (khai trương, nhậm chức, khởi động dự án)",priority:"common",explanation:'Mẫu ngữ pháp này có nghĩa là "nhân dịp / vào thời điểm", dùng khi chuẩn bị bước vào một sự kiện quan trọng, mang tính bước ngoặt hoặc trang trọng (như khai trương, kết hôn, khởi động dự án). Vế sau thường thể hiện sự chuẩn bị, lời chào hỏi, cảm ơn, quyết tâm hoặc những việc cần chú ý trước khi bắt đầu. Đây là cách nói trang trọng, thường dùng trong các bài phát biểu, thông báo chính thức hoặc văn phong kinh doanh.',examples:[{sentence:"新しい店舗のオープンにあたって、スタッフ全員で接客マナーの研修を行いました。",translation:"Nhân dịp khai trương cửa hàng mới, toàn thể nhân viên đã cùng nhau tham gia buổi đào tạo về văn hóa phục vụ khách hàng."},{sentence:"新規プロジェクトの立ち上げにあたって、綿密な市場調査を実施する必要があります。",translation:"Trước khi khởi động dự án mới, chúng ta cần phải tiến hành khảo sát thị trường một cách kỹ lưỡng."}],dialogue:{title:"Mở chi nhánh mới",lines:[{speaker:"A",text:"来月、大阪に新支社を開設するにあたって、何か特別な準備は進めていますか。",translation:"Nhân dịp mở chi nhánh mới tại Osaka vào tháng tới, anh đã chuẩn bị những gì đặc biệt chưa?"},{speaker:"B",text:"はい、現地スタッフの採用と事務所の契約はすでに完了いたしました。",translation:"Vâng, việc tuyển dụng nhân viên bản địa và ký hợp đồng thuê văn phòng đều đã hoàn tất rồi ạ."},{speaker:"A",text:"順調ですね。万全の態勢で初日を迎えられるよう期待しています。",translation:"Thuận lợi quá nhỉ. Mong rằng chi nhánh sẽ đón ngày khai trương với sự chuẩn bị tốt nhất."}]},commonMistake:{wrong:"スーパーへ買い物に行くにあたって、エコバッグを持っていきました。",correct:"スーパーへ買い物に行く際（に）、エコバッグを持っていきました。",why:"「〜にあたって」chỉ dùng cho những sự kiện trọng đại, có tính chất chuẩn bị bước ngoặt chứ không dùng cho các hành động sinh hoạt thường ngày."},note:"Mẫu này luôn hướng về các sự kiện tích cực trong tương lai có chủ đích, tuyệt đối không dùng cho các sự kiện tiêu cực (tai nạn, hỏng hóc, chia tay) hay những sự việc xảy ra bất ngờ."},{pattern:"際[さい]に ≠ とき（文体[ぶんたい]の使[つか]い分[わ]け）",meaning:"Phân biệt văn phong: 際に = trang trọng (văn bản, thông báo, lễ); とき = trung tính (nói/viết thường)",priority:"common",explanation:'Cả「〜際に」và「〜とき」đều có nghĩa là "khi / vào lúc", dùng để xác định thời điểm diễn ra hành động hoặc sự việc. Điểm khác biệt mấu chốt nằm ở văn phong:「〜際に」rất trang trọng, chủ yếu dùng trong thông báo, văn bản hướng dẫn, thư từ thương mại hoặc nghi lễ chính thức. Ngược lại,「〜とき」là từ mang sắc thái trung tính, được dùng phổ biến trong giao tiếp hàng ngày cũng như các văn bản miêu tả thông thường.',examples:[{sentence:"パスワードを変更される際には、ご登録のメールアドレスに確認コードをお送りいたします。",translation:"Khi quý khách thay đổi mật khẩu, chúng tôi sẽ gửi mã xác nhận về địa chỉ email đã đăng ký."},{sentence:"子どものときは、よく近くの公園で日が暮れるまでサッカーをしていたものだ。",translation:"Hồi còn nhỏ (khi còn bé), tôi thường chơi bóng đá ở công viên gần nhà cho đến tận lúc trời tối."}],dialogue:{title:"Hướng dẫn làm thủ tục",lines:[{speaker:"A",text:"すみません、この書類を提出するときに、身分証明書も一緒に見せる必要がありますか。",translation:"Xin lỗi, khi tôi nộp giấy tờ này thì có cần xuất trình cùng với giấy tờ tùy thân không ạ?"},{speaker:"B",text:"はい、ご申請の際には、運転免許証などのご本人確認書類をご提示いただいております。",translation:"Vâng, khi quý khách nộp đơn đăng ký, xin vui lòng xuất trình giấy tờ xác nhận danh tính như bằng lái xe ạ."},{speaker:"A",text:"分かりました。今からコピーを用意して持ってきますね。",translation:"Tôi hiểu rồi. Tôi sẽ chuẩn bị bản photo rồi mang lại ngay."}]},commonMistake:{wrong:"毎朝起きた際には、まずコップ一杯の白湯を飲むことにしている。",correct:"毎朝起きたときは、まずコップ一杯の白湯を飲むことにしている。",why:"「〜際に」mang sắc thái trang trọng nên không dùng cho các thói quen sinh hoạt vụn vặt thường nhật của cá nhân."},note:"「〜際に」chỉ kết hợp với danh từ hành động (Nの際) hoặc động từ, trong khi「〜とき」kết hợp linh hoạt được với cả tính từ (い/な) và danh từ chỉ mốc thời gian."},{pattern:"際[さい]に ≠ にあたって（目的[もくてき]の重[おも]さ）",meaning:"Phân biệt mức độ quan trọng: にあたって = nhân dịp trọng đại Ý CHÍ (1 lần); 際に = dịp/lần thông thường (có thể lặp lại)",priority:"common",explanation:'「にあたって」được dùng khi đứng trước một sự kiện trọng đại, mang tính bước ngoặt hoặc cột mốc quan trọng (như thành lập công ty, kết hôn, khởi động dự án lớn), thể hiện sự chuẩn bị và ý chí, quyết tâm của người nói. Ngược lại,「際に」chỉ đơn thuần mang nghĩa "khi / vào lúc / nhân dịp" ở mức độ trang trọng, dùng cho các tình huống thủ tục, thông báo hoặc sự việc có thể lặp đi lặp lại thường nhật. Do đó, những hành động mang tính quy trình hàng ngày không thể dùng「にあたって」mà phải dùng「際に」.',examples:[{sentence:"パスポートを更新する際には、こちらの窓口に申請書と写真をご提出ください。",translation:"Khi làm thủ tục đổi hộ chiếu, xin vui lòng nộp đơn đăng ký và ảnh tại quầy này."},{sentence:"新会社の設立にあたって、これまでの経験を生かし全力を尽くす所存です。",translation:"Nhân dịp thành lập công ty mới, tôi xin hứa sẽ vận dụng toàn bộ kinh nghiệm đã có và nỗ lực hết mình."}],dialogue:{title:"Chuẩn bị ký hợp đồng",lines:[{speaker:"A",text:"明日の新事業提携の調印式に臨むにあたって、何か留意すべき点はありますか。",translation:"Trước khi bước vào buổi lễ ký kết hợp tác dự án mới ngày mai, có điểm nào cần lưu ý không ạ?"},{speaker:"B",text:"契約書にサインをする際には、特約事項の項目をもう一度慎重にご確認ください。",translation:"Khi ký tên vào văn bản hợp đồng, anh hãy kiểm tra lại thật cẩn thận các điều khoản đặc biệt nhé."},{speaker:"A",text:"承知いたしました。万全の準備をして臨みます。",translation:"Tôi hiểu rồi. Tôi sẽ chuẩn bị thật chu đáo để tham dự."}]},commonMistake:{wrong:"エレベーターを降りるにあたって、足元にご注意ください。",correct:"エレベーターを降りる際には、足元にご注意ください。",why:'Việc "bước ra khỏi thang máy" là hành động thường nhật lặp đi lặp lại, không mang tính chất sự kiện trọng đại hay bước ngoặt cuộc đời, nên phải dùng「際に」chứ không thể dùng「にあたって」.'},note:"「にあたって」thường đi với các động từ chỉ sự chuẩn bị hoặc biểu đạt quyết tâm, hướng đến tương lai tích cực, trong khi「際に」trung tính và có thể dùng cho cả trường hợp cảnh báo hay tình huống khẩn cấp."}],73:[{pattern:"〜最中[さいちゅう]に",meaning:"Đúng đỉnh điểm đang làm ~ thì bị gián đoạn",priority:"core",explanation:'Mẫu câu「〜最中に」diễn tả ý nghĩa "đúng vào lúc đang ở đỉnh điểm hoặc cao trào của một hành động thì có một sự việc bất ngờ khác xen vào làm gián đoạn". Cấu trúc này đi với「V-ている」hoặc danh từ chỉ hành động「N の」để nhấn mạnh khoảnh khắc đang thực hiện hành vi. Vế sau luôn là một sự việc xảy ra ngoài ý muốn gây cản trở hoặc ngắt quãng, tuyệt đối không dùng cho hành động có chủ ý hay nguyện vọng của người nói.',examples:[{sentence:"大切なプレゼンテーションをしている最中に、突然パソコンがフリーズしてしまった。",translation:"Đúng lúc tôi đang thuyết trình bài quan trọng thì máy tính đột nhiên bị đơ."},{sentence:"試験の最中に激しい腹痛に襲われ、途中で保健室へ行くことになった。",translation:"Đúng lúc đang làm bài thi thì tôi bị một cơn đau bụng dữ dội hành hạ, đành phải xuống phòng y tế giữa chừng."}],dialogue:{title:"Cuộc gọi bị ngắt quãng",lines:[{speaker:"A",text:"さっき電話が急に切れちゃったけど、何かあったの？",translation:"Hồi nãy điện thoại tự nhiên bị ngắt, có chuyện gì thế?"},{speaker:"B",text:"ごめん！課長と大事な話をしている最中に、スマホのバッテリーが切れちゃったんだ。",translation:"Xin lỗi nhé! Đúng lúc tớ đang nói chuyện quan trọng với trưởng phòng thì điện thoại lại hết sạch pin."},{speaker:"A",text:"そうだったんだ。電波が悪くなったのかと思ったよ。",translation:"Ra là vậy. Tớ cứ tưởng là do sóng yếu cơ."}]},commonMistake:{wrong:"日本に留学している最中に、富士山に登りたいです。",correct:"日本に留学している間に、富士山に登りたいです。",why:"「〜最中に」chỉ dùng khi có sự việc bất ngờ làm gián đoạn hành động đang ở cao trào, không dùng để diễn tả ý định hay nguyện vọng có chủ đích trong một khoảng thời gian dài (trường hợp này phải dùng「〜間に」)."},note:"Khác với「〜間に」có thể đi với hành động có chủ ý ở vế sau, vế sau của「〜最中に」hầu như luôn là một sự cố bất ngờ ngoài dự tính gây cản trở cho người nói."},{pattern:"〜うちに",meaning:"Tranh thủ làm trong khi trạng thái còn giữ nguyên",priority:"common",explanation:'Mẫu ngữ pháp này mang ý nghĩa "tranh thủ làm việc gì đó trong khi trạng thái hiện tại chưa thay đổi". Thường dùng khi người nói muốn tận dụng một khoảng thời gian hoặc điều kiện thuận lợi trước khi cơ hội trôi qua hay tình huống xấu xảy ra. Vế sau luôn thể hiện hành động có chủ ý, mang tính tích cực và thường đi kèm các dạng câu thúc giục, khuyên nhủ hoặc nguyện vọng.',examples:[{sentence:"スープが温かいうちに、どうぞ召し上がってください。",translation:"Xin mời bạn dùng súp sớm trong lúc súp còn ấm nóng nhé."},{sentence:"日本に留学しているうちに、できるだけ多くの観光地を巡りたい。",translation:"Trong lúc còn đang du học ở Nhật, tôi muốn tranh thủ đi du lịch thật nhiều nơi."}],dialogue:{title:"Kế hoạch đi du lịch",lines:[{speaker:"A",text:"今度の連休、旅行に行かない？独身のうちに、色々な場所へ行っておきたいんだ。",translation:"Kỳ nghỉ dài tới đây đi du lịch không? Trong lúc còn độc thân, tớ muốn tranh thủ đi thật nhiều nơi."},{speaker:"B",text:"いいね！前から行ってみたかった北海道はどう？",translation:"Được đấy! Hay là đi Hokkaido - nơi tụi mình muốn đi từ trước tới giờ đi?"},{speaker:"A",text:"賛成！飛行機のチケットが安いうちに予約しちゃおう。",translation:"Nhất trí! Tranh thủ lúc vé máy bay còn rẻ thì đặt luôn thôi."}]},commonMistake:{wrong:"スープが温かい間に、早く飲んでください。",correct:"スープが温かいうちに、早く飲んでください。",why:"Khi muốn thúc giục hay khuyên đối phương tranh thủ làm việc gì đó trước khi trạng thái thuận lợi biến mất (súp bị nguội), bắt buộc phải dùng 「うちに」 chứ không dùng 「間に」."},note:"Khác với 「間に」 chỉ đơn thuần xác định một khoảng thời gian khách quan, 「うちに」 mang đậm sắc thái tận dụng thời điểm tốt và vế sau thường là hành động có ý chí, nguyện vọng (〜たい、〜てください、〜よう)."},{pattern:"〜間[あいだ]に",meaning:"Trong khoảng thời gian ~ thì (một điểm sự kiện xảy ra)",priority:"common",explanation:"Mẫu câu「〜間に」dùng để diễn tả một hành động hoặc sự việc mang tính thời điểm xảy ra xen vào trong suốt khoảng thời gian vế trước đang diễn ra. Cấu trúc thường đi với「V-ている / Nの / Tính từ + 間に」. Vế sau là hành động tức thời hoặc hoàn thành trong chốc lát, không kéo dài suốt toàn bộ khoảng thời gian như mẫu「〜間」.",examples:[{sentence:"子供が昼寝をしている間に、たまっていた家事を一気に片付けた。",translation:"Trong lúc con đang ngủ trưa, tôi đã dọn dẹp xong xuôi đống việc nhà dồn ứ."},{sentence:"日本に留学している間に、ぜひ一度富士山に登ってみたい。",translation:"Trong khoảng thời gian du học ở Nhật Bản, tôi nhất định muốn thử leo núi Phú Sĩ một lần."}],dialogue:{title:"Tranh thủ mua đồ",lines:[{speaker:"A",text:"映画が始まるまでの間に、ちょっと売店で飲み物を買ってきてもいい？",translation:"Trong khoảng thời gian chờ phim chiếu, mình chạy ra quầy mua chút đồ uống được không?"},{speaker:"B",text:"いいよ。じゃあ、私の分のお茶もついでにお願いできる？",translation:"Được chứ. Thế tiện thể mua giúp mình chai trà luôn nhé?"},{speaker:"A",text:"了解！上映開始までには必ず戻ってくるね。",translation:"Rõ rồi! Mình nhất định sẽ quay lại trước khi phim bắt đầu chiếu."}]},commonMistake:{wrong:"留守の間、家に泥棒が入ってしまった。",correct:"留守の間に、家に泥棒が入ってしまった。",why:"Vì hành động trộm đột nhập là sự kiện mang tính thời điểm xảy ra ngắt quãng trong khoảng thời gian vắng nhà, nên bắt buộc phải có trợ từ「に」."},note:"Cần phân biệt với「〜間」(không có に) khi hành động ở vế sau diễn ra liên tục, kéo dài suốt từ đầu đến cuối khoảng thời gian của vế trước."},{pattern:"最中[さいちゅう]に ≠ うちに ≠ 間[あいだ]に",meaning:"Phân biệt ba mẫu: gián đoạn / tranh thủ / điểm trong khoảng",priority:"common",explanation:"「最中に」nhấn mạnh hành động đang diễn ra ở giai đoạn cao trào nhất thì có sự việc bất ngờ xen vào làm gián đoạn, thường mang sắc thái phiền toái. Trong khi đó,「うちに」thể hiện sự tranh thủ thực hiện hành động trước khi trạng thái hiện tại thay đổi, hoặc một sự biến đổi diễn ra tự nhiên trong suốt khoảng thời gian đó. Ngược lại,「間に」chỉ đơn thuần xác định một hành động/sự việc mang tính khoảnh khắc xảy ra tại một thời điểm nào đó trong một khoảng thời gian kéo dài.",examples:[{sentence:"大事なスピーチの最中に、突然マイクの電源が切れてしまった。",translation:"Đúng lúc đang phát biểu quan trọng thì đột nhiên micro bị tắt nguồn."},{sentence:"日本に滞在しているうちに、一度富士山に登ってみたい。",translation:"Trong thời gian còn ở lại Nhật Bản, tôi muốn thử leo núi Phú Sĩ một lần."}],dialogue:{title:"Sự cố trong cuộc họp",lines:[{speaker:"A",text:"昨日のオンライン会議の最中に、急にパソコンがフリーズして焦ったよ。",translation:"Hôm qua đúng lúc đang họp trực tuyến thì bỗng nhiên máy tính bị đơ, hoảng cả người."},{speaker:"B",text:"えっ、大変だったね。大事な発表のタイミングだったんじゃない？",translation:"Hả, vất vả nhỉ. Lúc đó chẳng phải đúng thời điểm thuyết trình quan trọng sao?"},{speaker:"A",text:"うん。同僚が代わりに説明してくれている間に、再起動してなんとか復帰できたよ。",translation:"Ừ. Trong lúc đồng nghiệp giải thích giúp, tớ đã kịp khởi động lại và quay trở lại cuộc họp."}]},commonMistake:{wrong:"赤ちゃんが寝ている最中に、急いで夕飯を作ってしまおう。",correct:"赤ちゃんが寝ているうちに、急いで夕飯を作ってしまおう。",why:"「最中に」thường diễn tả sự việc bất ngờ xen ngang gây cản trở, không dùng khi người nói chủ động tranh thủ thời gian thực hiện ý chí/hành động như「うちに」."},note:"Vế sau của「最中に」không bao giờ đi cùng với câu biểu thị ý chí, mệnh lệnh, dự định hay rủ rê của người nói."}],74:[{pattern:"〜上[うえ]で（trình tự có căn cứ）",meaning:"Sau khi (làm X xong, trên cơ sở đó) mới Y — văn viết trang trọng",priority:"core",explanation:"Mẫu「〜た上で」dùng để diễn tả việc thực hiện hành động X (như tìm hiểu, kiểm tra, thảo luận...) coi đó là bước chuẩn bị hay căn cứ cần thiết, rồi mới tiến hành hành động Y mang tính ý chí hoặc đưa ra quyết định. Mẫu câu này mang sắc thái trang trọng, lịch sự, thường xuất hiện trong văn viết, môi trường công việc hoặc các quyết định quan trọng. Vế sau không dùng cho các hiện tượng tự nhiên hay trình tự sinh hoạt đời thường.",examples:[{sentence:"契約書の内容をよくご確認いただいた上で、こちらにご署名とご捺印をお願いいたします。",translation:"Sau khi đã kiểm tra kỹ nội dung hợp đồng, xin quý khách vui lòng ký tên và đóng dấu vào đây."},{sentence:"留学の件については、両親と十分に相談した上で最終的な決定を下すつもりです。",translation:"Về việc đi du học, tôi dự định sẽ đưa ra quyết định cuối cùng sau khi đã thảo luận kỹ càng với bố mẹ."}],dialogue:{title:"Bàn về dự án mới",lines:[{speaker:"A",text:"今回の新規プロジェクトへの参加についてですが、条件を検討した上でお返事してもよろしいでしょうか。",translation:"Về việc tham gia dự án mới lần này, sau khi xem xét kỹ các điều kiện, tôi xin phép trả lời sau có được không ạ?"},{speaker:"B",text:"ええ、もちろんです。締め切りは来週の水曜日ですので、それまでにご連絡ください。",translation:"Vâng, tất nhiên rồi. Hạn chót là thứ Tư tuần sau nên bạn hãy liên lạc trước thời điểm đó nhé."},{speaker:"A",text:"承知いたしました。チームメンバーとよく話し合った上でご連絡いたします。",translation:"Tôi đã rõ. Sau khi thảo luận kỹ với các thành viên trong nhóm, tôi sẽ liên lạc lại ạ."}]},commonMistake:{wrong:"昨日はシャワーを浴びた上で寝ました。",correct:"昨日はシャワーを浴びてから寝ました。",why:"「〜た上で」yêu cầu vế trước phải là bước đệm/căn cứ chuẩn bị cho hành động có chủ ý ở vế sau, không dùng cho trình tự các hành động sinh hoạt đời thường diễn ra thuần túy theo thời gian như tắm rồi ngủ."},note:"Khác với「〜てから」(chỉ đơn thuần là thứ tự trước - sau theo thời gian),「〜た上で」nhấn mạnh hành động trước là tiền đề/điều kiện cần thiết để thực hiện hành động sau; đồng thời chú ý không nhầm với「Vる＋上で」(trong quá trình/khi làm gì)."},{pattern:"〜てからでないと／〜てからでなければ",meaning:"Chưa X thì chưa thể / không thể Y (vế sau PHẢI phủ định)",priority:"common",explanation:"Mẫu câu này diễn tả ý nghĩa 'nếu chưa hoàn thành hành động A thì chưa thể hoặc không thể thực hiện hành động B'. Vế sau bắt buộc phải đi với các cách diễn đạt mang tính phủ định, diễn tả sự bất khả thi, khó khăn hoặc cấm đoán (như 〜できない、〜わけにはいかない、〜てはいけない). Cấu trúc này thường được dùng trong cả đời sống lẫn công việc để nhấn mạnh điều kiện tiên quyết bắt buộc phải làm trước.",examples:[{sentence:"契約書の内容を十分に確認してからでないと、サインすることはできません。",translation:"Nếu chưa xác nhận kỹ nội dung hợp đồng thì không thể ký tên được."},{sentence:"手術の傷が完全に治ってからでなければ、激しい運動をしてはいけません。",translation:"Nếu vết thương sau phẫu thuật chưa lành hẳn thì không được phép vận động mạnh."}],dialogue:{title:"Bàn chuyện mua nhà",lines:[{speaker:"A",text:"このマンション、駅にも近くてすごく気に入ったんだけど、もう契約しちゃおうか。",translation:"Căn hộ này vừa gần ga lại rất ưng ý, hay là mình ký hợp đồng luôn nhé?"},{speaker:"B",text:"いや、大きな買い物だから、両親に相談してからでないと決められないよ。",translation:"Không được, đây là việc mua sắm lớn nên nếu chưa bàn bạc với bố mẹ thì chưa thể quyết định được đâu."},{speaker:"A",text:"そうだね。今週末、二人で実家に行って話してみよう。",translation:"Đúng rồi nhỉ. Cuối tuần này hai đứa mình về quê rồi nói chuyện nhé."}]},commonMistake:{wrong:"実際に商品を見てからでないと、買います。",correct:"実際に商品を見てからでないと、買えません。",why:"Vế sau của mẫu câu「〜てからでないと」bắt buộc phải là câu phủ định hoặc thể khả năng phủ định, không được dùng câu khẳng định."},note:"Khác với「〜てから」(chỉ đơn thuần diễn tả thứ tự hành động trước - sau),「〜てからでないと」nhấn mạnh điều kiện tiên quyết bắt buộc và vế sau luôn luôn mang ý nghĩa phủ định."},{pattern:"上[うえ]で ≠ 上[うえ]は",meaning:"Phân biệt: 上で (trình tự căn cứ) ≠ 上は (vì đã... thì — quyết tâm/lập luận)",priority:"common",explanation:'「〜た上で」diễn tả hành động làm A trước như một tiền đề, chuẩn bị hoặc căn cứ cần thiết rồi mới tiến hành B. Trái lại,「〜上は」mang nghĩa "một khi đã... thì đương nhiên phải...", dùng để thể hiện quyết tâm, nghĩa vụ hoặc phán đoán dứt khoát dựa trên một sự thật đã rồi. Điểm khác biệt mấu chốt là「上で」nhấn mạnh trình tự thực hiện theo kế hoạch, còn「上は」nhấn mạnh vào trách nhiệm và thái độ tinh thần.',examples:[{sentence:"両親とよく相談した上で、留学するかどうかを決めたいと思います。",translation:"Tôi muốn bàn bạc kỹ với bố mẹ rồi sau đó mới quyết định có đi du học hay không."},{sentence:"契約書にサインした上は、どんな理由があっても約束を守らなければならない。",translation:"Một khi đã ký vào hợp đồng thì dù có bất kỳ lý do gì cũng phải giữ đúng cam kết."}],dialogue:{title:"Nhận dự án mới",lines:[{speaker:"A",text:"田中さん、このプロジェクトのリーダーを引き受けてもらえますか。",translation:"Anh Tanaka có thể nhận làm trưởng dự án này giúp tôi không?"},{speaker:"B",text:"チームと相談した上で、明日のお昼までにお返事してもよろしいでしょうか。",translation:"Sau khi thảo luận với nhóm rồi tôi trả lời vào trưa mai được không ạ?"},{speaker:"A",text:"わかりました。一度引き受けた上は最後までやり抜いてほしいので、じっくり考えてください。",translation:"Được chứ. Vì một khi đã nhận thì tôi muốn cậu làm tới cùng, nên hãy suy nghĩ thật kỹ nhé."}]},commonMistake:{wrong:"この契約書の内容をよく読んだ上は、サインしてください。",correct:"この契約書の内容をよく読んだ上で、サインしてください。",why:"「〜上は」mang sắc thái 'một khi đã... thì phải' (vế sau không dùng câu yêu cầu, nhờ vả đơn thuần), còn diễn tả quy trình 'sau khi làm A rồi mới làm B' thì bắt buộc dùng「〜た上で」."},note:"「〜た上で」chỉ trình tự chuẩn bị khách quan (vế sau thường là hành động có chủ ý), trong khi「〜上は」(đồng nghĩa với「〜以上は / 〜からには」) luôn đi kèm với phán đoán, nghĩa vụ hoặc ý chí mạnh mẽ ở vế sau."},{pattern:"〜てから ≠ 〜てからでないと",meaning:"てから (nối thứ tự, vế sau tự do) ≠ てからでないと (điều kiện, vế sau phải phủ định)",priority:"common",explanation:'「〜てから」dùng để diễn tả thứ tự thời gian đơn thuần (làm xong V1 rồi làm tiếp V2), vế sau hoàn toàn tự do và có thể là câu khẳng định, mệnh lệnh hoặc dự định. Ngược lại,「〜てからでないと」mang nghĩa "nếu chưa làm V1 thì không thể làm V2", nhấn mạnh V1 là điều kiện tiên quyết bắt buộc phải hoàn thành trước. Do đó, vế sau của「〜てからでないと」bắt buộc phải chia ở dạng phủ định hoặc diễn đạt sự bất khả thi, khó khăn.',examples:[{sentence:"資料をよく読んでから、明日の会議に参加してください。",translation:"Hãy đọc kỹ tài liệu rồi mới tham gia cuộc họp ngày mai nhé."},{sentence:"上司の許可をもらってからでないと、この契約を結ぶことはできません。",translation:"Nếu chưa nhận được sự cho phép của cấp trên thì chưa thể ký kết hợp đồng này được."}],dialogue:{title:"Báo cáo cấp trên",lines:[{speaker:"A",text:"田中さん、この新しいプロジェクトを今すぐ始めてもいいですか。",translation:"Anh Tanaka, tôi bắt đầu dự án mới này ngay bây giờ được không?"},{speaker:"B",text:"部長の承認をもらってからでないと、勝手に進めることはできないよ。",translation:"Nếu chưa nhận được phê duyệt của trưởng phòng thì không được tự ý tiến hành đâu."},{speaker:"A",text:"分かりました。まずは企画書を提出して相談してみます。",translation:"Tôi hiểu rồi. Trước hết tôi sẽ nộp bản kế hoạch để xin ý kiến sếp."}]},commonMistake:{wrong:"両親と相談してからでないと、留学を決めます。",correct:"両親と相談してからでないと、留学を決められません。",why:"Vế sau của cấu trúc「〜てからでないと」bắt buộc phải là câu phủ định hoặc mang sắc thái bất khả thi, không thể dùng câu khẳng định như「決めます」."},note:"「〜てからでないと」có thể thay thế tương đương bằng「〜てからでなければ」mà không làm thay đổi ý nghĩa và ngữ pháp của câu."}],75:[{pattern:"〜ばかりに",meaning:"Chỉ vì… mà (kéo hậu quả xấu ngoài ý muốn)",priority:"core",explanation:'Mẫu câu này diễn tả nguyên nhân duy nhất dẫn đến một kết quả tiêu cực, đáng tiếc hoặc ngoài ý muốn với ý nghĩa "chỉ vì... mà". Nó thể hiện mạnh mẽ tâm trạng hối hận, tiếc nuối hoặc bất mãn sâu sắc của người nói. Vế sau luôn là một kết cục xấu đã xảy ra và tuyệt đối không đi cùng câu thể hiện ý chí, nguyện vọng hay mệnh lệnh.',examples:[{sentence:"車の鍵を忘れたばかりに、大事な飛行機に乗り遅れてしまった。",translation:"Chỉ vì để quên chìa khóa xe mà tôi đã bị lỡ mất chuyến bay quan trọng."},{sentence:"一言余計なことを言ったばかりに、彼女をひどく怒らせてしまった。",translation:"Chỉ vì nói thừa một câu mà tôi đã khiến cô ấy giận dữ khủng khiếp."}],dialogue:{title:"Đến muộn buổi phỏng vấn",lines:[{speaker:"A",text:"目覚ましをかけ忘れたばかりに、大事な面接に大遅刻しちゃったよ。",translation:"Chỉ vì quên đặt báo thức mà tớ đã đến muộn buổi phỏng vấn quan trọng."},{speaker:"B",text:"えっ、本当？面接官にはちゃんと事情を説明できた？",translation:"Hả, thật á? Cậu đã giải thích rõ sự tình với người phỏng vấn chưa?"},{speaker:"A",text:"説明したけど、第一印象が悪くなったのは確実だから諦めているよ。",translation:"Tớ giải thích rồi nhưng chắc chắn ấn tượng ban đầu đã bị xấu đi nên đành buông xuôi thôi."}]},commonMistake:{wrong:"毎日日本語を練習したばかりに、N2試験に合格することができた。",correct:"毎日日本語を練習したおかげで、N2試験に合格することができた。",why:"「〜ばかりに」chỉ dùng cho kết quả tiêu cực hoặc đáng tiếc; khi kết quả mang lại điều tích cực, may mắn thì phải dùng「〜おかげで」."},note:'Cần chú ý dạng biến thể「V-たいばかりに」mang sắc thái "chỉ vì quá muốn làm V mà chấp nhận làm cả những việc vất vả, quá mức hoặc liều lĩnh".'},{pattern:"〜あまり（に）",meaning:"Vì quá… (cảm xúc/mức độ cực đoan) nên",priority:"common",explanation:"Mẫu câu này dùng để diễn tả vì một cảm xúc (lo lắng, vui mừng, tức giận...) hoặc trạng thái vượt quá mức độ thông thường mà dẫn đến một kết quả khác thường hoặc tiêu cực. Vế trước thường đi kèm danh từ chỉ tình cảm, tâm lý hoặc động từ diễn tả hành vi bị cảm xúc chi phối. Vế sau là kết quả xảy ra tự nhiên ngoài tầm kiểm soát, tuyệt đối không dùng câu mệnh lệnh, rủ rê hay biểu thị ý chí của người nói.",examples:[{sentence:"彼女は合格の知らせを聞いて、嬉しさのあまり大声で泣き出してしまった。",translation:"Khi nghe tin đỗ, vì quá đỗi vui mừng nên cô ấy đã bật khóc thành tiếng."},{sentence:"締め切りに追われ、焦るあまり重要な書類を添付し忘れてメールを送信してしまった。",translation:"Bị hạn chót dí, vì quá hấp tấp nên tôi đã gửi email mà quên đính kèm tài liệu quan trọng."}],dialogue:{title:"Căng thẳng khi phỏng vấn",lines:[{speaker:"A",text:"昨日の面接、緊張のあまり頭が真っ白になってうまく話せなかったよ。",translation:"Buổi phỏng vấn hôm qua, vì quá căng thẳng nên đầu óc tớ trống rỗng, chẳng nói năng trôi chảy được gì cả."},{speaker:"B",text:"大丈夫だった？でも、一生懸命な気持ちはきっと面接官に伝わっているはずだよ。",translation:"Cậu ổn chứ? Nhưng chắc chắn sự nhiệt tình, cố gắng của cậu đã truyền được tới người phỏng vấn rồi."},{speaker:"A",text:"そうだといいんだけど、合否が出るまで落ち着かないよ。",translation:"Mong là vậy, nhưng cho đến khi có kết quả đỗ trượt thì tớ vẫn đứng ngồi không yên."}]},commonMistake:{wrong:"試合に負けて、悔しいあまり部屋に閉じこもってしまった。",correct:"試合に負けて、悔しさのあまり部屋に閉じこもってしまった。",why:"Với tính từ đuôi -i, phải chuyển sang dạng danh từ hóa「〜さのあまり」(hoặc「あまりの〜さに」) chứ không ghép trực tiếp dạng nguyên thể「〜いあまり」."},note:"Khác với「〜すぎて」(có thể dùng cho hành động có chủ đích hoặc câu ý chí),「〜あまり」chỉ đi với kết quả tự nhiên ngoài tầm kiểm soát và thường mang sắc thái tiêu cực hoặc bất thường."},{pattern:"ばかりに ≠ せいで",meaning:'ばかりに = nhấn mạnh "CHỈ VÌ điều đó"; せいで = đổ lỗi chung chung (N3)',priority:"common",explanation:'「ばかりに」 mang nghĩa "chỉ vì... mà...", dùng để nhấn mạnh một nguyên nhân duy nhất (thường là sai sót nhỏ hoặc hành vi nhất thời) dẫn đến hậu quả nghiêm trọng ngoài dự tính, kèm theo tâm trạng ân hận, tiếc nuối sâu sắc. Ngược lại, 「せいで」 là mẫu câu N3 dùng để đổ lỗi, quy trách nhiệm chung cho người, vật hoặc sự việc gây ra kết quả xấu mà không nhấn mạnh sự day dứt hay tính chất "chỉ vì điều cỏn con ấy". Vì vậy, khi muốn bộc lộ cảm xúc dằn vặt cay đắng vì một nguyên nhân duy nhất, người Nhật sẽ ưu tiên chọn 「ばかりに」 thay vì 「せいで」.',examples:[{sentence:"嘘をついたばかりに、長年築いてきた信用を一瞬で失ってしまった。",translation:"Chỉ vì nói một lời dối trá mà tôi đã đánh mất sự tín nhiệm gây dựng bấy lâu nay trong chớp mắt."},{sentence:"台風が直撃したせいで、今週末に予定されていた花火大会は中止になった。",translation:"Do bão đổ bộ trực tiếp nên lễ hội pháo hoa dự kiến vào cuối tuần này đã bị hủy bỏ."}],dialogue:{title:"Kỳ thi bằng lái xe",lines:[{speaker:"A",text:"運転免許の試験、どうだった？合格できた？",translation:"Kỳ thi bằng lái xe thế nào rồi? Cậu có đỗ không?"},{speaker:"B",text:"ううん、最後に一時停止標識を見落としたばかりに、不合格になっちゃったよ。",translation:"Không, chỉ vì phút cuối nhìn sót mất biển báo dừng xe mà tớ bị đánh trượt rồi."},{speaker:"A",text:"それは本当に悔しいね。でも次は絶対に受かるよ！",translation:"Thế thì tiếc thật đấy. Nhưng lần sau nhất định cậu sẽ đỗ thôi!"}]},commonMistake:{wrong:"大雨が降ったばかりに、楽しみにしていた遠足が中止になった。",correct:"大雨が降ったせいで、楽しみにしていた遠足が中止になった。",why:"Khi đổ lỗi cho hiện tượng thời tiết hay nguyên nhân khách quan bên ngoài gây ra kết quả xấu thì phải dùng 「せいで」, không dùng 「ばかりに」 vì mẫu này vốn gắn với hành vi/nguyên nhân mang nặng tâm lý ân hận, day dứt."},note:'Ngoài chỉ nguyên nhân dẫn đến hậu quả tiêu cực, 「ばかりに」 còn có dạng 「Vたいばかりに」 biểu thị ý nghĩa "chỉ vì quá muốn làm V mà sẵn sàng làm những việc vất vả, quá mức".'},{pattern:"あまり(に) ≠ ばかりに（原因[げんいん]の種類[しゅるい]）",meaning:"あまり = vì mức độ QUÁ CAO; ばかりに = vì sự kiện/trạng thái CỤ THỂ",priority:"common",explanation:"「あまり(に)」 diễn tả nguyên nhân là do mức độ cảm xúc hoặc trạng thái vượt quá giới hạn bình thường (vì quá... nên) dẫn đến kết quả bất ngờ, khó kiểm soát. Ngược lại, 「ばかりに」 chỉ một sự việc, hành động hoặc lý do cụ thể làm mồi lửa gây ra hậu quả xấu (chỉ vì... mà), thường mang sắc thái hối hận sâu sắc. Do đó, các danh từ cảm xúc mạnh (như 緊張, 悲しみ, 怒り) chỉ có thể kết hợp với 「あまり(に)」 chứ không dùng với 「ばかりに」.",examples:[{sentence:"試験の前夜は緊張のあまり、一睡もできませんでした。",translation:"Đêm trước kỳ thi, vì quá căng thẳng mà tôi đã không thể chợp mắt được chút nào."},{sentence:"ちょっとした嘘をついたばかりに、親友の信頼を失ってしまった。",translation:"Chỉ vì nói dối một chút mà tôi đã đánh mất lòng tin của người bạn thân nhất."}],dialogue:{title:"Buổi thuyết trình quan trọng",lines:[{speaker:"A",text:"昨日のプレゼン、緊張のあまり頭が真っ白になっちゃったよ。",translation:"Bài thuyết trình hôm qua, vì quá căng thẳng mà đầu óc tớ hoàn toàn trống rỗng luôn."},{speaker:"B",text:"大丈夫だった？あんなに準備していたのに大変だったね。",translation:"Cậu có sao không? Đã chuẩn bị kỹ thế mà lại vất vả vậy rồi."},{speaker:"A",text:"原稿を家に忘れたばかりに、余計にパニックになっちゃって…。",translation:"Chỉ vì để quên bản thảo ở nhà mà tớ càng hoảng loạn hơn nữa..."}]},commonMistake:{wrong:"怒りばかりに、思わず相手を怒鳴ってしまった。",correct:"怒りのあまり、思わず相手を怒鳴ってしまった。",why:"「ばかりに」 dùng cho sự việc/hành động cụ thể dẫn đến hậu quả đáng tiếc, không dùng với danh từ cảm xúc để diễn tả phản ứng do mức độ cảm xúc quá cao."},note:"Hãy nhớ cụm cố định 「〜のあまり」 chuyên đi với danh từ cảm xúc (悲しみ、驚き、嬉しさ), còn 「ばかりに」 hay đi với động từ thể quá khứ 「Vた＋ばかりに」 để nhấn mạnh sự ân hận vì một hành động lỡ làm."}],76:[{pattern:"〜のことだから",meaning:"Vì biết tính (người/vật X) nên suy đoán",priority:"core",explanation:"Mẫu 「〜のことだから」 được dùng để đưa ra phán đoán, suy đoán về hành động hoặc trạng thái của một người dựa trên việc người nói đã hiểu rất rõ tính cách, thói quen hay đặc điểm của họ. Danh từ đứng trước thường là người mà người nói quen biết thân thiết hoặc hiểu rõ bản chất (như bạn bè, đồng nghiệp, người thân). Vế sau của câu hầu như luôn đi kèm các cách diễn đạt mang tính suy đoán, phán đoán như 「〜だろう」「〜に違いない」「〜はずだ」. Cấu trúc này mang sắc thái tin tưởng hoặc thấu hiểu sâu sắc và tuyệt đối không dùng cho bản thân người nói.",examples:[{sentence:"真面目な山田さんのことだから、締め切りには必ず間に合わせてくれるはずです。",translation:"Vì là người nghiêm túc như anh Yamada nên chắc chắn anh ấy sẽ kịp thời hạn nộp thôi."},{sentence:"子どもが大好きな田中先生のことだから、新しい幼稚園でもすぐに園児たちと仲良くなるだろう。",translation:"Vì là người rất yêu trẻ con như thầy Tanaka nên chắc là ở trường mầm non mới thầy cũng sẽ nhanh chóng thân thiết với các bé thôi."}],dialogue:{title:"Đợi bạn đến chỗ hẹn",lines:[{speaker:"A",text:"約束の時間を15分過ぎたけど、佐藤さんまだ来ないね。",translation:"Quá giờ hẹn 15 phút rồi mà anh Sato vẫn chưa đến nhỉ."},{speaker:"B",text:"いつも時間を守る佐藤さんのことだから、何か急な用事でもあって遅れているに違いないよ。",translation:"Vì là người luôn đúng giờ như anh Sato nên chắc chắn là có việc gì gấp mới đến muộn thôi."},{speaker:"A",text:"そうだね。連絡が来るまでもう少し待ってみよう。",translation:"Ừ đúng rồi. Chúng mình đợi thêm một chút nữa xem sao nhé."}]},commonMistake:{wrong:"私のことだから、明日もきっと寝坊してしまうだろう。",correct:"朝が苦手な彼のことだから、明日もきっと寝坊してしまうだろう。",why:"Mẫu 「〜のことだから」 dùng để suy đoán về đối tượng khác dựa trên tính cách quen thuộc, tuyệt đối không dùng để tự suy đoán về chính bản thân mình (私)."},note:"Vế sau của câu luôn luôn phải là câu suy đoán (như だろう, に違いない, はずだ...), không được dùng câu trần thuật khẳng định thực tế hiển nhiên hay câu mệnh lệnh, nhờ vả."},{pattern:"〜だけに",meaning:"Chính vì X nên kết quả tương xứng / bất ngờ (nhấn mạnh)",priority:"common",explanation:"Mẫu ngữ pháp「〜だけに」dùng để diễn tả ý nghĩa 'chính vì có lý do, hoàn cảnh đặc biệt X nên kết quả hoặc mức độ Y càng trở nên nổi bật, sâu sắc hơn bình thường'. Vế sau thường thể hiện cảm xúc (vui mừng, tiếc nuối, thất vọng) hoặc đánh giá, trạng thái tương xứng với nguyên nhân ở vế trước. Ngữ pháp này rất phổ biến trong cả văn viết lẫn giao tiếp thường ngày khi muốn nhấn mạnh tính chất nhân quả tự nhiên.",examples:[{sentence:"期待が大きかっただけに、不合格の知らせを聞いたときのショックは大きかった。",translation:"Chính vì kỳ vọng quá lớn nên khi nhận thông báo trượt, cú sốc lại càng nặng nề hơn."},{sentence:"彼は子どもの頃から日本に住んでいただけに、日本語の発音がとても自然だ。",translation:"Chính vì sống ở Nhật từ nhỏ nên phát âm tiếng Nhật của anh ấy rất tự nhiên."}],dialogue:{title:"Tổng kết sự kiện",lines:[{speaker:"A",text:"何ヶ月も準備に時間をかけただけに、イベントが大成功して本当に嬉しいです。",translation:"Chính vì đã dành nhiều tháng chuẩn bị nên khi sự kiện thành công rực rỡ em thực sự rất vui."},{speaker:"B",text:"本当にお疲れ様。君の頑張りがあったからこそだよ。",translation:"Em đã vất vả rồi. Chính là nhờ sự nỗ lực của em đấy."},{speaker:"A",text:"ありがとうございます。次の企画も全力で頑張ります！",translation:"Em cảm ơn ạ. Kế hoạch tiếp theo em cũng sẽ nỗ lực hết mình!"}]},commonMistake:{wrong:"プロの料理人だけに、私においしい料理を作ってください。",correct:"プロの料理人だけに、彼が作る料理はどれも格別に美味しい。",why:"Vế sau của「〜だけに」phải là kết quả, trạng thái hoặc cảm xúc tự nhiên, tuyệt đối không dùng câu mệnh lệnh, nhờ vả hay ý chí người nói như「〜てください」."},note:"Khác với「〜からには」(một khi đã... thì phải làm gì/thể hiện quyết tâm, nghĩa vụ),「〜だけに」nhấn mạnh mức độ cảm xúc hoặc kết quả tương xứng với nguyên nhân đặc biệt."},{pattern:"ことだから ≠ だけに の 使[つか]い分[わ]け",meaning:"Phân biệt: ことだから (biết tính nhân vật → suy đoán) ≠ だけに (nhân-quả tương xứng/bất ngờ)",priority:"common",explanation:'「〜ことだから」dùng sau danh từ chỉ người (hoặc nhóm người đã biết rõ) để đưa ra phán đoán, suy đoán về hành động của họ dựa trên tính cách hoặc thói quen vốn có. Trong khi đó,「〜だけに」diễn tả mối quan hệ nhân-quả đặc thù: "chính vì có lý do, năng lực hoặc đặc điểm X nên kết quả/mức độ Y phía sau là tương xứng, vượt trội hơn bình thường". Điểm khác biệt mấu chốt là vế sau của「〜ことだから」bắt buộc phải là câu suy đoán chủ quan (thường đi với きっと, だろう, はずだ), còn「〜だけに」hướng tới sự thật, năng lực hoặc cảm xúc tự nhiên được nhấn mạnh.',examples:[{sentence:"責任感の強い山田さんのことだから、頼まれた仕事は必ずやり遂げるはずだ。",translation:"Người có tinh thần trách nhiệm cao như anh Yamada thì chắc chắn sẽ hoàn thành công việc được giao thôi."},{sentence:"このホテルは一流の一等地にあるだけに、サービスも設備も文句のつけようがない。",translation:"Chính vì khách sạn này nằm ở khu vực đắc địa hàng đầu nên từ dịch vụ đến tiện nghi đều không có điểm nào để chê."}],dialogue:{title:"Chuẩn bị thuyết trình",lines:[{speaker:"A",text:"明日の新企画のプレゼン、佐藤さん一人で大丈夫かな。",translation:"Buổi thuyết trình dự án mới ngày mai, một mình anh Sato lo liệu có ổn không nhỉ?"},{speaker:"B",text:"準備を徹底する彼のことだから、きっと大成功すると思うよ。",translation:"Người chuẩn bị kỹ lưỡng như anh ấy thì tớ nghĩ chắc chắn sẽ thành công rực rỡ thôi."},{speaker:"A",text:"そうだね。経験豊富なだけに、安心して任せられるね。",translation:"Đúng thế. Chính vì giàu kinh nghiệm nên chúng ta hoàn toàn có thể an tâm giao phó."}]},commonMistake:{wrong:"真面目な彼だけに、明日の集合時間には遅刻しないだろう。",correct:"真面目な彼のことだから、明日の集合時間には遅刻しないだろう。",why:"Khi dựa vào tính cách, phẩm chất của một người để suy đoán hành động của họ (vế sau có suy đoán だろう/きっと) thì phải dùng「〜ことだから」, không dùng「〜だけに」."},note:"「〜ことだから」chủ yếu đi với danh từ chỉ người và vế sau mang tính suy đoán chủ quan, còn「〜だけに」chỉ mối quan hệ nhân-quả tương xứng và vế sau thường là đánh giá thực tế hoặc cảm xúc trực tiếp."},{pattern:"だけに ≠ だけあって の 違[ちが]い",meaning:"だけあって (b78) chỉ dùng khen (+); だけに dùng cả kết quả tốt lẫn tiếc/bất ngờ",priority:"common",explanation:'「〜だけあって」mang ý nghĩa "quả đúng là / chẳng hổ danh là", chuyên dùng để khen ngợi hoặc đánh giá cao một kết quả tích cực, xứng đáng với nguyên nhân phía trước. Trong khi đó,「〜だけに」mang nghĩa "chính vì... nên càng...", nhấn mạnh mức độ cảm xúc hay phản ứng tâm lý phát sinh đặc biệt mạnh mẽ. Điểm khác biệt quan trọng là「〜だけあって」chỉ dùng cho vế sau mang ý nghĩa tích cực (khen ngợi), còn「〜だけに」dùng được cho cả kết quả tốt lẫn kết quả xấu, thất vọng hay tiếc nuối ngoài dự tính.',examples:[{sentence:"期待が大きかっただけに、不合格の知らせを聞いたときのショックは大きかった。",translation:"Chính vì kỳ vọng càng lớn nên cú sốc khi nhận tin trượt lại càng nặng nề hơn."},{sentence:"このレストランはミシュランの星を獲得しているだけあって、どの料理も本当に素晴らしい。",translation:"Nhà hàng này quả đúng là từng đoạt sao Michelin, món ăn nào cũng thực sự tuyệt vời."}],dialogue:{title:"Cảm xúc sau trận đấu",lines:[{speaker:"A",text:"毎日遅くまで練習を重ねていただけに、初戦で負けてしまって本当に悔しいよ。",translation:"Chính vì đã nỗ lực luyện tập đến khuya mỗi ngày nên thua ngay trận đầu tớ thấy thật tiếc nuối và cay đắng."},{speaker:"B",text:"相手は全国大会の常連校だけあって、さすがに強かったね。",translation:"Đối thủ quả đúng là đội quen thuộc ở giải toàn quốc, công nhận họ rất mạnh."},{speaker:"A",text:"うん、でもこの悔しさをバネにして、次の大会に向けてもっと頑張るよ。",translation:"Ừ, nhưng tớ sẽ biến sự tiếc nuối này thành động lực để cố gắng hơn nữa cho giải tới."}]},commonMistake:{wrong:"一生懸命準備しただけあって、失敗してしまってとても残念だ。",correct:"一生懸命準備しただけに、失敗してしまってとても残念だ。",why:"Không dùng 「〜だけあって」 khi vế sau là kết quả tiêu cực hay sự thất vọng, tiếc nuối; trường hợp này phải dùng 「〜だけに」 để thể hiện cảm xúc bị khuếch đại do nguyên nhân trước đó."},note:"「〜だけに」thường đi kèm các từ chỉ mức độ cảm xúc tăng lên như 「なおさら」「一層」「ひとしお」, còn「〜だけあって」thường hay đi kèm với phó từ tán thưởng 「さすがに」."}],77:[{pattern:"〜以上[いじょう]（は）",meaning:"Đã…thì phải (lập luận logic, văn viết)",priority:"core",explanation:'Mẫu câu 「〜以上（は）」 mang ý nghĩa "Đã... thì phải / Một khi đã... thì đương nhiên...", dùng để diễn tả mối quan hệ nhân quả dựa trên lập luận logic và tinh thần trách nhiệm. Vế trước nêu ra một sự thật, một cương vị hoặc một quyết định đã xác định; vế sau là hệ quả tất yếu mà người nói phải gánh vác. Do đó, vế sau luôn đi cùng các mẫu câu thể hiện nghĩa vụ, quyết tâm, lời khuyên hoặc phán đoán như 「〜べきだ」「〜なければならない」「〜つもりだ」. Mẫu này mang sắc thái trang trọng, thường dùng trong văn viết, bài phát biểu hoặc các bối cảnh nghiêm túc.',examples:[{sentence:"プロジェクトのリーダーを引き受けた以上、最後まで責任を持ってやり遂げるべきだ。",translation:"Một khi đã nhận làm trưởng dự án thì phải có trách nhiệm thực hiện đến cùng."},{sentence:"試験を受けると決めた以上は、合格を目指して全力で勉強するつもりです。",translation:"Đã quyết định dự thi thì tôi dự định sẽ dốc toàn lực học tập để hướng tới mục tiêu đỗ đạt."}],dialogue:{title:"Giao phó dự án quan trọng",lines:[{speaker:"A",text:"この重要な契約を任された以上は、絶対に失敗できませんね。",translation:"Một khi đã được giao bản hợp đồng quan trọng này thì tuyệt đối không thể để thất bại được nhỉ."},{speaker:"B",text:"ええ、プレッシャーは大きいですが、チーム全員で協力して成功させましょう。",translation:"Vâng, áp lực rất lớn nhưng cả đội hãy cùng hợp tác để làm cho thành công nhé."},{speaker:"A",text:"はい、期待に応えられるよう、全力を尽くして頑張りましょう！",translation:"Vâng, chúng ta hãy dốc hết sức cố gắng để đáp lại sự kỳ vọng nhé!"}]},commonMistake:{wrong:"日本に留学した以上、日本語が自然に上手になりました。",correct:"日本に留学した以上、日本語を流暢に話せるようになるまで諦めないつもりです。",why:"Vế sau của 「〜以上（は）」 không dùng để kể lại sự việc đã xảy ra hay kết quả tự nhiên trong quá khứ, mà bắt buộc phải là câu thể hiện ý chí, nghĩa vụ hoặc quyết tâm của người nói."},note:"So với 「〜からには」 mang nhiều cảm xúc chủ quan và dùng nhiều trong văn nói thường ngày, 「〜以上（は）」 mang tính lập luận logic khách quan và trang trọng hơn nhiều."},{pattern:"〜上[うえ]は",meaning:"Đã…thì phải (văn viết trang trọng, bi tráng)",priority:"common",explanation:'Mẫu ngữ pháp này mang ý nghĩa "Một khi đã... thì phải / Đã... thì đương nhiên phải...", dùng để biểu thị quyết tâm cao độ, ý thức trách nhiệm hoặc nghĩa vụ tất yếu sau khi đã đưa ra một quyết định hay đứng trước một tình huống không thể thay đổi. Vế trước nêu tiền đề, vế sau luôn đi kèm các cách diễn đạt thể hiện ý chí, nghĩa vụ, phán đoán dứt khoát như 「〜なければならない」, 「〜べきだ」, 「〜つもりだ」, 「〜覚悟だ」. Đây là mẫu câu thuộc văn phong trang trọng, mang sắc thái nghiêm túc, quyết liệt (đôi khi bi tráng), thường xuất hiện trong văn viết, phát biểu chính thức hoặc khi tuyên thệ trước các bước ngoặt lớn.',examples:[{sentence:"一度プロジェクトの責任者を引き受けた上は、何があっても最後までやり抜く覚悟です。",translation:"Một khi đã nhận làm người phụ trách dự án, tôi quyết tâm sẽ theo đuổi đến cùng dù có bất cứ chuyện gì xảy ra."},{sentence:"国家資格の試験を受けると決めた上は、遊ぶ時間を削ってでも合格を目指さなければならない。",translation:"Đã quyết định tham gia kỳ thi chứng chỉ quốc gia thì dù phải cắt giảm thời gian vui chơi tôi cũng phải hướng đến mục tiêu đỗ."}],dialogue:{title:"Quyết tâm khởi nghiệp",lines:[{speaker:"A",text:"安定した会社を辞めて起業すると決めた上は、どんな困難があっても途中で投げ出すわけにはいかないよ。",translation:"Một khi đã quyết định từ bỏ công ty ổn định để khởi nghiệp thì dù gặp muôn vàn khó khăn tớ cũng tuyệt đối không thể bỏ dở giữa chừng."},{speaker:"B",text:"その強い覚悟があるなら大丈夫だ。みんなで全力でサポートするからね。",translation:"Cậu có quyết tâm mạnh mẽ như vậy thì yên tâm rồi. Mọi người nhất định sẽ dốc toàn lực ủng hộ cậu."},{speaker:"A",text:"ありがとう。必ず事業を成功させて、みんなの期待に応えてみせるよ。",translation:"Cảm ơn cậu. Tớ nhất định sẽ làm cho sự nghiệp thành công và đền đáp kỳ vọng của mọi người."}]},commonMistake:{wrong:"この契約を結んだ上は、会社の利益が増えました。",correct:"この契約を結んだ上は、全力で目標を達成しなければならない。",why:"Vế sau của 「〜上は」 không được dùng để tường thuật một kết quả thực tế hoặc sự việc khách quan đã xảy ra trong quá khứ, mà bắt buộc phải là biểu hiện ý chí, nghĩa vụ hoặc quyết tâm của người nói."},note:"「〜上は」 đồng nghĩa với 「〜からには」 và 「〜以上（は）」, nhưng 「〜上は」 mang phong cách văn viết trang trọng và sắc thái bi tráng, quyết tâm dứt khoát nhất trong cả ba mẫu."},{pattern:"〜からには",meaning:"Đã…thì phải (quyết tâm cá nhân, cả nói & viết)",priority:"common",explanation:'Mẫu 「〜からには」 mang ý nghĩa "Một khi đã... thì đương nhiên phải / quyết tâm làm đến cùng". Vế trước đưa ra một sự thật, lý do hoặc tiền đề hiển nhiên, dẫn đến vế sau bắt buộc phải thể hiện ý chí, quyết tâm, nghĩa vụ hoặc lời khuyên mạnh mẽ (như 「〜たい」「〜つもりだ」「〜べきだ」「〜てはならない」). Ngữ pháp này được dùng phổ biến trong cả giao tiếp đời sống lẫn văn viết trang trọng khi muốn nhấn mạnh tinh thần trách nhiệm và sự kiên định.',examples:[{sentence:"自分で留学を決めたからには、どんなに辛くても最後までやり遂げたい。",translation:"Một khi đã tự mình quyết định đi du học, dù có vất vả thế nào tôi cũng muốn nỗ lực đến cùng."},{sentence:"プロジェクトのリーダーを引き受けたからには、責任を持って成功させるつもりだ。",translation:"Một khi đã nhận làm trưởng dự án thì tôi dự định sẽ chịu trách nhiệm để đưa dự án tới thành công."}],dialogue:{title:"Chuẩn bị cho kỳ thi",lines:[{speaker:"A",text:"今度のJLPT N2試験、もう申し込んだんだって？",translation:"Nghe nói cậu đã đăng ký kỳ thi JLPT N2 đợt tới rồi à?"},{speaker:"B",text:"うん、高い受験料を払って申し込んだからには、絶対に一発で合格してみせるよ。",translation:"Ừ, một khi đã đóng khoản lệ phí thi đắt đỏ để đăng ký thì tớ nhất định sẽ đỗ ngay lần đầu cho xem."},{speaker:"A",text:"その意気だね！応援しているよ。",translation:"Quyết tâm thế là tốt đấy! Tớ sẽ cổ vũ cho cậu."}]},commonMistake:{wrong:"一度引き受けたからには、昨日その仕事を終わらせました。",correct:"一度引き受けたからには、最後まで責任を持ってやり遂げるつもりです。",why:"Vế sau của 「〜からには」 bắt buộc phải là biểu hiện thể hiện ý chí, quyết tâm hoặc nghĩa vụ (như 〜たい、〜つもりだ、〜べきだ), không dùng để kể lại một sự việc khách quan đã hoàn thành trong quá khứ."},note:"Mẫu này đồng nghĩa với 「〜以上（は）」 và 「〜上は」, trong đó 「〜上は」 mang sắc thái trang trọng, văn viết cứng nhất, còn 「〜からには」 được dùng linh hoạt và tự nhiên trong cả văn nói lẫn văn viết."},{pattern:"以上（は）・上は・からには の 使[つか]い分[わ]け",meaning:"Ba mẫu gần đồng nghĩa: 以上は = logic/văn viết; 上は = bi tráng/trang trọng; からには = quyết tâm/cá nhân",priority:"common",explanation:'Cả ba mẫu 「以上（は）」, 「上は」, 「からには」 đều diễn tả ý nghĩa "một khi đã... thì phải/đương nhiên...", vế sau đi kèm phán đoán, nghĩa vụ hoặc quyết tâm. Trong đó, 「からには」 nhấn mạnh ý chí và quyết tâm chủ quan của cá nhân người nói trong mọi tình huống. 「以上（は）」 mang tính logic khách quan và trách nhiệm xã hội, nhấn mạnh việc đương nhiên phải làm khi ở vào cương vị hay hoàn cảnh đó. Còn 「上は」 là văn phong trang trọng nhất, diễn tả sự xác định tâm thế khi bị dồn vào tình thế bắt buộc, không còn đường lui.',examples:[{sentence:"契約書にサインした以上は規則を守る義務があるが、自ら挑戦を決めたからには最後まで諦めない。",translation:"Một khi đã ký hợp đồng thì có nghĩa vụ tuân thủ quy tắc, nhưng một khi bản thân đã quyết định thử thách thì sẽ không bỏ cuộc tới cùng."},{sentence:"国家の機密を知ってしまった上は、どんな危険が迫ろうとも真実を守り抜く覚悟だ。",translation:"Một khi đã trót biết bí mật quốc gia (tình thế không thể thoái thác), tôi sẵn sàng chuẩn bị tâm thế bảo vệ sự thật đến cùng dù hiểm nguy phía trước."}],dialogue:{title:"Trọng trách dự án mới",lines:[{speaker:"A",text:"リーダーを引き受けた以上は、結果を出す責任があります。",translation:"Một khi đã nhận lời làm trưởng nhóm, tôi có trách nhiệm phải đem lại kết quả."},{speaker:"B",text:"大変そうですが、引き受けたからには全力でやり遂げましょう！",translation:"Có vẻ vất vả đấy, nhưng một khi đã nhận thì hãy dốc toàn lực làm đến cùng nhé!"},{speaker:"A",text:"はい、後戻りできない状況になった上は、不退転の決意で挑みます。",translation:"Vâng, một khi đã vào tình thế không thể quay đầu lại, tôi sẽ quyết tâm không lùi bước để đương đầu."}]},commonMistake:{wrong:"友達とお酒を飲む約束をした上は、絶対に行かなければならない。",correct:"友達とお酒を飲む約束をしたからには、絶対に行かなければならない。",why:"「上は」 mang sắc thái trang trọng, bi tráng khi đối mặt tình thế nghiêm trọng, không dùng cho việc sinh hoạt thường ngày như hẹn bạn bè uống rượu."},note:"Cần phân biệt rõ ngữ cảnh: 「からには」 thể hiện quyết tâm cá nhân, 「以上（は）」 thể hiện trách nhiệm đạo lý theo logic chung, còn 「上は」 dùng trong văn cảnh trang trọng hoặc tình huống hiểm nghèo không còn đường rút lui."}],78:[{pattern:"〜ものだから／〜もので",meaning:"Biện minh nhẹ lý do (xin lỗi / giải thích hành vi ngoài ý muốn)",priority:"core",explanation:"Mẫu 「〜ものだから／〜もので」 dùng để đưa ra lý do, phân trần hoặc biện minh cho một sự việc bất lợi, ngoài ý muốn hay lỡ thất lễ với đối phương. Vế sau thường diễn tả kết quả thực tế đã lỡ xảy ra hoặc lời xin lỗi, mang sắc thái nhẹ nhàng mong người nghe thấu hiểu và thông cảm. Ngữ pháp này chủ yếu dùng trong văn nói lịch sự vừa phải khi trần tình hoàn cảnh khách quan hoặc lý do cá nhân bất khả kháng.",examples:[{sentence:"昨日は久しぶりに学生時代の友人に会ったものだから、つい夜遅くまで話し込んでしまいました。",translation:"Hôm qua vì lâu ngày mới gặp lại bạn thời đi học nên tôi lỡ mải trò chuyện đến tận đêm muộn."},{sentence:"この靴、デザインがとても気に入ったもので、予算オーバーだったのに買ってしまったんです。",translation:"Đôi giày này vì tôi ưng thiết kế quá nên dù vượt ngân sách vẫn lỡ mua mất."}],dialogue:{title:"Đến muộn buổi họp",lines:[{speaker:"A",text:"すみません、事故で電車が急に止まってしまったものだから、遅れてしまいました。",translation:"Xin lỗi mọi người, vì gặp sự cố tàu đột ngột dừng lại nên tôi đã bị muộn ạ."},{speaker:"B",text:"そうでしたか。大変でしたね。まだ会議は始まったばかりですから大丈夫ですよ。",translation:"Thế à? Vất vả cho bạn quá. Cuộc họp cũng vừa mới bắt đầu thôi nên không sao đâu."},{speaker:"A",text:"ご迷惑をおかけして本当に申し訳ありません。すぐ準備に入ります。",translation:"Tôi thực sự xin lỗi vì đã gây phiền phức. Tôi sẽ chuẩn bị vào việc ngay ạ."}]},commonMistake:{wrong:"バスが遅れたものだから、少し待ってください。",correct:"バスが遅れているので、少し待ってください。",why:"Vế sau của 「〜ものだから」 dùng để trần tình cho kết quả đã xảy ra, không được dùng câu mệnh lệnh, nhờ vả hay thể ý chí."},note:"Trong hội thoại thân mật hàng ngày, mẫu này thường được biến âm rút gọn thành 「〜もんだから／〜もんで」."},{pattern:"〜だけあって",meaning:'Khen ngợi "xứng đáng / quả là" — kết quả tích cực tương xứng với danh tiếng/nỗ lực',priority:"common",explanation:'Mẫu ngữ pháp này dùng để khen ngợi và bày tỏ sự thán phục, có nghĩa là "quả đúng là / xứng đáng là / thảo nào mà...". Vế sau luôn là một kết quả tốt đẹp, sự vượt trội hoặc đặc trưng tích cực hoàn toàn tương xứng với nỗ lực, kinh nghiệm, địa vị hoặc danh tiếng nêu ở vế trước. Ngữ cảnh sử dụng mang sắc thái thấu hiểu sâu sắc và tâm phục khẩu phục sau khi người nói đã trực tiếp trải nghiệm hoặc chứng kiến sự việc.',examples:[{sentence:"このレストランはミシュランの星を獲得しただけあって、料理の味も接客も申し分がない。",translation:"Quả đúng là nhà hàng từng đạt sao Michelin, cả hương vị món ăn lẫn phong cách phục vụ đều không có điểm gì để chê."},{sentence:"彼女は10年間毎日ピアノを練習してきただけあって、演奏の表現力が素晴らしい。",translation:"Xứng đáng với 10 năm miệt mài luyện tập piano mỗi ngày, khả năng biểu cảm trong tiếng đàn của cô ấy thật tuyệt vời."}],dialogue:{title:"Trải nghiệm khu nghỉ dưỡng",lines:[{speaker:"A",text:"このホテル、サービスが隅々まで行き届いていて感動したよ。",translation:"Khách sạn này dịch vụ chu đáo đến từng chi tiết, làm mình ấn tượng thật đấy."},{speaker:"B",text:"一流の高級リゾートホテルだけあって、スタッフの気配りも素晴らしいね。",translation:"Quả đúng là khu nghỉ dưỡng cao cấp hạng nhất, sự tinh tế của nhân viên cũng thật tuyệt vời nhỉ."},{speaker:"A",text:"うん、決して安くはなかったけれど、ここに泊まって本当に大満足だよ。",translation:"Ừ, tuy không hề rẻ nhưng nghỉ lại ở đây mình thực sự vô cùng hài lòng."}]},commonMistake:{wrong:"有名な先生に習っただけあって、試験に落ちてしまった。",correct:"有名な先生に習っただけあって、見事に高得点で合格した。",why:"Mẫu 「〜だけあって」 bắt buộc vế sau phải là kết quả tích cực hoặc lời khen ngợi, không dùng cho kết quả tiêu cực hay thất bại."},note:"Cần phân biệt với 「〜だけに」: 「〜だけあって」 chỉ đi với đánh giá tích cực/khen ngợi, còn 「〜だけに」 có thể dùng cho cả kết quả tiêu cực mang sắc thái thất vọng (chính vì... nên càng thất vọng hơn)."},{pattern:"だけあって ≠ だけに",meaning:"だけあって = khen ngợi (tích cực); だけに = trung tính/nhấn mạnh (cả tốt lẫn xấu đều dùng được)",priority:"common",explanation:'「～だけあって」diễn đạt ý "quả đúng là / xứng danh là...", dùng khi muốn khen ngợi hoặc đánh giá cao một kết quả tích cực hoàn toàn tương xứng với thực lực hay danh tiếng (thường đi cùng với さすが). Trong khi đó,「～だけに」mang nghĩa "chính vì... nên càng...", dùng để nhấn mạnh mức độ cảm xúc hoặc hệ quả phát sinh từ một nguyên nhân đặc biệt. Điểm khác biệt then chốt là「だけあって」chỉ dùng cho ngữ cảnh tích cực/khen ngợi, còn「だけに」dùng được cho cả điều tích cực lẫn tiêu cực (đặc biệt là sự thất vọng, tiếc nuối khi kỳ vọng nhiều).',examples:[{sentence:"このホテルは5つ星だけあって、接客も設備も本当に素晴らしい。",translation:"Quả đúng là khách sạn 5 sao có khác, cả cung cách phục vụ lẫn tiện nghi đều thực sự tuyệt vời."},{sentence:"何ヶ月も一生懸命準備しただけに、試験に落ちたときのショックは大きかった。",translation:"Chính vì đã chuẩn bị chăm chỉ suốt nhiều tháng trời nên cú sốc khi thi trượt lại càng lớn."}],dialogue:{title:"Đánh giá nhà hàng",lines:[{speaker:"A",text:"このお店の料理、盛り付けも綺麗だしすごく美味しいね。",translation:"Món ăn của quán này bày trí vừa đẹp mắt lại còn ngon tuyệt nữa nhỉ."},{speaker:"B",text:"一流のシェフが作っているだけあって、素材の味がしっかり引き立っているよ。",translation:"Quả đúng là do đầu bếp hàng đầu nấu có khác, hương vị nguyên liệu được tôn lên trọn vẹn."},{speaker:"A",text:"うん、遠くからわざわざ食べに来た甲斐があったね。",translation:"Ừ, thật bõ công lặn lội đường xa đến đây ăn."}]},commonMistake:{wrong:"期待が大きかっただけあって、計画が失敗したときの落胆は激しかった。",correct:"期待が大きかっただけに、計画が失敗したときの落胆は激しかった。",why:"「だけあって」chỉ đi với vế sau mang ý nghĩa tích cực hoặc khen ngợi, khi diễn tả tâm trạng tiêu cực, thất vọng thì bắt buộc phải dùng「だけに」."},note:'Hãy nhớ mẹo: muốn khen ngợi "xứng danh / quả có khác" thì dùng「だけあって」, còn muốn nhấn mạnh mức độ cảm xúc "chính vì thế nên lại càng (thất vọng/lo lắng/vui mừng)" thì dùng「だけに」.'},{pattern:"ものだから ≠ せいで",meaning:"ものだから = biện minh nhẹ, có cảm giác xin lỗi; せいで = đổ lỗi mạnh, trách cứ rõ ràng",priority:"common",explanation:"「ものだから」và「せいで」đều dùng để nêu nguyên nhân dẫn đến sự việc không mong muốn, nhưng sắc thái biểu đạt hoàn toàn khác nhau.「ものだから」thường dùng khi người nói muốn giải thích, biện minh nhẹ nhàng cho hành động hoặc thiếu sót của bản thân với thái độ cầu thị, mong đối phương thông cảm. Ngược lại,「せいで」mang tính đổ lỗi gay gắt, quy trách nhiệm cho một đối tượng hoặc yếu tố ngoại cảnh gây ra hậu quả xấu, không dùng để xin lỗi lịch sự.",examples:[{sentence:"目覚まし時計が鳴らなかったものだから、会議に遅れてしまいました。申し訳ありません。",translation:"Vì đồng hồ báo thức không reo nên tôi đã trót đến họp muộn. Tôi thành thật xin lỗi."},{sentence:"連日の猛暑のせいで、畑の野菜が全部枯れてしまった。",translation:"Chỉ tại đợt nắng nóng gay gắt kéo dài nhiều ngày mà toàn bộ rau củ ngoài ruộng đã héo khô hết."}],dialogue:{title:"Giải thích gửi tài liệu trễ",lines:[{speaker:"A",text:"課長、急な来客の対応をしていたものだから、資料の提出が遅れてしまい申し訳ありません。",translation:"Thưa Trưởng phòng, vì phải tiếp khách đột xuất nên em nộp tài liệu bị trễ, em xin lỗi ạ."},{speaker:"B",text:"そうだったのか。大変だったね、確認しておくよ。",translation:"Ra là vậy à. Vất vả cho cậu rồi, để tôi xem qua nhé."},{speaker:"A",text:"お待たせして本当にすみませんでした。よろしくお願いいたします。",translation:"Em thật sự xin lỗi vì đã để anh phải đợi. Nhờ Trưởng phòng xem giúp em ạ."}]},commonMistake:{wrong:"道が混んでいたせいで、遅刻してしまいました。すみません。",correct:"道が混んでいたものだから、遅刻してしまいました。すみません。",why:"Khi phân trần và xin lỗi về lỗi lầm của bản thân, không dùng「せいで」vì sẽ tạo cảm giác đổ lỗi trốn tránh trách nhiệm, thay vào đó phải dùng「ものだから」để thể hiện sự hối lỗi và mong được thứ lỗi."},note:"Trong hội thoại thân mật hàng ngày,「ものだから」thường biến âm thành「もんだから」hoặc kết thúc câu lửng dạng「〜もので／〜ものだから」để giải thích lý do một cách khéo léo."}],79:[{pattern:"〜ものの",meaning:"Tuy…nhưng (văn viết — nhượng bộ, không trách móc)",priority:"core",explanation:'Mẫu câu「〜ものの」dùng để diễn đạt ý nghĩa "tuy... nhưng...", thừa nhận tính xác thực của vế trước nhưng vế sau lại đưa ra kết quả trái với dự đoán hoặc kỳ vọng thông thường. Mẫu này mang phong cách văn viết, trang trọng và thể hiện sự nhượng bộ một cách khách quan. Khác với các mẫu mang sắc thái tiêu cực,「〜ものの」không mang hàm ý trách móc và vế sau thường diễn tả một sự thật hay trạng thái thực tế, không dùng câu mệnh lệnh hay ý chí.',examples:[{sentence:"給料は高いものの、残業が多くて自分の時間がほとんど取れない。",translation:"Lương tuy cao thật nhưng vì tăng ca nhiều nên tôi hầu như không có thời gian cho bản thân."},{sentence:"日本語能力試験N2に合格したものの、実際の会話となるとまだうまく話せない。",translation:"Tuy đã đỗ kỳ thi JLPT N2 nhưng khi bước vào giao tiếp thực tế thì tôi vẫn chưa thể nói lưu loát được."}],dialogue:{title:"Mua máy tính mới",lines:[{speaker:"A",text:"新しいパソコンを買ったんだけど、性能はいいものの、重すぎて持ち運びに苦労しているんだ。",translation:"Tớ mới mua cái máy tính mới, tính năng tuy tốt thật nhưng nặng quá nên mang đi mang lại vất vả ghê."},{speaker:"B",text:"そうなんだ。画面が大きいタイプを選んだの？",translation:"Vậy à? Cậu chọn loại màn hình lớn hả?"},{speaker:"A",text:"うん。家で作業するにはすごく便利なんだけどね。",translation:"Ừ. Để làm việc ở nhà thì rất tiện nhưng mà..."}]},commonMistake:{wrong:"彼はまだ新入社員ものの、仕事の手際が非常に良い。",correct:"彼はまだ新入社員であるものの、仕事の手際が非常に良い。",why:"Danh từ khi kết hợp với「ものの」bắt buộc phải dùng ở dạng「N + であるものの」, không được ghép trực tiếp."},note:"Khác với「〜くせに」dùng trong văn nói để chỉ trích hay trách móc,「〜ものの」mang tính nhượng bộ khách quan và vế sau tuyệt đối không đi kèm các đuôi câu mệnh lệnh, rủ rê hay yêu cầu (như 〜てください、〜ましょう)."},{pattern:"〜とはいえ",meaning:"Tuy nói vậy / Đúng là…nhưng (đính chính kỳ vọng quá cao)",priority:"common",explanation:'Mẫu ngữ pháp này mang ý nghĩa "Dù nói là... nhưng...", dùng khi người nói thừa nhận một sự thật ở vế trước nhưng vế sau đưa ra nhận định nhằm đính chính hoặc giới hạn lại kỳ vọng. Mẫu câu mang sắc thái trang trọng, thường xuất hiện trong văn viết, báo chí hoặc các cuộc họp trang trọng. Vế sau phản ánh một thực tế không hoàn toàn lý tưởng hay tuyệt đối như những gì người ta dễ suy đoán từ tiền đề vế trước.',examples:[{sentence:"いくら実務経験があるとはいえ、新しい職場では謙虚に学ぶ姿勢が大切だ。",translation:"Dù nói là đã có kinh nghiệm thực tế, nhưng ở môi trường làm việc mới thì thái độ khiêm tốn học hỏi vẫn rất quan trọng."},{sentence:"4月に入って暖かくなってきたとはいえ、朝晩はまだ冷え込む日が多い。",translation:"Tuy nói là sang tháng 4 trời đã ấm dần lên, nhưng sáng và tối vẫn còn nhiều ngày trở lạnh."}],dialogue:{title:"Hỏi thăm sức khỏe đồng nghiệp",lines:[{speaker:"A",text:"熱が下がったとはいえ、まだ無理は禁物ですよ。",translation:"Tuy nói là đã hạ sốt rồi, nhưng anh tuyệt đối không được làm việc quá sức đâu nhé."},{speaker:"B",text:"心配してくれてありがとう。今日は残業せずに早めに帰るよ。",translation:"Cảm ơn em đã lo lắng. Hôm nay anh sẽ không tăng ca mà về sớm."},{speaker:"A",text:"ええ、しっかり休んで完全に治してくださいね。",translation:"Vâng, anh hãy nghỉ ngơi cẩn thận để khỏi hẳn nhé."}]},commonMistake:{wrong:"初心者だとはいえ、基本的なマナーくらいは知っておくべきだ。",correct:"初心者とはいえ、基本的なマナーくらいは知っておくべきだ。",why:"Khi kết hợp với Danh từ và Tính từ đuôi な, 「〜とはいえ」 nối trực tiếp mà không đi kèm trợ động từ 「だ」."},note:"So với 「〜といっても」 được sử dụng phổ biến trong giao tiếp hàng ngày, 「〜とはいえ」 mang tính văn viết và trang trọng hơn rõ rệt."},{pattern:"ものの ≠ のに（N3）",meaning:"Phân biệt: ものの = nhượng bộ khách quan (KHÔNG trách); のに = bất bình, tiếc nuối CỦA NGƯỜI NÓI",priority:"common",explanation:'Cả hai mẫu đều mang nghĩa tương phản "tuy... nhưng...", nhưng khác nhau cơ bản về sắc thái cảm xúc và tính trang trọng. 「ものの」 dùng trong văn phong trang trọng, khách quan để thừa nhận một sự thật/tiền đề trước khi nêu lên một thực tế hoặc hạn chế còn tồn tại mà không mang hàm ý oán trách. Ngược lại, 「のに」 mang đậm tính khẩu ngữ, bộc lộ trực tiếp cảm xúc chủ quan của người nói như bất mãn, thất vọng, tiếc nuối hoặc trách móc khi kết quả trái với mong đợi.',examples:[{sentence:"大学を卒業したものの、希望する職種への就職はなかなか厳しいのが現状だ。",translation:"Tuy đã tốt nghiệp đại học, nhưng thực tế là việc tìm kiếm việc làm đúng chuyên ngành mong muốn vẫn rất khó khăn."},{sentence:"今日は大事なプレゼンがあるのに、彼は事前の連絡もなく遅刻している。",translation:"Hôm nay có buổi thuyết trình quan trọng vậy mà anh ấy lại đi muộn mà không hề có liên lạc báo trước."}],dialogue:{title:"Quyết định học thêm",lines:[{speaker:"A",text:"新しい講座に申し込んだものの、仕事が忙しくて最後まで続けられるか少し不安なんだ。",translation:"Tớ đã đăng ký khóa học mới rồi, nhưng công việc bận rộn quá nên hơi lo không biết có theo được đến cùng không."},{speaker:"B",text:"せっかく高い受講料を払ったんだから、無理のないペースで頑張ってみたら？",translation:"Đã cất công đóng học phí đắt như vậy rồi, hay cậu thử cố gắng với tiến độ vừa sức xem sao?"},{speaker:"A",text:"そうだね、まずは毎回の課題をしっかり提出することから始めてみるよ。",translation:"Ừ nhỉ, trước mắt tớ sẽ bắt đầu từ việc cố gắng nộp bài tập đầy đủ mỗi buổi xem sao."}]},commonMistake:{wrong:"約束したものの、なんで時間通りに来ないの？",correct:"約束したのに、なんで時間通りに来ないの？",why:"「ものの」 chỉ dùng để diễn đạt sự thật nhượng bộ một cách khách quan, không dùng trong câu hỏi chất vấn, thể hiện sự bất bình hoặc trách móc trực tiếp đối phương như 「のに」."},note:"Vế sau của 「ものの」 chỉ nêu hiện thực khách quan, tuyệt đối không đi kèm câu mệnh lệnh, khuyên bảo, rủ rê hay ý chí của người nói."},{pattern:"とはいえ vs ものの の 使[つか]い分[わ]け",meaning:'とはいえ: tiền đề là sự thật ĐƯỢC THỪA NHẬN, đính chính phạm vi → "nhưng cũng không đến nỗi"; ものの: vế trước tạo KỲ VỌNG, vế sau ĐẢO NGƯỢC',priority:"common",explanation:"Cả hai mẫu ngữ pháp đều biểu thị quan hệ nhượng bộ «tuy... nhưng» trong văn phong trang trọng, nhưng có sự khác biệt rõ về chức năng diễn đạt. 「とはいえ」 dùng khi người nói thừa nhận một tiền đề/sự thật ở vế trước rồi đưa ra nhận định, đánh giá hoặc đính chính lại phạm vi ở vế sau (thực tế không đến mức như định kiến hay tên gọi). Trong khi đó, 「ものの」 dùng khi một sự việc thực tế ở vế trước tạo ra kỳ vọng nhất định, nhưng kết quả hoặc trạng thái thực tế xảy ra ở vế sau lại đi ngược lại kỳ vọng đó.",examples:[{sentence:"日本語能力試験N1に合格したとはいえ、まだネイティブのように流暢に話せるわけではない。",translation:"Dẫu biết là đã đỗ JLPT N1, nhưng điều đó không có nghĩa là tôi đã có thể nói lưu loát như người bản xứ."},{sentence:"新しいパソコンを買ったものの、使い方がよく分からなくてほとんど使っていない。",translation:"Tuy đã mua máy tính mới nhưng do chưa hiểu rõ cách dùng nên tôi hầu như chẳng dùng đến."}],dialogue:{title:"Khóa học lập trình",lines:[{speaker:"A",text:"プログラミングスクールに通い始めたものの、難しくて授業についていくのが大変だよ。",translation:"Tuy tớ đã bắt đầu đi học ở trung tâm lập trình, nhưng bài học khó quá nên theo kịp vất vả thật đấy."},{speaker:"B",text:"まだ初心者とはいえ、基礎からしっかり勉強すればきっと慣れてくるよ。",translation:"Dù đúng là mới bắt đầu thật, nhưng nếu cậu học chắc từ căn bản thì nhất định sẽ quen dần thôi."},{speaker:"A",text:"そうだね、諦めずにまずは課題を一つずつ終わらせてみるよ。",translation:"Ừ nhỉ, tớ sẽ không bỏ cuộc mà thử hoàn thành từng bài tập trước xem sao."}]},commonMistake:{wrong:"まだ子供ものの、大人顔負けの意見を言う。",correct:"まだ子供とはいえ、大人顔負けの意見を言う。",why:"「ものの」 không thể kết hợp trực tiếp sau danh từ; khi muốn thừa nhận một danh từ/thân phận làm tiền đề để đưa ra nhận định đối lập ở vế sau, ta dùng trực tiếp 「Danh từ + とはいえ」."},note:"「とはいえ」 nghiêng về việc người nói đưa ra đánh giá, đính chính chủ quan; còn 「ものの」 thường dùng để tường thuật lại một sự thật khách quan đi ngược kỳ vọng và vế sau hầu như không dùng câu mệnh lệnh, rủ rê hay ý chí."}],80:[{pattern:"〜にしても",meaning:"Dù … thì cũng (nhượng bộ thực tế — văn thường lẫn trang trọng)",priority:"core",explanation:'Mẫu câu 「〜にしても」 dùng để diễn đạt ý nghĩa "cho dù là... thì cũng...", trong đó người nói tạm thời thừa nhận một sự thật, lý do hoặc giả định ở vế trước. Vế sau thường thể hiện sự đánh giá, phán đoán, phê bình hoặc cảm xúc bất mãn rằng điều đó vẫn chưa thỏa đáng hoặc không thể chấp nhận được. Cấu trúc này được dùng linh hoạt trong cả hội thoại hàng ngày lẫn các tình huống giao tiếp trang trọng.',examples:[{sentence:"いくら仕事が忙しいにしても、体調管理はおろそかにしてはいけない。",translation:"Dù công việc có bận rộn đến đâu đi nữa thì cũng không được lơ là việc chăm sóc sức khỏe."},{sentence:"冗談のつもりだったにしても、あんな酷いことを言うべきではなかった。",translation:"Dù có định là nói đùa đi chăng nữa thì cũng không nên nói những lời tồi tệ như thế."}],dialogue:{title:"Nhắc nhở việc đi muộn",lines:[{speaker:"A",text:"田中さん、また遅刻ですね。電車が遅れたそうですが。",translation:"Anh Tanaka, lại đi muộn nữa rồi nhé. Nghe nói là do tàu điện bị trễ à?"},{speaker:"B",text:"申し訳ありません。途中で信号トラブルがあって30分も止まってしまいまして…。",translation:"Tôi rất xin lỗi. Giữa đường gặp sự cố tín hiệu nên tàu bị dừng mất 30 phút..."},{speaker:"A",text:"電車の遅延にしても、遅れると分かった時点ですぐ連絡を入れるべきですよ。",translation:"Dù là do tàu trễ đi nữa thì ngay thời điểm biết sẽ muộn anh cũng phải liên lạc báo ngay chứ."}]},commonMistake:{wrong:"初心者だにしても、このくらいのミスは確認すれば防げたはずだ。",correct:"初心者（である）にしても、このくらいのミスは確認すれば防げたはずだ。",why:"Danh từ và tính từ đuôi な khi kết hợp với 「〜にしても」 không đi cùng 「だ」 mà nối trực tiếp hoặc dùng dạng 「である＋にしても」."},note:"So với 「〜としても」 (thuần túy đưa ra giả định giả thuyết), 「〜にしても」 mang sắc thái chấp nhận một lý do hay thực tế nhưng vẫn nhấn mạnh sự phê phán hoặc đòi hỏi ở vế sau."},{pattern:"〜としても",meaning:"Giả sử dù … thì cũng (giả định chưa xảy ra — mang sắc phủ định / khó khăn)",priority:"common",explanation:'Mẫu「〜としても」dùng để đưa ra một giả định có khả năng xảy ra thấp hoặc tình huống chưa diễn ra trong thực tế ("giả sử cho dù... thì cũng"). Cấu trúc này đi liền sau thể thông thường (普通形) của động từ, tính từ và danh từ (danh từ và tính từ đuôi -na thường đi với だとしても hoặc としても). Vế sau hầu như luôn thể hiện sự đánh giá, phán đoán mang tính tiêu cực, khó khăn, hoặc chỉ ra rằng sự việc ở vế trước là vô ích, không làm thay đổi được cục diện.',examples:[{sentence:"今からタクシーに乗ったとしても、飛行機の出発時刻には間に合わないだろう。",translation:"Cho dù bây giờ có đi taxi đi chăng nữa thì chắc cũng không kịp giờ máy bay cất cánh đâu."},{sentence:"たとえ給料が高いとしても、あんなに労働環境が悪い会社では働きたくない。",translation:"Giả sử mức lương có cao đi chăng nữa thì tôi cũng không muốn làm việc ở một công ty có môi trường tồi tệ như vậy."}],dialogue:{title:"Kế hoạch leo núi cuối tuần",lines:[{speaker:"A",text:"明日の登山、天気予報では午後から大雨らしいよ。中止にしたほうがいいんじゃない？",translation:"Chuyến leo núi ngày mai nghe nói dự báo thời tiết chiều có mưa to đấy. Hay là hủy đi thì hơn?"},{speaker:"B",text:"朝早く出発するとしても、下山する頃には雨に降られそうだね。",translation:"Cho dù có xuất phát từ sáng sớm đi nữa thì có vẻ lúc xuống núi vẫn sẽ bị dính mưa nhỉ."},{speaker:"A",text:"そうだね。安全が一番だから、来週に延期しよう。",translation:"Đúng vậy. An toàn là trên hết nên chúng ta dời sang tuần sau đi."}]},commonMistake:{wrong:"明日暇だとしても、一緒に買い物に行きましょう。",correct:"明日暇なら、一緒に買い物に行きましょう。",why:"Mẫu「〜としても」chỉ dùng cho giả định mang sắc thái tiêu cực hoặc bất lực (vế sau vô ích/không giải quyết được vấn đề), không dùng để rủ rê, đề xuất hành động tích cực như「〜ましょう」."},note:"Cần phân biệt với「〜にしても」:「〜としても」thuần túy là giả định chưa xảy ra (khả năng thấp), còn「〜にしても」có thể dùng để công nhận một sự thật/hiện thực đã và đang tồn tại."},{pattern:"〜にせよ／〜にしろ",meaning:"Dù … thì cũng (văn VIẾT trang trọng = にしても); A にせよ B にせよ = dù A hay B",priority:"common",explanation:'Mẫu câu 「〜にせよ／〜にしろ」 mang ý nghĩa "cho dù là... thì cũng...", dùng để đưa ra một sự thật hoặc tình huống giả định và kèm theo nhận định, phán đoán dứt khoát ở vế sau. Khi sử dụng dưới dạng lặp lại 「AにせよBにせよ」, mẫu này mang nghĩa "dù là A hay B thì kết luận, trách nhiệm vẫn không đổi". So với 「〜にしても」, mẫu 「〜にせよ」 mang sắc thái trang trọng, dứt khoát hơn và chủ yếu xuất hiện trong văn viết, báo chí hoặc bài phát biểu chính thức.',examples:[{sentence:"どんなに忙しいにせよ、事前に連絡の一本くらいは入れておくべきだった。",translation:"Dù có bận rộn đến mức nào đi nữa, ít nhất bạn cũng nên gửi một lời thông báo từ trước."},{sentence:"賛成するにせよ反対するにせよ、自分の意見とその理由を明確に述べてください。",translation:"Dù tán thành hay phản đối thì xin hãy nêu rõ ý kiến cùng lý do của mình."}],dialogue:{title:"Quyết định chuyển việc",lines:[{speaker:"A",text:"転職するにせよ会社に残るにせよ、まずは今のプロジェクトを最後までやり遂げるつもりです。",translation:"Dù chuyển việc hay ở lại công ty, trước hết tôi cũng dự định sẽ hoàn thành dự án hiện tại đến cùng."},{speaker:"B",text:"その姿勢は素晴らしいですね。しっかり実績を残しておけば、次の道でも必ず評価されますよ。",translation:"Tinh thần đó thật tuyệt vời. Nếu tạo dựng được thành tích vững chắc thì ở con đường tiếp theo bạn nhất định cũng sẽ được đánh giá cao."},{speaker:"A",text:"ありがとうございます。どんな結果になるにしろ、全力を尽くして頑張ります。",translation:"Cảm ơn anh/chị. Dù kết quả có thế nào đi nữa, tôi cũng sẽ nỗ lực hết mình."}]},commonMistake:{wrong:"初心者だにせよ、現場の基本ルールは守らなければならない。",correct:"初心者であるにせよ、現場の基本ルールは守らなければならない。",why:"Danh từ và tính từ đuôi な khi kết hợp với 「〜にせよ」 không đi với 「だ」 mà phải ghép trực tiếp (初心者 + にせよ) hoặc dùng dạng 「であるにせよ」."},note:"「〜にせよ」 và 「〜にしろ」 có ý nghĩa tương đương với 「〜にしても」, nhưng 「〜にせよ」 mang tính văn viết trang trọng nhất, tiếp đến là 「〜にしろ」, còn 「〜にしても」 thường dùng trong văn nói hàng ngày."},{pattern:"A にせよ B にせよ",meaning:"Dù A hay B thì cũng… (liệt kê hai khả năng đối lập, kết luận không đổi)",priority:"common",explanation:"Mẫu ngữ pháp này dùng để đưa ra hai trường hợp đối lập hoặc cùng một nhóm lựa chọn, nhằm nhấn mạnh rằng dù rơi vào khả năng nào thì kết luận, phán đoán hay nghĩa vụ ở vế sau vẫn không thay đổi. Vế sau thường thể hiện ý chí, lời khuyên, nhận định hoặc sự thật hiển nhiên. Đây là cách diễn đạt mang sắc thái trang trọng, thường xuất hiện trong văn viết, nghị luận hoặc các phát biểu lịch sự.",examples:[{sentence:"賛成するにせよ反対するにせよ、会議では自分の意見を明確に述べるべきだ。",translation:"Dù tán thành hay phản đối thì trong cuộc họp cũng nên trình bày rõ ràng ý kiến của mình."},{sentence:"進学するにせよ就職するにせよ、早めに将来の計画を立てておいたほうがいい。",translation:"Dù học lên tiếp hay đi làm thì bạn cũng nên lập kế hoạch tương lai từ sớm."}],dialogue:{title:"Kế hoạch tổ chức tiệc",lines:[{speaker:"A",text:"来週の送別会、参加するにせよ不参加にせよ、明日までに返事をくれる？",translation:"Bữa tiệc chia tay tuần tới, dù tham gia hay không tham gia thì cậu trả lời cho mình trước ngày mai nhé?"},{speaker:"B",text:"了解。まだ残業があるか分からないから、今夜中には決めて連絡するよ。",translation:"Hiểu rồi. Tớ vẫn chưa biết có phải tăng ca không nên trong tối nay tớ sẽ quyết định rồi báo lại nhé."},{speaker:"A",text:"ありがとう。人数が確定しないと予約が取れないから助かるよ。",translation:"Cảm ơn cậu. Chưa chốt được số lượng người thì không đặt chỗ được nên giúp ích cho mình nhiều lắm."}]},commonMistake:{wrong:"プロだにせよアマチュアだにせよ、ルールは守らなければならない。",correct:"プロにせよアマチュアにせよ、ルールは守らなければならない。",why:"Khi đi với danh từ hoặc tính từ đuôi な, ta nối trực tiếp với 「にせよ」 (hoặc dùng 「であるにせよ」), tuyệt đối không gắn 「だ」 trước 「にせよ」."},note:"Mẫu 「〜にせよ〜にせよ」 có thể thay thế bằng 「〜にしろ〜にしろ」 hoặc 「〜にしても〜にしても」, trong đó 「にせよ」 mang sắc thái trang trọng, văn viết nhất, còn 「にしろ」「にしても」 dùng tự nhiên hơn trong hội thoại giao tiếp hàng ngày."}],81:[{pattern:"（可能形[かのうけい]）ものなら",meaning:"Giá mà có thể… (mong ước điều khó/không thể)",priority:"core",explanation:"Mẫu câu này dùng để diễn đạt mong ước về một điều gần như không thể thực hiện được hoặc rất khó xảy ra trong thực tế. Động từ ở vế trước luôn được chia ở thể khả năng (可能形), còn vế sau thường đi cùng các cách diễn đạt thể hiện nguyện vọng mãnh liệt của người nói như 〜たい、〜てみたい. Mẫu này thường mang sắc thái tiếc nuối, khao khát sâu sắc đối với những điều không tưởng như quay ngược thời gian hay thay đổi số phận.",examples:[{sentence:"生まれ変われるものなら、鳥になって大空を自由に飛び回りたい。",translation:"Nếu có thể được tái sinh, tôi muốn làm chim để tự do bay lượn khắp bầu trời rộng lớn."},{sentence:"病気で苦しむ子どもの痛みを代わってあげられるものなら、今すぐにでも代わってやりたい。",translation:"Giá mà có thể gánh thay nỗi đau cho đứa con đang chịu đau đớn vì bạo bệnh, tôi sẵn sàng gánh thay ngay lập tức."}],dialogue:{title:"Ước mơ quay ngược thời gian",lines:[{speaker:"A",text:"最近仕事のプレッシャーがすごくて、時間を巻き戻せるものなら学生時代に戻りたいよ。",translation:"Dạo này áp lực công việc lớn quá, giá mà quay ngược được thời gian thì tôi chỉ muốn trở lại thời sinh viên thôi."},{speaker:"B",text:"気持ちは分かるけど、過去には戻れないから、今度の連休に温泉でも行ってリフレッシュしようよ。",translation:"Tôi hiểu cảm xúc của bạn mà, nhưng quá khứ đâu thể quay lại được, đợt nghỉ tới cùng đi suối nước nóng xả hơi nhé."},{speaker:"A",text:"そうだね、現実逃避ばかりしていないで、週末を楽しみに頑張るよ。",translation:"Ừ nhỉ, không thể cứ trốn tránh thực tại mãi được, tôi sẽ cố gắng và chờ đón dịp cuối tuần."}]},commonMistake:{wrong:"過去に戻るものなら、あの時の失敗をやり直したい。",correct:"過去に戻れるものなら、あの時の失敗をやり直したい。",why:"Vế trước của mẫu câu mang ý nghĩa mong ước bất khả thi này bắt buộc phải chia ở thể khả năng (戻れる) chứ không dùng thể từ điển thông thường."},note:"Cần tránh nhầm lẫn với mẫu「〜ようものなら」(động từ thể ý chí + ものなら) vốn dùng để cảnh báo hậu quả nghiêm trọng nếu lỡ thực hiện một hành động nào đó."},{pattern:"（意向形[いこうけい]）ようものなら",meaning:"Hễ lỡ làm… thì hậu quả NGHIÊM TRỌNG",priority:"common",explanation:'Mẫu câu 「～ようものなら」 dùng để đưa ra giả định về một hành động không nên làm hoặc một sự cố bất ngờ: "Hễ lỡ làm... / Nếu mà... thì hậu quả vô cùng nghiêm trọng". Ngữ pháp này kết hợp với động từ chia ở thể ý chí (意向形 + ものなら), mang sắc thái cảnh báo, đe dọa hoặc lo lắng sâu sắc. Vế sau luôn luôn là một kết cục tồi tệ, tiêu cực (bị trừng phạt, mắng mỏ, gặp nguy hiểm...) và tuyệt đối không đi với kết quả mang ý nghĩa tích cực.',examples:[{sentence:"あの厳しい先生の授業に5分でも遅れようものなら、教室に入れてもらえない。",translation:"Hễ lỡ đến muộn dù chỉ 5 phút trong tiết học của giáo viên nghiêm khắc đó thì sẽ không được phép vào lớp."},{sentence:"この会社の機密データを外部に漏洩しようものなら、多額の損害賠償を請求される。",translation:"Hễ lỡ làm rò rỉ dữ liệu tuyệt mật của công ty này ra bên ngoài thì sẽ bị yêu cầu bồi thường thiệt hại một khoản tiền khổng lồ."}],dialogue:{title:"Áp lực sếp mới",lines:[{speaker:"A",text:"今度の新しい部長、ミスに対してすごく厳しいらしいよ。",translation:"Nghe nói vị trưởng phòng mới đợt này cực kỳ khắt khe với lỗi sai đấy."},{speaker:"B",text:"えっ、そうなの？じゃあ日頃から報告や確認を忘れないようにしないとね。",translation:"Hả, thế á? Vậy thì hàng ngày phải chú ý đừng quên báo cáo với kiểm tra kỹ nhé."},{speaker:"A",text:"うん、提出期限に1日でも遅れようものなら、みんなの前で怒鳴りつけられるらしいよ。",translation:"Ừ, hễ lỡ trễ hạn nộp dù chỉ một ngày là nghe đồn sẽ bị mắng té tát trước mặt mọi người đấy."}]},commonMistake:{wrong:"宝くじで1億円が当たろうものなら、世界一周旅行に行きたい。",correct:"もし宝くじで1億円が当たったら、世界一周旅行に行きたい。",why:"「～ようものなら」 chỉ dùng khi vế sau là hậu quả tồi tệ hoặc nguy hiểm, không dùng cho sự việc may mắn hay nguyện vọng tích cực của bản thân."},note:'Cần phân biệt với mẫu 「～ものなら」 đi với động từ thể khả năng (V-れる + ものなら) mang nghĩa "Giá mà có thể..." (ước muốn điều khó thực hiện), còn 「～ようものなら」 đi với thể ý chí mang nghĩa "Hễ lỡ... thì nguy to".'},{pattern:"ものなら ≠ ようものなら （形[けい]と意味[いみ]の違[ちが]い）",meaning:"Phân biệt: ものなら = mong ước (可能形+); ようものなら = cảnh báo hậu quả (意向形+)",priority:"common",explanation:"「〜ものなら」kết hợp với động từ thể khả năng dùng để biểu đạt nguyện vọng tha thiết về một điều khó hoặc không thể thực hiện được, vế sau thường đi kèm「〜たい／〜てみたい」. Ngược lại,「〜ようものなら」kết hợp với động từ thể ý chí mang ý nghĩa giả định 'nếu lỡ/hễ làm điều đó', dùng để cảnh báo về một hậu quả vô cùng nghiêm trọng ở vế sau. Điểm cốt lõi để phân biệt hai mẫu này nằm ở thể chia của động từ (Khả năng vs Ý chí) và tính chất của kết quả (Nguyện vọng vs Hậu quả tiêu cực).",examples:[{sentence:"生まれ変われるものなら、次は鳥になって大空を自由に飛び回りたい。",translation:"Nếu có thể được tái sinh, kiếp sau tôi muốn làm một chú chim bay lượn tự do trên bầu trời."},{sentence:"この極秘プロジェクトの情報をもらそうものなら、即座に懲戒免職になるだろう。",translation:"Nếu lỡ làm rò rỉ thông tin của dự án tối mật này thì chắc chắn sẽ bị sa thải kỷ luật ngay lập tức."}],dialogue:{title:"Hạn nộp bản kế hoạch",lines:[{speaker:"A",text:"企画書の作成、締め切りに間に合いそう？",translation:"Việc làm bản kế hoạch có kịp hạn chót không?"},{speaker:"B",text:"今夜徹夜してでも終わらせるよ。課長への提出が遅れようものなら、どれほど怒られるか分からないからね。",translation:"Dù tối nay phải thức trắng đêm tôi cũng làm cho xong. Bởi nếu lỡ nộp muộn cho trưởng nhóm thì chẳng biết sẽ bị mắng đến mức nào đâu."},{speaker:"A",text:"大変だね。手伝えるものなら手伝いたいけれど、私も自分の仕事で手一杯なんだ。",translation:"Vất vả thật đấy. Nếu có thể giúp được thì tôi cũng muốn giúp, nhưng tôi cũng đang ngập đầu trong việc của mình rồi."}]},commonMistake:{wrong:"過去に戻ろうものなら、もう一度人生をやり直したい。",correct:"過去に戻れるものなら、もう一度人生をやり直したい。",why:"Vế sau diễn tả nguyện vọng, mong ước (〜たい) nên động từ bắt buộc phải chia ở thể khả năng + ものなら, không được dùng thể ý chí + ようものなら (vốn chỉ dùng cho cảnh báo hậu quả tồi tệ)."},note:"Ghi nhớ mẹo phân biệt: 「可能形 ＋ ものなら」 hướng tới ước muốn (thường đi với 〜たい), còn 「意向形 ＋ ようものなら」 hướng tới rủi ro, nguy hiểm (thường đi với 〜大変なことになる／〜に違いない)."},{pattern:"動詞辞書形[どうしじしょけい] ＋ ものなら（仮定[かてい]・警告[けいこく]）",meaning:'ものなら với từ điển-form: cảnh báo "nếu có làm thì…" (= ようものなら nhưng văn phong khác)',priority:"common",explanation:"Mẫu ngữ pháp này kết hợp với động từ thể từ điển (V-る + ものなら) dùng để đưa ra một giả định mang tính cảnh báo hoặc đe dọa: 'Nếu lỡ thực hiện hành động đó thì sẽ dẫn đến hậu quả khôn lường'. Vế sau luôn đi kèm với kết quả tiêu cực, nguy hiểm hoặc trừng phạt nghiêm khắc. Ngữ cảnh thường dùng trong văn phong răn đe, nhắc nhở nghiêm túc giữa cấp trên với cấp dưới, cha mẹ với con cái, hoặc tự nhắc nhở bản thân.",examples:[{sentence:"会社の機密情報を外部に漏らすものなら、即座に解雇されるに違いない。",translation:"Nếu lỡ làm rò rỉ thông tin cơ mật của công ty ra ngoài, chắc chắn sẽ bị sa thải ngay lập tức."},{sentence:"あの厳しい先生の授業で居眠りでもするものなら、教室から追い出されてしまうよ。",translation:"Nếu mà lỡ ngủ gật trong giờ học của giáo viên nghiêm khắc ấy thì sẽ bị đuổi ra khỏi lớp ngay đấy."}],dialogue:{title:"Cảnh báo tiến độ công việc",lines:[{speaker:"A",text:"提出の締め切りに遅れるものなら、部長にどれほど怒られるか分からないよ。",translation:"Nếu mà trễ hạn nộp thì không biết sẽ bị trưởng phòng mắng dữ đến mức nào đâu."},{speaker:"B",text:"そうだね。残業してでも今日中に終わらせないとまずいね。",translation:"Đúng thế nhỉ. Dù có phải làm thêm giờ thì không xong trong hôm nay là nguy to đấy."},{speaker:"A",text:"うん、手伝えることがあったら遠慮なく言ってね。一緒に乗り切ろう。",translation:"Ừ, có gì cần giúp thì cứ nói đừng ngại nhé. Cùng nhau vượt qua nào."}]},commonMistake:{wrong:"この秘密を誰かに話せるものなら、大変なことになる。",correct:"この秘密を誰かに話すものなら、大変なことになる。",why:"Khi mang ý nghĩa cảnh báo hậu quả xấu ('nếu lỡ làm... thì gay'), bắt buộc phải dùng động từ thể từ điển (話す), không dùng thể khả năng (話せる) vì thể khả năng chỉ dùng cho mong ước điều khó thành."},note:"Mẫu 「V-る + ものなら」 mang tính cảnh báo tương tự như 「V-ようものなら」, nhưng cần đặc biệt tránh nhầm với 「V-khả năng + ものなら」 mang nghĩa nguyện vọng ('Giá mà có thể... thì muốn')."}],82:[{pattern:"〜たところで",meaning:"Dù có làm X cũng vô ích (kết quả luôn phủ định)",priority:"core",explanation:"Mẫu 「〜たところで」 diễn tả ý nghĩa dù có thực hiện một hành động nào đó thì cũng vô ích, không đem lại kết quả hay thay đổi được tình hình thực tế. Cấu trúc này luôn kết hợp với động từ thể quá khứ (Vた) và vế sau bắt buộc phải mang ý nghĩa phủ định, tiêu cực hoặc phán đoán như「〜ない」「〜無駄だ」. Mẫu câu thường thể hiện sự bất lực, khuyên can hoặc đánh giá chủ quan đầy thất vọng của người nói.",examples:[{sentence:"今さら後悔したところで、過去を変えることはできない。",translation:"Dù bây giờ có hối hận đi chăng nữa thì cũng không thể thay đổi được quá khứ."},{sentence:"どんなに謝ったところで、彼女が許してくれるとは思えない。",translation:"Dù có xin lỗi đến thế nào đi nữa thì tôi cũng không nghĩ rằng cô ấy sẽ tha thứ."}],dialogue:{title:"Chuẩn bị cho kỳ thi",lines:[{speaker:"A",text:"試験は明日なのに、今から焦って勉強したところで、結果は変わらないよ。",translation:"Ngày mai thi rồi, bây giờ dù có cuống cuồng học đi nữa thì kết quả cũng chẳng thay đổi được đâu."},{speaker:"B",text:"そうかもしれないけど、何もしないよりは少しでも復習しておきたいんだ。",translation:"Có thể là vậy, nhưng thà ôn lại một chút còn hơn là không làm gì cả."},{speaker:"A",text:"無理して徹夜しても体を壊すだけだから、早く寝たほうがいいよ。",translation:"Cố thức khuya cũng chỉ tổ hại sức khỏe thôi, cậu nên đi ngủ sớm đi."}]},commonMistake:{wrong:"いくら頼んだところで、彼はきっと手伝ってくれる。",correct:"いくら頼んだところで、彼は手伝ってくれないだろう。",why:"Vế sau của 「〜たところで」 bắt buộc phải là kết quả phủ định hoặc vô ích, không được dùng với kết quả tích cực hay mang tính kỳ vọng."},note:"Khác với 「〜ても」 có thể đi cùng kết quả tích cực, 「〜たところで」 luôn đi với vế sau mang nghĩa tiêu cực, vô ích hoặc không đạt được mục đích."},{pattern:"〜からといって",meaning:"Không phải chỉ vì X mà (phủ nhận suy luận)",priority:"common",explanation:'Mẫu câu này dùng để diễn đạt ý nghĩa "không phải cứ vì lý do A mà đương nhiên sẽ dẫn đến kết quả B". Vế sau luôn đi kèm với các dạng phủ định như phủ định một phần 「〜わけではない」(không hẳn là), 「〜とは限らない」(chưa chắc là) hoặc cấm đoán, khuyên bảo 「〜てはいけない / 〜ない」. Mẫu này thường dùng khi muốn bác bỏ suy nghĩ ngộ nhận, phiến diện hoặc nhắc nhở hành vi của đối phương.',examples:[{sentence:"日本に住んでいるからといって、誰もが日本語を上手に話せるわけではない。",translation:"Không phải cứ sống ở Nhật là ai cũng nói giỏi tiếng Nhật đâu."},{sentence:"いくら忙しいからといって、連絡もなしに遅刻するのは失礼ですよ。",translation:"Dù có bận rộn đến mấy đi nữa thì việc đi muộn mà không báo trước là rất thất lễ đấy."}],dialogue:{title:"Lời khuyên mua sắm",lines:[{speaker:"A",text:"有名なブランドだからといって、全部自分の体に合うとは限らないよ。",translation:"Không phải cứ là hàng hiệu nổi tiếng thì cái nào cũng vừa vặn với người mình đâu."},{speaker:"B",text:"そうですね。デザインや人気だけで決めるのは良くないですね。",translation:"Đúng thế thật. Chỉ quyết định dựa trên thiết kế hay độ nổi tiếng thì không nên chút nào."},{speaker:"A",text:"うん、実際に試着してみてから買ったほうが失敗しないよ。",translation:"Ừ, cứ thử đồ trực tiếp rồi hãy mua thì sẽ tránh được việc mua nhầm đấy."}]},commonMistake:{wrong:"便利だからといって、AIに頼りきりになります。",correct:"便利だからといって、AIに頼りきりになってはいけません。",why:"Vế sau của 「〜からといって」 bắt buộc phải mang tính phủ định (〜わけではない, 〜とは限らない) hoặc khuyên can, cấm đoán (〜てはいけない), không được dùng câu khẳng định đơn thuần để kể lại hành động."},note:"Khác với liên từ nhượng bộ thông thường như 「〜ても」(dù... nhưng), 「〜からといって」 nhấn mạnh việc bác bỏ mối quan hệ nhân quả tất nhiên mà người khác lầm tưởng."},{pattern:"たところで ≠ ても（N3）",meaning:"たところで = nhấn mạnh vô ích (vế sau PHỦ ĐỊNH); ても = nhượng bộ trung tính (vế sau tự do)",priority:"common",explanation:'「〜たところで」mang ý nghĩa "dù có làm... thì cũng vô ích", vế sau bắt buộc phải là kết quả tiêu cực, phủ định hoặc phán đoán không mang lại tác dụng gì (không thể, vô nghĩa). Trong khi đó, «〜ても» là cấu trúc nhượng bộ trung tính biểu thị "cho dù... thì vẫn...", vế sau hoàn toàn tự do và có thể là kết quả tích cực, câu mệnh lệnh hoặc ý chí. Vì vậy, chỉ dùng «〜たところで» khi muốn nhấn mạnh sự bất lực và tính chất vô ích của hành động.',examples:[{sentence:"いくら急いで走ったところで、もう最終電車には間に合わない。",translation:"Dù có vắt chân lên cổ chạy nhanh đến đâu thì cũng chẳng kịp chuyến tàu cuối nữa rồi."},{sentence:"どんなに失敗しても、最後まで諦めずに挑戦し続けるつもりだ。",translation:"Dù có thất bại thế nào đi nữa, tôi vẫn dự định kiên trì thử sức đến cùng mà không từ bỏ."}],dialogue:{title:"Ôn thi phút chót",lines:[{speaker:"A",text:"試験は明日なのに、今から徹夜して勉強したところで結果は変わらないよ。",translation:"Mai thi rồi, giờ có thức trắng đêm học đi nữa thì kết quả cũng chẳng thay đổi được đâu."},{speaker:"B",text:"そうかもしれないけど、何もしないより少しでも復習したほうが安心するんだ。",translation:"Có thể là vậy, nhưng ôn lại được chút nào thì vẫn yên tâm hơn là không làm gì."},{speaker:"A",text:"無理して体調を崩したら本末転倒だから、早く寝たほうがいいよ。",translation:"Cố quá rồi ngã bệnh thì lại hỏng việc, cậu nên ngủ sớm đi."}]},commonMistake:{wrong:"どんなに大変だったところで、諦めなければ必ず成功できる。",correct:"どんなに大変であっても、諦めなければ必ず成功できる。",why:"Vế sau của «〜たところで» bắt buộc phải là kết quả tiêu cực, phủ định hoặc vô ích, không được dùng với kết quả tích cực hay biểu thị kỳ vọng như «成功できる»."},note:"«〜たところで» thường hay đi kèm với các từ như いくら (dù bao nhiêu), どんなに (dù thế nào), 今さら (giờ này có... cũng muộn) để nhấn mạnh sự vô ích."},{pattern:"からといって ≠ からには",meaning:"からといって = phủ nhận hệ quả tất yếu; からには = khẳng định hệ quả tất yếu",priority:"common",explanation:"「〜からといって」dùng để phủ định một hệ quả tất yếu, mang nghĩa 'dù có lý do A đi nữa thì không hẳn/không được dẫn đến kết quả B', vế sau thường đi kèm các dạng phủ định như 〜わけではない、〜とは限らない. Trái lại,「〜からには」dùng để khẳng định một hệ quả tất yếu xuất phát từ một tiền đề, mang nghĩa 'một khi đã A thì đương nhiên phải/quyết tâm làm B'. Điểm mấu chốt để phân biệt là vế sau của「からといって」bác bỏ sự việc thông thường, còn「からには」đòi hỏi trách nhiệm, nghĩa vụ hoặc ý chí mạnh mẽ.",examples:[{sentence:"日本に住んでいるからといって、誰もが日本語を上手に話せるわけではない。",translation:"Không phải cứ sống ở Nhật là ai cũng có thể nói tiếng Nhật trôi chảy."},{sentence:"留学を決めたからには、目標の資格を取るまで諦めずに頑張るつもりだ。",translation:"Một khi đã quyết định đi du học thì tôi dự định sẽ nỗ lực không bỏ cuộc cho đến khi đạt được chứng chỉ mục tiêu."}],dialogue:{title:"Chuẩn bị thi JLPT",lines:[{speaker:"A",text:"模擬試験でいい点が取れたからといって、油断しちゃだめだよ。",translation:"Chỉ vì đạt điểm cao ở bài thi thử mà chủ quan lơ là là không được đâu đấy."},{speaker:"B",text:"うん、わかってる。N2を受験すると決めたからには、最後まで全力で復習するよ。",translation:"Ừ, tớ biết rồi. Một khi đã quyết định thi N2 thì tớ sẽ dốc toàn lực ôn tập đến cùng."},{speaker:"A",text:"その意気だね！一緒に合格を目指して頑張ろう。",translation:"Tinh thần tốt đấy! Cùng nhau cố gắng để đỗ nhé."}]},commonMistake:{wrong:"約束したからといって、絶対に守らなければならない。",correct:"約束したからには、絶対に守らなければならない。",why:"Vế sau là nghĩa vụ/bắt buộc (〜なければならない) nên phải dùng「からには」để khẳng định trách nhiệm tất yếu, trong khi「からといって」chỉ đi với vế sau mang nghĩa phủ nhận."},note:"Mẹo ghi nhớ nhanh theo đuôi câu:「からといって」thường đi với đuôi phủ định (〜わけではない、〜とは限らない、〜てはいけない), còn「からには」luôn đi với đuôi thể hiện nghĩa vụ/ý chí (〜べきだ、〜なければならない、〜つもりだ)."}],83:[{pattern:"〜において（は）／〜における",meaning:"Tại / trong (lĩnh vực, thời đại, địa điểm — văn viết trang trọng)",priority:"core",explanation:"Mẫu ngữ pháp này dùng để biểu thị địa điểm diễn ra sự kiện, thời kỳ/thời đại lịch sử, hoặc lĩnh vực, phạm vi mà một trạng thái, hiện tượng tồn tại. Về ý nghĩa, mẫu này tương đương với trợ từ 「で」 nhưng mang sắc thái trang trọng, lịch sự và mang tính văn viết cao hơn nhiều. Khi bổ nghĩa trực tiếp cho danh từ đi kèm phía sau, mẫu sẽ biến đổi thành dạng 「〜における＋N」. Cấu trúc này thường xuyên xuất hiện trong các bài phát biểu trang trọng, tin tức thời sự, luận văn và báo cáo công việc.",examples:[{sentence:"現代の医療分野において、AI技術の活用が急速に進んでいる。",translation:"Trong lĩnh vực y tế hiện đại, việc ứng dụng công nghệ AI đang tiến triển nhanh chóng."},{sentence:"21世紀における最大の課題は、地球温暖化への対策である。",translation:"Thách thức lớn nhất trong thế kỷ 21 là các biện pháp đối phó với hiện tượng nóng lên toàn cầu."}],dialogue:{title:"Thảo luận về dự án",lines:[{speaker:"A",text:"今回のプロジェクトにおいて、私たちが最も注力すべき点は何でしょうか。",translation:"Trong dự án lần này, điểm mà chúng ta nên tập trung nhất là gì ạ?"},{speaker:"B",text:"やはり、顧客データの安全管理を徹底することだと思います。",translation:"Tôi nghĩ trọng tâm vẫn là việc thực hiện triệt để quản lý an toàn dữ liệu khách hàng."},{speaker:"A",text:"承知いたしました。セキュリティ部門と連携して進めてまいります。",translation:"Tôi đã rõ. Tôi sẽ phối hợp cùng bộ phận an ninh mạng để tiến hành."}]},commonMistake:{wrong:"昨日の夜、自分の部屋において映画を見ました。",correct:"昨日の夜、自分の部屋で映画を見ました。",why:"「〜において」 mang sắc thái rất trang trọng nên không dùng cho các hành động sinh hoạt cá nhân, đời thường; trường hợp này chỉ dùng trợ từ 「で」."},note:"Khi muốn dùng cụm này để bổ nghĩa trực tiếp cho một danh từ đứng liền sau thì bắt buộc phải chuyển sang dạng 「〜における＋N」."},{pattern:"〜にわたって（は）／〜にわたる",meaning:"Suốt / trải khắp (thời kỳ kéo dài hoặc phạm vi rộng)",priority:"common",explanation:"Mẫu câu này đi sau danh từ chỉ thời gian, phạm vi không gian, số lần hoặc quy mô nhằm diễn tả một trạng thái, hiện tượng hay hành động kéo dài liên tục hoặc trải rộng khắp toàn bộ phạm vi đó. Khi bổ nghĩa cho danh từ phía sau, cấu trúc chuyển thành「〜にわたる＋N」, còn khi bổ nghĩa cho động từ thì dùng「〜にわたって／〜にわたり」. Mẫu này mang sắc thái trang trọng, thường xuất hiện trong các bản tin thời sự, báo chí hoặc báo cáo để nhấn mạnh tính quy mô lớn và thời gian kéo dài hơn bình thường.",examples:[{sentence:"3年間にわたる研究の末、チームはついに新薬の開発に成功した。",translation:"Sau 3 năm ròng rã nghiên cứu, cả đội cuối cùng đã phát triển thành công loại thuốc mới."},{sentence:"今回の大型台風の影響で、関東全域にわたって激しい雨と風が続いている。",translation:"Do ảnh hưởng của cơn bão lớn lần này, mưa to và gió giật mạnh đang tiếp tục diễn ra trên khắp toàn bộ khu vực Kanto."}],dialogue:{title:"Kế hoạch sửa chữa cầu",lines:[{speaker:"A",text:"駅前の歩道橋工事、来週から始まるらしいよ。半年間にわたって通行止めになるんだって。",translation:"Nghe nói công trình cầu vượt trước ga sẽ bắt đầu từ tuần sau đấy. Bảo là sẽ cấm đường suốt 6 tháng liền."},{speaker:"B",text:"ええ、半年も？通勤で毎日使っているから、かなり不便になりそうだね。",translation:"Hả, tận nửa năm cơ à? Ngày nào tớ cũng đi làm qua đó nên chắc sẽ bất tiện lắm đây."},{speaker:"A",text:"うん、迂回路を使うしかないから、朝は少し早めに出たほうがいいね。",translation:"Ừ, chỉ còn cách đi đường vòng thôi, nên buổi sáng chúng mình nên xuất phát sớm hơn một chút."}]},commonMistake:{wrong:"昨日は疲れていたので、30分にわたって昼寝をしました。",correct:"昨日は疲れていたので、30分間昼寝をしました。",why:"「〜にわたって」chỉ dùng để nhấn mạnh khoảng thời gian dài hoặc quy mô rộng lớn đáng kể, không dùng cho khoảng thời gian ngắn hay sinh hoạt vụn vặt hàng ngày."},note:"Khác với「〜を通じて／〜を通して」(thường mang nghĩa 'suốt cả một kỳ/giai đoạn' hoặc 'thông qua phương tiện/trung gian'),「〜にわたって」nhấn mạnh vào độ dài thời gian, quy mô hoặc diện tích trải rộng vượt trội của sự việc."},{pattern:"において ≠ にわたって",meaning:"において = địa điểm/lĩnh vực (một điểm/phạm vi cố định); にわたって = suốt khoảng thời gian hoặc trải rộng khắp",priority:"common",explanation:"「において」dùng để chỉ địa điểm, thời điểm hoặc lĩnh vực cụ thể mà một sự việc diễn ra (tương đương với「で」nhưng trang trọng hơn, mang tính điểm mốc hoặc phạm vi cố định). Ngược lại,「にわたって」nhấn mạnh vào sự trải rộng, kéo dài liên tục trên toàn bộ một khoảng thời gian, không gian hoặc quy mô lớn (suốt, khắp). Khi diễn tả sự việc diễn ra tại một mốc/địa điểm đơn thuần ta dùng「において」, còn khi muốn làm nổi bật độ dài liên tục hay bề rộng của phạm vi thì bắt buộc dùng「にわたって」.",examples:[{sentence:"現代社会において、インターネットは日常生活に欠かせないものとなっている。",translation:"Trong xã hội hiện đại, internet đã trở thành một thứ không thể thiếu trong đời sống hàng ngày."},{sentence:"台風の影響で、この地域では5日間にわたって停電が続いた。",translation:"Do ảnh hưởng của bão, tình trạng mất điện đã kéo dài suốt 5 ngày tại khu vực này."}],dialogue:{title:"Lễ hội trường đại học",lines:[{speaker:"A",text:"今年の大学祭は、メインホールにおいて開催されるそうですね。",translation:"Nghe nói lễ hội trường năm nay sẽ được tổ chức tại hội trường chính nhỉ."},{speaker:"B",text:"ええ、本番のために1週間にわたってリハーサルを重ねてきたんですよ。",translation:"Vâng, để chuẩn bị cho buổi diễn chính thì mọi người đã liên tục tập dượt suốt 1 tuần qua đấy."},{speaker:"A",text:"素晴らしいですね。大成功を祈っています。",translation:"Tuyệt vời quá. Chúc sự kiện thành công rực rỡ nhé."}]},commonMistake:{wrong:"彼は20年において、日本の伝統文化を研究し続けている。",correct:"彼は20年間にわたって、日本の伝統文化を研究し続けている。",why:"Khi diễn tả một hành động kéo dài liên tục suốt một khoảng thời gian (20 năm), phải dùng「にわたって」chứ không dùng「において」(vốn chỉ dùng cho mốc thời gian hoặc lĩnh vực cụ thể)."},note:"「において」thường đi với danh từ chỉ địa điểm/lĩnh vực/thời điểm xác định, còn「にわたって」thường đi với danh từ chỉ lượng thời gian, số lần hoặc phạm vi không gian rộng lớn (〜日間, 〜年間, 全域...)."}],84:[{pattern:"〜に基[もと]づいて（基[もと]づき）",meaning:"Dựa trên / căn cứ vào (nền tảng cụ thể: luật, dữ liệu, bằng chứng)",priority:"core",explanation:'Mẫu câu 「〜に基づいて」 mang ý nghĩa là "dựa trên / căn cứ vào", dùng khi lấy một dữ liệu, sự thật, luật pháp, kết quả điều tra hay nguyên tắc làm nền tảng, cơ sở để tiến hành một hành động hoặc đưa ra phán đoán, quyết định. Đi trước mẫu này luôn là các danh từ chỉ cơ sở mang tính khách quan và đáng tin cậy. Phía sau thường là các động từ thể hiện hành động có chủ ý như điều tra, lập kế hoạch, chế tạo, phán quyết. Đây là cách diễn đạt mang sắc thái trang trọng, thường xuất hiện trong văn viết, báo cáo, tin tức và môi trường công việc.',examples:[{sentence:"裁判官は個人的な感情に左右されず、法律の条文と証拠に基づいて判決を下した。",translation:"Thẩm phán đã đưa ra phán quyết căn cứ vào các điều khoản luật pháp và chứng cứ, chứ không bị cảm tính cá nhân chi phối."},{sentence:"この映画は実際に起きた歴史的な事件に基づいて制作されました。",translation:"Bộ phim này được sản xuất dựa trên một sự kiện lịch sử có thật trong thực tế."}],dialogue:{title:"Lập kế hoạch bán hàng",lines:[{speaker:"A",text:"来期の売上目標はどうやって設定しましょうか。",translation:"Chúng ta nên thiết lập mục tiêu doanh số cho kỳ tới như thế nào đây?"},{speaker:"B",text:"過去3年間の販売データに基づいて、地域別の需要を予測してから決めませんか。",translation:"Hay là chúng ta dự đoán nhu cầu theo từng khu vực dựa trên dữ liệu bán hàng 3 năm qua rồi hãy quyết định nhé?"},{speaker:"A",text:"そうですね。客観的なデータに基づいて計画を立てれば、上司も納得してくれるはずです。",translation:"Đúng vậy nhỉ. Nếu lập kế hoạch dựa trên số liệu khách quan thì chắc chắn cấp trên cũng sẽ đồng ý thôi."}]},commonMistake:{wrong:"お客様のご希望に基づいて、旅行プランを変更することができます。",correct:"お客様のご希望に応じて、旅行プランを変更することができます。",why:"「〜に基づいて」 đòi hỏi cơ sở nền tảng phải là sự thật, dữ liệu hay quy tắc cụ thể, còn khi điều chỉnh cho phù hợp, tương ứng với mong muốn hay hoàn cảnh thì phải dùng 「〜に応じて」."},note:"Cần phân biệt với 「〜をもとにして」 (thường dùng khi lấy chất liệu, nguyên liệu hoặc ý tưởng thô để sáng tạo ra sản phẩm mới) và 「〜に沿って」 (hành động bám sát theo đúng phương châm, quy trình đã định sẵn)."},{pattern:"〜に応[おう]じて",meaning:"Tùy theo / phù hợp với (thay đổi linh hoạt tương ứng X)",priority:"common",explanation:"Mẫu ngữ pháp này mang ý nghĩa 'tùy theo / ứng với X mà có sự thay đổi hoặc điều chỉnh Y cho phù hợp'. Vế sau thường đi kèm các hành động thể hiện sự đối ứng, thay đổi linh hoạt (như lựa chọn, điều chỉnh, chuẩn bị, cung cấp...) dựa trên điều kiện, nhu cầu, ngân sách hoặc năng lực của đối tượng. Mẫu câu mang sắc thái trang trọng, thường dùng trong văn bản hướng dẫn, dịch vụ khách hàng hoặc môi trường công sở.",examples:[{sentence:"当ホテルでは、お客様のご予算やご希望に応じて、様々な宿泊プランをご用意しております。",translation:"Khách sạn chúng tôi chuẩn bị nhiều gói lưu trú đa dạng tùy theo ngân sách và nguyện vọng của quý khách."},{sentence:"基礎疾患の有無や年齢に応じて、ワクチンの接種スケジュールを柔軟に調整します。",translation:"Lịch tiêm chủng vắc-xin sẽ được điều chỉnh linh hoạt tùy theo độ tuổi và việc có bệnh nền hay không."}],dialogue:{title:"Tư vấn lựa chọn khóa học",lines:[{speaker:"A",text:"すみません、自分の日本語レベルに合ったクラスを選びたいのですが。",translation:"Xin lỗi, tôi muốn chọn lớp học phù hợp với trình độ tiếng Nhật của mình."},{speaker:"B",text:"当校では、事前のレベルチェックテストの結果に応じて、最適なクラスをご案内しております。",translation:"Tại trường chúng tôi, chúng tôi sẽ hướng dẫn lớp học phù hợp nhất tùy theo kết quả bài kiểm tra đánh giá trình độ trước đó."},{speaker:"A",text:"なるほど。それなら安心して受講できますね。",translation:"Ra là vậy. Như thế thì tôi có thể yên tâm theo học rồi."}]},commonMistake:{wrong:"ファンの熱いご期待に応じて、アンコールでもう1曲歌いました。",correct:"ファンの熱いご期待に応えて、アンコールでもう1曲歌いました。",why:"Khi muốn diễn đạt hành động 'đáp lại' kỳ vọng, tình cảm hay sự cổ vũ của người khác thì phải dùng「〜に応えて」, còn「〜に応じて」chỉ dùng cho việc điều chỉnh cho thích ứng với điều kiện, tình hình hoặc nhu cầu cụ thể."},note:"Cần phân biệt với「〜に応えて」(đáp lại kỳ vọng, tiếng gọi, sự ủng hộ) và「〜によって」(tùy vào từng trường hợp mà kết quả khác nhau, không mang tính chủ động điều chỉnh để thích ứng)."},{pattern:"〜に沿[そ]って（沿[そ]った）",meaning:"Theo đúng / bám sát (kế hoạch, hướng dẫn, lộ trình, bờ sông — không lệch)",priority:"common",explanation:"Mẫu ngữ pháp này mang ý nghĩa là thực hiện theo đúng, bám sát một kế hoạch, quy định, hướng dẫn hoặc phương châm đã định sẵn mà không đi chệch hướng. Bên cạnh nghĩa trừu tượng đó, mẫu câu còn được dùng với nghĩa không gian cụ thể là di chuyển men theo, dọc theo một con đường, bờ sông hay bờ biển. Vế sau thường kết hợp với các động từ chỉ hành động di chuyển hoặc tiến hành công việc như 歩く, 行く, 進める, 実施する.",examples:[{sentence:"新入社員の研修は、会社が定めたマニュアルに沿って進められます。",translation:"Khóa đào tạo nhân viên mới được tiến hành bám sát theo đúng cuốn hướng dẫn mà công ty đã quy định."},{sentence:"この川に沿ってまっすぐ歩いていくと、大きな公園が見えてきます。",translation:"Nếu đi bộ thẳng men theo con sông này, bạn sẽ nhìn thấy một công viên lớn."}],dialogue:{title:"Tiến độ chuẩn bị sự kiện",lines:[{speaker:"A",text:"今回のイベントの準備は、スケジュールに沿って順調に進んでいますか。",translation:"Công tác chuẩn bị cho sự kiện lần này có đang tiến triển thuận lợi theo đúng lịch trình không?"},{speaker:"B",text:"はい、先週作成した計画表に沿って作業を行っております。",translation:"Vâng, chúng tôi đang tiến hành công việc bám sát theo bảng kế hoạch đã lập tuần trước."},{speaker:"A",text:"素晴らしいですね。何か問題があればすぐに報告してください。",translation:"Tuyệt vời quá. Nếu có vấn đề gì phát sinh thì báo cáo ngay nhé."}]},commonMistake:{wrong:"川に基づいて散歩をしましょう。",correct:"川に沿って散歩をしましょう。",why:"「〜に基づいて」chỉ dùng khi lấy dữ liệu, sự thật làm căn cứ để đưa ra phán đoán hoặc tạo ra cái mới, còn khi di chuyển men theo một đường dài/địa hình thì bắt buộc phải dùng「〜に沿って」."},note:"Cần phân biệt với「〜に基づいて」(dựa trên căn cứ, cơ sở dữ liệu) và「〜に従って」(tuân theo chỉ thị của cấp trên hoặc diễn tả sự biến đổi kéo theo)."},{pattern:"に基[もと]づいて ／ に応[おう]じて ／ に沿[そ]って — 使[つか]い分[わ]け",meaning:"Phân biệt: căn cứ cứng nhắc ↔ linh hoạt tương ứng ↔ bám sát không lệch",priority:"common",explanation:"「〜に基づいて」được dùng khi lấy luật lệ, dữ liệu, sự thật làm căn cứ, nền tảng quy chuẩn mang tính khách quan và cố định. Ngược lại,「〜に応じて」thể hiện sự điều chỉnh, thay đổi linh hoạt sao cho tương ứng và phù hợp với từng đối tượng, nhu cầu hoặc hoàn cảnh. Trong khi đó,「〜に沿って」nhấn mạnh hành động tuân thủ, bám sát một lộ trình, kế hoạch, phương châm định sẵn mà không đi chệch hướng. Việc nắm rõ sự khác biệt này giúp bạn diễn đạt chính xác mức độ: từ tuân thủ căn cứ nền tảng, biến đổi tương ứng, đến bám sát tiến trình.",examples:[{sentence:"今回の新事業は、市場調査のデータに基づいて方針を固め、顧客の反応に応じて計画に沿って着実に進めます。",translation:"Dự án mới lần này chúng tôi chốt phương châm dựa trên số liệu khảo sát thị trường, và sẽ bám sát kế hoạch triển khai vững chắc tùy theo phản ứng của khách hàng."},{sentence:"当社では法律に基づいて就業規則を定めていますが、社員の家庭環境に応じてガイドラインに沿った柔軟な働き方を認めています。",translation:"Công ty chúng tôi quy định nội quy lao động dựa trên luật pháp, nhưng cũng cho phép phương thức làm việc linh hoạt bám sát hướng dẫn tùy theo hoàn cảnh gia đình của từng nhân viên."}],dialogue:{title:"Triển khai dự án mới",lines:[{speaker:"A",text:"来期の販売戦略は、最新のアンケート結果に基づいて作成されたのですか。",translation:"Chiến lược bán hàng kỳ tới được lập dựa trên kết quả khảo sát mới nhất phải không?"},{speaker:"B",text:"はい。そのデータに基づいて立案し、各店舗の売れ行きに応じてマニュアルに沿って施策を実行する予定です。",translation:"Vâng. Chúng tôi lập kế hoạch dựa trên dữ liệu đó, và dự kiến sẽ thực hiện các biện pháp bám sát cẩm nang tùy theo tình hình buôn bán của từng cửa hàng."},{speaker:"A",text:"基本方針に沿いながらも、現地の状況に応じて柔軟に対応できる体制ですね。",translation:"Một hệ thống vừa bám sát phương châm cơ bản lại vừa có thể ứng biến linh hoạt tùy theo tình hình thực tế tại chỗ nhỉ."}]},commonMistake:{wrong:"お客様の年齢や予算に基づいて、最適な保険プランを提案いたします。",correct:"お客様の年齢や予算に応じて、最適な保険プランを提案いたします。",why:"Với yếu tố đa dạng và cần sự điều chỉnh tương ứng như tuổi tác hay ngân sách của khách hàng thì phải dùng「に応じて」, còn「に基づいて」chỉ dùng cho căn cứ hay dữ liệu nền tảng cố định."},note:"Mẹo ghi nhớ:「に基づいて」là lấy làm gốc rễ/căn cứ pháp lý,「に応じて」là biến đổi tương ứng theo từng trường hợp, còn「に沿って」là bám sát đường ray/kế hoạch không để chệch hướng."}],85:[{pattern:"〜をめぐって（〜をめぐる ＋ N）",meaning:"Xoay quanh — vấn đề/chủ đề gây tranh cãi, xung đột",priority:"core",explanation:"Mẫu ngữ pháp này mang ý nghĩa 'xoay quanh một vấn đề/chủ đề nào đó'. Cấu trúc này thường đi sau danh từ chỉ sự việc gây tranh cãi, xung đột hoặc có nhiều luồng ý kiến khác nhau giữa các bên. Vế sau luôn đi kèm với các động từ chỉ sự tranh luận, đối lập, cạnh tranh như 議論する, 対立する, 争う. Mẫu câu mang sắc thái trang trọng, thường xuất hiện trong tin tức, thời sự hoặc văn bản thảo luận chính thức.",examples:[{sentence:"親の遺産相続をめぐって、兄弟の間で激しい争いが起きている。",translation:"Xoay quanh việc thừa kế tài sản của cha mẹ, giữa các anh em đang xảy ra tranh chấp gay gắt."},{sentence:"新工場の建設計画をめぐって、住民と行政の間で対立が続いている。",translation:"Xoay quanh kế hoạch xây dựng nhà máy mới, sự đối đầu giữa người dân và chính quyền vẫn đang tiếp diễn."}],dialogue:{title:"Tranh luận trong công ty",lines:[{speaker:"A",text:"テレワークの廃止をめぐって、社内で意見が分かれているみたいですね。",translation:"Nghe nói trong công ty đang có ý kiến trái chiều xoay quanh việc bãi bỏ làm việc từ xa nhỉ."},{speaker:"B",text:"ええ、賛成派と反対派でかなり激しい議論になっているようですよ。",translation:"Vâng, dường như giữa phe tán thành và phe phản đối đang tranh luận khá gay gắt đấy."},{speaker:"A",text:"双方が納得できる解決策が見つかるといいですね。",translation:"Mong là sẽ tìm ra giải pháp khiến cả hai bên đều đồng thuận."}]},commonMistake:{wrong:"日本の文化をめぐって、レポートを書きました。",correct:"日本の文化について、レポートを書きました。",why:"「〜をめぐって」chỉ dùng khi có tranh cãi, đối lập ý kiến giữa nhiều đối tượng, không dùng cho hành động tìm hiểu hay viết báo cáo đơn thuần của một cá nhân."},note:"Khác với「〜について」(chỉ chủ đề tiếp nhận/suy nghĩ thông thường),「〜をめぐって」bắt buộc phải có sự tham gia của nhiều bên cùng tranh luận, đối đầu hoặc cạnh tranh xoay quanh một tâm điểm."},{pattern:"〜にかけては",meaning:"Về khoản/lĩnh vực… thì (khẳng định xuất sắc, tự tin)",priority:"common",explanation:'Cấu trúc 「〜にかけては」 đi sau một danh từ chỉ lĩnh vực, kỹ năng hoặc chuyên môn để diễn đạt ý nghĩa "xét về khoản/lĩnh vực... thì...". Mẫu câu này được dùng để đánh giá cao, khen ngợi hoặc thể hiện sự tự tin về một năng lực vượt trội, không thua kém bất kỳ ai. Vế sau luôn đi kèm các cách diễn đạt tích cực như khẳng định tài năng, vị trí số một hoặc sự vượt trội (như 誰にも負けない, 一番だ, 引けを取らない).',examples:[{sentence:"料理の手際にかけては、プロのシェフにも引けを取らない。",translation:"Nếu xét về sự nhanh nhẹn, khéo léo khi nấu nướng thì anh ấy không hề thua kém các đầu bếp chuyên nghiệp."},{sentence:"パソコンのトラブル解決にかけては、社内で彼にかなう人はいない。",translation:"Về khoản xử lý sự cố máy tính thì trong công ty không ai sánh bằng anh ấy."}],dialogue:{title:"Chọn người phụ trách thiết kế",lines:[{speaker:"A",text:"今度の新商品のパッケージデザイン、誰に頼もうか。",translation:"Bao bì sản phẩm mới lần này, mình nên nhờ ai thiết kế nhỉ?"},{speaker:"B",text:"ポップで目を引くデザインにかけては、佐藤さんが社内で一番ですよ。",translation:"Xét về khoản thiết kế bắt mắt và trẻ trung thì chị Sato là số một trong công ty đấy."},{speaker:"A",text:"そうだね！さっそく佐藤さんに相談してみるよ。",translation:"Ừ nhỉ! Để tôi đi trao đổi với chị Sato ngay."}]},commonMistake:{wrong:"漢字の読み書きにかけては、苦手で全然覚えられません。",correct:"漢字の読み書きに関しては、苦手で全然覚えられません。",why:"Mẫu 「〜にかけては」 chỉ đi với vế sau mang ý khen ngợi, tự tin hoặc vượt trội, không dùng để nói về điểm yếu hay đánh giá tiêu cực."},note:"Khác với 「〜に関しては」 dùng để nêu chủ đề mang tính trung lập, 「〜にかけては」 luôn gắn liền với thái độ tự tin hoặc khẳng định tài năng xuất sắc nhất trong một lĩnh vực."},{pattern:"〜をめぐる ＋ N（連体修飾[れんたいしゅうしょく]）",meaning:"をめぐる dùng trước danh từ (dạng bổ nghĩa)",priority:"common",explanation:'Mẫu ngữ pháp「〜をめぐる＋N」mang ý nghĩa "xoay quanh... / liên quan đến...". Cấu trúc này dùng để bổ nghĩa trực tiếp cho danh từ đứng sau, thường là các từ chỉ sự tranh cãi, mâu thuẫn, đối lập ý kiến hoặc bàn tán sôi nổi (như 議論, 対立, 裁判, 噂). Ngữ cảnh thường mang tính trang trọng, đề cập đến các vấn đề xã hội, chính trị, kinh tế hoặc sự kiện có nhiều bên tham gia với các luồng quan điểm khác nhau.',examples:[{sentence:"AIの著作権侵害をめぐる裁判は、多くのクリエイターから注目を集めている。",translation:"Vụ kiện xoay quanh vấn đề vi phạm bản quyền của AI đang thu hút nhiều sự chú ý từ giới sáng tạo."},{sentence:"消費税の引き上げをめぐる国民の意見は、賛成と反対で真っ二つに分かれている。",translation:"Ý kiến của người dân xoay quanh việc tăng thuế tiêu dùng đang bị chia làm hai phe thuận và chống rõ rệt."}],dialogue:{title:"Tranh cãi quy hoạch ga",lines:[{speaker:"A",text:"駅前の再開発計画をめぐる住民の対立、まだ決着がついていないみたいだね。",translation:"Sự mâu thuẫn giữa các cư dân xoay quanh kế hoạch tái quy hoạch trước nhà ga hình như vẫn chưa đi đến hồi kết nhỉ."},{speaker:"B",text:"景観を守りたい住民と商業施設を増やしたい側で、意見が折り合わないらしいよ。",translation:"Nghe nói bên muốn giữ cảnh quan và bên muốn mở rộng khu thương mại không tìm được tiếng nói chung."},{speaker:"A",text:"双方が納得できる解決策が見つかるといいんだけどね。",translation:"Giá mà tìm được phương án giải quyết khiến cả hai bên đều thỏa đáng thì tốt."}]},commonMistake:{wrong:"今日の会議では、新しい勤怠システムの導入をめぐる説明が行われた。",correct:"今日の会議では、新しい勤怠システムの導入についての説明が行われた。",why:"「〜をめぐる」chỉ đi với danh từ thể hiện sự tranh luận, đối lập hoặc bàn tán từ nhiều phía, không dùng với danh từ chỉ hành động truyền đạt thông tin một chiều như「説明」."},note:"So với「〜について」(chỉ chủ đề nội dung nói chung),「〜をめぐる」bắt buộc phải có sắc thái mâu thuẫn, tranh luận hoặc sự quan tâm đa chiều xoay quanh trung tâm của vấn đề."},{pattern:"をめぐって ≠ について ≠ に関[かん]して（文脈[ぶんみゃく]の使[つか]い分[わ]け）",meaning:"Phân biệt: をめぐって (tranh cãi/xung đột) ≠ について (trung tính, về chủ đề) ≠ に関して (trang trọng, trung tính)",priority:"common",explanation:"「〜について」được dùng để biểu thị đối tượng, chủ đề của hành vi suy nghĩ, nói hoặc nghiên cứu mang tính chất trung tính và phổ biến trong hội thoại hàng ngày. 「〜に関して」có ý nghĩa tương tự nhưng mang sắc thái trang trọng, khách quan hơn, thường dùng trong văn viết, báo cáo hoặc môi trường kinh doanh. Trong khi đó,「〜をめぐって」được dùng khi chủ đề đó là trung tâm gây ra sự tranh cãi, xung đột, bàn tán hoặc đối lập ý kiến giữa nhiều phía.",examples:[{sentence:"遺産の相続をめぐって、兄弟の間で激しい争いが起きている。",translation:"Một cuộc tranh chấp gay gắt đang nổ ra giữa các anh em xoay quanh việc phân chia tài sản thừa kế."},{sentence:"今回のシステム障害の原因に関して、現在専門チームが詳しく調査を行っております。",translation:"Liên quan đến nguyên nhân của sự cố hệ thống lần này, hiện tại đội ngũ chuyên môn đang tiến hành điều tra chi tiết."}],dialogue:{title:"Họp bàn dự án mới",lines:[{speaker:"A",text:"新しい工場の建設地をめぐって、住民と開発側の間で意見が対立しているそうですね。",translation:"Nghe nói đang có sự bất đồng ý kiến giữa người dân và bên phát triển xoay quanh địa điểm xây dựng nhà máy mới đúng không?"},{speaker:"B",text:"ええ、環境への影響について不安視する声が多く出ているんです。",translation:"Vâng, đang có rất nhiều tiếng nói lo ngại về những ảnh hưởng đối với môi trường."},{speaker:"A",text:"来週の説明会に関して、事前に分かりやすい資料を用意しておきましょう。",translation:"Liên quan đến buổi giải thích vào tuần tới, chúng ta hãy chuẩn bị sẵn tài liệu thật dễ hiểu nhé."}]},commonMistake:{wrong:"私の趣味をめぐって、皆さんの前でスピーチをしたいと思います。",correct:"私の趣味について、皆さんの前でスピーチをしたいと思います。",why:"「〜をめぐって」chỉ dùng khi vấn đề có sự tranh cãi hoặc xung đột giữa nhiều người, không dùng cho chủ đề chia sẻ/suy nghĩ cá nhân đơn thuần."},note:"Vế sau của「〜をめぐって」thường đi kèm các danh từ/động từ mang tính tương tác nhiều người như 対立 (đối lập), 議論 (thảo luận sôi nổi), 争い (tranh chấp) và không dùng cho hành động của một cá nhân đơn lẻ."}],86:[{pattern:"〜からすると / 〜からすれば",meaning:"Xét từ / Căn cứ vào … mà đánh giá (phán đoán khách quan)",priority:"core",explanation:'Mẫu câu này dùng để đưa ra phán đoán, suy luận dựa trên một căn cứ, dấu hiệu quan sát được hoặc lập trường của một đối tượng, dịch là "xét từ / căn cứ vào… mà nói". Vế trước kết hợp trực tiếp với danh từ chỉ biểu hiện bên ngoài, hiện tượng hoặc vị trí/lập trường. Vế sau thường đi kèm các cách nói suy đoán, đánh giá như 〜だろう、〜に違いない、〜ようだ. Sắc thái câu mang tính khách quan, suy luận từ manh mối thực tế.',examples:[{sentence:"あの空の暗さからすると、これから激しい雨が降るに違いない。",translation:"Căn cứ vào bầu trời tối sầm kia thì chắc chắn lát nữa trời sẽ mưa rất to."},{sentence:"親の立場からすれば、子どもの将来のことを心配するのは当然のことだ。",translation:"Đứng từ lập trường của cha mẹ mà xét thì việc lo lắng cho tương lai của con cái là điều đương nhiên."}],dialogue:{title:"Dự đoán kết quả phỏng vấn",lines:[{speaker:"A",text:"田中さんのさっきの表情からすると、面接はあまりうまくいかなかったみたいですね。",translation:"Nhìn biểu cảm lúc nãy của anh Tanaka thì có vẻ buổi phỏng vấn không được suôn sẻ lắm nhỉ."},{speaker:"B",text:"ええ、いつも自信満々な田中さんが珍しく落ち込んでいましたからね。",translation:"Vâng, vì hiếm khi thấy người luôn tự tin như anh Tanaka lại ủ rũ như vậy."},{speaker:"A",text:"でも、彼の普段の実績からすれば、合格の可能性も十分あると思いますよ。",translation:"Nhưng xét từ thành tích thường ngày của anh ấy thì tôi nghĩ khả năng đỗ vẫn hoàn toàn có thể đấy."}]},commonMistake:{wrong:"彼の日本語の勉強期間からすると、発音がとても上手だ。",correct:"彼の日本語の勉強期間にしては、発音がとても上手だ。",why:"Khi muốn diễn tả kết quả thực tế vượt ngoài hoặc trái ngược với mức độ dự đoán thông thường từ một căn cứ, ta phải dùng「〜にしては」thay vì「〜からすると」."},note:"Vế sau của「〜からすると／〜からすれば」luôn là câu phán đoán, nhận xét suy luận, tuyệt đối không dùng cho câu thể hiện ý chí, mệnh lệnh hay nguyện vọng của người nói."},{pattern:"〜から見[み]ると / 〜から見[み]れば",meaning:"Nhìn từ góc độ … mà xét (phán đoán có căn cứ, gần với からすると)",priority:"common",explanation:"Mẫu câu này đi kèm với danh từ, mang ý nghĩa 'nếu đứng từ lập trường, góc nhìn của ai đó mà phán đoán' hoặc 'nhìn từ tình trạng, biểu hiện bên ngoài mà suy xét'. Mẫu này thường dùng để đưa ra nhận định hoặc đánh giá khách quan về một sự việc dựa trên một điểm tựa quan sát nhất định. Vế sau câu thường đi kèm với các cách diễn đạt phán đoán, suy đoán như 〜だろう, 〜に違いない, 〜ようだ.",examples:[{sentence:"専門家から見れば、この絵画の修復作業にはまだ改善の余地があるようだ。",translation:"Nhìn từ góc độ của các chuyên gia, công việc phục chế bức tranh này dường như vẫn còn điểm cần cải thiện."},{sentence:"最近の売上データの推移から見ると、新商品の販売戦略は見直す必要があるだろう。",translation:"Xét từ xu hướng dữ liệu doanh số gần đây, có lẽ chúng ta cần phải xem xét lại chiến lược bán sản phẩm mới."}],dialogue:{title:"Đánh giá thiết kế mới",lines:[{speaker:"A",text:"新しいアプリのデザインですが、ユーザーの立場から見ると少し操作が分かりにくいかもしれません。",translation:"Về thiết kế ứng dụng mới, nếu nhìn từ góc độ người dùng thì có lẽ thao tác hơi khó hiểu một chút."},{speaker:"B",text:"確かに、機能が多すぎてどこを押せばいいか迷ってしまいますね。",translation:"Đúng thật, nhiều tính năng quá nên người dùng dễ phân vân không biết bấm vào đâu."},{speaker:"A",text:"ええ、開発側から見れば便利でも、使う人にとってシンプルであることが一番大切ですから修正しましょう。",translation:"Vâng, dù nhìn từ phía nhà phát triển thấy tiện lợi đi nữa, nhưng việc đơn giản đối với người sử dụng mới là quan trọng nhất nên chúng ta hãy sửa lại nhé."}]},commonMistake:{wrong:"私から見ると、明日の会議は午後から始めたほうがいいと思います。",correct:"私としては、明日の会議は午後から始めたほうがいいと思います。",why:"〜から見ると dùng để đưa ra nhận định khách quan từ một điểm nhìn/lập trường chứ không dùng để phát biểu ý kiến, nguyện vọng chủ quan thông thường của bản thân người nói (trường hợp này nên dùng 私としては hoặc 私の意見としては)."},note:"Cần phân biệt với 〜にとって (nhấn mạnh vào sự ảnh hưởng, đánh giá về mặt lợi hại/giá trị đối với đối tượng) và 〜から言うと (xét riêng về một khía cạnh, phương diện cụ thể của sự vật)."},{pattern:"〜にしたら / 〜にすれば",meaning:"Đứng từ lập trường / cảm nhận của … (chủ quan, đồng cảm với người cụ thể)",priority:"common",explanation:"Mẫu câu 「〜にしたら／〜にすれば」 mang ý nghĩa 'nếu đứng trên lập trường, vị trí hoặc góc nhìn cảm xúc của ai đó'. Người nói thường đặt mình vào hoàn cảnh của người khác (thường là ngôi thứ ba hoặc đối phương) để thấu hiểu, đồng cảm với tâm trạng, suy nghĩ hoặc áp lực của họ. Vế sau thường diễn tả những suy đoán, phán đoán mang tính chủ quan về cảm xúc, mong muốn hoặc phản ứng của đối tượng đó.",examples:[{sentence:"親にしたら、子どもの将来を心配して厳しく言っているだけなのだろう。",translation:"Đứng ở vị trí của cha mẹ, có lẽ họ chỉ vì lo lắng cho tương lai của con cái nên mới nói lời nghiêm khắc như vậy thôi."},{sentence:"経験のない新入社員にすれば、いきなり一人で顧客対応を任されるのは大きなプレッシャーに違いない。",translation:"Đứng từ góc độ của một nhân viên mới chưa có kinh nghiệm, việc đột ngột bị giao tự mình xử lý khách hàng chắc chắn là một áp lực rất lớn."}],dialogue:{title:"Chuyện quản lý cấp dưới",lines:[{speaker:"A",text:"田中部長、最近若手社員への指導がかなり厳しいですね。",translation:"Trưởng phòng Tanaka dạo này chỉ đạo nhân viên trẻ khá là nghiêm khắc nhỉ."},{speaker:"B",text:"確かに。でも、部長にしたら早く一人前になってほしいという思いがあるんだと思いますよ。",translation:"Đúng vậy. Nhưng nếu đứng ở vị trí của trưởng phòng, tôi nghĩ là ông ấy chỉ có mong muốn họ sớm vững vàng trong công việc thôi."},{speaker:"A",text:"そうですね。ただ、指導される新人にすれば、少し厳しすぎて自信を失ってしまうかもしれません。",translation:"Đúng thế thật. Nhưng đứng từ phía những người mới được chỉ đạo, có lẽ hơi nghiêm khắc quá sẽ khiến họ mất tự tin đấy."}]},commonMistake:{wrong:"私にすれば、この資格試験に合格することはとても大切です。",correct:"私にとって、この資格試験に合格することはとても大切です。",why:"Khi biểu thị một sự việc có ý nghĩa quan trọng, cần thiết hay đánh giá giá trị đối với ai đó thì phải dùng 「〜にとって」, còn 「〜にすれば」 chủ yếu dùng để đặt mình vào vị trí người khác nhằm thấu hiểu cảm xúc, tâm trạng chủ quan."},note:"Khác với 「〜にとって」 (đánh giá mức độ quan trọng/giá trị) hay 「〜から見ると」 (đưa ra phán đoán khách quan từ góc nhìn bên ngoài), 「〜にしたら」 nhấn mạnh việc thấu cảm với cảm xúc, suy nghĩ nội tâm của người trong cuộc."},{pattern:"にしたら ≠ にとって (N3)",meaning:"にしたら = lập trường/cảm xúc tình huống cụ thể; にとって = đánh giá/lợi ích chủ quan chung",priority:"common",explanation:"「〜にしたら」dùng khi người nói đặt mình vào lập trường, tâm trạng của một đối tượng cụ thể trong hoàn cảnh nhất định để thấu hiểu hoặc suy đoán cảm xúc (thường là bất mãn, lo âu, áp lực) của họ. Ngược lại, 「〜にとって」lại đứng từ góc độ của một đối tượng để đưa ra đánh giá, nhận định về mặt giá trị, tầm quan trọng hoặc mức độ cần thiết mang tính quy luật chung. Điểm mấu chốt để phân biệt là「〜にしたら」thiên về tâm tư, cảm xúc tức thời trong tình huống cụ thể, còn「〜にとって」nhấn mạnh vào sự đánh giá khách quan về lợi ích hay ý nghĩa.",examples:[{sentence:"親にしてみれば良かれと思って言ったことでも、反抗期の息子にしたら口うるさい小言にすぎないのだろう。",translation:"Dù đối với cha mẹ đó là điều nói vì muốn tốt cho con, nhưng đứng ở tâm trạng của đứa con trai đang tuổi nổi loạn thì có lẽ đó chỉ là lời cằn nhằn phiền phức."},{sentence:"十分な睡眠と適度な運動は、多忙な日々を送る現代人にとって健康を維持する上で不可欠な要素だ。",translation:"Giấc ngủ đầy đủ và vận động điều độ là những yếu tố không thể thiếu để duy trì sức khỏe đối với những người hiện đại có cuộc sống bận rộn."}],dialogue:{title:"Chuyện chuyển công tác",lines:[{speaker:"A",text:"田中さん、急な大阪への転勤を命じられて大変そうですね。",translation:"Anh Tanaka bị lệnh chuyển công tác gấp đến Osaka trông có vẻ vất vả nhỉ."},{speaker:"B",text:"ええ、会社側は昇進のチャンスだと言うけれど、新婚の彼にしたら家族と離れるのは辛い決断でしょう。",translation:"Vâng, phía công ty bảo đó là cơ hội thăng tiến, nhưng đứng ở hoàn cảnh của anh ấy vừa mới cưới thì việc xa gia đình quả là quyết định khó khăn."},{speaker:"A",text:"確かに。個人の事情ももう少し配慮してあげてほしいものですね。",translation:"Đúng vậy thật. Ước gì công ty cân nhắc thêm một chút cho hoàn cảnh cá nhân của anh ấy."}]},commonMistake:{wrong:"突然の減給を通告された社員にとって、納得がいかないのも当然だ。",correct:"突然の減給を通告された社員にしたら、納得がいかないのも当然だ。",why:"Khi đặt mình vào vị trí của ai đó để đồng cảm hoặc suy đoán cảm xúc bức xúc, bất mãn trong một tình huống cụ thể thì phải dùng「にしたら」chứ không dùng「にとって」."},note:"「〜にしたら」có thể dùng tương đương với「〜にすれば」hoặc「〜にしてみれば」, và lưu ý cả hai mẫu này thường không đi kèm với chủ ngữ là bản thân người nói (私) khi bộc lộ cảm xúc trực tiếp."}],87:[{pattern:"〜ざるを得[え]ない",meaning:"Buộc phải ~ (do hoàn cảnh cưỡng bức, dù không muốn)",priority:"core",explanation:'Mẫu câu này diễn tả ý nghĩa "đành phải / buộc phải làm gì đó" dù trong lòng thực sự không hề muốn, vì bị hoàn cảnh khách quan hoặc tình thế ép buộc không còn lựa chọn nào khác. Ngữ pháp này mang sắc thái trang trọng, khách quan, thường dùng trong văn viết, báo chí, báo cáo hoặc các phát biểu mang tính trang trọng. Về cách kết hợp, ta đưa động từ về thể phủ định V-ない, bỏ ない rồi thêm ざるを得ない, riêng động từ する sẽ biến đổi đặc biệt thành せざるを得ない.',examples:[{sentence:"これだけの決定的な証拠が揃っている以上、彼の主張を認めざるを得ない。",translation:"Một khi đã có đầy đủ bằng chứng mang tính quyết định như thế này, tôi buộc phải thừa nhận lập luận của anh ấy."},{sentence:"台風の影響で飛行機が全便欠航となったため、出張の日程を変更せざるを得なかった。",translation:"Do ảnh hưởng của bão khiến tất cả các chuyến bay bị hủy, tôi đành phải thay đổi lịch trình chuyến công tác."}],dialogue:{title:"Hoãn sự kiện ngoài trời",lines:[{speaker:"A",text:"明日の野外イベントですが、午後から大雨の予報が出ていますね。",translation:"Về sự kiện ngoài trời ngày mai, có dự báo là từ chiều sẽ mưa to đấy."},{speaker:"B",text:"参加者の安全を最優先に考えると、延期せざるを得ないかもしれませんね。",translation:"Nếu đặt sự an toàn của người tham gia lên hàng đầu, có lẽ chúng ta buộc phải hoãn lại thôi."},{speaker:"A",text:"そうですね。非常に残念ですが、今すぐ関係者に中止の連絡を入れましょう。",translation:"Đúng vậy. Dù rất đáng tiếc nhưng chúng ta hãy liên lạc ngay cho các bên liên quan để thông báo tạm hoãn thôi."}]},commonMistake:{wrong:"予算が大幅に不足しているため、今回の開発計画を中止しざるを得ない。",correct:"予算が大幅に不足しているため、今回の開発計画を中止せざるを得ない。",why:"Động từ nhóm 3 「する」 khi kết hợp với mẫu ngữ pháp này phải biến đổi thành 「せざるを得ない」 chứ không phải 「しざるを得ない」."},note:"Khác với 「〜ないわけにはいかない」 (thiên về áp lực tâm lý, đạo đức, trách nhiệm xã hội), 「〜ざるを得ない」 nhấn mạnh việc hoàn cảnh khách quan dồn ép khiến bản thân không còn phương án nào khác ngoài việc phải làm."},{pattern:"〜ないわけにはいかない",meaning:"Không thể không ~ (nghĩa vụ, lương tâm, chuẩn mực xã hội)",priority:"common",explanation:"Mẫu ngữ pháp này diễn tả ý nghĩa 'không thể không làm' hoặc 'buộc phải làm' một việc nào đó. Người nói sử dụng cấu trúc này khi bản thân có thể không thực sự muốn làm, nhưng vì trách nhiệm, lương tâm, phép lịch sự hoặc chuẩn mực xã hội nên cảm thấy bắt buộc phải thực hiện. Đây là dạng phủ định kép nhằm nhấn mạnh nghĩa vụ xuất phát từ áp lực tâm lý và đạo lý xã hội.",examples:[{sentence:"いつもお世話になっている先輩の結婚式なので、どんなに忙しくても出席しないわけにはいかない。",translation:"Vì là đám cưới của tiền bối luôn giúp đỡ mình nên dù bận rộn đến mấy tôi cũng không thể không tham dự."},{sentence:"自分が起こしたミスでチームに迷惑をかけてしまった以上、正直に謝罪しないわけにはいかない。",translation:"Một khi sai lầm do chính mình gây ra đã làm phiền đến cả đội thì tôi không thể không thành thật xin lỗi."}],dialogue:{title:"Tăng ca gấp cuối tuần",lines:[{speaker:"A",text:"山田さん、急なトラブルが発生してしまって、今週の土曜日出勤をお願いできないでしょうか。",translation:"Anh Yamada ơi, vừa phát sinh sự cố đột xuất, không biết tôi có thể nhờ anh đi làm vào thứ Bảy tuần này được không?"},{speaker:"B",text:"予定はあったんですが、この状況では担当者として手伝わないわけにはいかないですね。引き受けます。",translation:"Tôi vốn có lịch hẹn rồi, nhưng trong tình huống này với tư cách người phụ trách thì không thể không giúp được. Tôi sẽ nhận lời."},{speaker:"A",text:"本当に助かります！無理を言って申し訳ありません。",translation:"Thật sự cứu nguy cho tôi rồi! Xin lỗi vì đã làm khó anh nhé."}]},commonMistake:{wrong:"親切にしてくれた友達の頼みだから、手伝うわけにはいかない。",correct:"親切にしてくれた友達の頼みだから、手伝わないわけにはいかない。",why:"Để diễn đạt ý 'buộc phải làm (không thể không làm)' bắt buộc phải chia động từ sang thể phủ định V-ない, nếu dùng thể từ điển V-る thì câu sẽ mang nghĩa ngược lại hoàn toàn là 'không thể / không được phép giúp đỡ'."},note:"Khác với 「〜ざるを得ない」 dùng khi hoàn cảnh khách quan ép buộc không còn lựa chọn nào khác, 「〜ないわけにはいかない」 nhấn mạnh việc phải làm do trách nhiệm đạo đức, lương tâm hoặc bổn phận xã hội thúc đẩy."},{pattern:"する → せざるを得[え]ない（不規則[ふきそく]）",meaning:"Bất quy tắc: する không thể chia thành しざる, phải dùng せざるを得ない",priority:"common",explanation:'Mẫu câu này diễn tả ý nghĩa "đành phải / buộc phải làm gì đó", xuất phát từ tình thế, hoàn cảnh khách quan ép buộc khiến người nói không còn lựa chọn nào khác dù bản thân không thực sự muốn. Về mặt ngữ pháp, đây là dạng biến đổi bất quy tắc đặc biệt của động từ 「する」 (hoặc Danh từ + する), chuyển thành 「せざるを得ない」 thay vì chia theo quy tắc thông thường. Cấu trúc này mang sắc thái trang trọng, thể hiện sự miễn cưỡng, bất đắc dĩ và thường xuất hiện trong văn viết, báo cáo hoặc phát ngôn trang trọng.',examples:[{sentence:"予算が大幅に削減されたため、今年度の開発計画を縮小せざるを得ない。",translation:"Do ngân sách bị cắt giảm mạnh nên chúng tôi đành phải thu hẹp kế hoạch phát triển của năm nay."},{sentence:"悪天候により全便欠航となったので、楽しみにしていた旅行を延期せざるを得なかった。",translation:"Do thời tiết xấu nên tất cả chuyến bay đều bị hủy, vì vậy tôi buộc phải hoãn chuyến du lịch vốn rất mong đợi."}],dialogue:{title:"Hủy sự kiện ngoài trời",lines:[{speaker:"A",text:"明日の野外イベント、大型台風が接近しているから中止せざるを得ないね。",translation:"Sự kiện ngoài trời ngày mai do bão lớn đang đến gần nên đành phải hủy thôi nhỉ."},{speaker:"B",text:"残念ですが、参加者の安全を考えたら仕方がないですね。",translation:"Tiếc thật đấy, nhưng nghĩ đến sự an toàn của người tham gia thì cũng hết cách rồi."},{speaker:"A",text:"そうだね。関係者への連絡と返金対応を急いで進めよう。",translation:"Đúng vậy. Chúng ta hãy mau chóng tiến hành việc liên lạc với các bên liên quan và xử lý hoàn tiền thôi."}]},commonMistake:{wrong:"今回のシステム障害について、クライアントに説明しざるを得ない。",correct:"今回のシステム障害について、クライアントに説明せざるを得ない。",why:"Động từ 「する」 (bao gồm cả danh động từ như 説明する) có dạng biến đổi bất quy tắc là 「せざるを得ない」, không được chia thành 「しざるを得ない」."},note:"Mẫu câu này nhấn mạnh sự miễn cưỡng do hoàn cảnh ép buộc; nếu chỉ muốn diễn tả nghĩa vụ hoặc sự cần thiết khách quan đơn thuần mà không có sắc thái bất đắc dĩ, hãy dùng 「〜なければならない」."},{pattern:"ざるを得ない ≠ ないわけにはいかない（ニュアンス差[さ]）",meaning:"Phân biệt: ざる = hoàn cảnh ép buộc từ bên ngoài; わけには = tự ý thức nghĩa vụ bên trong",priority:"common",explanation:"「〜ざるを得ない」diễn tả việc chủ thể dù bản thân không hề muốn nhưng do hoàn cảnh khách quan bên ngoài ép buộc nên đành phải làm. Ngược lại, 「〜ないわけにはいかない」thể hiện hành động xuất phát từ ý thức trách nhiệm, chuẩn mực đạo lý xã hội hoặc tình cảm bên trong khiến người nói cảm thấy không thể không làm. Về hình thức kết hợp, 「〜ざるを得ない」đi với thể ない bỏ ない (riêng する đổi thành せざるを得ない), còn 「〜ないわけにはいかない」đi với thể ない nguyên dạng.",examples:[{sentence:"原料の価格が高騰したため、商品の定価を引き上げざるを得ない。",translation:"Do giá nguyên liệu tăng vọt nên chúng tôi buộc phải tăng giá bán niêm yết của sản phẩm."},{sentence:"お世話になった先輩の結婚式だから、どんなに忙しくても出席しないわけにはいかない。",translation:"Vì là đám cưới của tiền bối đã giúp đỡ mình rất nhiều nên dù bận rộn đến mấy tôi cũng không thể không tham dự."}],dialogue:{title:"Đổi kế hoạch dự án",lines:[{speaker:"A",text:"システムに重大な不具合が見つかったので、今週末のリリースは延期せざるを得ないね。",translation:"Vì phát hiện lỗi nghiêm trọng trong hệ thống nên đành phải hoãn đợt phát hành cuối tuần này thôi nhỉ."},{speaker:"B",text:"そうですね。クライアントへの説明も責任を持って対応しないわけにはいきませんね。",translation:"Vâng ạ. Về việc giải thích cho khách hàng thì chúng ta cũng phải có trách nhiệm giải quyết chu đáo."},{speaker:"A",text:"ああ、今から緊急ミーティングを開いて今後の対策を話し合おう。",translation:"Ừ, bây giờ hãy mở cuộc họp khẩn cấp để thảo luận đối sách sắp tới nhé."}]},commonMistake:{wrong:"親友が困っているから、助けざるを得ない。",correct:"親友が困っているから、助けないわけにはいかない。",why:"Hành động giúp đỡ bạn thân xuất phát từ tình cảm và đạo lý bên trong chứ không phải bị hoàn cảnh ép buộc miễn cưỡng, nên phải dùng「〜ないわけにはいかない」."},note:"Cần đặc biệt lưu ý cách chia bất quy tắc của động từ nhóm 3:「する」chuyển thành「せざるを得ない」chứ không phải「*しざるを得ない」."}],88:[{pattern:"〜て しかたがない",meaning:"…quá, không chịu được (chung)",priority:"core",explanation:"Mẫu ngữ pháp này dùng để diễn đạt cảm xúc, tâm trạng, mong muốn hoặc cảm giác sinh lý dâng trào đến mức không thể kìm nén hay kiềm chế được. Thường kết hợp với các từ ngữ chỉ cảm xúc (vui sướng, lo lắng), cảm giác cơ thể (buồn ngủ, ngứa) hoặc động từ tự phát (nhớ lại, lo sợ). Mẫu câu này chủ yếu dùng cho ngôi thứ nhất; khi muốn nói về cảm xúc của ngôi thứ ba thì cần đi kèm các dạng phán đoán như 「〜ようだ」「〜らしい」 hoặc 「〜がっている」.",examples:[{sentence:"合格発表の日が近づくにつれて、結果が気になって しかたがない。",translation:"Càng gần đến ngày công bố kết quả thi, tôi càng lo lắng sốt ruột không chịu được."},{sentence:"ずっと欲しかった限定版のスニーカーが手に入って、嬉しくて しかたがない。",translation:"Mua được đôi giày thể thao phiên bản giới hạn mà tôi ao ước bấy lâu, tôi vui sướng không chịu nổi."}],dialogue:{title:"Kế hoạch về quê",lines:[{speaker:"A",text:"来月、3年ぶりに実家に帰れることになって、早く家族に会いたくて しかたがないんだ。",translation:"Tháng sau tôi được về quê sau 3 năm, tôi mong gặp lại gia đình đến mức không chịu được."},{speaker:"B",text:"それはよかったですね！ご両親もきっと首を長くして待っていますよ。",translation:"Thế thì tốt quá rồi! Bố mẹ cậu chắc chắn cũng đang rất mong ngóng đấy."},{speaker:"A",text:"うん、今からお土産を何にするか考えてワクワクしているよ。",translation:"Ừ, từ bây giờ tôi đã thấy háo hức khi suy nghĩ xem nên mua quà gì rồi."}]},commonMistake:{wrong:"田中さんは家族に会えなくて、寂しくて しかたがない。",correct:"田中さんは家族に会えなくて、寂しくて しかたがないようだ。",why:"Mẫu 「〜て しかたがない」 biểu đạt cảm xúc nội tâm trực tiếp của bản thân nên chỉ dùng cho ngôi thứ nhất; khi nói về người thứ ba phải gắn thêm dạng suy đoán như 「〜ようだ」 hoặc 「〜らしい」."},note:"So với 「〜てたまらない」 (thiên về chịu đựng cảm giác thể xác hoặc khao khát mãnh liệt), 「〜てしかたがない」 nhấn mạnh cảm xúc tự nhiên không cưỡng lại được và có biến thể văn nói thân mật rất phổ biến là 「〜てしょうがない」."},{pattern:"〜て たまらない",meaning:"…không kìm được (cảm giác thể xác/ham muốn mạnh)",priority:"common",explanation:"Mẫu ngữ pháp 「〜て たまらない」 dùng để diễn tả cảm xúc, cảm giác thể xác hoặc mong muốn mạnh mẽ đến mức không thể kìm nén hay chịu đựng nổi. Cấu trúc này thường đi với ngôi thứ nhất (người nói); khi dùng cho ngôi thứ ba cần kết hợp thêm các yếu tố phỏng đoán hoặc trích dẫn như 「〜ようだ」「〜らしい」. Mẫu câu thường kết hợp với tính từ chỉ cảm giác, tâm trạng (như 痒い, 心配, 寂しい) hoặc dạng mong muốn 「〜たい」.",examples:[{sentence:"今日は猛暑のせいで、冷たい水が飲みたくて たまらない。",translation:"Hôm nay vì trời nóng gay gắt nên tôi thèm uống nước lạnh không chịu nổi."},{sentence:"合格発表の時間が近づくにつれて、結果が気になって たまらない。",translation:"Càng đến gần giờ công bố kết quả thi, tôi lại càng sốt ruột và bồn chồn không chịu nổi."}],dialogue:{title:"Tâm trạng trước ngày thi",lines:[{speaker:"A",text:"いよいよ明日が本番だと思うと、緊張して たまらないよ。",translation:"Cứ nghĩ đến việc ngày mai là thi thật rồi làm tớ căng thẳng không chịu nổi."},{speaker:"B",text:"今までたくさん勉強してきたんだから、自分を信じて大丈夫だよ。",translation:"Cậu đã nỗ lực học rất nhiều rồi, cứ tự tin vào bản thân là ổn thôi."},{speaker:"A",text:"ありがとう。早く試験を終えて、友達と旅行に行きたくて たまらないな。",translation:"Cảm ơn cậu. Tớ chỉ muốn thi xong thật nhanh rồi thèm đi du lịch với bạn bè không chịu nổi."}]},commonMistake:{wrong:"山田さんは故郷の家族に会いたくて たまらない。",correct:"山田さんは故郷の家族に会いたくて たまらないようだ。",why:"Mẫu 「〜て たまらない」 diễn tả cảm xúc trực tiếp của người nói (ngôi thứ nhất), nên khi áp dụng cho ngôi thứ ba phải dùng kèm các mẫu phỏng đoán như 「〜ようだ」「〜らしい」 hoặc trích dẫn."},note:"So với 「〜て ならない」 (thiên về cảm xúc tự nhiên dâng trào trong văn cảnh trang trọng, văn viết), 「〜て たまらない」 dùng nhiều trong khẩu ngữ tự nhiên và áp dụng tốt cho cả cảm giác thể xác lẫn ham muốn bột phát."},{pattern:"〜て ならない",meaning:"…không thể không (cảm xúc tự nhiên trào lên)",priority:"common",explanation:"Mẫu câu 「〜て ならない」 diễn tả cảm xúc, tâm trạng hoặc nỗi lo lắng trào dâng một cách tự nhiên từ sâu trong tâm trí đến mức không thể kìm nén được. Cấu trúc này thường kết hợp với các từ chỉ cảm xúc tâm lý (như 寂しい, 不安, 気になる) hoặc các động từ tự phát (như 思える, 気がする, 感じられる). Đây là cách diễn đạt trang trọng, giàu cảm xúc và thiên về văn viết hoặc diễn đạt trang nghiêm hơn so với 「〜てたまらない」.",examples:[{sentence:"合格発表の日が近づくにつれて、試験の結果がどうなるか気になって ならない。",translation:"Càng gần đến ngày công bố kết quả đỗ trượt, tôi lại càng không thể không bận tâm lo lắng xem kết quả thi sẽ ra sao."},{sentence:"一人で海外生活を始めたばかりのころは、家族や友達のことが恋しくて ならない日もあった。",translation:"Hồi mới bắt đầu cuộc sống một mình ở nước ngoài, cũng có những ngày tôi nhớ gia đình và bạn bè đến mức không chịu nổi."}],dialogue:{title:"Lo lắng trước kỳ thi",lines:[{speaker:"A",text:"最近、夜遅くまでずっと勉強しているみたいだけど、体調は大丈夫？",translation:"Dạo này thấy cậu toàn học đến tận khuya, sức khỏe vẫn ổn chứ?"},{speaker:"B",text:"うん、来週の大事な試験のことが気になって ならないんだ。どうしても集中が途切れちゃって。",translation:"Ừ, mình cứ không thể không lo lắng về kỳ thi quan trọng tuần tới. Thành ra cứ bị mất tập trung."},{speaker:"A",text:"気持ちは分かるけど、無理をして体調を崩したら大変だから、今日は早く休んでね。",translation:"Mình hiểu tâm trạng của cậu, nhưng nếu cố quá làm kiệt sức thì gay go lắm, hôm nay nghỉ sớm đi nhé."}]},commonMistake:{wrong:"喉がとても渇いたので、冷たい水が飲みたくて ならない。",correct:"喉がとても渇いたので、冷たい水が飲みたくて たまらない。",why:"「〜て ならない」 chỉ dùng cho cảm xúc nội tâm hoặc cảm giác tâm lý phát sinh tự nhiên, không dùng cho cảm giác sinh lý hay ham muốn thể chất trực tiếp như muốn uống nước (trường hợp này phải dùng 「〜てたまらない」)."},note:"Khác với 「〜てたまらない」 (dùng được cho cả nhu cầu sinh lý và cảm xúc đời thường), 「〜て ならない」 mang sắc thái trang trọng, văn viết và chủ yếu đi kèm các từ chỉ tâm trạng sâu sắc hoặc động từ thể tự phát (思える, 気がする, 案じられる)."}],89:[{pattern:"〜にすぎない",meaning:"Chẳng qua chỉ là… (hạ thấp mức độ, không hơn không kém)",priority:"core",explanation:'Mẫu 「〜にすぎない」 dùng để diễn đạt ý nghĩa "chẳng qua chỉ là... / chỉ dừng lại ở mức...", biểu thị sự việc không có gì to tát hay vượt trội, không hơn không kém. Ngữ pháp này đi trực tiếp sau danh từ, thể thông thường của động từ hoặc tính từ (đôi khi đi với である). Mẫu câu mang sắc thái khách quan, trang trọng, thường dùng trong văn viết hoặc khi người nói muốn thể hiện sự khiêm tốn, hạ thấp thành tích bản thân.',examples:[{sentence:"今回のテストで満点を取ったのは単なる偶然にすぎない。",translation:"Việc tôi đạt điểm tối đa trong bài kiểm tra lần này chẳng qua chỉ là sự ngẫu nhiên mà thôi."},{sentence:"ネットで見かけたその情報は、根拠のない噂にすぎない。",translation:"Thông tin thấy trên mạng đó chẳng qua chỉ là tin đồn vô căn cứ."}],dialogue:{title:"Khen ngợi thành tích",lines:[{speaker:"A",text:"スピーチコンテストで優勝したそうですね。おめでとうございます！",translation:"Nghe nói bạn đã giành giải nhất cuộc thi hùng biện đúng không? Chúc mừng nhé!"},{speaker:"B",text:"ありがとうございます。でも、私は準備した原稿を読んだにすぎないですよ。実力はまだまだです。",translation:"Cảm ơn bạn. Nhưng tôi chẳng qua chỉ đọc bản thảo đã chuẩn bị sẵn thôi. Thực lực tôi vẫn còn kém lắm."},{speaker:"A",text:"そんなことないですよ。堂々とした素晴らしい発表でした。",translation:"Không có chuyện đó đâu. Phần trình bày của bạn rất đỗi tự tin và tuyệt vời đấy."}]},commonMistake:{wrong:"彼は新入社員だにすぎないから、大きな決定はできない。",correct:"彼は新入社員にすぎないから、大きな決定はできない。",why:"Danh từ kết hợp trực tiếp với 「にすぎない」 (hoặc dùng N + であるにすぎない), không chèn trợ động từ 「だ」 vào trước tạo thành 「Nだにすぎない」."},note:'Cần phân biệt với 「〜にほかならない」 (mang nghĩa khẳng định mạnh mẽ "chính là / không gì khác ngoài"), trong khi 「〜にすぎない」 lại dùng để hạ thấp mức độ ("chẳng qua chỉ là").'},{pattern:"〜にほかならない",meaning:"Chính là… không gì khác (khẳng định tuyệt đối, loại trừ mọi giải thích khác)",priority:"common",explanation:"Mẫu ngữ pháp này dùng để khẳng định dứt khoát rằng sự việc, lý do hoặc bản chất của vấn đề chính là điều được nhắc đến, hoàn toàn không có khả năng hay cách giải thích nào khác. Nó mang sắc thái trang trọng, tính văn viết cao và thể hiện sự đánh giá, phán đoán chủ quan tuyệt đối của người nói. Cấu trúc thường đi trực tiếp sau danh từ hoặc kết hợp với các từ chỉ nguyên nhân như 「〜から／〜ため」 đặt ở cuối câu.",examples:[{sentence:"今回のプロジェクトの成功は、チーム全員の努力の結晶にほかならない。",translation:"Sự thành công của dự án lần này chính là kết tinh từ nỗ lực của toàn thể thành viên trong nhóm, không có gì khác."},{sentence:"彼がこれほど厳しく指導するのは、君の将来を心から期待しているからにほかならない。",translation:"Việc anh ấy chỉ dẫn nghiêm khắc đến mức này chính là vì thực lòng kỳ vọng vào tương lai của cậu chứ không vì lý do nào khác."}],dialogue:{title:"Bàn về kết quả thi",lines:[{speaker:"A",text:"田中さん、あんな難関試験に一発で合格するなんて本当にすごいですね。",translation:"Anh Tanaka đỗ kỳ thi khó như thế ngay từ lần thi đầu tiên thật là đáng nể phục nhỉ."},{speaker:"B",text:"いえ、毎晩遅くまで休まず勉強し続けた彼の努力の結果にほかならないと思います。",translation:"Không đâu, tôi nghĩ đó chính là kết quả của sự nỗ lực khi anh ấy kiên trì học muộn mỗi tối không nghỉ ngơi."},{speaker:"A",text:"確かに、目標に向かって妥協しない姿勢は見習いたいものですね。",translation:"Đúng là như vậy, thái độ không bao giờ thỏa hiệp hướng tới mục tiêu của anh ấy rất đáng để chúng ta học tập."}]},commonMistake:{wrong:"私たちが成功したのは、運がよかったにほかならない。",correct:"私たちが成功したのは、運がよかったからにほかならない。",why:"Khi dùng mẫu này để giải thích nguyên nhân/lý do cho cấu trúc 「〜のは」, phía trước bắt buộc phải thêm 「〜から」 hoặc 「〜ため」 chứ không nối trực tiếp sau thể thông thường của tính từ/động từ."},note:"Mẫu này mang văn phong nghị luận trang trọng và thể hiện niềm tin chủ quan mạnh mẽ, không nên dùng trong giao tiếp suồng sã hàng ngày hoặc khi nói về những sự thật hiển nhiên mang tính quy luật tự nhiên."},{pattern:"〜というものだ",meaning:"Thế mới (đúng là)… — kết luận theo lẽ thường / đạo lý chung",priority:"common",explanation:"Mẫu câu này dùng để đưa ra nhận định, đánh giá hoặc kết luận mang tính tất yếu theo lẽ thường, đạo lý chung ('thế mới đúng là...', 'thật là...'). Người nói dựa trên một tình huống cụ thể để nhấn mạnh cảm xúc hoặc khẳng định một chân lý hiển nhiên. Ngữ pháp này rất thường đi kèm với các từ thể hiện sự đánh giá như 無理 (vô lý), 当然 (đương nhiên), 贅沢 (xa xỉ), 本物 (đích thực).",examples:[{sentence:"困っている時に損得を考えずに助けてくれるのが、本当の友達というものだ。",translation:"Giúp đỡ nhau lúc khó khăn mà không màng đến thiệt hơn thì thế mới đúng là bạn bè thực sự."},{sentence:"たった一人でこの巨大なプロジェクトをすべて終わらせろというのは、無理というものだ。",translation:"Bắt một mình hoàn thành toàn bộ dự án khổng lồ này thì đúng là chuyện quá vô lý."}],dialogue:{title:"Bức xúc vì tăng ca",lines:[{speaker:"A",text:"連日残業しているのに、週末まで出勤しろと言うのは酷いというものだよ。",translation:"Ngày nào cũng tăng ca rồi mà còn bảo đi làm cả cuối tuần thì đúng là quá đáng thật đấy."},{speaker:"B",text:"確かに大変だけど、納期が迫っているから仕方がないんじゃない？",translation:"Đúng là vất vả thật, nhưng hạn chót đến gần rồi nên chẳng phải là không còn cách nào khác sao?"},{speaker:"A",text:"それでも、社員の健康を第一に考えるのが会社のあるべき姿というものだ。",translation:"Dù vậy thì việc ưu tiên sức khỏe nhân viên lên hàng đầu mới đúng là điều công ty cần làm."}]},commonMistake:{wrong:"天気予報によると、明日は関東地方で雪が降るというものだ。",correct:"天気予報によると、明日は関東地方で雪が降るということだ。",why:"〜というものだ dùng để đưa ra nhận định/kết luận theo lẽ thường chứ không dùng để truyền đạt lại thông tin nghe được như 〜ということだ."},note:"Cần chú ý dạng phủ định 「〜というものではない / というものでもない」 mang nghĩa 'không hẳn là / không phải cứ... là được', dùng để bác bỏ phán đoán mang tính tuyệt đối."}],90:[{pattern:"〜どころか、〜（反転[はんてん]）",meaning:"Nói gì đến X — ngược lại Y (đảo ngược kỳ vọng)",priority:"core",explanation:"Mẫu 「〜どころか」 dùng để diễn tả ý 'chẳng những không đạt được trạng thái X như kỳ vọng, mà thực tế ngược lại hoàn toàn là Y'. Vế trước (X) là điều vốn được dự đoán, hy vọng hoặc là mức chuẩn tối thiểu; vế sau (Y) đưa ra sự thật trái ngược 180 độ hoặc rơi vào chiều hướng xấu hơn. Mẫu câu này thường mang sắc thái bất ngờ, thất vọng hoặc nhấn mạnh sự thật hoàn toàn trái với tưởng tượng ban đầu.",examples:[{sentence:"薬を飲んで少しは良くなるどころか、かえって熱が上がってしまった。",translation:"Chẳng những không đỡ chút nào sau khi uống thuốc mà ngược lại tôi còn bị sốt cao hơn."},{sentence:"節約するどころか、セールで衝動買いをして余計な出費が増えてしまった。",translation:"Nói gì đến chuyện tiết kiệm, tôi còn mua sắm bốc đồng vào đợt giảm giá khiến chi phí phát sinh thêm nhiều hơn."}],dialogue:{title:"Hiệu quả tập thể dục",lines:[{speaker:"A",text:"ダイエットのために始めたジョギング、順調ですか。",translation:"Việc chạy bộ để giảm cân mà bạn bắt đầu dạo này thuận lợi chứ?"},{speaker:"B",text:"走った後にお腹が空いてたくさん食べてしまうので、痩せるどころか、逆に２キロも太ってしまいました。",translation:"Chạy xong đói bụng nên tôi lại ăn nhiều, chẳng những không gầy đi mà ngược lại còn tăng thêm hẳn 2 cân."},{speaker:"A",text:"それは大変ですね。運動した後の食事管理が一番難しいですよね。",translation:"Thế thì gay rồi nhỉ. Kiểm soát ăn uống sau khi vận động đúng là khó nhất đấy."}]},commonMistake:{wrong:"この部屋は静かなどころか、隣の工事の音がうるさくて全然集中できない。",correct:"この部屋は静かどころか、隣の工事の音がうるさくて全然集中できない。",why:"Khi kết hợp với tính từ đuôi な, ta phải bỏ 「な」 và gắn trực tiếp gốc từ vào 「どころか」 chứ không dùng 「〜などころか」."},note:"Khác với 「〜ばかりか / 〜だけでなく」(mang tính lũy tiến, bổ sung thông tin cùng chiều), 「〜どころか」 nhấn mạnh sự phản chuyển, đưa ra thực tế hoàn toàn trái ngược với kỳ vọng hoặc mức chuẩn ở vế trước."},{pattern:"〜どころか、むしろ〜（程度[ていど]の逆転[ぎゃくてん]）",meaning:"Không những không X, còn Y hơn thế nữa (leo thang ngược chiều)",priority:"common",explanation:"Mẫu câu này dùng để diễn tả rằng thực tế không những không đạt được kết quả hay kỳ vọng X ban đầu, mà ngược lại còn rơi vào trạng thái Y hoàn toàn trái ngược hoặc bất ngờ hơn. Cụm 「〜どころか」 mang tính phủ định mạnh mẽ vế trước, kết hợp với phó từ 「むしろ」 ở vế sau để nhấn mạnh tính chất đảo chiều và leo thang ngược hướng của sự việc. Mẫu này thường được dùng khi người nói muốn đính chính hoặc bày tỏ sự ngạc nhiên, thất vọng trước thực tế trái ngược hoàn toàn với dự đoán.",examples:[{sentence:"薬を飲んで症状が良くなるどころか、むしろ悪化してしまった。",translation:"Uống thuốc vào triệu chứng không những chẳng đỡ hơn, mà ngược lại còn trở nên trầm trọng hơn."},{sentence:"新しいシステムを導入したが、業務が効率化するどころか、むしろやることが増えてしまった。",translation:"Đã áp dụng hệ thống mới nhưng công việc không những chẳng hiệu quả hơn, mà trái lại còn phát sinh thêm nhiều việc."}],dialogue:{title:"Chuyện ăn kiêng giảm cân",lines:[{speaker:"A",text:"最近ダイエットを始めたそうだけど、効果はあった？",translation:"Nghe nói dạo này cậu bắt đầu ăn kiêng, có hiệu quả gì chưa?"},{speaker:"B",text:"それがね、痩せるどころか、むしろストレスで食欲が増えて太っちゃったの。",translation:"Thế đấy, không những chẳng gầy đi mà ngược lại do căng thẳng nên thèm ăn rồi tăng cân luôn."},{speaker:"A",text:"えっ、無理な食事制限は逆効果になるから気をつけてね。",translation:"Hả, kiêng khem quá mức sẽ phản tác dụng đấy nên nhớ cẩn thận nhé."}]},commonMistake:{wrong:"彼は優しいどころか、むしろ親切な人です。",correct:"彼は優しいどころか、むしろ冷たくて意地悪な人です。",why:"「〜どころか、むしろ〜」 dùng để chỉ sự đảo chiều hoặc trái ngược hoàn toàn với đánh giá/kỳ vọng ban đầu, không dùng để nối hai đặc điểm tương đồng cùng chiều tích cực (nếu muốn bổ sung tính chất tương đồng phải dùng 「だけでなく」)."},note:"Cần phân biệt với 「〜ばかりか / 〜だけでなく」 (bổ sung thông tin cùng chiều tiến triển) và 「〜どころではない」 (không có thời gian/tâm trí để làm việc gì)."},null,{pattern:"どころか ≠ どころではない の 使[つか]い分[わ]け",meaning:"Phân biệt: どころか = đảo chiều kỳ vọng (cần vế Y); どころではない = hoàn cảnh chặn hành động (câu đủ nghĩa)",priority:"common",explanation:"「〜どころか」dùng để diễn tả sự việc thực tế hoàn toàn trái ngược hoặc vượt xa dự đoán (không những không A mà ngược lại còn B), bắt buộc phải có vế sau để nêu kết quả đảo chiều. Trong khi đó,「〜どころではない」diễn tả việc hoàn cảnh khó khăn, bận rộn hoặc tâm lý bất an khiến ta không có tâm trí/thời gian làm việc gì đó. Điểm khác biệt lớn nhất là「〜どころではない」có thể đứng độc lập ở cuối câu để kết thúc câu, còn「〜どころか」luôn phải có vế tiếp nối phía sau.",examples:[{sentence:"ダイエットを始めたのに、痩せるどころかかえって２キロ太ってしまった。",translation:"Dù đã bắt đầu ăn kiêng nhưng chẳng những không gầy đi mà trái lại còn tăng thêm 2 kg."},{sentence:"明日は大事な試験があるので、今は遊びに行くどころではない。",translation:"Ngày mai có kỳ thi quan trọng nên bây giờ không phải là lúc để đi chơi."}],dialogue:{title:"Rủ đi du lịch",lines:[{speaker:"A",text:"今週末、連休だから温泉旅行にでも行かない？",translation:"Cuối tuần này được nghỉ dài ngày, hay tụi mình đi du lịch suối nước nóng đi?"},{speaker:"B",text:"残業続きで毎日ヘトヘトだし、今は旅行どころじゃないよ。",translation:"Tăng ca liên miên ngày nào cũng kiệt sức, lúc này tâm trí đâu mà đi du lịch nổi chứ."},{speaker:"A",text:"そうなんだ。休めるどころかますます忙しくなっているんだね、無理しないでね。",translation:"Vậy à. Chẳng những không được nghỉ ngơi mà lại còn bận hơn nhỉ, đừng cố quá sức nhé."}]},commonMistake:{wrong:"締め切りが迫っていて、映画を見るどころか。",correct:"締め切りが迫っていて、映画を見るどころではない。",why:"Khi muốn diễn đạt ý hoàn cảnh gấp gáp/bận rộn không cho phép thực hiện hành động và kết thúc câu, phải dùng「〜どころではない」; còn「〜どころか」bắt buộc phải có vế sau nêu rõ sự việc đảo chiều."},note:"Mẹo ghi nhớ: Muốn chốt hạ câu 'không phải lúc để...' thì dùng「〜どころではない」ở cuối câu; còn muốn nói 'chẳng những không A mà ngược lại còn B' thì dùng「〜どころか」và phải có vế B."}],91:[{pattern:"〜始末[しまつ]だ",meaning:"Rốt cuộc lại thành… (kết cục tiêu cực sau chuỗi sự việc)",priority:"core",explanation:"Mẫu ngữ pháp 「〜始末だ」 dùng để diễn tả một kết cục tồi tệ, tiêu cực hoặc đáng tiếc xảy ra sau một chuỗi hành động, sự việc diễn biến xấu kéo dài. Cấu trúc thường kết hợp với động từ thể từ điển (Vる), thể quá khứ (Vた) hoặc danh từ đi kèm 「この／その」 (この始末だ). Câu mang sắc thái ngán ngẩm, thất vọng sâu sắc hoặc phê phán của người nói khi nhìn lại toàn bộ quá trình.",examples:[{sentence:"彼は遅刻を繰り返したあげく、反省もせず上司に逆らって会社をクビになる始末だ。",translation:"Anh ta liên tục đi làm muộn, đã không kiểm điểm lại còn cãi lời cấp trên, rốt cuộc dẫn đến kết cục bị công ty sa thải."},{sentence:"弟は散々遊んで借金を作り、最後は高齢の両親に肩代わりしてもらう始末だ。",translation:"Em trai tôi chơi bời lêu lổng làm nợ nần chồng chất, rốt cuộc lại thành ra để bố mẹ già phải trả nợ thay."}],dialogue:{title:"Sự cố máy tính",lines:[{speaker:"A",text:"田中さん、先週買ったばかりのパソコンの調子がおかしいって自分で分解したらしいよ。",translation:"Nghe nói anh Tanaka thấy chiếc máy tính mới mua tuần trước bị trục trặc nên đã tự ý tháo tung ra đấy."},{speaker:"B",text:"えっ、無理にいじらないでサポートセンターに連絡すればよかったのに。",translation:"Hả, giá mà anh ấy đừng táy máy mà gọi cho trung tâm hỗ trợ có phải tốt hơn không."},{speaker:"A",text:"そうなんだよ。結局、元に戻せなくなって完全に壊してしまう始末だよ。",translation:"Đúng thế đấy. Rốt cuộc là không lắp lại được và làm hỏng hoàn toàn luôn rồi."}]},commonMistake:{wrong:"毎日一生懸命勉強した結果、第一志望の大学に合格する始末だ。",correct:"毎日一生懸命勉強した結果、第一志望の大学に合格することができた。",why:"「〜始末だ」 chỉ dùng cho kết cục tiêu cực, tồi tệ hoặc đáng thất vọng, tuyệt đối không dùng cho kết quả tốt đẹp hay thành công."},note:"So với 「〜あげく」 (nhấn mạnh vào quá trình giằng co, mệt mỏi dẫn đến kết quả xấu), 「〜始末だ」 tập trung mạnh vào chính kết cục tồi tệ, bế tắc cùng thái độ ngao ngán, phê phán của người nói."},{pattern:"〜ばかりだ（xu hướng）",meaning:"Ngày càng… (xu hướng một chiều đang diễn ra, thường xấu đi)",priority:"common",explanation:'Mẫu ngữ pháp 「〜ばかりだ」 đi sau động từ thể từ điển (Vる) chỉ sự biến đổi, diễn tả một xu hướng đang liên tục tiến triển theo một chiều hướng nhất định. Mẫu câu này hầu như chỉ dùng cho sắc thái tiêu cực, thể hiện tình trạng ngày càng xấu đi hoặc chuyển biến bất lợi mà không thể dừng lại được. Trong tiếng Việt, ngữ pháp này thường được dịch là "ngày càng..." hoặc "cứ... mãi (xấu đi)".',examples:[{sentence:"一度崩れてしまった人間関係は、修復しようと焦れば焦るほど悪化するばかりだ。",translation:"Mối quan hệ con người một khi đã rạn nứt thì càng nóng vội hàn gắn lại càng ngày càng xấu đi."},{sentence:"物価は上がる一方なのに給料は上がらず、生活は苦しくなるばかりだ。",translation:"Giá cả thì cứ tăng mà lương không tăng, cuộc sống ngày càng trở nên khó khăn hơn."}],dialogue:{title:"Tình hình già hóa",lines:[{speaker:"A",text:"最近、この町の人口減少がかなり深刻になってきているらしいよ。",translation:"Dạo này nghe nói tình trạng giảm dân số ở thị trấn này đang trở nên khá nghiêm trọng đấy."},{speaker:"B",text:"うん、若い人がみんな都会に出て行ってしまって、高齢化が進むばかりだ。",translation:"Ừ, người trẻ đều chuyển lên thành phố hết rồi, nên tình trạng già hóa ngày càng tăng cao."},{speaker:"A",text:"本当にそうだね。早く何か有効な対策を打たないと困るね。",translation:"Đúng là vậy thật. Nếu không sớm đưa ra biện pháp hiệu quả nào thì gay go to."}]},commonMistake:{wrong:"毎日日本語を練習しているので、会話が上手に話せるようになるばかりだ。",correct:"毎日日本語を練習しているので、会話が上手に話せるようになる一方だ。",why:"「〜ばかりだ」 hầu như chỉ dùng cho các xu hướng biến đổi mang tính tiêu cực hoặc xấu đi, không dùng cho sự tiến bộ hay biến đổi tốt đẹp."},note:"Khác với 「〜一方だ」 có thể dùng cho cả xu hướng tích cực lẫn tiêu cực, 「〜ばかりだ」 chỉ dùng cho chiều hướng xấu đi; ngoài ra cần tránh nhầm với 「Vた ＋ ばかりだ」 (vừa mới làm xong) và 「Vる ＋ ばかりだ」 biểu thị trạng thái đã chuẩn bị xong, chỉ còn chờ làm."},{pattern:"始末[しまつ]だ ≠ ばかりだ の 使[つか]い分[わ]け",meaning:"Phân biệt: 始末だ (tổng kết chuỗi sự việc đã qua → kết cục xấu) ≠ ばかりだ (xu hướng đang tiến triển)",priority:"common",explanation:"「〜始末だ」được dùng để diễn tả một kết cục tồi tệ, đáng tiếc xảy ra sau một chuỗi hành động sai lầm hoặc sự việc tiêu cực kéo dài trước đó. Ngược lại,「〜ばかりだ」nhấn mạnh vào xu hướng biến đổi theo chiều hướng xấu đang tiếp diễn và ngày càng trầm trọng hơn mà không thấy dấu hiệu dừng lại. Tóm lại,「〜始末だ」chốt lại 'kết cục cuối cùng' (điểm đến), còn「〜ばかりだ」tập trung vào 'chiều hướng đang tiếp tục xấu đi' (tiến trình).",examples:[{sentence:"彼は遅刻を繰り返したあげく、大事なプレゼンの日に無断欠勤する始末だ。",translation:"Anh ấy sau chuỗi ngày liên tục đi muộn, rốt cuộc đến ngày thuyết trình quan trọng lại nghỉ không phép."},{sentence:"不況の影響で会社の業績は下がり、将来への不安は募るばかりだ。",translation:"Do ảnh hưởng suy thoái, tình hình kinh doanh của công ty đi xuống và nỗi bất an về tương lai ngày càng chồng chất."}],dialogue:{title:"Rắc rối của đồng nghiệp",lines:[{speaker:"A",text:"田中さん、最近ミスが続いていて、昨日はついに取引先を怒らせてしまう始末だよ。",translation:"Anh Tanaka dạo này liên tục mắc lỗi, hôm qua rốt cuộc đến mức làm cho khách hàng nổi giận luôn đấy."},{speaker:"B",text:"えっ、本当ですか？注意しても彼の態度は悪化するばかりですね。",translation:"Hả, thật vậy sao? Dù đã nhắc nhở nhưng thái độ của anh ấy cứ ngày một tệ đi nhỉ."},{speaker:"A",text:"うん、このままだとチーム全体に悪影響が出るから、早めに話し合わないと。",translation:"Ừ, cứ thế này sẽ ảnh hưởng xấu đến cả nhóm nên phải sớm nói chuyện giải quyết thôi."}]},commonMistake:{wrong:"景気が悪化して、毎月の赤字は増える始末だ。",correct:"景気が悪化して、毎月の赤字は増えるばかりだ。",why:"Khi muốn diễn tả một sự việc đang có chiều hướng xấu đi liên tục theo thời gian (khoản lỗ ngày càng tăng), phải dùng「〜ばかりだ」chứ không dùng「〜始末だ」(vốn chỉ kết cục xấu sau cùng)."},note:"「〜ばかりだ」thường kết hợp với các động từ biến đổi (悪化する, 増える, 減る, 募る...), còn「〜始末だ」thường đi sau các phó từ/liên từ chỉ sự tích tụ như「〜あげく」「とうとう」「ついに」."}],92:[{pattern:"〜限[かぎ]りだ",meaning:"…vô cùng (cảm xúc mạnh — tiếp tính từ)",priority:"core",explanation:'Mẫu 「〜限りだ」 mang ý nghĩa "vô cùng...", "hết sức...", dùng để nhấn mạnh cảm xúc hoặc tâm trạng của người nói đã đạt đến mức độ cao nhất. Cấu trúc này kết hợp trực tiếp với tính từ đuôi い (A-い) hoặc tính từ đuôi な (A-な + な) biểu thị cảm xúc, tâm lý chủ quan như 嬉しい, 寂しい, 残念な, 誇らしい... Mẫu câu mang sắc thái trang trọng, thường xuất hiện trong văn viết, thư từ, phỏng vấn hoặc khi phát biểu cảm nghĩ cá nhân trước người khác.',examples:[{sentence:"長年努力してきた研究が世界的に認められ、研究者として誇らしい限りだ。",translation:"Công trình nghiên cứu mà tôi nỗ lực bao năm qua đã được thế giới công nhận, là một nhà nghiên cứu tôi cảm thấy tự hào vô cùng."},{sentence:"楽しみにしていた海外旅行が台風のせいで直前に中止になってしまい、残念な限りだ。",translation:"Chuyến du lịch nước ngoài mà tôi hóng đợi bấy lâu lại bị hủy ngay trước giờ đi vì bão, thật đáng tiếc vô cùng."}],dialogue:{title:"Chúc mừng nhận giải",lines:[{speaker:"A",text:"先輩、コンテストでの最優秀賞受賞、本当におめでとうございます！",translation:"Tiền bối, em thực sự chúc mừng anh đã đạt giải xuất sắc nhất trong cuộc thi ạ!"},{speaker:"B",text:"ありがとう。チーム全員で力を合わせて勝ち取った賞だから、リーダーとして光栄な限りだ。",translation:"Cảm ơn em. Vì đây là giải thưởng cả đội cùng hợp lực giành được nên với tư cách trưởng nhóm, anh thấy vinh dự vô cùng."},{speaker:"A",text:"私たちにとっても最高の思い出になりました。本当にお疲れ様でした！",translation:"Đối với tụi em đây cũng là kỷ niệm tuyệt vời nhất. Tiền bối đã vất vả nhiều rồi ạ!"}]},commonMistake:{wrong:"疲れたときは、温かいお風呂に入る限りだ。",correct:"疲れたときは、温かいお風呂に入るに限る。",why:"Để diễn đạt ý 'tốt nhất là / là nhất' phải dùng mẫu 「〜に限る」 (đi với V-る/Danh từ), còn 「〜限りだ」 chỉ kết hợp với Tính từ để diễn tả mức độ cảm xúc tột cùng ('vô cùng...')."},note:"Khác với 「〜てたまらない」 (cảm xúc bộc phát tự nhiên không kiềm chế được, dùng trong hội thoại thân mật), 「〜限りだ」 trang trọng hơn và chỉ dùng cho tính từ chỉ cảm xúc tâm lý của chính người nói."},{pattern:"〜ことか（どんなに／何度[なんど]〜ことか）",meaning:"Biết bao… (cảm thán — bắt buộc có từ nghi vấn)",priority:"common",explanation:'Mẫu ngữ pháp này dùng để bộc lộ cảm xúc, tâm trạng mãnh liệt mang tính cảm thán sâu sắc như "biết bao, biết chừng nào, bao nhiêu lần...". Điểm đặc trưng bắt buộc là luôn phải đi kèm với các từ nghi vấn chỉ mức độ hoặc tần suất như 「どんなに」「どれほど」「何度」「何回」 ở vế trước. Thường được sử dụng trong văn viết hồi tưởng, độc thoại nội tâm hoặc khi người nói muốn giãi bày nỗi niềm xúc động, hối tiếc, cực nhọc hay vui sướng tột cùng.',examples:[{sentence:"故郷を離れて一人で暮らしていると、母の手料理がどれほど恋しいことか。",translation:"Sống một mình xa quê hương mới thấy nhớ những món ăn mẹ nấu biết bao."},{sentence:"難関の国家試験に合格できたと知った時は、どんなに嬉しかったことか。",translation:"Khi biết tin mình đã đỗ kỳ thi quốc gia đầy cam go, tôi đã vui sướng biết dường nào."}],dialogue:{title:"Tâm sự thời mới du học",lines:[{speaker:"A",text:"留学生活を始めたばかりの頃は、言葉が通じなくて何度泣いたことか。",translation:"Hồi mới bắt đầu cuộc sống du học, bất đồng ngôn ngữ nên tôi đã khóc không biết bao nhiêu lần."},{speaker:"B",text:"最初は本当に大変ですよね。でも今はすっかり日本語が上手になったじゃないですか。",translation:"Thời gian đầu thực sự rất vất vả mà. Nhưng chẳng phải bây giờ tiếng Nhật của bạn đã rất thành thạo rồi sao?"},{speaker:"A",text:"ええ、あの苦しい時期を乗り越えたからこそ、今の自分があるんだと思います。",translation:"Vâng, tôi nghĩ chính nhờ vượt qua giai đoạn gian khó đó mà mới có tôi của ngày hôm nay."}]},commonMistake:{wrong:"合格発表で自分の番号を見つけた時は、嬉しかったことか。",correct:"合格発表で自分の番号を見つけた時は、どんなに嬉しかったことか。",why:"Mẫu 「〜ことか」 bắt buộc phải có từ nghi vấn chỉ mức độ như 「どんなに」 hoặc 「どれほど」 đi kèm phía trước để tạo thành cấu trúc cảm thán hoàn chỉnh."},note:"Khác với 「〜ものだ」 dùng để cảm thán chung về bản chất sự vật hoặc hoài niệm quá khứ, 「〜ことか」 luôn đi cùng từ nghi vấn để nhấn mạnh mức độ tột cùng trong cảm xúc của người nói."},{pattern:"〜の極[きわ]み",meaning:"Tột cùng của… (văn viết cực trang trọng — tiếp danh từ)",priority:"common",explanation:'Mẫu 「〜の極み」 đi trực tiếp sau danh từ để biểu thị trạng thái đạt đến đỉnh điểm, tột cùng của một cảm xúc, sự việc hoặc tính chất nào đó ("vô cùng...", "tột cùng của..."). Đây là cách diễn đạt văn viết cổ mang tính trang trọng, tôn nghiêm cao, thường xuất hiện trong các bài phát biểu, nghi thức trang trọng hoặc văn thư lịch thiệp. Mẫu câu này có thể đi kèm với cả danh từ mang nghĩa tích cực (vinh dự, hạnh phúc) lẫn tiêu cực (đau xót, ngu ngốc).',examples:[{sentence:"世界的な権威ある賞をいただき、研究者として栄誉の極みに存じます。",translation:"Được nhận giải thưởng danh giá tầm cỡ thế giới, với tư cách là một nhà nghiên cứu, tôi cảm thấy vinh dự tột cùng."},{sentence:"準備不足が原因で長年のプロジェクトが水泡に帰したのは、痛恨の極みである。",translation:"Việc dự án bao năm qua đổ sông đổ biển chỉ vì thiếu chuẩn bị là nỗi đau xót tột cùng."}],dialogue:{title:"Phát biểu nhận giải",lines:[{speaker:"A",text:"本日はこのような栄えある賞を賜り、光栄の極みでございます。",translation:"Hôm nay được đón nhận giải thưởng cao quý thế này, tôi cảm thấy vinh hạnh tột cùng."},{speaker:"B",text:"先生の長年にわたるご功績を考えれば当然の受賞ですよ。本当におめでとうございます。",translation:"Xét đến những cống hiến nhiều năm qua của thầy thì việc nhận giải là hoàn toàn xứng đáng. Thật lòng chúc mừng thầy!"},{speaker:"A",text:"身に余るお言葉をいただき、感謝の念に堪えません。",translation:"Nhận được những lời khen ngợi lớn lao như vậy, tôi không kìm được niềm xúc động và biết ơn."}]},commonMistake:{wrong:"みんなの前で転んでしまって、本当に恥ずかしいの極みです。",correct:"公式の席で重大な失態を演じてしまい、恥の極みでございます。",why:"Mẫu 「〜の極み」 chỉ kết hợp trực tiếp với danh từ mang sắc thái trang trọng, không đi trực tiếp sau tính từ đuôi -i như 「恥ずかしい」 và không dùng cho chuyện vụn vặt đời thường."},note:"So với mẫu 「〜の至り」 hầu như chỉ chuyên dùng cho cảm xúc nội tâm của người nói (như 光栄, 若気の至り), mẫu 「〜の極み」 có phạm vi rộng hơn khi dùng được cho cả cảm xúc lẫn đánh giá sự vật, trạng thái khách quan (như 痛恨, 愚劣, 贅沢)."},{pattern:"限[かぎ]りだ ／ ことか ／ の極[きわ]み の 使[つか]い分[わ]け",meaning:"Phân biệt ba mẫu: 限りだ (tính từ) ／ ことか (từ nghi vấn) ／ の極み (danh từ)",priority:"common",explanation:"Cả ba mẫu đều dùng để bộc lộ cảm xúc mãnh liệt nhưng khác nhau về từ loại kết hợp và sắc thái biểu đạt. 「〜限りだ」 đi trực tiếp sau tính từ để bộc lộ cảm xúc chủ quan tức thì của người nói (vô cùng/hết sức). 「〜ことか」 bắt buộc đi với từ nghi vấn (どんなに、どれほど...) để cảm thán về mức độ sâu sắc qua một quá trình (biết bao/dường nào). 「〜の極み」 kết hợp với danh từ trừu tượng để diễn tả trạng thái đạt đến mức tột đỉnh trong văn phong trang trọng (tột cùng của...).",examples:[{sentence:"合格の知らせを聞いた時はどんなに嬉しかったことか。今こうして夢の舞台に立てて光栄の極みであり、嬉しい限りだ。",translation:"Khi nghe tin đỗ tôi đã vui sướng biết bao. Giờ đây được đứng trên sân khấu mơ ước thế này, tôi thấy vinh dự tột cùng và vô cùng hạnh phúc."},{sentence:"異国の地で一人暮らしを始めた頃はどれほど心細かったことか。今では良き友人に恵まれ、感謝の極みであると同時に心強い限りだ。",translation:"Hồi mới bắt đầu sống một mình nơi đất khách quê người, tôi đã cảm thấy bất an biết bao. Giờ đây được bạn bè tốt giúp đỡ, tôi thấy biết ơn tột cùng và vô cùng vững tâm."}],dialogue:{title:"Tổng kết dự án thành công",lines:[{speaker:"A",text:"今回の大型プロジェクトが無事に大成功を収めて、責任者として嬉しい限りです。",translation:"Dự án lớn lần này đã thành công rực rỡ, trên cương vị người phụ trách tôi vô cùng vui mừng."},{speaker:"B",text:"準備期間中はどれほど大変だったことか。皆で乗り越えられて本当によかったですね。",translation:"Trong suốt giai đoạn chuẩn bị đã vất vả biết bao. Thật may là mọi người đã cùng nhau vượt qua."},{speaker:"A",text:"ええ、優秀な仲間に支えられてここまで来られたことは、まさに光栄の極みです。",translation:"Vâng, được những người đồng nghiệp xuất sắc hỗ trợ để đi đến ngày hôm nay đúng là niềm vinh dự tột cùng."}]},commonMistake:{wrong:"日本への留学が決まって、どんなに感激の極みだ。",correct:"日本への留学が決まって、どんなに嬉しかったことか。",why:"Từ nghi vấn chỉ mức độ 「どんなに」 bắt buộc phải đi cùng đuôi cảm thán 「〜ことか」, không được kết hợp trực tiếp với 「〜の極み」."},note:"「〜限りだ」 dùng cho tính từ chỉ cảm xúc chủ quan tức thời, 「〜ことか」 nhấn mạnh mức độ/thời gian đã trải qua cùng từ nghi vấn, còn 「〜の極み」 là văn viết trang trọng chỉ đi với danh từ cố định (痛恨、贅沢、光栄...)."}],93:[{pattern:"〜得る[うる／える]",meaning:"Có thể xảy ra — khả năng lý thuyết (văn trang trọng)",priority:"core",explanation:"Mẫu「〜得る（うる／える）」được ghép vào sau thân động từ thể Masu (V-stem) để diễn đạt khả năng một sự việc có thể xảy ra dựa trên lý thuyết, tình huống hoặc hoàn cảnh khách quan. Ngữ pháp này mang sắc thái trang trọng, thường xuất hiện trong văn viết, báo chí, báo cáo hoặc các bài phát biểu trang nghiêm. Về cách đọc, thể khẳng định có thể đọc là「うる」hoặc「える」, nhưng thể phủ định bắt buộc phải là「得ない（えない）」và thể quá khứ là「得た（えた）」. Mẫu này tuyệt đối không dùng để biểu thị năng lực, kỹ năng cá nhân của con người.",examples:[{sentence:"人間誰しも、油断すると大きなミスを犯し得る。",translation:"Con người ai cũng vậy, hễ lơ là chủ quan là đều có thể phạm phải sai lầm lớn."},{sentence:"この新薬には、予期せぬ副作用が生じ得るリスクがある。",translation:"Loại thuốc mới này tiềm ẩn rủi ro có thể phát sinh những tác dụng phụ ngoài dự kiến."}],dialogue:{title:"Bàn phương án khắc phục sự cố",lines:[{speaker:"A",text:"今回のシステム障害は、事前のテストでは予測し得なかった事態ですね。",translation:"Sự cố hệ thống lần này đúng là tình huống không thể nào dự đoán trước trong các đợt kiểm thử nhỉ."},{speaker:"B",text:"ええ。ただ、同様のトラブルは今後も再発し得るので、早急に対策を講じる必要があります。",translation:"Vâng. Tuy nhiên, rắc rối tương tự vẫn hoàn toàn có thể tái diễn trong tương lai nên chúng ta cần nhanh chóng đưa ra đối sách."},{speaker:"A",text:"分かりました。現在考え得るすべての予防策をリストアップして検討しましょう。",translation:"Tôi hiểu rồi. Chúng ta hãy lên danh sách và xem xét tất cả các biện pháp phòng ngừa có thể nghĩ ra lúc này."}]},commonMistake:{wrong:"彼は英語もフランス語も流暢に話し得る。",correct:"彼は英語もフランス語も流暢に話すことができる。",why:"「〜得る」chỉ dùng cho khả năng xảy ra của sự việc theo lý thuyết/khách quan, không dùng để diễn tả năng lực hay kỹ năng của một cá nhân."},note:"Cần đặc biệt lưu ý biến âm khi chia: thể từ điển đọc là「うる/える」, nhưng khi sang dạng phủ định bắt buộc phải đọc là「えない」(không có「うない」) và quá khứ là「えた」."},{pattern:"〜かねる（〜かねます）",meaning:"Khó lòng / không thể — từ chối lịch sự (người nói không muốn hoặc không thể vì đạo đức/quy định)",priority:"common",explanation:'Mẫu ngữ pháp 「〜かねる（〜かねます）」 kết hợp với động từ thể ます (bỏ ます), mang ý nghĩa "khó lòng mà..." hoặc "không thể...". Mẫu câu này được dùng khi người nói muốn từ chối một yêu cầu hay đề nghị một cách gián tiếp, khéo léo và lịch sự do bị ràng buộc bởi hoàn cảnh, lập trường, quy định hoặc lý do tâm lý. Đây là cách diễn đạt mang tính trang trọng cao, xuất hiện rất phổ biến trong môi trường thương mại và giao tiếp công việc.',examples:[{sentence:"担当者が不在のため、現時点ではそのご要望にお応えいたしかねます。",translation:"Do người phụ trách hiện đang vắng mặt nên tại thời điểm này chúng tôi khó lòng có thể đáp ứng yêu cầu đó của quý khách."},{sentence:"彼の提案には一理あるものの、予算の都合上、すぐには受け入れかねる。",translation:"Đề xuất của anh ấy cũng có lý, nhưng do vấn đề ngân sách nên tôi khó lòng chấp nhận ngay được."}],dialogue:{title:"Từ chối cung cấp thông tin",lines:[{speaker:"A",text:"すみません、昨日こちらで買い物をされた田中さんの連絡先を教えていただけますか。",translation:"Xin lỗi, bạn có thể cho tôi xin thông tin liên lạc của anh Tanaka đã mua hàng ở đây hôm qua được không?"},{speaker:"B",text:"恐れ入りますが、個人情報保護の観点から、他のお客様の連絡先はお教えいたしかねます。",translation:"Rất xin lỗi quý khách, xét từ góc độ bảo mật thông tin cá nhân, chúng tôi khó lòng có thể cung cấp thông tin của khách hàng khác được ạ."},{speaker:"A",text:"そうですよね。無理なお願いをしてしまい、失礼いたしました。",translation:"Đúng là vậy nhỉ. Tôi xin lỗi vì đã đưa ra yêu cầu vô lý."}]},commonMistake:{wrong:"私は泳ぎ方が分からないので、深いプールでは泳ぎかねます。",correct:"私は泳ぎ方が分からないので、深いプールでは泳ぐことができません。",why:"「〜かねる」 dùng để từ chối khéo léo vì lý do lập trường, quy tắc hoặc tâm lý, không dùng để biểu thị sự bất khả năng về mặt thể chất hay thiếu năng lực."},note:"Cần chú ý phân biệt 「〜かねる」 (khó lòng/không thể làm) với 「〜かねない」 (có nguy cơ/e rằng sẽ dẫn đến kết quả xấu)."},{pattern:"〜かねない",meaning:"E rằng sẽ… / Có nguy cơ… — cảnh báo khả năng hậu quả XẤU (chủ thể thứ ba hoặc tình huống)",priority:"common",explanation:'Mẫu ngữ pháp này kết hợp với động từ thể ます (bỏ ます) để diễn đạt phán đoán "có nguy cơ" hoặc "e rằng sẽ dẫn đến một hậu quả xấu". Cấu trúc này thường được người nói sử dụng để đưa ra lời cảnh báo hoặc lo ngại về một rủi ro tiêu cực xuất phát từ hành động hoặc tình trạng hiện tại. Điểm cốt lõi là mẫu chỉ dùng cho những sự việc bất lợi, không mong muốn xảy ra, không dùng cho kết quả tốt đẹp.',examples:[{sentence:"このまま無理な働き方を続けていたら、過労で倒れかねないよ。",translation:"Nếu cứ tiếp tục làm việc quá sức như thế này thì e rằng sẽ gục ngã vì kiệt sức đấy."},{sentence:"パスワードを紙に書いて貼っておくと、個人情報が漏洩しかねない。",translation:"Nếu viết mật khẩu ra giấy rồi dán ở đó thì có nguy cơ thông tin cá nhân sẽ bị rò rỉ."}],dialogue:{title:"Cảnh báo bão khi leo núi",lines:[{speaker:"A",text:"こんな悪天候の中で山登りを続けたら、遭難しかねないよ。",translation:"Nếu tiếp tục leo núi trong thời tiết xấu thế này thì có nguy cơ gặp nạn đấy."},{speaker:"B",text:"そうだね。無理をしないで、一度山小屋まで引き返そう。",translation:"Đúng vậy nhỉ. Đừng cố quá, chúng ta hãy quay lại lán nghỉ trên núi trước đã."},{speaker:"A",text:"うん、安全が第一だからね。天気が回復するまで待とう。",translation:"Ừ, an toàn là trên hết mà. Hãy đợi cho đến khi thời tiết tốt hơn nhé."}]},commonMistake:{wrong:"毎日一生懸命勉強すれば、N2に合格しかねない。",correct:"毎日一生懸命勉強すれば、N2に合格できるかもしれない。",why:"「〜かねない」 chỉ dùng để cảnh báo nguy cơ dẫn đến hậu quả xấu, không dùng cho các kết quả tốt đẹp hay tích cực như thi đỗ."},note:'Cần tránh nhầm lẫn với 「〜かねる」 (V-stem ＋ かねる) mang nghĩa là "khó lòng có thể / không thể làm được" dùng khi muốn từ chối một cách lịch sự.'},{pattern:"得る ／ 得ない ／ かねる ／ かねない の 使[つか]い分[わ]け",meaning:"Phân biệt 4 mẫu: khả năng lý thuyết / phủ định khả năng / từ chối lịch sự / nguy cơ xấu",priority:"common",explanation:"Cả bốn mẫu ngữ pháp này đều kết hợp với động từ thể ます (bỏ ます) nhưng mang sắc thái và mục đích diễn đạt hoàn toàn khác nhau. 「〜得る／得ない」dùng để phán đoán khả năng xảy ra của sự việc dựa trên lý thuyết hoặc tình huống khách quan (có thể / không thể). 「〜かねる」dùng để từ chối khéo léo hoặc bày tỏ sự khó khăn vì lý do lập trường, tâm lý dù có khả năng làm được (khó lòng mà, xin phép không thể). Trong khi đó, 「〜かねない」dùng để cảnh báo về một nguy cơ, hậu quả tiêu cực rất có thể sẽ xảy ra nếu tiếp diễn tình trạng hiện tại (e rằng, có nguy cơ).",examples:[{sentence:"人間誰しもミスを犯し得るが、放置すれば重大な事故になりかねない。",translation:"Con người ai cũng có thể phạm sai lầm, nhưng nếu cứ bỏ mặc thì có nguy cơ trở thành tai nạn nghiêm trọng."},{sentence:"個人情報に関わる案件ですので、私の一存では判断しかねますし、漏洩は絶対にあり得ないように管理すべきです。",translation:"Vì đây là vấn đề liên quan đến thông tin cá nhân nên tôi khó lòng tự quyết định được, và cần phải quản lý sao cho việc rò rỉ tuyệt đối không thể nào xảy ra."}],dialogue:{title:"Xử lý khiếu nại",lines:[{speaker:"A",text:"お客様から即時返金を求められましたが、規則上こちらでは対応しかねます。",translation:"Khách hàng yêu cầu hoàn tiền ngay lập tức, nhưng theo quy định thì bên ta khó lòng xử lý được."},{speaker:"B",text:"そうか。ただ、無理に断ると更なるトラブルに発展しかねないから、まずは上司に相談しよう。",translation:"Vậy à. Nhưng nếu từ chối thẳng thừng thì e rằng có thể dẫn đến rắc rối lớn hơn, nên trước hết hãy thảo luận với cấp trên nhé."},{speaker:"A",text:"わかりました。最悪の事態もあり得るので、早急に報告します。",translation:"Tôi hiểu rồi. Tình huống xấu nhất cũng có thể xảy ra nên tôi sẽ báo cáo ngay lập tức."}]},commonMistake:{wrong:"毎日しっかり勉強すれば、JLPT N2に合格しかねない。",correct:"毎日しっかり勉強すれば、JLPT N2に合格し得る。",why:"「〜かねない」chỉ dùng để cảnh báo kết quả xấu hoặc nguy cơ tiêu cực, nên khi nói về kết quả tốt đẹp như đỗ kỳ thi thì phải dùng「〜得る」hoặc thể khả năng thông thường."},note:"Cần lưu ý cách đọc của「得る」ở dạng khẳng định có thể đọc là「うる」hoặc「える」, nhưng khi chuyển sang phủ định「得ない」hoặc quá khứ「得た」thì bắt buộc phải phát âm theo hàng え (えない, えた)."}],94:[{pattern:"尊敬語[そんけいご]：いらっしゃる・なさる・おっしゃる・ご覧[らん]になる",meaning:"Tôn kính ngữ — NÂNG người đối diện hoặc người được nói đến",priority:"core",explanation:"Đây là nhóm động từ tôn kính đặc biệt (尊敬語) dùng để thể hiện sự tôn trọng đối với hành động, trạng thái của đối phương, cấp trên hoặc khách hàng. Nhóm từ này thay thế trực tiếp cho các động từ thông thường: いる/行く/来る chuyển thành いらっしゃる, する thành なさる, 言う thành おっしゃる, và 見る thành ご覧になる. Chúng được sử dụng rất phổ biến trong môi trường công sở, giao tiếp kinh doanh và thư từ thương mại khi nói về phía đối tác hoặc người bề trên. Tuyệt đối không sử dụng nhóm động từ tôn kính này để diễn đạt hành động của bản thân hay người thuộc nhóm nội bộ của mình.",examples:[{sentence:"部長が会議でおっしゃった改善案について、企画書に反映させておきました。",translation:"Tôi đã đưa những đề xuất cải tiến mà Trưởng phòng đã phát biểu trong cuộc họp vào bản kế hoạch rồi ạ."},{sentence:"先ほどメールでお送りいたしました新商品のカタログは、すでにご覧になりましたでしょうか。",translation:"Không biết quý khách đã xem qua cuốn catalogue sản phẩm mới mà tôi gửi qua email lúc nãy chưa ạ?"}],dialogue:{title:"Tiếp đón khách hàng",lines:[{speaker:"A",text:"田中様、本日はお越しいただきありがとうございます。担当の鈴木はまもなくこちらにいらっしゃいます。",translation:"Chào anh Tanaka, cảm ơn anh hôm nay đã ghé thăm công ty. Anh Suzuki phụ trách sẽ đến đây ngay bây giờ ạ."},{speaker:"B",text:"分かりました。先日の契約内容について少し確認したい点があるのですが。",translation:"Tôi hiểu rồi. Tôi có một vài điểm muốn xác nhận về nội dung hợp đồng hôm trước."},{speaker:"A",text:"かしこまりました。鈴木が参るまで、こちらの資料をご覧になってお待ちください。",translation:"Dạ tôi hiểu rồi ạ. Trong lúc chờ anh Suzuki đến, xin mời anh xem qua tập tài liệu này ạ."}]},commonMistake:{wrong:"私が昨日、そのプロジェクトの資料をご覧になりました。",correct:"私が昨日、そのプロジェクトの資料を拝見いたしました。",why:"「ご覧になる」 là tôn kính ngữ chỉ dùng cho hành động của đối phương hoặc cấp trên; khi nói về hành động xem/đọc của bản thân phải dùng khiêm nhường ngữ 「拝見する/拝見いたす」."},note:"Cần phân biệt rõ ranh giới 'trong/ngoài' (Uchi/Soto) để không dùng nhầm tôn kính ngữ cho bản thân, đồng thời chú ý cách chia đặc biệt dạng lịch sự như おっしゃいます, なさいます thay vì chia theo quy tắc thông thường."},{pattern:"謙譲語[けんじょうご]I：伺[うかが]う・申[もう]し上[あ]げる・拝見[はいけん]する",meaning:"Khiêm nhường ngữ I — HẠ bản thân, tôn người nhận (cần đối tượng cụ thể)",priority:"common",explanation:"Khiêm nhường ngữ I (謙譲語I) là cách nói hạ thấp hành vi của bản thân hoặc người thuộc phía mình nhằm thể hiện sự tôn kính đối với người tiếp nhận hành vi (đối tác, khách hàng, cấp trên). Các động từ đặc biệt như 伺う (đi, đến, nghe, hỏi), 申し上げる (nói, trình bày) và 拝見する (xem, đọc) luôn đòi hỏi một đối tượng cụ thể mà hành vi hướng tới. Nhóm mẫu này được sử dụng rất phổ biến trong môi trường công sở và thương mại khi giao tiếp, báo cáo công việc hoặc trao đổi tài liệu.",examples:[{sentence:"明日の午前中に、新しい契約書の詳細をご説明するため御社へ伺う予定でございます。",translation:"Vào sáng mai, tôi dự định sẽ đến quý công ty để giải thích chi tiết về bản hợp đồng mới."},{sentence:"今回のシステム障害による納期の遅れにつきまして、深くお詫び申し上げる次第でございます。",translation:"Về việc chậm trễ kỳ hạn giao hàng do sự cố hệ thống lần này, tôi xin chân thành gửi lời xin lỗi sâu sắc."}],dialogue:{title:"Kiểm tra tài liệu dự án",lines:[{speaker:"A",text:"部長、昨日クライアントから届いた修正案の資料を拝見いたしました。",translation:"Trưởng phòng, tôi đã xem qua tài liệu phương án sửa đổi gửi từ khách hàng hôm qua rồi ạ."},{speaker:"B",text:"内容を確認して特に問題がなければ、今日の午後、先方のオフィスへ伺うことにしよう。",translation:"Nếu cậu kiểm tra nội dung mà không có vấn đề gì thì chiều nay chúng ta hãy đến văn phòng đối tác nhé."},{speaker:"A",text:"承知いたしました。私から先方に訪問の旨を申し上げる連絡を入れておきます。",translation:"Tôi hiểu rồi ạ. Tôi sẽ liên lạc thông báo với đối tác về việc chúng ta đến thăm."}]},commonMistake:{wrong:"部長、先ほどメールでお送りした企画書をもう拝見しましたか。",correct:"部長、先ほどメールでお送りした企画書をもうご覧になりましたか。",why:"「拝見する」là khiêm nhường ngữ chỉ dùng cho hành vi xem của bản thân, không được dùng cho hành vi của cấp trên hay đối tác mà phải chuyển sang tôn kính ngữ「ご覧になる」."},note:"Cần phân biệt 謙譲語I (hạ mình và hướng tới đối tượng tiếp nhận cụ thể như 伺う, 申し上げる, 拝見する) với 丁重語/謙譲語II (hạ mình để nâng cao tính lịch sự chung với người nghe mà không cần đối tượng tiếp nhận như 参る, 申す, いたす)."},null,{pattern:"使[つか]い分[わ]け：尊敬 ≠ 謙譲 ≠ 丁重",meaning:"Phân biệt cốt lõi: 尊敬 (nâng người khác) ≠ 謙譲I (hạ mình+tôn người nhận) ≠ 丁重 (trịnh trọng không cần người nhận)",priority:"common",explanation:"Mục này giúp phân biệt rõ 3 nhóm kính ngữ quan trọng trong giao tiếp công sở: Tôn kính ngữ (尊敬語 - nâng cao hành động của người khác/đối phương), Khiêm nhường ngữ I (謙譲語I - hạ thấp hành động của bản thân nhằm tôn kính đối tượng tiếp nhận hành động), và Đinh trọng ngữ / Khiêm nhường ngữ II (丁重語 - hạ thấp hành động của bản thân để nói chuyện trang trọng, lịch sự với người nghe mà không cần đối tượng tiếp nhận). Điểm mấu chốt là xác định rõ ai là chủ thể thực hiện hành động và hành động đó có hướng tới một đối tượng cụ thể cần tôn kính hay không. Việc phân biệt chính xác giúp bạn diễn đạt chuẩn mực, tự nhiên và tránh các lỗi kính ngữ thô sơ trong thương mại.",examples:[{sentence:"社長[しゃちょう]がお戻[もど]りになりましたら（尊敬）、私[わたし]から企画書[きかくしょ]をお渡[わた]しいたします（謙譲I）。",translation:"Khi Giám đốc quay trở lại (tôn kính ngữ), tôi xin phép sẽ trao bản kế hoạch cho ngài (khiêm nhường ngữ I)."},{sentence:"来週[らいしゅう]は取引先[とりひきさき]へ伺[うかが]いますが（謙譲I）、その前[まえ]に準備[じゅんび]のため自社[じしゃ]の倉庫[そうこ]へ参[まい]ります（丁重）。",translation:"Tuần tới tôi sẽ đến thăm công ty đối tác (khiêm nhường ngữ I), nhưng trước đó tôi sẽ đến nhà kho của công ty mình để chuẩn bị (đinh trọng ngữ)."}],dialogue:{title:"Phân công tiếp đón khách",lines:[{speaker:"A",text:"課長[かちょう]、先方[せんぽう]の部長[ぶちょう]がお見[み]えになりましたら（尊敬）、私[わたし]が応接室[おうせつしつ]へご案内[あんない]申[もう]し上[あ]げます（謙譲I）。",translation:"Thưa Trưởng nhóm, khi Trưởng phòng bên đối tác đến (tôn kính ngữ), em sẽ dẫn đường cho ngài ấy vào phòng tiếp khách (khiêm nhường ngữ I) ạ."},{speaker:"B",text:"ありがとう。私[わたし]は午後[ごご]から支社[ししゃ]へ参[まい]る（丁重）予定[よてい]だから、よろしく頼[たの]むよ。",translation:"Cảm ơn cậu. Chiều nay tôi có lịch đi đến chi nhánh (đinh trọng ngữ) nên nhờ cả vào cậu nhé."},{speaker:"A",text:"かしこまりました。打[う]ち合[あ]わせが終[お]わり次第[しだい]、結果[けっか]をご報告[ほうこく]申[もう]し上[あ]げます（謙譲I）。",translation:"Em rõ rồi ạ. Ngay sau khi cuộc họp kết thúc, em sẽ báo cáo lại kết quả cho anh ạ."}]},commonMistake:{wrong:"私[わたし]は午後[ごご]から銀行[ぎんこう]へ伺[うかが]います。",correct:"私[わたし]は午後[ごご]から銀行[ぎんこう]へ参[まい]ります。",why:"Khi di chuyển đến một địa điểm thông thường (không có đối tượng người nhận cụ thể cần tôn kính), phải dùng đinh trọng ngữ 「参[まい]る」 chứ không dùng khiêm nhường ngữ I 「伺[うかが]う」."},note:"Quy tắc cốt lõi: 尊敬 ngữ dùng cho hành động của đối phương; 謙譲I dùng khi hành động của mình hướng tới đối tượng được tôn kính; còn 丁重 ngữ chỉ nhằm giữ sự trang trọng với người nghe khi nói về hành động độc lập của mình."}],95:[{pattern:"Vる ＋ や否[いな]や",meaning:"Vừa…là ngay lập tức… (văn viết/báo chí, tường thuật khách quan)",priority:"core",explanation:"Mẫu câu 「〜や否や」 diễn tả một sự việc vừa mới xảy ra thì ngay lập tức sự việc tiếp theo diễn ra gần như cùng lúc. Cấu trúc này mang sắc thái trang trọng, thường xuất hiện trong văn viết, phóng sự, tin tức báo chí hoặc lời văn tường thuật khách quan. Vế sau luôn là hành động/sự việc diễn ra trong thực tế (thường chia ở thì quá khứ), tuyệt đối không dùng với các mẫu câu thể hiện ý chí, mệnh lệnh, nguyện vọng hay rủ rê của người nói (như 〜たい, 〜てください, 〜ましょう).",examples:[{sentence:"人気歌手の限定コンサートチケットは、発売が開始されるや否や、瞬く間に売り切れてしまった。",translation:"Vé buổi hòa nhạc giới hạn của ca sĩ nổi tiếng vừa mở bán là ngay lập tức được bán hết sạch trong chớp mắt."},{sentence:"彼は連日の残業で疲労困憊だったのか、ベッドに横たわるや否や、深い眠りに落ちてしまった。",translation:"Có lẽ vì kiệt sức do tăng ca nhiều ngày liên tiếp, anh ấy vừa ngả lưng xuống giường là ngay lập tức chìm vào giấc ngủ sâu."}],dialogue:{title:"Họp báo khẩn cấp",lines:[{speaker:"A",text:"社長の辞任発表を聞くや否や、集まった記者たちが一斉に質問を浴びせ始めましたね。",translation:"Vừa nghe thông báo từ chức của giám đốc là các phóng viên tập trung tại đó ngay lập tức đồng loạt dồn dập đặt câu hỏi nhỉ."},{speaker:"B",text:"ええ、あまりの電撃発表に会場全体が一瞬で騒然としましたよ。",translation:"Vâng, thông báo quá bất ngờ khiến toàn bộ hội trường náo loạn chỉ trong chớp mắt."},{speaker:"A",text:"今後の新体制について、世間の注目がさらに高まりそうです。",translation:"Có vẻ như sự chú ý của dư luận về bộ máy tổ chức mới sắp tới sẽ càng tăng cao hơn."}]},commonMistake:{wrong:"授業が終わるや否や、一緒に学食へ昼ご飯を食べに行きましょう。",correct:"授業が終わったら、一緒に学食へ昼ご飯を食べに行きましょう。",why:"「〜や否や」 chỉ dùng để tường thuật sự việc khách quan đã xảy ra, không được kết hợp với vế sau mang ý chí, mệnh lệnh hay rủ rê như 「〜ましょう」."},note:"So với 「〜が早いか」 (vế sau thường là hành vi chủ ý) và 「〜なり」 (chủ ngữ hai vế thường là ngôi thứ 3 cùng một người), 「〜や否や」 mang tính tường thuật khách quan cao nhất và nhấn mạnh khoảng cách thời gian giữa hai sự việc gần như bằng không."},{pattern:"Vる ＋ が早[はや]いか",meaning:"Vừa mới…đã ngay lập tức… (nhấn phản xạ cực nhanh, gần như đồng thời)",priority:"common",explanation:"Mẫu 「Vる ＋ が早いか」 dùng để diễn tả một hành động, sự việc ở vế sau diễn ra gần như tức khắc, chớp nhoáng ngay sau khi hành động ở vế trước vừa xuất hiện. Ngữ pháp này thường được người nói sử dụng với tư cách người quan sát khách quan để tường thuật lại chuỗi hành vi diễn ra với tốc độ phản xạ cực nhanh. Vế sau luôn luôn là một sự việc có thật đã hoàn tất trong quá khứ, tuyệt đối không dùng các cấu trúc biểu thị ý chí, nguyện vọng, mệnh lệnh hay phỏng đoán tương lai.",examples:[{sentence:"終業のチャイムが鳴るが早いか、生徒たちは一斉に教室を飛び出して運動場へ向かった。",translation:"Chuông báo tan học vừa mới reng một cái là học sinh đồng loạt lao ra khỏi lớp chạy thẳng về phía sân vận động."},{sentence:"デパートの扉が開くが早いか、開店を待っていた客たちが限定福袋の売り場へ殺到した。",translation:"Cửa trung tâm thương mại vừa mở ra một cái là dòng người chờ sẵn lập tức ùa vào khu bán túi may mắn giới hạn."}],dialogue:{title:"Tranh mua hàng giảm giá",lines:[{speaker:"A",text:"今日のタイムセール、お目当ての限定商品は手に入った？",translation:"Đợt giảm giá chớp nhoáng hôm nay, cậu có săn được món hàng giới hạn nhắm tới không?"},{speaker:"B",text:"全然ダメ。店のシャッターが上がるが早いか、大勢の人が押し寄せて一瞬で売り切れちゃったよ。",translation:"Chịu luôn. Cửa cuốn của tiệm vừa kéo lên một cái là cả đám đông ùa vào mua sạch bách trong chớp mắt."},{speaker:"A",text:"相変わらずすごい人気だね。でも怪我しなくて本当によかったよ。",translation:"Vẫn hot như mọi khi nhỉ. Nhưng mà cậu không bị chen lấn thương tích là may lắm rồi đấy."}]},commonMistake:{wrong:"仕事が終わるが早いか、居酒屋へ飲みに行こう。",correct:"彼は仕事が終わるが早いか、カバンを持って居酒屋へ走って行った。",why:"Vế sau của 「〜が早いか」 bắt buộc phải là sự việc đã thực sự diễn ra trong thực tế (quá khứ), không được dùng các cách diễn đạt ý chí, rủ rê (〜よう), nguyện vọng (〜たい) hay mệnh lệnh."},note:"So với 「〜や否や」 (văn viết trang trọng, dùng được cho cả hiện tượng tự nhiên) và 「〜なり」 (bắt buộc hai vế cùng một chủ ngữ ngôi thứ ba), 「〜が早いか」 đặc biệt nhấn mạnh tốc độ phản xạ chớp nhoáng và hành động cạnh tranh, gấp gáp của con người."},{pattern:"Vる ＋ なり",meaning:"Vừa…thì (bất ngờ) lập tức… (hành động sau ngoài dự đoán, cùng một chủ thể)",priority:"common",explanation:"Mẫu 「〜なり」 diễn tả một hành động vừa diễn ra thì ngay lập tức có một hành động khác bất ngờ tiếp nối. Điểm mấu chốt là chủ ngữ của cả hai vế trước và sau bắt buộc phải là cùng một chủ thể (thường là ngôi thứ ba). Vế sau miêu tả hành vi mang tính bộc phát hoặc ngoài dự tính của người quan sát, tuyệt đối không dùng câu mệnh lệnh, ý chí hay rủ rê. Mẫu câu này mang sắc thái văn tường thuật, phóng sự hoặc tiểu thuyết nhằm tạo cảm giác dồn dập, kịch tính.",examples:[{sentence:"彼はひどく疲れていたのか、ベッドに横たわるなり、ぐっすり眠ってしまった。",translation:"Có lẽ vì quá mệt mỏi nên anh ấy vừa đặt lưng xuống giường là đã ngủ say như chết."},{sentence:"息子は母親の顔を見るなり、堪えきれずに大声で泣き出した。",translation:"Đứa con trai vừa nhìn thấy mặt mẹ là đã không kìm được mà òa khóc nức nở."}],dialogue:{title:"Phản ứng bất thường của đồng nghiệp",lines:[{speaker:"A",text:"田中さん、さっき社長から電話を受けるなり、血相を変えて部屋を出て行ったけど、何かあったのかな。",translation:"Anh Tanaka vừa nhận điện thoại từ giám đốc là mặt biến sắc lao ra khỏi phòng ngay, có chuyện gì thế nhỉ?"},{speaker:"B",text:"えっ、本当？さっきまで普通に企画書を作っていたのにね。",translation:"Hả, thật á? Mới lúc nãy còn đang làm bản kế hoạch bình thường mà."},{speaker:"A",text:"うん、何か緊急のトラブルでも起きたのかもしれないよ。",translation:"Ừ, có khi lại xảy ra rắc rối khẩn cấp gì rồi cũng nên."}]},commonMistake:{wrong:"ベルが鳴るなり、生徒たちは一斉に教室から飛び出した。",correct:"ベルが鳴るや否や、生徒たちは一斉に教室から飛び出した。",why:"Mẫu 「〜なり」 bắt buộc hai vế phải cùng một chủ thể thực hiện hành động, nếu hai vế khác chủ thể (chuông reo / học sinh chạy ra) thì phải dùng 「〜や否や」."},note:"Cần phân biệt rõ 「V-る ＋ なり」 (vừa... đã lập tức) với mẫu ngữ pháp N1 khác là 「V-た ＋ なり」 (kể từ khi làm gì thì giữ nguyên trạng thái đó suốt)."},{pattern:"や否[いな]や ／ が早[はや]いか ／ なり の 使[つか]い分[わ]け",meaning:"Cả 3 đều thuật lại việc ĐÃ xảy ra: や否や = trung tính/khách quan (báo chí); が早いか = nhấn tốc độ phản xạ; なり = nhấn bất ngờ + BẮT BUỘC cùng chủ thể. Khác hẳn 次第[しだい]（N2, B71）: 次第 dùng cho việc CHƯA xảy ra, vế sau LÀ ý chí/kế hoạch.",priority:"common",explanation:"Cả ba mẫu 「〜や否や」「〜が早いか」「〜なり」 đều diễn tả hành động ở vế sau xảy ra gần như tức khắc ngay sau khi hành động ở vế trước vừa hoàn tất trong quá khứ. Trong đó, 「〜や否や」 mang tính khách quan, trung tính thường dùng trong văn phong phóng sự, tin tức báo chí; 「〜が早いか」 nhấn mạnh vào tốc độ phản xạ chớp nhoáng của hành động; còn 「〜なり」 thể hiện sự việc bất ngờ, đường đột và bắt buộc hai vế phải cùng một chủ thể (thường là ngôi thứ ba). Khác hoàn toàn với 「〜次第」(N2) dùng cho sự việc chưa xảy ra, cả ba mẫu này đều chỉ dùng tường thuật lại sự việc đã xảy ra.",examples:[{sentence:"非常ベルが鳴り響くや否や、館内の客は係員の誘導に従って一斉に避難を始めた。",translation:"Chuông báo động vừa réo vang một cái là khách trong tòa nhà lập tức đồng loạt sơ tán theo hướng dẫn của nhân viên."},{sentence:"開店のシャッターが上がるが早いか、待機していた大勢のファンが限定グッズ売り場へ駆け込んだ。",translation:"Cửa cuốn mở ra một cái là dòng người hâm mộ xếp hàng chờ sẵn lập tức lao ngay vào quầy bán đồ phiên bản giới hạn."}],dialogue:{title:"Chuyện sếp nổi giận",lines:[{speaker:"A",text:"さっき部長、出社するや否や、会議室のドアを激しく閉めて誰かを怒鳴りつけていたよ。",translation:"Vừa nãy trưởng phòng vừa đến công ty cái là đóng sầm cửa phòng họp rồi quát tháo ai đó ầm ĩ đấy."},{speaker:"B",text:"えっ、本当？朝から一体何があったんだろう。",translation:"Hả, thật á? Từ sáng sớm đã xảy ra chuyện gì vậy không biết."},{speaker:"A",text:"どうやら昨日の重要クライアントへの提出書類に重大なミスが見つかったらしいよ。",translation:"Nghe đâu là tài liệu nộp cho khách hàng quan trọng hôm qua vừa bị phát hiện có lỗi nghiêm trọng."}]},commonMistake:{wrong:"日本に着き次第、すぐに母に電話をかけた。",correct:"日本に着くや否や、すぐに母に電話をかけた。",why:"「〜次第」 chỉ dùng cho hành động chưa xảy ra trong tương lai (kèm ý chí người nói), còn sự việc đã hoàn thành trong quá khứ phải dùng các mẫu như 「〜や否や」 hay 「〜が早いか」."},note:"Vế sau của cả 3 mẫu 「〜や否や」「〜が早いか」「〜なり」 đều miêu tả sự việc đã xảy ra trong quá khứ nên tuyệt đối không đi với các đuôi câu thể hiện ý chí, nguyện vọng, nhờ vả hay mệnh lệnh như 〜たい、〜つもり、〜てください."}],96:[{pattern:"〜そばから",meaning:"Vừa mới xong lại ngay (vòng lặp vô ích, lặp đi lặp lại liên tục)",priority:"core",explanation:"Mẫu「〜そばから」diễn tả ý nghĩa vừa làm xong một việc thì ngay lập tức có sự việc khác xảy ra khiến kết quả trở về số không. Cấu trúc thường kết hợp với động từ thể từ điển hoặc thể quá khứ (Vる / Vた + そばから), nhấn mạnh một hành động/sự việc cứ lặp đi lặp lại nhiều lần như một vòng luẩn quẩn. Người nói thường dùng mẫu này với sắc thái phàn nàn, chán ngán hoặc bất lực trước những nỗ lực vô ích.",examples:[{sentence:"新しい単語を覚えるそばから忘れてしまい、なかなか語彙力が増えない。",translation:"Tôi cứ vừa học xong từ mới là lại quên ngay, mãi mà vốn từ vựng không tăng lên được."},{sentence:"メールを返信するそばから新しい問い合わせが届いて、一向に仕事が終わらない。",translation:"Vừa trả lời xong email thì lại có yêu cầu hỗ trợ mới gửi đến, công việc mãi chẳng thấy xong."}],dialogue:{title:"Học từ mới N1",lines:[{speaker:"A",text:"単語帳で新しい言葉を覚えたそばから忘れていくんだけど、どうやって暗記してる？",translation:"Tớ cứ vừa học xong từ mới trong sổ tay là lại quên ngay, cậu ghi nhớ từ vựng kiểu gì thế?"},{speaker:"B",text:"何度も復習して、実際に例文を作ってみると定着しやすいよ。",translation:"Cứ ôn tập nhiều lần rồi thử tự đặt câu ví dụ thực tế thì sẽ dễ nhớ lâu hơn đấy."},{speaker:"A",text:"なるほど、ただ眺めているだけじゃダメなんだね。",translation:"Ra là vậy, chỉ nhìn lướt qua thôi thì không ăn thua rồi."}]},commonMistake:{wrong:"今朝、家を出るそばから大雨が降り出した。",correct:"今朝、家を出たとたんに大雨が降り出した。",why:"「〜そばから」chỉ dùng cho hành động lặp đi lặp lại nhiều lần mang tính vòng lặp vô ích, không dùng cho sự kiện đơn lẻ chỉ xảy ra một lần trong quá khứ."},note:"Khác với「〜とたんに」hay「〜が早いか」(chỉ một sự việc đơn lẻ xảy ra ngay tức khắc),「〜そばから」bắt buộc phải mang tính lặp đi lặp lại liên tục khiến nỗ lực trở thành công cốc."},{pattern:"〜たら最後[さいご]",meaning:"Một khi đã… thì hết đường lui / không thể cứu vãn",priority:"common",explanation:"Mẫu ngữ pháp này dùng để diễn đạt ý nghĩa 'một khi đã lỡ làm điều gì đó thì chắc chắn sẽ dẫn đến một kết cục xấu, nghiêm trọng và hoàn toàn không thể cứu vãn hay quay đầu lại được'. Cấu trúc này thường đi sau động từ thể quá khứ (Vたら最後 / Vたが最後), vế sau luôn là một hậu quả tiêu cực mang tính quyết định hoặc mất kiểm soát. Mẫu câu thường mang sắc thái cảnh báo mạnh mẽ về sự nguy hiểm hoặc rủi ro khôn lường của một hành động.",examples:[{sentence:"あの秘密[ひみつ]を彼[かれ]に話[はな]したら最後[さいご]、あっという間[ま]に社内[しゃない]中[じゅう]に広[ひろ]まってしまうだろう。",translation:"Một khi đã tiết lộ bí mật đó cho anh ta thì chắc chắn nó sẽ bị đồn thổi khắp công ty trong chớp mắt."},{sentence:"このオンラインゲームは一度[いちど]始[はじ]めたら最後[さいご]、夢中[むちゅう]になりすぎて朝[あさ]まで止[と]まらなくなる。",translation:"Trò chơi trực tuyến này một khi đã bắt đầu chơi thì sẽ mê mẩn đến mức không thể dừng lại được cho tới tận sáng."}],dialogue:{title:"Cảnh báo đầu tư mờ ám",lines:[{speaker:"A",text:"あんな怪[あや]しい投資[とうし]話[ばなし]に乗[の]ったら最後[さいご]、全財産[ぜんざいさん]を失[うしな]うことになるよ。",translation:"Một khi cậu đã dính vào lời mời đầu tư mờ ám đó thì coi như mất trắng toàn bộ tài sản đấy."},{speaker:"B",text:"でも、短期間[たんきかん]で大儲[おおもう]けできるって言[い]われたんだ。",translation:"Nhưng người ta bảo có thể kiếm được món hời lớn trong thời gian ngắn mà."},{speaker:"A",text:"そんなうまい話[はなし]があるわけないだろう。絶対[ぜったい]に手[て]を出[だ]してはだめだ。",translation:"Làm gì có chuyện ngon ăn như thế chứ. Tuyệt đối không được đụng vào đâu."}]},commonMistake:{wrong:"日本語能力試験[にほんごのうりょくしけん]N1に合格[ごうかく]したら最後[さいご]、給料[きゅうりょう]が大幅[おおはば]に上[あ]がる。",correct:"日本語能力試験[にほんごのうりょくしけん]N1に合格[ごうかく]したら、給料[きゅうりょう]が大幅[おおはば]に上[あ]がる。",why:"Mẫu 「〜たら最後」 chỉ dùng cho kết cục xấu, hậu quả tiêu cực không thể cứu vãn, tuyệt đối không dùng cho kết quả tốt đẹp hay may mắn."},note:"Mẫu này có thể thay thế bằng 「〜たが最後[さいご]」 với ý nghĩa tương đương nhưng mang sắc thái văn viết và trang trọng hơn."},{pattern:"〜たが最後[さいご]",meaning:"Cách nói văn viết/trang trọng của たら最後（cùng nghĩa, hay gặp trong xã luận・công văn）",priority:"common",explanation:'Mẫu câu này mang ý nghĩa "một khi đã lỡ làm điều gì đó hoặc rơi vào một tình huống nào đó thì chắc chắn sẽ dẫn đến một kết cục xấu, tồi tệ không thể cứu vãn hay đảo ngược được". Đây là cách nói mang tính văn viết, trang trọng hơn của 「〜たら最後」, thường xuất hiện trong xã luận, báo chí, văn kiện chính luận hoặc tiểu thuyết để nhấn mạnh tính nghiêm trọng của sự việc. Vế sau luôn diễn tả một hậu quả tiêu cực mang tính tất yếu và tuyệt đối không dùng các câu biểu thị ý chí, mệnh lệnh hay nhờ vả của người nói.',examples:[{sentence:"一度[いちど]インターネット上[じょう]に個人情報[こじんじょうほう]が流出[りゅうしゅつ]したが最後[さいご]、完全[かんぜん]に消去[しょうきょ]することは不可能[ふかのう]だ。",translation:"Một khi thông tin cá nhân đã bị rò rỉ lên mạng Internet thì việc xóa bỏ hoàn toàn là điều bất khả thi."},{sentence:"一度[いちど]あの男[おとこ]に弱[よわ]みを握[にぎ]られたが最後[さいご]、一生[いっしょう]脅迫[きょうはく]され続[つづ]けることになる。",translation:"Một khi đã bị gã đó nắm được điểm yếu thì sẽ bị đe dọa, tống tiền suốt cả cuộc đời."}],dialogue:{title:"Bảo mật dự án tối mật",lines:[{speaker:"A",text:"この極秘[ごくひ]プロジェクトのデータは、外部[がいぶ]に漏洩[ろうえい]したが最後[さいご]、我[わ]が社[しゃ]の信用[しんよう]は一瞬[いっしゅん]で失墜[しっつい]します。",translation:"Dữ liệu của dự án tối mật này một khi đã bị rò rỉ ra ngoài thì uy tín của công ty chúng ta sẽ sụp đổ trong chớp mắt."},{speaker:"B",text:"承知[しょうち]いたしました。アクセス権限[けんげん]を厳格[げんかく]に管理[かんり]し、情報[じょうほう]漏洩[ろうえい]防止[ぼうし]を徹底[てってい]します。",translation:"Tôi đã hiểu rõ. Tôi sẽ quản lý nghiêm ngặt quyền truy cập và triệt để phòng chống rò rỉ thông tin."},{speaker:"A",text:"ええ、どんな些細[ささい]な油断[ゆだん]も許[ゆる]されませんので、慎重[しんちょう]にお願[ねが]いします。",translation:"Vâng, tuyệt đối không được có bất kỳ sự lơ là sơ suất nào nên nhờ anh/chị hãy thật cẩn trọng."}]},commonMistake:{wrong:"彼[かれ]に相談[そうだん]したが最後[さいご]、すべてうまく解決[かいけつ]するだろう。",correct:"彼[かれ]に相談[そうだん]しさえすれば、すべてうまく解決[かいけつ]するだろう。",why:"Mẫu 「〜たが最後」 bắt buộc phải đi kèm với hậu quả tiêu cực, tồi tệ không thể cứu vãn ở vế sau, không được dùng cho kết quả tích cực hay tốt đẹp."},note:"So với khẩu ngữ 「〜たら最後」, 「〜たが最後」 mang sắc thái văn phong trang trọng, kịch tính và cảnh báo cao hơn, thường hay đi kèm phó từ 「一度[いちど]」 ở đầu vế để nhấn mạnh tính tuyệt đối không thể cứu vãn."},{pattern:"そばから ≠ たら最後／たが最後 ≠ たびに（N3・58課）≠ ようものなら（N2・81課）",meaning:'Phân biệt: そばから (lặp lại vô ích ngay lập tức) ≠ たら最後／たが最後 (một khi ĐÃ xảy ra một lần → hậu quả không cứu vãn) ≠ たびに (chỉ tương quan lặp lại đơn thuần, không nhấn "vô ích/tức khắc") ≠ ようものなら (cảnh báo TRƯỚC cho hành động còn giả định, chưa xảy ra)',priority:"common",explanation:"「そばから」diễn tả hành động vừa hoàn thành thì ngay lập tức vế sau tái diễn làm tiêu tan công sức, tạo thành một vòng lặp vô ích và gây cảm giác bất lực. Ngược lại,「たら最後／たが最後」nhấn mạnh tình thế không còn đường lui, chỉ cần một khi sự việc đã lỡ xảy ra dù chỉ một lần thì kết cục tồi tệ chắc chắn sẽ ập đến. Cần tránh nhầm với「たびに」(chỉ mối quan hệ lặp lại mang tính quy luật trung tính) và「ようものなら」(đưa ra giả định cảnh báo cho điều chưa xảy ra).",examples:[{sentence:"部屋を片付けるそばから子どもがおもちゃを散らかすので、一向にきれいにならない。",translation:"Cứ vừa dọn phòng xong là con lại bày bừa đồ chơi ra ngay, thành ra phòng chẳng lúc nào ngăn nắp được."},{sentence:"この機密データは一度流出したが最後、会社の社会的信用は完全に失墜してしまう。",translation:"Dữ liệu tuyệt mật này một khi đã bị rò rỉ thì uy tín xã hội của công ty sẽ hoàn toàn sụp đổ, không thể cứu vãn."}],dialogue:{title:"Cảnh báo bảo mật",lines:[{speaker:"A",text:"この不審なリンク、一度クリックしたら最後、端末のデータが全部暗号化されちゃうらしいよ。",translation:"Nghe nói cái đường link đáng ngờ này một khi đã lỡ bấm vào là toàn bộ dữ liệu trong máy sẽ bị mã hóa sạch đấy."},{speaker:"B",text:"えっ、本当？確認のために危うく開いてしまうところだったよ。",translation:"Hả, thật á? Suýt chút nữa là tôi mở ra để kiểm tra rồi đấy."},{speaker:"A",text:"絶対に触っちゃダメ。怪しいメールは受信するそばから即座に削除するのが一番安全だよ。",translation:"Tuyệt đối không được đụng vào. Mấy email đáng ngờ thì cứ vừa nhận được là xóa ngay lập tức là an toàn nhất."}]},commonMistake:{wrong:"新しい単語を暗記したら最後、すぐに忘れてしまうので困っている。",correct:"新しい単語を暗記するそばからすぐに忘れてしまうので困っている。",why:"Việc học từ mới rồi quên diễn ra lặp đi lặp lại như một vòng luẩn quẩn nên phải dùng「そばから」, còn「たら最後」chỉ dùng cho sự việc xảy ra một lần dẫn đến hậu quả nghiêm trọng không thể đảo ngược."},note:"Vế sau của「たら最後／たが最後」luôn là kết cục tiêu cực mang tính tất yếu và không đi với câu mệnh lệnh hay ý chí, khác với「ようものなら」vốn chuyên dùng để răn đe, cảnh báo hậu quả nếu lỡ làm điều giả định."}],97:[{pattern:"〜を 皮切[かわき]りに（して）",meaning:"Lấy…làm mở đầu — khởi động một CHUỖI sự kiện tiếp diễn sau đó",priority:"core",explanation:'Mẫu「〜を皮切りに（して／として）」diễn tả ý nghĩa "lấy một sự việc, hành động làm phát súng mở đầu, để rồi sau đó một chuỗi các sự kiện cùng loại liên tiếp diễn ra với quy mô ngày càng mở rộng". Mẫu này thường kết hợp với danh từ chỉ hành động, sự kiện có chủ đích của con người (như mở bán, lưu diễn, xuất bản, phản đối...). Vế sau luôn miêu tả các hành động tiếp diễn liên tục với nhịp độ dồn dập (thường đi kèm 次々と, 相次いで), tạo cảm giác phong trào hoặc hoạt động đang lan rộng mạnh mẽ.',examples:[{sentence:"新商品の発売を皮切りに、全国の主要都市で大規模なプロモーションイベントが次々と展開された。",translation:"Bắt đầu bằng việc mở bán sản phẩm mới, hàng loạt sự kiện quảng bá quy mô lớn đã liên tiếp được triển khai tại các thành phố lớn trên cả nước."},{sentence:"デビュー作の大ヒットを皮切りにして、彼女は話題作を相次いで発表し、人気作家の仲間入りを果たした。",translation:"Lấy thành công vang dội của tác phẩm đầu tay làm bước khởi đầu, cô ấy đã liên tục cho ra mắt các tác phẩm gây tiếng vang và bước vào hàng ngũ các nhà văn nổi tiếng."}],dialogue:{title:"Kế hoạch mở rộng chi nhánh",lines:[{speaker:"A",text:"来月オープンするハノイ店を皮切りに、年内に国内で10店舗を新規出店する予定です。",translation:"Lấy cửa hàng Hà Nội khai trương vào tháng tới làm điểm khởi đầu, chúng tôi dự định sẽ mở mới 10 cửa hàng trong nước ngay trong năm nay."},{speaker:"B",text:"それは素晴らしいですね！事業拡大のスピードが一気に加速しそうです。",translation:"Thế thì tuyệt vời quá! Tốc độ mở rộng kinh doanh có vẻ sẽ tăng tốc đáng kể đấy."},{speaker:"A",text:"ええ、まずはハノイでの成功を足がかりにして、市場シェアを確実に広げていきたいと考えています。",translation:"Vâng, trước mắt chúng tôi muốn lấy thành công ở Hà Nội làm bàn đạp để từng bước mở rộng thị phần một cách chắc chắn."}]},commonMistake:{wrong:"台風の接近を皮切りに、各地で土砂崩れや浸水などの被害が相次いだ。",correct:"台風の接近に伴い、各地で土砂崩れや浸水などの被害が相次いだ。",why:"「〜を皮切りに」chỉ dùng cho chuỗi hành vi, sự kiện mang tính chủ đích của con người có xu hướng lan rộng, tuyệt đối không dùng cho hiện tượng tự nhiên hay thiên tai, tai nạn tiêu cực."},note:"Khác với「〜をきっかけに／〜を契機に」(chỉ mốc thời gian hoặc cơ duyên dẫn tới sự thay đổi),「〜を皮切りに」bắt buộc phải có một CHUỖI các hành động tương tự liên tiếp diễn ra phía sau."},{pattern:"〜を 限[かぎ]りに",meaning:"Kể từ [nay/lần này] trở đi, chính thức CHẤM DỨT — dứt khoát, không còn nữa",priority:"common",explanation:"Mẫu ngữ pháp này kết hợp với các danh từ chỉ thời gian mang tính thời điểm hiện tại (như 今日, 本日, 今月, 今回) để biểu thị việc chính thức và dứt khoát chấm dứt một hành động, trạng thái nào đó kể từ mốc này trở đi. Ngữ pháp này thường dùng khi người nói đưa ra tuyên bố mang tính dứt điểm như bỏ thói quen xấu, giải nghệ, hoặc đóng cửa một dịch vụ đã duy trì lâu năm. Sắc thái câu văn thể hiện sự quyết tâm mạnh mẽ hoặc mang tính cảm thán cá nhân sâu sắc.",examples:[{sentence:"今月を限りに、長年続けてきたこのブログの更新を終了することにいたしました。",translation:"Kể từ hết tháng này, tôi xin phép chính thức dừng cập nhật trang blog mà mình đã duy trì suốt nhiều năm qua."},{sentence:"健康のために、今日を限りに大好きなお酒とタバコを完全に断つと誓った。",translation:"Vì sức khỏe, tôi đã thề rằng kể từ hôm nay sẽ dứt khoát từ bỏ hoàn toàn rượu và thuốc lá."}],dialogue:{title:"Quyết định nghỉ việc",lines:[{speaker:"A",text:"突然ですが、今週を限りに会社を退職することになりました。",translation:"Hơi đột ngột một chút, nhưng kể từ hết tuần này tôi sẽ chính thức nghỉ việc tại công ty."},{speaker:"B",text:"えっ、本当ですか？長年お世話になったのでとても寂しくなります。",translation:"Hả, thật vậy sao? Được anh giúp đỡ suốt bao năm qua nên tôi sẽ thấy buồn và nhớ lắm đấy."},{speaker:"A",text:"今まで本当にありがとうございました。これからは夢だったカフェの経営に専念します。",translation:"Cảm ơn anh rất nhiều trong thời gian qua. Từ giờ tôi sẽ chuyên tâm vào việc kinh doanh quán cà phê mơ ước của mình."}]},commonMistake:{wrong:"来年の3月を限りに、当サービスの提供を終了いたします。",correct:"来年3月末日をもちまして、当サービスの提供を終了いたします。",why:"「〜を限りに」chỉ đi với các mốc thời gian mang tính hiện tại/lần này (今日, 今月, 今回...) mang sắc thái quyết tâm cá nhân, không dùng cho mốc thời gian xa trong tương lai hay thông báo công cộng trang trọng của tổ chức (khi đó phải dùng「〜をもって / をもちまして」)."},note:"Khác với「〜をもって」mang tính thông báo hành chính/trang trọng của đoàn thể,「〜を限りに」thiên về quyết định, cảm xúc và sự dứt khoát chấm dứt của cá nhân."},{pattern:"〜を もって／をもちまして",meaning:"Lấy [mốc thời gian] làm ranh giới chính thức bắt đầu/kết thúc — TRUNG TÍNH, văn thủ tục",priority:"common",explanation:"Mẫu ngữ pháp này dùng để chỉ một mốc thời gian cụ thể (ngày tháng, giờ giấc) làm ranh giới chính thức để chấm dứt hoặc bắt đầu một trạng thái, sự việc. Đây là cách diễn đạt trang trọng, trung tính, thường xuất hiện trong các văn bản thông báo, nghi thức, thủ tục hành chính hoặc ngữ cảnh kinh doanh. Dạng lịch sự hơn là 「〜をもちまして」 thường được dùng khi phát biểu trong các buổi lễ, sự kiện hoặc gửi thông cáo chính thức đến khách hàng.",examples:[{sentence:"本日の午後5時をもちまして、今年度の採用エントリーの受付を締め切らせていただきます。",translation:"Đúng 5 giờ chiều hôm nay, chúng tôi xin phép được chính thức đóng cổng tiếp nhận hồ sơ ứng tuyển của năm nay."},{sentence:"当店はビルの改装工事に伴い、今月20日をもって一時休業とさせていただきます。",translation:"Do tòa nhà tiến hành cải tạo, cửa hàng chúng tôi xin phép tạm ngừng kinh doanh kể từ ngày 20 tháng này."}],dialogue:{title:"Bế mạc hội thảo",lines:[{speaker:"A",text:"皆様、これをもちまして、本日の国際シンポジウムを終了とさせていただきます。",translation:"Kính thưa quý vị, tôi xin phép được bế mạc buổi hội thảo quốc tế ngày hôm nay tại đây."},{speaker:"B",text:"司会の方、本日は大変お疲れ様でした。とても有意義な会でしたね。",translation:"MC hôm nay vất vả quá rồi. Buổi hội thảo thực sự rất ý nghĩa."},{speaker:"A",text:"ありがとうございます。皆様のご協力のおかげで無事に終えることができました。",translation:"Xin cảm ơn anh. Nhờ sự hỗ trợ của mọi người mà sự kiện đã kết thúc tốt đẹp."}]},commonMistake:{wrong:"健康のために、今日をもってタバコを完全にやめることにした。",correct:"健康のために、今日を限りにタバコを完全にやめることにした。",why:"「〜をもって」 mang tính thủ tục hành chính, trang trọng và khách quan, không dùng cho các quyết định mang tính quyết tâm hay cảm xúc cá nhân như 「〜を限りに」."},note:"Khác với 「〜を限りに」 vốn mang đậm cảm xúc tiếc nuối hoặc quyết tâm dứt khoát của người nói, 「〜をもって／をもちまして」 thuần túy là lời thông báo công vụ mang tính nghi thức, lịch sự."},{pattern:"皮切[かわき]りに ≠ 限[かぎ]りに ≠ をもって ≠ 機[き]に（N2）／にあたって（N2, 72課）",meaning:"Phân biệt: 皮切りに = mở một CHUỖI; 限りに = chấm dứt, cảm thán cá nhân; をもって = mốc trung tính, thủ tục; を機に (N2) = động lực cho MỘT thay đổi đơn lẻ (không cần chuỗi); にあたって (N2, bài 72) = nhân dịp Ý CHÍ khởi đầu MỘT tuyên bố (không cần chuỗi lặp lại)",priority:"common",explanation:"「〜を皮切りに」diễn tả một sự việc khởi đầu và sau đó kéo theo một chuỗi các hành động, sự kiện cùng loại liên tiếp diễn ra và lan rộng, khác với「〜を機に」vốn chỉ là cái cớ hay động lực dẫn đến một thay đổi đơn lẻ. Trong khi đó,「〜にあたって」nhấn mạnh vào thời điểm đặc biệt mang tính chuẩn bị cho một hành động ý chí hướng đến tương lai mà không cần tạo thành chuỗi sự kiện. Ở mốc kết thúc,「〜を限りに」mang đậm cảm xúc cá nhân thể hiện sự dứt khoát hoặc tiếc nuối, còn「〜をもって」lại mang tính trang trọng, trung tính dùng trong các thông báo hành chính hoặc thủ tục chính thức.",examples:[{sentence:"新作アニメの放送を皮切りに、関連グッズの販売やコラボカフェの開催が次々と発表された。",translation:"Khởi đầu bằng việc phát sóng bộ anime mới, hàng loạt thông báo về việc mở bán đồ lưu niệm và tổ chức quán cà phê hợp tác đã liên tiếp được đưa ra."},{sentence:"結婚を機に、郊外の一軒家に引っ越すことに決めた。",translation:"Nhân dịp kết hôn, chúng tôi đã quyết định chuyển về sống tại một ngôi nhà riêng ở vùng ngoại ô."}],dialogue:{title:"Quyết tâm bỏ ăn đêm",lines:[{speaker:"A",text:"今日を限りに、深夜にラーメンを食べるのはきっぱりやめることにしたよ。",translation:"Kể từ hôm nay, tôi quyết định sẽ dứt khoát từ bỏ việc ăn mì ramen vào đêm muộn."},{speaker:"B",text:"えっ、本気？先月も「健康診断を機に食生活を見直す」って言ってなかった？",translation:'Hả, thật á? Tháng trước cậu cũng bảo "nhân dịp khám sức khỏe sẽ xem lại chế độ ăn" còn gì?'},{speaker:"A",text:"今回は絶対に守るよ。今夜の一杯が本当に最後だからね。",translation:"Lần này tớ nhất định sẽ giữ lời. Bát tối nay thực sự là bát cuối cùng đấy."}]},commonMistake:{wrong:"体調を崩したのを皮切りに、お酒を控えるようにした。",correct:"体調を崩したのを機に、お酒を控えるようにした。",why:"「〜を皮切りに」chỉ dùng khi phía sau là một chuỗi sự kiện tương tự liên tiếp diễn ra và lan rộng, còn đối với một quyết định hay sự thay đổi hành vi đơn lẻ thì phải dùng「〜を機に」."},note:"Khi thông báo kết thúc,「〜をもって」mang sắc thái hành chính, trang trọng và khách quan, trong khi「〜を限りに」bộc lộ cảm xúc tiếc nuối hoặc sự dứt khoát mang tính cá nhân của người nói."}],98:[{pattern:"〜に至[いた]って",meaning:"Mãi đến tận lúc… (mới) — chỉ khi sự việc trở nên nghiêm trọng/cực đoan mới có phản ứng",priority:"core",explanation:"Mẫu câu này diễn tả ý nghĩa 'mãi cho đến khi sự việc tiến triển tới mức nghiêm trọng hoặc cực đoan nhất thì mới...', thường đi sau danh từ hoặc động từ thể từ điển (Vる). Vế sau thường đi kèm với 「初めて」, 「ようやく」 để diễn tả phản ứng, hành động hoặc sự nhận thức muộn màng. Cấu trúc này mang sắc thái phê phán hoặc tiếc nuối rõ rệt, ngụ ý rằng đáng lẽ phải hành động sớm hơn chứ không nên để tình thế rơi vào bước đường cùng như vậy.",examples:[{sentence:"体調を崩して緊急入院するに至って、ようやく日頃の不摂生を深く反省した。",translation:"Mãi đến tận lúc đổ bệnh phải nhập viện cấp cứu, tôi mới chịu kiểm điểm sâu sắc về thói quen sinh hoạt thiếu điều độ bấy lâu."},{sentence:"死傷者が出る大事故に至って初めて、警察や自治体は交差点の改修に乗り出した。",translation:"Mãi đến khi xảy ra vụ tai nạn lớn có thương vong, cảnh sát và chính quyền địa phương mới bắt tay vào cải tạo nút giao thông."}],dialogue:{title:"Xử lý khủng hoảng",lines:[{speaker:"A",text:"顧客情報の流出で不買運動にまで発展するに至って、ようやく経営陣が動くのでは遅すぎます。",translation:"Mãi đến tận lúc vụ rò rỉ thông tin khách hàng phát triển thành phong trào tẩy chay ban lãnh đạo mới chịu hành động thì quá muộn rồi."},{speaker:"B",text:"本当に申し訳ない。初期対応の甘さを痛感している。今すぐ緊急記者会見を開いて謝罪しよう。",translation:"Thành thật xin lỗi. Tôi thấm thía sự chủ quan trong việc xử lý ban đầu rồi. Hãy mở ngay cuộc họp báo khẩn cấp để xin lỗi thôi."},{speaker:"A",text:"はい、これ以上の信用失墜を防ぐためにも、包み隠さず事実を公表してください。",translation:"Vâng, để ngăn chặn uy tín sụt giảm thêm nữa, xin hãy công khai toàn bộ sự thật không giấu giếm."}]},commonMistake:{wrong:"日本に来るに至って、初めて自分で自炊する大変さを知った。",correct:"日本に来て初めて、自分で自炊する大変さを知った。",why:"「〜に至って」 chỉ dùng cho những sự việc diễn tiến đến mức cực đoan, nguy cấp hoặc nghiêm trọng, không dùng cho sự việc hay mốc thời gian đời thường."},note:"Tránh nhầm với 「〜に至っては」 (dùng để nêu trường hợp cực đoan nhất làm ví dụ: 'đến như/riêng cái khoản... thì tệ nhất') và 「〜に至るまで」 (chỉ phạm vi rộng lớn trải dài 'cho đến tận...')."},{pattern:"〜に至[いた]るまで",meaning:"Cho đến tận… — nhấn mạnh phạm vi bao quát rộng hoặc mức độ cực kỳ chi tiết",priority:"common",explanation:'Mẫu câu này có nghĩa là "cho đến tận...", được dùng để nhấn mạnh phạm vi bao quát cực kỳ rộng lớn hoặc mức độ chi tiết đến mức đáng kinh ngạc (từ những việc lớn lao đến cả những chi tiết nhỏ nhặt nhất). Cấu trúc thường gặp là 「AからBに至るまで」 (từ A cho đến tận B) hoặc 「Nに至るまで」 (đến cả N). Mẫu này mang sắc thái trang trọng, thường xuất hiện trong văn viết, báo cáo hoặc các bài phát biểu lịch sự nhằm thể hiện sự triệt để, toàn diện.',examples:[{sentence:"この高級ホテルでは、客室の内装からアメニティグッズの品質に至るまで、徹底したこだわりが感じられる。",translation:"Tại khách sạn cao cấp này, từ nội thất phòng ngủ cho đến tận chất lượng của các đồ dùng tiện ích cá nhân, người ta đều cảm nhận được sự tỉ mỉ tuyệt đối."},{sentence:"警察の家宅捜索により、日記やスマートフォンの閲覧履歴に至るまで徹底的に調べ上げられた。",translation:"Qua cuộc khám xét nhà của cảnh sát, mọi thứ cho đến tận nhật ký hay lịch sử duyệt web trên điện thoại thông minh đều bị điều tra một cách triệt để."}],dialogue:{title:"Chuẩn bị tiệc cưới",lines:[{speaker:"A",text:"結婚式の準備、順調に進んでる？決めることが多くて大変でしょう。",translation:"Việc chuẩn bị đám cưới tiến triển thuận lợi chứ? Nhiều thứ phải quyết định như vậy chắc vất vả lắm nhỉ."},{speaker:"B",text:"うん、招待状のデザインから披露宴で流すBGMの一曲に至るまで二人でこだわっているから、本当に時間が足りないよ。",translation:"Ừ, từ thiết kế thiệp mời cho đến tận từng bài nhạc nền phát trong tiệc cưới hai đứa mình đều chăm chút tỉ mỉ, nên thực sự thấy không đủ thời gian luôn."},{speaker:"A",text:"そこまで徹底して準備しているなら、きっとゲストの心に残る素敵な式になるね。",translation:"Chu đáo đến tận mức ấy thì chắc chắn sẽ là một buổi lễ tuyệt vời để lại ấn tượng sâu đậm trong lòng khách mời đấy."}]},commonMistake:{wrong:"明日の全体会議は午前10時から午後3時に至るまで行われる予定です。",correct:"明日の全体会議は午前10時から午後3時まで行われる予定です。",why:"「〜に至るまで」 dùng để nhấn mạnh phạm vi rộng lớn hoặc chi tiết mang tính cực đoan, không dùng cho mốc thời gian kết thúc của lịch trình sinh hoạt/công việc thông thường (trường hợp này chỉ dùng trợ từ 「〜まで」)."},note:"Cần phân biệt với 「〜に至って」 (chỉ dùng khi tình huống đã tiến triển đến mức nghiêm trọng/đường cùng thì mới có hành động hoặc nhận thức) và 「〜にかけて」 (chỉ khoảng thời gian/không gian bao quát ước chừng, không mang sắc thái triệt để đến từng ngóc ngách như に至るまで)."},{pattern:"〜を経[へ]て",meaning:"Trải qua (một quá trình/nhiều giai đoạn) rồi mới… — trung lập, hợp văn công vụ/báo chí",priority:"common",explanation:"Mẫu 「〜を経て」 diễn tả ý nghĩa 'trải qua một khoảng thời gian dài, qua các giai đoạn, thủ tục hoặc địa điểm trung gian' để dẫn đến một kết quả hay trạng thái hiện tại. Ngữ pháp này kết hợp trực tiếp với danh từ chỉ thời gian, quy trình, sự biến đổi hoặc địa điểm (như 歳月, 審査, 協議, シンガポール...). Mang sắc thái khách quan, trung lập và trang trọng, mẫu này rất phổ biến trong văn viết, báo chí, tin tức thời sự và báo cáo chính thức.",examples:[{sentence:"数回にわたる慎重な協議を経て、両国はついに歴史的な和平協定の締結に至った。",translation:"Trải qua nhiều vòng đàm phán thận trọng, hai nước cuối cùng đã đi đến việc ký kết hiệp định hòa bình mang tính lịch sử."},{sentence:"この新薬は10年以上に及ぶ臨床試験を経て、ようやく実用化が承認された。",translation:"Loại thuốc mới này trải qua hơn 10 năm thử nghiệm lâm sàng mới chính thức được phê duyệt đưa vào ứng dụng thực tế."}],dialogue:{title:"Dự án mới được phê duyệt",lines:[{speaker:"A",text:"田中さん、新規事業の企画書が無事に役員会を通過したそうですね。",translation:"Anh Tanaka, nghe nói bản đề án kinh doanh mới đã được ban giám đốc thông qua suôn sẻ rồi nhỉ."},{speaker:"B",text:"ええ、半年間の市場調査と度重なる見直しを経て、ようやく正式に予算が下りました。",translation:"Vâng, trải qua nửa năm khảo sát thị trường và nhiều lần xem xét chỉnh sửa, cuối cùng ngân sách cũng chính thức được duyệt."},{speaker:"A",text:"長い道のりでしたね。これからの本格的なスタートを応援しています。",translation:"Quả là một chặng đường dài. Tôi rất ủng hộ và mong chờ bước triển khai chính thức sắp tới."}]},commonMistake:{wrong:"知人を経て、現在の会社を紹介してもらいました。",correct:"知人を通じて、現在の会社を紹介してもらいました。",why:"「〜を経て」 dùng cho quá trình, thời gian, thủ tục hoặc địa điểm quá cảnh chứ không dùng cho người làm trung gian kết nối (trường hợp này phải dùng 「〜を通じて／〜を通して」)."},note:"Ngoài việc biểu thị tiến trình thời gian và quy trình thủ tục, mẫu này còn dùng cho chuyển động không gian với nghĩa 'đi qua / quá cảnh tại một địa điểm trung gian' (ví dụ: ドバイを経てヨーロッパへ向かう)."},{pattern:"使[つか]い分[わ]け：に至[いた]って ≠ に至[いた]るまで ≠ を経[へ]て（≠ 末[すえ]に・上[うえ]で）",meaning:"Phân biệt cốt lõi: に至って (đỉnh điểm nghiêm trọng, có phê phán chậm trễ) ≠ に至るまで (phạm vi/mức độ) ≠ を経て (quá trình trung lập) ≠ 末に (cảm xúc vất vả, N2) ≠ 上で (trình tự bình thường, N2 bài74)",priority:"common",explanation:'「〜に至って」diễn tả sự việc tiến triển đến tình thế nghiêm trọng, cấp bách thì mới nhận thức hoặc hành động (thường mang sắc thái phê phán sự chậm trễ, "mãi đến khi nước đến chân"). Trái lại,「〜を経て」chỉ đơn thuần diễn tả việc trải qua một quá trình, giai đoạn hoặc thủ tục mang tính trung lập để đạt được kết quả. Ngoài ra,「〜に至るまで」nhấn mạnh phạm vi hoặc mức độ trải rộng đến tận cùng của sự việc.',examples:[{sentence:"被害が全国に拡大するに至って、政府はようやく重い腰を上げた。",translation:"Mãi đến khi thiệt hại lan rộng ra toàn quốc, chính phủ mới chịu bắt tay vào hành động."},{sentence:"この新薬は、10年以上の臨床試験を経て、ようやく実用化が認められた。",translation:"Loại thuốc mới này sau khi trải qua hơn 10 năm thử nghiệm lâm sàng thì cuối cùng cũng đã được phê duyệt đưa vào sử dụng."}],dialogue:{title:"Đối phó bê bối nội bộ",lines:[{speaker:"A",text:"内部告発がメディアに報道されるに至って、経営陣はやっと記者会見を開いたね。",translation:"Mãi đến khi việc tố cáo nội bộ bị truyền thông đưa tin, ban giám đốc mới chịu mở cuộc họp báo nhỉ."},{speaker:"B",text:"もっと早い段階で適切な調査を経て対応していれば、ここまでの事態にならなかったのに。",translation:"Nếu ngay từ giai đoạn sớm hơn họ đã xử lý thông qua một cuộc điều tra thích hợp thì sự việc đâu đến nông nỗi này."},{speaker:"A",text:"本当にそうだね。初動の遅れが会社の信用を失墜させてしまったよ。",translation:"Đúng vậy thật. Sự chậm trễ trong xử lý ban đầu đã làm đánh mất hoàn toàn uy tín của công ty."}]},commonMistake:{wrong:"３回にわたる面接に至って、ようやく採用が内定した。",correct:"３回にわたる面接を経て、ようやく採用が内定した。",why:"「〜に至って」chỉ dùng khi sự việc đã đi đến bước đường cùng hoặc tình thế nghiêm trọng; với quy trình, thủ tục mang tính trung lập như phỏng vấn thì phải dùng「〜を経て」."},note:"Phân biệt thêm:「〜末に」nhấn mạnh kết quả sau một quá trình dài vất vả, dằn vặt (N2), còn「〜上で」chỉ thứ tự hành động bình thường theo trình tự (N2 bài 74)."}],99:[{pattern:"〜（が）ゆえ（に）",meaning:"Vì (lý do trang trọng, mang tính lý luận/khách quan) — văn viết học thuật, xã luận, công văn",priority:"core",explanation:'「〜（が）ゆえ（に）」mang nghĩa "chính vì / do bởi", dùng để diễn tả nguyên nhân, lý do mang tính logic dẫn đến một kết quả tất yếu, khó tránh khỏi hoặc mang tính số phận. Đây là lối diễn đạt văn viết cổ điển, trang trọng, thường xuất hiện trong văn phong học thuật, xã luận báo chí, tác phẩm văn học hoặc công văn. Mẫu câu này không dùng cho các tình huống sinh hoạt thường nhật và không đi kèm câu mệnh lệnh, nhờ vả trực tiếp.',examples:[{sentence:"経験が浅いがゆえに、予期せぬトラブルに対して適切な判断を下すことができなかった。",translation:"Chính vì còn ít kinh nghiệm nên tôi đã không thể đưa ra phán đoán thích hợp trước sự cố bất ngờ."},{sentence:"有名人であるがゆえの苦悩は、一般の人々にはなかなか理解されないものだ。",translation:"Những nỗi khổ chỉ vì là người nổi tiếng thì người bình thường khó lòng mà thấu hiểu được."}],dialogue:{title:"Đánh giá tiến độ dự án",lines:[{speaker:"A",text:"今回のシステム刷新は、開発期間が短縮されたがゆえに、検証作業が不十分になってしまったようです。",translation:"Đợt nâng cấp hệ thống lần này, có vẻ như chính vì thời gian phát triển bị rút ngắn nên việc kiểm thử đã không được trọn vẹn."},{speaker:"B",text:"確かに、スケジュールの過密さがトラブルを招いた最大の要因ですね。",translation:"Đúng vậy, lịch trình quá gấp gáp chính là nguyên nhân lớn nhất dẫn đến sự cố."},{speaker:"A",text:"今後はスピードを重視するがゆえの品質低下を防ぐため、工程の見直しを徹底しましょう。",translation:"Từ nay về sau, để ngăn chặn tình trạng giảm chất lượng do quá chú trọng tốc độ, chúng ta hãy rà soát kỹ lại các công đoạn."}]},commonMistake:{wrong:"今日は熱があるがゆえに、会社を休ませていただきます。",correct:"今日は熱がありますので、会社を休ませていただきます。",why:"「〜ゆえ（に）」mang sắc thái văn viết trang trọng/học thuật, không dùng để nêu lý do cá nhân trong đời sống thường nhật hay khi xin phép."},note:"Khi bổ nghĩa trực tiếp cho một danh từ đứng sau, mẫu này biến đổi thành dạng「〜（が）ゆえの＋N」chứ không dùng「〜ゆえに＋N」."},{pattern:"〜とあって",meaning:"Vì tình huống đặc biệt/hiếm nên (hệ quả khách quan) — hiện tượng xã hội, KHÔNG dùng cho ý chí của chính người nói",priority:"common",explanation:'Mẫu ngữ pháp 「〜とあって」 dùng để diễn tả ý nghĩa "bởi vì rơi vào một hoàn cảnh hay tình huống đặc biệt/hiếm có, nên đương nhiên dẫn đến một kết quả hoặc hiện tượng tương ứng". Vế sau luôn là một sự việc, trạng thái khách quan có thể quan sát được (như sự đông đúc, lượng tiêu thụ tăng vọt, sự quan tâm của công chúng). Mẫu câu này thường mang sắc thái khách quan, hay dùng trong tin tức, báo chí hoặc phóng sự xã hội, và tuyệt đối không đi cùng các đuôi câu biểu thị ý chí, nguyện vọng hay nhờ vả của người nói.',examples:[{sentence:"今年の夏は記録的な猛暑とあって、エアコンや清涼飲料水の売れ行きが急増している。",translation:"Vì mùa hè năm nay nắng nóng kỷ lục nên lượng tiêu thụ máy điều hòa và nước giải khát đang tăng vọt."},{sentence:"世界的に有名な指揮者が来日するとあって、コンサートのチケットは発売開始からわずか数分で完売した。",translation:"Vì vị nhạc trưởng nổi tiếng thế giới sang Nhật biểu diễn nên vé buổi hòa nhạc đã bán hết sạch chỉ sau vài phút mở bán."}],dialogue:{title:"Lễ hội pháo hoa đông đúc",lines:[{speaker:"A",text:"3年ぶりの花火大会の開催とあって、駅前も会場周辺もすごい人出だね。",translation:"Vì là lễ hội pháo hoa được tổ chức lại sau 3 năm nên trước nhà ga lẫn quanh khu vực sự kiện đều đông nghẹt người nhỉ."},{speaker:"B",text:"そうだね。浴衣を着た若い人たちも多くて、街全体がとても賑わっているよ。",translation:"Đúng thế thật. Nhiều bạn trẻ mặc yukata ghê, cả con phố náo nhiệt hẳn lên."},{speaker:"A",text:"これ以上混雑する前に、早めに鑑賞スペースを確保しておこう。",translation:"Trước khi đông đúc hơn nữa, chúng ta hãy nhanh chóng tìm chỗ ngồi xem thôi."}]},commonMistake:{wrong:"今週末は久しぶりの連休とあって、家族と一緒に温泉に行きたいです。",correct:"今週末は久しぶりの連休なので、家族と一緒に温泉に行きたいです。",why:"Vế sau của 「〜とあって」 chỉ dùng để miêu tả hiện tượng, sự việc khách quan, không được kết hợp với các cấu trúc thể hiện ý chí, mong muốn cá nhân của người nói như 「〜たい」 hay 「〜つもりだ」."},note:'Khác với 「〜ゆえ（に）」 mang tính trang trọng/nguyên nhân trừu tượng, 「〜とあって」 nhấn mạnh vào "bối cảnh/sự kiện đặc biệt trước mắt" dẫn đến hiện tượng náo nhiệt, đông đúc hay phản ứng rõ rệt có thể nhìn thấy được ở vế sau.'},{pattern:"ゆえ（に） ≠ とあって の 使[つか]い分[わ]け",meaning:"ゆえに = lý do lý luận trừu tượng, chủ ngữ bất kỳ (kể cả bản thân); とあって = vì HOÀN CẢNH ĐẶC BIỆT/HIẾM cụ thể nên xảy ra hiện tượng khách quan (xã hội/đám đông)",priority:"common",explanation:"「ゆえ（に）」mang sắc thái văn viết trang trọng, dùng để giải thích mối quan hệ nhân quả mang tính lý luận, nguyên nhân sâu xa hoặc bản chất trừu tượng và có thể dùng cho bất kỳ chủ ngữ nào (kể cả bản thân). Ngược lại,「とあって」nhấn mạnh nguyên nhân là một tình huống hoặc sự kiện đặc biệt, hiếm thấy, dẫn đến một kết quả/hiện tượng mang tính khách quan (thường là phản ứng của số đông, xã hội). Do đó,「とあって」không dùng cho nguyên nhân bản chất trừu tượng hay để thể hiện ý chí, nguyện vọng cá nhân của người nói.",examples:[{sentence:"若さゆえに、周囲の助言に素直に耳を傾けられず、多くの失敗を重ねてしまった。",translation:"Chính vì còn quá trẻ người non dạ nên tôi đã không thể thành thật lắng nghe lời khuyên của mọi người xung quanh và liên tiếp phạm phải nhiều sai lầm."},{sentence:"人気アイドルのラストコンサートとあって、会場の前には早朝から長蛇の列ができていた。",translation:"Vì là buổi hòa nhạc cuối cùng của thần tượng nổi tiếng nên ngay từ sáng sớm trước hội trường đã có một hàng dài người xếp hàng."}],dialogue:{title:"Hội chợ sách cuối tuần",lines:[{speaker:"A",text:"週末は有名作家のサイン会とあって、会場はものすごい人出になりそうだね。",translation:"Vì cuối tuần có buổi ký tặng của nhà văn nổi tiếng nên chắc hội trường sẽ đông nghịt người đấy nhỉ."},{speaker:"B",text:"そうだね。年に一度の大型イベントだし、早く行かないと入場制限がかかるかもしれないよ。",translation:"Đúng vậy. Dù sao cũng là sự kiện lớn mỗi năm một lần, không đến sớm có khi bị giới hạn vào cửa đấy."},{speaker:"A",text:"限定本も販売されるらしいから、朝一番で並ぶことにするよ。",translation:"Nghe nói còn bán cả ấn bản giới hạn nữa nên tôi quyết định sẽ đi xếp hàng từ đợt đầu tiên luôn."}]},commonMistake:{wrong:"彼は真面目すぎる性格とあって、時に融通が利かない。",correct:"彼は真面目すぎる性格ゆえに、時に融通が利かない。",why:"「とあって」chỉ dùng cho tình huống/sự kiện đặc biệt phát sinh hiện tượng khách quan, còn nguyên nhân xuất phát từ tính cách, phẩm chất hay lý do trừu tượng thì bắt buộc dùng「ゆえ（に）」."},note:"Vế sau của「とあって」luôn là hiện tượng thực tế xảy ra một cách tự nhiên/khách quan, tuyệt đối không đi cùng câu thể hiện ý chí, nguyện vọng của người nói như「〜たい」「〜つもりだ」hay câu mệnh lệnh, nhờ vả."},{pattern:"ゆえ（に）（N1） ≠ だけに（N2・第76課）の 使[つか]い分[わ]け",meaning:"だけに (N2) = chính vì X nên kết quả Y tương xứng/bất ngờ, mang sắc thái cảm xúc, dùng được cả văn nói; ゆえに (N1) = lý do lý luận thuần túy, KHÔNG mang sắc thái tương xứng/bất ngờ, chỉ dùng văn viết trang trọng cao cấp",priority:"common",explanation:"「だけに」 (N2) dùng để nhấn mạnh mối quan hệ nhân quả mà trong đó vế sau là kết quả, mức độ cảm xúc (vui, buồn, thất vọng...) tương xứng hoặc vượt trên mức kỳ vọng thông thường từ vế trước, dùng linh hoạt trong cả văn nói lẫn văn viết. Ngược lại, 「ゆえ（に）」 (N1) là mẫu câu thuộc phong cách văn viết trang trọng, cổ kính, dùng để trình bày lý do mang tính logic, lý luận học thuật hoặc nguyên nhân khách quan mà không chứa đựng hàm ý 'kết quả tương xứng với nỗ lực/kỳ vọng'. Vì vậy, không dùng 「ゆえに」 cho các biểu đạt cảm xúc đời thường, và không dùng 「だけに」 trong văn bản nghị luận hay quy phạm đòi hỏi sự khách quan tuyệt đối.",examples:[{sentence:"科学的根拠が不十分であるがゆえに、この仮説は学会で受け入れられなかった。",translation:"Chính vì căn cứ khoa học chưa đầy đủ mà giả thuyết này đã không được hội đồng học thuật chấp nhận."},{sentence:"長年期待されていた大型プロジェクトだけに、中止が決まった時の関係者の落胆は大きい。",translation:"Chính vì là dự án quy mô lớn được kỳ vọng suốt nhiều năm nên sự thất vọng của những người liên quan khi có quyết định hủy bỏ là vô cùng lớn."}],dialogue:{title:"Kết quả cuộc thi",lines:[{speaker:"A",text:"優勝候補と言われていただけに、決勝で敗れた悔しさは言葉にできないよ。",translation:"Chính vì được đánh giá là ứng cử viên vô địch nên nỗi tiếc nuối khi để thua ở trận chung kết thật không lời nào tả xiết."},{speaker:"B",text:"全力を尽くしたんだから胸を張っていいよ。相手が一枚上手だっただけさ。",translation:"Cậu đã nỗ lực hết sức rồi nên cứ tự hào đi. Chỉ là đối thủ cao tay hơn một bậc thôi."},{speaker:"A",text:"ありがとう。この悔しさをバネにして、来年こそリベンジするよ。",translation:"Cảm ơn cậu. Tớ sẽ lấy nỗi thất vọng này làm bàn đạp để năm sau nhất định phục thù."}]},commonMistake:{wrong:"毎日一生懸命練習したゆえに、合格した時の嬉しさは格別だった。",correct:"毎日一生懸命練習しただけに、合格した時の嬉しさは格別だった。",why:"Khi diễn tả tâm trạng, cảm xúc dâng trào tương xứng với nỗ lực bỏ ra (嬉しさは格別) thì phải dùng 「だけに」, không dùng mẫu câu mang sắc thái lập luận logic khách quan như 「ゆえに」."},note:"「ゆえに」 có thể đứng độc lập ở đầu câu như một liên từ kết nối (故に、〜 = Do đó / Vì vậy) trong văn nghị luận, trong khi 「だけに」 tuyệt đối không có cách dùng làm liên từ đầu câu."}],100:[{pattern:"〜ばこそ（〜のだ）",meaning:"Chính vì… (mới)… — nhấn mạnh lý do DUY NHẤT, tích cực; câu thường kết bằng のだ",priority:"core",explanation:'Mẫu 「〜ばこそ」 dùng để nhấn mạnh lý do duy nhất, mang tính cốt lõi dẫn đến một hành động hoặc kết quả tích cực ở vế sau với ý nghĩa "chính vì... nên mới...". Vế sau câu thường kết thúc bằng 「〜のだ／〜のである」 để khẳng định và lý giải cho hành vi, quyết định hoặc tình cảm của người nói. Về mặt ngữ pháp, mẫu này kết hợp với động từ/tính từ ở thể điều kiện 「ば」 cộng với 「こそ」, riêng danh từ và tính từ đuôi ナ sẽ đi với 「であればこそ」.',examples:[{sentence:"親は子どもの将来を思えばこそ、時には厳しく叱ることもあるのだ。",translation:"Chính vì nghĩ cho tương lai của con cái nên cha mẹ đôi khi mới mắng mỏ nghiêm khắc như vậy."},{sentence:"皆様の温かいご支援があればこそ、我が社は危機を乗り越えて今日を迎えることができたのである。",translation:"Chính nhờ có sự ủng hộ nồng nhiệt của quý vị mà công ty chúng tôi mới có thể vượt qua khủng hoảng và có được ngày hôm nay."}],dialogue:{title:"Lời khuyên của cấp trên",lines:[{speaker:"A",text:"部長、最近私に対して少し指導が厳しすぎるのではないでしょうか。",translation:"Trưởng phòng ơi, dạo này anh có thấy mình hơi quá khắt khe khi chỉ bảo em không ạ?"},{speaker:"B",text:"君の将来の成長に期待していればこそ、あえて厳しく接しているんだよ。",translation:"Chính vì kỳ vọng vào sự trưởng thành tương lai của cậu nên tôi mới cố tình nghiêm khắc đấy chứ."},{speaker:"A",text:"そうだったんですね。期待に応えられるよう精一杯頑張ります！",translation:"Thì ra là vậy ạ. Em sẽ cố gắng hết mình để không phụ sự kỳ vọng của anh!"}]},commonMistake:{wrong:"雨が降ればこそ、学校に遅刻してしまったのだ。",correct:"雨が降ったせいで、学校に遅刻してしまったのだ。",why:"Mẫu 「〜ばこそ」 dùng để nhấn mạnh lý do tích cực hoặc thấu hiểu hành động, tuyệt đối không dùng để viện cớ hay giải thích cho hậu quả, kết quả tiêu cực."},note:"Khác với 「〜からこそ」 có thể dùng tương đối linh hoạt, 「〜ばこそ」 mang sắc thái trang trọng, văn viết cao hơn và không bao giờ dùng cho vế sau có kết quả xấu."},{pattern:"〜（が）あってこそ",meaning:"Phải có… thì mới có được… — nhấn mạnh điều kiện NỀN TẢNG không thể thiếu",priority:"common",explanation:"Mẫu ngữ pháp 「〜（が）あってこそ」 dùng để nhấn mạnh rằng chỉ khi có danh từ N (điều kiện nền tảng, cốt lõi nhất) thì kết quả hoặc sự việc ở vế sau mới có thể tồn tại và thành hiện thực. Cấu trúc này thường đi kèm với những danh từ chỉ yếu tố then chốt như sức khỏe, sự nỗ lực, niềm tin hay sự giúp đỡ từ người khác. Vế sau luôn biểu thị kết quả tích cực, sự thành công hoặc đánh giá cao, tuyệt đối không dùng với kết quả tiêu cực. Sắc thái câu thể hiện sự trân trọng và lòng biết ơn sâu sắc đối với điều kiện tiền đề đó.",examples:[{sentence:"お客様からの信頼があってこそ、わが社の事業は成り立っているのです。",translation:"Chính nhờ có sự tin tưởng từ khách hàng thì hoạt động kinh doanh của công ty chúng tôi mới có thể duy trì và phát triển được."},{sentence:"どんなに才能があっても、日々の地道な努力があってこそ一流の選手になれる。",translation:"Dù có tài năng đến đâu đi nữa, phải có sự nỗ lực bền bỉ mỗi ngày thì mới có thể trở thành một vận động viên hàng đầu."}],dialogue:{title:"Thành công của dự án",lines:[{speaker:"A",text:"今回の大型プロジェクトの成功は、チーム全員の協力があってこそ成し遂げられたものですね。",translation:"Thành công của dự án lớn lần này thực sự là nhờ có sự chung sức hợp tác của toàn thể thành viên trong đội mới đạt được đấy nhỉ."},{speaker:"B",text:"本当にそうですね。誰か一人でも欠けていたら、納期に間に合わなかったと思います。",translation:"Đúng là như vậy thật. Tôi nghĩ nếu thiếu đi dù chỉ một người thì chắc đã không kịp thời hạn giao hàng rồi."},{speaker:"A",text:"ええ、皆さんの日頃の頑張りに改めて感謝したいです。本当にお疲れ様でした！",translation:"Vâng, tôi muốn một lần nữa cảm ơn sự cố gắng không ngừng nghỉ của mọi người. Mọi người đã vất vả nhiều rồi!"}]},commonMistake:{wrong:"健康があってこそ、病気になってしまった。",correct:"健康があってこそ、思い切り仕事や趣味に打ち込むことができる。",why:"Vế sau của 「〜（が）あってこそ」 bắt buộc phải là kết quả tích cực, thành tựu hoặc sự việc có thể thực hiện được, không dùng cho kết quả tiêu cực hay chuyện không may xảy ra."},note:"Khác với 「〜ばこそ」 (nhấn mạnh lý do/nguyên nhân và đi kèm động từ/tính từ thể điều kiện), 「〜（が）あってこそ」 bắt buộc đi với Danh từ để nhấn mạnh sự tồn tại của N là tiền đề không thể thiếu."},{pattern:"ばこそ ≠ あってこそ の使[つか]い分[わ]け",meaning:"Phân biệt: ばこそ nhấn lý do duy nhất từ động từ/tính từ ý chí ≠ あってこそ nhấn điều kiện nền tảng (danh từ cụ thể)",priority:"common",explanation:"「〜ばこそ」nhấn mạnh lý do cốt lõi hoặc động cơ xuất phát từ ý chí, cảm xúc (thường đi với động từ/tính từ thể điều kiện) dẫn đến một hành động hay thái độ có chủ đích ở vế sau. Ngược lại,「〜あってこそ」đi trực tiếp sau danh từ để nhấn mạnh điều kiện nền tảng, sự tồn tại thiết yếu mang tính quyết định (phải có A thì B mới có thể thành lập hoặc tiếp tục). Tóm lại,「ばこそ」tập trung vào nguyên nhân, lý do chủ quan (chính vì...), còn「あってこそ」tập trung vào yếu tố nền móng không thể thiếu (phải có... mới có).",examples:[{sentence:"子どもの将来を案じればこそ、親はあえて辛い現実を教えるのだ。",translation:"Chính vì lo nghĩ cho tương lai của con, cha mẹ mới chủ ý dạy cho con biết về hiện thực khắc nghiệt."},{sentence:"どんなに優れた企画も、地道な実行力があってこそ初めて成果につながる。",translation:"Dù kế hoạch có xuất sắc đến đâu, phải có năng lực thực thi bền bỉ thì mới dẫn tới thành quả."}],dialogue:{title:"Động lực luyện tập",lines:[{speaker:"A",text:"監督、今日のメニューはいくら何でもハードすぎますよ…",translation:"Huấn luyện viên ơi, bài tập hôm nay dù sao đi nữa cũng nặng quá ạ…"},{speaker:"B",text:"限界を超えて成長してほしいと思えばこそ、あえて負荷をかけているんだ。",translation:"Chính vì muốn các em vượt qua giới hạn để tiến bộ nên thầy mới chủ đích tăng cường độ đấy."},{speaker:"A",text:"わかりました。先生の熱心なご指導があってこそですから、全力で食らいつきます！",translation:"Em hiểu rồi ạ. Chính nhờ có sự hướng dẫn tận tâm của thầy nên em sẽ cố gắng theo đến cùng!"}]},commonMistake:{wrong:"あなたを心配するがあってこそ、あえて厳しい忠告をしたのです。",correct:"あなたを心配すればこそ、あえて厳しい忠告をしたのです。",why:"Khi muốn nhấn mạnh động cơ tâm lý thôi thúc hành vi của người nói (chính vì lo lắng nên mới khuyên), phải chia động từ sang thể điều kiện kết hợp với「〜ばこそ」chứ không dùng「があってこそ」."},note:"Vế sau của「〜ばこそ」thường kết thúc bằng「〜のだ／〜のです」để giải thích lý do, trong khi「〜あってこそ」thường kết hợp với「初めて／成り立つ」để diễn tả sự tạo thành kết quả."},{pattern:"ばこそ・あってこそ ≠ からこそ（N2）",meaning:"Phân biệt với からこそ (N2): からこそ tự nhiên/phổ biến (khẩu ngữ+viết); ばこそ／あってこそ (N1) văn viết trang trọng, cổ điển hơn",priority:"common",explanation:'Cả ba mẫu ngữ pháp đều dùng để nhấn mạnh lý do cốt lõi hoặc điều kiện tiên quyết mang nghĩa "chính vì... mới..." hoặc "phải có... mới có được". Trong đó, 「からこそ」(N2) có tính phổ biến cao nhất, được dùng linh hoạt và tự nhiên trong cả giao tiếp hằng ngày lẫn văn bản. Ngược lại, 「ばこそ」và「あってこそ」(N1) mang sắc thái trang trọng, tính văn viết hoặc diễn thuyết cao hơn, nhằm nhấn mạnh tuyệt đối tính tất yếu và tầm quan trọng sống còn của điều kiện.',examples:[{sentence:"皆様の温かいご支援があってこそ、我が社は創立30周年を迎えることができました。",translation:"Chính nhờ có sự ủng hộ nồng nhiệt của quý vị mà công ty chúng tôi mới có thể đón mừng kỷ niệm 30 năm thành lập."},{sentence:"あなたの将来を本気で心配しているからこそ、あえて厳しいアドバイスをしているんだよ。",translation:"Chính vì thực sự lo lắng cho tương lai của bạn nên tôi mới đưa ra lời khuyên nghiêm khắc đấy."}],dialogue:{title:"Lời khuyên từ tiền bối",lines:[{speaker:"A",text:"先輩、いつも私のミスを厳しくご指導いただき、感謝しています。",translation:"Tiền bối, cảm ơn anh vì lúc nào cũng nghiêm khắc chỉ bảo những lỗi sai của em."},{speaker:"B",text:"君の成長を期待しているからこそ、あえて甘やかさないようにしているんだよ。",translation:"Chính vì kỳ vọng vào sự tiến bộ của cậu nên anh mới cố tình không nuông chiều đấy."},{speaker:"A",text:"はい、そのご指導があってこそ、今の自分があるのだと実感しています。",translation:"Vâng, em thực sự cảm nhận được rằng phải có sự chỉ dạy đó thì mới có em của ngày hôm nay."}]},commonMistake:{wrong:"今日は疲れていればこそ、早く寝たいんだ。",correct:"今日は疲れているからこそ、早く寝たいんだ。",why:"「ばこそ」mang tính trang trọng và thường nhấn mạnh động lực/kết quả lớn lao, không dùng cho các lý do sinh hoạt đời thường, cá nhân như「からこそ」."},note:"Vế sau của「ばこそ」thường đi kèm với「〜のだ／〜わけだ」để khẳng định kết quả tích cực, tuyệt đối không dùng cho kết quả tiêu cực hay các câu mang tính nhờ vả, mệnh lệnh thông thường."}],101:[{pattern:"〜んがため（に）",meaning:"Nhằm để... — mục đích quyết liệt, ý chí gắng sức đến cùng (văn viết cứng, mang sắc thái khẩn thiết/sinh tồn)",priority:"core",explanation:'Mẫu ngữ pháp 「〜んがため（に）」 biểu thị mục đích lớn lao, mang ý nghĩa "với mong muốn/nhằm để...", thể hiện ý chí quyết tâm cao độ hoặc sự nỗ lực tột cùng của chủ thể. Đây là lối diễn đạt văn viết cổ kính, trang trọng, thường xuất hiện trong văn học, báo chí hoặc các bài diễn thuyết mang tính lịch sử, thời sự. Động từ kết nối bằng cách lấy dạng phủ định 「ない」 bỏ 「ない」 cộng với 「んがため（に）」, riêng động từ 「する」 biến đổi đặc biệt thành 「せんがため（に）」. Vế sau của câu thường miêu tả những hành động quyết liệt, chấp nhận gian khổ hoặc hy sinh để đạt được mục đích đó, không dùng cho sinh hoạt thường nhật.',examples:[{sentence:"彼は真実を明らかにせんがために、身の危険を顧みず調査を続けた。",translation:"Nhằm làm sáng tỏ chân tướng sự thật, anh ấy đã bất chấp hiểm nguy đến tính mạng để tiếp tục cuộc điều tra."},{sentence:"難病に苦しむ人々を救わんがため、研究者たちは日夜新薬の開発に没頭している。",translation:"Nhằm cứu giúp những bệnh nhân mắc bệnh hiểm nghèo, các nhà nghiên cứu đang ngày đêm miệt mài phát triển loại thuốc mới."}],dialogue:{title:"Quyết tâm vì nghệ thuật",lines:[{speaker:"A",text:"彼は自らの理想とする映画を完成させんがために、私財をすべて投げ打ったらしいよ。",translation:"Nghe nói để hoàn thành bộ phim lý tưởng của đời mình, anh ấy đã dốc cạn toàn bộ tài sản cá nhân đấy."},{speaker:"B",text:"ええ、周囲の反対を押し切ってまで情熱を注ぐ姿には、本当に圧倒されるね。",translation:"Ừ, nhìn dáng vẻ dồn trọn tâm huyết bất chấp cả sự can ngăn của mọi người xung quanh, quả thực đáng khâm phục."},{speaker:"A",text:"そこまでの覚悟があるからこそ、多くの人の心を動かす名作が生まれるんだろう。",translation:"Chính vì có sự quyết tâm và giác ngộ đến mức đó nên mới tạo ra được kiệt tác lay động lòng người như vậy nhỉ."}]},commonMistake:{wrong:"彼は国を改革しんがために、政治の世界に飛び込んだ。",correct:"彼は国を改革せんがために、政治の世界に飛び込んだ。",why:"Động từ nhóm 3 「する」 khi kết hợp với mẫu ngữ pháp này bắt buộc phải biến đổi bất quy tắc thành 「せんがため（に）」, không chia theo thể ない thông thường thành 「しんがため」."},note:"Mẫu này mang sắc thái ý chí vô cùng quyết liệt và trang nghiêm nên tuyệt đối không dùng cho các hành động hay mục đích vụn vặt hằng ngày (như đi chợ, mua sắm); trường hợp thông thường hãy dùng 「〜ために」."},{pattern:"〜べく",meaning:"Để (mà)... — nêu mục đích của một hành động cụ thể, văn viết trang trọng/tường thuật; vế sau KHÔNG được là mệnh lệnh・thỉnh cầu",priority:"common",explanation:'Mẫu ngữ pháp 「〜べく」 mang ý nghĩa "để, nhằm mục đích...", dùng để diễn đạt việc thực hiện một hành động cụ thể nhằm đạt được mục tiêu xác định. Mẫu câu này thuộc phong cách văn viết trang trọng, mang tính tường thuật cao, thường xuất hiện trong báo chí, văn kiện kinh doanh, bài luận hoặc phát biểu trịnh trọng. Vế sau luôn là hành động có ý chí của người nói và tuyệt đối không đi cùng các hình thức mệnh lệnh, nhờ vả hay tác động đến người nghe.',examples:[{sentence:"弊社は海外市場を開拓すべく、現地法人の設立準備を進めている。",translation:"Công ty chúng tôi đang xúc tiến việc chuẩn bị thành lập pháp nhân tại địa phương nhằm mở rộng thị trường ra nước ngoài."},{sentence:"彼は最新の医療技術を学ぶべく、アメリカへの留学を決意した。",translation:"Anh ấy đã quyết định đi du học Mỹ để học hỏi những kỹ thuật y tế tiên tiến nhất."}],dialogue:{title:"Kế hoạch mở rộng kinh doanh",lines:[{speaker:"A",text:"来期のアジア展開を成功させるべく、今から市場調査を強化すべきでしょうか。",translation:"Để kế hoạch mở rộng sang châu Á kỳ tới thành công, chúng ta có nên đẩy mạnh khảo sát thị trường từ bây giờ không ạ?"},{speaker:"B",text:"ええ、現地のニーズを正確に把握すべく、専門チームを現地へ派遣しましょう。",translation:"Ừ, nhằm nắm bắt chính xác nhu cầu của địa phương, chúng ta hãy cử đội ngũ chuyên trách sang đó."},{speaker:"A",text:"承知いたしました。早速メンバーの選定と日程調整に入ります。",translation:"Tôi đã rõ. Tôi sẽ tiến hành lựa chọn thành viên và sắp xếp lịch trình ngay lập tức."}]},commonMistake:{wrong:"試験に合格すべく、毎日しっかり復習してください。",correct:"試験に合格するために、毎日しっかり復習してください。",why:"Vế sau của 「〜べく」 không được dùng câu nhờ vả, mệnh lệnh hay khuyên bảo người khác (như 〜てください); trường hợp này phải dùng 「〜ために」."},note:"Động từ 「する」 khi kết hợp với mẫu này có thể chuyển thành 「すべく」 hoặc 「するべく」, trong đó dạng 「すべく」 mang tính cổ và trang trọng hơn."},{pattern:"〜んがため（に） ≠ 〜べく の 使[つか]い分[わ]け",meaning:"んがため(に) nhấn ý chí quyết liệt/sinh tồn cực độ, thường mang sắc thái bi tráng; べく trung tính hơn, chỉ tường thuật mục đích của một hành động cụ thể (báo cáo/xã luận)",priority:"common",explanation:'Cả hai mẫu ngữ pháp đều mang nghĩa "nhằm để / với mục đích", thuộc văn phong viết trang trọng nhưng có sắc thái biểu cảm khác biệt. 「〜んがため（に）」nhấn mạnh ý chí quyết tâm cao độ, sẵn sàng hy sinh hoặc mang tính chất sinh tử, bi tráng của chủ thể khi theo đuổi một mục tiêu to lớn. Ngược lại, 「〜べく」mang sắc thái khách quan và trung tính hơn, thường dùng trong báo cáo công vụ, thông cáo hoặc xã luận để tường thuật mục đích của một hành động, kế hoạch cụ thể. Cả hai mẫu đều không dùng câu mang tính nhờ vả, mệnh lệnh hoặc sai khiến ở vế sau.',examples:[{sentence:"国家の独立と尊厳を守らんがために、兵士たちは最前線で命を懸けて戦った。",translation:"Nhằm bảo vệ nền độc lập và lòng tự tôn của quốc gia, các binh sĩ đã liều mình chiến đấu nơi tiền tuyến."},{sentence:"弊社は海外市場への本格的な進出を果たすべく、現地法人を設立することとした。",translation:"Nhằm thực hiện việc tiến ra thị trường quốc tế một cách bài bản, công ty chúng tôi đã quyết định thành lập pháp nhân tại địa phương."}],dialogue:{title:"Triển khai dự án mới",lines:[{speaker:"A",text:"新規事業の立ち上げを成功させるべく、各部署から精鋭を集めたそうですね。",translation:"Nghe nói anh đã tập hợp các nhân sự tinh anh từ các phòng ban nhằm đưa việc ra mắt dự án mới tới thành công phải không?"},{speaker:"B",text:"ええ、社運を賭けたプロジェクトですから、万全の体制で臨みたいと考えています。",translation:"Vâng, vì đây là dự án đặt cược cả vận mệnh công ty nên tôi muốn đối đầu với sự chuẩn bị chu đáo nhất."},{speaker:"A",text:"期待しています。何か協力できることがあれば遠慮なく言ってください。",translation:"Tôi rất kỳ vọng đấy. Nếu có gì cần hỗ trợ thì đừng ngại nói nhé."}]},commonMistake:{wrong:"新型ウイルスの感染経路を特定せんがために、調査委員会が設置された。",correct:"新型ウイルスの感染経路を特定すべく、調査委員会が設置された。",why:"Khi tường thuật sự việc mang tính chất công vụ, báo cáo khách quan trong tin tức, cần dùng 「〜べく」 thay vì 「〜んがため（に）」 vốn mang nặng cảm xúc cá nhân và quyết tâm sinh tử."},note:"Cần lưu ý cách chia đặc biệt của động từ nhóm 3 「する」: đi với 「んがため」 sẽ là 「せんがため」, còn đi với 「べく」 sẽ chuyển thành 「すべく」 (hoặc 「するべく」)."},{pattern:"〜んがため（に）・〜べく ≠ 〜ために・〜ように（N3）",meaning:"ため(に)/ように (N3) trung tính, dùng cả văn nói lẫn văn viết; んがため(に)/べく (N1) CHỈ dùng văn viết cứng (xã luận/công văn/diễn văn), nhấn quyết tâm/khẩn thiết mạnh hơn nhiều",priority:"common",explanation:"Trong khi「〜ために・〜ように」(N3) diễn tả mục đích thông thường, mang tính trung tính và dùng linh hoạt trong cả hội thoại thường ngày lẫn văn viết, thì「〜んがため（に）・〜べく」(N1) thuộc phong cách văn viết trang trọng, cổ kính và cứng cáp (thường gặp trong xã luận, công văn, diễn văn). Các mẫu N1 này nhấn mạnh quyết tâm mãnh liệt, sự nỗ lực phi thường hướng tới một mục đích trọng đại, sống còn hoặc khẩn thiết, mang sắc thái hào hùng hơn rất nhiều so với ngữ pháp N3.",examples:[{sentence:"チームを勝利に導かんがため、主将は激痛に耐えて最後まで戦い抜いた。",translation:"Quyết tâm đưa toàn đội đến thắng lợi, người đội trưởng đã nén chịu đau đớn dữ dội để chiến đấu đến cùng."},{sentence:"体力をつけるために、毎朝30分ジョギングをすることにしている。",translation:"Để rèn luyện thể lực, tôi duy trì thói quen chạy bộ 30 phút mỗi sáng."}],dialogue:{title:"Phỏng vấn về cải cách doanh nghiệp",lines:[{speaker:"A",text:"新社長は経営危機を打開すべく、大規模な組織改革を断行したそうですね。",translation:"Nghe nói tân giám đốc đã quyết định tiến hành cải tổ tổ chức quy mô lớn nhằm tìm lối thoát cho khủng hoảng kinh doanh nhỉ."},{speaker:"B",text:"ええ、会社の存続を図るためには、これまでのやり方を抜本的に見直す必要がありました。",translation:"Vâng, để hướng tới sự sống còn của công ty thì việc xem xét lại triệt để cách làm từ trước đến nay là điều tất yếu."},{speaker:"A",text:"企業の未来を切り拓かんがため、まさに背水の陣で挑まれているのですね。",translation:"Nhằm mục đích mở ra tương lai cho doanh nghiệp, ông ấy quả thực đang dốc toàn lực dấn thân vào thử thách."}]},commonMistake:{wrong:"お腹が空いたので、パンを買わんがためにコンビニへ行った。",correct:"お腹が空いたので、パンを買うためにコンビニへ行った。",why:"「〜んがため（に）」chỉ dùng cho mục tiêu lớn mang tính quyết định trong văn viết trang trọng, tuyệt đối không dùng cho những việc sinh hoạt vụn vặt hàng ngày."},note:"「〜べく」thường hướng tới hành động thể hiện trách nhiệm hoặc định hướng lớn mang tính lý trí, trong khi「〜ように」chủ yếu dùng khi mục đích ở vế trước là trạng thái hoặc khả năng không trực tiếp điều khiển được."}],102:[{pattern:"〜ずじまい（だ）",meaning:"Rốt cuộc đã không…(tiếc nuối) — việc định làm nhưng cuối cùng KHÔNG xảy ra",priority:"core",explanation:'Mẫu ngữ pháp này mang ý nghĩa "rốt cuộc đã không thể/chưa kịp làm gì", dùng để diễn tả một việc bản thân đã định làm hoặc có cơ hội thực hiện nhưng cuối cùng lại bỏ lỡ cho đến khi hết thời gian hay hoàn cảnh kết thúc. Cấu trúc kết nối bằng cách chia động từ về thể ない rồi bỏ ない thêm 「ずじまい」（riêng する chuyển thành せずじまい, có thể kết hợp với thể khả năng hoặc bị động）. Mẫu câu luôn hướng về một kết cục trong quá khứ và mang đậm sắc thái tiếc nuối, hối tiếc của người nói.',examples:[{sentence:"去年買った参考書は、忙しさを理由に一度も開かずじまいで本棚に眠っている。",translation:"Cuốn sách tham khảo mua từ năm ngoái, lấy lý do bận rộn nên rốt cuộc tôi vẫn chưa hề mở ra lần nào mà cứ nằm yên trên giá sách."},{sentence:"せっかく大阪まで出張に行ったのに、仕事に追われて名物のたこ焼きを食べずじまいで帰ってきた。",translation:"Cất công đi công tác tận Osaka vậy mà bị công việc cuốn đi nên rốt cuộc tôi đã trở về mà chưa kịp ăn món takoyaki nổi tiếng."}],dialogue:{title:"Chuyến đi Kyoto",lines:[{speaker:"A",text:"田中さん、先週の京都旅行はどうでしたか。行きたがっていた金閣寺は見られましたか。",translation:"Anh Tanaka, chuyến du lịch Kyoto tuần trước thế nào rồi? Anh đã xem được chùa Kinkaku-ji mà anh muốn đi chưa?"},{speaker:"B",text:"いや、急な大雨でスケジュールが狂ってしまって、結局見学できずじまいだったんだよ。",translation:"Chưa, cơn mưa lớn bất ngờ làm đảo lộn lịch trình nên rốt cuộc tôi vẫn chưa thể tham quan được."},{speaker:"A",text:"それは残念でしたね。ぜひ次回リベンジしてください。",translation:"Tiếc quá nhỉ. Lần tới anh nhất định phải đi bù nhé."}]},commonMistake:{wrong:"明日の会議では、自分の意見を言わずじまいにするつもりだ。",correct:"明日の会議では、自分の意見を言わないでおくつもりだ。",why:"「〜ずじまい」chỉ dùng cho kết cục đã kết thúc trong quá khứ kèm theo sự tiếc nuối vì bỏ lỡ cơ hội, không dùng để biểu thị ý định hay kế hoạch phủ định trong tương lai."},note:"Khác với 「〜ないまま」 chỉ trạng thái chưa làm gì rồi tiếp tục thực hiện hành động khác, 「〜ずじまい」 nhấn mạnh cơ hội hoặc khoảng thời gian đã hoàn toàn khép lại mà dự định vẫn chưa thành."},{pattern:"〜に至[いた]る／に至[いた]った",meaning:"Đi đến mức/kết cục là… — kết quả cuối cùng ĐÃ XẢY RA sau một quá trình",priority:"common",explanation:'Mẫu ngữ pháp này diễn tả ý nghĩa "sau một quá trình dài hoặc trải qua nhiều diễn biến, sự việc cuối cùng đã đi đến một kết cục, giai đoạn hay mức độ nhất định". Cấu trúc thường kết hợp với danh từ chỉ kết quả/trạng thái quan trọng (như 合意, 辞任, 解決) hoặc động từ thể từ điển (Vる) chỉ hành vi mang tính bước ngoặt. Đây là cách diễn đạt trang trọng, mang tính văn viết cao, thường xuất hiện trong báo chí, tin tức thời sự, báo cáo kinh doanh hoặc các bài diễn văn.',examples:[{sentence:"数か月に及ぶ労使協議の末、ようやく双方が基本合意に至った。",translation:"Sau nhiều tháng đàm phán giữa công đoàn và ban quản lý, cuối cùng đôi bên đã đi đến một thỏa thuận cơ bản."},{sentence:"長年勤めた会社であったが、経営陣の不正を見過ごせず、自ら内部告発するに至った。",translation:"Dù là công ty đã gắn bó nhiều năm, nhưng không thể làm ngơ trước sai phạm của ban lãnh đạo, tôi đã đi đến quyết định tự mình tố giác nội bộ."}],dialogue:{title:"Tranh chấp hợp đồng đối tác",lines:[{speaker:"A",text:"相手企業との損害賠償をめぐる交渉は、結局どのような結論に至ったのですか。",translation:"Cuộc đàm phán về bồi thường thiệt hại với công ty đối tác rốt cuộc đã đi đến kết luận như thế nào rồi?"},{speaker:"B",text:"何度も話し合いを重ねましたが妥協点が見いだせず、残念ながら裁判を起こすに至りました。",translation:"Chúng tôi đã thương lượng nhiều lần nhưng không tìm được tiếng nói chung, đáng tiếc là sự việc đã đi đến mức phải khởi kiện ra tòa."},{speaker:"A",text:"そうですか。泥沼化を避けるためにも、弁護士と早急に対策を練る必要がありますね。",translation:"Vậy sao. Để tránh tình trạng lún sâu vào bế tắc kéo dài, chúng ta cần nhanh chóng thảo luận phương án xử lý với luật sư thôi."}]},commonMistake:{wrong:"苦渋の決断の末、海外事業から撤退したに至った。",correct:"苦渋の決断の末、海外事業から撤退するに至った。",why:"Động từ kết nối trực tiếp trước 「〜に至る／至った」 bắt buộc phải ở thể từ điển (Vる), không dùng thể quá khứ (Vた) dù kết cục đó đã hoàn tất trong quá khứ."},note:"Cần tránh nhầm lẫn mẫu này với 「〜に至っては」 (nhấn mạnh ví dụ/trường hợp cực đoan mang nghĩa 'ngay cả/đến như...') hoặc 「〜に至るまで」 (chỉ phạm vi 'cho đến tận cả...')."},{pattern:"（度重[たびかさ]なる／相次[あいつ]ぐ／〜の末[すえ]／〜を経[へ]て）〜に至[いた]る",meaning:"に至る LUÔN cần một quá trình/chuỗi sự kiện phía trước, KHÔNG dùng cho một sự việc đơn lẻ, đột ngột",priority:"common",explanation:"Mẫu 「〜に至る」 dùng để diễn tả việc sau khi trải qua một quá trình dài, nhiều biến cố hoặc chuỗi sự kiện dồn dập thì cuối cùng đã đi đến một kết cục, tình trạng hay quyết định nào đó. Mẫu câu này bắt buộc phải có sự xuất hiện của quá trình tích lũy phía trước, thường kết hợp chặt chẽ với các từ như 「度重なる」(chồng chất), 「相次ぐ」(liên tiếp), 「〜の末」(sau một hồi), 「〜を経て」(trải qua). Mẫu mang sắc thái văn viết rất trang trọng, thường dùng trong báo chí, báo cáo và tuyệt đối không dùng cho những sự việc diễn ra đột ngột, đơn lẻ.",examples:[{sentence:"度重なる資金難と幹部の相次ぐ辞任を経て、創業50年の老舗メーカーがついに倒産に至った。",translation:"Trải qua khó khăn tài chính chồng chất và việc các cán bộ chủ chốt liên tiếp từ chức, nhà sản xuất lâu đời 50 năm tuổi cuối cùng đã đi đến bờ vực phá sản."},{sentence:"10年以上に及ぶ長年の研究と度重なる実験の末、ようやく新薬の開発成功に至った。",translation:"Sau hơn 10 năm nghiên cứu bền bỉ và vô số lần thử nghiệm lặp đi lặp lại, cuối cùng chúng tôi đã đi đến việc phát triển thành công loại thuốc mới."}],dialogue:{title:"Quyết định hoãn dự án",lines:[{speaker:"A",text:"新規事業の立ち上げ計画、結局見送りになったって本当ですか？",translation:"Kế hoạch triển khai dự án kinh doanh mới rốt cuộc đã bị hoãn lại thật sao anh?"},{speaker:"B",text:"ええ、相次ぐトラブルと度重なる予算削減の末、事業の継続を断念するに至りました。",translation:"Ừ, sau hàng loạt rắc rối liên tiếp và nhiều lần bị cắt giảm ngân sách, công ty đã đi đến quyết định từ bỏ việc tiếp tục dự án."},{speaker:"A",text:"チーム全員で準備を進めてきただけに、本当に残念ですね。",translation:"Cả đội đã cùng nhau chuẩn bị kỹ lưỡng suốt thời gian qua, nghe vậy thật là tiếc quá."}]},commonMistake:{wrong:"今朝は突然の事故により、イベントの中止に至った。",correct:"今朝は突然の事故により、イベントが中止になった。",why:"「〜に至る」 bắt buộc phải có một quá trình hoặc chuỗi biến cố tích lũy diễn ra trước đó, không được dùng cho sự việc đơn lẻ xảy ra đột ngột, mang tính tức thời."},note:"Hãy luôn ghi nhớ các cụm kết hợp quen thuộc như 「〜の末に至る」「〜を経て...に至る」「度重なる...に至る」 vì nếu thiếu vế chỉ quá trình thì việc dùng 「〜に至る」 sẽ trở nên gượng gạo, không tự nhiên."},{pattern:"使[つか]い分[わ]け：ずじまい ≠ に至[いた]る ≠ 始末[しまつ]だ（N2）",meaning:"Phân biệt: ずじまい (ĐÃ KHÔNG xảy ra, luôn tiếc) ≠ に至る (ĐÃ xảy ra qua quá trình, trung tính/khách quan) ≠ 始末だ (N2, kết cục xấu, giọng than thở/chê trách)",priority:"common",explanation:"「〜ずじまい」diễn tả một sự việc dù có ý định nhưng rốt cuộc đã KHÔNG xảy ra cho đến khi thời điểm/cơ hội kết thúc, luôn đi kèm cảm xúc tiếc nuối. Ngược lại, 「〜に至る」diễn tả sự việc ĐÃ xảy ra hoặc đi đến một kết cục sau một tiến trình dài, mang tính khách quan, trang trọng (dùng được cho cả kết quả tích cực lẫn tiêu cực). Trong khi đó, 「〜始末だ」(N2) nhấn mạnh một kết cục xấu, tồi tệ phát sinh từ chuỗi hành vi tiêu cực trước đó với sắc thái than thở hoặc phê phán.",examples:[{sentence:"忙しくて、日本にいる間に一度も富士山に登れずじまいで帰国してしまった。",translation:"Vì bận rộn nên trong suốt thời gian ở Nhật, tôi đã về nước mà chưa từng một lần leo được núi Phú Sĩ."},{sentence:"両国は何ヶ月にも及ぶ協議を重ね、ようやく平和条約の締結に至った。",translation:"Hai nước đã trải qua nhiều tháng đàm phán và cuối cùng đã đi đến việc ký kết hiệp ước hòa bình."}],dialogue:{title:"Dự án kinh doanh mới",lines:[{speaker:"A",text:"先日提案された新規事業のプロジェクト、その後どうなりましたか。",translation:"Dự án kinh doanh mới đề xuất hôm trước, sau đó thế nào rồi?"},{speaker:"B",text:"予算の都合がつかず、結局一度も試作品を作れずじまいで中止になりました。",translation:"Không thu xếp được ngân sách nên rốt cuộc đã bị hủy bỏ mà chưa kịp làm mẫu thử lấy một lần."},{speaker:"A",text:"そうですか。何ヶ月も準備してきたのに、実現に至らなかったのは本当に残念ですね。",translation:"Vậy sao. Đã chuẩn bị bao nhiêu tháng trời mà lại không đi đến được bước hiện thực hóa, tiếc thật đấy."}]},commonMistake:{wrong:"ずっと楽しみにしていたコンサートだったが、急な仕事で行くに至らなかった。",correct:"ずっと楽しみにしていたコンサートだったが、急な仕事で行けずじまいだった。",why:"Khi muốn diễn tả việc bản thân dự định làm nhưng rốt cuộc không thực hiện được kèm sự tiếc nuối trong đời sống hàng ngày, phải dùng 「〜ずじまい」 chứ không dùng 「〜に至る」."},note:"「〜ずじまい」chỉ việc KHÔNG xảy ra (thường đi với thể khả năng phủ định như 買えず、会えず), còn 「〜に至る」và 「〜始末だ」chỉ việc ĐÃ xảy ra (trong đó 「〜始末だ」chỉ dùng cho kết cục xấu và mang giọng điệu bất bình/than phiền)."}],103:[{pattern:"〜と言[い]えども",meaning:"Dù là ... đi nữa (nhượng bộ trang trọng — vế sau PHỦ ĐỊNH kỳ vọng gắn liền với chủ thể)",priority:"core",explanation:'Mẫu 「〜と言えども」 mang ý nghĩa "dù là... đi chăng nữa", dùng để biểu đạt sự nhượng bộ mang tính trang trọng và có sắc thái văn viết cao. Cấu trúc này thường đi sau một chủ thể hoặc điều kiện tưởng chừng có ưu thế tuyệt đối, có uy tín lớn hay đặc quyền, nhưng vế sau lại phủ định điều người ta kỳ vọng hoặc khẳng định không có ngoại lệ. Vế sau thường kết hợp với các cách diễn đạt mang tính nghĩa vụ, cấm chỉ hoặc giới hạn như 〜てはならない、〜わけにはいかない、〜できない.',examples:[{sentence:"百戦錬磨のベテラン医師と言えども、このような前例のない難手術を一人で成功させることは極めて困難だ。",translation:"Dù là một bác sĩ kỳ cựu dày dặn kinh nghiệm đi chăng nữa, việc một mình thực hiện thành công ca phẫu thuật phức tạp chưa từng có tiền lệ như thế này vẫn vô cùng khó khăn."},{sentence:"一国の首相と言えども、国民の知る権利を不当に侵害し、重要機密を隠蔽することは決して許されない。",translation:"Dù là thủ tướng của một quốc gia đi nữa thì cũng tuyệt đối không được phép xâm phạm trái phép quyền được biết của người dân và che giấu các bí mật quan trọng."}],dialogue:{title:"Quy định an toàn",lines:[{speaker:"A",text:"部長、いくら納期が迫っていると言えども、安全確認の手順を省くわけにはいきません。",translation:"Trưởng phòng, dù thời hạn giao hàng có đang cận kề đi chăng nữa thì chúng ta cũng không thể bỏ qua quy trình kiểm tra an toàn được."},{speaker:"B",text:"分かっているが、今回のクライアントは特に納期に厳しいから焦ってしまってね。",translation:"Tôi biết chứ, nhưng khách hàng lần này đặc biệt khắt khe về thời hạn nên tôi mới sốt ruột quá."},{speaker:"A",text:"事故が起きてからでは取り返しがつきませんから、マニュアル通りに進めましょう。",translation:"Một khi sự cố xảy ra thì không thể cứu vãn được nữa, nên chúng ta hãy cứ tiến hành đúng theo sách hướng dẫn ạ."}]},commonMistake:{wrong:"日曜日だと言えども、今日は試験勉強をしなければならない。",correct:"日曜日だと言っても、今日は試験勉強をしなければならない。",why:"「〜と言えども」 mang sắc thái văn viết trang trọng, mang tính triết lý hoặc nguyên tắc khắt khe, không dùng cho các tình huống sinh hoạt thường nhật đơn giản."},note:"So với 「〜といっても」 dùng nhiều trong hội thoại thường ngày để bổ sung/hạn chế thực tế, 「〜と言えども」 là văn phong cứng và vế sau thường nhấn mạnh tính tuyệt đối không có ngoại lệ bằng các cấu trúc như 「〜許されない」「〜わけにはいかない」."},{pattern:"〜であれ",meaning:"Dù là gì/ai đi nữa (liệt kê khách quan mọi khả năng — thường đi với 何・誰・どう・いつ)",priority:"common",explanation:"Mẫu 「〜であれ」 mang ý nghĩa 「dù là... hay bất kể là... đi nữa」, dùng để đưa ra giả định mang tính bao quát mọi trường hợp nhưng kết luận hoặc quy tắc ở vế sau vẫn không thay đổi. Cấu trúc này thường đi kèm với Danh từ, Tính từ đuôi な hoặc các từ để hỏi (何、誰、どこ、いかに...). Đây là lối diễn đạt trang trọng, thường xuất hiện trong văn viết, nghị luận hoặc những phát biểu mang tính nguyên tắc, đạo đức.",examples:[{sentence:"たとえ未成年であれ、社会的なルールを守る義務がある。",translation:"Dù là trẻ vị thành niên đi nữa thì vẫn có nghĩa vụ phải tuân thủ các quy tắc xã hội."},{sentence:"理由が何であれ、無断で試合を欠席することは認められない。",translation:"Dù lý do là gì đi chăng nữa, việc vắng mặt trong trận đấu mà không xin phép là không thể chấp nhận."}],dialogue:{title:"Báo cáo công việc",lines:[{speaker:"A",text:"どんなに小さなミスであれ、見過ごさずに報告してください。",translation:"Dù là lỗi nhỏ đến thế nào đi nữa, cậu cũng đừng bỏ qua mà hãy báo cáo nhé."},{speaker:"B",text:"わかりました。すぐに修正してチーム全体に共有します。",translation:"Tôi hiểu rồi. Tôi sẽ sửa ngay và chia sẻ cho toàn đội."},{speaker:"A",text:"頼みますよ。初期段階での対応が一番重要ですから。",translation:"Nhờ cậu nhé. Vì việc xử lý ở giai đoạn đầu là quan trọng nhất đấy."}]},commonMistake:{wrong:"いかに忙しいであれ、毎日の睡眠時間は確保すべきだ。",correct:"いかに多忙であれ、毎日の睡眠時間は確保すべきだ。",why:"Mẫu 「〜であれ」 chỉ đi với Danh từ hoặc Tính từ đuôi な, không kết hợp trực tiếp với Tính từ đuôi い (cần chuyển sang Danh từ tương đương hoặc dùng dạng 〜かろうと)."},note:"Khi muốn nhấn mạnh tính toàn diện của hai khả năng tương phản hoặc song song, ta có thể dùng dạng lặp lại 「AであれBであれ」 (dù là A hay là B)."},{pattern:"〜であろうと",meaning:"Dù có là ... đi chăng nữa (giả định cực đoan, sắc thái quyết tâm mạnh — văn diễn thuyết/xã luận)",priority:"common",explanation:'Mẫu ngữ pháp「〜であろうと」mang ý nghĩa "dù có là... đi chăng nữa", dùng để đưa ra một giả định mang tính cực đoan nhằm khẳng định vế sau không bị ảnh hưởng. Cấu trúc này thường kết hợp với Danh từ hoặc Tính từ đuôi な, hay đi kèm các từ nhấn mạnh như「たとえ」「いかなる」「どれほど」và vế sau thể hiện ý chí, quyết tâm mạnh mẽ hoặc quy tắc tất yếu. Đây là cách diễn đạt mang sắc thái rất trang trọng, thường dùng trong văn viết xã luận, tuyên ngôn hoặc diễn thuyết trước công chúng.',examples:[{sentence:"たとえ一国の首相であろうと、法を犯したならば厳正に裁かれなければならない。",translation:"Dù có là thủ tướng của một quốc gia đi chăng nữa, nếu vi phạm pháp luật thì đều phải bị xét xử nghiêm minh."},{sentence:"いかに困難な状況であろうと、我々はお客様との信頼関係を決して裏切らない。",translation:"Dù có là tình huống khó khăn đến mức nào đi chăng nữa, chúng tôi tuyệt đối không bao giờ phản bội niềm tin của khách hàng."}],dialogue:{title:"Tinh thần trách nhiệm công việc",lines:[{speaker:"A",text:"部長、今回の遅延は新入社員の確認ミスが原因ですが、納期を少し延ばせませんか。",translation:"Thưa trưởng phòng, sự chậm trễ lần này là do lỗi kiểm tra của nhân viên mới, liệu chúng ta có thể lùi hạn giao hàng một chút không ạ?"},{speaker:"B",text:"たとえ新人であろうと、プロとして案件を引き受けた以上は納期を守るのが鉄則だ。",translation:"Dù có là nhân viên mới đi chăng nữa, một khi đã nhận dự án với tư cách người làm việc chuyên nghiệp thì đúng hạn là nguyên tắc bất di bất dịch."},{speaker:"A",text:"おっしゃる通りです。チーム全員ですぐに対策を立てて間に合わせます。",translation:"Đúng như trưởng phòng nói ạ. Tôi sẽ cùng toàn đội lập tức lên phương án xử lý để kịp tiến độ."}]},commonMistake:{wrong:"どれほど忙しいであろうと、毎日の健康管理は怠ってはいけない。",correct:"どれほど忙しかろうと、毎日の健康管理は怠ってはいけない。",why:"Mẫu「〜であろうと」chỉ kết hợp trực tiếp với Danh từ và Tính từ đuôi な, còn với Tính từ đuôi い phải biến đổi sang dạng「〜かろうと」hoặc dùng「〜くても」."},note:"Mẫu này mang tính văn phong trang trọng, tôn nghiêm hơn nhiều so với「〜ても」và thường không dùng cho các hội thoại sinh hoạt thường ngày trừ khi muốn nhấn mạnh thái độ cực kỳ nghiêm túc."},{pattern:"と言[い]えども ≠ であれ／であろうと ≠ にしても・にせよ（N2）",meaning:"Phân biệt: と言えども (phủ định kỳ vọng ở MỘT chủ thể cụ thể) ≠ であれ／であろうと (liệt kê nghi vấn từ, であろうと cực đoan/quyết tâm hơn) ≠ にしても・にせよ (N2, nhượng bộ trung tính, không bắt buộc phủ định kỳ vọng)",priority:"common",explanation:"「と言えども」dùng để nhượng bộ một chủ thể cụ thể, mà vế sau đi kèm việc phủ định kỳ vọng thông thường về chủ thể đó (dù có tư cách X nhưng thực tế lại không/chưa hẳn Y). Trong khi đó,「であれ／であろうと」thường kết hợp với từ nghi vấn hoặc liệt kê nhằm nhấn mạnh tính toàn diện không phân biệt đối tượng nào (trong đó「であろうと」thể hiện sắc thái quyết tâm, cực đoan mạnh hơn). Khác với hai mẫu trên,「にしても・にせよ」(N2) chỉ là nhượng bộ trung tính trong văn cảnh thường nhật và không bắt buộc phủ định kỳ vọng.",examples:[{sentence:"親と言えども、子どものプライバシーを勝手に覗き見ることは許されない。",translation:"Dù là cha mẹ đi chăng nữa, việc tự tiện xâm phạm sự riêng tư của con cái cũng không được phép."},{sentence:"いかなる理由であろうと、契約を一方的に破棄することは認められない。",translation:"Dù với bất kỳ lý do nào đi chăng nữa, việc đơn phương hủy bỏ hợp đồng cũng không được chấp nhận."}],dialogue:{title:"Quy định công ty",lines:[{speaker:"A",text:"佐藤さん、役員の方々が提出期限の延長を求めていますが、どうしますか。",translation:"Anh Sato, các vị trong ban giám đốc đang yêu cầu gia hạn hạn nộp, tính sao đây ạ?"},{speaker:"B",text:"役員と言えども、社内の公式ルールを勝手に破ることは認められませんよ。",translation:"Dù là giám đốc đi nữa thì việc tự ý phá vỡ quy định chính thức của công ty cũng không được chấp nhận đâu."},{speaker:"A",text:"分かりました。例外なく全員に期日通りの提出をお願いしてまいります。",translation:"Tôi hiểu rồi. Tôi sẽ thông báo yêu cầu tất cả nộp đúng hạn mà không có ngoại lệ."}]},commonMistake:{wrong:"誰と言えども、この立ち入り禁止区域に入ることはできません。",correct:"誰であれ、この立ち入り禁止区域に入ることはできません。",why:"「と言えども」chỉ đi với danh từ chỉ đối tượng/chủ thể cụ thể mang tính đại diện chứ không kết hợp trực tiếp với từ nghi vấn (như 誰, 何); trường hợp muốn diễn đạt 'bất kể là ai' bắt buộc phải dùng「であれ／であろうと」."},note:"「と言えども」thường gắn liền với các danh từ có vị thế hoặc kỳ vọng cao (chuyên gia, người lớn, người giàu...) nhưng kết quả vế sau lại đi ngược lại kỳ vọng đó."}],104:[{pattern:"〜ものを（〜ばよかったものを）",meaning:"Giá mà đã… thì đâu đến nỗi — tiếc nuối, trách móc mạnh về việc đã không làm",priority:"core",explanation:"Mẫu 「〜ものを」 dùng để diễn tả sự hối tiếc sâu sắc của bản thân hoặc sự bất mãn, trách móc người khác vì đã không làm một việc lẽ ra nên làm. Vế trước thường kết hợp với thể giả định quá khứ (〜ば / 〜たらよかった) nêu phương án đúng đắn, vế sau diễn tả kết quả thực tế đáng tiếc hoặc bất lợi đã xảy ra. Cấu trúc này mang sắc thái cảm xúc mạnh mẽ và trang trọng hơn so với 「〜のに」.",examples:[{sentence:"体調が悪いなら無理せず休めばよかったものを、無理して出勤したせいで症状が悪化してしまった。",translation:"Nếu thấy không khỏe thì giá mà cứ nghỉ ngơi đừng ráng thì đâu đến nỗi, đằng này lại cố đi làm nên bệnh tình càng nặng thêm."},{sentence:"セールまであと数日待てば安く買えたものを、焦って定価で買ってしまってひどく後悔している。",translation:"Giá mà kiên nhẫn đợi thêm vài ngày tới đợt giảm giá thì mua được rẻ rồi, vậy mà lại vội vàng mua đúng giá gốc nên giờ thấy vô cùng hối hận."}],dialogue:{title:"Ướt sũng vì quên mang ô",lines:[{speaker:"A",text:"天気予報で雨が降るって言ってたんだから、折りたたみ傘を持っていけばよかったものを。",translation:"Dự báo thời tiết đã báo trời mưa rồi, giá mà cậu mang theo ô gấp thì đâu đến nỗi ướt thế này."},{speaker:"B",text:"朝はすっかり晴れていたから大丈夫だと思ったんだよ。まさかこんな土砂降りになるとは思わなくて…",translation:"Sáng thấy trời nắng ráo nên tớ nghĩ chắc không sao. Ai ngờ lại mưa như trút nước thế này..."},{speaker:"A",text:"ほら、風邪を引かないうちに早くタオルで拭いて、服を着替えなさい。",translation:"Thôi, mau lấy khăn lau khô người rồi thay đồ đi kẻo bị cảm lạnh đấy."}]},commonMistake:{wrong:"事前に連絡してくれれば駅まで迎えに行ったものを、来てくれて本当にありがとう。",correct:"事前に連絡してくれれば駅まで迎えに行ったものを、連絡がなかったから一人で歩く羽目になったじゃないか。",why:"Mẫu 「〜ものを」 bắt buộc phải đi với kết quả xấu hoặc sự bất mãn, tuyệt đối không dùng khi vế sau là lời cảm ơn hoặc kết quả tích cực."},note:"Trong giao tiếp thân mật hàng ngày, vế sau thường được lược bỏ và kết thúc câu lửng ở 「〜ものを…」 để nhấn mạnh tiếng thở dài tiếc nuối hoặc sự trách móc ngầm."},{pattern:"〜ところを（中断[ちゅうだん]・恐縮[きょうしゅく]の意[い]）",meaning:"Giữa lúc đang… mà (bị xen ngang, hoặc lịch sự khi cảm ơn/xin lỗi vì đã làm phiền đúng lúc đó)",priority:"common",explanation:"Mẫu「〜ところを」được dùng để diễn tả ý nghĩa 'giữa lúc đang trong trạng thái hoặc tình huống nào đó thì có việc khác chen ngang hoặc làm phiền'. Ngữ pháp này xuất hiện chủ yếu trong các câu giao tiếp trang trọng, thư từ thương mại nhằm bày tỏ lời xin lỗi hoặc cảm ơn vì đã làm phiền người khác đúng vào lúc họ bận rộn hoặc nghỉ ngơi. Vế sau thường đi kèm các lời cảm kích, áy náy (恐縮) hoặc các hành động làm gián đoạn đối phương.",examples:[{sentence:"お休みのところを急にお呼び立てしてしまい、大変申し訳ございません。",translation:"Rất xin lỗi vì đã đường đột gọi anh/chị đến giữa lúc đang trong ngày nghỉ."},{sentence:"厳しい寒さのところを、遠方よりわざわざ足をお運びいただき心より感謝申し上げます。",translation:"Tôi xin chân thành cảm ơn quý vị đã không quản ngại đường xa đến đây giữa lúc thời tiết giá rét như thế này."}],dialogue:{title:"Trao đổi công việc gấp",lines:[{speaker:"A",text:"課長、ご休憩中のところを恐れ入りますが、至急確認していただきたい書類がございます。",translation:"Thưa trưởng phòng, xin thứ lỗi vì làm phiền giữa lúc ngài đang nghỉ ngơi, nhưng có tài liệu khẩn này cần ngài xem qua ạ."},{speaker:"B",text:"ああ、いいよ。どんな内容の書類だい？",translation:"À được chứ. Tài liệu về nội dung gì thế?"},{speaker:"A",text:"明日のプレゼン資料の最終版です。どうぞよろしくお願いいたします。",translation:"Dạ là bản tài liệu thuyết trình cuối cùng cho ngày mai ạ. Nhờ trưởng phòng xem giúp em."}]},commonMistake:{wrong:"お忙しいところにわざわざお越しいただき、誠にありがとうございます。",correct:"お忙しいところをわざわざお越しいただき、誠にありがとうございます。",why:"Trong các câu chào hỏi trang trọng bày tỏ sự áy náy hoặc cảm ơn khi làm phiền đối phương, bắt buộc phải dùng trợ từ 「ところを」 chứ không dùng 「ところに」."},note:"Cần phân biệt với 「〜ところに／へ」 vốn chỉ thuần túy diễn tả một sự việc bất ngờ xảy đến đúng thời điểm đó mà không mang sắc thái áy náy, xin lỗi hay cảm ơn."},{pattern:"〜ところを（危機[きき]一髪[いっぱつ]の意[い]）",meaning:"Ngay lúc sắp/đang… (nguy hiểm, phạm pháp) thì được cứu/bị bắt/bị phát hiện",priority:"common",explanation:"Mẫu câu này diễn tả tình huống một sự can thiệp từ bên ngoài hoặc sự việc bất ngờ xảy ra đúng vào khoảnh khắc then chốt, nguy kịch (ngàn cân treo sợi tóc) hoặc khi hành vi phạm pháp, lén lút đang diễn ra. Cấu trúc thường kết hợp「V-ている / V-そうになっている + ところを」với vế sau là các động từ thể bị động như được cứu (助けられる), bị bắt (逮捕される), bị phát hiện (発見される). Mẫu câu mang sắc thái nhấn mạnh khoảnh khắc quyết định làm thay đổi cục diện nguy hiểm hoặc chấm dứt hành vi sai trái.",examples:[{sentence:"川でおぼれそうになっていたところを、通りかかった警察官に助けられた。",translation:"Ngay lúc tôi sắp chết đuối dưới sông thì may mắn được một viên cảnh sát đi ngang qua cứu thoát."},{sentence:"犯人は盗んだバイクで逃走しようとしているところを、駆けつけた警察官に取り押さえられた。",translation:"Tên tội phạm ngay lúc đang định tẩu thoát bằng chiếc xe máy trộm được thì đã bị cảnh sát ập đến khống chế bắt giữ."}],dialogue:{title:"Thoát nạn trong gang tấc",lines:[{speaker:"A",text:"先週、山で道に迷って遭難しかけたらしいね。大丈夫だった？",translation:"Nghe nói tuần trước cậu bị lạc suýt gặp nạn trên núi à? Cậu có sao không?"},{speaker:"B",text:"ええ、吹雪で倒れそうになっていたところを、運よく救助隊に発見されて助かったんだ。",translation:"Ừ, ngay lúc tớ sắp ngã quỵ vì bão tuyết thì may mắn được đội cứu hộ phát hiện và cứu sống."},{speaker:"A",text:"本当に無事でよかったよ。まさに九死に一生を得たね。",translation:"Thật may là cậu bình an vô sự. Đúng là thoát chết trong gang tấc nhỉ."}]},commonMistake:{wrong:"空き巣が家に侵入しているところを、私は大声で叫んだ。",correct:"空き巣が家に侵入しているところを、巡回中の警察官に取り押さえられた。",why:"Vế sau của mẫu「〜ところを」ở sắc thái nguy cấp/bắt quả tang bắt buộc phải là hành động can thiệp trực tiếp lên đối tượng (thường dùng động từ thể bị động như 取り押さえられる, 逮捕される, 助けられる), chứ không dùng hành động chủ động đơn thuần của người chứng kiến."},note:"Khác với「〜ところに/へ」chỉ đơn thuần diễn tả ai đó hoặc sự việc nào đó xuất hiện chen ngang (vế sau là tự động từ hoặc hành động thông thường), mẫu「〜ところを」này nhấn mạnh đối tượng được giải cứu hoặc bị bắt giữ trong gang tấc nên vế sau hầu như luôn dùng thể bị động."},{pattern:"使[つか]い分[わ]け：ものを ≠ ところを ≠ のに",meaning:"Phân biệt: ものを (kết luận trách móc/tiếc nuối, đứng cuối câu) ≠ ところを (trung tính, cần động từ xen vào/受身 theo sau) ≠ のに (thực tế trái kỳ vọng, sắc thái nhẹ hơn ものを)",priority:"common",explanation:'「ものを」được dùng để nhấn mạnh sự tiếc nuối sâu sắc hoặc trách móc rằng nếu làm khác đi thì kết quả đã tốt hơn, mang nặng cảm xúc chủ quan và có thể đứng ở cuối câu. Trái lại,「ところを」mang tính khách quan, diễn tả thời điểm "đúng lúc đang... thì có sự việc chen ngang/bị bắt gặp", thường đi với động từ bị động hoặc lời cảm ơn, xin lỗi lịch sự chứ không mang sắc thái oán trách. Trong khi đó,「のに」chỉ đơn thuần diễn đạt sự việc thực tế trái ngược kỳ vọng với cảm xúc ngạc nhiên, tiếc nuối nhẹ nhàng và phạm vi sử dụng rộng rãi nhất.',examples:[{sentence:"一言相談してくれれば力になれたものを、どうして一人で抱え込んでしまったのですか。",translation:"Giá mà cậu chịu bàn với tôi một lời thì tôi đã có thể giúp đỡ rồi, vậy mà sao lại tự mình ôm đồm mọi chuyện thế?"},{sentence:"犯人は変装して空港から国外へ逃亡しようとしたところを、警戒中の警察官に取り押さえられた。",translation:"Tên tội phạm đang giữa lúc cải trang định bỏ trốn ra nước ngoài từ sân bay thì bị cảnh sát đang cảnh giới khống chế bắt giữ."}],dialogue:{title:"Hối hận sau kỳ thi",lines:[{speaker:"A",text:"もう少し早く試験対策を始めておけば合格できたものを、完全に油断していたよ。",translation:"Giá mà bắt đầu ôn thi sớm hơn một chút thì đã có thể đỗ rồi, vậy mà mình lại hoàn toàn chủ quan."},{speaker:"B",text:"落ち込んでいても仕方がないから、次に向けて仕事の合間に少しずつ勉強しよう。",translation:"Cậu có ủ rũ thì cũng chẳng thay đổi được gì, hãy tranh thủ thời gian giữa giờ làm để học dần cho kỳ thi tới đi."},{speaker:"A",text:"うん、今度こそ後悔しないように今日から計画を立て直すよ。",translation:"Ừ, để lần tới không phải hối tiếc nữa, ngay từ hôm nay mình sẽ lập lại kế hoạch ôn tập."}]},commonMistake:{wrong:"万引き犯は店から逃げようとしたものを、警備員に呼び止められた。",correct:"万引き犯は店から逃げようとしたところを、警備員に呼び止められた。",why:"「ものを」dùng để thể hiện sự bất mãn, tiếc nuối chủ quan nên vế sau không thể đi với hành động bị bắt gặp, chặn lại (thể bị động) như「ところを」."},note:"「ところを」thường xuyên xuất hiện trong các câu chào hỏi, nhờ vả trang trọng (như お忙しいところを...), trong khi「ものを」tuyệt đối không dùng cho bối cảnh lịch sự này."}],105:[{pattern:"〜（よ）うが",meaning:"Dù có… đi nữa, dù ra sao cũng… (nhượng bộ cực đoan, văn viết trang trọng)",priority:"core",explanation:'Mẫu câu này dùng để biểu thị sự nhượng bộ mang tính giả định cực đoan, mang ý nghĩa "dù cho có... đi chăng nữa thì sự việc ở vế sau vẫn không thay đổi hoặc không bị ảnh hưởng". Cấu trúc thường kết hợp với thể ý chí của động từ/tính từ và đi kèm với các từ nghi vấn như「たとえ」「どんなに」「誰が」「何を」để tăng tính nhấn mạnh. Đây là cách diễn đạt trang trọng, thiên về văn viết, thường dùng để thể hiện quyết tâm sắt đá, thái độ dứt khoát hoặc một chân lý hiển nhiên.',examples:[{sentence:"周囲からどんなに反対されようが、私は自分が信じた道を進むつもりだ。",translation:"Dù có bị mọi người xung quanh phản đối thế nào đi nữa, tôi vẫn dự định sẽ bước tiếp trên con đường mình tin tưởng."},{sentence:"たとえどれほど多忙であろうが、提出期限を守るのは社会人としての最低限のマナーだ。",translation:"Dù có bận rộn đến mức nào đi chăng nữa, việc tuân thủ thời hạn nộp vẫn là quy tắc ứng xử tối thiểu của người đi làm."}],dialogue:{title:"Quyết định khởi nghiệp",lines:[{speaker:"A",text:"今の安定した仕事を辞めて起業するなんて、リスクが大きすぎるんじゃない？",translation:"Bỏ công việc ổn định hiện tại để khởi nghiệp chẳng phải rủi ro quá lớn sao?"},{speaker:"B",text:"ええ、周りにどれほど反対されようが、自分の可能性を試してみたいんです。",translation:"Vâng, dù cho có bị mọi người xung quanh phản đối thế nào đi nữa, em vẫn muốn thử thách tiềm năng của bản thân."},{speaker:"A",text:"そこまで強い覚悟があるなら、私も全力で応援するよ。",translation:"Nếu cậu đã có quyết tâm lớn đến mức đó thì tôi cũng sẽ ủng hộ hết mình."}]},commonMistake:{wrong:"どんなに辛いようが、途中で諦めてはいけない。",correct:"どんなに辛かろうが、途中で諦めてはいけない。",why:"Với tính từ đuôi い, dạng thức ý chí đi với 「が」 phải biến đổi thành 「〜かろうが」（辛かろうが）chứ không ghép trực tiếp thành 「〜いようが」."},note:"Mẫu「〜（よ）うが」hoàn toàn đồng nghĩa và có thể thay thế bằng「〜（よ）うと」; ngoài ra cấu trúc còn hay gặp ở dạng lặp lại đối lập「A（よ）うが B（よ）うが」(dù là A hay là B thì...)."},{pattern:"〜（よ）うと",meaning:"Biến thể của うが — cùng nghĩa, thường đi với 何と／どんなに, nhấn lập trường cá nhân",priority:"common",explanation:'Mẫu ngữ pháp 「〜（よ）うと」 mang ý nghĩa "cho dù... / dù có... đi chăng nữa", diễn tả rằng điều kiện ở vế trước hoàn toàn không ảnh hưởng hay làm thay đổi sự việc, nhận định ở vế sau. Đây là biến thể đồng nghĩa với 「〜（よ）うが」, kết hợp với thể ý chí của động từ (意向形) hoặc dạng 「〜かろうと / 〜であろうと」. Mẫu câu này thường đi kèm với các phó từ/từ để hỏi như 「たとえ / どんなに / 何を / 誰が」 và thường dùng để nhấn mạnh lập trường cá nhân, niềm tin hoặc quyết tâm sắt đá của người nói.',examples:[{sentence:"たとえ周囲の人たちに反対されようと、私は自分の信じた道を進むつもりだ。",translation:"Dù cho có bị những người xung quanh phản đối đi chăng nữa, tôi vẫn dự định sẽ bước tiếp trên con đường mà mình tin tưởng."},{sentence:"どんなに困難な状況に陥ろうと、決して最後まで諦めてはいけない。",translation:"Dù có rơi vào hoàn cảnh khó khăn đến mức nào đi chăng nữa, tuyệt đối không được bỏ cuộc cho đến phút cuối cùng."}],dialogue:{title:"Quyết định khởi nghiệp",lines:[{speaker:"A",text:"親に何と言われようと、会社を辞めて起業するという私の決意は変わりません。",translation:"Dù bố mẹ có nói gì đi nữa, quyết định nghỉ việc để khởi nghiệp của tôi cũng sẽ không thay đổi."},{speaker:"B",text:"そこまで覚悟が決まっているなら応援するよ。でも、資金繰りの計画は大丈夫かい？",translation:"Nếu cậu đã hạ quyết tâm đến mức đó thì tôi sẽ ủng hộ. Nhưng kế hoạch xoay vòng vốn đã ổn thỏa chưa?"},{speaker:"A",text:"はい、これからどんな苦労をしようと最後までやり抜くつもりです。",translation:"Vâng, từ giờ trở đi dù có phải vất vả thế nào thì tôi cũng dự định sẽ kiên trì tới cùng."}]},commonMistake:{wrong:"たとえ周りに反対するようと、自分の夢を諦めるわけにはいかない。",correct:"たとえ周りに反対されようと、自分の夢を諦めるわけにはいかない。",why:"Mẫu này bắt buộc phải chia động từ sang thể ý chí (意向形: されよう/しよう), người học hay nhầm lẫn ghép thể từ điển với 「〜ようと」 hoặc nhầm sang cấu trúc 「〜ように」."},note:"So với 「〜ても」 phổ biến trong khẩu ngữ hàng ngày, 「〜（よ）うと」 là văn phong viết/trang trọng hơn hẳn và mang sắc thái nhấn mạnh vào ý chí, lập trường kiên định của người nói."},{pattern:"〜（よ）うが〜まいが",meaning:"Dù có… hay không cũng… (nêu cả hai chiều lựa chọn đối lập, phủ định bằng cả hai)",priority:"common",explanation:'Mẫu câu này dùng để diễn đạt ý nghĩa "dù có làm hay không làm... thì kết quả hoặc hành động ở vế sau vẫn không hề thay đổi". Cấu trúc được hình thành bằng cách lặp lại cùng một động từ ở dạng ý chí kết hợp với dạng phủ định trang trọng まい để đưa ra hai khả năng đối lập nhau. Mẫu thường thể hiện quyết tâm mạnh mẽ của người nói hoặc khẳng định một sự việc mang tính khách quan không phụ thuộc vào điều kiện vế trước, chủ yếu dùng trong văn phong trang trọng, phát biểu hoặc văn viết.',examples:[{sentence:"周りの人に反対されようがされまいが、私は自分の信じる道を進むつもりだ。",translation:"Dù có bị mọi người xung quanh phản đối hay không, tôi vẫn dự định tiến bước trên con đường mình tin tưởng."},{sentence:"雨が降ろうが降るまいが、明日のマラソン大会は予定通り開催されます。",translation:"Dù trời có mưa hay không mưa, giải chạy marathon ngày mai vẫn sẽ được tổ chức theo đúng kế hoạch."}],dialogue:{title:"Quyết định thử thách",lines:[{speaker:"A",text:"今度の新規プロジェクト、参加するかどうかまだ迷っているんですか。",translation:"Dự án mới lần này, cậu vẫn còn đang phân vân có nên tham gia hay không à?"},{speaker:"B",text:"ええ、でも周りがどう評価しようがしまいが、自分の成長のために挑戦しようと決めました。",translation:"Vâng, nhưng dù mọi người xung quanh có đánh giá thế nào đi nữa, tôi đã quyết định sẽ thử sức vì sự phát triển của bản thân."},{speaker:"A",text:"その意気ですね！私も全力で応援しますよ。",translation:"Khí thế đấy! Tôi cũng sẽ ủng hộ cậu hết mình."}]},commonMistake:{wrong:"彼が来ようが来ないが、会議は時間通りに始めます。",correct:"彼が来ようが来るまいが、会議は時間通りに始めます。",why:"Mẫu ngữ pháp này bắt buộc vế phủ định đối lập phải chia với「〜まいが」, không dùng thể phủ định thông thường「〜ないが」."},note:"Cấu trúc này có thể dùng tương đương với「〜（よ）うと〜まいと」, đồng thời cần chú ý dạng chia đặc biệt của động từ nhóm 3: する → しようがしまいが (hoặc するまいが), くる → こようがくるまいが (hoặc こまいが)."},{pattern:"〜（よ）うが/と ≠ 〜ても（N3）≠ 〜たところで（N2）",meaning:"Phân biệt: (よ)うが/と cần cặp đối lập rõ ràng ≠ ても là nhượng bộ giả định một chiều trung tính ≠ たところで nhấn kết quả VÔ ÍCH của một hành động cụ thể",priority:"common",explanation:"「〜（よ）うが／と」dùng để khẳng định dù rơi vào bất kỳ trường hợp nào trong hai vế đối lập (làm hay không làm, xảy ra hay không xảy ra) thì kết quả hoặc lập trường phía sau vẫn không hề suy chuyển. Khác với「〜ても」chỉ là câu nhượng bộ giả định một chiều trung tính,「〜たところで」luôn nhấn mạnh sự vô ích, vô nghĩa của một hành động hay nỗ lực cụ thể. Do đó, vế sau của「〜たところで」bắt buộc phải là kết quả tiêu cực hoặc đánh giá không đem lại tác dụng gì.",examples:[{sentence:"周りの人に賛成されようが反対されようが、私は自分の信じる道を進むつもりだ。",translation:"Dù có được mọi người xung quanh tán thành hay phản đối, tôi vẫn dự định đi theo con đường mình tin tưởng."},{sentence:"締め切りを過ぎてからいくら完璧な書類を提出したところで、受け付けてもらえないだろう。",translation:"Dù có nộp một bộ hồ sơ hoàn hảo đến đâu sau khi đã quá hạn, thì chắc cũng chẳng được tiếp nhận đâu."}],dialogue:{title:"Quyết định nhảy việc",lines:[{speaker:"A",text:"親に反対されようが何を言われようが、私は転職して海外で挑戦する決意を変えません。",translation:"Dù có bị bố mẹ phản đối hay bị nói gì đi nữa, tôi cũng không thay đổi quyết tâm chuyển việc ra nước ngoài thử thách bản thân đâu."},{speaker:"B",text:"そこまで覚悟があるなら応援するよ。でも、準備不足のまま飛び出したところで、現地で苦労するだけだから気をつけてね。",translation:"Nếu cậu đã có quyết tâm đến mức đó thì mình ủng hộ. Nhưng mà dù có lao ra nước ngoài khi chưa chuẩn bị kỹ thì cũng chỉ rước thêm vất vả thôi, nên hãy cẩn thận nhé."},{speaker:"A",text:"ありがとう。語学もビザの手続きもしっかり整えてから出発するよ。",translation:"Cảm ơn cậu. Mình sẽ chuẩn bị kỹ lưỡng cả ngoại ngữ lẫn thủ tục visa rồi mới xuất phát."}]},commonMistake:{wrong:"今さら謝ろうが許してもらえないだろうから、行くのはやめよう。",correct:"今さら謝ったところで許してもらえないだろうから、行くのはやめよう。",why:"Để diễn tả một hành động cụ thể dù có cố gắng làm ở thời điểm hiện tại cũng đã muộn màng và vô ích thì phải dùng「〜たところで」chứ không dùng「〜（よ）うが」."},note:"Vế sau của「〜たところで」luôn mang ý nghĩa tiêu cực hoặc phán đoán vô ích (không thể, vô ích, chỉ tổ...), tuyệt đối không đi cùng câu thể hiện ý chí, mệnh lệnh hay kết quả tích cực."}],106:[{pattern:"〜ならいざしらず",meaning:"Chứ nếu là… thì không biết (chấp nhận được) — so sánh 2 đối tượng/tình huống, vế sau BẮT BUỘC mang sắc thái bất mãn/ngạc nhiên",priority:"core",explanation:"Mẫu câu「〜ならいざしらず」dùng để đưa ra một trường hợp giả định, đặc biệt hoặc trong quá khứ mà ở đó sự việc có thể châm chước hoặc chấp nhận được. Người nói mượn trường hợp đó làm nền so sánh để nhấn mạnh rằng tình huống thực tế hiện tại là hoàn toàn vô lý, không thể chấp nhận. Do đó, vế sau bắt buộc phải mang sắc thái bất mãn, chê trách, ngạc nhiên hoặc phủ định mạnh mẽ (thường đi kèm với なんて, とは, 信じがたい, 許せない).",examples:[{sentence:"新入社員ならいざしらず、入社１０年目のベテランがこんな初歩的なミスを犯すなんて信じがたい。",translation:"Nếu là nhân viên mới thì còn châm chước được, chứ một người kỳ cựu vào công ty 10 năm mà lại phạm lỗi sơ đẳng thế này thì thật khó tin."},{sentence:"何十年も昔の物価ならいざしらず、現在の東京で月５万円で一人暮らしをするなんて到底無理だ。",translation:"Nếu là vật giá của mấy chục năm về trước thì không biết thế nào, chứ ở Tokyo hiện nay mà sống một mình với 5 vạn yên một tháng thì hoàn toàn không thể."}],dialogue:{title:"Trễ hẹn trong công việc",lines:[{speaker:"A",text:"課長、佐藤さんがまた連絡もなしに遅刻したそうですよ。",translation:"Trưởng phòng ơi, nghe nói anh Sato lại đi làm muộn mà không thèm báo trước đấy ạ."},{speaker:"B",text:"体調不良ならいざしらず、理由も言わずに遅れてくるとは社会人として看過できないな。",translation:"Nếu là vì lý do sức khỏe thì còn thông cảm được, chứ đến muộn mà không nói lý do thế này thì với tư cách là người đi làm không thể bỏ qua được."},{speaker:"A",text:"ええ、今回ばかりは厳しく注意したほうがよろしいかと思います。",translation:"Vâng, em nghĩ riêng lần này thì nên nhắc nhở nghiêm khắc ạ."}]},commonMistake:{wrong:"子供ならいざしらず、大人なら誰でもこの問題を簡単に解くことができる。",correct:"子供ならいざしらず、大人がこんな簡単な問題すら解けないなんて情けない。",why:"Vế sau của「〜ならいざしらず」bắt buộc phải thể hiện sự phê phán, bất mãn hoặc ngạc nhiên tiêu cực trước thực tế khó chấp nhận, không được dùng cho câu trần thuật trung tính hay đánh giá tích cực."},note:"Mẫu này mang sắc thái phê phán và bất bình mạnh mẽ hơn「〜ならともかく」, và khác với「〜はさておき」ở chỗ nó luôn đặt 2 trường hợp lên bàn cân để bác bỏ trường hợp thực tế."},{pattern:"〜はさておき（は差[さ]し置[お]いて）",meaning:"Chuyện đó gác lại đã, bàn chuyện khác quan trọng hơn — chuyển trọng tâm chủ đề, không so sánh, không mang thái độ phê phán",priority:"common",explanation:"Mẫu 「〜はさておき」 mang ý nghĩa tạm thời gác một chủ đề, vấn đề nào đó sang một bên để chuyển trọng tâm và ưu tiên bàn luận về việc khác quan trọng hoặc cấp bách hơn. Cấu trúc thường đi với danh từ hoặc cụm 「từ nghi vấn + か/かどうか」 đứng trước はさておき. Mẫu câu mang sắc thái trung tính, khách quan, không chứa hàm ý so sánh hay phê phán đối tượng được gác lại, và rất hay được dùng trong các cuộc họp, hội thảo hoặc văn viết trang trọng.",examples:[{sentence:"冗談はさておき、今回の新規事業計画について具体的なスケジュールの検討に入りましょう。",translation:"Gác chuyện đùa sang một bên, chúng ta hãy bắt đầu đi vào xem xét tiến độ cụ thể cho kế hoạch kinh doanh mới lần này."},{sentence:"デザインの良し悪しはさておき、まずはこの防災グッズの耐久性と実用性を検証する必要がある。",translation:"Tạm thời gác lại chuyện thiết kế đẹp hay xấu, trước hết chúng ta cần phải kiểm chứng độ bền và tính thực dụng của dụng cụ phòng chống thiên tai này."}],dialogue:{title:"Kế hoạch tổ chức sự kiện",lines:[{speaker:"A",text:"会場の装飾をどうするかという細かい話はさておき、まずは予算の上限を確定させませんか。",translation:"Gác lại những chuyện chi tiết như trang trí hội trường thế nào, trước mắt chúng ta chốt mức ngân sách tối đa đã được không?"},{speaker:"B",text:"そうですね。予算が決まらないことには、業者への発注も進められませんしね。",translation:"Đúng vậy nhỉ. Chừng nào chưa quyết định được ngân sách thì cũng không thể tiến hành đặt hàng bên nhà cung cấp được."},{speaker:"A",text:"では、前回の実績データを基に全体のコスト試算から始めましょう。",translation:"Vậy thì chúng ta hãy bắt đầu từ việc tính toán chi phí tổng thể dựa trên số liệu thực tế lần trước nhé."}]},commonMistake:{wrong:"部長の意向はさておき、部下が独断でプロジェクトを進めるのは問題だ。",correct:"部長の意向を差し置いて、部下が独断でプロジェクトを進めるのは問題だ。",why:"Khi muốn diễn tả hành vi bỏ qua hoặc vượt mặt một người/ý kiến quan trọng hơn kèm theo thái độ phê phán, bất bình, ta phải dùng trợ từ を trong 「〜を差し置いて」 chứ không dùng 「〜はさておき」 mang tính trung lập."},note:"Cần phân biệt 「〜はさておき」 (gác chuyện thứ yếu để bàn việc chính, trung tính khách quan) với 「〜を差し置いて」 (bỏ qua người/việc quan trọng hơn, mang sắc thái tiêu cực hoặc bất ngờ)."},{pattern:"使[つか]い分[わ]け：ならいざしらず ≠ はさておき ≠ はともかく（N2）",meaning:"Phân biệt: ならいざしらず (so sánh 2 đối tượng, vế sau bất mãn/ngạc nhiên) ≠ はさておき (chuyển chủ đề, trung tính, văn viết N1 trang trọng) ≠ はともかく (N2, cùng nghĩa với はさておき nhưng thiên về khẩu ngữ/ít trang trọng hơn)",priority:"common",explanation:"「ならいざしらず」dùng để so sánh hai đối tượng (nếu là trường hợp A thì còn có thể châm chước, chứ trường hợp B thì không thể chấp nhận), vế sau thường thể hiện sự bất mãn, chỉ trích hoặc ngạc nhiên. Trong khi đó,「はさておき」dùng để tạm gác lại một chủ đề phụ để ưu tiên bàn luận vấn đề chính quan trọng hơn, mang sắc thái trung tính, trang trọng và hay dùng trong văn viết hoặc phát biểu. Còn「はともかく」(N2) có ý nghĩa tương tự「はさておき」(đều tạm gác việc A để bàn việc B) nhưng mang tính khẩu ngữ, ít trang trọng hơn và dùng phổ biến trong giao tiếp hàng ngày.",examples:[{sentence:"新入社員ならいざしらず、課長ともあろう人がそんな初歩的なミスをするなんて信じられない。",translation:"Nếu là nhân viên mới thì không nói làm gì, đằng này đến tầm cỡ trưởng phòng mà lại mắc lỗi sơ đẳng như thế thì thật không thể tin nổi."},{sentence:"冗談はさておき、本日の会議のメインテーマである新規事業計画について話し合いを進めましょう。",translation:"Chuyện đùa gác lại đã, chúng ta hãy cùng tiến hành thảo luận về chủ đề chính của cuộc họp hôm nay là kế hoạch kinh doanh mới."}],dialogue:{title:"Thảo luận kế hoạch mới",lines:[{speaker:"A",text:"コストの問題はさておき、まずはこの企画が消費者に受け入れられるかどうかを検証すべきです。",translation:"Gác lại vấn đề chi phí đã, trước hết chúng ta cần kiểm chứng xem kế hoạch này có được người tiêu dùng đón nhận hay không."},{speaker:"B",text:"確かにそうですね。魅力を感じてもらえなければ、いくら安くても意味がありませんから。",translation:"Đúng là như vậy. Nếu không tạo được sức hút thì dù có rẻ đến đâu cũng vô nghĩa."},{speaker:"A",text:"ええ。素人ならいざしらずプロのチームですから、まずは品質と独自性にこだわりましょう。",translation:"Vâng. Nếu là người nghiệp dư thì không nói, chứ chúng ta là đội ngũ chuyên nghiệp, trước hết hãy tập trung vào chất lượng và tính độc đáo."}]},commonMistake:{wrong:"細かい議論ならいざしらず、まずは結論から先に報告してください。",correct:"細かい議論はさておき、まずは結論から先に報告してください。",why:"Để tạm gác vấn đề phụ nhằm tập trung ngay vào việc chính cần ưu tiên thì phải dùng「はさておき」, còn「ならいざしらず」chỉ dùng khi so sánh hai đối tượng với hàm ý vế sau không thể chấp nhận được."},note:"Cần lưu ý rằng「はさておき／はともかく」đều hướng sự chú ý vào vế sau quan trọng hơn mà không mang hàm ý chỉ trích, còn「ならいざしらず」luôn nhấn mạnh sự bất thường hoặc đáng phê phán ở vế sau khi so với vế trước."}],107:[{pattern:"〜をおいて（ほかに）〜ない",meaning:"Ngoài X ra thì không còn ai/gì khác — phủ định tuyệt đối, hàm khen sự duy nhất",priority:"core",explanation:'Mẫu 「〜をおいて（ほかに）〜ない」 dùng sau danh từ để biểu thị ý nghĩa "ngoài đối tượng X này ra thì không có ai/gì khác có thể làm được hoặc sánh bằng". Vế sau luôn luôn bắt buộc phải đi với các từ phủ định tuyệt đối như 「ない」「いない」. Mẫu câu này mang sắc thái đánh giá rất cao, khâm phục hoặc ca ngợi tính độc nhất vô nhị của đối tượng, thường xuất hiện trong các bài phát biểu trang trọng, giới thiệu nhân vật ưu tú hoặc đề cử phương án tối ưu.',examples:[{sentence:"次の大型プロジェクトを成功に導けるリーダーは、豊富な経験と統率力を備えた彼女をおいてほかにいない。",translation:"Người lãnh đạo có thể dẫn dắt dự án lớn tiếp theo đến thành công thì ngoài cô ấy - người sở hữu cả kinh nghiệm phong phú lẫn năng lực lãnh đạo - ra không có ai khác."},{sentence:"伝統の技と最先端の技術が見事に融合したこの作品を作れるのは、あの工房をおいてほかにないだろう。",translation:"Nơi có thể tạo ra tác phẩm kết hợp tuyệt mỹ giữa kỹ nghệ truyền thống và công nghệ tối tân thế này thì ngoài xưởng thủ công đó ra có lẽ chẳng còn nơi nào khác."}],dialogue:{title:"Chọn diễn giả hội thảo",lines:[{speaker:"A",text:"来月の国際環境シンポジウムの基調講演、誰に依頼するか決まりましたか。",translation:"Buổi thuyết trình chính tại hội thảo môi trường quốc tế tháng sau, anh đã quyết định mời ai chưa?"},{speaker:"B",text:"ええ、長年この分野の第一線で研究を続けてこられた山田教授をおいてほかに適任者はいないと思います。",translation:"Vâng, tôi nghĩ ngoài giáo sư Yamada - người đã cống hiến nghiên cứu ở tuyến đầu trong lĩnh vực này nhiều năm qua - ra thì không có ai là người thích hợp hơn cả."},{speaker:"A",text:"確かにそうですね。早速、教授のスケジュールを確認して打診してみましょう。",translation:"Đúng là như vậy rồi. Chúng ta hãy kiểm tra lịch trình của giáo sư và liên hệ thăm dò ý kiến ngay thôi."}]},commonMistake:{wrong:"あんなくだらないミスをする人は、彼をおいてほかにいない。",correct:"あんなくだらないミスをする人は、彼以外にいない。",why:"Mẫu 「〜をおいて〜ない」 luôn mang sắc thái tôn vinh, đánh giá cao đối tượng nên không được dùng trong ngữ cảnh tiêu cực, chê bai; trường hợp phê bình chỉ dùng 「〜以外に」."},note:"Khác với 「〜以外に（〜ない）」 có thể dùng trung tính cho mọi trường hợp, 「〜をおいて（ほかに）〜ない」 chỉ đi trực tiếp với Danh từ và luôn mang hàm ý ca ngợi sự độc nhất, tuyệt đối không đi với vế sau khẳng định."},{pattern:"〜ならではの＋N",meaning:"Chỉ riêng X mới có được N này — đặc trưng/phẩm chất riêng có, khen ngợi, đứng trước danh từ",priority:"common",explanation:'Mẫu 「〜ならではの＋N」 diễn tả ý nghĩa "chỉ riêng X mới có được N đặc sắc/tuyệt vời như vậy", làm nổi bật giá trị độc đáo hoặc phẩm chất vượt trội mang tính độc quyền của chủ thể. Cấu trúc này hầu như luôn mang sắc thái khen ngợi, tán thưởng và được dùng nhiều trong quảng cáo, giới thiệu văn hóa, nghệ thuật hoặc dịch vụ cao cấp. Khi bổ nghĩa trực tiếp cho danh từ đứng sau, ta dùng 「〜ならではの＋N」; còn nếu đặt ở cuối câu vị ngữ thì sẽ chuyển thành dạng 「〜ならではだ」 hoặc 「〜ならではのものだ」.',examples:[{sentence:"満天の星空を眺めながら入る露天風呂は、この温泉宿ならではの贅沢だ。",translation:"Vừa ngâm mình trong bồn tắm lộ thiên vừa ngắm nhìn bầu trời đầy sao là sự xa hoa chỉ riêng lữ quán suối nước nóng này mới có được."},{sentence:"失敗を恐れずに斬新なアイデアへ果敢に挑戦できるのは、ベンチャー企業ならではの強みと言える。",translation:"Việc có thể dũng cảm thử thách những ý tưởng mới lạ mà không sợ thất bại chính là thế mạnh đặc trưng chỉ riêng các công ty khởi nghiệp mới có."}],dialogue:{title:"Trải nghiệm ẩm thực địa phương",lines:[{speaker:"A",text:"このお料理、すごく爽やかな香りがして美味しいですね！",translation:"Món ăn này có mùi thơm rất thanh mát và ngon miệng nhỉ!"},{speaker:"B",text:"ええ、朝採れの新鮮な山菜を使っているそうで、産地ならではの奥深い味わいですね。",translation:"Vâng, nghe nói họ dùng rau rừng tươi mới hái buổi sáng, đúng là hương vị sâu lắng chỉ nơi sản xuất mới có được."},{speaker:"A",text:"本当にそうですね。都会のレストランではなかなか体験できない贅沢です。",translation:"Quả thật là vậy. Đây là sự xa xỉ mà ở nhà hàng thành phố khó lòng trải nghiệm được."}]},commonMistake:{wrong:"大都市ならではの深刻な交通渋滞には、毎朝本当にうんざりさせられる。",correct:"大都市特有の深刻な交通渋滞には、毎朝本当にうんざりさせられる。",why:"「〜ならでは」 luôn mang sắc thái khen ngợi, đánh giá tích cực nên không được dùng cho những đặc điểm tiêu cực hay phiền toái như kẹt xe, ô nhiễm (những trường hợp này phải dùng 「〜特有の」)."},note:"Khác với 「〜特有の」 mang tính trung tính (dùng được cho cả điều tốt lẫn điều xấu/bệnh tật), 「〜ならではの」 chỉ dùng riêng cho các điểm mạnh, nét đẹp độc đáo đáng tự hào."},{pattern:"〜ならではだ（文末[ぶんまつ]）",meaning:"Đúng là chỉ có X mới làm được — dùng ở cuối câu khi KHÔNG có danh từ theo sau",priority:"common",explanation:'Mẫu câu 「〜ならではだ」 đứng ở cuối câu mang ý nghĩa "đúng là chỉ có X mới có được/làm được", khẳng định phẩm chất hoặc giá trị độc đáo chỉ thuộc về đối tượng đó. Cấu trúc này thường đi sau danh từ chỉ người, nơi chốn hoặc tổ chức để khen ngợi, bày tỏ sự thán phục trước nét đặc trưng tiêu biểu khó nơi nào sánh bằng. Khác với dạng bổ nghĩa danh từ 「〜ならではの＋N」, dạng này đóng vai trò vị ngữ kết thúc câu nhằm nhấn mạnh trọn vẹn tính chất đặc thù ấy.',examples:[{sentence:"こんなに温かみのある接客ができるのは、老舗旅館ならではだ。",translation:"Có thể phục vụ khách chu đáo và ấm áp đến nhường này đúng là phong cách chỉ riêng lữ quán lâu đời mới làm được."},{sentence:"この深みのある重低音の響きは、高級オーディオメーカーならではだ。",translation:"Âm bass sâu lắng và đầy đặn như thế này quả đúng là đẳng cấp chỉ có ở hãng âm thanh cao cấp."}],dialogue:{title:"Khen ngợi kịch bản phim",lines:[{speaker:"A",text:"昨日の映画、伏線の回収が見事だったね。登場人物の心理描写の細やかさは、あの監督ならではだ。",translation:"Bộ phim hôm qua tháo gỡ các nút thắt xuất sắc thật đấy. Sự tinh tế trong việc khắc họa tâm lý nhân vật đúng là chỉ vị đạo diễn đó mới làm được."},{speaker:"B",text:"本当にそうだね。派手な演出に頼らず、あそこまで観客を引き込めるのはさすがだよ。",translation:"Đúng là như vậy. Không cần kỹ xảo phô trương mà vẫn lôi cuốn người xem đến mức đó thì thật đáng nể."},{speaker:"A",text:"次回作もどんなテーマを扱ってくれるのか、今から楽しみでならないよ。",translation:"Tôi đang cực kỳ mong đợi xem tác phẩm tiếp theo của ông ấy sẽ khai thác chủ đề gì đây."}]},commonMistake:{wrong:"こんな重大なミスをするのは、経験が浅い新人ならではだ。",correct:"こんな重大なミスをするのは、経験が浅い新人にありがちだ。",why:"Mẫu 「〜ならではだ」 chỉ mang sắc thái khen ngợi, đánh giá cao ưu điểm hoặc nét đặc sắc độc nhất, tuyệt đối không dùng cho khuyết điểm hay tình huống tiêu cực."},note:"Cần phân biệt với 「〜をおいて〜ない」 (nhấn mạnh không có ai/lựa chọn nào khác để thay thế), trong khi 「〜ならではだ」 tập trung ca ngợi nét đặc trưng, bản sắc riêng biệt vốn có của đối tượng."},{pattern:"使[つか]い分[わ]け：をおいて（ない） ≠ ならでは（の） ≠ にかけては",meaning:'をおいて…ない = phủ định tuyệt đối "không ai khác ngoài X" (排他); ならでは = đặc trưng riêng có của X (khen phẩm chất, không cần phủ định); にかけては = về khoản/lĩnh vực nào đó X giỏi nhất (không bắt buộc phủ định, không dùng cho tranh cãi)',priority:"common",explanation:"「〜をおいて（…ない）」mang tính bài trừ tuyệt đối, khẳng định ngoài đối tượng X ra thì không có ai hoặc cái gì khác có thể thay thế hay làm được (bắt buộc đi kèm vế phủ định phía sau). Trong khi đó,「〜ならでは（の）」nhấn mạnh nét đặc sắc, giá trị độc đáo chỉ riêng đối tượng X mới có nhằm mục đích ngợi khen mà không cần vế phủ định. Còn「〜にかけては」lại dùng để chỉ ra năng lực vượt trội, sở trường xuất sắc nhất ở một lĩnh vực cụ thể của đối tượng mà không mang tính loại trừ cực đoan.",examples:[{sentence:"次の大型プロジェクトのリーダーを任せられる人物は、豊富な海外経験を持つ山田部長をおいて他にはいない。",translation:"Người có thể tin tưởng giao phó trọng trách trưởng dự án lớn tiếp theo thì ngoài trưởng phòng Yamada với bề dày kinh nghiệm ở nước ngoài ra không còn ai khác."},{sentence:"職人が丹精込めて手作りしたこの家具には、既製品にはない無垢材ならではの温もりが感じられる。",translation:"Món đồ nội thất do nghệ nhân dồn tâm huyết làm thủ công này mang lại cảm giác ấm áp đặc trưng chỉ có ở gỗ nguyên khối mà hàng sản xuất sẵn không thể có."}],dialogue:{title:"Lựa chọn đạo diễn phim",lines:[{speaker:"A",text:"今回の歴史大作映画のメガホンを取れるのは、巨匠の佐藤監督をおいて他に適任者はいないでしょう。",translation:"Người có thể đảm nhận vai trò đạo diễn cho bộ phim sử thi hoành tráng lần này thì ngoài đạo diễn gạo cội Sato ra chắc không ai thích hợp hơn đâu nhỉ."},{speaker:"B",text:"同感です。壮大な世界観と繊細な人間心理の描写は、あの監督ならではの魅力ですからね。",translation:"Tôi hoàn toàn đồng ý. Việc khắc họa thế giới quan hùng vĩ và tâm lý nhân vật tinh tế chính là sức hút đặc trưng chỉ vị đạo diễn ấy mới có mà."},{speaker:"A",text:"ええ、迫力ある映像表現の技術にかけては、国内で彼の右に出る者はいませんよ。",translation:"Vâng, xét về kỹ thuật biểu đạt hình ảnh đầy uy lực thì trong nước không có ai vượt qua được ông ấy cả."}]},commonMistake:{wrong:"この濃厚なスープの深いコクは、この老舗ラーメン店をおいて他にはない美味しさだ。",correct:"この濃厚なスープの深いコクは、この老舗ラーメン店ならではの美味しさだ。",why:"Mẫu「〜をおいて…ない」chỉ dùng để loại trừ đối tượng khác nhằm tìm ra duy nhất một ứng viên/phương án thích hợp, còn khi muốn khen ngợi hương vị, nét đặc trưng độc đáo của đối tượng thì phải dùng「〜ならでは（の）」."},note:"Cần lưu ý「〜をおいて…ない」luôn bắt buộc kết thúc bằng vế phủ định (いない、ない) và đi kèm danh từ chỉ người/vật được đánh giá cao, trong khi「〜ならでは」thường đứng trước danh từ ở dạng「ならではのN」để ca ngợi phẩm chất tốt đẹp."}],108:[{pattern:"〜はおろか、〜も／さえ／すら",meaning:"Nói gì đến X — đến cả Y (vốn dễ/nhẹ hơn) cũng chẳng... (nhấn mạnh cực đoan tiêu cực)",priority:"core",explanation:"Mẫu câu này mang ý nghĩa 「X thì khỏi phải nói, ngay cả mức độ thấp hơn là Y còn không làm được」. Vế trước (X) đưa ra một sự việc ở mức độ cao hoặc hiển nhiên, vế sau (Y) đưa ra sự việc đơn giản, dễ dàng hơn nhưng cũng không đạt được, thường đi kèm các trợ từ nhấn mạnh như 「も」「さえ」「すら」 và luôn kết thúc bằng vị ngữ phủ định. Mẫu này chủ yếu dùng trong văn viết trang trọng hoặc phát biểu, thể hiện sự chê trách, bức xúc hoặc nhấn mạnh tình trạng tiêu cực, khó khăn cùng cực.",examples:[{sentence:"彼は高熱で寝込んでおり、食事はおろか、水さえ喉を通らない状態だ。",translation:"Anh ấy bị sốt cao nằm liệt giường, ăn uống thì nói làm gì, đến cả ngụm nước cũng nuốt không trôi."},{sentence:"先日の台風による被害が深刻で、工場の再開はおろか、安全確認すらまだ終わっていない。",translation:"Thiệt hại do cơn bão vừa rồi rất nghiêm trọng, việc vận hành lại nhà máy chưa dám bàn tới, đến cả kiểm tra an toàn còn chưa xong."}],dialogue:{title:"Tiến độ chuẩn bị tài liệu dự án",lines:[{speaker:"A",text:"田中さん、新規プロジェクトの進捗はどうですか。今週末までに提案書は仕上がりそうですか。",translation:"Anh Tanaka, tiến độ dự án mới thế nào rồi? Liệu đến cuối tuần này có kịp hoàn thiện bản đề xuất không?"},{speaker:"B",text:"実はトラブルが相次いでおりまして、提案書の作成はおろか、基礎的なデータ収集すら間に合っていません。",translation:"Thật ra sự cố liên tục phát sinh nên nói gì đến việc lập đề xuất, ngay cả thu thập dữ liệu cơ bản cũng chưa kịp nữa ạ."},{speaker:"A",text:"それは大変ですね。手遅れになる前に、至急チーム全体で作業の分担を見直しましょう。",translation:"Thế thì gay go rồi. Trước khi quá muộn, chúng ta hãy họp khẩn để phân chia lại công việc trong đội ngay nhé."}]},commonMistake:{wrong:"怪我のせいで、走ることはおろか、ゆっくり歩くこともできる。",correct:"怪我のせいで、走ることはおろか、ゆっくり歩くことさえできない。",why:"Vế sau của 「〜はおろか」 bắt buộc phải đi với thể phủ định (〜ない/できない) để nhấn mạnh mức độ tồi tệ, không được dùng câu khẳng định."},note:"Khác với 「〜はもちろん／〜はもとより」 có thể dùng cho cả ý tích cực và câu khẳng định, 「〜はおろか」 chỉ dùng với sắc thái tiêu cực và vế sau luôn luôn là phủ định."},{pattern:"〜もさることながら",meaning:"X đã đành (là điều hiển nhiên/nổi bật), nhưng Y mới càng đáng nói/quan trọng hơn",priority:"common",explanation:"Mẫu ngữ pháp 「〜もさることながら」 diễn tả ý nghĩa: vế trước (X) là điều hiển nhiên hoặc đã rất nổi bật rồi, nhưng vế sau (Y) lại càng đáng nói, đáng chú ý hoặc quan trọng hơn nữa. Cấu trúc này đi trực tiếp sau Danh từ (N ＋ もさることながら) và thường được dùng để đánh giá cao, tán thưởng cả hai yếu tố cùng lúc. Khác với các mẫu câu phủ định, mẫu này hoàn toàn công nhận giá trị của vế trước rồi nâng tầm nhấn mạnh thêm vế sau trong các văn cảnh trang trọng, lịch sự.",examples:[{sentence:"この最新のスマートフォンは、洗練されたデザインもさることながら、バッテリーの持ちの良さが多くのユーザーに高く評価されている。",translation:"Chiếc điện thoại thông minh đời mới này thiết kế tinh tế đã đành, nhưng thời lượng pin bền bỉ mới là điều được đông đảo người dùng đánh giá cao hơn cả."},{sentence:"彼女はピアニストとしての圧倒的な演奏技術もさることながら、聴衆を引き込む豊かな表現力も実に素晴らしい。",translation:"Cô ấy kỹ thuật biểu diễn piano đỉnh cao đã đành, nhưng khả năng biểu cảm phong phú lôi cuốn khán giả lại càng tuyệt vời hơn nữa."}],dialogue:{title:"Nhận xét nhà hàng mới",lines:[{speaker:"A",text:"駅前に新しくできたレストラン、もう行った？料理の味もさることながら、店員さんの接客が本当に丁寧で感動したよ。",translation:"Cậu đã đến nhà hàng mới mở trước ga chưa? Đồ ăn ngon đã đành, mà thái độ phục vụ chu đáo của nhân viên mới thực sự làm mình ấn tượng đấy."},{speaker:"B",text:"へえ、そうなんだ！味だけでなくサービスまで行き届いているお店なら、ぜひ行ってみたいな。",translation:"Ồ, vậy à! Quán nào mà không chỉ ngon miệng mà dịch vụ cũng chu đáo thì nhất định phải ghé thử rồi."},{speaker:"A",text:"うん、落ち着いた店の雰囲気も抜群だから、今度の週末にでも一緒に行こうよ。",translation:"Ừ, không gian yên tĩnh của quán cũng tuyệt vời lắm, cuối tuần này cùng đi nhé."}]},commonMistake:{wrong:"彼は漢字もさることながら、ひらがなさえ読めない。",correct:"彼は漢字はおろか、ひらがなさえ読めない。",why:"「〜もさることながら」thường dùng để công nhận hai yếu tố mang tính tích cực/đáng khen ngợi, không dùng trong ngữ cảnh phủ định, chê bai hoặc diễn tả mức độ tồi tệ như「〜はおろか」."},note:"Khác với「〜はおろか」(mang hàm ý tiêu cực: 'nói gì đến X, ngay cả Y còn không...'),「〜もさることながら」hoàn toàn thừa nhận giá trị tốt của X và nhấn mạnh rằng Y còn nổi bật hoặc đáng ghi nhận hơn."},{pattern:"使[つか]い分[わ]け：はおろか ≠ もさることながら ≠ どころか",meaning:"Phân biệt: はおろか (phủ định cực đoan, cần も/さえ, cùng chiều) ≠ もさることながら (không phủ định, so sánh 2 điểm đều nổi bật) ≠ どころか (N2, có thể đảo chiều kỳ vọng むしろ, khẩu ngữ hơn, không bắt buộc も/さえ)",priority:"common",explanation:'「はおろか」chuyên dùng trong ngữ cảnh tiêu cực hoặc thiếu hụt để nhấn mạnh "ngay cả cái cơ bản (vế sau đi với も/さえ/すら) còn không có/không làm được, nói chi đến cái lớn lao hơn (vế trước)". Trái lại,「もさることながら」dùng cho ngữ cảnh khẳng định, đánh giá cả hai yếu tố đều nổi bật ("A là đương nhiên/tốt rồi nhưng B cũng rất đáng chú ý"). Trong khi đó,「どころか」(thuộc N2) mang tính khẩu ngữ cao hơn, không bắt buộc đi kèm も/さえ và có thể dùng để đảo ngược hoàn toàn kỳ vọng ("chẳng những không... mà trái lại...").',examples:[{sentence:"大怪我をしてしまい、走ることはおろか、歩くことさえできない状態だ。",translation:"Tôi bị chấn thương nặng nên nói gì đến chuyện chạy, ngay cả đi bộ cũng không thể làm được."},{sentence:"このホテルは立地の良さもさることながら、スタッフの丁寧な接客も素晴らしい。",translation:"Khách sạn này vị trí đắc địa đã đành, mà phong cách phục vụ chu đáo của nhân viên cũng rất tuyệt vời."}],dialogue:{title:"Đánh giá ứng viên mới",lines:[{speaker:"A",text:"新しく応募してきた人、英語の資格はおろか、日常会話さえ怪しいらしいよ。",translation:"Người mới nộp hồ sơ ứng tuyển nghe bảo nói gì đến bằng cấp tiếng Anh, ngay cả hội thoại thông thường cũng bập bõm đấy."},{speaker:"B",text:"えっ、履歴書では実務経験が豊富だとアピールしていたのに、本当ですか。",translation:"Hả, trong sơ yếu lý lịch người đó thể hiện kinh nghiệm thực tế phong phú lắm mà, thật vậy sao?"},{speaker:"A",text:"うん。経験者どころか、基本的なビジネスマナーすら身についていなかったんだ。",translation:"Ừ. Đâu chỉ là không có kinh nghiệm, đến cả quy tắc ứng xử cơ bản trong công việc cũng chưa nắm được."}]},commonMistake:{wrong:"このレストランは料理の味はおろか、サービスも最高だ。",correct:"このレストランは料理の味もさることながら、サービスも最高だ。",why:"「はおろか」chỉ dùng cho ngữ cảnh phủ định/thiếu hụt (vế sau thường đi kèm phủ định ない), không dùng để khen ngợi tích cực cả hai mặt như「もさることながら」."},note:"Khi muốn diễn tả sự phủ định cùng chiều tăng cấp (đến cái tối thiểu còn chưa đạt) thì dùng「はおろか」, còn khi muốn phủ định để lật ngược tình thế (không những không A mà thực tế lại trái ngược/tệ hơn là B) thì phải dùng「どころか」."}],109:[{pattern:"〜だに",meaning:"Chỉ cần...(nghĩ/tưởng tượng) thôi cũng đã... — nhấn cực đoan, cảm xúc tiêu cực mạnh",priority:"core",explanation:'Mẫu ngữ pháp này mang ý nghĩa "chỉ cần... thôi là đã...", dùng để nhấn mạnh mức độ cực đoan của cảm xúc khi người nói mới chỉ nghĩ đến một việc gì đó. Cấu trúc thường đi sau các động từ liên quan đến hoạt động tư duy, tâm lý như 「想像する」「考える」「思い出す」「聞く」. Vế sau hầu như luôn kết hợp với các từ ngữ biểu thị cảm xúc tiêu cực, rùng mình hoặc sợ hãi như 「恐ろしい」「ぞっとする」「胸が痛む」. Đây là mẫu câu mang tính văn viết trang trọng, thường gặp trong các bài văn học hoặc phóng sự truyền thông.',examples:[{sentence:"あの悲惨な事故の現場を思い出すだに、今でも全身に鳥肌が立つ。",translation:"Chỉ cần nhớ lại hiện trường vụ tai nạn thảm khốc đó thôi, đến tận bây giờ toàn thân tôi vẫn nổi da gà."},{sentence:"平和な日常が一瞬で奪われてしまうなど、想像するだに恐ろしいことだ。",translation:"Việc cuộc sống bình yên thường ngày bị cướp mất chỉ trong chớp mắt, chỉ tưởng tượng thôi cũng đã thấy vô cùng đáng sợ."}],dialogue:{title:"Lo lắng về thiên tai",lines:[{speaker:"A",text:"巨大地震でインフラが完全に麻痺したらどうしよう。想像するだに恐ろしいよ。",translation:"Nếu xảy ra động đất lớn khiến cơ sở hạ tầng bị tê liệt hoàn toàn thì phải làm sao đây? Chỉ tưởng tượng thôi đã thấy rợn người rồi."},{speaker:"B",text:"不安になる気持ちは分かるけど、日頃から非常用グッズを備えておくしかないね。",translation:"Mình hiểu tâm trạng lo lắng của cậu, nhưng chúng ta chỉ còn cách chuẩn bị sẵn đồ dùng khẩn cấp thường ngày thôi."},{speaker:"A",text:"そうだね。今度の休みに非常食や防災リュックの中身を確認しておくよ。",translation:"Cậu nói đúng. Kỳ nghỉ tới mình sẽ kiểm tra lại lương thực dự trữ và ba lô phòng chống thiên tai."}]},commonMistake:{wrong:"来月大好きな歌手のコンサートに行けることを想像するだに、胸がワクワクする。",correct:"来月大好きな歌手のコンサートに行けることを想像するだけで、胸がワクワクする。",why:"Mẫu「〜だに」bắt buộc đi kèm với cảm xúc tiêu cực, ghê sợ hoặc đau đớn (như 恐ろしい, ぞっとする), không được dùng với những cảm xúc tích cực, hào hứng như「ワクワクする」."},note:"Ngoài cách dùng khẳng định trên,「だに」còn xuất hiện dưới dạng quán ngữ đi với thể phủ định tuyệt đối như「夢だに思わなかった」(chưa từng mảy may nghĩ tới) hay「微動だにしない」(không hề nhúc nhích một li)."},{pattern:"〜すら（ですら）",meaning:"Đến cả...(cũng) — văn viết trang trọng, gần nghĩa さえ (N3) nhưng cứng/文語 hơn",priority:"common",explanation:'「〜すら（ですら）」là mẫu ngữ pháp biểu thị ý nghĩa "đến cả / ngay cả... (cũng)", dùng để nêu ra một ví dụ mang tính cực đoan hoặc tối thiểu, từ đó ngầm ám chỉ những điều bình thường khác thì dĩ nhiên là thế. Mẫu này tương đồng về ý nghĩa với「〜さえ」(N3) nhưng mang sắc thái văn viết (文語) trang trọng, cứng cáp hơn và nhấn mạnh cảm xúc ngạc nhiên, bất ngờ hoặc nghiêm trọng. Trong thực tế, mẫu câu thường kết hợp nhiều với dạng phủ định「〜すら…ない」để diễn tả tình trạng tồi tệ đến mức ngay cả điều đơn giản nhất cũng không thể làm được.',examples:[{sentence:"重い病気で寝たきりの状態が続き、自分の力で起き上がることすらできない。",translation:"Vì bệnh nặng phải nằm liệt giường liên tục nên đến cả việc tự mình ngồi dậy tôi cũng không thể làm được."},{sentence:"長年の不況により、業界トップを誇る大企業ですら経営破綻に追い込まれた。",translation:"Do suy thoái kéo dài nhiều năm, ngay cả doanh nghiệp lớn dẫn đầu ngành cũng bị đẩy vào bờ vực phá sản."}],dialogue:{title:"Áp lực công việc",lines:[{speaker:"A",text:"最近、連日の残業で忙しすぎて、家族とゆっくり食事をする時間すら取れないよ。",translation:"Dạo này ngày nào cũng tăng ca bận rộn quá, đến cả thời gian ăn bữa cơm thong thả với gia đình mình cũng chẳng có."},{speaker:"B",text:"それは大変ですね。体を壊してしまう前に、有給休暇を取って休んだほうがいいですよ。",translation:"Thế thì vất vả quá. Trước khi ngã bệnh, bạn nên xin nghỉ phép để nghỉ ngơi đi thôi."},{speaker:"A",text:"そうだね。このままでは集中力すら保てそうにないから、上司に相談してみるよ。",translation:"Ừ, cứ thế này thì đến cả khả năng tập trung cũng chẳng duy trì nổi mất, để mình thử trao đổi với sếp xem sao."}]},commonMistake:{wrong:"薬を飲みすらすれば、この病気はすぐに治ります。",correct:"薬を飲みさえすれば、この病気はすぐに治ります。",why:"「〜すら」chỉ dùng để nhấn mạnh ví dụ cực đoan chứ không thể dùng trong cấu trúc giả định điều kiện tối thiểu「〜さえ…ば」(chỉ cần... là được)."},note:"So với「〜さえ」vốn dùng được rộng rãi trong cả văn nói và văn viết,「〜すら」chủ yếu xuất hiện trong văn viết/báo chí trang trọng và thường đi kèm với những tình huống mang sắc thái tiêu cực hoặc bất lợi."},{pattern:"〜たりとも〜ない",meaning:"Dù chỉ một...cũng không — phủ định TUYỆT ĐỐI với số lượng nhỏ nhất",priority:"common",explanation:"Mẫu 「〜たりとも〜ない」 đi sau danh từ chỉ đơn vị số lượng nhỏ nhất (luôn bắt đầu bằng số 1 như 一滴, 一円, 一瞬...) kết hợp với thể phủ định ở vế sau để nhấn mạnh ý nghĩa 'dù chỉ một... cũng tuyệt đối không'. Cấu trúc này biểu thị sự phủ định triệt để, dứt khoát và không chấp nhận bất kỳ ngoại lệ nào. Ngữ pháp mang sắc thái trang trọng, văn phong viết hoặc các phát biểu có tính nguyên tắc, quyết tâm cao.",examples:[{sentence:"国民から集めた大切な税金は、一円たりとも無駄にしてはならない。",translation:"Tiền thuế quý báu thu từ người dân thì dù chỉ một yên cũng tuyệt đối không được lãng phí."},{sentence:"手術を控えた執刀医は、一瞬たりとも集中力を切らすことは許されない。",translation:"Bác sĩ phẫu thuật chính trước ca mổ không được phép mất tập trung dù chỉ trong một khoảnh khắc."}],dialogue:{title:"Chuẩn bị trước trận đấu",lines:[{speaker:"A",text:"明日の本番に向けて、一秒たりとも時間を無駄にしたくないんだ。",translation:"Hướng tới buổi thi đấu chính thức ngày mai, tớ không muốn lãng phí dù chỉ một giây."},{speaker:"B",text:"そうだね。悔いが残らないように、最後まで集中して練習しよう。",translation:"Đúng vậy nhỉ. Để không phải hối tiếc, chúng ta hãy tập trung luyện tập cho đến phút cuối cùng."},{speaker:"A",text:"うん、みんなで最高の結果を出せるように頑張ろう！",translation:"Ừ, tất cả chúng ta hãy cùng cố gắng để đạt được kết quả tốt nhất nhé!"}]},commonMistake:{wrong:"喉がカラカラだったが、水は少したりとも残っていなかった。",correct:"喉がカラカラだったが、水は一滴たりとも残っていなかった。",why:"Mẫu 「〜たりとも〜ない」 bắt buộc phải đi kèm danh từ chỉ số lượng nhỏ nhất bằng con số 1 (như 一滴, 一円, 一人...) chứ không kết hợp với các từ chỉ lượng mơ hồ như 少し hay các số từ 2 trở lên."},note:"Khác với 「〜すら / 〜さえ〜ない」 có thể kết hợp với danh từ thông thường bất kỳ để nêu ví dụ cực đoan, 「〜たりとも〜ない」 chỉ đi với đơn vị số lượng nhỏ nhất (gắn liền với số 1) nhằm nhấn mạnh sự phủ định triệt để."},{pattern:"使[つか]い分[わ]け：だに ≠ すら ≠ たりとも〜ない（と さえ の関係[かんけい]）",meaning:"Phân biệt: だに (CHỈ đi động từ tư duy 想像する/考える) ≠ すら (đến cả..., thay được さえ N3, gắn danh từ) ≠ たりとも〜ない (đơn vị đếm nhỏ nhất + phủ định tuyệt đối)",priority:"common",explanation:'「だに」 chỉ giới hạn đi kèm với một số động từ tư duy, cảm xúc (như 考える, 想像する, 夢に...) mang nghĩa "chỉ cần... thôi cũng đã...". Trong khi đó, 「すら」 đi với danh từ để nêu ra một ví dụ cực đoan với nghĩa "đến cả...", là dạng văn viết trang trọng tương đương với 「さえ」. Khác với hai mẫu trên, 「たりとも〜ない」 bắt buộc phải gắn sau số từ chỉ đơn vị tối thiểu (1 + đơn vị đếm) và kết hợp với vị ngữ phủ định tuyệt đối để biểu thị ý nghĩa "dù chỉ một... cũng nhất quyết không...".',examples:[{sentence:"彼[かれ]がスパイだったなどとは、夢[ゆめ]にだに思[おも]わなかった。",translation:"Tôi chưa từng mảy may nghĩ đến (thậm chí trong giấc mơ) rằng anh ấy lại là gián điệp."},{sentence:"大人[おとな]ですら解[と]けない難問[なんもん]を、小学生[しょうがくせい]の彼[かれ]が見事[みごと]に解[と]いてしまった。",translation:"Một câu đố hóc búa mà đến cả người lớn cũng không giải nổi, vậy mà cậu bé tiểu học ấy đã giải xong một cách xuất sắc."}],dialogue:{title:"Chiến thuật trận chung kết",lines:[{speaker:"A",text:"決勝戦[けっしょうせん]では、一瞬[いっしゅん]たりとも油断[ゆだん]してはならないぞ。",translation:"Trong trận chung kết, dù chỉ một khoảnh khắc cũng tuyệt đối không được lơ là đấy."},{speaker:"B",text:"はい、相手[あいて]はプロですら手[て]を焼[や]く強豪[きょうごう]ですからね。",translation:"Vâng, đối thủ là đội cực mạnh mà đến cả giới chuyên nghiệp cũng phải bó tay mà."},{speaker:"A",text:"ああ、弱気[よわき]になることなど考[かんが]えるだにせず、全力[ぜんりょく]でぶつかろう。",translation:"Ừ, đừng mảy may nghĩ đến chuyện nản lòng, hãy dốc toàn lực chiến đấu nào."}]},commonMistake:{wrong:"彼[かれ]の連絡先[れんらくさき]だに知[し]らないのだから、連絡[れんらく]の取[と]りようがない。",correct:"彼[かれ]の連絡先[れんらくさき]すら知[し]らないのだから、連絡[れんらく]の取[と]りようがない。",why:'「だに」 chỉ dùng với các từ thể hiện hoạt động tư duy/cảm xúc (như 考える, 想像する, 夢に), không đi với danh từ thông thường để nhấn mạnh "đến cả..." như 「すら」 hay 「さえ」.'},note:"「すら」 là dạng văn viết trang trọng của 「さえ」, còn 「たりとも〜ない」 bắt buộc phải đi với từ chỉ số lượng 1 (như 一滴, 一円, 一瞬) và luôn đi với vế phủ định tuyệt đối."}],110:[{pattern:"〜にとどまらず（N／Vる こと＋にとどまらず）",meaning:"Không dừng lại ở X (mà còn lan rộng/leo thang đến Y) — nhấn mạnh phạm vi mở rộng",priority:"core",explanation:"Mẫu câu 「〜にとどまらず」 diễn tả ý nghĩa không chỉ dừng lại ở một phạm vi, đối tượng hay mức độ ban đầu X, mà còn lan rộng, phát triển hoặc leo thang sang một phạm vi lớn hơn nhiều Y. Cấu trúc này thường kết hợp trực tiếp với Danh từ chỉ phạm vi/thời gian/không gian hoặc 「Động từ thể từ điển + こと」, vế sau bắt buộc phải là phạm vi rộng hơn và hay đi kèm với trợ từ 「〜も／〜さえ／〜にまで」. Đây là cách diễn đạt trang trọng, khách quan, thường xuất hiện trong văn viết, báo chí, tin tức hoặc các bài thuyết trình, phát biểu.",examples:[{sentence:"この大気汚染の問題は、一地域の健康被害にとどまらず、地球規模の気候変動にまで深刻な影響を及ぼしている。",translation:"Vấn đề ô nhiễm không khí này không dừng lại ở tổn hại sức khỏe của một khu vực, mà còn gây ảnh hưởng nghiêm trọng tới tận biến đổi khí hậu trên quy mô toàn cầu."},{sentence:"そのアニメ作品の人気は日本国内にとどまらず、世界中の若者の間にも熱狂的なファンを生み出している。",translation:"Sức hút của tác phẩm anime đó không chỉ dừng lại ở trong nước Nhật, mà còn tạo ra lượng người hâm mộ cuồng nhiệt trong giới trẻ khắp thế giới."}],dialogue:{title:"Tầm ảnh hưởng của AI",lines:[{speaker:"A",text:"最近の生成AIの進化は、IT業界にとどまらず、教育や医療の現場にまで大きな変革をもたらしていますね。",translation:"Sự phát triển của AI tạo sinh gần đây không chỉ dừng lại ở ngành CNTT, mà còn mang lại sự thay đổi lớn tới cả môi trường giáo dục và y tế nhỉ."},{speaker:"B",text:"ええ、単なる業務の効率化だけでなく、創造的な分野にまで活用が広がっていますからね。",translation:"Vâng, vì ứng dụng của nó đang lan rộng đến cả những lĩnh vực sáng tạo chứ không đơn thuần là nâng cao hiệu suất công việc."},{speaker:"A",text:"技術の進歩に遅れないよう、私たちも柔軟に対応していく必要がありますね。",translation:"Chúng ta cũng cần thích ứng linh hoạt để không bị tụt lại phía sau sự tiến bộ công nghệ."}]},commonMistake:{wrong:"この映画の人気は世界中にとどまらず、日本国内でも大ヒットしている。",correct:"この映画の人気は日本国内にとどまらず、世界中でも大ヒットしている。",why:"「〜にとどまらず」bắt buộc vế trước là phạm vi hẹp ban đầu và vế sau phải là phạm vi mở rộng lớn hơn, không thể đặt phạm vi rộng (thế giới) ở vế trước rồi đến phạm vi hẹp (trong nước) ở vế sau."},note:"Khác với 「〜だけでなく／〜ばかりか」 dùng được cho việc bổ sung thông tin thông thường, 「〜にとどまらず」 bắt buộc phải thể hiện sự mở rộng hoặc lan tỏa rõ rệt về mặt không gian, thời gian, mức độ hoặc phạm vi ảnh hưởng."},{pattern:"〜にとどまらず＋（にも／さえ／にまで）— cấu trúc bắt buộc",meaning:"にとどまらず không bao giờ đứng một mình cuối câu — luôn phải kéo theo vế mở rộng phía sau",priority:"common",explanation:'Cấu trúc 「〜にとどまらず」 mang ý nghĩa "không chỉ dừng lại ở phạm vi X mà còn lan rộng, mở rộng ra cả Y (ở quy mô lớn hơn hoặc mức độ sâu hơn)". Điểm mấu chốt về mặt ngữ pháp là mẫu này không bao giờ đứng độc lập ở cuối câu để ngắt câu, mà bắt buộc phải kéo theo vế sau chứa các trợ từ nhấn mạnh sự lan tỏa như 「にも」「さえ」「にまで」 đi kèm vị ngữ. Mẫu câu này mang sắc thái trang trọng, thường xuất hiện trong văn viết, báo cáo, thời sự khi muốn nhấn mạnh một hiện tượng hay tầm ảnh hưởng đã vượt xa khỏi giới hạn ban đầu.',examples:[{sentence:"このアニメの人気は日本国内にとどまらず、アジア諸国や欧米にまで広がっている。",translation:"Độ nổi tiếng của bộ phim hoạt hình này không chỉ dừng lại ở trong nước Nhật mà còn lan rộng sang tận các nước châu Á và Âu Mỹ."},{sentence:"今回の豪雨による被害は農業にとどまらず、観光業や交通インフラにさえ深刻な影響を及ぼしている。",translation:"Thiệt hại do đợt mưa lớn lần này không chỉ dừng lại ở ngành nông nghiệp mà thậm chí còn gây ảnh hưởng nghiêm trọng đến cả ngành du lịch và cơ sở hạ tầng giao thông."}],dialogue:{title:"Tác động của công nghệ AI",lines:[{speaker:"A",text:"最近のAI技術の進化はIT業界にとどまらず、医療や教育の現場にまで大きな変革をもたらしているね。",translation:"Sự phát triển của công nghệ AI gần đây không chỉ dừng lại ở ngành IT mà còn mang lại sự biến đổi lớn đến tận cả lĩnh vực y tế và giáo dục nhỉ."},{speaker:"B",text:"ええ、私たちの日常業務にも導入が進んでいて、想像以上のスピードで普及していますよ。",translation:"Vâng, nó cũng đang được đưa vào công việc thường nhật của chúng ta và phổ biến với tốc độ vượt xa tưởng tượng đấy."},{speaker:"A",text:"今後は一部の専門家にとどまらず、一般の社員にさえ必須のスキルになりそうだね。",translation:"Sau này có vẻ nó sẽ trở thành kỹ năng thiết yếu đối với cả nhân viên bình thường chứ không chỉ dừng lại ở một bộ phận chuyên gia nữa."}]},commonMistake:{wrong:"円安の影響は輸出企業にとどまらず。",correct:"円安の影響は輸出企業にとどまらず、一般消費者の生活にまで及んでいる。",why:"「〜にとどまらず」không thể đứng cuối câu để đóng câu lửng lơ mà bắt buộc phải kéo theo vế sau đi kèm 「にも／さえ／にまで」 để hoàn chỉnh ý mở rộng phạm vi."},note:"So với 「〜のみならず」 hay 「〜ばかりか」, 「〜にとどまらず」 nhấn mạnh rõ rệt vào tính chất lan tỏa, bùng phát từ phạm vi hạn hẹp ban đầu sang một quy mô rộng lớn hơn nhiều."},{pattern:"〜に限[かぎ]ったことではない",meaning:"Không phải chỉ riêng X (mà nhiều nơi/nhiều người/nhiều lúc khác cũng vậy) — phủ định tính cá biệt",priority:"common",explanation:'Mẫu câu này mang ý nghĩa "không chỉ riêng đối tượng hay thời điểm X mà những nơi khác, người khác, lúc khác cũng vậy", nhằm phủ định tính cá biệt và khẳng định tính phổ biến của một hiện tượng. Ngữ pháp này thường đi sau danh từ chỉ người, tổ chức, ngành nghề hoặc mốc thời gian, kết hợp cùng các phó từ như 「今に」「一人に」「〜だけに」. Đây là cách diễn đạt mang tính trang trọng, thường được dùng khi bình luận, phân tích các vấn đề xã hội hoặc khó khăn mang tính cơ cấu.',examples:[{sentence:"少子高齢化による人手不足は、介護業界に限ったことではなく、運輸や建設など多くの分野で深刻化している。",translation:"Tình trạng thiếu hụt nhân lực do già hóa dân số và giảm tỷ lệ sinh không phải chuyện riêng của ngành điều dưỡng, mà đang ngày càng trầm trọng ở nhiều lĩnh vực như vận tải và xây dựng."},{sentence:"ネット上での誹謗中傷は、有名人に限ったことではなく、一般の人々も被害を受けるリスクにさらされている。",translation:"Việc bị vu khống, xúc phạm trên mạng không chỉ giới hạn ở người nổi tiếng, mà người bình thường cũng phải đối mặt với nguy cơ trở thành nạn nhân."}],dialogue:{title:"Vấn đề làm thêm giờ",lines:[{speaker:"A",text:"最近、うちの部署は残業が増えて大変ですね。",translation:"Dạo này phòng mình làm thêm giờ nhiều vất vả quá nhỉ."},{speaker:"B",text:"ええ、でもそれは開発部に限ったことではなく、全社的なシステム障害が原因のようですよ。",translation:"Vâng, nhưng đó không phải là chuyện riêng của phòng phát triển đâu, dường như nguyên nhân là do lỗi hệ thống trên toàn công ty đấy."},{speaker:"A",text:"そうでしたか。根本的なシステム改修を急いでもらいたいですね。",translation:"Hóa ra là vậy. Mong là công ty sẽ sớm sửa chữa hệ thống từ gốc rễ."}]},commonMistake:{wrong:"値段が高いからといって、必ずしも品質が良いことに限ったことではない。",correct:"値段が高いからといって、必ずしも品質が良いとは限らない。",why:'Mẫu 「〜に限ったことではない」 dùng để nhấn mạnh một sự việc "không riêng gì đối tượng X", còn khi muốn diễn đạt ý phủ định một phần "không hẳn/chưa chắc..." thì phải dùng 「〜とは限らない」.'},note:"Mẫu này thường đi với những vấn đề tiêu cực hoặc mang tính phê phán, và có thể thay thế bằng 「〜に限った話ではない」 trong văn phong tự nhiên."},{pattern:"使[つか]い分[わ]け：にとどまらず ≠ に限[かぎ]ったことではない ≠ どころか／はもとより（N2）",meaning:"Phân biệt: にとどまらず (phạm vi leo thang, cần vế にまで／さえ) ≠ に限ったことではない (phủ định tính cá biệt, kết luận tổng quát) ≠ どころか (đảo chiều kỳ vọng, N2) ≠ はもとより (liệt kê đã-biết, N2)",priority:"common",explanation:"「にとどまらず」được dùng để diễn tả sự việc không chỉ dừng lại ở phạm vi hẹp ban đầu mà tiếp tục lan rộng, leo thang sang quy mô lớn hơn (thường đi kèm vế 「にまで／さえ」). Trong khi đó, 「に限ったことではない」dùng để phủ định tính cá biệt của một đối tượng nhằm khẳng định đây là vấn đề chung, hiện tượng phổ biến của nhiều đối tượng khác. Khác với 「どころか」(thực tế đảo chiều hoàn toàn so với kỳ vọng) hay 「はもとより」(đưa ra điều đã biết/đương nhiên rồi bổ sung điều khác), hai mẫu này tập trung vào mức độ lan tỏa hoặc tính chất phổ quát của sự việc.",examples:[{sentence:"AIの活用はIT業界にとどまらず、医療や農業の現場にまで急速に広がっている。",translation:"Việc ứng dụng AI không dừng lại ở ngành IT mà còn đang lan rộng nhanh chóng sang tận các lĩnh vực y tế và nông nghiệp."},{sentence:"若者の離職率の高さは我が社に限ったことではなく、業界全体が直面している深刻な課題だ。",translation:"Tỷ lệ nghỉ việc cao của giới trẻ không phải là chuyện riêng của công ty chúng ta, mà là vấn đề nghiêm trọng mà toàn ngành đang phải đối mặt."}],dialogue:{title:"Tình trạng thiếu hụt nhân lực",lines:[{speaker:"A",text:"最近、地方での人手不足が一段と深刻化しているようですね。",translation:"Dạo gần đây tình trạng thiếu hụt nhân lực ở các địa phương có vẻ ngày càng trầm trọng hơn nhỉ."},{speaker:"B",text:"ええ、でもそれは地方に限ったことではなく、都心部の飲食業や介護の現場でも同じですよ。",translation:"Vâng, nhưng đó không phải là chuyện riêng của các vùng quê, mà ở các cơ sở điều dưỡng hay ngành ẩm thực tại đô thị cũng y như vậy đấy."},{speaker:"A",text:"国全体で根本的な対策を講じる必要がありますね。",translation:"Đúng là cần phải có biện pháp đối phó căn cơ trên quy mô toàn quốc rồi."}]},commonMistake:{wrong:"業績不振は我が社にとどまらず、市場全体の冷え込みによる共通の課題だ。",correct:"業績不振は我が社に限ったことではなく、市場全体の冷え込みによる共通の課題だ。",why:"Khi muốn phủ định tính cá biệt để kết luận đó là vấn đề chung thì phải dùng 「に限ったことではない」, còn 「にとどまらず」chỉ dùng khi miêu tả sự việc bắt đầu từ một điểm rồi lan rộng, leo thang sang phạm vi khác."},note:"Ghi nhớ: 「にとどまらず」nhấn mạnh vào quá trình bành trướng phạm vi (vế sau hay đi với にまで／へと), trong khi 「に限ったことではない」nhấn mạnh bản chất sự việc không phải ngoại lệ đơn lẻ."}],111:[{pattern:"〜にあって（は）",meaning:"Ở trong (hoàn cảnh đặc biệt/khủng hoảng/bước ngoặt) — KHÔNG dùng cho việc thường",priority:"core",explanation:'Mẫu 「〜にあって（は）」 đi sau danh từ để biểu thị ý nghĩa "chính vì đang ở trong một hoàn cảnh, thời kỳ đặc biệt hoặc tình huống khủng hoảng/biến động lớn". Cấu trúc này mang sắc thái trang trọng, văn viết cứng (thường dùng trong tin tức, phóng sự, diễn văn trang trọng). Vế sau thường đi kèm với những hành động, thái độ kiên định hoặc sự việc đặc biệt mang tính quyết định phát sinh từ hoàn cảnh ngặt nghèo đó.',examples:[{sentence:"激しい市場競争にあって、独自の技術開発を怠らない企業だけが生き残ることができる。",translation:"Ở trong bối cảnh cạnh tranh thị trường khốc liệt, chỉ những doanh nghiệp không ngừng nỗ lực phát triển công nghệ độc quyền mới có thể sống sót."},{sentence:"大災害という非常時にあっては、デマに惑わされず冷静に行動することが何よりも求められる。",translation:"Ở trong tình trạng khẩn cấp như thảm họa lớn, điều được đòi hỏi hơn hết là phải bình tĩnh hành động mà không bị lung lạc bởi tin đồn thất thiệt."}],dialogue:{title:"Chiến lược thời khủng hoảng",lines:[{speaker:"A",text:"世界的な不況にあって、我が社の売上も前年比で大幅に落ち込んでいます。",translation:"Ở trong bối cảnh suy thoái toàn cầu, doanh thu công ty ta cũng sụt giảm nghiêm trọng so với năm ngoái."},{speaker:"B",text:"厳しい状況ですが、今こそ新規事業への投資を見直すべきではないでしょうか。",translation:"Tình hình ngặt nghèo thật, nhưng chẳng phải chính lúc này chúng ta nên tái cơ cấu đầu tư vào mảng kinh doanh mới hay sao?"},{speaker:"A",text:"ええ、この難局にあって攻めの姿勢を崩さないことが、将来の成長につながるはずです。",translation:"Vâng, giữ vững thái độ chủ động tiến công ngay trong giai đoạn khó khăn này chắc chắn sẽ mở đường cho sự tăng trưởng tương lai."}]},commonMistake:{wrong:"普段の生活にあって、バランスの良い食事を心がけています。",correct:"普段の生活において、バランスの良い食事を心がけています。",why:"「〜にあって」 chỉ dùng cho những hoàn cảnh đặc biệt, khủng hoảng hoặc bước ngoặt lớn, tuyệt đối không dùng cho bối cảnh sinh hoạt thường ngày."},note:"Khác với 「〜において」 dùng được cho mọi bối cảnh/địa điểm chung, 「〜にあって」 luôn nhấn mạnh tính chất gay cấn, nghiêm trọng hoặc tính bước ngoặt của hoàn cảnh."},{pattern:"〜をもって（① 手段[しゅだん]・様態[ようたい]）",meaning:"Bằng / với (phương tiện, cách thức trang trọng — như で nhưng cứng hơn)",priority:"common",explanation:'Mẫu ngữ pháp 「〜をもって」 đi sau danh từ để biểu thị phương tiện, phương pháp hoặc thái độ/cách thức thực hiện hành động, mang nghĩa là "bằng / với / thông qua". Đây là cách diễn đạt rất trang trọng, có tính văn viết và nghi lễ cao, tương đương với trợ từ 「で」 nhưng mang sắc thái nghiêm túc, quyết tâm hoặc trịnh trọng hơn nhiều. Cấu trúc này thường xuất hiện trong thông báo chính thức, diễn văn, văn bản kinh doanh, hoặc đi kèm các danh từ trừu tượng chỉ tinh thần, thái độ (nỗ lực, thành ý) và phương thức liên lạc chính thức (văn bản).',examples:[{sentence:"今回の採用試験の結果につきましては、後日書面をもってお知らせいたします。",translation:"Về kết quả của kỳ thi tuyển dụng lần này, chúng tôi xin phép thông báo bằng văn bản vào ngày sau."},{sentence:"彼は持ち前の不屈の精神をもって、度重なる困難を乗り越えてきた。",translation:"Anh ấy đã vượt qua muôn vàn khó khăn liên tiếp bằng tinh thần bất khuất vốn có của mình."}],dialogue:{title:"Xử lý khiếu nại khách hàng",lines:[{speaker:"A",text:"今回のシステム障害に関するお客様からのクレームには、どのように対応すべきでしょうか。",translation:"Đối với khiếu nại của khách hàng về sự cố hệ thống lần này, chúng ta nên xử lý như thế nào ạ?"},{speaker:"B",text:"まずは誠心誠意の態度をもって直接謝罪し、早急に原因と再発防止策をご説明してください。",translation:"Trước hết, hãy trực tiếp xin lỗi bằng thái độ hết sức chân thành, rồi nhanh chóng giải thích nguyên nhân cùng biện pháp phòng ngừa tái diễn."},{speaker:"A",text:"承知いたしました。すぐに担当チームと共にお客様のもとへ伺います。",translation:"Tôi đã rõ. Tôi sẽ cùng đội ngũ phụ trách đến gặp khách hàng ngay lập tức."}]},commonMistake:{wrong:"アンケートには黒のボールペンをもってご記入ください。",correct:"アンケートには黒のボールペンでご記入ください。",why:"「〜をもって」 không dùng cho các dụng cụ, phương tiện vật chất cụ thể hàng ngày (như bút, xe cộ, đũa...), trường hợp này chỉ dùng trợ từ 「で」."},note:"Cần phân biệt với 「〜をもって」 mang nghĩa biểu thị mốc thời gian kết thúc/bắt đầu (ví dụ: 本日をもって — kể từ hôm nay / kết thúc vào hôm nay)."},{pattern:"〜をもって（② 期限[きげん]・基準時[きじゅんじ]）",meaning:"Kể từ / cho đến (mốc thời điểm chính thức bắt đầu hoặc kết thúc — văn công vụ)",priority:"common",explanation:'Mẫu ngữ pháp 「〜をもって」 đi sau danh từ chỉ thời gian để biểu thị mốc thời điểm chính thức chấm dứt hoặc khởi đầu một sự việc, trạng thái. Mẫu câu mang sắc thái rất trang trọng, tính nghi thức cao, thường xuất hiện trong các văn bản thông báo của công ty, cơ quan nhà nước hoặc các bài phát biểu khai mạc, bế mạc. Trong tiếng Việt, mẫu này thường được dịch là "kể từ...", "tính đến hết...", "vào lúc...".',examples:[{sentence:"弊社のオンラインサービスは、3月31日をもって終了とさせていただきます。",translation:"Dịch vụ trực tuyến của công ty chúng tôi xin phép được chính thức dừng hoạt động kể từ hết ngày 31 tháng 3."},{sentence:"今年度の助成金申請の受付は、本日17時をもって締め切らせていただきます。",translation:"Việc tiếp nhận hồ sơ xin trợ cấp cho năm tài chính này sẽ chính thức khép lại vào lúc 17 giờ hôm nay."}],dialogue:{title:"Thông báo đóng cửa chi nhánh",lines:[{speaker:"A",text:"全社員に通達された通り、当支社は来月15日をもって閉鎖されることになりました。",translation:"Đúng như thông báo đã gửi đến toàn thể nhân viên, chi nhánh của chúng ta sẽ chính thức đóng cửa kể từ ngày 15 tháng sau."},{speaker:"B",text:"本当に残念ですね。業務の引き継ぎや移転の準備を急いで進めなければなりませんね。",translation:"Thật đáng tiếc quá. Chúng ta phải nhanh chóng tiến hành bàn giao công việc và chuẩn bị cho việc di dời thôi."},{speaker:"A",text:"ええ、残された期間で混乱が生じないよう、各自担当業務の整理を徹底してください。",translation:"Vâng, để không xảy ra xáo trộn trong khoảng thời gian còn lại, mọi người hãy rà soát kỹ lưỡng các công việc mình phụ trách nhé."}]},commonMistake:{wrong:"宿題は明日の午後3時をもって出してください。",correct:"宿題は明日の午後3時までに出してください。",why:"「〜をもって」 chỉ dùng cho các sự kiện, thủ tục mang tính nghi thức, thông báo công vụ chính thức chứ không dùng cho các hạn định cá nhân hoặc sinh hoạt thường ngày."},note:"Trong các bài phát biểu hoặc thông báo mang tính nghi lễ trang trọng, mẫu này thường được chuyển thành dạng kính ngữ lịch sự là 「〜をもちまして」."},{pattern:"〜にあって ≠ 〜をもって（①②） ≠ 〜において（N2）",meaning:"にあって = hoàn cảnh đặc biệt/khủng hoảng; をもって = phương tiện trang trọng HOẶC mốc dứt điểm (2 nghĩa khác hẳn nhau); において = trung tính, dùng cho bối cảnh/lĩnh vực chung, KHÔNG cần đặc biệt",priority:"common",explanation:"「〜にあって」dùng để nhấn mạnh sự việc diễn ra trong một hoàn cảnh, bối cảnh đặc biệt hoặc ngặt nghèo (như khủng hoảng, biến động thời đại). Trong khi đó,「〜をもって」thuộc văn phong trang trọng, mang hai nghĩa riêng biệt là phương tiện/cách thức (bằng...) hoặc mốc thời gian dứt điểm (kể từ...). Khác với hai mẫu trên,「〜において」chỉ mang tính trung tính, dùng để nêu địa điểm, thời gian hoặc lĩnh vực chung mà không chứa sắc thái hoàn cảnh đặc biệt.",examples:[{sentence:"少子高齢化が急速に進む現代にあって、柔軟な働き方の推進は不可欠である。",translation:"Trong bối cảnh thời đại hiện nay khi tỷ lệ sinh giảm và già hóa dân số diễn ra nhanh chóng, việc thúc đẩy các hình thức làm việc linh hoạt là điều không thể thiếu."},{sentence:"当館は施設の老朽化に伴い、今月末日をもって閉館することとなりました。",translation:"Do cơ sở vật chất đã xuống cấp, bảo tàng của chúng tôi sẽ chính thức đóng cửa kể từ ngày cuối cùng của tháng này."}],dialogue:{title:"Họp triển khai dự án",lines:[{speaker:"A",text:"厳しい市場環境にあって、わが社が成長を続けるには迅速な変革が必要です。",translation:"Trong môi trường thị trường đầy khắc nghiệt này, công ty chúng ta cần phải cải cách nhanh chóng để tiếp tục tăng trưởng."},{speaker:"B",text:"同感です。まずは各部署において業務プロセスの見直しを進めましょう。",translation:"Tôi hoàn toàn đồng ý. Trước hết chúng ta hãy tiến hành rà soát lại quy trình nghiệp vụ ở từng bộ phận."},{speaker:"A",text:"ええ、全社員が熱意をもって取り組める体制を整えていきましょう。",translation:"Vâng, chúng ta hãy cùng xây dựng một bộ máy để toàn thể nhân viên có thể bắt tay thực hiện với lòng nhiệt huyết."}]},commonMistake:{wrong:"来週の月曜日に大会議室にあって、新入社員の研修を行います。",correct:"来週の月曜日に大会議室において、新入社員の研修を行います。",why:"「〜にあって」chỉ dùng cho hoàn cảnh đặc biệt hoặc tình thế ngặt nghèo, còn địa điểm tổ chức sự kiện thông thường phải dùng「〜において」."},note:"Cần lưu ý「〜をもって」có hai nét nghĩa hoàn toàn khác nhau là 'bằng phương tiện/thái độ' và 'tính đến mốc thời gian (kết thúc)', cả hai đều chỉ dùng trong văn phong trang trọng, thông báo chính thức."}],112:[{pattern:"〜に即[そく]して（に即[そく]した＋N）",meaning:"Theo sát thực tế — hành động/quyết định không rời khỏi tình hình cụ thể",priority:"core",explanation:'Mẫu câu 「〜に即して」（dạng bổ nghĩa danh từ là 「〜に即した＋N」）mang ý nghĩa là "theo sát / bám sát / dựa theo", biểu thị việc thực hiện hành động, lập kế hoạch hoặc đưa ra phán đoán sao cho phù hợp và không tách rời khỏi tình hình thực tế cụ thể. Mẫu này thường kết hợp với các danh từ chỉ hiện trạng khách quan như 現実 (hiện thực), 現状 (hiện trạng), 事実 (sự thật), 時代の変化 (sự biến đổi thời đại). Đây là cách diễn đạt mang sắc thái trang trọng, khách quan, thường dùng trong văn bản nghị luận, báo cáo kinh doanh hoặc các phát biểu chính thức.',examples:[{sentence:"今回の防災計画は、過去の被災地の現状に即して見直されることになった。",translation:"Kế hoạch phòng chống thiên tai lần này đã được quyết định rà soát lại sao cho sát với tình hình thực tế của các vùng bị thiên tai trong quá khứ."},{sentence:"都市開発を進めるにあたっては、地域住民の生活実態に即して柔軟に計画を修正していく必要がある。",translation:"Khi tiến hành phát triển đô thị, cần phải linh hoạt điều chỉnh kế hoạch sao cho bám sát với thực tế đời sống của người dân địa phương."}],dialogue:{title:"Điều chỉnh quy định làm việc",lines:[{speaker:"A",text:"リモートワークの普及に伴い、現場の労働環境に即して社内規定を見直すべきだと思います。",translation:"Cùng với sự phổ biến của làm việc từ xa, tôi nghĩ chúng ta nên rà soát lại quy định nội bộ sao cho sát với môi trường làm việc thực tế."},{speaker:"B",text:"賛成です。従来のルールに固執せず、現場社員のリアルな声を聞くことが先決ですね。",translation:"Tôi đồng ý. Việc trước mắt là không nên cố chấp giữ quy tắc cũ mà cần lắng nghe ý kiến thực tế từ nhân viên hiện trường."},{speaker:"A",text:"ええ、さっそく実態調査を行い、現場のニーズに即した新たな運用ルールを作成しましょう。",translation:"Vâng, chúng ta hãy nhanh chóng khảo sát thực tế và xây dựng quy tắc vận hành mới bám sát nhu cầu thực tế nhé."}]},commonMistake:{wrong:"法律の条文に即して、厳格に裁判が進められた。",correct:"法律の条文にのっとって、厳格に裁判が進められた。",why:"「〜に即して」chuyên dùng để nói về việc bám sát thực tế/hiện trạng đời sống, còn khi tuân theo chuẩn mực, quy tắc, luật lệ hay truyền thống thì phải dùng「〜にのっとって」."},note:"Phân biệt bộ ba:「〜に即して」(bám sát thực tế khách quan),「〜にのっとって」(tuân thủ quy tắc/luật lệ), và「〜を踏まえて」(dựa trên kinh nghiệm/kết quả đã có làm tiền đề để hành động)."},{pattern:"〜にのっとって（にのっとった＋N）",meaning:"Theo đúng quy phạm/truyền thống — tuân thủ trung thành hình thức/quy tắc đã định",priority:"common",explanation:"Mẫu「〜にのっとって」mang ý nghĩa là làm theo, tuân thủ đúng theo quy phạm, luật pháp, phong tục hay truyền thống đã định sẵn. Ngữ pháp này thường đi kèm với các danh từ mang tính chuẩn mực, khuôn mẫu như 法律 (luật pháp), 規則 (quy tắc), 伝統 (truyền thống), 慣例 (tập quán). Đây là cách diễn đạt trang trọng, thường dùng trong văn viết hoặc các bối cảnh chính thức, thể hiện sự trung thành làm theo khuôn phép mà không tự ý thay đổi.",examples:[{sentence:"古くから受け継がれてきた伝統にのっとって、今年の秋祭りも厳かに執り行われた。",translation:"Theo đúng truyền thống được kế thừa từ xa xưa, lễ hội mùa thu năm nay cũng đã được tổ chức một cách trang nghiêm."},{sentence:"裁判は個人の感情に左右されることなく、厳格な法規にのっとって公平に進められなければならない。",translation:"Phiên tòa phải được tiến hành công bằng theo đúng các quy định pháp luật nghiêm ngặt mà không bị chi phối bởi cảm xúc cá nhân."}],dialogue:{title:"Sửa đổi quy định công ty",lines:[{speaker:"A",text:"今回の就業規則の改定は、最新の労働基準法にのっとって進める必要がありますね。",translation:"Việc sửa đổi quy chế làm việc lần này cần phải tiến hành theo đúng Luật Tiêu chuẩn Lao động mới nhất nhỉ."},{speaker:"B",text:"はい、専門の社会保険労務士にも確認してもらい、法律上の不備がないようにしましょう。",translation:"Vâng, chúng ta hãy nhờ chuyên gia tư vấn bảo hiểm và lao động kiểm tra để đảm bảo không có sai sót về mặt pháp lý."},{speaker:"A",text:"では、来週の役員会議に向けて必要な資料の準備をお願いします。",translation:"Vậy thì nhờ anh chuẩn bị các tài liệu cần thiết cho cuộc họp ban giám đốc vào tuần sau nhé."}]},commonMistake:{wrong:"現場の実情にのっとって、柔軟に対応策を考えるべきだ。",correct:"現場の実情に即して、柔軟に対応策を考えるべきだ。",why:"「〜にのっとって」chỉ kết hợp với quy tắc, luật lệ, truyền thống mang tính khuôn mẫu, còn khi dựa trên thực tế, hiện trạng thì phải dùng「〜に即して」."},note:"Phân biệt:「〜にのっとって」tuân thủ quy chuẩn/luật lệ đã định,「〜に即して」bám sát thực tế, còn「〜を踏まえて」lấy kinh nghiệm/kết quả trước đó làm cơ sở phán đoán."},{pattern:"〜を踏[ふ]まえて（を踏[ふ]まえた＋N）",meaning:"Trên cơ sở (đã xem xét) — lấy điều đã biết làm căn cứ tham khảo để hành động tiếp",priority:"common",explanation:'Mẫu ngữ pháp này mang ý nghĩa "trên cơ sở / dựa trên...", dùng khi lấy một sự thật, kết quả điều tra, ý kiến đóng góp hoặc kinh nghiệm làm nền tảng, căn cứ để đưa ra quyết định hay hành động tiếp theo. Vế sau thường đi kèm với các động từ thể hiện hành động có chủ đích như xem xét, sửa đổi, lập kế hoạch (見直す, 検討する, 計画する...). Cấu trúc này mang sắc thái trang trọng, khách quan, thường được sử dụng phổ biến trong môi trường công sở, báo cáo kinh doanh hoặc các văn bản thảo luận chính thức.',examples:[{sentence:"前回のアンケート結果を踏まえて、新商品のパッケージデザインを見直すことにしました。",translation:"Dựa trên kết quả khảo sát lần trước, chúng tôi đã quyết định xem xét và điều chỉnh lại thiết kế bao bì cho sản phẩm mới."},{sentence:"専門家の指摘を踏まえて、防災マニュアルの内容をより実践的なものへと改訂した。",translation:"Trên cơ sở tiếp thu các ý kiến chỉ ra của chuyên gia, chúng tôi đã sửa đổi nội dung sổ tay phòng chống thiên tai cho mang tính thực tiễn hơn."}],dialogue:{title:"Điều chỉnh kế hoạch bán hàng",lines:[{speaker:"A",text:"先月の販売実績を踏まえて、来期の営業戦略を再検討する必要がありますね。",translation:"Dựa trên kết quả kinh doanh tháng trước, chúng ta cần phải xem xét lại chiến lược bán hàng cho kỳ tới nhỉ."},{speaker:"B",text:"そうですね。特に若年層向けのプロモーションに課題が見られました。",translation:"Đúng vậy. Đặc biệt là các chương trình quảng bá hướng đến giới trẻ vẫn còn tồn tại nhiều vấn đề."},{speaker:"A",text:"では、顧客へのヒアリング結果も踏まえて、来週までに改善案をまとめましょう。",translation:"Vậy thì dựa thêm trên kết quả phỏng vấn khách hàng, chúng ta hãy tổng hợp phương án cải thiện trước tuần sau nhé."}]},commonMistake:{wrong:"裁判は法律を踏まえて公正に行われなければならない。",correct:"裁判は法律にのっとって公正に行われなければならない。",why:"Với các quy chuẩn mang tính bắt buộc tuân thủ tuyệt đối như pháp luật thì dùng 「〜にのっとって」, còn 「〜を踏まえて」 chỉ dùng khi lấy dữ liệu, ý kiến làm căn cứ tham khảo để xử lý hành động tiếp theo."},note:"Khác với 「〜に即して」(bám sát thực tế hiện tại) và 「〜にのっとって」(tuân thủ chuẩn mực/quy tắc), 「〜を踏まえて」 nhấn mạnh việc tiếp thu, cân nhắc các yếu tố sẵn có (kết quả, ý kiến, bài học) làm bước đệm cho quyết định tương lai."},{pattern:"使[つか]い分[わ]け：に即[そく]して ≠ にのっとって ≠ を踏[ふ]まえて（cf. に基[もと]づいて）",meaning:'Phân biệt cốt lõi: に即して (thực tế cụ thể) ≠ にのっとって (quy phạm/truyền thống có sẵn) ≠ を踏まえて (xem xét rồi hành động tiếp); khác に基づいて (N2) — căn cứ luật/số liệu cố định để LÀM NỀN TẢNG phán đoán, không nhấn mạnh "bám sát thực tế" hay "tuân thủ hình thức"',priority:"common",explanation:"「に即して」diễn đạt việc lấy hiện thực khách quan, kinh nghiệm thực tế làm cơ sở để hành động mà không xa rời thực tế.「にのっとって」mang sắc thái trang trọng, dùng khi hành động tuân thủ nghiêm ngặt theo đúng chuẩn mực, tiền lệ, quy tắc hoặc truyền thống đã được định hình từ trước.「を踏まえて」nhấn mạnh việc xem xét, tiếp thu kỹ lưỡng ý kiến, kết quả hoặc bài học trước đó để làm tiền đề đưa ra bước đi tiếp theo. Khác với ba mẫu trên,「に基づいて」(N2) thuần túy lấy dữ liệu, sự thật hoặc văn bản luật pháp làm nền tảng khách quan để suy luận hay thực thi mà không mang sắc thái bám sát thực tiễn hay tuân thủ quy chuẩn.",examples:[{sentence:"新商品の開発にあたっては、消費者の実際の生活行動に即して機能を見直す必要がある。",translation:"Khi phát triển sản phẩm mới, cần xem xét lại các tính năng sao cho bám sát hành vi sinh hoạt thực tế của người tiêu dùng."},{sentence:"本校の創立記念式典は、百年前から受け継がれてきた伝統的な作法にのっとって執り行われた。",translation:"Lễ kỷ niệm thành lập trường chúng tôi đã được tiến hành tuân thủ đúng theo những nghi thức truyền thống được kế thừa từ một trăm năm trước."}],dialogue:{title:"Điều chỉnh kế hoạch dự án",lines:[{speaker:"A",text:"前回のアンケート調査で得られた利用者の声を踏まえて、アプリの改善案を作成しました。",translation:"Dựa trên việc tiếp thu ý kiến của người dùng từ đợt khảo sát vừa rồi, tôi đã lập phương án cải tiến ứng dụng."},{speaker:"B",text:"素晴らしいですね。理想論だけでなく、現場の利用実態に即して使いやすさを追求しましょう。",translation:"Tuyệt vời quá. Không chỉ nói lý thuyết, chúng ta hãy bám sát thực tế sử dụng tại hiện trường để tối ưu hóa sự tiện dụng nhé."},{speaker:"A",text:"はい、社内のセキュリティ規定にも厳格にのっとって進めてまいります。",translation:"Vâng, tôi cũng sẽ tiến hành tuân thủ nghiêm ngặt theo đúng quy định bảo mật của công ty."}]},commonMistake:{wrong:"現場の目まぐるしい変化にのっとって、臨機応変に対応してください。",correct:"現場の目まぐるしい変化に即して、臨機応変に対応してください。",why:"「にのっとって」chỉ dùng cho quy tắc, truyền thống hoặc tiền lệ chuẩn mực cố định, còn khi nói về việc thích ứng bám sát thực tế hay tình hình biến động thì phải dùng「に即して」."},note:"「に即して」nhấn mạnh sự linh hoạt theo thực tế,「にのっとって」nhấn mạnh việc tuân thủ khuôn mẫu/chuẩn mực, còn「を踏まえて」chú trọng việc lấy kết quả/kinh nghiệm trước đó làm bước đệm để hành động tiếp."}],113:[{pattern:"〜（の）いかんで（は）／〜（の）いかんによって（は）",meaning:"Tùy thuộc vào… (mà kết quả/quyết định sẽ khác đi) — văn viết trang trọng, hay gặp trong quy chế, thông báo chính thức",priority:"core",explanation:"Mẫu ngữ pháp này mang ý nghĩa tương tự như 「〜によって／〜次第で」 (tùy thuộc vào... mà kết quả, phán đoán hoặc diễn biến phía sau sẽ thay đổi/được định đoạt). Đây là cách diễn đạt mang tính trang trọng, thuộc văn phong viết hoặc phát biểu trang trọng, thường xuất hiện trong các thông báo chính thức, quy chế, hợp đồng. Danh từ đứng trước thường là những yếu tố mang tính then chốt, quyết định (như thái độ, thành tích, nỗ lực, kết quả điều tra).",examples:[{sentence:"今回の新規事業計画は、今期の業績いかんによって、見送られる可能性もある。",translation:"Kế hoạch kinh doanh mới lần này, tùy thuộc vào kết quả kinh doanh kỳ này, có khả năng sẽ bị hoãn lại."},{sentence:"面接試験の結果のいかんでは、筆記試験の点数が高くても不合格となる場合がございます。",translation:"Tùy thuộc vào kết quả phỏng vấn, dù điểm thi viết có cao thì vẫn có trường hợp bị đánh trượt."}],dialogue:{title:"Phê duyệt ngân sách dự án",lines:[{speaker:"A",text:"部長、来期の研究開発予算の増額申請の件はいかがでしょうか。",translation:"Thưa trưởng phòng, vụ xin tăng ngân sách nghiên cứu phát triển cho kỳ tới thế nào rồi ạ?"},{speaker:"B",text:"役員会でのプレゼンのいかんによっては、希望通りの予算が承認される見込みだ。",translation:"Tùy thuộc vào buổi thuyết trình trước ban điều hành, nhiều khả năng mức ngân sách theo đúng nguyện vọng sẽ được phê duyệt đấy."},{speaker:"A",text:"承知いたしました。万全の準備をして臨みます。",translation:"Tôi đã rõ. Tôi sẽ chuẩn bị thật chu đáo để bước vào buổi thuyết trình."}]},commonMistake:{wrong:"あなたがどれだけ頑張るいかんで、試験の結果が変わってくる。",correct:"あなたの努力のいかんで、試験の結果が変わってくる。",why:"「いかん」chỉ kết hợp trực tiếp với Danh từ (hoặc N + の) mang tính biến động/quyết định, không kết hợp trực tiếp với thể thông thường của động từ (V-る)."},note:"So với mẫu「〜次第で」có thể dùng linh hoạt trong cả giao tiếp hàng ngày lẫn công việc,「〜いかんで」mang sắc thái trang trọng, văn phong nghiêm túc và có sức nặng văn bản/quy định cao hơn nhiều."},{pattern:"〜（の）いかんによらず／〜（の）いかんにかかわらず",meaning:"Bất kể… ra sao (cũng không ảnh hưởng đến kết luận/quy định)",priority:"common",explanation:"Mẫu câu này có nghĩa là 'bất kể... ra sao / không phụ thuộc vào...', dùng để biểu thị rằng dù tình trạng hay nội dung phía trước có thế nào đi nữa thì hành động, kết quả hoặc quy định ở vế sau vẫn giữ nguyên không thay đổi. Phía trước luôn đi với danh từ chỉ sự biến động hoặc có nhiều khả năng xảy ra (như 理由, 結果, 成績, 採否...). Đây là cách diễn đạt mang tính trang trọng, văn viết cứng, thường được dùng trong các thông báo chính thức, hợp đồng hoặc quy định mang tính pháp lý.",examples:[{sentence:"合否の結果のいかんにかかわらず、すべての受験者に通知書を郵送いたします。",translation:"Bất kể kết quả đỗ hay trượt ra sao, chúng tôi sẽ gửi giấy thông báo qua đường bưu điện tới tất cả các thí sinh."},{sentence:"理由のいかんによらず、無断で3日以上欠勤した場合は懲戒解雇の対象となります。",translation:"Bất kể lý do là gì, trường hợp vắng mặt không phép từ 3 ngày trở lên sẽ thuộc diện bị sa thải kỷ luật."}],dialogue:{title:"Quy định hoàn trả học phí",lines:[{speaker:"A",text:"先生、体調不良で講座を途中で辞める場合、受講料は返金されますか。",translation:"Thưa thầy, nếu em nghỉ học giữa chừng vì lý do sức khỏe thì có được hoàn tiền học phí không ạ?"},{speaker:"B",text:"申し訳ありませんが、理由のいかんによらず、納入済みの受講料の返金は一切いたしかねます。",translation:"Rất tiếc nhưng bất kể lý do là gì, chúng tôi tuyệt đối không thể hoàn trả học phí đã nộp."},{speaker:"A",text:"そうなんですね。規約をしっかり確認していませんでした。",translation:"Dạ ra là vậy. Em đã không kiểm tra kỹ quy định ạ."}]},commonMistake:{wrong:"出席するかどうかのいかんによらず、期日までに返信をお願いします。",correct:"出欠のいかんによらず、期日までに返信をお願いします。",why:"Mẫu 「〜いかんによらず」 chỉ kết hợp trực tiếp với danh từ mang tính biến động hoặc lựa chọn (như 出欠, 理由), không kết hợp với mệnh đề 「〜かどうか」."},note:"So với 「〜にかかわらず」 thông thường (có thể đi trực tiếp với cặp động từ/tính từ đối lập), 「〜いかんによらず」 chỉ kết hợp với danh từ và mang sắc thái văn bản quy phạm, nghi thức trang trọng hơn nhiều."},{pattern:"いかん＝如何[いかん]（文語[ぶんご]）",meaning:'いかん là âm đọc Hán-Nhật cổ của 如何 (nghĩa "ra sao, thế nào") — chỉ xuất hiện trong văn viết trang trọng: quy chế, điều khoản, công văn, báo cáo; KHÔNG dùng trong khẩu ngữ',priority:"common",explanation:'「いかん（如何）」là âm đọc Hán-Nhật cổ của chữ Hán 如何, mang nghĩa "như thế nào, ra sao". Đây là từ ngữ thuộc phong cách văn viết cổ (文語), mang sắc thái cực kỳ trang trọng và mang tính nghi thức cao. Mẫu này chủ yếu xuất hiện trong văn bản hành chính, quy chế doanh nghiệp (規定), điều khoản hợp đồng (条項) hoặc tiêu chí xét duyệt (審査基準). Trong giao tiếp hàng ngày hoặc hội thoại thông thường, tuyệt đối không dùng「いかん」mà dùng các từ tự nhiên hơn như「どう」「どのように」hoặc「次第」.',examples:[{sentence:"理由の如何を問わず、一度納入された受験料の返金には一切応じられません。",translation:"Bất kể lý do ra sao/thế nào, lệ phí thi một khi đã nộp sẽ hoàn toàn không được hoàn trả."},{sentence:"新規事業を予定通り進めるか否かは、今期の業績の如何によって判断いたします。",translation:"Việc có tiến hành dự án mới theo đúng kế hoạch hay không sẽ được quyết định tùy theo tình hình thành tích kinh doanh kỳ này ra sao."}],dialogue:{title:"Điều khoản trong hợp đồng",lines:[{speaker:"A",text:"こちらの契約書第5条に「理由の如何を問わず中途解約は不可」とありますが、例外は一切認められないのでしょうか。",translation:"Ở điều 5 của hợp đồng này có ghi 'Bất kể lý do ra sao cũng không được hủy bỏ giữa chừng', liệu hoàn toàn không có ngoại lệ nào sao ạ?"},{speaker:"B",text:"申し訳ございません。こちらは規定の重要条項となっておりますので、いかなる場合も変更いたしかねます。",translation:"Rất xin lỗi quý khách. Đây là điều khoản trọng yếu trong quy định nên chúng tôi không thể thay đổi trong bất kỳ trường hợp nào."},{speaker:"A",text:"承知いたしました。では、その条件を踏まえて社内で再度検討いたします。",translation:"Tôi hiểu rồi. Vậy chúng tôi sẽ dựa trên điều kiện đó để thảo luận lại trong nội bộ."}]},commonMistake:{wrong:"明日のバーベキューに行くかどうかは、天気のいかんで決めるよ。",correct:"明日のバーベキューに行くかどうかは、当日の天気次第で決めるよ。",why:"「いかん（如何）」mang sắc thái văn viết cổ rất trang trọng (chỉ dùng trong văn bản, quy chế), không dùng cho các tình huống hội thoại thường nhật mà phải dùng「次第で」."},note:"Trong văn bản trang trọng,「如何」thường đi liền trong các cấu trúc cố định như「〜の如何を問わず」「〜の如何にかかわらず」「〜の如何によって／いかんで」."},{pattern:"いかんで(は) ≠ に応[おう]じて（N2）／ いかんによらず ≠ にもかかわらず",meaning:"いかんで(は) gần nghĩa に応じて (N2) nhưng いかんで(は) chỉ đi sau danh từ trừu tượng cố định (結果・内容・程度・出来) trong văn bản chính thức, còn に応じて linh hoạt hơn, dùng cả với danh từ cụ thể (収入・需要) và khẩu ngữ. いかんによらず gần nghĩa にもかかわらず nhưng いかんによらず mang tính QUY ĐỊNH khách quan, trung tính (luật/điều khoản), còn にもかかわらず nhấn mạnh sự TRÁI NGƯỢC với kỳ vọng/ngạc nhiên của người nói.",priority:"common",explanation:'「いかんで(は)」 có ý nghĩa tương tự 「に応じて」(N2) là "tùy thuộc vào...", nhưng chỉ kết hợp với các danh từ trừu tượng cố định (như 結果, 成果, 内容, 程度) trong các văn bản mang tính trang trọng, chính thức. Trong khi đó, 「に応じて」 linh hoạt hơn nhiều, có thể đi kèm danh từ cụ thể (thu nhập, độ tuổi, nhu cầu) và dùng được trong cả văn phong giao tiếp thường ngày. Về mặt phủ định, 「いかんによらず」 biểu thị quy tắc hay điều khoản mang tính khách quan, trung tính rằng "bất kể... ra sao thì quy định vẫn giữ nguyên". Ngược lại, 「にもかかわらず」 lại nhấn mạnh tâm lý ngạc nhiên hoặc sự đối lập thực tế nằm ngoài dự đoán, kỳ vọng của người nói.',examples:[{sentence:"プレゼンテーションの成否のいかんで、新規事業への予算配分が見直されることになっている。",translation:"Tùy vào sự thành bại của bài thuyết trình mà việc phân bổ ngân sách cho dự án mới sẽ được xem xét lại."},{sentence:"国籍や身分のいかんによらず、すべての被災者に救援物資を平等に配布する。",translation:"Bất kể quốc tịch hay địa vị ra sao, hàng cứu trợ đều được phân phát bình đẳng cho tất cả người dân vùng thiên tai."}],dialogue:{title:"Kế hoạch tổ chức sự kiện",lines:[{speaker:"A",text:"明日の屋外イベントですが、もし悪天候になったら延期されますか。",translation:"Về sự kiện ngoài trời ngày mai, nếu thời tiết xấu thì có bị hoãn không ạ?"},{speaker:"B",text:"いいえ、天候のいかんによらず、雨天決行で予定通り開催いたします。",translation:"Không, bất kể thời tiết ra sao, chúng tôi vẫn tiến hành tổ chức theo đúng kế hoạch."},{speaker:"A",text:"承知いたしました。雨具の準備を呼びかけておきます。",translation:"Tôi hiểu rồi. Tôi sẽ thông báo mọi người chuẩn bị sẵn đồ đi mưa."}]},commonMistake:{wrong:"お客様のご予算のいかんで、最適な宿泊プランをご案内いたします。",correct:"お客様のご予算に応じて、最適な宿泊プランをご案内いたします。",why:"「ご予算」 là danh từ cụ thể nên phải dùng 「に応じて」, còn 「いかんで」 chỉ đi với danh từ trừu tượng cố định trong văn cảnh mang tính quyết định, chính thức."},note:"Hãy ghi nhớ 「いかんで／いかんによらず」 thường đi kèm các danh từ mang tính biến thiên như 成否, 結果, 理由 trong các thông báo và quy chế chính thức."}],114:[{pattern:"〜をよそに",meaning:"Mặc kệ, phớt lờ mối lo/ý kiến của NGƯỜI KHÁC mà vẫn hành động theo ý mình",priority:"core",explanation:"Mẫu ngữ pháp「〜をよそに」được dùng để diễn tả hành vi phớt lờ, mặc kệ ý kiến, sự lo lắng, kỳ vọng hoặc lời khuyên từ những người xung quanh để tự ý hành động theo ý mình. Cấu trúc đi kèm trực tiếp với danh từ chỉ cảm xúc hoặc sự quan tâm của người khác như「心配」「期待」「反対」「忠告」. Câu văn thường thể hiện sắc thái phê phán, bất bình hoặc ngạc nhiên trước sự bàng quan, thờ ơ của chủ thể.",examples:[{sentence:"親の心配をよそに、彼は安定した仕事を辞めて海外へ行ってしまった。",translation:"Mặc kệ sự lo lắng của cha mẹ, anh ấy đã bỏ công việc ổn định để ra nước ngoài."},{sentence:"医師の度重なる忠告をよそに、祖父は退院後すぐにまたタバコを吸い始めた。",translation:"Phớt lờ những lời khuyên can liên tục của bác sĩ, ông tôi vừa xuất viện là lại bắt đầu hút thuốc lá."}],dialogue:{title:"Quyết định khởi nghiệp",lines:[{speaker:"A",text:"山田さん、周囲の反対をよそに会社を辞めて起業するらしいよ。",translation:"Nghe nói anh Yamada mặc kệ sự phản đối của mọi người xung quanh, quyết định nghỉ việc để khởi nghiệp đấy."},{speaker:"B",text:"えっ、本当？今の不況の中ではリスクが大きすぎるのに、思い切ったね。",translation:"Hả, thật á? Giữa lúc kinh tế khó khăn thế này rủi ro lớn lắm, anh ấy liều thật đấy."},{speaker:"A",text:"うん、成功するかどうかは別として、あの行動力には驚かされるよ。",translation:"Ừ, chưa biết có thành công hay không nhưng sự quyết đoán dám làm của anh ấy khiến ai cũng bất ngờ."}]},commonMistake:{wrong:"選手たちは大雨をよそに、最後まで全力で走り抜いた。",correct:"選手たちは大雨をものともせず、最後まで全力で走り抜いた。",why:"「〜をよそに」chỉ dùng khi phớt lờ sự quan tâm, lo lắng hay ý kiến của người khác chứ không dùng với trở ngại thời tiết, khó khăn ngoại cảnh để ca ngợi tinh thần kiên cường."},note:"Khác với「〜をよそに」(thờ ơ với ý kiến người khác),「〜をものともせず」dùng để ca ngợi việc vượt qua khó khăn, còn「〜を顧みず」dùng khi không màng đến rủi ro/tính mạng của bản thân."},{pattern:"〜をものともせず（に）",meaning:"Bất chấp khó khăn/trở ngại để vượt qua — thường khen ngợi nghị lực của NGƯỜI KHÁC",priority:"common",explanation:'Mẫu「〜をものともせず（に）」mang ý nghĩa "bất chấp, vượt lên trên những khó khăn, trở ngại lớn" để nỗ lực hành động hoặc đạt được thành quả. Mẫu câu thường kết hợp với các danh từ chỉ nghịch cảnh, tật nguyền, điều kiện khắc nghiệt (như 逆境, 障害, 悪天候, プレッシャー). Cấu trúc này mang sắc thái thán phục, ngợi ca ý chí và sự dũng cảm của người khác (ngôi thứ 3) chứ không dùng cho bản thân để tự đề cao.',examples:[{sentence:"彼女は生まれつきの視覚障害をものともせず、難関の司法試験に見事一発で合格した。",translation:"Cô ấy đã bất chấp khiếm khuyết thị giác bẩm sinh để xuất sắc đỗ kỳ thi tư pháp đầy cam go ngay từ lần đầu tiên."},{sentence:"救助隊員たちは激しい暴風雨をものともせずに、夜を徹して被災者の捜索活動を続けた。",translation:"Các nhân viên cứu trợ đã bất chấp mưa bão dữ dội, tiếp tục công tác tìm kiếm nạn nhân xuyên đêm."}],dialogue:{title:"Tán dương vận động viên",lines:[{speaker:"A",text:"田中選手、足の怪我をものともせずに最後まで走り抜いて、見事優勝しましたね。",translation:"Tuyển thủ Tanaka đã bất chấp chấn thương ở chân để chạy hết mình đến cùng và xuất sắc giành chức vô địch nhỉ."},{speaker:"B",text:"ええ、あの強い精神力と諦めない姿勢には本当に胸を打たれました。",translation:"Vâng, tinh thần quật cường và thái độ không bỏ cuộc ấy thực sự làm tôi vô cùng xúc động."},{speaker:"A",text:"私たちも見習って、どんな困難があっても前を向いて頑張りたいですね。",translation:"Chúng ta cũng nên học tập theo, dù gặp khó khăn gì cũng luôn hướng về phía trước và cố gắng."}]},commonMistake:{wrong:"彼は周囲の忠告をものともせず、危険な投資に手を出してしまった。",correct:"彼は周囲の忠告をよそに、危険な投資に手を出してしまった。",why:"「〜をものともせず」dùng khi đối mặt với gian khổ, nghịch cảnh cần vượt qua, còn hành động phớt lờ, coi thường lời khuyên hay ý kiến của người khác thì phải dùng「〜をよそに」."},note:"Cần phân biệt với「〜をよそに」(bỏ ngoài tai sự lo lắng, can ngăn của người khác) và lưu ý không dùng「〜をものともせず」ở ngôi thứ nhất để tự khen ngợi chính mình."},{pattern:"〜を顧[かえり]みず",meaning:"Không màng đến thứ đáng lẽ phải quan tâm (nguy hiểm, bản thân, gia đình) mà vẫn làm",priority:"common",explanation:"Mẫu câu「〜を顧みず」diễn tả hành vi bất chấp, không màng đến những thứ quý giá hoặc đáng lẽ bản thân phải quan tâm, lo lắng như tính mạng, sức khỏe hay gia đình. Cấu trúc thường là Danh từ + を顧みず (hoặc を顧みない N / を顧みないで), trong đó danh từ đi kèm chủ yếu là những yếu tố thuộc về chính bản thân người nói/chủ thể. Mẫu này thường dùng với sắc thái ca ngợi sự dũng cảm, tận tụy hy sinh vì người khác hoặc vì nghĩa lớn, nhưng đôi khi cũng dùng để phê phán hành vi bỏ bê trách nhiệm đối với gia đình.",examples:[{sentence:"彼は自身の健康を顧みず、新薬の開発に昼夜を問わず没頭した。",translation:"Anh ấy không màng đến sức khỏe của bản thân, lao vào nghiên cứu phát triển loại thuốc mới bất kể ngày đêm."},{sentence:"家庭を顧みずに仕事ばかりしていると、いつか家族に見放されてしまうよ。",translation:"Nếu cứ cắm đầu vào công việc mà không màng gì đến gia đình thì có ngày sẽ bị người nhà quay lưng đấy."}],dialogue:{title:"Cứu người trong hỏa hoạn",lines:[{speaker:"A",text:"先日の火災で、隊長は自らの命を顧みずにとり残された子どもを救出したそうですね。",translation:"Nghe nói trong vụ hỏa hoạn hôm trước, đội trưởng đã không màng đến tính mạng của bản thân để giải cứu đứa trẻ bị mắc kẹt nhỉ."},{speaker:"B",text:"ええ、本当に勇敢な方ですが、一歩間違えれば命を落とすところでした。",translation:"Vâng, đúng là một người vô cùng dũng cảm, nhưng chỉ sơ sẩy một chút thôi là mất mạng rồi."},{speaker:"A",text:"その強い責任感には本当に頭が下がりますが、どうかご無事でいてほしいですね。",translation:"Tinh thần trách nhiệm cao của anh ấy thật đáng khâm phục, nhưng cũng mong anh ấy luôn được bình an."}]},commonMistake:{wrong:"救助隊は激しい風雨を顧みず、捜索活動を続けた。",correct:"救助隊は激しい風雨をものともせず、捜索活動を続けた。",why:"「〜を顧みず」chỉ đi với những điều thuộc về bản thân cần giữ gìn/lo lắng (tính mạng, gia đình, sức khỏe), còn đối với trở ngại, điều kiện khắc nghiệt từ ngoại cảnh như thời tiết thì phải dùng「〜をものともせず」."},note:"Cần phân biệt với「〜をものともせず」(bất chấp khó khăn, cản trở khách quan bên ngoài) và「〜をよそに」(mặc kệ sự lo lắng, can ngăn hoặc kỳ vọng của người khác)."},{pattern:"使[つか]い分[わ]け：をよそに ≠ をものともせず ≠ を顧みず ≠ を問わず（N2）",meaning:"Phân biệt cốt lõi: をよそに (lo lắng của NGƯỜI KHÁC) ≠ をものともせず (khó khăn CỦA MÌNH, khen ngợi) ≠ を顧みず (thứ đáng lẽ phải bảo vệ) ≠ を問わず/にかかわらず (N2, trung tính, không cảm xúc)",priority:"common",explanation:"「〜をよそに」diễn tả việc phớt lờ, bỏ ngoài tai sự lo lắng, kỳ vọng hoặc chỉ trích từ người khác hay dư luận xung quanh. Trong khi đó, 「〜をものともせず」nhấn mạnh sự kiên cường vượt qua khó khăn, trở ngại của chính mình (mang sắc thái khâm phục, ngợi ca), còn 「〜を顧みず」thể hiện sự liều lĩnh, bất chấp việc hy sinh những thứ bản thân lẽ ra phải trân trọng bảo vệ như tính mạng, gia đình hay sức khỏe. Trái ngược với 3 mẫu N1 đầy cảm xúc trên, mẫu N2 「〜を問わず」chỉ mang tính trung tính, khách quan khi đưa ra điều kiện không phân biệt (như tuổi tác, quốc tịch, giới tính).",examples:[{sentence:"彼は重い病気の後遺症をものともせず、過酷なトレーニングを続けて金メダルを獲得した。",translation:"Bất chấp di chứng của căn bệnh nặng, anh ấy vẫn kiên trì luyện tập khắc nghiệt và xuất sắc giành huy chương vàng."},{sentence:"親や周囲の心配をよそに、息子は安定した公務員の仕事を辞めて海外へ旅立ってしまった。",translation:"Mặc kệ nỗi lo lắng của cha mẹ và mọi người xung quanh, cậu con trai đã bỏ công việc công chức ổn định để lên đường ra nước ngoài."}],dialogue:{title:"Hành động dũng cảm",lines:[{speaker:"A",text:"火災現場で、消防士が自身の危険を顧みず、逃げ遅れた子供を救出したそうですね。",translation:"Nghe nói tại hiện trường vụ cháy, người lính cứu hỏa đã không màng nguy hiểm của bản thân để cứu đứa trẻ mắc kẹt nhỉ."},{speaker:"B",text:"ええ、猛火の恐怖をものともせず立ち向かった勇気には、本当に頭が下がります。",translation:"Vâng, sự dũng cảm đối mặt bất chấp nỗi sợ hãi trước biển lửa dữ dội thực sự khiến tôi vô cùng khâm phục."},{speaker:"A",text:"周囲の制止をよそに飛び込んだそうですが、二人とも無事で本当によかったですね。",translation:"Nghe nói anh ấy đã lao vào mặc kệ sự can ngăn của mọi người xung quanh, thật may là cả hai đều bình an vô sự."}]},commonMistake:{wrong:"年齢や経験を顧みず、やる気のある方を幅広く募集しております。",correct:"年齢や経験を問わず、やる気のある方を幅広く募集しております。",why:"Khi nêu điều kiện tuyển dụng khách quan, trung tính thì phải dùng「〜を問わず」, còn「〜を顧みず」chỉ dùng cho hành động liều lĩnh, không màng đến những điều quý giá đáng lẽ phải bảo vệ."},note:"Mẹo nhớ cốt lõi:「よそに」(phớt lờ người ngoài),「ものともせず」(vượt nghịch cảnh bản thân),「顧みず」(liều lĩnh bỏ qua điều quý giá),「問わず」(điều kiện khách quan không phân biệt)."}],115:[{pattern:"〜ずにはおかない（Vさせずにはおかない）",meaning:"Tất yếu sẽ gây ra… — chủ thể thường là SỰ VIỆC/TÁC PHẨM/TỔ CHỨC, hay đi kèm thể sai khiến",priority:"core",explanation:"Mẫu câu này dùng để biểu thị một sự việc, hiện tượng hoặc tác phẩm nghệ thuật có sức ảnh hưởng mạnh mẽ, tất yếu sẽ gây ra một cảm xúc, rung động hoặc biến chuyển lớn cho người khác/xã hội. Trong cách dùng này, ngữ pháp hầu hết đi kèm với thể sai khiến (Vさせずにはおかない) như làm rung động, làm bật cười, khiến suy ngẫm. Ngoài ra, mẫu câu còn được dùng để thể hiện quyết tâm sắt đá mang tính ý chí của người nói rằng nhất định sẽ thực hiện một hành động nào đó đến cùng.",examples:[{sentence:"彼女の圧倒的な歌声は、会場にいるすべての観客を感動させずにはおかない。",translation:"Giọng hát đầy nội lực của cô ấy nhất định sẽ khiến toàn bộ khán giả có mặt trong khán phòng phải xúc động."},{sentence:"自然環境を破壊し続ければ、将来世代に深刻な被害をもたらさずにはおかないだろう。",translation:"Nếu chúng ta cứ tiếp tục hủy hoại môi trường tự nhiên, nhất định sẽ để lại những hậu quả khôn lường cho các thế hệ tương lai."}],dialogue:{title:"Bàn về bộ phim tài liệu",lines:[{speaker:"A",text:"昨日公開されたあのドキュメンタリー映画、もう観た？",translation:"Cậu đã xem bộ phim tài liệu vừa công chiếu hôm qua chưa?"},{speaker:"B",text:"まだ観てないけど、SNSでものすごく話題になっているね。",translation:"Tớ chưa xem, nhưng thấy trên mạng xã hội đang bàn tán xôn xao lắm."},{speaker:"A",text:"うん、戦争の現実を生々しく描いていて、観る者の心を揺さぶらずにはおかない傑作だよ。",translation:"Ừ, phim khắc họa hiện thực chiến tranh chân thực đến mức nhất định sẽ làm lay động trái tim bất cứ ai theo dõi, đúng là một kiệt tác."}]},commonMistake:{wrong:"他人の車を傷つけてしまったのだから、弁償せずにはおかない。",correct:"他人の車を傷つけてしまったのだから、弁償せずにはすまない。",why:"Khi nói về trách nhiệm, nghĩa vụ hoặc quy chuẩn xã hội bắt buộc phải làm việc gì đó (không đền không xong), ta phải dùng 〜ずにはすまない chứ không dùng 〜ずにはおかない."},note:"Cần phân biệt rõ: 〜ずにはおかない nhấn mạnh tác động tất yếu gây ảnh hưởng mãnh liệt lên người khác (thường đi với thể sai khiến), trong khi 〜ずにはすまない diễn tả việc bị trói buộc bởi đạo đức, luật lệ hay lương tâm rằng 'không làm là không xong'."},{pattern:"〜ずにはおかない（決意[けつい]の用法[ようほう]）",meaning:"Quyết tâm mạnh mẽ, không dừng lại cho đến khi làm được — chủ thể là NGƯỜI có ý chí",priority:"common",explanation:"Mẫu 「〜ずにはおかない」 trong cách dùng quyết tâm (決意) biểu thị ý chí sắt đá, quyết tâm mãnh liệt của người nói rằng «nhất định sẽ làm bằng được, tuyệt đối không từ bỏ». Cấu trúc được chia theo dạng: Động từ thể ない (bỏ ない) + ずにはおかない (riêng する chuyển thành せずにはおかない). Mẫu này thường mang sắc thái trang trọng, kịch tính, hay được sử dụng trong văn viết hoặc đối thoại thể hiện ý chí vươn lên, tìm ra chân tướng sự việc hoặc quyết tâm đánh bại đối thủ.",examples:[{sentence:"どんな困難があろうとも、このプロジェクトを成功させずにはおかない。",translation:"Dù có gặp muôn vàn khó khăn đi nữa, tôi cũng quyết tâm sẽ đưa dự án này đến thành công bằng được."},{sentence:"今回の屈辱を晴らすため、次の大会ではライバルを倒さずにはおかない。",translation:"Để rửa sạch nỗi nhục lần này, tại giải đấu tiếp theo tôi nhất định sẽ đánh bại đối thủ cho bằng được."}],dialogue:{title:"Quyết tâm tìm sự thật",lines:[{speaker:"A",text:"このまま事件を迷宮入りにさせてたまるか。何年かかろうと、真実を突き止めずにはおかないぞ。",translation:"Tuyệt đối không thể để vụ án rơi vào ngõ cụt như thế này được. Dù có mất bao nhiêu năm, tôi nhất định sẽ tìm ra sự thật bằng được."},{speaker:"B",text:"先輩、そのお気持ちは分かりますが、決して無茶だけはしないでくださいね。",translation:"Tiền bối, em hiểu tâm trạng của anh, nhưng xin anh tuyệt đối đừng hành động liều lĩnh nhé."},{speaker:"A",text:"ああ、分かっている。必ず生きて戻り、黒幕の正体を暴いてみせるさ。",translation:"Ừ, anh biết rồi. Anh nhất định sẽ sống sót trở về và vạch trần chân tướng kẻ đứng sau giật dây."}]},commonMistake:{wrong:"相手がどんな強豪でも、次の試合は絶対に勝たずにはすまない。",correct:"相手がどんな強豪でも、次の試合は絶対に勝たずにはおかない。",why:"「〜ずにはすまない」 diễn tả trách nhiệm, bổn phận hoặc tình thế đạo đức buộc phải làm, còn khi muốn thể hiện ý chí quyết tâm đạt được mục tiêu của bản thân thì phải dùng 「〜ずにはおかない」."},note:"Cần phân biệt với cách dùng tác động tự nhiên của 「〜ずにはおかない」 (chủ ngữ là sự vật/sự việc khiến người khác nảy sinh cảm xúc như 「感動させずにはおかない」), trong khi ở cách dùng quyết tâm thì chủ ngữ luôn là con người mang ý chí chủ động."},{pattern:"〜ずにはすまない",meaning:"Không làm thì không xong / không thể không — nghĩa vụ đạo đức-xã hội, chủ thể thường là NGƯỜI",priority:"common",explanation:"Mẫu câu này diễn tả ý nghĩa về mặt đạo đức, trách nhiệm xã hội hoặc quy tắc thông thường thì không thể không làm việc gì đó, nếu không làm thì sự việc sẽ không được giải quyết ổn thỏa. Ngữ pháp này thường đi cùng các động từ thể hiện hành động có chủ ý như xin lỗi, bồi thường, từ chức hay chịu trách nhiệm. Chủ thể của hành động thường là con người, nhấn mạnh vào sức ép tâm lý hoặc tình thế bắt buộc phải thực hiện nghĩa vụ.",examples:[{sentence:"会社の重要データを誤って消去してしまったのだから、始末書を提出するだけでなく、直接上司に謝罪せずにはすまないだろう。",translation:"Vì đã vô tình xóa mất dữ liệu quan trọng của công ty nên không chỉ nộp bản kiểm điểm, chắc chắn tôi không thể không trực tiếp xin lỗi cấp trên."},{sentence:"不注意で隣の家の車に傷をつけてしまった以上、修理代を弁償せずにはすまない。",translation:"Một khi đã bất cẩn làm trầy xước xe nhà hàng xóm thì không thể không bồi thường chi phí sửa chữa."}],dialogue:{title:"Trách nhiệm sự cố",lines:[{speaker:"A",text:"今回のシステム障害でお客様に多大な損害を与えてしまった以上、社長自ら会見を開いて謝罪せずにはすまないでしょう。",translation:"Một khi sự cố hệ thống lần này đã gây thiệt hại lớn cho khách hàng, ắt hẳn đích thân giám đốc không thể không mở họp báo xin lỗi."},{speaker:"B",text:"そうですね。下手に隠そうとすれば、かえって企業の社会的信用を失うことになりますから。",translation:"Đúng vậy. Nếu cố tình che giấu vụng về thì ngược lại sẽ đánh mất uy tín xã hội của doanh nghiệp mất."},{speaker:"A",text:"ええ、すぐに広報部と連携して発表の準備を進めましょう。",translation:"Ừ, chúng ta hãy phối hợp ngay với phòng truyền thông để tiến hành chuẩn bị công bố thôi."}]},commonMistake:{wrong:"その感動的な映画を見て、涙を流さずにはすまなかった。",correct:"その感動的な映画を見て、涙を流さずにはいられなかった。",why:"「〜ずにはすまない」dùng cho nghĩa vụ đạo đức/xã hội (không làm không xong), còn cảm xúc bột phát không kìm nén được như rơi nước mắt thì phải dùng 「〜ずにはいられない」."},note:"Tránh nhầm với 「〜ずにはおかない」 (ý chí mạnh mẽ nhất định sẽ tác động làm đối phương/tình thế thay đổi), còn 「〜ずにはすまない」 là nhận thức về trách nhiệm bắt buộc phải làm."},{pattern:"使[つか]い分[わ]け：ずにはおかない ≠ ずにはすまない ≠ ないわけにはいかない",meaning:"Phân biệt: ずにはおかない (tất yếu/quyết tâm) ≠ ずにはすまない (nghĩa vụ đạo đức của người) ≠ ないわけにはいかない (N2, không thể không vì hoàn cảnh/lẽ thường, trung tính hơn)",priority:"common",explanation:"「〜ずにはおかない」dùng để diễn tả một sự việc tất yếu sẽ gây ra tác động mạnh mẽ đến người khác hoặc thể hiện quyết tâm sắt đá nhất định phải thực hiện. Trong khi đó,「〜ずにはすまない」nhấn mạnh vào nghĩa vụ đạo đức, lương tâm và quy chuẩn xã hội — nếu không làm thì về mặt đạo lý sẽ không thể xong hoặc không được chấp nhận. Khác với hai mẫu N1 mang tính cảm xúc và áp lực đạo lý nặng nề này,「〜ないわけにはいかない」(N2) chỉ việc buộc phải làm do hoàn cảnh thực tế hoặc phép lịch sự với sắc thái trung tính hơn.",examples:[{sentence:"彼[かれ]の 圧倒的[あっとうてき]な 演技[えんぎ]は、 見[み]る 人[ひと] すべてを 感動[かんどう]させずにはおかない。",translation:"Diễn xuất áp đảo của anh ấy nhất định sẽ làm rung động tất cả những người theo dõi."},{sentence:"人[ひと]の 車[くるま]を 傷[きず]つけてしまったのだから、 謝罪[しゃざい]して 弁償[べんしょう]せずにはすまない。",translation:"Vì đã làm trầy xước xe của người khác nên về mặt đạo lý tôi không thể không xin lỗi và bồi thường."}],dialogue:{title:"Trách nhiệm sau sự cố",lines:[{speaker:"A",text:"プロジェクトで 重大[じゅうだい]な ミスを 隠[かく]していたことが 発覚[はっかく]したらしいよ。",translation:"Nghe nói việc che giấu lỗi nghiêm trọng trong dự án đã bị phát giác rồi đấy."},{speaker:"B",text:"えっ、本当[ほんとう]に？ それは さすがに 責任者[せきにんしゃ]が 処分[しょぶん]を 受[う]けずにはすまないだろうね。",translation:"Hả, thật sao? Chuyện như vậy thì chắc chắn người chịu trách nhiệm không thể không nhận kỷ luật rồi."},{speaker:"A",text:"うん、 会社[かいしゃ]の 信用[しんよう]に 関[かか]わる 大問題[だいもんだい]だからね。",translation:"Ừ, vì đây là vấn đề lớn liên quan đến uy tín của cả công ty mà."}]},commonMistake:{wrong:"この 素晴[すば]らしい 映画[えいが]は、 観客[かんきゃく]を 泣[な]かせずにはすまない。",correct:"この 素晴[すば]らしい 映画[えいが]は、 観客[かんきゃく]を 泣[な]かせずにはおかない。",why:"「〜ずにはすまない」chỉ dùng khi nói về nghĩa vụ, lương tâm hoặc trách nhiệm của chủ thể, còn để diễn tả việc một tác phẩm/sự việc tất yếu gây ảnh hưởng hoặc xúc động mạnh cho người khác thì bắt buộc phải dùng「〜ずにはおかない」."},note:"Hãy ghi nhớ:「ずにはおかない」nhấn mạnh vào tác động tất yếu/quyết tâm,「ずにはすまない」hướng vào áp lực đạo lý/trách nhiệm cá nhân, còn「ないわけにはいかない」chỉ là sự bắt buộc thông thường do hoàn cảnh khách quan."}],116:[{pattern:"〜を禁[きん]じ得[え]ない",meaning:"Không nén nổi/không kìm được (cảm xúc bộc phát mạnh) — văn viết trang trọng",priority:"core",explanation:'Mẫu câu này diễn tả ý nghĩa "không thể kìm nén được, không ngăn được cảm xúc mãnh liệt bộc phát" trước một sự tình hoặc sự việc cụ thể. Về cách dùng, mẫu chỉ kết hợp trực tiếp với các danh từ biểu thị tâm trạng, cảm xúc như 怒り (phẫn nộ), 悲しみ (đau buồn), 同情 (cảm thương), 疑問 (nghi vấn)... Đây là cách diễn đạt trang trọng thuộc phong cách văn viết, thường xuất hiện trong xã luận, báo chí, phê bình hoặc bài phát biểu bày tỏ thái độ, quan điểm sâu sắc.',examples:[{sentence:"相次ぐ企業の不正会計問題に対して、社会全体が強い憤りを禁じ得ない。",translation:"Trước hàng loạt vụ bê bối gian lận kế toán của doanh nghiệp, toàn xã hội không thể kìm nén được sự phẫn nộ gay gắt."},{sentence:"被災地の過酷な現状を目の当たりにして、支援に訪れた人々は涙を禁じ得なかった。",translation:"Tận mắt chứng kiến hiện trạng khắc nghiệt tại vùng thiên tai, những người đến cứu trợ đã không thể kìm được nước mắt."}],dialogue:{title:"Bàn về chính sách mới",lines:[{speaker:"A",text:"十分な説明のないまま突然発表された方針に、関係者の間でも困惑を禁じ得ない状況です。",translation:"Trước phương châm bất ngờ được công bố mà không có giải thích thỏa đáng, nội bộ những người liên quan cũng không kìm nổi sự bối rối hoang mang."},{speaker:"B",text:"そうですね。現場への負担も大きいですし、納得できない人が多いのも無理はありません。",translation:"Đúng vậy. Gánh nặng lên thực tế công việc rất lớn, nên nhiều người không thể đồng tình cũng là điều dễ hiểu."},{speaker:"A",text:"来週の説明会で、経営陣がどういった具体的な対応策を示すのか注目したいところです。",translation:"Chúng ta cần chú ý xem ban lãnh đạo sẽ đưa ra biện pháp ứng phó cụ thể nào trong buổi giải trình tuần tới."}]},commonMistake:{wrong:"彼の身勝手な振る舞いを見て、私は怒ることを禁じ得なかった。",correct:"彼の身勝手な振る舞いを見て、私は怒りを禁じ得なかった。",why:"Mẫu 「〜を禁じ得ない」 chỉ kết hợp trực tiếp với danh từ biểu thị cảm xúc (như 怒り, 涙) chứ không kết hợp với dạng danh từ hóa của động từ (như 怒ること)."},note:"Khác với các mẫu quen thuộc như 「〜てたまらない」 hay 「〜て仕方がない」 dùng nhiều trong hội thoại đời thường, 「〜を禁じ得ない」 thuộc phong cách văn viết trang trọng và mang tính bình luận khách quan, sâu sắc."},{pattern:"〜に堪[た]えない①（見[み]るに堪[た]えない・読[よ]むに堪[た]えない）",meaning:"Không nỡ/không chịu nổi khi xem・đọc・nghe (vì phẩm chất quá kém, mang tính phê phán)",priority:"common",explanation:"Mẫu câu này kết hợp với các động từ chỉ hành vi tri giác (chủ yếu là 見る, 聞く, 読む) để diễn tả ý 'quá tồi tệ hoặc quá đau lòng đến mức không thể chịu đựng nổi khi nhìn, nghe, đọc'. Thường được dùng để phê phán gay gắt chất lượng kém cỏi của một tác phẩm, phát ngôn hoặc bày tỏ sự xót xa trước một cảnh tượng bi thương. Cấu trúc mang tính văn viết trang trọng và chỉ giới hạn đi cùng một số ít động từ nhất định.",examples:[{sentence:"彼の書いた論文は誤字脱字や論理の破綻が多く、とても読むに堪えない。",translation:"Luận văn do anh ấy viết có quá nhiều lỗi chính tả và mâu thuẫn logic, thực sự không nỡ đọc nổi."},{sentence:"期待されていた新作映画だったが、演出も演技もひどすぎて最後まで見るに堪えなかった。",translation:"Bộ phim mới dù rất được kỳ vọng nhưng dàn dựng và diễn xuất quá tệ hại, đến mức không thể xem nổi đến hết."}],dialogue:{title:"Nhận xét buổi biểu diễn",lines:[{speaker:"A",text:"昨日の新人アイドルの歌、音程が外れすぎていて正直聞くに堪えなかったよ。",translation:"Màn hát của idol tân binh hôm qua bị lệch tông quá nhiều, nói thật là không nỡ nghe nổi."},{speaker:"B",text:"えっ、そこまでひどかったの？楽しみに録画しておいたのに。",translation:"Hả, tệ đến mức ấy cơ à? Thế mà tớ còn hào hứng ghi hình lại nữa."},{speaker:"A",text:"うん、わざわざ見直すほどのクオリティじゃないから、期待しないほうがいいよ。",translation:"Ừ, chất lượng không đáng để cất công xem lại đâu, cậu đừng kỳ vọng quá."}]},commonMistake:{wrong:"この部屋はエアコンが壊れていて、この暑さに堪えない。",correct:"この部屋はエアコンが壊れていて、この暑さに耐えられない。",why:"「〜に堪えない」ở nghĩa này chỉ đi với động từ tri giác (見る、聞く、読む) để chê bai chất lượng hoặc xót xa trước sự việc, không dùng để diễn tả sự chịu đựng áp lực vật lý hay thời tiết."},note:"Cần phân biệt với nghĩa ②「Danh từ cảm xúc ＋ に堪えない」(như 感謝に堪えない, 遺憾に堪えない) mang sắc thái trang trọng là 'vô cùng / khôn xiết'."},{pattern:"〜に堪[た]えない②（感謝[かんしゃ]の念[ねん]に堪[た]えない・感激[かんげき]の念[ねん]に堪[た]えない）",meaning:"Tràn đầy/không kìm được (cảm xúc TÍCH CỰC trang trọng: biết ơn, cảm động, khâm phục)",priority:"common",explanation:"Mẫu ngữ pháp này dùng để biểu đạt cảm xúc dâng trào mãnh liệt đến mức không thể kìm nén được (vô cùng biết ơn, cảm kích, khâm phục). Ngữ pháp thường kết hợp chặt chẽ với một số danh từ chỉ tâm thái trang trọng, phổ biến nhất ở dạng 「感謝の念に堪えない」, 「感激の念に堪えない」 hoặc 「敬服の念に堪えない」. Đây là cách diễn đạt có tính nghi lễ và trang trọng cao, thường xuất hiện trong các bài phát biểu, diễn văn, thư cảm ơn hoặc văn bản chính thức.",examples:[{sentence:"長年にわたり多大なるご支援をいただいた皆様には、感謝の念に堪えない。",translation:"Đối với tất cả quý vị đã hết lòng ủng hộ chúng tôi trong suốt nhiều năm qua, tôi vô cùng biết ơn không sao kể xiết."},{sentence:"被災地で不眠不休で救援活動を続けるボランティアの方々の姿には、敬服の念に堪えない。",translation:"Chứng kiến hình ảnh các tình nguyện viên không quản ngày đêm cứu trợ tại vùng thiên tai, tôi cảm phục khôn cùng."}],dialogue:{title:"Tổng kết dự án",lines:[{speaker:"A",text:"先輩方のご指導のおかげで大型案件が無事に成約し、感謝の念に堪えない思いです。",translation:"Nhờ sự hướng dẫn tận tình của các tiền bối mà hợp đồng lớn đã được ký kết thành công, em cảm thấy biết ơn vô cùng."},{speaker:"B",text:"いや、最後まで粘り強く交渉を続けた君の努力の結果だよ。本当にお疲れ様。",translation:"Đâu có, đó là kết quả từ sự nỗ lực đàm phán kiên trì đến cùng của em đấy. Em vất vả rồi."},{speaker:"A",text:"そう言っていただけて励みになります。今後ともご指導よろしくお願いいたします。",translation:"Được anh động viên như vậy em rất có thêm động lực. Sau này vẫn mong nhận được sự chỉ dẫn của anh ạ."}]},commonMistake:{wrong:"友達から誕生日プレゼントをもらって、うれしさに堪えない。",correct:"恩師の温かいお心遣いに触れ、感謝の念に堪えない。",why:"Mẫu này chỉ kết hợp với các danh từ cảm xúc trang trọng, sâu sắc cố định (như 感謝の念, 感激の念, 敬服の念), tuyệt đối không kết hợp với cảm xúc đời thường hay tính từ như 嬉しい, 楽しい."},note:"Cần phân biệt với 〜に堪えない① (đi với động từ như 見る, 聞く mang nghĩa tiêu cực là 'không nỡ/không chịu nổi'), trong khi 〜に堪えない② chỉ đi với danh từ cảm xúc trang trọng và mang sắc thái tích cực là 'vô cùng/khôn xiết'."},{pattern:"〜に足[た]る（N／Vるに足[た]る＋N）",meaning:"Xứng đáng để/đủ tư cách để — biểu thị mức độ ĐẦY ĐỦ/XỨNG ĐÁNG, KHÔNG liên quan cảm xúc bộc phát",priority:"common",explanation:'Mẫu「〜に足る」dùng để diễn tả một sự vật, sự việc hoặc con người có đầy đủ giá trị, phẩm chất hoặc điều kiện để thực hiện một hành động nào đó (mang nghĩa "xứng đáng để...", "đủ tư cách/giá trị để..."). Cấu trúc này thường đi với động từ thể từ điển (Vる) hoặc danh từ (như 信頼, 評価, 推薦...) để bổ nghĩa cho danh từ phía sau, hoặc đứng cuối câu ở dạng khẳng định/phủ định (〜に足る / 〜に足らない). Đây là cách diễn đạt trang trọng mang tính văn viết, thường xuất hiện trong các bài bình luận, báo cáo, đánh giá học thuật hoặc môi trường công việc chuyên nghiệp.',examples:[{sentence:"この研究論文は長年の綿密な調査に基づいており、国際的な学術賞に推薦するに足る素晴らしい成果だ。",translation:"Luận văn nghiên cứu này dựa trên cuộc điều tra tỉ mỉ qua nhiều năm, là một thành quả tuyệt vời xứng đáng để tiến cử cho giải thưởng học thuật quốc tế."},{sentence:"今回提案された新規事業計画は、多額の予算を投資するに足る十分な市場性と将来性を備えている。",translation:"Kế hoạch kinh doanh mới được đề xuất lần này có đầy đủ tiềm năng thị trường và triển vọng xứng đáng để đầu tư một khoản ngân sách lớn."}],dialogue:{title:"Đánh giá ứng viên quản lý",lines:[{speaker:"A",text:"今度の大型プロジェクトの責任者候補ですが、佐藤さんはいかがでしょうか。",translation:"Về ứng viên cho vị trí phụ trách dự án lớn sắp tới, anh thấy anh Sato thế nào?"},{speaker:"B",text:"彼は実務経験も豊富でリーダーシップもあり、この重責を任せるに足る優秀な人材だと思いますよ。",translation:"Cậu ấy vừa có kinh nghiệm thực tế phong phú vừa có năng lực lãnh đạo, tôi nghĩ là một nhân sự xuất sắc xứng đáng để giao phó trọng trách này."},{speaker:"A",text:"分かりました。では、役員会への推薦リストに彼の名前を加えておきます。",translation:"Tôi hiểu rồi. Vậy tôi sẽ thêm tên cậu ấy vào danh sách tiến cử lên ban giám đốc."}]},commonMistake:{wrong:"彼は長年の実績があり、誰もが信頼したに足るリーダーだ。",correct:"彼は長年の実績があり、誰もが信頼するに足るリーダーだ。",why:"Mẫu ngữ pháp「〜に足る」chỉ kết hợp trực tiếp với động từ thể từ điển (Vる) hoặc danh từ, tuyệt đối không kết hợp với động từ thể quá khứ (Vた)."},note:"Cần chú ý dạng quán ngữ phủ định「取るに足らない」(tầm thường/không đáng nhắc tới), và tránh nhầm với「〜に堪えない」(biểu thị cảm xúc mãnh liệt hoặc không nỡ/không chịu nổi)."},{pattern:"使[つか]い分[わ]け：を禁[きん]じ得[え]ない ≠ に堪[た]えない①② ≠ に足[た]る（cf. てならない N2）",meaning:"Phân biệt cốt lõi: を禁じ得ない=cảm xúc bộc phát tức thời (danh từ cảm xúc) ≠ に堪えない①=phê phán chất lượng kém (sau động từ tri giác) ≠ に堪えない②=cảm xúc tích cực tràn đầy (danh từ cảm xúc tích cực) ≠ に足る=xứng đáng/đủ tư cách (không phải cảm xúc); khác てならない (N2, bài 88) — cảm giác chủ quan tự nhiên trào ra, đi sau tính từ/động từ thể thường, khẩu ngữ hơn nhiều",priority:"common",explanation:"「〜を禁じ得ない」dùng trong văn viết trang trọng khi một cảm xúc mạnh mẽ (phẫn nộ, đau xót, hoài nghi...) bộc phát dữ dội không thể kìm nén, luôn đi sau danh từ cảm xúc. Trong khi đó,「〜に堪えない」mang hai sắc thái: đi sau động từ tri giác (như 見る, 聞く) để phê phán điều gì quá tệ hại đến mức không chịu nổi, hoặc đi với danh từ trang trọng để bày tỏ cảm xúc biết ơn/vui mừng vô hạn. Trái lại,「〜に足る」không biểu thị cảm xúc dâng trào mà đánh giá sự vật/người đủ giá trị, tư cách hoặc xứng đáng để làm gì đó (khác với「〜てならない」ở N2 vốn là khẩu ngữ diễn tả cảm xúc/cảm giác chủ quan trào lên tự nhiên).",examples:[{sentence:"不正が発覚したにもかかわらず、平然と責任を逃れようとする幹部たちの態度には、強い憤りを禁じ得ない。",translation:"Tôi không thể nào kìm nén được sự phẫn nộ tột cùng trước thái độ thản nhiên trốn tránh trách nhiệm của các vị cán bộ dù sai phạm đã bị phơi bày."},{sentence:"彼女が提案した新規事業計画は、会社全体で予算を投じて本格的に検討するに足る優れた内容だ。",translation:"Kế hoạch kinh doanh mới mà cô ấy đề xuất có nội dung vô cùng xuất sắc, xứng đáng để toàn công ty đầu tư ngân sách xem xét kỹ lưỡng."}],dialogue:{title:"Đánh giá phim mới",lines:[{speaker:"A",text:"昨日公開された話題の映画、もうご覧になりましたか。",translation:"Cậu đã xem bộ phim đang gây sốt công chiếu hôm qua chưa?"},{speaker:"B",text:"ええ、でも脚本の粗が目立って聞くに堪えない台詞も多く、わざわざ映画館で観るに足る作品とは思えませんでした。",translation:"Xem rồi, nhưng kịch bản lộ quá nhiều hạt sạn và có nhiều câu thoại dở đến không nỡ nghe, tôi không nghĩ đây là tác phẩm đáng để cất công ra rạp xem."},{speaker:"A",text:"そうでしたか。ずっと期待して待っていただけに、残念な気持ちを禁じ得ませんね。",translation:"Vậy sao. Kỳ vọng và chờ đợi bấy lâu nay mà thế này thì đúng là không kìm được cảm giác thất vọng nhỉ."}]},commonMistake:{wrong:"事故現場の悲惨な状況は、あまりにショックで見るを禁じ得ない。",correct:"事故現場の悲惨な状況は、あまりにショックで見るに堪えない。",why:"Khi muốn diễn tả một sự việc quá đau lòng hoặc tồi tệ đến mức không nỡ nhìn/nghe (sau động từ tri giác như 見る, 聞く), bắt buộc phải dùng「〜に堪えない」thay vì「〜を禁じ得ない」(vốn chỉ kết hợp trực tiếp với danh từ cảm xúc)."},note:"Cần chú ý「〜を禁じ得ない」và「〜に堪えない」đều là mẫu văn viết/trang trọng cao độ, tuyệt đối không dùng cho các cảm giác sinh lý hay cảm xúc thường nhật (vốn dùng「〜てならない」)."}],117:[{pattern:"〜極[きわ]まりない（A-な語幹[ごかん]＋極まりない）",meaning:"Cực kỳ, vô cùng... (nhận xét/phê phán mạnh — nối sau gốc tính từ đuôi な, bỏ な)",priority:"core",explanation:'Mẫu câu dùng để biểu thị một trạng thái hoặc tính chất đã đạt đến mức độ tột cùng, không gì sánh bằng (mang nghĩa "hết sức...", "vô cùng..."). Cấu trúc này đi trực tiếp sau gốc tính từ đuôi な (bỏ な) và mang sắc thái văn viết trang trọng, cứng cáp. Trong thực tế, mẫu này chủ yếu được dùng để đưa ra nhận xét, đánh giá gay gắt hoặc phê phán mạnh mẽ các hành vi tiêu cực.',examples:[{sentence:"重要なプロジェクトの進行中に何の相談もなく勝手に仕様を変更するとは、無責任極まりない。",translation:"Tự ý thay đổi yêu cầu kỹ thuật mà không hề trao đổi gì trong lúc dự án quan trọng đang diễn ra thật là vô trách nhiệm cùng cực."},{sentence:"SNS上で根拠のない噂を拡散し、他人のプライバシーを暴くような行為は不快極まりない。",translation:"Hành vi lan truyền tin đồn vô căn cứ và phơi bày đời tư của người khác trên mạng xã hội là hết sức khó chịu."}],dialogue:{title:"Thái độ của nhân viên",lines:[{speaker:"A",text:"さっきの店員の対応、客に対してため口を使うなんて無礼極まりないと思わない？",translation:"Cậu có thấy cách ứng xử của nhân viên vừa rồi, nói trổng với khách hàng như thế là vô lễ hết sức không?"},{speaker:"B",text:"本当にそうだね。混雑していて忙しいのは分かるけど、あの態度はあんまりだよ。",translation:"Đúng thật đấy. Dẫu biết quán đông và đang bận rộn, nhưng thái độ như vậy quả là quá đáng."},{speaker:"A",text:"うん、せっかくの食事が台無しになって本当に不愉快だったよ。",translation:"Ừ, bữa ăn ngon lành bỗng dưng bị phá hỏng khiến tớ thấy khó chịu vô cùng."}]},commonMistake:{wrong:"締切直前になって連絡がつかなくなるのは、無責任な極まりない行為だ。",correct:"締切直前になって連絡がつかなくなるのは、無責任極まりない行為だ。",why:"Mẫu 「〜極まりない」 chỉ kết hợp trực tiếp với thân từ của tính từ đuôi な (bắt buộc phải bỏ 「な」 khi nối)."},note:"Cần lưu ý 「〜極まりない」 hầu như chỉ dùng cho các đánh giá tiêu cực; đối với cảm xúc vinh dự, biết ơn hay vui mừng tột bậc mang nghĩa tích cực, người ta thường dùng 「〜の至り」 hoặc 「〜の極み」."},{pattern:"〜の至[いた]り（N＋の至り）",meaning:"Thật là... tột bậc (khiêm tốn bày tỏ cảm xúc trước người khác — chỉ đi với nhóm danh từ hạn chế cố định)",priority:"common",explanation:'Mẫu「〜の至り」mang ý nghĩa "vô cùng...", "thật là... tột bậc", dùng để diễn tả cảm xúc hoặc tâm trạng của người nói đạt đến mức độ cao nhất. Đây là cách nói mang tính thành ngữ rất trang trọng, thường dùng trong các bài phát biểu, thư tín thương mại hoặc hoàn cảnh giao tiếp lễ nghi. Mẫu câu này chỉ kết hợp hạn chế với một số danh từ cố định thể hiện tâm trạng hay nguyên nhân như 光栄 (vinh dự), 恐縮 (áy náy/cảm kích), 汗顔 (xấu hổ), 若気 (bồng bột tuổi trẻ).',examples:[{sentence:"このような権威ある賞をいただき、身に余る光栄の至りに存じます。",translation:"Được nhận giải thưởng danh giá như thế này, tôi cảm thấy vô cùng vinh hạnh vượt quá sự xứng đáng của bản thân."},{sentence:"若気の至りとはいえ、あの時先輩に失礼な態度を取ってしまったことを深く反省しております。",translation:"Dẫu biết là do sự bồng bột của tuổi trẻ, tôi vẫn vô cùng hối hận và tự kiểm điểm sâu sắc vì lúc đó đã có thái độ thất lễ với tiền bối."}],dialogue:{title:"Tiệc mừng nhận chức",lines:[{speaker:"A",text:"田中先生、本日はご多忙の折、私の就任祝賀会にお越しいただき恐縮の至りです。",translation:"Thưa thầy Tanaka, hôm nay dù bận rộn thầy vẫn bớt chút thời gian đến dự tiệc mừng nhận chức của em, em vô cùng cảm kích và áy náy ạ."},{speaker:"B",text:"いやいや、君の晴れ舞台ですからね。今後のさらなるご活躍を期待していますよ。",translation:"Đâu có gì, đây là ngày vui trọng đại của em mà. Thầy rất kỳ vọng vào những thành công tiếp theo của em đấy."},{speaker:"A",text:"ありがとうございます。先生の温かいお言葉を胸に、誠心誠意励んでまいります。",translation:"Em xin chân thành cảm ơn thầy. Khắc ghi lời động viên ấm áp của thầy, em sẽ nỗ lực cống hiến hết mình ạ."}]},commonMistake:{wrong:"このたび第一志望の大学に合格でき、嬉しいの至りです。",correct:"このたび第一志望の大学に合格でき、喜びの極みです。",why:"「〜の至り」chỉ đi với một số danh từ thành ngữ cố định (như 光栄, 恐縮, 汗顔, 若気), không thể ghép tự do với tính từ hay từ cảm xúc thông thường như「嬉しい」; trường hợp muốn biểu thị cảm xúc cực hạn tự do nên dùng「〜の極み」."},note:"Khác với「〜の極み」(có thể kết hợp phong phú với nhiều danh từ trừu tượng như 贅沢, 疲労, 痛恨),「〜の至り」bị giới hạn trong các cụm cố định dùng để bày tỏ cảm xúc trang trọng, khiêm nhường trước người khác."},{pattern:"〜の極[きわ]み（N＋の極み）",meaning:"Tột cùng của... (miêu tả khách quan trạng thái/sự vật đạt đến cực điểm, không cần khiêm nhường)",priority:"common",explanation:"Mẫu ngữ pháp 「〜の極み」 kết hợp với danh từ để diễn tả một sự việc, trạng thái hay cảm xúc đã đạt đến mức độ đỉnh điểm, tột cùng. Đây là cách diễn đạt trang trọng trong văn viết, mang tính chất miêu tả khách quan mức độ cực hạn của sự vật hoặc sự việc chứ không mang tính khiêm nhường. Cấu trúc này thường đi kèm với một số danh từ trừu tượng thể hiện cảm xúc sâu sắc hoặc đánh giá cao độ như 痛恨 (đau xót/hối tiếc), 愚劣 (ngu ngốc), 栄華 (vinh hoa), 悲痛 (bi thương).",examples:[{sentence:"取引先との重要な契約を私の不注意で失ってしまい、痛恨の極みです。",translation:"Để mất hợp đồng quan trọng với đối tác chỉ vì sự bất cẩn của bản thân, đó thực sự là điều hối tiếc tột cùng."},{sentence:"かつて栄華の極みを誇った古代帝国も、今ではただの遺跡として残るのみだ。",translation:"Đế chế cổ đại từng một thời đứng trên đỉnh cao của sự phồn vinh tột bậc, nay cũng chỉ còn trơ lại những tàn tích."}],dialogue:{title:"Quyết định khởi nghiệp",lines:[{speaker:"A",text:"一流企業を辞めて起業するなんて、安定を捨てる愚劣の極みだと親に反対されたよ。",translation:"Bố mẹ phản đối và bảo tôi rằng việc từ chức ở công ty hàng đầu để khởi nghiệp là hành động ngu ngốc tột cùng khi vứt bỏ sự ổn định."},{speaker:"B",text:"親御さんは心配なんだよ。でも、自分の夢に果敢に挑戦するのは素晴らしいことだと思うよ。",translation:"Bố mẹ lo lắng cho cậu thôi mà. Nhưng tôi nghĩ dám dũng cảm thử thách với ước mơ của chính mình là một điều rất tuyệt vời."},{speaker:"A",text:"ありがとう。そう言ってもらえると、自分の決断に自信が持てるよ。",translation:"Cảm ơn cậu. Được cậu nói vậy giúp tôi thêm tự tin vào quyết định của mình."}]},commonMistake:{wrong:"このような名誉ある賞をいただき、感激の極みです。",correct:"このような名誉ある賞をいただき、感激の至りです。",why:"Khi bày tỏ sự cảm kích hoặc vinh dự mang tính chất lễ nghi, khiêm nhường của bản thân trước đối phương, người Nhật dùng 「〜の至り」 thay vì 「〜の極み」."},note:"Khác với 「〜の至り」 chuyên dùng cho cảm xúc mang tính lễ nghi, khiêm nhường cá nhân (như 光栄, 恐縮), 「〜の極み」 dùng để nhận định hoặc miêu tả khách quan trạng thái cực điểm của sự vật, hiện tượng (như 痛恨, 愚劣, 栄華)."},{pattern:"極[きわ]まりない ≠ の至[いた]り ≠ の極[きわ]み（＆ 限[かぎ]りだ・ことか, N2 第92課[だい92か]）",meaning:"Phân biệt: 極まりない (tính từ, phê phán mạnh) ≠ の至り (danh từ khiêm nhường cá nhân) ≠ の極み (danh từ, trạng thái khách quan) ≠ 限りだ／ことか (N2, cảm thán thông thường)",priority:"common",explanation:"「極まりない」kết hợp với tính từ (chủ yếu là tính từ đuôi な) để phê phán gay gắt hành vi tiêu cực hoặc nhấn mạnh sự nguy hiểm tột độ. Trong khi đó,「～の至り」đi kèm danh từ để bày tỏ cảm xúc cá nhân sâu sắc (như biết ơn, vinh dự, áy náy) trong các nghi lễ, diễn văn trang trọng mang tính khiêm nhường. Còn「～の極み」kết hợp với danh từ để miêu tả trạng thái đỉnh điểm mang tính khách quan, trừu tượng (như sự xa hoa, tột đỉnh nghệ thuật), khác với cảm thán thường ngày trực tiếp như「～限りだ」「～ことか」ở cấp độ N2.",examples:[{sentence:"締め切り直前になって突然担当者が連絡を断つとは、無責任極まりない。",translation:"Việc người phụ trách đột ngột cắt đứt liên lạc ngay trước hạn chót quả là vô trách nhiệm tột cùng."},{sentence:"満天の星空を眺めながら露天風呂に入るのは、まさに贅沢の極みだ。",translation:"Vừa ngâm mình trong suối nước nóng ngoài trời vừa ngắm bầu trời đầy sao quả là sự xa hoa tột đỉnh."}],dialogue:{title:"Cảm nghĩ sau buổi lễ",lines:[{speaker:"A",text:"本日の祝賀会で代表挨拶を務めさせていただき、感激の至りでした。",translation:"Được vinh dự thay mặt phát biểu tại buổi tiệc chúc mừng hôm nay, tôi cảm thấy vô cùng xúc động."},{speaker:"B",text:"素晴らしいスピーチでしたよ。会場全体が聞き入っていました。",translation:"Bài phát biểu rất tuyệt vời đấy ạ. Cả hội trường đều chăm chú lắng nghe."},{speaker:"A",text:"そう言っていただけると嬉しい限りです。今後ともよろしくお願いいたします。",translation:"Được anh khen như vậy tôi mừng khôn xiết. Kính mong tiếp tục nhận được sự giúp đỡ của anh từ nay về sau."}]},commonMistake:{wrong:"念願の第一志望校に合格できて、嬉しいの至りです。",correct:"念願の第一志望校に合格できて、嬉しい限りです。",why:"「～の至り」chỉ kết hợp với danh từ trang trọng diễn tả cảm xúc mang tính nghi thức (như 光栄, 恐縮), còn tính từ chỉ cảm xúc trực tiếp của bản thân phải dùng「～限りだ」."},note:"Cần nhớ:「極まりない」thiên về phê phán tiêu cực;「の至り」dùng mang tính khiêm nhường/nghi lễ cá nhân; còn「の極み」diễn đạt đỉnh điểm của một trạng thái khách quan (cả tích cực lẫn tiêu cực)."}],118:[{pattern:"〜んばかりに（せんばかりに）",meaning:"Như thể sắp… (miêu tả trạng thái/cảm xúc đang lên tới mức cực điểm, dù thực tế chưa xảy ra)",priority:"core",explanation:"Mẫu ngữ pháp này dùng để ví von một hành động hoặc trạng thái đạt đến mức cực điểm, như thể sắp sửa xảy ra ngay trước mắt (dù thực tế chưa xảy ra). Mẫu này thường mang sắc thái phóng đại cảm xúc, thái độ hoặc mức độ gay cấn qua góc nhìn khách quan của người quan sát. Động từ chia ở thể ない bỏ ない thêm 「んばかりに」, riêng 「する」 chuyển thành 「せんばかりに」.",examples:[{sentence:"彼女は飛び上がらんばかりに喜んで、合格通知を握りしめた。",translation:"Cô ấy vui mừng khôn xiết như thể sắp nhảy cẫng lên và nắm chặt lấy giấy báo đỗ."},{sentence:"彼は頭を床に擦り付けんばかりに深く下げて、誠心誠意謝罪した。",translation:"Anh ấy cúi gập người sâu đến mức như thể sắp áp sát trán xuống sàn để tạ lỗi hết sức thành tâm."}],dialogue:{title:"Cơn giận của trưởng phòng",lines:[{speaker:"A",text:"さっきの会議で、部長は机を叩かんばかりに激怒していたね。",translation:"Trong cuộc họp lúc nãy, trưởng phòng giận dữ tột cùng như thể sắp đập bàn đến nơi rồi nhỉ."},{speaker:"B",text:"ええ、あんなに取り乱した部長を見たのは初めてで、息が詰まりそうでした。",translation:"Vâng, đây là lần đầu tiên tôi thấy trưởng phòng mất bình tĩnh đến thế, cảm giác ngột ngạt nghẹt thở luôn."},{speaker:"A",text:"次のプレゼンは二度とミスが出ないよう、念入りにチェックし直そう。",translation:"Chúng ta hãy rà soát thật kỹ lại để buổi thuyết trình tới tuyệt đối không lặp lại sai sót nữa nhé."}]},commonMistake:{wrong:"彼は土下座しんばかりに何度も頭を下げて頼み込んできた。",correct:"彼は土下座せんばかりに何度も頭を下げて頼み込んできた。",why:"Động từ nhóm 3 「する」 khi đi với mẫu ngữ pháp cổ này bắt buộc phải biến đổi thành 「せんばかりに」, không chia nhầm thành 「しんばかりに」."},note:"Cần phân biệt với 「〜とばかりに」 (ra vẻ/như muốn nói rằng...) dùng để thể hiện thái độ thay cho lời nói, trong khi 「〜んばかりに」 thuần túy nhấn mạnh trạng thái/mức độ kề cận sắp bùng phát."},{pattern:"〜とばかりに",meaning:"Ra điều rằng…, như muốn nói… (hành động ngầm thể hiện một câu nói không thành lời)",priority:"common",explanation:"Mẫu 「〜とばかりに」 dùng để diễn tả một hành động hoặc cử chỉ thể hiện rõ thái độ như muốn truyền tải một câu nói, suy nghĩ cụ thể dù người đó không trực tiếp thốt ra thành lời. Vế trước thường là một câu trích dẫn ngắn, câu khẩu ngữ, mệnh lệnh hoặc thán từ (như 今だ, 待ってました...), còn vế sau là hành động cụ thể tương ứng với thái độ đó. Mẫu câu này chủ yếu dùng khi quan sát và miêu tả sinh động hành vi, thái độ của người khác (ngôi thứ ba).",examples:[{sentence:"上司が「誰か意見はあるか」と尋ねると、彼は待ってましたとばかりに手を挙げて発言した。",translation:'Khi cấp trên hỏi "Có ai có ý kiến gì không?", anh ấy liền giơ tay phát biểu ra điều như muốn nói "Tôi chờ câu này mãi rồi!".'},{sentence:"タイムセールの合図が鳴ると、客たちはここぞとばかりに特売コーナーへ押し寄せた。",translation:'Ngay khi có tín hiệu giờ giảm giá, khách hàng liền ùa tới khu hàng khuyến mãi như muốn bảo "Chính là lúc này rồi!".'}],dialogue:{title:"Thái độ của Tanaka",lines:[{speaker:"A",text:"さっきの会議で、田中さんは「私の話を聞け」とばかりに机を強く叩いたんだよ。",translation:'Trong cuộc họp ban nãy, anh Tanaka đã đập mạnh xuống bàn như muốn nói "Hãy nghe tôi nói đây này!" đấy.'},{speaker:"B",text:"ええっ、そんなにあからさまに不満をアピールしたんですか？",translation:"Hả, anh ấy thể hiện sự bất mãn lộ liễu đến mức đó sao?"},{speaker:"A",text:"そうなんだ、周りのみんなも言葉を失って部屋が一瞬で静まり返ったよ。",translation:"Ừ, mọi người xung quanh cũng câm nín khiến căn phòng bỗng chốc im bặt luôn."}]},commonMistake:{wrong:"私は「もう話したくない」とばかりに、彼の目の前でドアをバタンと閉めた。",correct:"彼は「もう話したくない」とばかりに、私の目の前でドアをバタンと閉めた。",why:"Mẫu 「〜とばかりに」 dùng để người nói quan sát và phỏng đoán thái độ ngầm của người khác (ngôi thứ 3), nên không dùng cho hành động có chủ ý của chính bản thân mình (ngôi thứ 1)."},note:'Cần phân biệt với 「〜んばかりに」 (chỉ mức độ hoặc trạng thái như sắp sửa xảy ra điều gì, đi với động từ thể ない bỏ ない), còn 「〜とばかりに」 nhấn mạnh hành động thay cho một lời thoại cụ thể ("như muốn nói rằng...").'},{pattern:"〜べからず（すべからず）",meaning:"Cấm…, không được… (văn phong cổ, thường ở CUỐI câu — biển báo/thông cáo/quy tắc)",priority:"common",explanation:'Mẫu 「〜べからず」 mang ý nghĩa là "cấm...", "không được làm...", bắt nguồn từ văn phong cổ để thể hiện sự cấm đoán mang tính trang nghiêm và tuyệt đối. Cấu trúc này hầu như luôn đứng ở cuối câu, chủ yếu xuất hiện trên các biển báo cấm, văn bản quy tắc, thông cáo công cộng hoặc các lời răn dạy cổ điển chứ không dùng để giao tiếp miệng thường ngày. Về hình thức nối, cấu trúc đi với động từ thể từ điển, riêng động từ nhóm 3 「する」 sẽ biến đổi đặc biệt thành 「すべからず」.',examples:[{sentence:"【注意】安全のため、許可なくこの機械に触れるべからず。",translation:"【Chú ý】Vì lý do an toàn, không được tự ý chạm vào máy móc này khi chưa có phép."},{sentence:"【規則】学生たる者、正当な理由なく授業を欠席すべからず。",translation:"【Quy tắc】Là học sinh, tuyệt đối không được vắng mặt trong tiết học nếu không có lý do chính đáng."}],dialogue:{title:"Đọc biển báo ở đền",lines:[{speaker:"A",text:"見て、あの古い立札に「境内の木を伐採すべからず」って書いてあるよ。",translation:'Nhìn kìa, trên tấm biển gỗ cũ kia có viết là "Cấm chặt phá cây cối trong khuôn viên đền" đấy.'},{speaker:"B",text:"本当だ、歴史を感じる表現だね。昔から大切に守られてきた鎮守の森なんだ。",translation:"Đúng thật, cách diễn đạt đậm chất lịch sử ghê. Đây là khu rừng linh thiêng được gìn giữ cẩn thận từ xưa mà."},{speaker:"A",text:"勝手に枝を一本折るだけでも怒られそうだね。",translation:"Thế này thì tự tiện bẻ dù chỉ một cành cây thôi chắc cũng bị phạt nặng mất."}]},commonMistake:{wrong:"【案内】試験中は携帯電話を使用するべからず。",correct:"【案内】試験中は携帯電話を使用すべからず。",why:"Với động từ nhóm 3 「する」 (hoặc danh động từ + する), dạng đúng theo quy tắc văn cổ bắt buộc phải là 「すべからず」 chứ không kết hợp thành 「するべからず」."},note:'Mẫu này còn có dạng bổ nghĩa danh từ là 「〜べからざる + N」 mang nghĩa "không được phép... / không thể..." (ví dụ: 許すべからざる行為 - hành vi không thể tha thứ).'},{pattern:"〜べからざる＋N",meaning:"(điều/vật) không thể/không được… (dạng bổ nghĩa danh từ, PHẢI đứng trước N; hay đi cùng 欠く = thiếu)",priority:"common",explanation:'「〜べからざる＋N」 là dạng bổ nghĩa cho danh từ (liên thể hình) của mẫu văn cổ 「〜べからず」, mang ý nghĩa "(điều/người/hành vi) không thể..." hoặc "không được phép...". Mẫu ngữ pháp này đứng liền trước một danh từ và thường đi với các động từ chỉ nhận thức, đạo đức như 許す (tha thứ), 欠く (thiếu), 疑う (nghi ngờ), 看過する (bỏ qua). Đây là lối diễn đạt văn viết cổ, cực kỳ trang trọng, thường dùng trong văn cảnh bình luận xã hội, đạo đức hoặc tuyên bố chính thức.',examples:[{sentence:"罪のない人々を巻き込むテロ行為は、いかなる理由があろうとも断じて許すべからざる悪行だ。",translation:"Hành vi khủng bố lôi kéo cả những người vô tội, dù có bất kỳ lý do gì đi nữa, tuyệt đối là tội ác không thể tha thứ."},{sentence:"彼の残した輝かしい研究実績は、学界全体にとって疑うべからざる事実として認められている。",translation:"Những thành tựu nghiên cứu rực rỡ mà ông để lại được công nhận là một sự thật không thể nghi ngờ đối với toàn bộ giới học thuật."}],dialogue:{title:"Bàn về vụ bê bối",lines:[{speaker:"A",text:"今回のデータ改ざんは、企業の信頼を根底から揺るがす看過すべからざる問題ですね。",translation:"Việc làm giả dữ liệu lần này là một vấn đề không thể xem nhẹ, làm lung lay tận gốc rễ uy tín của doanh nghiệp nhỉ."},{speaker:"B",text:"ええ、直ちに第三者委員会を立ち上げて、原因究明を急ぐ必要があります。",translation:"Vâng, chúng ta cần lập tức thành lập ban điều tra độc lập và khẩn trương làm rõ nguyên nhân."},{speaker:"A",text:"二度と同じ過ちを繰り返さないためにも、徹底的に責任を追及しましょう。",translation:"Để không bao giờ lặp lại sai lầm tương tự, chúng ta hãy truy cứu trách nhiệm đến cùng."}]},commonMistake:{wrong:"このような重大な不正行為は、社会的に決して許すべからざる。",correct:"このような重大な不正行為は、社会的に決して許すべからざる罪だ。",why:"「〜べからざる」 là dạng bổ nghĩa danh từ nên bắt buộc phải có một danh từ theo sau, không được dùng để kết thúc câu như vị ngữ."},note:"Cần phân biệt rõ 「〜べからざる＋N」 (định ngữ bổ nghĩa cho danh từ) với 「〜べからず」 (đứng ở cuối câu mang ý nghĩa cấm đoán hoặc răn đe trong văn bản trang trọng/cổ)."},{pattern:"使[つか]い分[わ]け：んばかりに ≠ とばかりに ≠ べからず／べからざる",meaning:"Phân biệt: んばかりに = tả MỨC ĐỘ trạng thái/cảm xúc cực đại (chưa xảy ra) ≠ とばかりに = HÀNH ĐỘNG ngầm nói lên một câu (đi kèm động tác cụ thể) ≠ べからず/べからざる = CẤM ĐOÁN/BẤT KHẢ THIẾU (văn cổ, không miêu tả trạng thái hay hành động ngầm)",priority:"common",explanation:'「〜んばかりに」dùng để miêu tả mức độ của trạng thái hay cảm xúc đạt đến đỉnh điểm, như thể sắp sửa xảy ra một sự việc (dù thực tế chưa xảy ra). Ngược lại,「〜とばかりに」dùng khi một người thực hiện hành động cụ thể để ngầm phát đi thông điệp "như muốn nói rằng..." mà không thốt ra thành lời. Trong khi đó,「〜べからず／べからざる」là dạng văn cổ mang tính cấm đoán nghiêm ngặt ("không được làm") hoặc bất khả ("không thể tha thứ/không thể thiếu"), hoàn toàn khác biệt về chức năng và ngữ cảnh sử dụng so với hai mẫu trên.',examples:[{sentence:"観[かん]客[きゃく]は 割[わ]れんばかりに 拍[はく]手[しゅ]を 送[おく]り、彼[かれ]の 素[す]晴[ば]らしい 演[えん]奏[そう]を 称[たた]えた。",translation:"Khán giả vỗ tay nồng nhiệt như muốn vỡ tung cả hội trường để tán thưởng màn biểu diễn tuyệt vời của anh ấy."},{sentence:"彼[かれ]は「チャンスだ」とばかりに、すばやく ボールを 奪[うば]って ゴールへ 走[はし]り出[だ]した。",translation:"Như muốn nói 'Cơ hội đây rồi!', anh ấy nhanh chóng cướp bóng và lao thẳng về phía khung thành."}],dialogue:{title:"Phản ứng trong cuộc họp",lines:[{speaker:"A",text:"部[ぶ]長[ちょう]の 提[てい]案[あん]に、山[やま]田[だ]さんは「賛[さん]成[せい]できない」とばかりに 首[くび]を 横[よこ]に 振[ふ]っていたね。",translation:"Trước đề xuất của trưởng phòng, anh Yamada lắc đầu nguầy nguậy như muốn nói rằng 'Tôi không thể tán thành' nhỉ."},{speaker:"B",text:"ええ、彼[かれ]は 怒[いか]りで 爆[ばく]発[はつ]せんばかりに 顔[かお]を 真[ま]っ赤[か]にしていましたね。",translation:"Vâng, mặt anh ấy đỏ bừng lên như thể sắp nổ tung vì tức giận vậy."},{speaker:"A",text:"そうですね。お互[たが]い 言[い]い分[ぶん]はあるにせよ、あの 険[けん]悪[あく]な 雰[ふん]囲[い]気[き]には ひやひやしました。",translation:"Đúng vậy. Dù đôi bên đều có lý lẽ riêng, nhưng bầu không khí căng thẳng đó khiến tôi thót tim."}]},commonMistake:{wrong:"彼[かれ]は「私[わたし]には 関[かん]係[けい]ない」んばかりに 肩[かた]を すくめた。",correct:"彼[かれ]は「私[わたし]には 関[かん]係[けい]ない」とばかりに 肩[かた]を すくめた。",why:"Khi muốn diễn đạt thái độ/hành động ngầm thể hiện một phát ngôn hoặc suy nghĩ cụ thể (đi kèm nội dung trích dẫn), phải dùng「〜とばかりに」chứ không dùng「〜んばかりに」(chỉ dùng tả mức độ trạng thái đạt đến đỉnh điểm)."},note:"「〜べからず」chỉ dùng cho biển báo cấm đoán tuyệt đối trong văn viết trang trọng, trong khi dạng「〜べからざる + N」dùng như tính từ bổ nghĩa mang nghĩa 'không thể...' (ví dụ: 許すべからざる 行為: hành vi không thể tha thứ)."}],119:[{pattern:"～をきっかけに／をきっかけとして",meaning:"Lấy ~ làm dịp, nhân cơ hội ~, được khởi phát từ",priority:"core",explanation:"Mẫu ngữ pháp này dùng để diễn tả việc lấy một sự kiện, biến cố hoặc cơ hội nào đó làm duyên cớ hay bước ngoặt để bắt đầu một hành vi mới, hoặc tạo ra sự thay đổi trong cuộc sống. Vế trước là sự việc mang tính chất khơi nguồn, vế sau diễn tả hành động mới phát sinh hoặc sự chuyển biến rõ rệt tiếp nối từ cơ hội đó. Mẫu câu này không dùng cho các hành động sinh hoạt lặp đi lặp lại thường ngày mà hướng tới những thay đổi mang tính bước ngoặt hoặc khởi đầu mới.",examples:[{sentence:"日本のアニメを見たことをきっかけに、日本語の勉強を始めました。",translation:"Nhân dịp xem phim hoạt hình Nhật Bản, tôi đã bắt đầu học tiếng Nhật."},{sentence:"大学時代の留学をきっかけとして、将来は海外で働きたいという夢を持つようになった。",translation:"Lấy chuyến du học thời đại học làm bước ngoặt, tôi bắt đầu ấp ủ ước mơ sau này sẽ làm việc ở nước ngoài."}],dialogue:{title:"Bắt đầu tập thể dục",lines:[{speaker:"A",text:"最近ジムに通い始めたそうですね。何か理由があるんですか。",translation:"Nghe nói dạo này cậu bắt đầu đi tập gym à? Có lý do gì đặc biệt không?"},{speaker:"B",text:"先月の健康診断をきっかけに、運動不足を解消しようと思ったんです。",translation:"Nhân đợt khám sức khỏe tháng trước, tớ đã quyết định phải khắc phục tình trạng thiếu vận động đấy."},{speaker:"A",text:"それは素晴らしいですね。私も見習わなくては。",translation:"Tuyệt quá nhỉ. Chắc tớ cũng phải học tập cậu thôi."}]},commonMistake:{wrong:"日本のアニメを見るをきっかけに、日本語の勉強を始めた。",correct:"日本のアニメを見たことをきっかけに、日本語の勉強を始めた。",why:"Khi kết hợp với động từ, bắt buộc phải danh từ hóa động từ bằng 「～こと」 (hoặc 「～たこと」) chứ không được nối trực tiếp thể từ điển với 「をきっかけに」."},note:"「～をきっかけに」 dùng tự nhiên cho cả các sự kiện cá nhân đời thường lẫn trang trọng, trong khi mẫu tương đương 「～を契機に」 mang sắc thái văn viết trang trọng hơn và thường đi với các sự kiện có tầm ảnh hưởng lớn về mặt lịch sử hoặc xã hội."},{pattern:"～に加えて／に加え",meaning:"Ngoài ra, thêm vào đó, cộng thêm",priority:"common",explanation:'Mẫu ngữ pháp 「～に加えて／に加え」 mang ý nghĩa "ngoài ra, thêm vào đó, cộng thêm", dùng để bổ sung thêm một yếu tố, sự việc khác vào điều đã nêu trước đó. Cấu trúc này thường đi trực tiếp với Danh từ (hoặc V/A + ことに加えて) để diễn đạt các yếu tố cùng chiều tích cực hoặc cùng chiều tiêu cực dồn lại. Mẫu câu này mang sắc thái trang trọng, thường xuất hiện trong văn viết, tin tức hoặc các bài phát biểu, trình bày.',examples:[{sentence:"今月は残業の多さに加えて休日出勤まで重なり、心身ともに疲れ果ててしまった。",translation:"Tháng này, thêm vào việc tăng ca nhiều lại dồn cả đi làm ngày nghỉ nữa, nên tôi kiệt sức cả về thể xác lẫn tinh thần."},{sentence:"彼女は優れた英語力に加えてITや会計の専門知識も兼ね備えており、即戦力として期待されている。",translation:"Ngoài năng lực tiếng Anh xuất sắc, cô ấy còn sở hữu cả kiến thức chuyên môn về CNTT và kế toán, nên được kỳ vọng là nhân sự làm việc được ngay."}],dialogue:{title:"Tìm thuê căn hộ mới",lines:[{speaker:"A",text:"駅からの近さに加えて家賃も予算内なので、このマンションを契約しようと思います。",translation:"Ngoài việc gần ga, tiền thuê cũng nằm trong ngân sách nên tôi định ký hợp đồng thuê căn chung cư này."},{speaker:"B",text:"日当たりや夜間の周辺の治安はどうですか。長く住むならそこも重要ですよ。",translation:"Độ đón nắng và an ninh xung quanh vào ban đêm thế nào? Nếu ở lâu dài thì những điểm đó cũng quan trọng lắm đấy."},{speaker:"A",text:"昼も夜も見に行きましたが、とても静かで環境も抜群でした。",translation:"Tôi đã đi xem cả ban ngày lẫn ban đêm rồi, khu đó rất yên tĩnh và môi trường xung quanh cũng tuyệt vời lắm."}]},commonMistake:{wrong:"このレストランは料理が美味しいに加えて、サービスも行き届いている。",correct:"このレストランは料理が美味しいことに加えて、サービスも行き届いている。",why:"Mẫu 「～に加えて」 kết nối trực tiếp với Danh từ, nên khi muốn đi với Tính từ hoặc Động từ thì bắt buộc phải thêm 「こと」 để danh từ hóa vế trước."},note:"So với 「～だけでなく」 dùng linh hoạt trong giao tiếp hàng ngày, 「～に加えて」 mang tính trang trọng hơn và nhấn mạnh sự tích lũy, cộng hưởng của các yếu tố cùng tính chất (cùng tốt hoặc cùng xấu)."},{pattern:"ところで",meaning:"Nhân tiện, à này, mà này (chuyển chủ đề)",priority:"common",explanation:'「ところで」là liên từ đứng ở đầu câu, mang nghĩa "nhân tiện", "à này", "mà này", dùng để chủ động chuyển cuộc đối thoại sang một chủ đề hoàn toàn mới. Mẫu câu này thường được dùng khi câu chuyện trước đó đã kết thúc hoặc khi người nói chợt nhớ ra điều gì đó cần hỏi hay thông báo. Lưu ý không sử dụng mẫu này khi muốn tiếp tục hoặc bổ sung thông tin chi tiết cho cùng một đề tài đang thảo luận.',examples:[{sentence:"明日の会議の資料は準備できました。ところで、田中さんは何時にいらっしゃる予定ですか。",translation:"Tài liệu cho cuộc họp ngày mai đã chuẩn bị xong rồi. Mà này, anh Tanaka dự định mấy giờ sẽ đến vậy?"},{sentence:"旅行の写真は後でグループに送るね。ところで、来週の土曜日は何か予定ある？",translation:"Ảnh chuyến du lịch lát nữa mình sẽ gửi vào nhóm nhé. Nhân tiện thì thứ Bảy tuần sau cậu có kế hoạch gì chưa?"}],dialogue:{title:"Hỏi thăm kế hoạch",lines:[{speaker:"A",text:"昨日のプレゼン、無事に終わって本当によかったですね。",translation:"Buổi thuyết trình hôm qua kết thúc suôn sẻ thật là tốt quá nhỉ."},{speaker:"B",text:"本当にお疲れ様でした。これでやっとひと息つけますね。",translation:"Thực sự vất vả cho cậu rồi. Giờ thì cuối cùng cũng có thể thở phào nhẹ nhõm rồi."},{speaker:"A",text:"はい。ところで、来月の社員旅行の件ですが、参加されますか。",translation:"Vâng. À mà này, về chuyến du lịch công ty tháng sau, anh có tham gia không ạ?"}]},commonMistake:{wrong:"スーパーへ行くなら、ところでパンも買ってきてくれませんか。",correct:"スーパーへ行くなら、ついでにパンも買ってきてくれませんか。",why:'「ところで」chỉ dùng để chuyển hướng chủ đề cuộc trò chuyện chứ không dùng với nghĩa "nhân tiện/tiện thể làm hành động gì" như「ついでに」.'},note:"Cần phân biệt với「ちなみに」(dùng để bổ sung thông tin liên quan đến chủ đề đang nói) và tránh nhầm lẫn với cấu trúc ngữ pháp「〜たところで」(dẫu có... thì cũng vô ích)."},{pattern:"～にわたって／にわたる",meaning:"Trải dài, kéo dài (thời gian/phạm vi)",priority:"common",explanation:"Mẫu ngữ pháp「～にわたって／にわたる」được dùng để diễn tả một hành động, hiện tượng hoặc trạng thái trải rộng, kéo dài trên suốt một khoảng thời gian, phạm vi không gian hay quy mô lớn. Về mặt kết nối, mẫu đi sau danh từ chỉ thời gian/phạm vi và dùng「～にわたって」khi bổ nghĩa cho động từ/vị ngữ, hoặc đổi thành「～にわたる + Danh từ」khi bổ nghĩa trực tiếp cho danh từ phía sau. Mẫu câu mang sắc thái trang trọng, khách quan, thường xuất hiện trong văn viết, báo chí, bản tin thời sự hoặc các bài phát biểu.",examples:[{sentence:"台風の影響により、九州全域にわたって激しい雨と強風が続いている。",translation:"Do ảnh hưởng của bão, mưa to và gió giật mạnh đang tiếp tục kéo dài trên toàn bộ khu vực Kyushu."},{sentence:"5日間にわたる国際環境会議が、多くの共同宣言を採択して無事に閉幕した。",translation:"Hội nghị môi trường quốc tế kéo dài suốt 5 ngày đã bế mạc tốt đẹp sau khi thông qua nhiều tuyên bố chung."}],dialogue:{title:"Chuẩn bị sự kiện kỷ niệm",lines:[{speaker:"A",text:"来月の創立記念イベントは、1週間にわたって開催されるそうですね。",translation:"Nghe nói sự kiện kỷ niệm thành lập vào tháng sau sẽ được tổ chức kéo dài suốt 1 tuần đúng không anh?"},{speaker:"B",text:"ええ、社内だけでなく地域住民も参加できる大規模な企画を用意しています。",translation:"Đúng vậy, chúng tôi đang chuẩn bị một kế hoạch quy mô lớn để không chỉ người trong công ty mà cả người dân địa phương cũng có thể tham gia."},{speaker:"A",text:"長期にわたるビッグイベントですから、体調管理に気をつけて成功させましょう。",translation:"Vì là sự kiện lớn kéo dài ngày nên chúng ta hãy chú ý giữ gìn sức khỏe để tổ chức thành công nhé."}]},commonMistake:{wrong:"昨日は駅のカフェで友達を30分にわたって待ちました。",correct:"昨日は駅のカフェで友達を30分間待ちました。",why:"「～にわたって」 mang sắc thái quy mô lớn hoặc khoảng thời gian dài đáng kể, không dùng cho khoảng thời gian ngắn trong sinh hoạt thường nhật của cá nhân."},note:"Cần lưu ý khi bổ nghĩa cho danh từ đứng sau phải đổi thành 「～にわたる + N」, và phân biệt với 「～にかけて」 vốn dùng để biểu thị phạm vi thời gian hoặc không gian áng chừng từ điểm A tới điểm B."},{pattern:"～をめぐって／をめぐる",meaning:"Xung quanh (vấn đề gây tranh cãi)",priority:"common",explanation:'Mẫu ngữ pháp này mang ý nghĩa "xung quanh / xoay quanh (vấn đề nào đó)", diễn tả tình trạng tranh luận, mâu thuẫn hoặc cạnh tranh giữa nhiều bên về một chủ đề cụ thể. Vế trước luôn là danh từ chỉ vấn đề hoặc sự việc gây chú ý/tranh cãi, còn vế sau đi kèm với các động từ chỉ sự đối lập, tranh cãi, thảo luận như 議論する, 対立する, 争う. Dạng 「～をめぐる + N」 được sử dụng khi cần bổ nghĩa trực tiếp cho danh từ đứng phía sau. Mẫu câu này mang sắc thái trang trọng, thường xuất hiện nhiều trong tin tức thời sự, báo chí hoặc văn bản học thuật.',examples:[{sentence:"親の遺産相続をめぐって、兄弟の間で深刻な対立が生じている。",translation:"Xung quanh việc phân chia di sản của cha mẹ, giữa các anh em đang nảy sinh mâu thuẫn sâu sắc."},{sentence:"新しい消費税率の導入をめぐる議論は、国会で今も続いている。",translation:"Những cuộc thảo luận xoay quanh việc áp dụng mức thuế tiêu dùng mới hiện vẫn đang tiếp diễn tại Quốc hội."}],dialogue:{title:"Tranh cãi địa điểm nhà máy",lines:[{speaker:"A",text:"新工場の建設地をめぐって、役員会で意見が真っ二つに割れているらしいよ。",translation:"Nghe nói xoay quanh địa điểm xây dựng nhà máy mới, ý kiến trong ban giám đốc đang bị chia làm hai phe đối lập đấy."},{speaker:"B",text:"コスト重視派と環境配慮派で折り合いがつかないみたいですね。",translation:"Có vẻ như phe chú trọng chi phí và phe quan tâm môi trường vẫn chưa tìm được tiếng nói chung nhỉ."},{speaker:"A",text:"来週の臨時会議で決着をつけるそうだけど、まだまだ長引きそうだね。",translation:"Nghe bảo cuộc họp bất thường tuần tới sẽ đưa ra phán quyết, nhưng xem chừng còn kéo dài đấy."}]},commonMistake:{wrong:"私は将来の進路をめぐって、一人でずっと悩んでいます。",correct:"私は将来の進路について、一人でずっと悩んでいます。",why:"「～をめぐって」 bắt buộc phải có sự tham gia của nhiều người (nhiều phía) với các ý kiến hoặc hành động đối lập nhau, không dùng cho sự suy nghĩ hay trăn trở của một cá nhân đơn lẻ."},note:"Khác với 「～について」 chỉ đơn thuần giới thiệu đề tài, 「～をめぐって」 luôn gắn liền với bối cảnh có sự bất đồng ý kiến, tranh chấp hoặc xung đột quyền lợi giữa các bên."},{pattern:"～に反して／に反する",meaning:"Trái với, ngược lại với (kỳ vọng/quy định)",priority:"common",explanation:"Mẫu câu này biểu thị một sự việc, hành vi diễn ra hoàn toàn trái ngược với dự đoán, kỳ vọng, mong muốn ban đầu, hoặc vi phạm quy tắc, pháp luật. Danh từ đi trước thường là các từ chỉ suy nghĩ, dự báo (予想, 期待, 意図) hoặc nguyên tắc, quy định (規則, 法律, 方針). Khi đứng trước để bổ nghĩa cho danh từ, cấu trúc sẽ chuyển thành dạng 「〜に反する＋N」.",examples:[{sentence:"親の期待に反して、彼は大学に進学せず、料理人になる道を選んだ。",translation:"Trái với kỳ vọng của cha mẹ, anh ấy không học lên đại học mà chọn con đường trở thành đầu bếp."},{sentence:"いかなる理由があろうとも、社内規則に反する行為は決して許されない。",translation:"Dù với bất kỳ lý do gì đi nữa, hành vi trái với quy định nội bộ công ty tuyệt đối không được tha thứ."}],dialogue:{title:"Doanh số sản phẩm mới",lines:[{speaker:"A",text:"新商品の売れ行きはどうですか。事前のアンケートではかなり好評でしたよね。",translation:"Tình hình bán sản phẩm mới thế nào rồi? Khảo sát trước đó phản hồi khá tốt mà đúng không?"},{speaker:"B",text:"ええ、しかし開発チームの予想に反して、売上はかなり伸び悩んでいます。",translation:"Vâng, nhưng trái ngược với dự đoán của đội ngũ phát triển, doanh số đang bị chững lại khá nhiều."},{speaker:"A",text:"そうなんですか。早急にプロモーション方法を見直す必要がありますね。",translation:"Vậy sao. Chúng ta cần phải xem xét lại phương thức quảng bá càng sớm càng tốt."}]},commonMistake:{wrong:"兄が活発な性格であるのに反して、弟はおとなしい。",correct:"兄が活発な性格であるのに対して、弟はおとなしい。",why:"「〜に反して」chỉ dùng khi kết quả trái với dự đoán, mong đợi hoặc quy định, không dùng để so sánh đối chiếu đặc điểm tương phản giữa hai đối tượng như「〜に対して」."},note:"Phía sau「〜に反して」thường là kết quả bất ngờ hoặc tiêu cực ngoài dự tính; khi bổ nghĩa trực tiếp cho danh từ thì bắt buộc dùng「〜に反する＋N」chứ không dùng「〜に反しての＋N」."}],120:[{pattern:"～ことで",meaning:"Bằng cách ~ thì, thông qua việc ~",priority:"core",explanation:'Mẫu ngữ pháp 「～ことで」 dùng để diễn tả phương thức, cách thức hoặc nguyên nhân dẫn đến một kết quả hay sự thay đổi (mang nghĩa "bằng cách...", "thông qua việc...", "nhờ việc..."). Cấu trúc này thường kết hợp với động từ thể từ điển (V-ru) hoặc thể quá khứ (V-ta) để biến hành động đó thành một giải pháp hay lý do tạo ra kết quả ở vế sau. Vế sau thường chỉ kết quả đạt được, sự tiến bộ hoặc nhận thức mới. Mẫu câu này mang tính logic, thường được sử dụng phổ biến trong cả văn viết lẫn văn nói lịch sự khi trình bày giải pháp hoặc chia sẻ kinh nghiệm.',examples:[{sentence:"定期的に運動することで、日々のストレスを効果的に解消することができます。",translation:"Bằng cách tập thể dục định kỳ, bạn có thể giải tỏa căng thẳng thường ngày một cách hiệu quả."},{sentence:"先輩のアドバイスを真面目に聞いたことで、困難な課題を無事に解決できました。",translation:"Nhờ nghiêm túc lắng nghe lời khuyên của tiền bối, tôi đã giải quyết êm đẹp bài toán khó khăn."}],dialogue:{title:"Bí quyết phát âm chuẩn",lines:[{speaker:"A",text:"日本語の発音を早く上達させるには、どうすればいいでしょうか。",translation:"Làm thế nào để phát âm tiếng Nhật tiến bộ nhanh được nhỉ?"},{speaker:"B",text:"毎日シャドーイングを続けることで、自然なイントネーションが身につきますよ。",translation:"Bằng việc duy trì luyện shadowing mỗi ngày, bạn sẽ ngấm được ngữ điệu tự nhiên đấy."},{speaker:"A",text:"なるほど、早速今日の勉強から取り入れてみます！",translation:"Ra là vậy, tôi sẽ áp dụng vào việc học ngay từ hôm nay!"}]},commonMistake:{wrong:"インターネットのことで、世界中のニュースを簡単に調べられます。",correct:"インターネットを使うことで、世界中のニュースを簡単に調べられます。",why:"「～ことで」 phải đi sau một động từ biểu thị hành động cụ thể, không thể kết hợp trực tiếp sau danh từ chỉ công cụ/phương tiện theo dạng 「Nのことで」."},note:"So với 「～によって」 có thể đi trực tiếp với danh từ để chỉ phương tiện chung, 「～ことで」 luôn nhấn mạnh vào việc thực hiện một hành vi cụ thể (V-る/V-た) để mang lại kết quả."},{pattern:"～だからといって",meaning:"Dù nói rằng vì ~, không phải vì ~ mà",priority:"common",explanation:'Mẫu câu 「～だからといって」 mang ý nghĩa "dù nói là vì... nhưng không hẳn là..." hoặc "chỉ vì... mà...". Cấu trúc này dùng để nhấn mạnh rằng một lý do nào đó không thể là căn cứ tất yếu để dẫn đến kết quả hay hành vi ở vế sau. Vế sau của câu thường đi cùng các dạng phủ định một phần như 「～わけではない」「～とは限らない」 hoặc biểu hiện cấm đoán, khuyên nhủ như 「～てはいけない」. Mẫu này thường dùng để phản bác lại một nhận định phiến diện hoặc nhắc nhở ai đó không nên lấy một lý do để làm cớ.',examples:[{sentence:"有名だからといって、その店の料理がすべて美味しいわけではない。",translation:"Không phải cứ vì là quán nổi tiếng mà tất cả các món ăn ở đó đều ngon."},{sentence:"便利だからといって、ネットショッピングでお金を使いすぎてはいけない。",translation:"Chỉ vì tiện lợi mà không được tiêu xài quá nhiều tiền vào việc mua sắm qua mạng."}],dialogue:{title:"Lời khuyên cho người mới",lines:[{speaker:"A",text:"初心者だからといって、基本の練習をおろそかにしてはいけませんよ。",translation:"Dù là người mới bắt đầu thì cũng không được lơ là việc luyện tập cơ bản đâu nhé."},{speaker:"B",text:"すみません、早く上達したくて応用ばかりやっていました。",translation:"Em xin lỗi, vì muốn nhanh tiến bộ nên em toàn nhảy vào làm phần nâng cao."},{speaker:"A",text:"焦らずに、まずは土台をしっかり固めることが大切です。",translation:"Đừng nóng vội, quan trọng nhất là phải xây chắc nền tảng trước đã."}]},commonMistake:{wrong:"暇だからといって、一日中ゲームをした。",correct:"暇だからといって、一日中ゲームをしてはいけない。",why:"Vế sau của 「～だからといって」 không dùng cho câu kể hành động khẳng định thông thường, mà bắt buộc phải đi với biểu hiện phủ định hoặc khuyên bảo, cấm đoán."},note:"Nếu chỉ muốn nêu nguyên nhân - kết quả thông thường mang tính khẳng định thì dùng 「～から／～ので」 chứ không dùng 「～だからといって」."},{pattern:"～のあまり",meaning:"Vì quá (cảm xúc mạnh đến mức hành động cực đoan)",priority:"common",explanation:"Mẫu câu 「～のあまり」 dùng để diễn tả mức độ cảm xúc hoặc tình cảm (như vui mừng, lo lắng, tức giận, căng thẳng...) quá mãnh liệt dẫn đến một kết quả cực đoan, bất thường hoặc không kiểm soát được. Vế sau của câu thường là một hành động mang tính bột phát, vô thức hoặc một trạng thái tiêu cực ngoài dự tính. Cấu trúc này thường kết hợp phổ biến nhất với danh từ chỉ cảm xúc dạng 「N + のあまり」 và không đi kèm với các biểu hiện ý chí, mệnh lệnh hay rủ rê.",examples:[{sentence:"緊張のあまり、面接で自分の名前さえ言えなくなってしまった。",translation:"Vì quá căng thẳng, tôi thậm chí không thể nói được cả tên mình trong buổi phỏng vấn."},{sentence:"彼は怒りのあまり、持っていたグラスを床に叩きつけて割ってしまった。",translation:"Anh ấy vì quá tức giận đã ném mạnh chiếc ly đang cầm xuống sàn làm vỡ toang."}],dialogue:{title:"Buổi gặp mặt thần tượng",lines:[{speaker:"A",text:"昨日、憧れの歌手に会えた時、感激のあまり言葉が出なかったよ。",translation:"Hôm qua lúc gặp được ca sĩ mà mình hâm mộ, vì quá xúc động mà tớ không nói nên lời luôn."},{speaker:"B",text:"本当によかったね！ずっと前から大ファンだったもんね。",translation:"Thế thì tuyệt quá rồi còn gì! Cậu là người hâm mộ cuồng nhiệt của họ từ lâu lắm rồi mà."},{speaker:"A",text:"うん、サインをもらった瞬間は夢かと思って手が震えたよ。",translation:"Ừ, khoảnh khắc nhận được chữ ký tớ còn tưởng là mơ nên run cả tay đấy."}]},commonMistake:{wrong:"発表の時、恥ずかしいのあまり顔が真っ赤になった。",correct:"発表の時、恥ずかしさのあまり顔が真っ赤になった。",why:"Khi đi cùng tính từ đuôi い, phải đổi tính từ thành danh từ cảm xúc bằng cách bỏ 「い」 thêm 「さ」 (恥ずかしさのあまり), không dùng trực tiếp 「い-adj + のあまり」."},note:"Vế sau của 「～のあまり」 thường dẫn đến phản ứng vô thức hoặc kết quả tiêu cực, không được dùng để biểu thị nguyện vọng, ý chí hay mệnh lệnh như ～たい, ～てください, ～よう."},{pattern:"～ばかりに",meaning:"Chỉ vì (nguyên nhân duy nhất dẫn đến hệ quả xấu)",priority:"common",explanation:'Mẫu ngữ pháp 「～ばかりに」 dùng để chỉ nguyên nhân, lý do duy nhất dẫn đến một kết quả xấu, tiêu cực hoặc đáng tiếc ngoài dự kiến. Cấu trúc này thường mang sắc thái hối hận, day dứt hoặc bất mãn của người nói theo kiểu "chỉ vì... mà lại thành ra nông nỗi này". Vế sau luôn đi với kết quả xấu, tuyệt đối không dùng với câu mang tính ý chí, nguyện vọng hay mệnh lệnh.',examples:[{sentence:"経験が浅いばかりに、商談で相手に主導権を握られてしまった。",translation:"Chỉ vì thiếu kinh nghiệm mà tôi đã bị đối tác nắm quyền chủ động trong cuộc đàm phán."},{sentence:"お金がないばかりに、ずっと行きたかった留学を諦めざるを得なかった。",translation:"Chỉ vì không có tiền mà tôi đành phải từ bỏ ước mơ đi du học bấy lâu nay."}],dialogue:{title:"Lỡ chuyến bay",lines:[{speaker:"A",text:"目覚ましをかけ忘れたばかりに、飛行機に乗り遅れてしまったよ。",translation:"Chỉ vì quên đặt báo thức mà tớ bị lỡ chuyến bay mất rồi."},{speaker:"B",text:"ええっ、それは災難だったね！それでチケットはどうしたの？",translation:"Hả, đen đủi thế! Thế vé máy bay xử lý sao rồi?"},{speaker:"A",text:"買い直しになって、余計なお金がかかっちゃった。",translation:"Tớ phải mua lại vé mới, tốn thêm một khoản tiền oan uổng."}]},commonMistake:{wrong:"毎日一生懸命勉強したばかりに、N1に合格することができた。",correct:"毎日一生懸命勉強したおかげで、N1に合格することができた。",why:"「～ばかりに」 chỉ đi với hệ quả xấu hoặc đáng tiếc, không được dùng cho kết quả tốt hay sự việc tích cực (trường hợp này phải dùng 「～おかげで」)."},note:"Cần lưu ý dạng biến thể 「～たいばかりに」 (chỉ vì muốn làm V mà làm điều quá mức/vất vả), khi đó vế sau thường là hành động có phần gượng ép hoặc hy sinh của chủ ngữ."}],121:[{pattern:"～たばかり",meaning:"Vừa mới làm xong, mới ~ được một lúc",priority:"core",explanation:"Mẫu ngữ pháp 「～たばかり」 dùng để diễn tả một hành động vừa mới xảy ra hoặc hoàn tất chưa lâu theo cảm nhận chủ quan của người nói. Cấu trúc kết hợp là động từ thể quá khứ: Vた + ばかり（だ／の／に／で）. Điểm đặc trưng là khoảng thời gian thực tế có thể là vừa xong tức thì hoặc đã trôi qua khá lâu (vài tuần, vài năm), miễn là người nói cảm thấy sự việc vẫn còn rất mới mẻ.",examples:[{sentence:"このスマホは先月買ったばかりなのに、もう壊れてしまった。",translation:"Chiếc điện thoại thông minh này tôi mới mua tháng trước thôi mà đã hỏng mất rồi."},{sentence:"彼はこの会社に入社したばかりで、まだ業務に慣れていない。",translation:"Anh ấy mới vào công ty này nên vẫn chưa quen với công việc."}],dialogue:{title:"Chiếc máy tính mới",lines:[{speaker:"A",text:"新しいパソコン、使い心地はどう？",translation:"Chiếc máy tính mới dùng thấy thế nào rồi?"},{speaker:"B",text:"昨日セットアップしたばかりだから、まだよく分からないんだ。",translation:"Tớ mới thiết lập hôm qua thôi nên vẫn chưa rõ lắm."},{speaker:"A",text:"そうなんだ。何か困ったことがあったら何でも聞いてね。",translation:"Thế à. Có khó khăn gì cứ hỏi tớ nhé."}]},commonMistake:{wrong:"私は1年前に日本へ来たところなので、まだ生活に慣れていません。",correct:"私は1年前に日本へ来たばかりなので、まだ生活に慣れていません。",why:"「～たところ」 chỉ dùng cho sự việc vừa mới hoàn thành tức thì về mặt thời gian khách quan, còn khoảng thời gian dài (như 1 năm trước) dựa trên cảm nhận chủ quan thì phải dùng 「～たばかり」."},note:"Khác với 「～たところ」 (chỉ dùng cho mốc thời gian vừa dứt tức thì), 「～たばかり」 nhấn mạnh vào tâm lý người nói nên có thể đi kèm các mốc thời gian dài như 先月 (tháng trước), 去年 (năm ngoái)."},{pattern:"～するところだ／しているところだ／したところだ",meaning:"Sắp làm / Đang làm / Vừa xong (thời điểm của hành động)",priority:"common",explanation:"Mẫu ngữ pháp này dùng để diễn đạt chính xác thời điểm của một hành động: sắp sửa bắt đầu (V辞書形 + ところだ), đang trong quá trình thực hiện (Vている + ところだ), hoặc vừa mới kết thúc tức thì (Vた形 + ところだ). Điểm mấu chốt là mẫu câu nhấn mạnh vào khoảnh khắc ngay trước, trong hoặc ngay sau khi hành động xảy ra. Do đó, câu thường đi kèm với các phó từ tương ứng như 「これから／今から」(sắp), 「今／ちょうど」(đang), 「たった今／今」(vừa mới).",examples:[{sentence:"これから部屋の掃除をするところだから、後で電話をかけ直すね。",translation:"Bây giờ tớ chuẩn bị dọn dẹp phòng đây, lát nữa tớ gọi lại cho nhé."},{sentence:"たった今、駅に到着したところだから、改札の前で待っていて。",translation:"Tớ vừa mới đến ga tức thì, cậu cứ đợi ở trước cửa soát vé nhé."}],dialogue:{title:"Hỏi thăm qua điện thoại",lines:[{speaker:"A",text:"もしもし、今話せる？",translation:"A lô, cậu nói chuyện bây giờ được không?"},{speaker:"B",text:"ごめん、今明日の発表の準備をしているところだから、30分後にかけ直してもいい？",translation:"Xin lỗi nhé, bây giờ tớ đang chuẩn bị cho bài thuyết trình ngày mai, 30 phút nữa tớ gọi lại được không?"},{speaker:"A",text:"了解！じゃあ、準備が終わったら連絡してね。",translation:"Được rồi! Vậy khi nào chuẩn bị xong thì liên lạc với tớ nhé."}]},commonMistake:{wrong:"3か月前に日本に来たところです。",correct:"3か月前に日本に来たばかりです。",why:"「～したところだ」 chỉ dùng cho hành động vừa mới hoàn thành trong khoảnh khắc tức thì (vừa xong vài phút), không dùng cho khoảng thời gian thực tế đã trôi qua lâu như 3 tháng (phải dùng 「～たばかりだ」)."},note:"Cần phân biệt 「～したところだ」(vừa xong tức thì theo mốc thời gian khách quan) với 「～たばかりだ」(vừa mới làm theo cảm nhận chủ quan của người nói, có thể dùng cho sự việc đã xảy ra vài tháng hoặc vài năm trước)."},{pattern:"～際（に）",meaning:"Khi, lúc (trang trọng, ngữ cảnh chính thức)",priority:"common",explanation:'「～際（に）」mang ý nghĩa là "khi", "vào lúc" hoặc "nhân dịp", dùng để xác định thời điểm xảy ra một sự việc hay hành động cụ thể. Cấu trúc này đi sau động từ thể từ điển, thể た hoặc danh từ kết hợp với trợ từ 「の」. Đây là cách diễn đạt trang trọng, lịch sự, thường xuất hiện trong các văn bản hướng dẫn, thông báo công cộng hoặc môi trường công việc kinh doanh thay cho 「～とき」.',examples:[{sentence:"館内をご利用の際は、他のお客様のご迷惑にならないよう静かにお過ごしください。",translation:"Khi sử dụng dịch vụ trong khuôn viên tòa nhà, xin quý khách vui lòng giữ trật tự để không làm phiền người khác."},{sentence:"パスポートを更新する際に、申請書とともに所定の顔写真の提出が必要です。",translation:"Khi làm thủ tục đổi hộ chiếu, bạn cần nộp kèm ảnh thẻ theo quy định cùng với đơn xin cấp đổi."}],dialogue:{title:"Thủ tục nhận phòng khách sạn",lines:[{speaker:"A",text:"チェックインの際には、こちらの用紙にお名前とご連絡先のご記入をお願いいたします。",translation:"Khi làm thủ tục nhận phòng, xin quý khách vui lòng điền họ tên và thông tin liên lạc vào mẫu giấy này ạ."},{speaker:"B",text:"分かりました。宿泊料金の支払いは今ここで済ませたほうがいいですか。",translation:"Tôi hiểu rồi. Tôi nên thanh toán tiền phòng luôn tại đây bây giờ phải không?"},{speaker:"A",text:"はい、当館は前払い制となっておりますので、その際にお部屋の鍵をお渡しいたします。",translation:"Vâng, vì khách sạn chúng tôi thu tiền trước nên lúc thanh toán xong, tôi sẽ giao chìa khóa phòng cho quý khách ạ."}]},commonMistake:{wrong:"今朝起きた際に、すぐに顔を洗って歯を磨きました。",correct:"今朝起きたとき、すぐに顔を洗って歯を磨きました。",why:"「～際（に）」mang sắc thái trang trọng nên không dùng cho các hành động sinh hoạt đời thường cá nhân lặp đi lặp lại mỗi ngày, trường hợp này phải dùng 「～とき」."},note:"Khác với 「～とき」, 「～際（に）」hầu như không kết hợp trực tiếp với tính từ đuôi い hay đuôi な để miêu tả trạng thái thông thường (không nói 「忙しい際」 hay 「暇な際」)."},{pattern:"～にあたって／にあたり",meaning:"Nhân dịp, khi tiến hành (một việc quan trọng)",priority:"common",explanation:"Mẫu câu diễn tả thời điểm bắt đầu hoặc trước khi tiến hành một sự kiện quan trọng, mang tính bước ngoặt hoặc nghi thức trang trọng. Cấu trúc này thường kết hợp với động từ thể từ điển (Vる) hoặc danh từ chỉ các sự kiện đặc biệt như khai trương, kết hôn, du học, ký kết hợp đồng. Vế sau thường thể hiện sự chuẩn bị, lời chào, lời cảm ơn hoặc tâm thế quyết tâm hướng tới tương lai với sắc thái trang trọng, lịch sự.",examples:[{sentence:"新工場の建設を開始するにあたって、周辺住民の皆様へ事前説明会を実施いたします。",translation:"Trước khi bắt đầu việc xây dựng nhà máy mới, chúng tôi sẽ tổ chức buổi giải thích trước cho toàn thể cư dân xung quanh."},{sentence:"日本への留学にあたり、多くの方々から温かいご支援と励ましをいただきました。",translation:"Nhân dịp sang Nhật du học, tôi đã nhận được rất nhiều sự hỗ trợ và động viên ấm áp từ mọi người."}],dialogue:{title:"Chuẩn bị khai trương quán",lines:[{speaker:"A",text:"来月の新店舗オープンにあたり、どのような記念イベントを企画しましょうか。",translation:"Nhân dịp khai trương cửa hàng mới vào tháng sau, chúng ta nên lên kế hoạch cho sự kiện kỷ niệm như thế nào nhỉ?"},{speaker:"B",text:"先着50名様にオリジナルグッズをプレゼントするのはどうでしょうか。",translation:"Tặng quà lưu niệm độc quyền cho 50 khách hàng đầu tiên thì thế nào ạ?"},{speaker:"A",text:"いいアイデアですね！では、さっそく具体的な準備を進めましょう。",translation:"Ý tưởng hay đấy! Vậy chúng ta hãy bắt tay vào chuẩn bị cụ thể ngay nhé."}]},commonMistake:{wrong:"寝るにあたって、歯を磨かなければならない。",correct:"寝る前に、歯を磨かなければならない。",why:"「～にあたって」chỉ dùng cho những sự kiện trọng đại, bước ngoặt hoặc mang tính nghi thức, không dùng cho các hoạt động sinh hoạt thường ngày lặp đi lặp lại."},note:"So với「～に際して」,「～にあたって」mang tính chủ động chuẩn bị và hướng tới tương lai nhiều hơn, đồng thời chỉ dùng cho các sự kiện tích cực hoặc trung tính, không dùng cho sự việc tiêu cực (như tai nạn, nhập viện, phá sản)."}],122:[{pattern:"～ていく（変化）",meaning:"Sẽ dần, tiếp tục ~ (thay đổi từ hiện tại về tương lai)",priority:"core",explanation:"Mẫu câu này dùng để diễn tả một trạng thái hoặc hiện tượng đang và sẽ tiếp tục thay đổi, phát triển từ hiện tại hướng tới tương lai. Cấu trúc thường đi kèm với các động từ chỉ sự biến đổi như 増える, 減る, 変わる, 暖かくなる,... Ngữ pháp này mang góc nhìn hướng về phía trước, thường xuất hiện trong các dự đoán, nhận định về xu hướng phát triển hoặc sự chuyển biến tự nhiên.",examples:[{sentence:"少子高齢化の影響で、今後この地域の人口はますます減っていくだろう。",translation:"Do ảnh hưởng của già hóa dân số và giảm tỷ lệ sinh, dân số khu vực này từ nay về sau có lẽ sẽ ngày càng giảm dần."},{sentence:"来週からは一段と寒くなり、冬の気配が強まっていく見込みです。",translation:"Dự báo từ tuần sau trời sẽ lạnh hơn một bậc và không khí mùa đông sẽ ngày càng rõ nét hơn."}],dialogue:{title:"Xu hướng thanh toán số",lines:[{speaker:"A",text:"最近、現金を使わないキャッシュレス決済のお店が増えてきたね。",translation:"Dạo này các cửa hàng thanh toán không tiền mặt đã tăng lên nhiều nhỉ."},{speaker:"B",text:"そうだね。今後はさらにデジタル化が進んで、財布を持たない生活が当たり前になっていくだろうね。",translation:"Đúng thế. Từ nay về sau số hóa sẽ còn phát triển hơn nữa và cuộc sống không cần mang ví có lẽ sẽ dần trở thành điều hiển nhiên."},{speaker:"A",text:"便利になるのは嬉しいけど、スマホの充電切れには気をつけないとね。",translation:"Tiện lợi thì thích thật đấy, nhưng phải cẩn thận không để điện thoại hết pin mới được."}]},commonMistake:{wrong:"これからの時代は、オンラインでの仕事がますます増えてきました。",correct:"これからの時代は、オンラインでの仕事がますます増えていくでしょう。",why:"Khi nói về sự thay đổi hướng tới tương lai (có dấu hiệu như これからの時代 - thời đại từ nay về sau), bắt buộc phải dùng 「〜ていく」 thay vì 「〜てくる」 (vốn chỉ sự thay đổi tích lũy từ quá khứ đến hiện tại)."},note:"Cần phân biệt rõ với 「〜てくる」: 「〜てくる」 diễn tả sự biến đổi diễn ra từ quá khứ đến mốc hiện tại, còn 「〜ていく」 diễn tả sự biến đổi xuất phát từ hiện tại và tiếp diễn về tương lai."},{pattern:"～つつある",meaning:"Đang trong quá trình (tiến triển dần dần)",priority:"common",explanation:"Mẫu câu 「～つつある」 diễn tả một sự việc, hiện tượng đang trong quá trình biến đổi dần dần theo một chiều hướng nhất định. Ngữ pháp này được kết hợp theo công thức: V (bỏ ます) + つつある, thường đi kèm các động từ chỉ sự thay đổi (như 変化する, 回復する, 増える, 悪化する). Đây là lối diễn đạt trang trọng mang tính văn viết, thường xuất hiện trong báo chí, thời sự hoặc các báo cáo chính thức.",examples:[{sentence:"景気は緩やかに回復しつつあるが、依然として課題は多い。",translation:"Nền kinh tế đang dần hồi phục một cách chậm rãi, nhưng vẫn còn nhiều vấn đề tồn đọng."},{sentence:"地球温暖化の影響により、各地で貴重な生態系が失われつつある。",translation:"Do ảnh hưởng của hiện tượng nóng lên toàn cầu, hệ sinh thái quý giá ở nhiều nơi đang dần mất đi."}],dialogue:{title:"Thời tiết chuyển mùa",lines:[{speaker:"A",text:"最近、朝晩はずいぶん涼しくなって、秋になりつつありますね。",translation:"Dạo này sáng tối trời mát mẻ hẳn ra, mùa thu đang dần tới rồi nhỉ."},{speaker:"B",text:"そうですね。山の木々も少しずつ色づき始めているようですよ。",translation:"Đúng vậy nhỉ. Cây cối trên núi dường như cũng đang bắt đầu chuyển màu dần rồi đấy."},{speaker:"A",text:"過ごしやすい季節になるのは嬉しいですが、体調を崩さないように気をつけましょう。",translation:"Bước vào mùa dễ chịu thế này thì vui thật, nhưng chúng ta hãy chú ý giữ gìn sức khỏe nhé."}]},commonMistake:{wrong:"今、図書館で日本語の試験のために勉強しつつある。",correct:"今、図書館で日本語の試験のために勉強している。",why:"「～つつある」chỉ dùng cho động từ biểu thị sự biến đổi, tiến triển khách quan, không dùng cho hành động có chủ ý đang diễn ra của con người."},note:"Khác với「～ている」dùng được cho mọi hành động đang tiếp diễn,「～つつある」mang sắc thái văn viết trang trọng và nhấn mạnh vào tiến trình thay đổi liên tục chưa kết thúc."},{pattern:"～てくる（変化）",meaning:"Đã dần, bắt đầu ~ (thay đổi đến hiện tại)",priority:"common",explanation:"Mẫu câu「～てくる」dùng để diễn tả một sự thay đổi hoặc trạng thái bắt đầu xuất hiện và phát triển dần từ quá khứ kéo dài đến hiện tại (hoặc hướng về thời điểm nói). Mẫu này thường kết hợp với các động từ chỉ sự biến đổi (như 変わる, 増える, 寒くなる...) và đi cùng các phó từ chỉ mức độ tăng dần như「だんだん」「少しずつ」「次第に」. Người nói sử dụng mẫu này khi muốn nhấn mạnh quá trình biến đổi đang tiến gần đến mình hoặc được bản thân trực tiếp cảm nhận rõ rệt.",examples:[{sentence:"秋が深まるにつれて、朝晩はだんだん寒くなってくる。",translation:"Khi mùa thu càng về sâu, buổi sáng và buổi tối trời dần trở nên lạnh hơn."},{sentence:"この薬を飲んでしばらく休めば、少しずつ痛みが治まってくる。",translation:"Nếu uống thuốc này rồi nghỉ ngơi một lát thì cơn đau sẽ dần dịu bớt đi."}],dialogue:{title:"Luyện tập tiếng Nhật",lines:[{speaker:"A",text:"最近、毎日シャドーイングをしているんだけど、なかなか上手に話せなくて。",translation:"Dạo này tớ ngày nào cũng luyện shadowing nhưng mãi vẫn chưa nói trôi chảy được."},{speaker:"B",text:"焦らなくていいよ。続けていれば、だんだん自然に言葉が出てくるようになるから。",translation:"Đừng vội. Cứ kiên trì tiếp tục thì dần dần lời nói sẽ tự nhiên bật ra thôi mà."},{speaker:"A",text:"そうだね、諦めずにコツコツ頑張ってみるよ。",translation:"Ừ nhỉ, tớ sẽ không bỏ cuộc mà cố gắng từng chút một."}]},commonMistake:{wrong:"日本に来てから3年が経ち、日本の生活にも慣れていった。",correct:"日本に来てから3年が経ち、日本の生活にも慣れてきた。",why:"Khi diễn tả sự thay đổi diễn ra từ một mốc thời gian trong quá khứ kéo dài đến hiện tại (thời điểm nói), bắt buộc phải dùng「～てきた」chứ không dùng「～ていった」."},note:"Phân biệt với「～ていく」(diễn tả sự thay đổi từ hiện tại tiếp diễn tới tương lai hoặc hướng ra xa người nói), còn「～てくる」nhấn mạnh sự thay đổi hướng về hiện tại hoặc tiếp cận người nói."},{pattern:"～ようになる",meaning:"Trở nên có thể, đã dần dần đạt được",priority:"common",explanation:"Mẫu ngữ pháp này dùng để diễn đạt sự biến đổi về năng lực, trạng thái hoặc thói quen qua một quá trình thời gian (từ 'không thể/không làm' trở thành 'có thể/bắt đầu làm'). Thường kết hợp với động từ thể khả năng, thể phủ định ない, hoặc động từ vô ý chí để thể hiện sự thay đổi dần dần, tự nhiên nhờ rèn luyện hoặc do hoàn cảnh tác động. Mẫu câu nhấn mạnh vào kết quả của sự chuyển biến trạng thái chứ không biểu thị hành động nhất thời.",examples:[{sentence:"日本に来てから、苦いゴーヤや納豆が食べられるようになりました。",translation:"Kể từ khi sang Nhật, tôi đã dần ăn được mướp đắng và món natto."},{sentence:"AI技術の発展によって、専門知識がなくても簡単にアプリが作れるようになってきている。",translation:"Nhờ sự phát triển của công nghệ AI, ngay cả khi không có kiến thức chuyên môn người ta cũng dần có thể tự tạo ứng dụng một cách dễ dàng."}],dialogue:{title:"Tiến bộ học tiếng Nhật",lines:[{speaker:"A",text:"最近、字幕がなくても日本語のアニメが少しずつ聞き取れるようになってきたよ。",translation:"Dạo gần đây tớ đã dần dần nghe hiểu được anime tiếng Nhật mà không cần phụ đề rồi đấy."},{speaker:"B",text:"すごいね！毎日シャドーイングを続けている成果が出たんだね。",translation:"Tuyệt thật đấy! Đó là thành quả của việc cậu kiên trì luyện shadowing mỗi ngày đấy."},{speaker:"A",text:"うん、もっと自然に会話できるようになりたいから、これからも頑張るよ。",translation:"Ừ, vì muốn có thể giao tiếp tự nhiên hơn nữa nên từ giờ tớ vẫn sẽ tiếp tục cố gắng."}]},commonMistake:{wrong:"毎日勉強したおかげで、日本語を上手に話すようになりました。",correct:"毎日勉強したおかげで、日本語が上手に話せるようになりました。",why:"Khi muốn diễn tả sự thay đổi về mặt năng lực ('trở nên có thể làm gì'), bắt buộc phải chia động từ sang thể khả năng (話せる) trước khi nối với ようになる thay vì dùng động từ nguyên mẫu có ý chí."},note:"Cần phân biệt với 「～ことにする／～ことになる」 (nhấn mạnh sự quyết định/lựa chọn hành vi), còn 「～ようになる」 nhấn mạnh vào sự biến chuyển tự nhiên theo thời gian của trạng thái hoặc năng lực."},{pattern:"～ようにする",meaning:"Cố gắng làm sao để, chú ý làm",priority:"common",explanation:"Mẫu câu 「～ようにする」 diễn tả sự nỗ lực, cố gắng thực hiện (hoặc không thực hiện) một hành vi nào đó như một mục tiêu hoặc thói quen cần chú ý. Cấu trúc này kết hợp với động từ thể từ điển (V辞書形) hoặc thể phủ định (Vない形) để thể hiện hành động có chủ ý của người nói. Dạng 「～ようにしている」 thường dùng để chỉ nỗ lực duy trì một thói quen tốt đều đặn trong cuộc sống. Ngoài ra, dạng 「～ようにしてください」 được dùng để nhắc nhở hoặc đưa ra lời khuyên đối phương một cách nhẹ nhàng, lịch sự.",examples:[{sentence:"日本語の会話力を高めるために、毎日少しでも声を出して練習するようにする。",translation:"Để nâng cao khả năng hội thoại tiếng Nhật, tôi sẽ cố gắng luyện tập phát âm mỗi ngày dù chỉ một chút."},{sentence:"仕事で同じミスを繰り返さないように、作業手順を必ずメモに残すようにする。",translation:"Để không lặp lại lỗi sai tương tự trong công việc, tôi sẽ chú ý luôn ghi chú lại quy trình làm việc."}],dialogue:{title:"Rèn luyện sức khỏe",lines:[{speaker:"A",text:"最近運動不足だから、これからはエレベーターを使わずに階段を使うようにするよ。",translation:"Dạo này tôi ít vận động quá nên từ giờ tôi sẽ cố gắng đi cầu thang bộ thay vì dùng thang máy."},{speaker:"B",text:"それは素晴らしい心がけだね。私も見習わなくちゃ。",translation:"Đó là ý thức tuyệt vời đấy. Tôi cũng phải học tập bạn mới được."},{speaker:"A",text:"無理のない範囲で、毎日少しずつ継続するようにするよ。",translation:"Tôi sẽ cố gắng duy trì từng chút một mỗi ngày trong khả năng của mình."}]},commonMistake:{wrong:"日本語を一生懸命練習したので、上手に話せるようにしました。",correct:"日本語を一生懸命練習したので、上手に話せるようになりました。",why:"「～ようにする」 biểu thị sự nỗ lực, cố gắng có chủ ý của bản thân, còn sự biến đổi về năng lực hoặc trạng thái theo thời gian phải dùng 「～ようになる」."},note:"Phân biệt với 「～ことにする」 (nhấn mạnh vào quyết định dứt khoát tại một thời điểm), còn 「～ようにする」 nhấn mạnh vào quá trình nỗ lực, rèn luyện thói quen hoặc chú ý làm điều gì đó."}],123:[{pattern:"～てばかりいる",meaning:"Chỉ làm mỗi việc ~, cứ mãi ~",priority:"core",explanation:"Mẫu ngữ pháp「～てばかりいる」được dùng để diễn tả một hành động lặp đi lặp lại liên tục, mang nghĩa chỉ làm mỗi việc đó mà bỏ bê những việc khác cần làm. Cấu trúc này đi sau động từ thể Te (V-て + ばかりいる) và thường thể hiện sự phê bình, chê trách hoặc bất mãn của người nói trước một thói quen xấu. Vì mang sắc thái phàn nàn và tiêu cực nên mẫu này tuyệt đối không dùng cho các hành động mang tính khen ngợi hay đánh giá tích cực.",examples:[{sentence:"彼は文句を言ってばかりいて、自分では何もしようとしない。",translation:"Anh ta cứ cằn nhằn phàn nàn suốt mà bản thân chẳng chịu làm gì cả."},{sentence:"休みの日だからといって、一日中ベッドで寝てばかりいると体に良くないよ。",translation:"Dù là ngày nghỉ nhưng cứ nằm ngủ suốt cả ngày trên giường thì không tốt cho sức khỏe đâu."}],dialogue:{title:"Chuẩn bị cho kỳ thi",lines:[{speaker:"A",text:"来週テストがあるのに、弟はスマホを見てばかりいて全然勉強しないのよ。",translation:"Tuần sau có bài kiểm tra rồi mà em trai tớ cứ dán mắt vào điện thoại suốt, chẳng chịu học hành gì cả."},{speaker:"B",text:"それは困ったね。ちゃんとお母さんから注意してもらったほうがいいんじゃない？",translation:"Thế thì gay nhỉ. Có khi nên nhờ mẹ nhắc nhở xem sao?"},{speaker:"A",text:"言っても「今からやる」と言い訳して、ちっとも聞かないんだよね。",translation:'Có bảo thì nó cũng viện cớ "tí nữa làm", chẳng thèm nghe gì cả.'}]},commonMistake:{wrong:"弟は毎日一生懸命本を読んでばかりいて感心した。",correct:"弟は毎日一生懸命本を読んでいて感心した。",why:"Mẫu 「～てばかりいる」 luôn mang sắc thái phàn nàn, chê trách nên không dùng để khen ngợi những hành vi tích cực, đáng tuyên dương."},note:"Cần phân biệt với 「Vる＋ばかりだ」 diễn tả xu hướng ngày càng diễn biến theo một chiều hướng xấu, còn 「Vて＋ばかりいる」 nhấn mạnh sự lặp lại của một hành động tiêu cực."},{pattern:"～一方だ",meaning:"Ngày càng ~, cứ ~ mãi (xu hướng tiếp tục tăng/giảm)",priority:"common",explanation:"Mẫu ngữ pháp này dùng để diễn tả một trạng thái hoặc xu hướng đang không ngừng tiếp diễn theo một chiều hướng nhất định (ngày càng tăng, giảm, xấu đi...). Mẫu chỉ kết hợp với các động từ biểu thị sự biến đổi như 増える, 減る, 悪化する, 進む... Trong đa số các trường hợp, mẫu mang sắc thái tiêu cực hoặc thể hiện sự lo ngại về tình hình đang diễn biến theo chiều hướng không mong muốn.",examples:[{sentence:"最近は仕事が忙しくなるにつれて、ストレスがたまる一方だ。",translation:"Dạo gần đây công việc càng bận rộn thì căng thẳng lại ngày càng tích tụ nhiều hơn."},{sentence:"少子化の影響で、この地域の子供の数は減る一方だ。",translation:"Do ảnh hưởng của tình trạng giảm tỷ lệ sinh, số lượng trẻ em ở khu vực này ngày càng giảm đi."}],dialogue:{title:"Suy giảm thị lực",lines:[{speaker:"A",text:"最近パソコンを使う時間が増えて、視力が落ちる一方だ。",translation:"Dạo này thời gian dùng máy tính tăng lên nên thị lực của tôi ngày càng giảm sút."},{speaker:"B",text:"私も同じですよ。目が疲れて本当に困りますね。",translation:"Tôi cũng vậy đấy. Mắt mỏi mệt thực sự phiền toái ghê."},{speaker:"A",text:"意識して画面を見る時間を減らさないとだめですね。",translation:"Phải có ý thức giảm bớt thời gian nhìn màn hình thôi chứ không thì gay."}]},commonMistake:{wrong:"地方では若者が都会へ出て行ってしまい、人口が減っている一方だ。",correct:"地方では若者が都会へ出て行ってしまい、人口は減る一方だ。",why:"Mẫu 「～一方だ」 chỉ kết hợp trực tiếp với động từ thể từ điển (V-る) biểu thị sự biến đổi, không kết hợp với thể đang tiếp diễn 「～ている」."},note:"So với mẫu 「～ばかりだ」 (hầu như chỉ dùng cho chiều hướng xấu), 「～一方だ」 cũng chủ yếu dùng cho biến chuyển tiêu cực nhưng đôi khi vẫn có thể dùng cho chiều hướng tích cực nếu ngữ cảnh thể hiện rõ sự thay đổi tiến triển."},{pattern:"～がちだ",meaning:"Hay bị, thường hay (xu hướng tiêu cực)",priority:"common",explanation:"Mẫu ngữ pháp này dùng để diễn đạt việc một hành động, trạng thái hoặc xu hướng nào đó thường hay diễn ra. Cấu trúc này hầu như luôn mang sắc thái tiêu cực, dùng cho những sự việc không tốt, không mong muốn hoặc thói quen xấu. Thường đi sau động từ thể ます (bỏ ます) hoặc danh từ để tạo thành kết cấu diễn tả khuynh hướng hay mắc phải.",examples:[{sentence:"パソコンを長時間使っていると、目が疲れがちだ。",translation:"Nếu sử dụng máy tính trong thời gian dài thì mắt thường hay bị mỏi."},{sentence:"忙しい時期は、食事を簡単に済ませて栄養が偏りがちだ。",translation:"Vào những thời điểm bận rộn, người ta thường hay ăn uống qua loa dẫn đến việc mất cân bằng dinh dưỡng."}],dialogue:{title:"Thói quen sinh hoạt",lines:[{speaker:"A",text:"最近、夜遅くまでスマホを見て夜更かしをしがちだよ。",translation:"Dạo này tớ thường hay thức khuya để bấm điện thoại đến tận đêm muộn."},{speaker:"B",text:"睡眠不足は体によくないから、寝る前は画面を見ないほうがいいよ。",translation:"Thiếu ngủ không tốt cho cơ thể đâu, trước khi ngủ cậu không nên nhìn màn hình thì hơn."},{speaker:"A",text:"そうだね。今日から早めに寝るように気をつけるよ。",translation:"Ừ nhỉ. Từ hôm nay tớ sẽ chú ý đi ngủ sớm hơn."}]},commonMistake:{wrong:"彼はいつも真面目に勉強しているので、テストでいい点を取りがちだ。",correct:"彼はいつも真面目に勉強しているので、テストでいい点を取ることが多い。",why:"Không dùng 「～がちだ」 cho những sự việc mang ý nghĩa tích cực hay kết quả tốt đẹp, thay vào đó nên dùng cách diễn đạt trung tính như 「～ことが多い」."},note:"Cần phân biệt với 「～気味（ぎみ）」 vốn chỉ dấu hiệu, cảm giác nhẹ ở hiện tại (như hơi sốt, hơi mệt), trong khi 「～がち」 nhấn mạnh tần suất thường xuyên xảy ra của một khuynh hướng tiêu cực."},{pattern:"～っぽい",meaning:"Có vẻ, hay, dễ (mang tính chất nào đó)",priority:"common",explanation:"Mẫu「～っぽい」dùng để diễn tả người hoặc sự vật có xu hướng, cảm giác hoặc mang đậm tính chất nào đó (như màu sắc, tính cách, trạng thái). Ngữ pháp này kết hợp với danh từ, tính từ đuôi い (bỏ い) hoặc động từ thể ます (bỏ ます). Đây là cách nói mang tính khẩu ngữ thân mật, thường mang sắc thái tiêu cực hoặc chê bai nhẹ nhàng. Khi đi cùng động từ, mẫu biểu thị xu hướng dễ hoặc hay làm một việc gì đó.",examples:[{sentence:"最近の彼は疲れがたまっているのか、少し怒りっぽくなっている。",translation:"Dạo gần đây chắc do mệt mỏi tích tụ nên anh ấy trở nên hơi dễ nổi nóng."},{sentence:"このスープは水っぽくて、あまり味がしない。",translation:"Món súp này loãng toẹt như nước, chẳng có vị gì mấy."}],dialogue:{title:"Mua sắm quần áo",lines:[{speaker:"A",text:"このシャツ、デザインは可愛いけど、生地がちょっと安っぽくない？",translation:"Chiếc áo này thiết kế thì dễ thương đấy, nhưng chất vải trông hơi rẻ tiền nhỉ?"},{speaker:"B",text:"うーん、確かに近くで見るとペラペラしてるね。",translation:"Ừm, đúng là nhìn gần thì thấy mỏng dính thật."},{speaker:"A",text:"じゃあ、別の店でもう少ししっかりしたやつを探そうか。",translation:"Thế thì mình sang cửa hàng khác tìm chiếc nào chất lượng hơn chút đi."}]},commonMistake:{wrong:"祖父は最近、大事なことを忘れるっぽくなってきた。",correct:"祖父は最近、大事なことを忘れっぽくなってきた。",why:"Khi kết hợp với động từ, phải chia về thể ます rồi bỏ ます (忘れ + っぽい) chứ không ghép trực tiếp với thể từ điển."},note:"Phân biệt với「～らしい」(đúng bản chất thực tế, thường mang nghĩa tích cực),「～っぽい」chỉ mang cảm giác bên ngoài và thường dùng với sắc thái tiêu cực hoặc khi đối tượng không thực sự là bản chất đó (ví dụ: 女っぽい dùng cho nam giới có nét nữ tính)."}],124:[{pattern:"～こそ",meaning:"Chính là, chỉ có (nhấn mạnh điều quan trọng nhất)",priority:"core",explanation:"Mẫu 「～こそ」 dùng để nhấn mạnh chính đối tượng, nguyên nhân hay thời điểm đó chứ tuyệt đối không phải cái nào khác. Mẫu này thường đi trực tiếp sau danh từ (N + こそ) hoặc sau liên từ chỉ lý do (～からこそ) nhằm khẳng định mạnh mẽ cảm xúc, lý do cốt lõi hoặc ý chí quyết tâm của người nói. Sắc thái câu mang tính dứt khoát, trang trọng, thường xuất hiện nhiều trong văn viết, phát biểu hoặc các câu chào hỏi xã giao hàng ngày.",examples:[{sentence:"今年こそ絶対にJLPT N1に合格してみせる。",translation:"Chính năm nay tôi nhất định sẽ thi đỗ JLPT N1 cho mà xem."},{sentence:"健康こそが人生において何よりも大切でかけがえのない財産だ。",translation:"Chính sức khỏe mới là tài sản quý giá và quan trọng hơn bất cứ thứ gì trong cuộc đời."}],dialogue:{title:"Hợp tác trong dự án",lines:[{speaker:"A",text:"いつも助けてくれてありがとう。田中さんのアドバイスがあったからこそ、発表がうまくいったよ。",translation:"Cảm ơn cậu vì lúc nào cũng giúp đỡ. Chính nhờ có lời khuyên của Tanaka mà bài thuyết trình mới thành công đấy."},{speaker:"B",text:"いや、それは山田さん自身が熱心に準備を重ねていたからだよ。",translation:"Không đâu, đó là do chính Yamada đã chuẩn bị hết sức tận tâm đấy chứ."},{speaker:"A",text:"そう言ってもらえると嬉しいよ。次もこの調子で頑張るね。",translation:"Cậu nói vậy làm mình vui lắm. Lần tới mình cũng sẽ cố gắng phát huy thế này."}]},commonMistake:{wrong:"彼だこそ、この困難なプロジェクトのリーダーにふさわしい。",correct:"彼こそ、この困難なプロジェクトのリーダーにふさわしい。",why:"「こそ」 gắn trực tiếp vào sau danh từ (N + こそ) chứ không kết hợp thành 「N + だこそ」 (chỉ có dạng 「N + だからこそ」 khi nhấn mạnh nguyên nhân)."},note:"Khác với 「だけ」(chỉ giới hạn phạm vi đơn thuần), 「こそ」 mang sắc thái cảm xúc mạnh mẽ hơn, dùng để nhấn mạnh sự tâm đắc, quyết tâm hoặc tính đặc biệt của đối tượng."},{pattern:"～だって",meaning:"Kể cả, dù là ~ cũng (nhấn mạnh trường hợp cực đoan)",priority:"common",explanation:'Mẫu ngữ pháp 「～だって」 đi sau danh từ hoặc từ để hỏi nhằm đưa ra một trường hợp điển hình hoặc cực đoan, mang ý nghĩa "kể cả, ngay cả, dù là... cũng...". Mẫu này tương đương với 「～でも / ～さえ」 nhưng mang sắc thái văn nói thân mật và đời thường hơn. Khi kết hợp với từ để hỏi (誰, どこ, いつ...), câu mang ý nghĩa khẳng định toàn diện như "bất cứ ai / bất cứ đâu / bất cứ khi nào".',examples:[{sentence:"プロの選手だって、大きなプレッシャーでミスをすることがある。",translation:"Kể cả vận động viên chuyên nghiệp cũng có lúc mắc sai lầm vì chịu áp lực lớn."},{sentence:"人間なんだから、誰だって失敗することはあるよ。",translation:"Đã là con người thì bất kỳ ai cũng có lúc mắc phải sai lầm thôi."}],dialogue:{title:"Thử thách món mì cay",lines:[{speaker:"A",text:"この激辛ラーメン、一口食べただけで汗が止まらないよ。",translation:"Món mì siêu cay này, mới ăn một miếng thôi mà mồ hôi tớ tuôn ra không ngừng rồi."},{speaker:"B",text:"辛いものが大好きな田中さんだって完食できなかったらしいから、無理しないでね。",translation:"Nghe nói ngay cả anh Tanaka vốn cực kỳ thích ăn cay cũng không ăn hết nổi, nên cậu đừng cố quá nhé."},{speaker:"A",text:"そうなんだ。じゃあ、残りは無理せずスープだけにしよう。",translation:"Thế à. Vậy thì phần còn lại tớ không cố nữa, chỉ húp chút nước rồi thôi."}]},commonMistake:{wrong:"忙しいだって、メールの返信くらいはできるはずだ。",correct:"忙しくたって、メールの返信くらいはできるはずだ。",why:'Khi muốn diễn đạt ý "Dù có bận...", tính từ đuôi -i phải biến đổi thành dạng 「～くたって」 chứ không gắn trực tiếp 「～い + だって」.'},note:"「～だって」 là cách nói mang đậm tính khẩu ngữ suồng sã, nên tránh dùng trong bài viết trang trọng, thư từ kinh doanh hoặc khi giao tiếp với người trên bằng kính ngữ."},{pattern:"～さえ（も）",meaning:"Thậm chí cả ~ (ngạc nhiên về điều cực đoan)",priority:"common",explanation:"Mẫu ngữ pháp này dùng để đưa ra một ví dụ mang tính cực đoan hoặc bất ngờ nhất, nhằm ngụ ý rằng đến điều khó tin như vậy còn xảy ra thì những điều bình thường khác là hiển nhiên. Thường mang sắc thái ngạc nhiên, cảm thán, thất vọng hoặc nhấn mạnh mức độ nghiêm trọng của sự việc. Vế sau của câu rất thường đi kèm với dạng phủ định để làm nổi bật sự thiếu sót hoặc bất khả thi.",examples:[{sentence:"昨日は仕事が忙しすぎて、昼ご飯を食べる時間さえなかった。",translation:"Hôm qua công việc quá bận rộn nên thậm chí đến thời gian ăn trưa tôi cũng không có."},{sentence:"この専門用語は、ベテランのエンジニアでさえも即座には答えられない難問だ。",translation:"Thuật ngữ chuyên môn này là câu hỏi khó đến mức thậm chí cả kỹ sư lâu năm cũng không thể trả lời ngay được."}],dialogue:{title:"Bị kiệt sức vì ốm",lines:[{speaker:"A",text:"昨日からの高熱で、ベッドから起き上がることさえできませんでした。",translation:"Vì sốt cao từ hôm qua nên thậm chí việc ngồi dậy khỏi giường tôi cũng không làm nổi."},{speaker:"B",text:"それは大変でしたね。病院にはもう行けましたか。",translation:"Thế thì vất vả quá. Bạn đã đi bệnh viện được chưa?"},{speaker:"A",text:"ええ、薬を飲んで少し落ち着きましたが、まだ食欲さえ湧きません。",translation:"Vâng, uống thuốc xong thì đỡ hơn chút rồi, nhưng thậm chí cảm giác thèm ăn vẫn chưa có lại."}]},commonMistake:{wrong:"疲れたでしょう。お茶さえ飲みませんか。",correct:"疲れたでしょう。お茶でも飲みませんか。",why:"Mẫu「～さえ」chỉ dùng để nhấn mạnh sự việc cực đoan gây ngạc nhiên, không dùng để đưa ra lời rủ rê hoặc gợi ý nhẹ nhàng như「～でも」."},note:"Khi gắn vào danh từ,「さえ」sẽ thay thế hoàn toàn cho trợ từ「が」「を」, nhưng lại đứng sau các trợ từ chỉ vị trí, phương tiện như「に」「で」「から」(ví dụ: 先生にさえ、子供でさえ)."},{pattern:"～だけでなく／のみならず",meaning:"Không chỉ ~ mà còn (mở rộng phạm vi)",priority:"common",explanation:'Mẫu câu này dùng để diễn đạt ý nghĩa "không chỉ A mà còn cả B", trong đó B là yếu tố được bổ sung thêm vào cùng phạm vi hoặc ở mức độ cao hơn. Trong khi 「～だけでなく」 được dùng rất phổ biến trong cả văn nói lẫn văn viết hằng ngày, thì 「～のみならず」 mang sắc thái trang trọng và dùng nhiều trong văn phong viết hoặc các bài phát biểu lịch sự. Vế sau thường đi kèm với các trợ từ mang tính mở rộng như 「も」、「まで」、「さえ」 để nhấn mạnh thông tin được thêm vào.',examples:[{sentence:"この新製品は国内市場のみならず、海外市場でも非常に高く評価されている。",translation:"Sản phẩm mới này không chỉ ở thị trường trong nước mà còn được đánh giá rất cao tại thị trường nước ngoài."},{sentence:"健康のためには、栄養バランスの良い食事を取るだけでなく、十分な睡眠を確保することも大切だ。",translation:"Để giữ gìn sức khỏe, không chỉ việc ăn uống cân bằng dinh dưỡng mà việc đảm bảo ngủ đủ giấc cũng rất quan trọng."}],dialogue:{title:"Quán ăn mới mở",lines:[{speaker:"A",text:"駅前に新しくできたレストラン、料理が美味しいだけでなく、値段もリーズナブルらしいよ。",translation:"Nghe nói nhà hàng mới mở trước ga không chỉ món ăn ngon mà giá cả còn rất hợp lý đấy."},{speaker:"B",text:"本当？雰囲気も良さそうだし、今度の週末に行ってみない？",translation:"Thật á? Không gian trông cũng đẹp nữa, cuối tuần này chúng mình cùng đi thử không?"},{speaker:"A",text:"いいね！予約が埋まる前に、さっそく席を取っておこう。",translation:"Được đấy! Trước khi kín chỗ thì mình đặt bàn ngay thôi."}]},commonMistake:{wrong:"このホテルは便利だけでなく、サービスも素晴らしい。",correct:"このホテルは便利なだけでなく、サービスも素晴らしい。",why:"Tính từ đuôi な khi kết hợp với 「だけでなく」 bắt buộc phải giữ 「な」 (hoặc chia thành 「である」), không được nối trực tiếp như danh từ."},note:"So với 「～だけでなく」 dùng linh hoạt trong đời sống hằng ngày, 「～のみならず」 là văn phong cứng, trang trọng hơn và thường xuất hiện trong báo chí, tin tức hoặc báo cáo kinh doanh."},{pattern:"～ばかりか／ばかりでなく",meaning:"Không chỉ ~ mà thậm chí còn (nhấn mạnh phạm vi vượt kỳ vọng)",priority:"common",explanation:'Mẫu ngữ pháp này mang ý nghĩa "không chỉ dừng lại ở A mà thậm chí còn B", dùng khi muốn nhấn mạnh sự việc ở vế sau phát triển vượt ngoài mức độ hoặc kỳ vọng thông thường. Vế sau thường đi kèm với các trợ từ nhấn mạnh như 「も」「まで」「さえ」 để làm nổi bật phạm vi hoặc mức độ gia tăng. Cấu trúc này thường mang sắc thái ngạc nhiên, cảm thán hoặc bức xúc của người nói, và vế sau không dùng với dạng câu mệnh lệnh, nhờ vả hay thể hiện ý chí.',examples:[{sentence:"このレストランは料理がまずいばかりか、店員の接客態度まで最悪だった。",translation:"Nhà hàng này không chỉ đồ ăn dở tệ mà đến cả thái độ phục vụ của nhân viên cũng tồi tệ hết mức."},{sentence:"彼女は英語ばかりでなく、フランス語や中国語も流暢に話すことができる。",translation:"Cô ấy không chỉ tiếng Anh mà còn có thể nói trôi chảy cả tiếng Pháp và tiếng Trung."}],dialogue:{title:"Đánh giá đồng nghiệp mới",lines:[{speaker:"A",text:"田中さんは仕事が速いばかりでなく、ミスもほとんどないから本当に助かるよ。",translation:"Anh Tanaka không chỉ làm việc nhanh mà hầu như còn không mắc lỗi nên thực sự giúp ích rất nhiều đấy."},{speaker:"B",text:"そうですね。周りへの気配りもできて、チームのみんなから頼りにされていますよ。",translation:"Đúng vậy nhỉ. Anh ấy còn biết quan tâm đến xung quanh nên được mọi người trong đội rất tin tưởng."},{speaker:"A",text:"本当に素晴らしい新人が入ってくれて心強いね。",translation:"Thực sự có nhân viên mới xuất sắc như vậy gia nhập làm mình thấy yên tâm hẳn."}]},commonMistake:{wrong:"このアパートは駅から遠くて不便ばかりか、家賃も高すぎる。",correct:"このアパートは駅から遠くて不便なばかりか、家賃も高すぎる。",why:"Tính từ đuôi な khi kết hợp với 「ばかりか／ばかりでなく」 phải giữ lại 「な」 (hoặc dùng dạng 「である」) chứ không được lược bỏ."},note:"So với 「～だけでなく」 mang tính chất liệt kê trung tính, 「～ばかりか」 thể hiện rõ cảm xúc bất ngờ, bất mãn hoặc thán phục khi sự việc ở vế sau vượt quá tưởng tượng."}],125:[{pattern:"～にかかわらず",meaning:"Bất kể, không kể (điều kiện không ảnh hưởng kết quả)",priority:"core",explanation:'Mẫu câu「～にかかわらず」mang ý nghĩa "bất kể... / không màng đến...", diễn đạt ý nghĩa hành động hoặc kết quả ở vế sau hoàn toàn không bị chi phối hay ảnh hưởng bởi điều kiện ở vế trước. Vế trước thường đi kèm danh từ chỉ phạm vi/sự biến thiên (như thời tiết, tuổi tác, quốc tịch) hoặc các cặp từ đối lập, cặp khẳng định - phủ định (như có hay không, làm hay không làm). Mẫu này mang sắc thái trang trọng, khách quan, thường xuất hiện nhiều trong các văn bản thông báo, quy tắc, hợp đồng hoặc bài phát biểu.',examples:[{sentence:"理由の如何にかかわらず、提出期限を過ぎた申請書は一切受理いたしません。",translation:"Bất kể lý do là gì, chúng tôi tuyệt đối không tiếp nhận đơn xin đã quá hạn nộp."},{sentence:"この市民講座は、年齢や国籍にかかわらず、どなたでも無料で受講していただけます。",translation:"Khóa học cộng đồng này bất kể độ tuổi hay quốc tịch, bất kỳ ai cũng có thể tham gia học miễn phí."}],dialogue:{title:"Kế hoạch giải chạy marathon",lines:[{speaker:"A",text:"明日のマラソン大会ですが、もし雨が降ったら中止になりますか。",translation:"Về giải chạy marathon ngày mai, nếu trời mưa thì có bị hoãn không ạ?"},{speaker:"B",text:"いえ、天候の良し悪しにかかわらず、予定通り決行されるそうですよ。",translation:"Không đâu, nghe nói là bất kể thời tiết đẹp hay xấu thì giải vẫn được tiến hành theo đúng kế hoạch đấy."},{speaker:"A",text:"そうですか。それなら雨具の用意もきちんとしておかないといけませんね。",translation:"Vậy à. Thế thì tôi phải chuẩn bị sẵn cả áo mưa/đồ đi mưa cẩn thận mới được."}]},commonMistake:{wrong:"雨が降っていたにかかわらず、彼は傘を差さずに出かけた。",correct:"雨が降っていたにもかかわらず、彼は傘を差さずに出かけた。",why:"Người học hay nhầm lẫn giữa「～にかかわらず」(bất kể) và「～にもかかわらず」(mặc dù... thế mà); ở đây diễn tả một sự việc thực tế cụ thể xảy ra trái với kỳ vọng nên phải dùng「～にもかかわらず」."},note:"Cần lưu ý:「～にかかわらず」yêu cầu vế trước phải là yếu tố có độ dao động/lựa chọn (như thời tiết, đi hay không), còn nếu chỉ là một sự thật đã định hình muốn diễn tả sự tương phản thì phải dùng「～にもかかわらず」."},{pattern:"～どころか",meaning:"Không những không ~, trái lại / Không phải ~ đâu mà còn",priority:"common",explanation:'Mẫu câu 「～どころか」 dùng để nhấn mạnh một thực tế hoàn toàn trái ngược với điều được dự đoán, kỳ vọng, hoặc sự việc thực tế còn ở mức độ chênh lệch rất xa so với vế trước. Cấu trúc này thường được dịch là "không những không... mà trái lại" hoặc "ngay cả A còn chưa được, nói gì đến B". Mẫu này mang sắc thái phủ định mạnh mẽ, thường biểu thị sự ngạc nhiên, thất vọng hoặc phê phán trong cả giao tiếp thường ngày lẫn văn viết.',examples:[{sentence:"風邪が治るどころか、熱が４０度まで上がって入院することになった。",translation:"Bệnh cảm cúm không những không khỏi mà sốt còn tăng lên tận 40 độ khiến tôi phải nhập viện."},{sentence:"忙しくて、旅行どころか週末にゆっくり休む時間さえない。",translation:"Bận rộn đến mức nói gì đến chuyện đi du lịch, ngay cả thời gian nghỉ ngơi thong thả vào cuối tuần cũng chẳng có."}],dialogue:{title:"Tình hình kinh doanh mới",lines:[{speaker:"A",text:"先月オープンしたカフェ、もう儲かっている？",translation:"Quán cà phê mở tháng trước đã có lãi chưa?"},{speaker:"B",text:"儲かるどころか、毎月大赤字で家賃を払うのもやっとだよ。",translation:"Có lãi đâu không thấy, trái lại tháng nào cũng lỗ nặng, tiền thuê mặt bằng còn suýt không trả nổi đây."},{speaker:"A",text:"えっ、それは大変だね。何か集客の対策を考えないと。",translation:"Hả, thế thì gay go quá. Phải nghĩ cách gì đó để thu hút khách thôi."}]},commonMistake:{wrong:"薬を飲んだら、治るどころかすっかり元気になりました。",correct:"薬を飲んだら、治るどころかかえって症状が悪化してしまった。",why:"「～どころか」dùng để diễn tả kết quả trái ngược hoặc tồi tệ hơn hẳn so với kỳ vọng, không dùng khi vế sau là kết quả thuận chiều tích cực."},note:"Khác với 「～ばかりか」(không chỉ A mà còn B, hai vế cùng chiều bổ sung cho nhau), 「～どころか」luôn mang tính phủ định thực tế ở vế trước để nêu lên một sự thật tương phản gay gắt hoặc tiêu cực hơn nhiều."},{pattern:"～にすぎない",meaning:"Chỉ là, không hơn gì (hạ thấp, không coi trọng quá)",priority:"common",explanation:'Mẫu câu 「～にすぎない」 dùng để diễn tả ý nghĩa "chỉ là... không hơn không kém", nhằm đánh giá sự việc ở mức độ thấp hoặc không coi trọng quá mức. Cấu trúc này thường kết hợp với danh từ hoặc thể thông thường của động từ/tính từ, mang sắc thái khiêm tốn khi nói về bản thân hoặc xem nhẹ một sự việc nào đó. Trong câu, mẫu này rất hay đi kèm với các phó từ như 「ただ」「単に」 để tăng tính nhấn mạnh.',examples:[{sentence:"今回の成功は運が良かったにすぎないから、次はもっと気を引き締めて臨もう。",translation:"Thành công lần này chẳng qua chỉ là do may mắn thôi, nên lần tới hãy tập trung hơn nữa nhé."},{sentence:"ネット上の噂は単なる推測にすぎないため、鵜呑みにするのは危険だ。",translation:"Tin đồn trên mạng chỉ đơn thuần là suy đoán thôi, vì vậy việc tin ngay là rất nguy hiểm."}],dialogue:{title:"Khen ngợi bài thuyết trình",lines:[{speaker:"A",text:"今日のプレゼン、データも分かりやすくて素晴らしかったよ！",translation:"Bài thuyết trình hôm nay tuyệt vời lắm, số liệu cũng rất dễ hiểu!"},{speaker:"B",text:"ありがとうございます。でも、私は先輩が集めてくれた資料をまとめたにすぎないですよ。",translation:"Em cảm ơn anh ạ. Nhưng em chẳng qua chỉ là tổng hợp lại tài liệu mà tiền bối thu thập giúp thôi ạ."},{speaker:"A",text:"いや、あの短時間でここまで仕上げたのは君の実力だよ。",translation:"Không đâu, hoàn thành tốt thế này trong thời gian ngắn như vậy chính là thực lực của em đấy."}]},commonMistake:{wrong:"今回のプロジェクトが大成功したのは、チーム全員の努力にすぎない。",correct:"今回のプロジェクトが大成功したのは、チーム全員の努力にほかならない。",why:'「～にすぎない」 mang sắc thái hạ thấp, xem nhẹ sự việc ("chẳng qua chỉ là") nên không dùng để ca ngợi hay nhấn mạnh nguyên nhân lớn; trường hợp muốn khẳng định "chính là nhờ..." phải dùng 「～にほかならない」.'},note:'「～にすぎない」 thường đi cùng phó từ 「ただ」「単に」 để nhấn mạnh ý "chỉ là", và tránh nhầm với mẫu khẳng định mạnh mẽ 「～にほかならない」 (chính là/không gì khác ngoài).'},{pattern:"～はともかく（として）",meaning:"Tạm gác (vấn đề đó) sang một bên",priority:"common",explanation:'Mẫu câu này có nghĩa là "tạm gác A sang một bên / chưa bàn tới A", dùng khi người nói muốn tạm thời không xem xét vấn đề A để ưu tiên nhấn mạnh vào sự việc B ở vế sau. Cấu trúc thường kết hợp trực tiếp với Danh từ, cụm danh từ hóa (V-るの) hoặc dạng nghi vấn 「〜かどうか」. Vế B phía sau thể hiện đánh giá, hành động hoặc sự thực quan trọng hơn mà người nói muốn tập trung vào. Mẫu này được dùng phổ biến cả trong giao tiếp hàng ngày lẫn văn viết để diễn đạt cách nhìn nhận thực tế và khách quan.',examples:[{sentence:"結果はともかくとして、最後まで諦めずに全力を尽くしたことに大きな意味がある。",translation:"Tạm gác kết quả sang một bên, việc nỗ lực hết mình và không bỏ cuộc cho đến phút cuối cùng mới mang ý nghĩa to lớn."},{sentence:"デザインはともかく、この空気清浄機は機能性と省エネ性能が非常に優れている。",translation:"Chưa bàn đến kiểu dáng thiết kế, chiếc máy lọc không khí này có tính năng và khả năng tiết kiệm điện vô cùng vượt trội."}],dialogue:{title:"Chọn quán cà phê",lines:[{speaker:"A",text:"駅前の新しいカフェに行ってみない？味はともかくとして、店内が静かで作業しやすそうだよ。",translation:"Cậu có muốn ghé quán cà phê mới trước ga không? Tạm gác chuyện đồ uống ngon dở sang một bên, không gian ở đó yên tĩnh và rất dễ ngồi làm việc đấy."},{speaker:"B",text:"いいね！最近集中できる場所を探していたから、ちょうどよかった。",translation:"Được đấy! Dạo này tớ đang tìm chỗ nào tập trung được, đúng lúc quá."},{speaker:"A",text:"じゃあ、混み始める前に早速行ってみよう。",translation:"Vậy thì chúng mình đi ngay trước khi quán bắt đầu đông nhé."}]},commonMistake:{wrong:"合格するはともかく、試験に向けて毎日3時間勉強している。",correct:"合格できるかどうかはともかくとして、試験に向けて毎日3時間勉強している。",why:"Mẫu 「〜はともかく」 không đứng trực tiếp sau động từ thể từ điển mà cần đi với danh từ, dạng danh từ hóa 「〜のは」 hoặc lồng câu nghi vấn 「〜かどうか」."},note:"Phân biệt với 「〜は抜きにして」 (bỏ qua một nghi thức/thủ tục quen thuộc để đi thẳng vào việc chính) và 「〜にかかわらず」 (bất kể điều kiện A thế nào thì vế B vẫn hoàn toàn không bị ảnh hưởng)."}],126:[{pattern:"～かな／かしら",meaning:"Không biết có ~ không nhỉ, nhỉ (tự hỏi, phân vân)",priority:"core",explanation:"Mẫu ngữ pháp「～かな／かしら」được dùng khi người nói tự hỏi, băn khoăn hoặc phân vân về một sự việc nào đó mà bản thân chưa chắc chắn. Về mặt ngữ thái, đây thường là dạng câu độc thoại nội tâm hoặc hỏi dò ý kiến đối phương một cách nhẹ nhàng, tế nhị. Cấu trúc kết hợp với thể thông thường (普通形), trong đó「かな」dùng cho cả nam và nữ trong văn phong thân mật, còn「かしら」chủ yếu được nữ giới sử dụng.",examples:[{sentence:"このレポート、締め切りまでに書き終わるかしら。",translation:"Không biết mình có viết xong bản báo cáo này trước hạn chót không nhỉ."},{sentence:"バスがなかなか来ないけれど、途中で事故でもあったのかな。",translation:"Xe buýt mãi chưa thấy tới, không biết có xảy ra tai nạn ở giữa đường không nhỉ."}],dialogue:{title:"Chọn món ăn trưa",lines:[{speaker:"A",text:"今日のお昼は何を食べようかな。駅前の新しいラーメン屋に行ってみない？",translation:"Trưa nay không biết nên ăn gì nhỉ. Hay tụi mình đi thử quán ramen mới mở trước ga không?"},{speaker:"B",text:"いいね。でも、お昼休みはすごく混んでいるかもしれないよ。",translation:"Được đấy. Nhưng tầm giờ nghỉ trưa có khi đông lắm đấy."},{speaker:"A",text:"そうだね。じゃあ、少し時間をずらして1時過ぎに行こうか。",translation:"Ừ nhỉ. Vậy tụi mình lùi giờ lại một chút, qua 1 giờ rồi đi nhé."}]},commonMistake:{wrong:"田中さんは今日、暇だかな。",correct:"田中さんは今日、暇かな。",why:"Với tính từ đuôi な và danh từ ở dạng hiện tại khẳng định, ta gắn trực tiếp「かな」vào sau thân từ (bỏ だ) chứ không nói「だかな」."},note:"Khi kết hợp với thể phủ định「～ないかな／～ないかしら」, mẫu câu còn biểu thị ước muốn tha thiết của người nói mong cho điều gì đó xảy ra (ví dụ: 早く雨がやまないかな - Ước gì trời mau tạnh mưa nhỉ)."},{pattern:"～よね／ね／よ（終助詞）",meaning:"Nhỉ / Nhé / Đấy (tìm kiếm đồng thuận / nhấn mạnh)",priority:"common",explanation:"Các trợ từ cuối câu 「よ」「ね」「よね」 dùng để điều chỉnh sắc thái giao tiếp và chia sẻ thông tin giữa người nói với người nghe. Trong đó, 「よ」 dùng để truyền đạt thông tin mới hoặc nhấn mạnh ý kiến của người nói; 「ね」 dùng để tìm kiếm sự đồng cảm hoặc xác nhận thông tin cả hai bên cùng biết; còn 「よね」 kết hợp cả hai sắc thái, dùng khi người nói đưa ra phán đoán/ý kiến của mình và muốn người nghe xác nhận, đồng tình. Cả ba trợ từ đều đứng trực tiếp ở cuối câu (thể thông thường hoặc lịch sự) và xuất hiện liên tục trong hội thoại tự nhiên hàng ngày.",examples:[{sentence:"明日のミーティングの時間は午前10時からでしたよね。",translation:"Cuộc họp ngày mai bắt đầu từ 10 giờ sáng đúng không nhỉ?"},{sentence:"田中さんも今回の新企画に参加する予定ですよね。",translation:"Anh Tanaka cũng có kế hoạch tham gia vào dự án mới lần này đúng không nhỉ?"}],dialogue:{title:"Kế hoạch tiệc nướng",lines:[{speaker:"A",text:"今週末のバーベキュー、佐藤さんも来る予定ですよね。",translation:"Buổi tiệc nướng cuối tuần này, anh Sato cũng định đến đúng không nhỉ?"},{speaker:"B",text:"ええ、さっき確認したら参加するって言ってましたよ。",translation:"Vâng, nãy tôi vừa hỏi thì anh ấy bảo là sẽ tham gia đấy."},{speaker:"A",text:"よかった！みんなで集まると絶対に楽しいですよね。",translation:"May quá! Mọi người cùng tụ tập thì chắc chắn sẽ vui lắm nhỉ."}]},commonMistake:{wrong:"私の出身地はハノイですよね。",correct:"私の出身地はハノイですよ。",why:"Không dùng 「よね」 cho thông tin cá nhân của người nói mà người nghe không thể biết để đồng tình hay xác nhận, trường hợp này phải dùng 「よ」 để cung cấp thông tin mới."},note:"Cần ghi nhớ sự khác biệt cốt lõi: 「よ」 dùng khi người nói cung cấp thông tin mới mà người nghe chưa biết, 「ね」 dùng khi cả hai cùng biết thông tin, còn 「よね」 dùng khi người nói tin vào phán đoán của mình nhưng muốn người nghe xác nhận lại."},{pattern:"でしょ／でしょう（確認・推量）",meaning:"Đúng không, chắc là ~ (xác nhận hoặc suy đoán)",priority:"common",explanation:'Mẫu câu 「でしょ／でしょう」 được dùng để diễn tả sự suy đoán, phán đoán của người nói về một sự việc, hoặc dùng để xác nhận và tìm kiếm sự đồng tình từ người nghe ("đúng không?", "chắc là..."). Khi lên giọng ở cuối câu (thường là「でしょ⤴」trong hội thoại), câu mang sắc thái hỏi lại hoặc đòi hỏi sự đồng thuận; khi xuống giọng, câu thể hiện sự phán đoán nhẹ nhàng, khách quan. Trong đó, 「でしょ」 là dạng thân mật dùng trong văn nói hàng ngày, còn 「でしょう」 mang tính lịch sự hơn.',examples:[{sentence:"明日の午後は雨が降るでしょうから、傘を持っていったほうがいいですよ。",translation:"Buổi chiều mai chắc là trời sẽ mưa đấy, nên bạn mang theo dù đi nhé."},{sentence:"この店のケーキ、甘すぎなくてすごく美味しいでしょ？",translation:"Bánh ngọt của quán này không quá ngọt mà ngon cực kỳ đúng không?"}],dialogue:{title:"Hỏi thăm kỳ thi",lines:[{speaker:"A",text:"田中さん、昨日の試験はかなり難しかったでしょう？",translation:"Anh Tanaka, bài thi hôm qua chắc là khó lắm đúng không?"},{speaker:"B",text:"ええ、特に読解問題に時間がかかって大変でしたよ。",translation:"Vâng, đặc biệt là phần đọc hiểu mất nhiều thời gian nên vất vả lắm."},{speaker:"A",text:"やっぱりそうでしたか。みんな同じことを言っていました。",translation:"Quả nhiên là vậy à. Mọi người cũng đều nói như thế đấy."}]},commonMistake:{wrong:"明日は雨だでしょうから、イベントは中止になるかもしれません。",correct:"明日は雨でしょうから、イベントは中止になるかもしれません。",why:"Khi kết hợp với danh từ hoặc tính từ đuôi な, ta nối trực tiếp với 「でしょう／でしょ」 mà không giữ lại 「だ」."},note:'Khi lên giọng ở cuối câu (でしょ⤴), câu mang sắc thái thúc ép đồng tình hoặc mang tính nhắc nhở ("đã bảo rồi mà"), vì vậy tuyệt đối không dùng với cấp trên hay người lớn tuổi để tránh bị coi là thất lễ.'},{pattern:"～じゃないか／じゃないですか",meaning:"~ không, chẳng phải ~ sao (xác nhận, đề xuất, phản bác)",priority:"common",explanation:"Mẫu câu này dùng khi người nói muốn xác nhận ý kiến, đưa ra đề xuất nhẹ nhàng hoặc nhắc nhở, phản bác đối phương về một sự thật hiển nhiên. Ngoài ra, cấu trúc này còn thể hiện sự ngạc nhiên, thích thú khi người nói bất ngờ phát hiện ra một điều gì đó ngoài dự kiến. Cách kết hợp là đi sau thể thông thường (lưu ý danh từ và tính từ đuôi な phải bỏ だ), trong đó 「じゃないですか」 mang sắc thái lịch sự hơn 「じゃないか」.",examples:[{sentence:"ほら、あそこに田中さんがいるじゃないですか。声をかけてみましょう。",translation:"Kìa, chẳng phải anh Tanaka đang ở đằng kia sao? Chúng ta ra gọi anh ấy đi."},{sentence:"昨日徹夜したんだから、今日眠いのは当たり前じゃないか。",translation:"Hôm qua cậu đã thức trắng đêm thì hôm nay buồn ngủ là chuyện đương nhiên rồi còn gì."}],dialogue:{title:"Tìm chìa khóa xe",lines:[{speaker:"A",text:"あれ？車の鍵が見当たらないんだけど、どこかで見なかった？",translation:"Ơ? Tôi không thấy chìa khóa xe đâu cả, cậu có thấy ở đâu không?"},{speaker:"B",text:"えっ、机の上にあるじゃないですか。さっき置いたばかりですよ。",translation:"Ủa, chẳng phải nó đang nằm ngay trên bàn kia sao? Anh vừa mới để lúc nãy mà."},{speaker:"A",text:"あ、本当だ！全然気づかなかったよ、ありがとう。",translation:"A, đúng thật rồi! Tôi hoàn toàn không để ý thấy, cảm ơn cậu nhé."}]},commonMistake:{wrong:"週末だし、明日は休みだじゃないですか。映画でも見に行きませんか。",correct:"週末だし、明日は休みじゃないですか。映画でも見に行きませんか。",why:"Khi kết hợp với danh từ và tính từ đuôi な ở thể thông thường hiện tại, phải bỏ だ trước じゃないか／じゃないですか."},note:"Cần chú ý ngữ điệu: khi lên giọng ở cuối câu sẽ mang sắc thái hỏi/xác nhận ý kiến đối phương, còn khi hạ giọng sẽ thể hiện sự phát hiện bất ngờ hoặc trách móc, cằn nhằn nhẹ."},{pattern:"～んだ／んです（説明・強調）",meaning:"Là do ~, thực ra là ~ đấy (giải thích/nhấn mạnh)",priority:"common",explanation:"Mẫu ngữ pháp này dùng để giải thích lý do, nguyên nhân hoặc bối cảnh của một sự việc mà người nghe đang thấy hoặc thắc mắc. Trong giao tiếp hàng ngày, nó còn dùng để nhấn mạnh cảm xúc, chia sẻ thông tin bất ngờ hoặc chủ động mở đầu câu chuyện. Khi kết hợp với danh từ và tính từ đuôi な ở thể khẳng định hiện tại, cần chú ý đổi 「だ」 thành 「な」 trước khi cộng với 「んだ／んです」.",examples:[{sentence:"昨日買ったばかりの傘を電車の中に忘れてしまったんです。",translation:"Thực ra là em lỡ để quên chiếc ô vừa mới mua hôm qua trên tàu điện mất rồi."},{sentence:"すみません、今日はちょっと体調が悪いんです。早退してもよろしいでしょうか。",translation:"Xin lỗi, hôm nay người em hơi không được khỏe. Em có thể xin phép về sớm được không ạ?"}],dialogue:{title:"Hỏi thăm đồng nghiệp",lines:[{speaker:"A",text:"顔色が良くないですね。どうかしたんですか。",translation:"Sắc mặt cậu trông không tốt lắm. Có chuyện gì thế?"},{speaker:"B",text:"実は、昨日からずっと頭が痛いんです。",translation:"Thực ra là từ hôm qua đến giờ đầu tôi cứ đau suốt."},{speaker:"A",text:"大変ですね。無理しないで早く休んでくださいね。",translation:"Vất vả quá nhỉ. Đừng gắng gượng quá, hãy nghỉ ngơi sớm đi nhé."}]},commonMistake:{wrong:"彼は日本語がとても上手だんです。",correct:"彼は日本語がとても上手なんです。",why:"Với tính từ đuôi な và danh từ ở thể khẳng định hiện tại, phải đổi 「だ」 thành 「な」 rồi mới thêm 「んだ／んです」."},note:"Tránh dùng 「～んです」 khi chỉ tường thuật sự thật khách quan đơn thuần mà không có ngữ cảnh giải thích, thắc mắc hay chia sẻ cảm xúc."}],127:[{pattern:"～とか（例示・伝聞・口語）",meaning:"~ chẳng hạn, ~ hay gì đó (liệt kê ví dụ/truyền đạt không chính thức)",priority:"core",explanation:'Mẫu ngữ pháp 「～とか」 dùng trong văn nói để đưa ra một vài ví dụ tiêu biểu mang tính chất không liệt kê hết (như "chẳng hạn như... hay là..."), hoặc biểu thị thông tin nghe loáng thoáng, phỏng đoán chưa chắc chắn. Mẫu này thường đi trực tiếp sau danh từ hoặc dạng thông thường (普通形) của động từ, tính từ. Vì mang sắc thái thân mật, tự nhiên và có tính khẩu ngữ cao nên 「～とか」 chỉ dùng trong giao tiếp đời thường hàng ngày, tránh dùng trong văn bản hoặc hoàn cảnh trang trọng.',examples:[{sentence:"気分転換に散歩するとか、音楽を聴くとかしたらどう？",translation:"Để đổi gió thì bạn thử đi dạo hay nghe nhạc gì đó xem sao?"},{sentence:"山田さんは来月仕事を辞めるとか言ってたけど、本当かな。",translation:"Nghe đâu Yamada bảo tháng sau sẽ nghỉ việc hay sao ấy, không biết có thật không nhỉ."}],dialogue:{title:"Chuẩn bị đồ ăn cho tiệc",lines:[{speaker:"A",text:"今度のパーティー、何を持って行けばいいかな。",translation:"Bữa tiệc sắp tới mang theo món gì thì được nhỉ?"},{speaker:"B",text:"唐揚げとかサンドイッチとか、手軽に食べられるものがいいんじゃない？",translation:"Mấy món dễ ăn như gà rán hay bánh mì kẹp chẳng hạn, không phải sẽ tốt sao?"},{speaker:"A",text:"了解！じゃあ、帰りにスーパーで材料を買っていくよ。",translation:"Hiểu rồi! Thế trên đường về tớ sẽ ghé siêu thị mua nguyên liệu."}]},commonMistake:{wrong:"レポートにはアンケートの結果とか考察とかを書かなければならない。",correct:"レポートにはアンケートの結果や考察などを書かなければならない。",why:"「～とか」 mang tính khẩu ngữ thân mật nên không phù hợp trong báo cáo, bài luận hay văn cảnh trang trọng; trường hợp này phải dùng 「～や～など」."},note:"So với 「～や～など」 có thể dùng cho cả văn viết lẫn văn nói trang trọng, 「～とか」 chỉ dùng trong hội thoại đời thường và có thể đi kèm động từ ở cuối câu để đưa ra gợi ý nhẹ nhàng hoặc diễn đạt sự ngập ngừng."},{pattern:"～てしまう／ちゃう（完了・後悔）",meaning:"Đã ~ mất rồi, lỡ ~ rồi (hoàn tất/hối tiếc)",priority:"common",explanation:"Mẫu câu 「～てしまう」 được dùng để diễn tả một hành động đã hoàn tất trọn vẹn (làm xong hết) hoặc một sự việc xảy ra ngoài ý muốn gây ra cảm giác hối tiếc, tiếc nuối hay thất vọng. Trong văn nói thân mật hàng ngày, 「～てしまう」 thường được biến đổi ngắn gọn thành 「～ちゃう」 (và 「～でしまう」 thành 「～じゃう」). Mẫu này kết hợp với động từ thể て và xuất hiện vô cùng phổ biến trong giao tiếp đời sống lẫn các kỳ thi JLPT.",examples:[{sentence:"大切にしていたお気に入りの傘を、電車の中に忘れてきてしまいました。",translation:"Tôi lỡ để quên mất chiếc ô yêu thích mà mình vô cùng trân trọng ở trên tàu điện rồi."},{sentence:"ずっと楽しみにしていた大人気のアニメを、週末で全話一気に観ちゃった。",translation:"Bộ anime đình đám mà tôi mong chờ bấy lâu, tôi đã xem hết sạch cả bộ chỉ trong dịp cuối tuần rồi."}],dialogue:{title:"Làm mất chìa khóa",lines:[{speaker:"A",text:"どうしよう、家の鍵をどこかに落としちゃったみたい。",translation:"Làm sao bây giờ, hình như tớ lỡ làm rơi chìa khóa nhà ở đâu mất rồi."},{speaker:"B",text:"えっ、本当？最後に鍵を見たのはどこか覚えてる？",translation:"Hả, thật á? Cậu có nhớ lần cuối nhìn thấy chìa khóa là ở đâu không?"},{speaker:"A",text:"さっき立ち寄ったコンビニのレジかもしれない。急いで戻ってみるね。",translation:"Có thể là ở quầy thanh toán cửa hàng tiện lợi tớ ghé lúc nãy. Tớ sẽ chạy vội lại đó kiểm tra xem sao."}]},commonMistake:{wrong:"友達に借りた本をもう全部読んちゃった。",correct:"友達に借りた本をもう全部読んじゃった。",why:"Với các động từ chia thể て có âm đục 「～で」 (như 読む → 読んで) thì trong văn nói rút gọn phải chuyển thành 「～じゃう／じゃった」 chứ không dùng 「～ちゃう／ちゃった」."},note:"Cần phân biệt sắc thái tiếc nuối hoặc làm xong dứt điểm của 「～てしまう」 với hành động chủ động làm sẵn để chuẩn bị trước của 「～ておく」."},{pattern:"～なあ",meaning:"~ nhỉ, ~ thật (cảm thán, nội tâm)",priority:"common",explanation:"Mẫu「～なあ」được dùng để bộc lộ cảm xúc, sự cảm thán hoặc suy nghĩ nội tâm một cách tự nhiên như tiếng lòng tự nói với chính mình. Ngoài ra, mẫu này cũng rất hay đi cùng thể điều kiện (như ～たら、～ば) để thể hiện niềm mong ước tha thiết hay nuối tiếc. Do mang sắc thái độc thoại và thân mật, mẫu này chỉ dùng cho bản thân hoặc trò chuyện với bạn bè thân thiết, không dùng trong ngữ cảnh trang trọng.",examples:[{sentence:"富士山の頂上から見る日の出は、本当に綺麗だなあ。",translation:"Ngắm bình minh từ đỉnh núi Phú Sĩ thực sự đẹp tuyệt vời biết bao."},{sentence:"子どもの頃に戻れたらいいのになあ。",translation:"Ước gì mình có thể quay trở lại thời thơ ấu thì tốt biết mấy."}],dialogue:{title:"Sau buổi thi kết thúc",lines:[{speaker:"A",text:"今日の日本語のテスト、難しかったなあ。",translation:"Bài thi tiếng Nhật hôm nay khó thật đấy nhỉ."},{speaker:"B",text:"そうだね、特に最後の長文読解に時間がかかっちゃったよ。",translation:"Đúng thế thật, đặc biệt là bài đọc hiểu dài ở cuối tốn bao nhiêu thời gian."},{speaker:"A",text:"うん、二人とも合格できているといいなあ。",translation:"Ừ, mong sao cả hai đứa mình đều đỗ."}]},commonMistake:{wrong:"部長、今日のプレゼンは本当に素晴らしかったなあ。",correct:"部長、今日のプレゼンは本当に素晴らしかったです。",why:"「～なあ」mang tính độc thoại nội tâm hoặc giao tiếp suồng sã, tuyệt đối không dùng trực tiếp khi phát ngôn với cấp trên hay người lớn tuổi."},note:"Khác với「ね」dùng để hướng tới đối phương nhằm tìm kiếm sự đồng cảm,「なあ」chủ yếu là tiếng thở dài hay cảm thán thốt ra từ nội tâm của chính người nói."},{pattern:"～っけ",meaning:"Nhỉ, nhỉ (hỏi lại điều mình không chắc nhớ)",priority:"common",explanation:"Mẫu 「～っけ」 được dùng nhiều trong hội thoại thân mật để xác nhận lại một thông tin mà người nói đã từng biết hoặc từng nghe qua nhưng tạm thời không nhớ rõ. Ngoài ra, mẫu này cũng thường dùng khi tự độc thoại với chính mình nhằm cố nhớ lại một việc gì đó. Cấu trúc này rất hay kết hợp với thể quá khứ (như ～たっけ / だったっけ) để thể hiện rằng sự việc đó vốn đã được định sẵn hoặc đã xảy ra trong quá khứ.",examples:[{sentence:"来週のテストの範囲って、教科書の何ページまでだったっけ？",translation:"Phạm vi bài kiểm tra tuần sau là đến trang bao nhiêu trong sách giáo khoa ấy nhỉ?"},{sentence:"あの新しいカフェ、駅の西口を出て右手にあるんだっけ？",translation:"Quán cà phê mới mở đó nằm ở bên tay phải sau khi ra khỏi cửa Tây ga đúng không nhỉ?"}],dialogue:{title:"Hỏi lại kế hoạch xem phim",lines:[{speaker:"A",text:"ねえ、明日観に行く映画って、チケットもう予約したっけ？",translation:"Này, vé bộ phim ngày mai tụi mình đi xem đã đặt trước chưa ấy nhỉ?"},{speaker:"B",text:"うん、昨日の夜にネットで席取っておいたよ。",translation:"Ừ, tối qua tớ đã đặt chỗ trên mạng rồi đấy."},{speaker:"A",text:"ありがとう！上映は何時からだっけ？",translation:"Cảm ơn cậu nhé! Chiếu từ mấy giờ ấy nhỉ?"}]},commonMistake:{wrong:"（初対面の人に）すみません、お名前は何だっけ？",correct:"（初対面の人に）すみません、お名前は何とおっしゃいますか？",why:"Mẫu 「～っけ」 chỉ dùng để xác nhận lại thông tin mình đã từng nghe hay từng biết trước đó nhưng quên mất, không dùng để hỏi thông tin mới hoàn toàn hoặc hỏi người lạ trong lần đầu gặp gỡ."},note:"Khi cần hỏi người bề trên hoặc trong bối cảnh lịch sự, có thể chuyển sang dạng 「～でしたっけ / ～ましたっけ」 để xác nhận lại thông tin một cách nhẹ nhàng, lễ phép."},{pattern:"～てくれない？／てもらえる？",meaning:"Nhờ, xin ~ giùm (yêu cầu thân mật/lịch sự)",priority:"common",explanation:"Mẫu câu này dùng để nhờ vả hoặc yêu cầu đối phương thực hiện một hành động nào đó giúp mình với thái độ nhẹ nhàng. Dạng thân mật 「～てくれない？／てもらえる？」 thường dùng khi trò chuyện với bạn bè, người thân trong gia đình hoặc người có vai vế thấp hơn. Khi cần thể hiện sự lịch sự hơn trong giao tiếp hàng ngày hoặc công việc, người nói sẽ chuyển sang dạng 「～てくれませんか？／～てもらえますか？」.",examples:[{sentence:"エアコンのリモコン、そこの机の上にあるから取ってくれない？",translation:"Điều khiển điều hòa ở trên bàn đằng kia, lấy giùm mình được không?"},{sentence:"この書類の日本語が合っているかどうか、ちょっと見てもらえる？",translation:"Cậu xem giúp tớ xem tiếng Nhật trong tài liệu này có đúng không được không?"}],dialogue:{title:"Chuẩn bị bữa tối",lines:[{speaker:"A",text:"今手が離せないから、お鍋の火を消してくれない？",translation:"Bây giờ tớ đang bận tay, cậu tắt bếp nồi canh giúp tớ được không?"},{speaker:"B",text:"わかった、今すぐ消すね。他には何かある？",translation:"Tớ biết rồi, tắt ngay đây. Còn việc gì nữa không?"},{speaker:"A",text:"ありがとう、ついでにそっちのお皿も並べてもらえる？",translation:"Cảm ơn nhé, tiện thể cậu xếp giúp tớ mấy cái đĩa bên kia nữa được không?"}]},commonMistake:{wrong:"部長、この企画書をチェックしてくれない？",correct:"部長、この企画書をチェックしていただけませんか？",why:"「～てくれない？」 là cách nhờ vả thân mật suồng sã, tuyệt đối không dùng với cấp trên hay người lớn tuổi mà phải dùng dạng kính ngữ lịch sự như 「～していただけませんか？」."},note:"「～てもらえる？」 thường mang sắc thái khiêm tốn và thăm dò khả năng của đối phương nhiều hơn so với 「～てくれない？」."}],128:[{pattern:"～をよそに",meaning:"Bất chấp / Không màng đến ~",priority:"core",explanation:'Mẫu câu 「～をよそに」 đi sau danh từ, có nghĩa là "mặc kệ, không màng đến, bất chấp" những lo lắng, kỳ vọng, phản đối hay sự chú ý từ những người xung quanh để làm việc gì đó. Cấu trúc này thường dùng để diễn tả hành vi của người khác với sắc thái ngạc nhiên hoặc phê phán trước thái độ bàng quan, dửng dưng của chủ thể. Thông thường, mẫu ngữ pháp này kết hợp với các danh từ chỉ cảm xúc hoặc ý kiến của người khác như 心配 (lo lắng), 期待 (kỳ vọng), 反対 (phản đối), 批判 (chỉ trích).',examples:[{sentence:"親の心配をよそに、弟は大学を中退して一人で海外へ旅立ってしまった。",translation:"Mặc kệ sự lo lắng của bố mẹ, cậu em trai đã bỏ học đại học rồi một mình lên đường ra nước ngoài."},{sentence:"住民たちの強い反対の声をよそに、この地区での高層ビルの建設計画が進められている。",translation:"Bất chấp những tiếng nói phản đối kịch liệt của cư dân, kế hoạch xây dựng tòa nhà cao tầng ở khu vực này vẫn đang được xúc tiến."}],dialogue:{title:"Thái độ của Tanaka",lines:[{speaker:"A",text:"田中さん、周りの批判をよそに、また勝手に新しいプロジェクトを進めているらしいよ。",translation:"Nghe nói anh Tanaka lại mặc kệ những lời chỉ trích xung quanh mà tự ý tiến hành dự án mới rồi đấy."},{speaker:"B",text:"えっ、本当？チームの意見も聞かずに進めたら、後で大きなトラブルになりそうだね。",translation:"Hả, thật sao? Cứ làm mà không thèm hỏi ý kiến cả đội thế thì sau này dễ xảy ra rắc rối lớn lắm."},{speaker:"A",text:"そうだよね。一度リーダーからしっかり注意してもらった方がいいと思うよ。",translation:"Đúng thế nhỉ. Tớ nghĩ nên để trưởng nhóm nhắc nhở nghiêm túc một lần xem sao."}]},commonMistake:{wrong:"消防士たちは激しい炎をよそに、果敢に救助活動を続けた。",correct:"消防士たちは激しい炎をものともせずに、果敢に救助活動を続けた。",why:"「～をよそに」 mang sắc thái thờ ơ, làm ngơ trước cảm xúc hoặc ý kiến người khác, không dùng để ca ngợi hành động dũng cảm vượt qua khó khăn, nguy hiểm (trường hợp này phải dùng 「～をものともせずに」)."},note:"Phân biệt với 「～をものともせずに」: 「～をよそに」 nhấn mạnh thái độ phớt lờ sự quan tâm/kỳ vọng/lo lắng của người khác (mang nét nghĩa tiêu cực hoặc bàng quan), còn 「～をものともせずに」 dùng để ca ngợi việc dũng cảm đối mặt và vượt qua trở ngại, nghịch cảnh (bão tuyết, chấn thương, hiểm nguy)."},{pattern:"～をはじめ",meaning:"~ là đầu tiên / Bắt đầu từ ~",priority:"common",explanation:"Mẫu câu này dùng để đưa ra một đối tượng mang tính đại diện, tiêu biểu nhất đứng đầu, nhằm kéo theo nhiều đối tượng/sự vật khác cùng nhóm (trước hết phải kể đến..., tiêu biểu là...). Vế sau thường đi kèm với các từ chỉ số lượng nhiều hoặc tập hợp như「など」「多くの」「皆様」. Cấu trúc ngữ pháp gồm「N＋をはじめ（として）」hoặc bổ nghĩa cho danh từ「N＋をはじめとする＋N」, mang sắc thái trang trọng, thường dùng trong văn viết, diễn văn hoặc bối cảnh lịch sự.",examples:[{sentence:"日本には富士山をはじめ、世界に誇る美しい自然景観が数多く存在する。",translation:"Ở Nhật Bản có rất nhiều cảnh quan thiên nhiên tươi đẹp đáng tự hào với thế giới, tiêu biểu trước hết là núi Phú Sĩ."},{sentence:"校長先生をはじめとする先生方のご指導のおかげで、無事に卒業を迎えることができました。",translation:"Nhờ có sự chỉ bảo tận tình của các thầy cô giáo mà đứng đầu là thầy hiệu trưởng, chúng em đã có thể thuận lợi đón ngày tốt nghiệp."}],dialogue:{title:"Chuẩn bị sự kiện giao lưu",lines:[{speaker:"A",text:"今度のベトナムフェアでは、フォーをはじめ、様々な伝統料理を提供する予定です。",translation:"Hội chợ Việt Nam sắp tới dự kiến sẽ phục vụ rất nhiều món ăn truyền thống, trước hết phải kể đến phở."},{speaker:"B",text:"素晴らしいですね！料理だけでなく、アオザイの試着コーナーなども人気が出そうですよ。",translation:"Tuyệt vời quá nhỉ! Không chỉ ẩm thực, góc trải nghiệm mặc thử áo dài chắc cũng sẽ rất hút khách đấy."},{speaker:"A",text:"ええ、地域の皆様に楽しんでいただけるよう、しっかり準備を進めます。",translation:"Vâng, chúng tôi sẽ chuẩn bị thật chu đáo để bà con trong khu vực có thể tận hưởng trọn vẹn."}]},commonMistake:{wrong:"明日のイベントは午前10時をはじめ、午後4時まで行われます。",correct:"明日のイベントは午前10時から始まり、午後4時まで行われます。",why:"「～をはじめ」chỉ dùng để nêu đối tượng tiêu biểu trong một tập thể/danh sách chứ không dùng để chỉ mốc thời gian bắt đầu của một sự việc (lỗi do dịch theo nghĩa 'bắt đầu từ')."},note:"Cần lưu ý danh từ đứng trước「～をはじめ」phải là đại diện điển hình hoặc có thứ bậc cao nhất trong nhóm, và không dùng mẫu này cho các sự việc mang tính chất tiêu cực, nhỏ nhặt đời thường."},{pattern:"～からには",meaning:"Đã ~ rồi thì / Một khi đã ~",priority:"common",explanation:"Mẫu ngữ pháp này mang ý nghĩa 「Một khi đã... / Đã... thì đương nhiên...」. Cấu trúc được dùng để thể hiện quyết tâm, trách nhiệm, nghĩa vụ hoặc yêu cầu mạnh mẽ rằng một khi đã ở vào hoàn cảnh hay đưa ra quyết định đó thì việc tiếp theo là tất yếu phải thực hiện. Do đó, vế sau của câu thường đi kèm các biểu hiện mang tính ý chí, mệnh lệnh, nhờ vả hoặc phán đoán như ～べきだ, ～つもりだ, ～てみせる, ～てください.",examples:[{sentence:"一度このプロジェクトのリーダーを引き受けたからには、最後まで責任を持ってやり遂げるつもりです。",translation:"Một khi đã nhận lời làm trưởng dự án này rồi thì tôi dự định sẽ chịu trách nhiệm hoàn thành đến cùng."},{sentence:"高い学費を払って留学するからには、絶対に専門知識を身につけて帰国したい。",translation:"Đã trả chi phí đắt đỏ để đi du học thì tôi nhất định muốn tiếp thu kiến thức chuyên môn rồi mới về nước."}],dialogue:{title:"Quyết tâm thi đấu",lines:[{speaker:"A",text:"来月のスピーチコンテストに出場することにしたんだ。",translation:"Tớ đã quyết định sẽ tham gia cuộc thi hùng biện vào tháng sau đấy."},{speaker:"B",text:"本当？出るからには、優勝を目指して全力で頑張らなきゃね！",translation:"Thật à? Một khi đã tham gia thì phải nỗ lực hết mình nhắm tới giải quán quân đấy nhé!"},{speaker:"A",text:"うん、毎日練習を重ねて悔いのない発表をしてみせるよ。",translation:"Ừ, tớ sẽ chăm chỉ luyện tập mỗi ngày và thể hiện một bài thuyết trình không có gì nuối tiếc."}]},commonMistake:{wrong:"日本へ留学したからには、日本語が上手になりました。",correct:"日本へ留学したからには、ネイティブ並みに話せるようになりたい。",why:"Vế sau của 「～からには」 không dùng để trần thuật một kết quả hay sự thật đã xảy ra đơn thuần, mà bắt buộc phải mang tính ý chí, nguyện vọng, nghĩa vụ hoặc lời khuyên bảo."},note:"So với các mẫu mang nghĩa tương đương như 「～以上は」 và 「～上は」, 「～からには」 mang sắc thái cảm xúc và quyết tâm cá nhân mạnh mẽ nhất, trong khi 「～上は」 mang tính trang trọng và dùng nhiều trong văn viết chính thức."},{pattern:"～ことなく",meaning:"Không ~ mà / Không hề ~",priority:"common",explanation:'Mẫu ngữ pháp「～ことなく」mang ý nghĩa "không hề làm V / mà không làm V", diễn tả việc thực hiện một hành vi hay duy trì trạng thái mà hoàn toàn không diễn ra hành động V đi trước. Cấu trúc kết nối trực tiếp với động từ thể từ điển (V-る + ことなく). Đây là cách diễn đạt trang trọng, mang tính văn viết của「～ないで」hoặc「～ずに」, thường nhấn mạnh sự kiên trì liên tục không bỏ cuộc hoặc sự việc diễn ra thuận lợi mà không gặp trở ngại.',examples:[{sentence:"彼は一度も諦めることなく、10年間研究を続けてついに新薬を開発した。",translation:"Anh ấy không một lần bỏ cuộc, kiên trì nghiên cứu suốt 10 năm và cuối cùng đã phát triển thành công loại thuốc mới."},{sentence:"ネット通販の普及により、わざわざ店に足を運ぶことなく欲しい物が手に入るようになった。",translation:"Nhờ sự phổ biến của mua sắm trực tuyến, chúng ta có thể mua được món đồ mình muốn mà không cần phải cất công đến tận cửa hàng."}],dialogue:{title:"Báo cáo tiến độ dự án",lines:[{speaker:"A",text:"今回のシステム移行は、大きなトラブルが起きることなく無事に完了しましたね。",translation:"Đợt chuyển đổi hệ thống lần này đã hoàn thành êm đẹp mà không hề phát sinh sự cố lớn nào nhỉ."},{speaker:"B",text:"ええ、チーム全員が事前に入念なテストを重ねてくれたおかげです。",translation:"Vâng, tất cả là nhờ các thành viên trong nhóm đã kiểm tra kỹ lưỡng nhiều lần từ trước."},{speaker:"A",text:"本当によかったです。この調子で次の案件も進めていきましょう。",translation:"Thật tốt quá rồi. Chúng ta hãy cứ giữ vững phong độ này để triển khai dự án tiếp theo nhé."}]},commonMistake:{wrong:"彼は弱音を吐かないことなく、最後までやり抜いた。",correct:"彼は弱音を吐くことなく、最後までやり抜いた。",why:"Vì bản thân mẫu「ことなく」đã mang ý nghĩa phủ định nên động từ đứng trước phải luôn để ở thể từ điển (V-る), không chia sang thể phủ định「V-ない」."},note:"So với「～ないで」hay「～ずに」,「～ことなく」mang sắc thái trang trọng và tính văn viết cao hơn, thường gặp trong văn bản, báo chí hoặc phát biểu lịch sự chứ không dùng trong giao tiếp suồng sã thường nhật."},{pattern:"～を通じて",meaning:"Thông qua ~ / Trong suốt ~",priority:"common",explanation:"Mẫu ngữ pháp này kết hợp với danh từ, mang hai ý nghĩa chính là 'thông qua...' (chỉ phương tiện, trung gian, cầu nối gián tiếp) hoặc 'trong suốt...' (chỉ sự diễn tiến liên tục trong toàn bộ khoảng thời gian). Khi chỉ phương tiện, mẫu câu thường đi với người, tổ chức, trải nghiệm hoặc phương tiện truyền thông chứ không dùng cho các dụng cụ vật lý cụ thể. Mẫu này mang sắc thái trang trọng, mang tính khách quan và thường được sử dụng trong văn viết hoặc các bối cảnh trang trọng.",examples:[{sentence:"現代では、インターネットを通じて世界中のニュースや情報を瞬時に手に入れることができる。",translation:"Thời nay, chúng ta có thể nắm bắt tin tức và thông tin trên khắp thế giới ngay tức thì thông qua Internet."},{sentence:"この地域は年間を通じて温暖な気候に恵まれており、多くの観光客が訪れる。",translation:"Khu vực này được ưu đãi với khí hậu ấm áp quanh năm (trong suốt cả năm), thu hút rất nhiều khách du lịch ghé thăm."}],dialogue:{title:"Cơ hội giao lưu văn hóa",lines:[{speaker:"A",text:"日本の文化に興味があるのですが、何か良い学び方はありますか。",translation:"Tôi rất quan tâm đến văn hóa Nhật Bản, bạn có cách học nào hay không?"},{speaker:"B",text:"地域の国際交流イベントを通じて、実際に現地の人と話してみるのがおすすめですよ。",translation:"Tôi khuyên bạn nên thử trò chuyện thực tế với người bản xứ thông qua các sự kiện giao lưu quốc tế ở địa phương."},{speaker:"A",text:"なるほど、実際に体験しながら交流を深めるのが一番ですね。",translation:"Ra là vậy, vừa trải nghiệm thực tế vừa thắt chặt quan hệ giao lưu là tốt nhất nhỉ."}]},commonMistake:{wrong:"鉛筆を通じて、日本語で手紙を書きました。",correct:"鉛筆で、日本語で手紙を書きました。",why:"「～を通じて」chỉ dùng cho phương tiện/cầu nối trừu tượng hoặc gián tiếp, không dùng cho dụng cụ hay công cụ tác động vật lý trực tiếp (trường hợp này phải dùng trợ từ 「で」)."},note:"Mẫu「～を通じて」và「～を通して」gần như tương đồng về ngữ nghĩa, nhưng「～を通じて」thường trang trọng hơn và nhấn mạnh quá trình diễn ra một cách tự nhiên, gián tiếp."},{pattern:"～を通して",meaning:"Thông qua ~ / Trong suốt",priority:"common",explanation:'Mẫu câu 「～を通して」 có hai ý nghĩa chính: diễn tả hành động được thực hiện gián tiếp "thông qua" một trung gian, phương tiện, trải nghiệm; hoặc diễn tả trạng thái kéo dài "trong suốt" một khoảng thời gian. Khi mang nghĩa "thông qua", mẫu nhấn mạnh việc đối tượng đứng trước đóng vai trò làm cầu nối chứ người nói không tương tác trực tiếp. Dạng bổ nghĩa cho danh từ đi sau là 「～を通した＋N」 và thường mang sắc thái trang trọng, lịch sự.',examples:[{sentence:"留学生活を通して、異文化を尊重することの大切さを学びました。",translation:"Thông qua cuộc sống du học, tôi đã học được tầm quan trọng của việc tôn trọng các nền văn hóa khác biệt."},{sentence:"この高原リゾートは、四季を通して多くの観光客で賑わっています。",translation:"Khu nghỉ dưỡng trên cao nguyên này nhộn nhịp khách du lịch trong suốt cả bốn mùa."}],dialogue:{title:"Mở rộng mối quan hệ",lines:[{speaker:"A",text:"地域のボランティア活動を通して、世代を超えたたくさんの友人に出会えました。",translation:"Thông qua các hoạt động tình nguyện tại địa phương, tôi đã gặp gỡ được rất nhiều người bạn ở mọi lứa tuổi."},{speaker:"B",text:"それは素晴らしいですね！私も何か新しい活動に参加してみようかな。",translation:"Thế thì tuyệt vời quá nhỉ! Chắc tôi cũng thử tham gia hoạt động mới nào đó xem sao."},{speaker:"A",text:"ぜひおすすめします。視野も広がって本当にいい経験になりますよ。",translation:"Rất khuyến khích bạn đấy. Tầm nhìn vừa được mở rộng mà lại là một trải nghiệm thực sự bổ ích nữa."}]},commonMistake:{wrong:"毎日、バスを通して会社に通っています。",correct:"毎日、バスで会社に通っています。",why:"「～を通して」 chỉ dùng cho phương tiện trung gian gián tiếp hoặc trừu tượng (như người kết nối, trải nghiệm), không dùng cho phương tiện giao thông hoặc dụng cụ thao tác trực tiếp."},note:"「～を通して」 và 「～を通じて」 về cơ bản đồng nghĩa và có thể thay thế cho nhau, nhưng 「～を通して」 thường gợi sắc thái có sự tác động chủ động của chủ thể hơn."},{pattern:"～ともなく",meaning:"Vô thức / Không chủ tâm ~ mà",priority:"common",explanation:"Mẫu câu này diễn tả một hành vi được thực hiện một cách vô thức, lơ đãng, không hề có chủ đích hay sự tập trung có ý thức ngay từ đầu. Cấu trúc thường đi với các động từ chỉ nhận thức, tri giác như 見る (nhìn), 聞く (nghe), 考える (suy nghĩ) và thường lặp lại chính động từ đó ở vế sau dạng 「V-る + ともなく + V-ている／V-ると」. Vế sau của câu thường là một sự việc, phát hiện bất ngờ hoặc cảm xúc nảy sinh trong khoảnh khắc lơ đãng đó.",examples:[{sentence:"電車の中で外の景色を眺めるともなく眺めていたら、昔住んでいたアパートが目に入った。",translation:"Khi đang lơ đãng ngắm nhìn phong cảnh bên ngoài trên tàu điện mà chẳng hề chú tâm, tôi bỗng nhìn thấy căn hộ mình từng sống ngày xưa."},{sentence:"カフェで隣の席の会話を聞くともなく聞いていたら、自分の会社の名前が出てきて驚いた。",translation:"Trong quán cà phê, khi vô tình nghe loáng thoáng cuộc trò chuyện của bàn bên cạnh mà không chủ ý, tôi giật mình khi nghe thấy tên công ty mình."}],dialogue:{title:"Phút giây lơ đãng",lines:[{speaker:"A",text:"さっきからぼんやりとテレビを見るともなく見ていたんだけど、あの速報は本当なのかな。",translation:"Nãy giờ tớ cứ ngồi nhìn màn hình TV một cách vô thức, không biết tin nóng đó liệu có thật không nhỉ."},{speaker:"B",text:"えっ、どのニュース？私もパソコン作業をしながらだったから全然気づかなかったよ。",translation:"Hả, tin tức nào thế? Tớ cũng mải làm việc trên máy tính nên hoàn toàn không để ý."},{speaker:"A",text:"人気俳優が電撃結婚したっていうニュースだよ。驚いちゃった。",translation:"Tin diễn viên nổi tiếng bất ngờ kết hôn đấy. Làm tớ bất ngờ ghê."}]},commonMistake:{wrong:"明日の大事な会議のために、資料を集中して読むともなく読んだ。",correct:"明日の大事な会議のために、資料を集中してしっかり読んだ。",why:"Mẫu「～ともなく」chỉ dùng cho hành động bâng quơ, không chủ ý, nên không thể kết hợp với các từ mang tính tập trung cao độ và có mục đích rõ ràng như「集中して」."},note:"Cần phân biệt cách dùng lặp động từ diễn tả hành động vô thức (như「見るともなく」) với cách kết hợp cùng từ nghi vấn để chỉ sự bất định, mơ hồ như「どこからともなく」(không biết từ đâu) hay「いつからともなく」(từ bao giờ không hay)."},{pattern:"～ともなしに",meaning:"Không chủ ý ~ mà (biến thể)",priority:"common",explanation:"Mẫu ngữ pháp này diễn tả hành động được thực hiện một cách bâng quơ, vô định, không có chủ ý hay mục đích rõ ràng ngay từ đầu. Thường kết hợp với các động từ chỉ tri giác, nhận thức như 見る (nhìn), 聞く (nghe), 考える (nghĩ), 眺める (ngắm), 歩く (đi dạo). Trong câu, mẫu này rất hay lặp lại cùng một động từ theo cấu trúc 「V-る + ともなしに + V-ている/ていたら」 để dẫn ra một sự việc bất ngờ nhận thấy trong lúc lơ đãng.",examples:[{sentence:"休日の午後、窓の外の景色を眺めるともなしに眺めていたら、ふと懐かしい友人の顔が脳裏に浮かんだ。",translation:"Chiều ngày nghỉ, tôi ngồi bâng quơ ngắm nhìn cảnh vật ngoài cửa sổ thì khuôn mặt người bạn năm nào bỗng hiện lên trong tâm trí."},{sentence:"電車の中で隣の乗客の会話を聞くともなしに聞いていたら、自分の母校の話が出てきて驚いた。",translation:"Đang ngồi trên tàu lơ đãng nghe lõm bõm cuộc trò chuyện của hành khách bên cạnh thì bất ngờ nghe họ nhắc đến trường cũ của mình."}],dialogue:{title:"Nghỉ ngơi lúc giải lao",lines:[{speaker:"A",text:"さっきからスマホの画面を見るともなしに眺めているけど、何か気になることでもあるの？",translation:"Nãy giờ thấy cậu cứ lơ đãng nhìn vào màn hình điện thoại, có chuyện gì làm cậu bận tâm à?"},{speaker:"B",text:"いや、特に何を見るわけでもないんだけど、頭がぼーっとしててね。",translation:"Không, tớ cũng chẳng định xem cái gì cụ thể đâu, chỉ là đầu óc đang hơi đơ đơ chút thôi."},{speaker:"A",text:"そっか。最近残業続きだったし、少し目を休めたほうがいいよ。",translation:"Vậy à. Dạo này tăng ca liên tục rồi, cậu nên nhắm mắt nghỉ ngơi một chút đi."}]},commonMistake:{wrong:"来週の試験に合格するために、教科書を読むともなしに一生懸命読んだ。",correct:"来週の試験に合格するために、教科書を集中して一生懸命読んだ。",why:"「～ともなしに」diễn tả hành động làm vô thức, không tập trung, nên không thể dùng cho hành động có chủ đích rõ ràng và nỗ lực cao như「一生懸命」hay「試験に合格するために」."},note:"Ngoài việc đi với động từ, mẫu này còn có biến thể 「～ともなく」 và có thể kết hợp với từ để hỏi (どこからともなく, いつからともなく...) để chỉ sự việc diễn ra từ một nguồn gốc/thời điểm mơ hồ, không rõ ràng."}],129:[{pattern:"～に限って",meaning:"Chỉ ~, không ai khác (thường tiêu cực)",priority:"core",explanation:'Mẫu ngữ pháp 「～に限って」 kết hợp trực tiếp với danh từ, mang ý nghĩa "chính/chỉ những ai hoặc trường hợp như... thì lại thường (xảy ra điều tiêu cực)". Mẫu câu này được dùng khi người nói muốn nhấn mạnh sự mỉa mai, trớ trêu, bất mãn hoặc phê phán một đối tượng có đặc điểm cụ thể nào đó. Vế sau của câu hầu như luôn đi kèm với những hành động, thói quen hoặc tình trạng tiêu cực, không mong muốn.',examples:[{sentence:"自分で何も行動しない人に限って、他人の努力や挑戦を批判したがるものだ。",translation:"Chính những kẻ bản thân chẳng chịu hành động gì thì lại rất hay thích chỉ trích nỗ lực và sự cố gắng của người khác."},{sentence:"大事なプレゼンがある日に限って、目覚まし時計が鳴らずに寝坊してしまった。",translation:"Cứ đúng vào cái ngày có buổi thuyết trình quan trọng thì đồng hồ báo thức lại không kêu khiến tôi bị ngủ quên mất."}],dialogue:{title:"Than phiền trong công việc",lines:[{speaker:"A",text:"佐藤さん、また会議に遅刻してきたよ。いつも偉そうなことを言っているのに。",translation:"Anh Sato lại đến muộn cuộc họp rồi. Rõ ràng bình thường toàn lên mặt nói đạo lý."},{speaker:"B",text:"本当だね。口先だけで仕事ができない人に限って、他人の文句ばかり言うんだから困るよ。",translation:"Công nhận đấy. Chính những người chỉ khua môi múa mép chứ không làm được việc thì lại suốt ngày đi phàn nàn người khác, mệt thật sự."},{speaker:"A",text:"全くだよ。周りに迷惑をかけていることに少しは気づいてほしいよね。",translation:"Đúng thế thật. Ước gì anh ta nhận thức được bản thân đang làm phiền người xung quanh một chút."}]},commonMistake:{wrong:"お金持ちの人に限り、お金の使い方にとてもケチだ。",correct:"お金持ちの人に限って、お金の使い方にとてもケチだ。",why:"Mẫu 「～に限り」 chỉ dùng trong văn bản thông báo hoặc quy định để giới hạn phạm vi áp dụng (như khuyến mãi, đối tượng tham gia), còn khi diễn tả sự trớ trêu, mỉa mai hay định kiến tiêu cực về một đối tượng thì bắt buộc phải dùng 「～に限って」."},note:"Bên cạnh nghĩa phê phán đối tượng tiêu cực, 「～に限って」 còn rất hay dùng để than thở về sự trùng hợp xui xẻo (Cứ đúng lúc đặc biệt/không có sự chuẩn bị thì lại gặp chuyện đen đủi)."},{pattern:"～をもちまして",meaning:"Kể từ ~ này (trang trọng nhất)",priority:"common",explanation:"Mẫu câu 「～をもちまして」 (dạng lịch sự trang trọng của 「～をもって」) đi kèm với danh từ chỉ mốc thời gian hoặc sự việc, mang ý nghĩa là lấy thời điểm đó làm mốc để kết thúc một việc gì đó. Mẫu này có sắc thái cực kỳ trang trọng và tính nghi thức cao, thường được dùng trong các thông báo kinh doanh, thư từ chính thức hoặc lời phát biểu bế mạc sự kiện. Thông thường, vế sau sẽ đi cùng các động từ biểu thị sự kết thúc như 終了する (kết thúc), 締め切る (đóng/hết hạn), 閉会する (bế mạc).",examples:[{sentence:"本日の午後5時をもちまして、今年度の採用エントリーの受付を締め切らせていただきます。",translation:"Kể từ 5 giờ chiều hôm nay, chúng tôi xin phép chính thức đóng cổng tiếp nhận hồ sơ ứng tuyển của niên khóa này."},{sentence:"当店は、今月末日をもちまして閉店することとなりました。長年のご愛顧に心より感謝申し上げます。",translation:"Cửa hàng chúng tôi sẽ đóng cửa kể từ ngày cuối cùng của tháng này. Xin chân thành cảm ơn sự ủng hộ của quý khách trong suốt những năm qua."}],dialogue:{title:"Bế mạc hội thảo quốc tế",lines:[{speaker:"A",text:"皆様、本日はご多忙のところご参加いただき誠にありがとうございました。これをもちまして、本日のシンポジウムを閉会いたします。",translation:"Xin chân thành cảm ơn quý vị đã dành thời gian quý báu tham dự ngày hôm nay. Đến đây, tôi xin phép được bế mạc buổi hội thảo chuyên đề ngày hôm nay."},{speaker:"B",text:"大変有意義な議論ができて勉強になりました。お疲れ様でした。",translation:"Tôi đã học hỏi được rất nhiều từ những cuộc thảo luận vô cùng ý nghĩa. Mọi người vất vả rồi."},{speaker:"A",text:"そう言っていただけて光栄です。また次回の開催時にもぜひお越しください。",translation:"Được anh nói vậy chúng tôi rất vinh hạnh. Rất mong lại được đón tiếp anh trong lần tổ chức tới."}]},commonMistake:{wrong:"今日をもちまして、毎日運動することにしました。",correct:"今日から、毎日運動することにしました。",why:"「～をもちまして」 là cách nói mang tính nghi thức, công cộng và thường dùng khi kết thúc một sự kiện/thời hạn, tuyệt đối không dùng cho các kế hoạch, thói quen hay sinh hoạt cá nhân thông thường."},note:"So với 「～をもって」, dạng 「～をもちまして」 trang trọng hơn và hầu như chỉ dùng trong văn nói mang tính diễn văn, phát biểu tại chỗ hoặc thông cáo chính thức gửi khách hàng."},{pattern:"～ゆえに",meaning:"Vì ~ / Do ~ (văn viết trang trọng)",priority:"common",explanation:'Mẫu 「～ゆえに」 có nghĩa là "bởi vì / do...", dùng để nêu nguyên nhân, lý do dẫn đến một kết quả hoặc tình trạng tương ứng. Đây là mẫu ngữ pháp mang sắc thái văn viết trang trọng, cổ kính và mang tính văn chương cao, thường xuất hiện trong các bài luận, tác phẩm văn học, thư từ nghi thức hoặc các phát biểu mang tính triết lý. Mẫu này không dùng trong giao tiếp sinh hoạt thường nhật hay các tình huống đời thường thông thường.',examples:[{sentence:"若さゆえに、当時は周囲の親身な助言に耳を傾けることができなかった。",translation:"Chính vì sự nông nổi của tuổi trẻ mà hồi đó tôi đã không thể lắng nghe những lời khuyên chân thành từ mọi người xung quanh."},{sentence:"国民の信頼を裏切る行為をしたゆえに、その閣僚は辞任に追い込まれた。",translation:"Bởi vì đã thực hiện hành vi phản bội lòng tin của người dân, vị bộ trưởng đó đã bị đẩy vào bước đường phải từ chức."}],dialogue:{title:"Họp đánh giá dự án",lines:[{speaker:"A",text:"今回のプロジェクトが難航したのは、事前の市場調査が不十分であったゆえに生じた結果だと考えられます。",translation:"Tôi cho rằng việc dự án lần này gặp khó khăn là kết quả phát sinh do khâu nghiên cứu thị trường trước đó chưa đầy đủ."},{speaker:"B",text:"おっしゃる通りです。見通しが甘かったと言わざるを得ませんね。",translation:"Đúng như anh nói. Chúng ta không thể không thừa nhận rằng việc dự tính ban đầu còn quá chủ quan."},{speaker:"A",text:"はい。しかし失敗を恐れるがゆえに歩みを止めるのではなく、この教訓を次の開発に活かしましょう。",translation:"Vâng. Tuy nhiên không phải vì sợ thất bại mà dừng bước, chúng ta hãy áp dụng bài học này vào đợt phát triển tiếp theo."}]},commonMistake:{wrong:"有名人だゆえに、私生活での自由がほとんどない。",correct:"有名人であるゆえに、私生活での自由がほとんどない。",why:"Khi kết hợp với Danh từ hoặc Tính từ đuôi な, ngữ pháp này phải dùng dạng 「であるゆえに」 hoặc 「Danh từ + (の)ゆえに」, tuyệt đối không gắn với 「だゆえに」."},note:"「～ゆえに」 có thể lược bỏ 「に」 thành 「～ゆえ」 hoặc dùng bổ nghĩa cho danh từ ở dạng 「～ゆえの＋Danh từ」 (ví dụ: 若さゆえの過ち - sai lầm của tuổi trẻ)."},{pattern:"～ゆえ",meaning:"Vì ~ / Do ~ (biến thể ngắn)",priority:"common",explanation:'「～ゆえ（に）」mang ý nghĩa "vì / do...", dùng để nêu lý do, nguyên nhân dẫn đến một kết quả hoặc tình trạng phía sau. Đây là cách diễn đạt mang phong cách văn viết cổ, trang trọng và kiểu cách hơn nhiều so với「～から」hay「～ため」. Mẫu câu này thường xuất hiện trong văn bản chính thức, thư từ trang trọng, tác phẩm văn học, hoặc khi biểu đạt những nguyên nhân mang tính định mệnh, sâu xa.',examples:[{sentence:"初めての海外生活ゆえ、言葉や文化の違いに戸惑うことも多い。",translation:"Do lần đầu sống ở nước ngoài nên tôi còn nhiều bỡ ngỡ trước sự khác biệt về ngôn ngữ và văn hóa."},{sentence:"不慣れな業務ゆえ、皆様には多大なるご迷惑をおかけしましたことを深くお詫び申し上げます。",translation:"Do chưa quen với công việc nên tôi xin gửi lời xin lỗi sâu sắc vì đã gây ra nhiều phiền toái cho mọi người."}],dialogue:{title:"Đánh giá nhân viên mới",lines:[{speaker:"A",text:"田中君は真面目すぎるゆえに、仕事を一人で抱え込んでしまう傾向がありますね。",translation:"Cậu Tanaka vì quá nghiêm túc nên hay có xu hướng tự ôm đồm công việc một mình nhỉ."},{speaker:"B",text:"ええ、責任感が強いのは長所ですが、チームで分担することも学んでほしいですね。",translation:"Vâng, tinh thần trách nhiệm cao là ưu điểm, nhưng tôi cũng muốn cậu ấy học cách phân chia công việc trong nhóm nữa."},{speaker:"A",text:"そうですね。彼が潰れてしまわないよう、周りがうまくサポートしていきましょう。",translation:"Đúng vậy. Chúng ta hãy cùng hỗ trợ phù hợp để cậu ấy không bị quá tải nhé."}]},commonMistake:{wrong:"今日は雨ゆえ、傘を持って友達とカラオケに行きます。",correct:"今日は雨だから、傘を持って友達とカラオケに行きます。",why:"「～ゆえ」mang sắc thái văn viết rất trang trọng, cổ kính nên không dùng cho các nguyên nhân sinh hoạt đời thường hay hội thoại thân mật mà nên dùng「～から」hoặc「～ので」."},note:"Khi bổ nghĩa trực tiếp cho danh từ phía sau, cấu trúc sẽ chuyển thành「～ゆえの + N」, rất hay gặp trong các cụm cố định như「若さゆえの過ち」(sai lầm do tuổi trẻ bột phát)."},{pattern:"～向け",meaning:"Được thiết kế dành cho ~ (có chủ ý)",priority:"common",explanation:"Mẫu ngữ pháp 「～向け」 đi trực tiếp sau danh từ chỉ người hoặc nhóm đối tượng, mang ý nghĩa là được làm ra, thiết kế hoặc định hướng có chủ đích dành riêng cho đối tượng đó. Cấu trúc thường gặp là 「～向けに + Động từ」, 「～向けの + Danh từ」 hoặc kết câu bằng 「～向けだ」. Mẫu câu này rất phổ biến trong kinh doanh, truyền thông nhằm giới thiệu sản phẩm, dịch vụ, tài liệu hoặc chính sách phục vụ một nhóm khách hàng mục tiêu nhất định.",examples:[{sentence:"この日本語学習アプリは、漢字が苦手な欧米人学習者向けに開発されました。",translation:"Ứng dụng học tiếng Nhật này được phát triển có chủ đích dành riêng cho người học phương Tây gặp khó khăn với chữ Hán."},{sentence:"駅の近くに、一人暮らしの社会人向けのワンルームマンションが新しく建てられた。",translation:"Gần nhà ga, một tòa chung cư mini dành riêng cho người đi làm sống độc thân vừa mới được xây dựng."}],dialogue:{title:"Chọn mua sách nấu ăn",lines:[{speaker:"A",text:"料理を始めたいんだけど、何かおすすめの本はある？",translation:"Tôi muốn bắt đầu tập nấu ăn, bạn có cuốn sách nào hay để giới thiệu không?"},{speaker:"B",text:"これなんかどう？初心者向けに写真付きで分かりやすく書かれているよ。",translation:"Cuốn này thì sao? Nó được viết rất dễ hiểu kèm hình ảnh dành riêng cho người mới bắt đầu đấy."},{speaker:"A",text:"いいね！写真が多いと手順がイメージしやすくて助かるよ。",translation:"Hay quá! Nhiều hình ảnh thì dễ hình dung các bước làm hơn, cảm ơn nhé."}]},commonMistake:{wrong:"このアニメは子ども向きに作られたが、大人にも大人気だ。",correct:"このアニメは子ども向けに作られたが、大人にも大人気だ。",why:"Khi có động từ chỉ hành động tạo ra/sản xuất có chủ đích như 「作る」「開発する」 thì phải dùng 「～向け」, không dùng 「～向き」 vốn chỉ sự phù hợp tự nhiên."},note:"Phân biệt với 「～向き」: 「～向け」 nhấn mạnh ý đồ và mục đích của người tạo ra sản phẩm/dịch vụ, còn 「～向き」 chỉ tính chất phù hợp, vừa vặn một cách tự nhiên với ai đó."}],130:[{pattern:"～として",meaning:"Với tư cách là, được coi là",priority:"core",explanation:'Mẫu ngữ pháp 「～として」 đi trực tiếp sau danh từ để biểu thị tư cách, vai trò, lập trường, chức danh hoặc danh nghĩa của một đối tượng khi thực hiện hành động. Cấu trúc này thường được dịch là "với tư cách là...", "dưới danh nghĩa...", hoặc "được coi là...". Mẫu câu mang sắc thái khách quan, trang trọng, được dùng phổ biến trong cả văn viết học thuật lẫn giao tiếp công việc hàng ngày.',examples:[{sentence:"私は留学生として日本に来て、今年で3年目になります。",translation:"Tôi đến Nhật Bản với tư cách là một du học sinh, tính đến nay đã là năm thứ 3."},{sentence:"富士山は日本の象徴として世界中の人々に広く知られている。",translation:"Núi Phú Sĩ được người dân khắp thế giới biết đến rộng rãi như một biểu tượng của Nhật Bản."}],dialogue:{title:"Lời khuyên của tiền bối",lines:[{speaker:"A",text:"先輩、今回のプロジェクトでリーダーとして何に一番気をつけるべきでしょうか。",translation:"Tiền bối ơi, với tư cách là trưởng nhóm trong dự án lần này, em nên chú ý nhất đến điều gì ạ?"},{speaker:"B",text:"メンバー全員の意見をしっかり聞くことが一番大切だと思うよ。",translation:"Anh nghĩ điều quan trọng nhất là phải lắng nghe kỹ ý kiến của tất cả các thành viên."},{speaker:"A",text:"わかりました。責任を持って最後まで頑張ります。",translation:"Em hiểu rồi ạ. Em sẽ nỗ lực làm việc với tinh thần trách nhiệm cao nhất đến cùng."}]},commonMistake:{wrong:"私として、この問題はとても難しいです。",correct:"私にとって、この問題はとても難しいです。",why:'Khi muốn diễn đạt góc nhìn, cảm nhận hay đánh giá chủ quan ("đối với tôi thì..."), phải dùng 「～にとって」 chứ không dùng 「～として」 (vốn chỉ tư cách, danh nghĩa).'},note:"Cần lưu ý phân biệt 「～として」 (đứng trên danh nghĩa/vai trò hành động) với 「～にとって」 (đối tượng nhận định, đánh giá) và 「～にしては」 (vậy mà/thế mà, biểu thị sự bất ngờ so với tiêu chuẩn)."},{pattern:"～において／においては",meaning:"Ở, tại, trong (bối cảnh/lĩnh vực)",priority:"common",explanation:'Mẫu「～において／においては」được dùng để biểu thị địa điểm diễn ra sự kiện, thời kỳ/bối cảnh lịch sử hoặc lĩnh vực/phương diện mà sự việc xảy ra, tương đương với nghĩa "ở, tại, trong" của trợ từ「で」. Mẫu này mang sắc thái trang trọng, tính nghi thức cao, thường xuất hiện trong văn viết, báo cáo, tin tức thời sự hoặc các bài phát biểu chính thức. Khi đứng trước để bổ nghĩa trực tiếp cho một danh từ khác, mẫu này sẽ chuyển thành dạng「～における + Danh từ」.',examples:[{sentence:"現代社会において、AI技術の急速な発展は人々の働き方や生活様式を大きく変えつつある。",translation:"Trong xã hội hiện đại, sự phát triển nhanh chóng của công nghệ AI đang dần làm thay đổi mạnh mẽ cách làm việc và lối sống của con người."},{sentence:"次回の国際環境サミットは、東京国際フォーラムにおいて開催される予定となっております。",translation:"Hội nghị thượng đỉnh môi trường quốc tế lần tới dự kiến sẽ được tổ chức tại Diễn đàn Quốc tế Tokyo."}],dialogue:{title:"Thảo luận về quản lý rủi ro",lines:[{speaker:"A",text:"ビジネスにおいては、予期せぬリスクにどう備えるかが企業の存続を左右しますね。",translation:"Trong kinh doanh, việc chuẩn bị ứng phó với các rủi ro bất ngờ như thế nào sẽ quyết định sự sống còn của doanh nghiệp nhỉ."},{speaker:"B",text:"ええ、特に新規市場への参入時は迅速かつ柔軟な意思決定が求められます。",translation:"Vâng, đặc biệt là khi gia nhập thị trường mới thì đòi hỏi phải đưa ra quyết định nhanh chóng và linh hoạt."},{speaker:"A",text:"そのためにも、社内における情報共有の体制を早急に見直す必要がありますね。",translation:"Cũng vì lý do đó, chúng ta cần nhanh chóng rà soát lại cơ chế chia sẻ thông tin trong nội bộ công ty."}]},commonMistake:{wrong:"昨日は学食において友達と一緒に昼ご飯を食べました。",correct:"昨日は学食で友達と一緒に昼ご飯を食べました。",why:"「～において」mang sắc thái trang trọng nên không dùng cho các hành động sinh hoạt đời thường cá nhân như ăn cơm hay mua sắm; những trường hợp này bắt buộc phải dùng trợ từ「で」."},note:"Cần lưu ý phân biệt với trợ từ「で」:「～において」chỉ dùng trong bối cảnh trang trọng/văn viết và không dùng để chỉ công cụ, phương tiện hay nguyên nhân như trợ từ「で」."},{pattern:"～をはじめ（として）",meaning:"Bắt đầu từ, đại diện là, tiêu biểu là",priority:"common",explanation:'Mẫu ngữ pháp này dùng để đưa ra một ví dụ tiêu biểu, đại diện nhất trước tiên, theo sau là những đối tượng khác cùng loại thuộc một tập hợp rộng lớn. Cấu trúc mang ý nghĩa "trước hết phải kể đến...", "tiêu biểu/đại diện là...". Mẫu câu này thường được sử dụng trong các bài phát biểu, văn viết trang trọng hoặc các bản tin mang tính thông báo công khai.',examples:[{sentence:"富士山をはじめとして、日本には世界に誇れる素晴らしい自然がたくさんあります。",translation:"Tiêu biểu là núi Phú Sĩ, ở Nhật Bản có rất nhiều danh lam thắng cảnh tuyệt vời đáng tự hào với thế giới."},{sentence:"今回のプロジェクトは、IT部門をはじめとする各部署の協力のおかげで無事に完了しました。",translation:"Dự án lần này đã hoàn thành thuận lợi nhờ vào sự hợp tác của các phòng ban, trước hết phải kể đến bộ phận IT."}],dialogue:{title:"Địa điểm du lịch nổi tiếng",lines:[{speaker:"A",text:"ベトナム旅行に行くなら、ハロン湾をはじめとする有名な世界遺産は絶対に見ておいたほうがいいですよ。",translation:"Nếu đi du lịch Việt Nam thì nhất định bạn nên đi xem các di sản thế giới nổi tiếng, tiêu biểu như vịnh Hạ Long đấy."},{speaker:"B",text:"ハロン湾ですね！写真で見たことがあって、一度行ってみたいと思っていました。",translation:"Vịnh Hạ Long nhỉ! Tôi từng thấy qua ảnh rồi và đã luôn muốn đến thử một lần."},{speaker:"A",text:"景色が本当に素晴らしいので、きっと忘れられない思い出になりますよ。",translation:"Phong cảnh thực sự tuyệt vời nên chắc chắn sẽ là một kỷ niệm khó quên đấy."}]},commonMistake:{wrong:"来週月曜日をはじめとして、新しい研修プログラムが始まります。",correct:"来週月曜日から、新しい研修プログラムが始まります。",why:"「～をはじめ」chỉ dùng để nêu ra ví dụ tiêu biểu trong một tập hợp sự vật/người, không dùng để chỉ mốc thời gian bắt đầu của một sự việc."},note:"Vế câu đi sau「～をはじめ」thường xuất hiện các từ ngữ chỉ số nhiều hoặc phạm vi bao quát như「多く」「様々」「各地」「全員」để làm rõ tổng thể."},{pattern:"～について／に関して",meaning:"Về, liên quan đến (chủ đề)",priority:"common",explanation:'Mẫu 「～について／に関して」 được dùng để biểu thị chủ đề, đối tượng mà hành vi, lời nói hoặc suy nghĩ hướng tới, mang nghĩa là "về..." hoặc "liên quan đến...". Cả hai cấu trúc đều đi trực tiếp sau danh từ, khi muốn bổ nghĩa cho danh từ phía sau sẽ đổi thành dạng 「～についてのN」 hoặc 「～に関する／に関してのN」. Trong khi 「について」 được dùng phổ biến cả trong giao tiếp hàng ngày lẫn văn viết, thì 「に関して」 mang sắc thái trang trọng, khách quan và bao hàm phạm vi rộng hơn, thường xuất hiện trong báo cáo, tin tức và môi trường công việc.',examples:[{sentence:"今回の新製品の仕様に関して、何かご質問はございますか。",translation:"Liên quan đến thông số kỹ thuật của sản phẩm mới lần này, quý khách có câu hỏi nào không ạ?"},{sentence:"将来の進路について、両親とじっくり話し合いました。",translation:"Tôi đã trao đổi kỹ lưỡng với bố mẹ về định hướng tương lai."}],dialogue:{title:"Chuẩn bị tài liệu họp",lines:[{speaker:"A",text:"明日の会議で話し合う議題について、事前に資料を確認しておいてください。",translation:"Về các chủ đề sẽ thảo luận trong cuộc họp ngày mai, bạn hãy xem trước tài liệu nhé."},{speaker:"B",text:"分かりました。予算案に関する資料も含まれていますか。",translation:"Tôi hiểu rồi. Trong đó có bao gồm tài liệu liên quan đến dự thảo ngân sách không?"},{speaker:"A",text:"はい、先ほどメールで添付して送りましたので確認をお願いします。",translation:"Có, tôi vừa gửi đính kèm qua email rồi nên nhờ bạn kiểm tra giúp nhé."}]},commonMistake:{wrong:"これはAI技術に関して論文です。",correct:"これはAI技術に関する論文です。",why:"Khi đứng trước để bổ nghĩa trực tiếp cho một danh từ, bắt buộc phải dùng dạng 「～に関するN」 hoặc 「～についてのN」 chứ không thể nối trực tiếp bằng 「に関して」."},note:"「に関して」 trang trọng và có phạm vi bao quát rộng hơn 「について」, đồng thời cần chú ý không dùng mẫu này để biểu thị thái độ hay hành vi tác động trực tiếp lên đối tượng (khi đó phải dùng 「に対して」)."},{pattern:"～に対して／に対する",meaning:"Đối với, hướng tới (đối tượng/phản ứng)",priority:"common",explanation:"Mẫu câu「～に対して／に対する」dùng để biểu thị đối tượng tiếp nhận hành động, thái độ, cảm xúc hoặc phản ứng hướng tới ai/cái gì. Cấu trúc đi trực tiếp sau danh từ với dạng「N + に対して」, còn khi bổ nghĩa cho danh từ phía sau thì dùng「N + に対する + N」. Mẫu này thường mang sắc thái trang trọng, thường xuất hiện trong ngữ cảnh ứng xử, chăm sóc khách hàng, phản hồi ý kiến hoặc nghiên cứu xã hội.",examples:[{sentence:"店員はお客様のクレームに対して、丁寧にお詫びをした。",translation:"Nhân viên cửa hàng đã cúi đầu xin lỗi một cách lịch sự đối với lời phàn nàn của khách hàng."},{sentence:"若者の環境問題に対する関心は年々高まっている。",translation:"Sự quan tâm của giới trẻ đối với vấn đề môi trường đang ngày càng tăng lên qua từng năm."}],dialogue:{title:"Thái độ với nhân viên mới",lines:[{speaker:"A",text:"田中部長は新入社員に対して、いつも親切に指導してくださいますね。",translation:"Trưởng phòng Tanaka luôn hướng dẫn rất tận tình đối với các nhân viên mới nhỉ."},{speaker:"B",text:"ええ、どんな質問に対しても笑顔で答えてくれるので、とても質問しやすいです。",translation:"Vâng, đối với bất kỳ câu hỏi nào chú ấy cũng tươi cười trả lời nên rất dễ hỏi bài."},{speaker:"A",text:"本当に頼りになる上司ですね。私たちも見習いましょう。",translation:"Đúng là một cấp trên đáng tin cậy. Chúng ta cũng phải học tập theo thôi."}]},commonMistake:{wrong:"私に対して、家族が一番大切です。",correct:"私にとって、家族が一番大切です。",why:"Khi thể hiện quan điểm, lập trường hoặc đánh giá mang tính chủ quan (đối với tôi... là quan trọng/khó khăn) thì phải dùng「～にとって」, còn「～に対して」chỉ dùng khi có hành vi/thái độ hướng tới đối tượng."},note:"Cần lưu ý phân biệt với「～にとって」(đứng trên lập trường để đánh giá) và「～について」(nói về đề tài), ngoài ra mẫu này còn một cách dùng khác ở trình độ N2 mang nghĩa so sánh hai vế đối lập."}],131:[{pattern:"～おかげで／おかげか",meaning:"Nhờ (nguyên nhân mang tính tích cực/biết ơn)",priority:"core",explanation:'Mẫu câu này dùng để diễn tả nguyên nhân, lý do dẫn đến một kết quả tốt đẹp, mang hàm ý biết ơn hoặc cảm thấy may mắn (nghĩa là "nhờ có..."). Khi dùng dạng 「～おかげか」, câu mang sắc thái phỏng đoán không chắc chắn ("có lẽ là nhờ..."). Về kết nối, mẫu đi sau thể thông thường (普通形), lưu ý tính từ đuôi な giữ 「な」 và danh từ đi với 「の」.',examples:[{sentence:"毎朝ウォーキングを始めたおかげか、最近体の調子がとても良いです。",translation:"Có lẽ nhờ bắt đầu đi bộ mỗi sáng mà dạo này sức khỏe của tôi rất tốt."},{sentence:"新しいプロジェクトはチーム全員が協力してくれたおかげで、無事に成功しました。",translation:"Dự án mới đã thành công tốt đẹp nhờ có sự chung sức giúp đỡ của tất cả thành viên trong nhóm."}],dialogue:{title:"Đỗ phỏng vấn xin việc",lines:[{speaker:"A",text:"リンさん、第一志望の会社に内定が決まったそうですね！本当におめでとうございます。",translation:"Linh ơi, nghe nói em đã nhận được việc ở công ty nguyện vọng một rồi đúng không! Chúc mừng em nhiều nhé."},{speaker:"B",text:"ありがとうございます。先輩が何度も面接の練習に付き合ってくださったおかげです。",translation:"Em cảm ơn anh. Tất cả là nhờ tiền bối đã nhiều lần dành thời gian luyện phỏng vấn giúp em đấy ạ."},{speaker:"A",text:"いやいや、リンさん自身が最後まで諦めずに努力した結果ですよ。",translation:"Đâu có gì, đó là thành quả từ chính sự nỗ lực không từ bỏ của em đấy chứ."}]},commonMistake:{wrong:"大雨が降ったおかげで、楽しみにしていたサッカーの試合が中止になりました。",correct:"大雨が降ったせいで、楽しみにしていたサッカーの試合が中止になりました。",why:"「～おかげで」 chỉ dùng khi kết quả mang tính tích cực hoặc đáng mừng; trường hợp kết quả xấu/tiêu cực (trận đấu bị hủy) thì phải dùng 「～せいで」 (tại vì/do)."},note:"Ngoài việc dùng để cảm ơn chân thành, trong khẩu ngữ mẫu này đôi khi được dùng với giọng điệu mỉa mai, châm biếm khi ai đó làm hỏng việc dẫn đến kết quả xấu."},{pattern:"～ことから",meaning:"Từ thực tế là, xuất phát từ (căn cứ/lý do)",priority:"common",explanation:"Mẫu ngữ pháp 「～ことから」được dùng để diễn tả lý do, căn cứ dẫn đến một phán đoán, kết quả hoặc giải thích nguồn gốc tên gọi của sự vật, sự việc (nghĩa là: từ thực tế là..., xuất phát từ...). Cấu trúc này kết hợp với thể thông thường (thể ngắn), trong đó danh từ và tính từ đuôi な thường kết hợp với である hoặc な trước ことから. Sắc thái câu mang tính khách quan và trang trọng (thường dùng trong văn viết hoặc tin tức), vế sau không dùng cho các câu thể hiện ý chí, mệnh lệnh hay rủ rê của người nói.",examples:[{sentence:"富士山に形が似ていることから、その山は「小富士」と呼ばれている。",translation:'Xuất phát từ việc có hình dáng giống núi Phú Sĩ, ngọn núi đó được gọi là "Tiểu Phú Sĩ".'},{sentence:"現場に指紋が残っていたことから、警察はすぐに犯人を特定することができた。",translation:"Từ thực tế là dấu vân tay còn lưu lại ở hiện trường, cảnh sát đã có thể nhanh chóng xác định được thủ phạm."}],dialogue:{title:"Nguồn gốc tên quán cà phê",lines:[{speaker:"A",text:"このカフェ、「月影」っていう名前、どこから来たか知ってる？",translation:'Cậu có biết cái tên "Tsukikage" của quán cà phê này bắt nguồn từ đâu không?'},{speaker:"B",text:"夜になると窓から月が綺麗に見えることから、そう名付けられたらしいよ。",translation:"Nghe nói là xuất phát từ việc vào ban đêm nhìn từ cửa sổ thấy trăng rất đẹp nên quán mới được đặt tên như vậy đấy."},{speaker:"A",text:"へえ、そうなんだ！ロマンチックで素敵な理由だね。",translation:"Ồ, ra là vậy à! Lý do lãng mạn và tuyệt vời thật đấy."}]},commonMistake:{wrong:"明日はテストがあることから、今夜は早く寝てください。",correct:"明日はテストがあるから、今夜は早く寝てください。",why:"「～ことから」chỉ nêu căn cứ/nguyên nhân khách quan nên vế sau tuyệt đối không dùng với câu mang tính nhờ vả, mệnh lệnh hay rủ rê (như ～てください, ～ましょう)."},note:"Khác với「から／ので」dùng tự do cho mọi lý do giao tiếp thường ngày,「ことから」mang tính văn viết trang trọng và đặc biệt chuyên dùng cho các mẫu giải thích nguồn gốc tên gọi (kết hợp với ～と呼ばれている／～と名付けられた)."},{pattern:"～ために（原因）",meaning:"Vì, do (nguyên nhân dẫn đến kết quả)",priority:"common",explanation:"Mẫu câu 「～ために」 dùng để biểu thị nguyên nhân, lý do trực tiếp dẫn đến một sự việc, hiện tượng hoặc kết quả khách quan. Ngữ pháp này mang sắc thái trang trọng, có tính văn viết cao, thường được dùng trong các thông báo công cộng, bản tin thời sự hoặc báo cáo công việc. Điểm mấu chốt là vế sau diễn tả kết quả thực tế đã xảy ra hoặc ngoài tầm kiểm soát, tuyệt đối không đi kèm với các cách nói thể hiện ý chí, mệnh lệnh, rủ rê hay nguyện vọng cá nhân.",examples:[{sentence:"大雨のために、近くの川の水位が急激に上がっている。",translation:"Do mưa lớn, mực nước con sông gần đây đang dâng lên nhanh chóng."},{sentence:"システムに障害が発生したために、一時的にサービスがご利用いただけません。",translation:"Do hệ thống phát sinh sự cố, quý khách tạm thời không thể sử dụng dịch vụ."}],dialogue:{title:"Đi làm muộn vì động đất",lines:[{speaker:"A",text:"今朝、地震のために電車が大幅に遅れて、遅刻してしまいました。",translation:"Sáng nay do động đất nên tàu điện bị trễ nghiêm trọng, khiến tôi bị muộn giờ làm mất."},{speaker:"B",text:"そうだったんですね。怪我はありませんでしたか。",translation:"Ra là vậy à. Bạn có bị thương hay sao không?"},{speaker:"A",text:"はい、幸い怪我はありませんでしたが、とても焦りました。",translation:"Vâng, may mà tôi không sao, nhưng lúc đó cuống hết cả lên."}]},commonMistake:{wrong:"風邪を引いたために、今日は早く帰らせてください。",correct:"風邪を引いたので、今日は早く帰らせてください。",why:"Vế sau của 「～ために」 chỉ nguyên nhân không thể đi cùng với các câu xin phép, nhờ vả hoặc mệnh lệnh như 「～てください」, khi đó phải dùng 「～ので」 hoặc 「～から」."},note:"Cần phân biệt rõ với 「～ために」 chỉ mục đích (vế sau đi cùng hành động có chủ ý), còn 「～ために」 chỉ nguyên nhân thì vế sau luôn là tình trạng, kết quả xảy ra tự nhiên ngoài tầm kiểm soát."},{pattern:"～せいで／せいか",meaning:"Vì lỗi của, do (nguyên nhân mang tính tiêu cực/đổ lỗi)",priority:"common",explanation:'Mẫu ngữ pháp「～せいで」dùng để chỉ nguyên nhân, lý do dẫn đến một kết quả tiêu cực, không mong muốn, thường mang sắc thái trách móc hoặc đổ lỗi ("tại vì...", "do... mà ra nông nỗi này"). Khi dùng biến thể「～せいか」, câu văn mang sắc thái phỏng đoán không chắc chắn ("có lẽ là tại...", "không biết có phải do... hay không"). Mẫu câu kết hợp với thể thông thường (普通形), trong đó tính từ đuôi な giữ nguyên な và danh từ đi kèm với の.',examples:[{sentence:"昨夜遅くまでゲームをしていたせいで、今朝の重要な会議に遅刻してしまった。",translation:"Tại tối qua mải chơi game đến khuya nên sáng nay tôi đã bị trễ cuộc họp quan trọng."},{sentence:"歳のせいか、最近細かい文字を読むのが億劫になってきた。",translation:"Có lẽ do tuổi tác nên dạo này tôi bắt đầu thấy ngại đọc những dòng chữ nhỏ."}],dialogue:{title:"Lý do đi làm muộn",lines:[{speaker:"A",text:"課長、遅れて申し訳ありません。大雨のせいで電車が大幅に遅延してしまって。",translation:"Thưa trưởng phòng, em xin lỗi vì đến muộn. Do mưa lớn nên tàu điện bị hoãn chuyến khá lâu ạ."},{speaker:"B",text:"そうか、大変だったね。事故に巻き込まれなくてよかったよ。",translation:"Vậy à, vất vả cho cậu quá. May mà không bị vướng vào tai nạn nào."},{speaker:"A",text:"はい、ご迷惑をおかけしました。次からは悪天候のせいにする前に、もっと早く家を出るようにします。",translation:"Vâng, em đã làm phiền mọi người rồi. Từ lần sau em sẽ chủ động rời nhà sớm hơn chứ không để đổ lỗi cho thời tiết xấu nữa ạ."}]},commonMistake:{wrong:"先生が熱心に教えてくれたせいで、N1に合格できました。",correct:"先生が熱心に教えてくださったおかげで、N1に合格できました。",why:"「～せいで」chỉ dùng cho kết quả tiêu cực hoặc đổ lỗi, còn với kết quả tốt đẹp cùng lòng biết ơn thì bắt buộc phải dùng「～おかげで」."},note:"Cần chú ý cách nối danh từ phải có の (N＋のせいで) và có thể dùng cụm cố định「〜のせいにする」với nghĩa 'đổ lỗi/đổ thừa cho ai/cái gì'."}],132:[{pattern:"～以上は／以上",meaning:"Khi đã, vì đã (trách nhiệm sau quyết định)",priority:"core",explanation:"Mẫu câu diễn tả ý nghĩa 'Một khi đã... / Vì đã... thì đương nhiên phải...', nhấn mạnh mối quan hệ nhân quả mang tính tất yếu về mặt trách nhiệm hoặc đạo lý. Vế trước nêu lên một sự thật, quyết định hoặc cam kết đã được xác lập (thường đi với thể V-た hoặc Nである). Vế sau luôn thể hiện ý chí, quyết tâm mạnh mẽ, nghĩa vụ hoặc phán đoán tất yếu như 〜べきだ, 〜つもりだ, 〜なければならない.",examples:[{sentence:"このプロジェクトのリーダーを引き受けた以上、最後までやり抜く覚悟です。",translation:"Một khi đã nhận làm trưởng dự án này, tôi xác định tâm lý sẽ nỗ lực hoàn thành đến cùng."},{sentence:"日本への留学を決意した以上は、目標の大学院に合格するまで決して諦めない。",translation:"Một khi đã quyết tâm đi du học Nhật Bản, tôi tuyệt đối sẽ không bỏ cuộc cho tới khi thi đỗ vào trường cao học mục tiêu."}],dialogue:{title:"Trận đấu chung kết",lines:[{speaker:"A",text:"決勝戦まで勝ち進んだ以上、絶対に優勝を目指そう！",translation:"Đã tiến vào tận trận chung kết rồi, chúng ta nhất định phải nhắm tới chức vô địch!"},{speaker:"B",text:"そうだね。相手は強豪だけど、全力を尽くして戦おう。",translation:"Đúng vậy. Dù đối thủ rất mạnh nhưng hãy dốc toàn lực chiến đấu nào."},{speaker:"A",text:"うん、悔いの残らない素晴らしい試合にしよう！",translation:"Ừ, hãy tạo nên một trận đấu tuyệt vời không để lại hối tiếc nhé!"}]},commonMistake:{wrong:"プロの選手以上、ファンの期待に応える義務がある。",correct:"プロの選手である以上、ファンの期待に応える義務がある。",why:"Danh từ khi kết hợp với「以上（は）」bắt buộc phải chia ở dạng「Nである以上」chứ không nối trực tiếp."},note:"So với mẫu đồng nghĩa「〜からには」,「〜以上（は）」mang sắc thái trang trọng hơn và nhấn mạnh nhiều hơn vào nghĩa vụ, trách nhiệm xã hội hoặc lập trường của người nói."},{pattern:"～さえ～ば",meaning:"Chỉ cần ~ là, miễn là ~ thì",priority:"common",explanation:'Mẫu ngữ pháp này dùng để biểu thị ý nghĩa "chỉ cần đáp ứng được một điều kiện tối thiểu này thì kết quả vế sau sẽ thành hiện thực hoặc mọi chuyện sẽ ổn". Cấu trúc này nhấn mạnh tính quyết định của một điều kiện duy nhất và bỏ qua các yếu tố khác. Về cách nối, thường gặp dạng Danh từ + さえ + thể điều kiện (ば/なら) hoặc Động từ thể ます (bỏ ます) + さえすれば.',examples:[{sentence:"体調さえ良ければ、少しぐらい忙しくても頑張れます。",translation:"Chỉ cần sức khỏe tốt thì dù có bận rộn một chút tôi vẫn có thể cố gắng được."},{sentence:"道さえ間違えなければ、ここから30分で駅に着くはずです。",translation:"Chỉ cần không đi nhầm đường thì từ đây chắc mất khoảng 30 phút là tới ga."}],dialogue:{title:"Chuẩn bị bài thuyết trình",lines:[{speaker:"A",text:"明日のプレゼン、うまくいくかすごく不安なんだ。",translation:"Tớ thấy lo quá, không biết buổi thuyết trình ngày mai có suôn sẻ không."},{speaker:"B",text:"毎日あんなに練習したんだから、自信さえ持っていれば大丈夫だよ。",translation:"Cậu đã luyện tập chăm chỉ mỗi ngày rồi, chỉ cần giữ vững sự tự tin là ổn thôi."},{speaker:"A",text:"ありがとう。そう言ってもらえると少し安心したよ。",translation:"Cảm ơn cậu nhé. Nghe cậu nói vậy tớ cũng thấy yên tâm hơn một chút rồi."}]},commonMistake:{wrong:"薬を飲むさえすれば、すぐに風邪が治るわけではありません。",correct:"薬を飲みさえすれば、すぐに風邪が治るわけではありません。",why:"Khi kết hợp với động từ, phải đưa về thể ます rồi bỏ ます trước khi ghép với 「さえすれば」, không dùng trực tiếp thể từ điển (Vる)."},note:"Mẫu「～さえ～ば」nhấn mạnh vào điều kiện tiên quyết mang tính tối thiểu nhất để đạt được kết quả, khác với「～だけで」chỉ đơn thuần giới hạn phạm vi hành động."},{pattern:"～からには／からは",meaning:"Đã làm thì phải, vì đã quyết định làm",priority:"common",explanation:"Mẫu ngữ pháp này mang ý nghĩa 'Một khi đã... thì đương nhiên phải / nhất định sẽ...', dùng để thể hiện quyết tâm, ý chí hoặc tinh thần trách nhiệm cao dựa trên một sự thật hay quyết định đã định sẵn. Vế trước nêu lên tiền đề hoặc sự việc đã trở thành hiện thực, còn vế sau bắt buộc đi cùng các biểu hiện mang tính ý chí, nghĩa vụ, nguyện vọng hoặc kêu gọi như 「～べきだ」, 「～なければならない」, 「～つもりだ」, 「～てください」. Sắc thái câu văn rất dứt khoát, nghiêm túc và thường được dùng trong các tình huống trang trọng, công việc hoặc khi thể hiện lập trường kiên định.",examples:[{sentence:"留学を決意したからには、何としてもJLPT N1に合格してみせる。",translation:"Một khi đã quyết tâm đi du học, tôi nhất định sẽ thi đỗ JLPT N1 cho bằng được."},{sentence:"プロジェクトのリーダーを引き受けたからには、最後まで責任を持ってやり遂げるべきだ。",translation:"Một khi đã nhận làm trưởng dự án thì nên có trách nhiệm hoàn thành đến cùng."}],dialogue:{title:"Chuẩn bị bài thuyết trình",lines:[{speaker:"A",text:"来週の重要なプレゼン、田中さんがメインの発表者を担当するそうですね。",translation:"Nghe nói buổi thuyết trình quan trọng tuần tới anh Tanaka sẽ đảm nhận vai trò người trình bày chính nhỉ."},{speaker:"B",text:"ええ、大役を任されたからには、全力で準備して成功させたいと思っています。",translation:"Vâng, một khi đã được giao trọng trách lớn thì tôi muốn dốc toàn lực chuẩn bị để buổi thuyết trình thành công."},{speaker:"A",text:"応援していますよ。何か手伝えることがあればいつでも声をかけてください。",translation:"Tôi ủng hộ anh hết mình. Nếu có việc gì cần giúp thì anh cứ bảo tôi bất cứ lúc nào nhé."}]},commonMistake:{wrong:"日本に来たからには、毎日日本語を勉強した。",correct:"日本に来たからには、毎日一生懸命日本語を勉強するつもりだ。",why:"Vế sau của 「～からには」 bắt buộc phải là biểu hiện thể hiện ý chí, mục tiêu, nghĩa vụ hoặc lời khuyên (như ～つもりだ, ～べきだ), tuyệt đối không dùng câu trần thuật chỉ đơn thuần kể lại sự việc đã xảy ra trong quá khứ."},note:"「～からは」 là cách nói mang tính văn viết cổ hơn và ít phổ biến trong giao tiếp hiện đại so với 「～からには」, cả hai đều có ý nghĩa và sắc thái tương đồng với mẫu 「～以上（は）」."},{pattern:"～としたら／とすれば／とすると",meaning:"Nếu giả sử, giả định rằng",priority:"common",explanation:"Mẫu câu này dùng để đưa ra một giả định, giả thiết (thường là tình huống không có thật hoặc khó xảy ra ở hiện tại) nhằm bàn luận hoặc suy xét về diễn biến tiếp theo. Trong đó, 「～としたら」thiên về giả thiết phi thực tế và mang tính cảm tính, 「～とすれば」nhấn mạnh vào tiền đề lập luận logic, còn 「～とすると」hướng đến kết quả suy diễn tất yếu kéo theo. Vế sau không dùng cho sự thật đã diễn ra trong quá khứ mà đi với phán đoán, ý kiến, nguyện vọng hoặc câu hỏi giả định.",examples:[{sentence:"もし明日から一週間の休みが取れるとしたら、どこへ旅行に行きたいですか。",translation:"Nếu giả sử được nghỉ một tuần kể từ ngày mai, bạn muốn đi du lịch ở đâu?"},{sentence:"新商品の発売を来月に延期するとすれば、予算の再調整が必要になります。",translation:"Giả sử hoãn ngày ra mắt sản phẩm mới sang tháng sau thì chúng ta sẽ cần phải điều chỉnh lại ngân sách."}],dialogue:{title:"Nguyện vọng chuyển phòng ban",lines:[{speaker:"A",text:"もし他の部署へ異動できるとしたら、どこを希望しますか。",translation:"Nếu giả sử có thể chuyển sang phòng ban khác, anh sẽ nguyện vọng vào đâu?"},{speaker:"B",text:"企画部ですね。新しいプロジェクトの立ち上げに挑戦してみたいです。",translation:"Phòng Kế hoạch đấy. Tôi muốn thử sức với việc khởi động các dự án mới."},{speaker:"A",text:"いいですね。今の経験を生かせば、きっと即戦力として活躍できますよ。",translation:"Hay quá nhỉ. Nếu tận dụng kinh nghiệm hiện tại thì chắc chắn anh sẽ phát huy năng lực ngay được đấy."}]},commonMistake:{wrong:"留学するとすると、アメリカに行きたいです。",correct:"留学するとしたら、アメリカに行きたいです。",why:"Khi vế sau thể hiện ý chí, nguyện vọng (như ～たい) thì phải dùng「～としたら」hoặc「～とすれば」chứ không dùng「～とすると」do đặc tính đuôi「と」không đi cùng ý chí hay mệnh lệnh."},note:"「～とすると」thường dẫn tới một hệ quả tính toán hoặc kết luận logic tất yếu, do đó vế sau tuyệt đối không dùng các mẫu câu thể hiện ý chí, nguyện vọng (～たい), mệnh lệnh (～てください) hay rủ rê (～ましょう)."},{pattern:"～としても",meaning:"Dù cho là, ngay cả nếu (nhượng bộ giả định)",priority:"common",explanation:'Mẫu câu 「～としても」 dùng để biểu thị sự nhượng bộ mang tính giả định, mang nghĩa "dù cho / ngay cả khi giả định là...". Mẫu này kết hợp với thể thông thường (普通形), thường được dùng khi mức độ xảy ra của giả thuyết là rất thấp hoặc chỉ là một khả năng được đặt ra. Vế sau thể hiện lập trường, phán đoán hoặc ý chí của người nói rằng kết luận sẽ không bị lung lay bởi giả định ở vế trước.',examples:[{sentence:"仮にその話が事実だとしても、彼が取った行動を正当化することはできない。",translation:"Giả sử chuyện đó có là sự thật đi chăng nữa, cũng không thể biện minh cho hành động của anh ta."},{sentence:"たとえ試験に失敗したとしても、これまで努力してきた経験は無駄にはならない。",translation:"Dù cho có thi trượt đi nữa, thì những kinh nghiệm nỗ lực từ trước đến nay cũng không hề vô ích."}],dialogue:{title:"Cân nhắc đổi việc",lines:[{speaker:"A",text:"新しい会社から内定をもらったんだけど、残業がかなり多いらしいんだよね。",translation:"Tớ vừa nhận được thông báo trúng tuyển từ công ty mới, nhưng nghe nói ở đó phải tăng ca khá nhiều."},{speaker:"B",text:"たとえ給料が今より上がったとしても、健康を損なうようなら考え直したほうがいいよ。",translation:"Dù cho lương có cao hơn hiện tại đi nữa, nếu tổn hại đến sức khỏe thì cậu nên suy nghĩ lại."},{speaker:"A",text:"そうだね。自分の生活スタイルを一番に考えて決めるよ。",translation:"Ừ, cậu nói đúng. Tớ sẽ ưu tiên lối sống của bản thân lên hàng đầu để quyết định."}]},commonMistake:{wrong:"昨日雨が降ったとしても、マラソン大会は予定通り行われました。",correct:"昨日雨が降ったけれど、マラソン大会は予定通り行われました。",why:"「～としても」chỉ dùng cho tình huống giả định (chưa xảy ra hoặc giả định tương lai), không dùng để thuật lại sự việc đối lập đã thực sự diễn ra trong quá khứ."},note:"So với 「～にしても」, mẫu「～としても」mang tính chất giả định thuần túy mạnh hơn và rất thường đi kèm với các phó từ như 「たとえ」「仮に」「いくら」."}],133:[{pattern:"～にしては",meaning:"So với, xét theo (kết quả bất ngờ so với tiêu chuẩn)",priority:"core",explanation:'Mẫu câu 「～にしては」 được dùng để diễn tả một sự việc, kết quả thực tế không tương xứng hoặc bất ngờ so với tiêu chuẩn, định kiến thông thường được nêu ở vế trước ("so với... thì..."). Ngữ pháp này kết hợp với Danh từ hoặc Thể thông thường (lưu ý lược bỏ だ với Danh từ và Tính từ đuôi な). Vế sau thể hiện một sự thật cụ thể gây ngạc nhiên cho người nói, tuyệt đối không dùng với câu mang tính ý chí, mệnh lệnh hay dự định tương lai.',examples:[{sentence:"彼は日本に来てまだ半年にしては、日本語がとても流暢だ。",translation:"So với việc mới đến Nhật được nửa năm thì tiếng Nhật của anh ấy rất lưu loát."},{sentence:"このコートは3000円にしては、生地がしっかりしていて暖かい。",translation:"Chiếc áo khoác này so với mức giá 3.000 yên thì chất vải rất dày dặn và ấm áp."}],dialogue:{title:"Thử quán ăn mới",lines:[{speaker:"A",text:"このラーメン、500円にしては具がたくさん入っていて美味しいですね。",translation:"Tô mì ramen này so với giá 500 yên thì nhiều topping mà ngon ghê nhỉ."},{speaker:"B",text:"そうですね！最近の物価高を考えると、信じられないコスパですよ。",translation:"Đúng thế! Nghĩ đến thời buổi bão giá gần đây thì đúng là chất lượng vượt trội so với giá tiền."},{speaker:"A",text:"ええ、今度またほかのメニューも食べに来ましょう。",translation:"Ừ, lần tới chúng ta lại đến thử các món khác nữa nhé."}]},commonMistake:{wrong:"彼は外国人だにしては、日本のマナーをよく知っている。",correct:"彼は外国人にしては、日本のマナーをよく知っている。",why:"Khi kết hợp với Danh từ hoặc Tính từ đuôi な, không giữ nguyên 「だ」 mà phải bỏ 「だ」 rồi nối trực tiếp với 「にしては」."},note:"Khác với 「～わりに（は）」 thường đi kèm danh từ chỉ mức độ chung chung, 「～にしては」 có thể đi trực tiếp với các số liệu, số tuổi hoặc số tiền cụ thể (như 3000円, 5歳, 2月)."},{pattern:"～くせに",meaning:"Dù là, mặc dù ~ thế mà (hàm ý chỉ trích, trách móc)",priority:"common",explanation:"Mẫu ngữ pháp này dùng để diễn tả sự việc ở vế sau trái ngược với điều đương nhiên ở vế trước, mang sắc thái mỉa mai, chỉ trích hoặc bất mãn. Hai vế câu phải cùng chung chủ ngữ và chỉ dùng để nói về người khác (ngôi thứ hai hoặc thứ ba), không dùng cho bản thân. Đi sau thể thông thường của động từ và tính từ đuôi -i, riêng tính từ đuôi -na thêm 「な」 và danh từ đi kèm 「の」.",examples:[{sentence:"自分で何も手伝わないくせに、文句ばかり言っている。",translation:"Bản thân chẳng chịu giúp đỡ gì thế mà cứ luôn mồm cằn nhằn, phàn nàn."},{sentence:"兄はお金がないくせに、また高いゲーム機を買ってきた。",translation:"Anh trai dù chẳng có tiền thế mà lại đi mua máy chơi game đắt tiền về."}],dialogue:{title:"Than phiền về đồng nghiệp",lines:[{speaker:"A",text:"田中さん、パソコンが得意じゃないくせに、ITの専門家ぶっているよね。",translation:"Anh Tanaka rõ ràng chẳng giỏi máy tính thế mà cứ làm ra vẻ chuyên gia IT nhỉ."},{speaker:"B",text:"そうだね。この前も設定を間違えて大騒ぎしていたよ。",translation:"Đúng thế. Hôm trước cũng chỉnh sai cài đặt rồi làm ầm ĩ cả lên."},{speaker:"A",text:"本当に困ったものだね。少しは自覚してほしいよ。",translation:"Thật là hết nói nổi. Mong anh ấy biết tự lượng sức mình một chút."}]},commonMistake:{wrong:"私は日本語が下手なくせに、日本へ留学することにしました。",correct:"私は日本語が下手なのに、日本へ留学することにしました。",why:"「～くせに」 mang hàm ý mỉa mai, chỉ trích và chỉ dùng cho người khác, không dùng để nói về hoàn cảnh của chính bản thân theo cách trung tính."},note:"Khác với 「～のに」 chỉ thể hiện sự bất ngờ hay tiếc nuối mang tính khách quan, 「～くせに」 luôn chứa đựng cảm xúc tiêu cực, coi thường hoặc bực bội của người nói."},{pattern:"～にもかかわらず",meaning:"Mặc dù, bất chấp (kết quả trái ngược kỳ vọng)",priority:"common",explanation:'Mẫu「～にもかかわらず」mang ý nghĩa "mặc dù / bất chấp sự thật rằng...", diễn tả một kết quả hoặc sự việc diễn ra trái ngược hoàn toàn với kỳ vọng hiển nhiên từ vế trước. Mẫu câu kết hợp trực tiếp với thể thông thường (普通形), danh từ (N) hoặc dạng 「である」 đối với danh từ và tính từ đuôi な. Đây là cách diễn đạt mang tính trang trọng, văn viết hoặc phát biểu lịch sự, thường nhấn mạnh sự bất ngờ, tiếc nuối hoặc khâm phục trước một hiện thực khách quan.',examples:[{sentence:"深夜であるにもかかわらず、多くのエンジニアがサーバーの復旧作業に当たっている。",translation:"Mặc dù đã là đêm muộn, nhiều kỹ sư vẫn đang dốc sức xử lý công việc khắc phục sự cố máy chủ."},{sentence:"悪天候にもかかわらず、スタジアムには満員のサポーターが詰めかけた。",translation:"Bất chấp thời tiết xấu, rất đông cổ động viên vẫn đến lấp đầy cả sân vận động."}],dialogue:{title:"Khai mạc hội thảo",lines:[{speaker:"A",text:"足元の悪い中にもかかわらず、本日はセミナーにご参加いただき誠にありがとうございます。",translation:"Mặc dù thời tiết mưa gió đi lại khó khăn, xin chân thành cảm ơn quý vị đã đến tham dự buổi hội thảo hôm nay."},{speaker:"B",text:"貴重なお話を直接伺える機会ですので、楽しみにして参りました。",translation:"Vì đây là cơ hội quý báu để trực tiếp lắng nghe chia sẻ nên tôi đã rất mong đợi khi đến đây ạ."},{speaker:"A",text:"そう言っていただけて光栄です。どうぞ最後までごゆっくりお聞きください。",translation:"Được quý khách nói vậy chúng tôi rất vinh dự. Kính mời quý khách lắng nghe trọn vẹn chương trình."}]},commonMistake:{wrong:"雨のにもかかわらず、彼は傘も差さずに走って出かけて行った。",correct:"雨にもかかわらず、彼は傘も差さずに走って出かけて行った。",why:"Danh từ nối trực tiếp với 「にもかかわらず」 (hoặc dùng 「であるにもかかわらず」), không thêm trợ từ 「の」 hay 「な」 như khi nối với 「のに」."},note:"So với「～のに」(thiên về văn nói và cảm xúc cá nhân),「～にもかかわらず」mang tính khách quan, trang trọng hơn và vế sau tuyệt đối không dùng để rủ rê, nhờ vả hay mệnh lệnh."},{pattern:"～ながら（も）",meaning:"Dù, mặc dù (nhượng bộ thực tế hiện hữu)",priority:"common",explanation:'Mẫu ngữ pháp này dùng để biểu thị sự nhượng bộ, mang ý nghĩa "tuy/dù... nhưng", diễn tả hai sự việc hoặc trạng thái trái ngược nhau về mặt logic thông thường. Cấu trúc thường kết hợp với tính từ, danh từ hoặc động từ chỉ trạng thái, tâm lý, nhận thức và hai vế thường có cùng một chủ ngữ. Mẫu câu được dùng tự nhiên từ giao tiếp thường ngày đến văn viết, bao gồm nhiều quán ngữ quen thuộc thể hiện sự khiêm tốn hoặc tiếc nuối như 残念ながら, 狭いながらも.',examples:[{sentence:"このカメラは小型ながらも、プロ並みの高画質な写真を撮ることができる。",translation:"Chiếc máy ảnh này tuy nhỏ gọn nhưng vẫn có thể chụp được những bức ảnh chất lượng cao như máy chuyên nghiệp."},{sentence:"彼女は体に悪いと知りながらも、夜遅くにラーメンを食べるのをやめられない。",translation:"Dù biết là có hại cho sức khỏe nhưng cô ấy vẫn không thể bỏ thói quen ăn mì ramen vào đêm muộn."}],dialogue:{title:"Căn nhà mới",lines:[{speaker:"A",text:"田中さん、新しいお家はどうですか。住み心地はいいですか。",translation:"Anh Tanaka, nhà mới thế nào rồi? Ở có thoải mái không?"},{speaker:"B",text:"ええ、狭いながらも日当たりが良くて、とても快適に暮らしていますよ。",translation:"Vâng, tuy hẹp một chút nhưng đón nắng tốt nên sống rất thoải mái."},{speaker:"A",text:"それは良かったですね。今度ぜひ遊びに行かせてください。",translation:"Vậy thì tốt quá. Dịp tới nhất định cho tôi qua chơi nhé."}]},commonMistake:{wrong:"彼は危険だと知るながらも、一人で冬の山に登った。",correct:"彼は危険だと知りながらも、一人で冬の山に登った。",why:"Khi kết hợp với động từ, mẫu này bắt buộc phải chia về dạng ます (bỏ ます) chứ không được ghép trực tiếp với thể nguyên mẫu (thể từ điển)."},note:"Mẫu 「～つつ（も）」 có ý nghĩa nhượng bộ tương tự nhưng chủ yếu chỉ đi với động từ và mang sắc thái văn viết trang trọng, cứng nhắc hơn so với 「～ながら（も）」."}],134:[{pattern:"～以来",meaning:"Kể từ khi, từ lúc ~ đến nay",priority:"core",explanation:'Mẫu「～以来」được dùng để diễn tả ý nghĩa "kể từ một mốc thời điểm hoặc sự kiện trong quá khứ, một trạng thái hoặc hành động đã kéo dài liên tục cho tới tận hiện tại". Mẫu ngữ pháp này kết hợp với động từ thể て (Vて以来) hoặc danh từ chỉ sự kiện/mốc thời gian (N + 以来). Vế sau của câu luôn là hành động hoặc trạng thái tiếp diễn liên tục, không dùng cho sự việc chỉ xảy ra một lần.',examples:[{sentence:"大学を卒業して以来、彼とは一度も連絡を取っていない。",translation:"Kể từ khi tốt nghiệp đại học đến nay, tôi chưa từng liên lạc với anh ấy lần nào."},{sentence:"去年大きな病気をして以来、健康のために毎日野菜を多く食べるようにしている。",translation:"Kể từ sau trận ốm nặng năm ngoái đến nay, tôi luôn cố gắng ăn nhiều rau mỗi ngày vì sức khỏe."}],dialogue:{title:"Gặp lại đồng nghiệp cũ",lines:[{speaker:"A",text:"田中さん、お久しぶりです！転職して以来ですから、もう三年ぶりですね。",translation:"Chào anh Tanaka, lâu quá không gặp! Kể từ khi anh chuyển việc đến nay cũng đã ba năm rồi nhỉ."},{speaker:"B",text:"本当ですね。山田さんも相変わらずお元気そうで何よりです。",translation:"Đúng thế thật. Thấy anh Yamada vẫn khỏe mạnh như trước là tốt rồi."},{speaker:"A",text:"ええ、また今度ゆっくり食事でもしながら近況を話しましょう。",translation:"Vâng, hôm nào chúng mình thong thả đi ăn rồi trò chuyện về tình hình dạo này nhé."}]},commonMistake:{wrong:"今朝起きて以来、ずっと頭が痛い。",correct:"今朝起きてから、ずっと頭が痛い。",why:"「～以来」không dùng cho mốc thời gian quá gần như sáng nay hay hôm qua, trường hợp này phải dùng「～てから」."},note:"Khác với「～てから」có thể dùng cho cả quá khứ gần và các hành động làm nối tiếp nhau theo thứ tự,「～以来」yêu cầu mốc thời gian xảy ra cách hiện tại một khoảng thời gian nhất định và vế sau bắt buộc phải là trạng thái kéo dài liên tục đến nay."},{pattern:"～度に／たびに",meaning:"Mỗi lần, hễ",priority:"common",explanation:'Mẫu ngữ pháp này diễn tả ý nghĩa "mỗi lần... thì luôn..." hoặc "cứ hễ... là lại...", chỉ một hành động hay sự việc hễ xảy ra thì kéo theo một kết quả hoặc cảm xúc tương tự lặp lại. Cấu trúc kết hợp với động từ thể từ điển (Vる) hoặc danh từ đi kèm の (Nの). Mẫu câu thường nhấn mạnh tính quy luật cá nhân hoặc trải nghiệm lặp lại, không dùng cho các thói quen sinh hoạt hiển nhiên hàng ngày.',examples:[{sentence:"母は旅行に行くたびに、家族や近所の人たちにお土産をたくさん買ってくる。",translation:"Mẹ tôi cứ mỗi lần đi du lịch là lại mua rất nhiều quà lưu niệm cho gia đình và hàng xóm."},{sentence:"新入社員の山田さんは、失敗のたびに落ち込んでいるが、確実に成長している。",translation:"Nhân viên mới Yamada cứ mỗi lần thất bại là lại suy sụp, nhưng cậu ấy đang tiến bộ rõ rệt."}],dialogue:{title:"Tâm sự về gia đình",lines:[{speaker:"A",text:"最近、実家に帰るたびに、両親が少しずつ年をとったなあと感じるよ。",translation:"Dạo gần đây, cứ mỗi lần về quê là mình lại cảm thấy bố mẹ đã già đi từng chút một."},{speaker:"B",text:"分かるよ。私も久しぶりに会うと、もっと親孝行しなきゃって思うもん。",translation:"Mình hiểu cảm giác đó mà. Bản thân mình hễ lâu ngày mới gặp lại cũng nghĩ phải hiếu thảo với bố mẹ nhiều hơn."},{speaker:"A",text:"そうだね。これからはもっと頻繁に連絡を取るようにしよう。",translation:"Đúng vậy nhỉ. Từ giờ chúng mình nên chủ động liên lạc thường xuyên hơn."}]},commonMistake:{wrong:"毎朝、起きるたびに顔を洗って歯を磨きます。",correct:"毎朝、起きたら顔を洗って歯を磨きます。",why:"Không dùng「～たびに」cho những hành động sinh hoạt thường nhật mang tính hiển nhiên lặp lại mỗi ngày."},note:"Vế sau của「～たびに」không dùng câu thể hiện ý chí, mệnh lệnh hay nhờ vả trực tiếp (như ～てください, ～よう) đối với hành động của thời điểm hiện tại."},{pattern:"～たとたん（に）",meaning:"Ngay lúc vừa, vừa mới ~ thì ngay lập tức",priority:"common",explanation:"Mẫu ngữ pháp này diễn tả một sự việc hoặc sự biến đổi bất ngờ xảy ra gần như đồng thời, ngay lập tức sau khi hành động phía trước vừa hoàn thành. Vế trước luôn đi với động từ thể quá khứ (Vた), còn vế sau là sự việc xảy ra ngoài ý muốn hoặc ngoài dự tính của người nói. Vì vế sau mang tính khách quan và bất ngờ, cấu trúc này tuyệt đối không đi kèm với các đuôi câu thể hiện ý chí, nguyện vọng, mệnh lệnh hay rủ rê.",examples:[{sentence:"窓を開けたとたん、冷たい風が部屋の中に吹き込んできた。",translation:"Vừa mở cửa sổ ra thì ngay lập tức một luồng gió lạnh thổi ùa vào trong phòng."},{sentence:"犯人は警察の姿を見たとたんに、路地へ走って逃げ出した。",translation:"Tên tội phạm vừa nhìn thấy bóng dáng cảnh sát là ngay lập tức cắm đầu chạy trốn vào con hẻm."}],dialogue:{title:"Em bé bỗng nhiên khóc",lines:[{speaker:"A",text:"赤ちゃん、さっきまで笑っていたのに、お母さんが部屋を出て行ったとたんに泣き出しちゃったよ。",translation:"Em bé lúc nãy còn đang cười mà vừa lúc mẹ bước ra khỏi phòng là khóc ré lên ngay đấy."},{speaker:"B",text:"やっぱりお母さんが見えなくなると寂しいんだね。少し抱っこしてあげようか。",translation:"Đúng là không thấy mẹ là thấy cô đơn ngay mà. Để tớ bế dỗ bé một chút nhé."},{speaker:"A",text:"うん、お願い。早くお母さんが戻ってくるといいね。",translation:"Ừ, nhờ cậu nhé. Mong là mẹ bé sớm quay lại."}]},commonMistake:{wrong:"駅に着いたとたんに、私に電話してください。",correct:"駅に着いたら、私に電話してください。",why:"Vế sau của 「～たとたん（に）」diễn tả sự việc bất ngờ xảy ra ngoài dự kiến, không được dùng cho câu thể hiện ý chí, mệnh lệnh hay yêu cầu như 「～てください」."},note:"Khác với 「～次第」dùng cho hành động có chủ ý khi hoàn thành việc gì đó trong tương lai, vế sau của 「～たとたん（に）」thường diễn tả sự việc bất ngờ đã xảy ra trong quá khứ và không chứa ý định của người nói."},{pattern:"～うちに",meaning:"Trong khi còn, tranh thủ khi (trước khi tình huống thay đổi)",priority:"common",explanation:"Mẫu 「～うちに」 mang ý nghĩa tranh thủ làm một hành động nào đó trong khi trạng thái hiện tại vẫn còn duy trì, trước khi tình huống biến đổi sang trạng thái bất lợi hoặc khó thực hiện hơn. Điểm mấu chốt là nếu không làm ngay thì sau đó sẽ khó có cơ hội tốt để làm nữa. Vế sau thường đi kèm các câu thể hiện ý chí, lời khuyên, yêu cầu hoặc rủ rê như 〜たい、〜てください、〜よう.",examples:[{sentence:"スープが温かいうちに、どうぞ召し上がってください。",translation:"Xin mời bạn dùng súp tranh thủ lúc súp còn đang ấm nóng ạ."},{sentence:"雨が降らないうちに、早く買い物を済ませてしまおう。",translation:"Tranh thủ lúc trời chưa mưa, chúng ta hãy đi mua sắm cho xong sớm nào."}],dialogue:{title:"Kế hoạch đi leo núi",lines:[{speaker:"A",text:"日本にいるうちに、一度富士山に登ってみたいですね。",translation:"Trong lúc còn ở Nhật, tôi muốn thử một lần leo núi Phú Sĩ."},{speaker:"B",text:"いいですね！登るなら天気が安定している今の時期がおすすめですよ。",translation:"Hay đấy! Nếu leo thì tôi khuyên nên đi vào thời điểm này khi thời tiết còn ổn định."},{speaker:"A",text:"じゃあ、本格的に寒くならないうちに日程を決めましょう。",translation:"Vậy thì tranh thủ lúc trời chưa lạnh hẳn, chúng ta cùng chốt lịch trình nhé."}]},commonMistake:{wrong:"スープが温かい間に、どうぞ飲んでください。",correct:"スープが温かいうちに、どうぞ飲んでください。",why:"Khi muốn khuyên bảo hoặc thúc giục người khác tranh thủ làm gì trước khi trạng thái thuận lợi thay đổi (súp bị nguội), phải dùng 「～うちに」 chứ không dùng 「～間に」 vì 「～間に」 chỉ đơn thuần nêu mốc thời gian khách quan."},note:"Cần phân biệt với mẫu 「～間に」: 「～間に」 diễn tả hành động diễn ra trong một khoảng thời gian khách quan, còn 「～うちに」 luôn mang sắc thái tâm lý tranh thủ tận dụng thời cơ trước khi trạng thái hiện tại biến mất."},{pattern:"～間に／間は",meaning:"Trong khoảng thời gian (xảy ra điều khác)",priority:"common",explanation:"Mẫu ngữ pháp 「～間に／間は」dùng để diễn tả một hành động, sự việc hoặc trạng thái diễn ra trong một khoảng thời gian nhất định của vế trước. Trong đó, 「～間に」được dùng khi vế sau là một hành động mang tính thời điểm, xảy ra tại một lúc nào đó trong khoảng thời gian diễn ra vế đầu. Ngược lại, 「～間（は）」dùng khi hành động hoặc trạng thái ở vế sau kéo dài liên tục trong suốt toàn bộ khoảng thời gian đó. Mẫu này đi kèm với động từ thể từ điển, thể ている hoặc danh từ kết hợp với trợ từ の.",examples:[{sentence:"子供が昼寝をしている間に、たまっていた洗濯や掃除を済ませた。",translation:"Trong lúc con đang ngủ trưa, tôi đã tranh thủ làm xong đống việc giặt giũ và dọn dẹp còn tồn đọng."},{sentence:"日本に留学している間は、できるだけたくさんの人と日本語で話すようにしている。",translation:"Trong suốt thời gian du học tại Nhật Bản, tôi luôn cố gắng trò chuyện bằng tiếng Nhật với càng nhiều người càng tốt."}],dialogue:{title:"Chuẩn bị bữa tối",lines:[{speaker:"A",text:"私がお風呂に入っている間に、お湯を沸かしておいてくれる？",translation:"Trong lúc em đi tắm, anh đun sẵn nước sôi giúp em được không?"},{speaker:"B",text:"いいよ。ついでに野菜も切っておこうか？",translation:"Được chứ. Tiện thể anh cắt rau củ luôn nhé?"},{speaker:"A",text:"助かる！じゃあ上がったらすぐ夕食の準備ができるね。",translation:"Được thế thì tốt quá! Vậy lúc em tắm xong là có thể nấu bữa tối được ngay rồi."}]},commonMistake:{wrong:"留守の間、家に泥棒が入ってしまった。",correct:"留守の間に、家に泥棒が入ってしまった。",why:"Việc kẻ trộm đột nhập vào nhà là sự việc xảy ra tại một thời điểm bất chợt chứ không kéo dài liên tục suốt lúc vắng nhà, do đó bắt buộc phải dùng 「間に」 chứ không dùng 「間」."},note:"Cần phân biệt rõ: 「～間に」dùng cho hành động mang tính thời điểm/khoảnh khắc, còn 「～間（は）」dùng cho hành động hoặc trạng thái diễn ra liên tục, kéo dài suốt cả khoảng thời gian đó."}],135:[{pattern:"～次第で／次第では",meaning:"Tùy theo, phụ thuộc vào",priority:"core",explanation:"Mẫu câu này dùng để diễn đạt ý nghĩa kết quả hoặc sự việc phía sau sẽ thay đổi, được quyết định tùy thuộc vào nội dung, mức độ của danh từ đi trước. Cấu trúc kết hợp trực tiếp với danh từ (N + 次第で / 次第では). Trong đó, khi dùng dạng 「次第では」, câu văn thường mang sắc thái nhấn mạnh vào một khả năng hay một trường hợp cụ thể có thể xảy ra (thường đi kèm với ～こともある, ～かもしれない).",examples:[{sentence:"明日の花火大会は、天候次第で中止になる可能性があります。",translation:"Lễ hội pháo hoa ngày mai có khả năng sẽ bị hủy tùy thuộc vào thời tiết."},{sentence:"面接での受け答え次第では、未経験者でも採用されることがあります。",translation:"Tùy vào cách trả lời trong buổi phỏng vấn, ngay cả người chưa có kinh nghiệm cũng có thể được tuyển dụng."}],dialogue:{title:"Kế hoạch đi cắm trại",lines:[{speaker:"A",text:"今週末のキャンプ、雨が降りそうだけど本当に行くの？",translation:"Buổi cắm trại cuối tuần này trời có vẻ sắp mưa đấy, mình vẫn đi thật à?"},{speaker:"B",text:"明日の朝の天気予報次第で、決行するかどうか決めよう。",translation:"Tùy vào dự báo thời tiết sáng mai, chúng ta hãy quyết định xem có tiến hành hay không nhé."},{speaker:"A",text:"分かった。もし雨が強ければ無理せず延期にしようね。",translation:"Được rồi. Nếu mưa to thì đừng cố quá mà hãy hoãn lại nhé."}]},commonMistake:{wrong:"会議の準備が終わり次第で、すぐに報告してください。",correct:"会議の準備が終わり次第、すぐに報告してください。",why:'Khi mang nghĩa "ngay sau khi làm xong V thì làm tiếp..." (V-bỏ ます + 次第) thì tuyệt đối không thêm 「で」, vì 「次第で」 chỉ kết hợp với danh từ để biểu thị quan hệ điều kiện "tùy thuộc vào".'},note:"Khác với 「～次第で」 diễn tả kết quả thay đổi đa dạng tùy theo danh từ, 「～次第では」 thường hướng đến một khả năng, hệ quả cụ thể (thường đi kèm với đuôi câu ～こともある、～かもしれない)."},{pattern:"～らしい（推量・根拠）",meaning:"Có vẻ, hình như (dựa trên bằng chứng khách quan)",priority:"common",explanation:"Mẫu ngữ pháp này dùng để đưa ra phán đoán, suy đoán mang tính khách quan ('hình như / có vẻ') dựa trên các căn cứ thực tế, dấu hiệu bên ngoài hoặc thông tin gián tiếp. Người nói dựa vào những chứng cứ cụ thể thu thập được qua thính giác, thị giác hoặc tình trạng thực tế để suy luận chứ không chỉ dựa vào cảm tính nhất thời. Cấu trúc này đi với thể thông thường (普通形), riêng tính từ đuôi な và danh từ thì nối trực tiếp mà không đi kèm 「だ」.",examples:[{sentence:"隣の部屋からいい匂いがしてきた。今夜はカレーを作っているらしい。",translation:"Từ phòng bên cạnh bay ra mùi thơm nức. Có vẻ như tối nay họ nấu món cà ri."},{sentence:"部屋の電気も消えているし、車もないから、山田さんは留守らしい。",translation:"Đèn phòng thì tắt mà xe cũng không có, hình như anh Yamada đang vắng nhà."}],dialogue:{title:"Tiếng ồn ngoài phố",lines:[{speaker:"A",text:"さっきから外がパトカーのサイレンで騒がしいね。何かあったのかな。",translation:"Từ nãy đến giờ ngoài đường ồn ào tiếng còi xe cảnh sát nhỉ. Không biết có chuyện gì không nữa."},{speaker:"B",text:"ニュースを見たら、駅前の交差点で軽い事故があったらしいよ。",translation:"Tớ vừa xem tin tức thì hình như có vụ va chạm nhẹ ở ngã tư trước ga đấy."},{speaker:"A",text:"そうなんだ。大きな怪我をした人がいなければいいね。",translation:"Ra là vậy. Mong là không có ai bị thương nặng."}]},commonMistake:{wrong:"鈴木さんは最近仕事がとても暇だらしい。",correct:"鈴木さんは最近仕事がとても暇らしい。",why:"Tính từ đuôi な (và danh từ) khi kết hợp với 「らしい」 phải bỏ 「だ」 chứ không giữ nguyên dạng だ như trong 「～そうだ」 truyền đạt."},note:"Khác với 「～そうだ（様態）」 phán đoán cảm tính trực tiếp qua vẻ ngoài trước mắt, 「～らしい」 là suy đoán khách quan dựa trên chứng cứ, dấu hiệu cụ thể hoặc thông tin gián tiếp."},{pattern:"～そうだ（外観）",meaning:"Trông có vẻ, nhìn có vẻ (dựa vào quan sát trực tiếp)",priority:"common",explanation:"Mẫu 「～そうだ」 dùng để diễn tả phán đoán, cảm nhận trực quan của người nói về trạng thái hoặc tính chất của sự vật, sự việc thông qua quan sát vẻ bề ngoài (trông có vẻ...). Ngoài ra, khi kết hợp với động từ thể ます, mẫu này còn thể hiện một hiện tượng hay hành động sắp sửa xảy ra ngay trước mắt (sắp sửa...). Ngữ pháp này mang sắc thái nhận định chủ quan tức thì dựa trên những gì mắt thấy, thường dùng nhiều trong giao tiếp sinh hoạt hàng ngày.",examples:[{sentence:"空が急に暗くなってきて、今にも大雨が降り出しそうだ。",translation:"Trời bỗng nhiên tối sầm lại, trông như sắp sửa đổ mưa lớn đến nơi rồi."},{sentence:"田中さんは新しいプロジェクトの話をしているとき、いつも本当に楽しそうだ。",translation:"Anh Tanaka khi nói về dự án mới lúc nào trông cũng có vẻ thực sự rất vui."}],dialogue:{title:"Mua máy tính mới",lines:[{speaker:"A",text:"このパソコン、画面も見やすくてとても使いやすそうだね。",translation:"Chiếc máy tính này màn hình dễ nhìn mà trông có vẻ rất dễ dùng nhỉ."},{speaker:"B",text:"ええ、本体も軽くて持ち運びに便利そうですし、仕事にぴったりですね。",translation:"Vâng, thân máy cũng nhẹ và trông có vẻ tiện mang theo, rất hợp cho công việc đấy."},{speaker:"A",text:"性能の割に値段も手頃そうだから、これに決めよう。",translation:"So với hiệu năng thì giá cả trông cũng phải chăng, chốt mua cái này đi."}]},commonMistake:{wrong:"田中さんが持っている新しいスマホは、とてもいいそうだ。",correct:"田中さんが持っている新しいスマホは、とてもよさそうだ。",why:"Tính từ 「いい」 khi kết hợp với 「そうだ」 biểu thị vẻ ngoài phải biến đổi thành 「よさそうだ」, còn 「いいそうだ」 sẽ bị hiểu thành ngữ pháp truyền văn (nghe nói là tốt)."},note:"Không dùng 「～そうだ」 cho các từ chỉ tính chất thị giác quá hiển nhiên đập vào mắt (như màu sắc 赤い, 青い hoặc かわいい, きれい), và dạng phủ định của tính từ là 「～なさそうだ」."},{pattern:"～ほど（程度）",meaning:"Đến mức, đến nỗi (mức độ cao)",priority:"common",explanation:'Mẫu ngữ pháp này dùng để diễn tả mức độ rất cao của một trạng thái hoặc hành động bằng cách đưa ra ví dụ so sánh cụ thể, thậm chí mang tính cường điệu hóa ("đến mức...", "đến nỗi..."). Cấu trúc này đi trực tiếp sau thể thông thường (V/A-i/A-na/N) và thường xuất hiện khi người nói muốn nhấn mạnh cảm xúc mạnh mẽ hoặc tình trạng quá tải. Trong giao tiếp hàng ngày lẫn văn viết, nó giúp câu văn trở nên sinh động và giàu hình ảnh hơn.',examples:[{sentence:"昨日は仕事が忙しすぎて、息をつく暇もないほど働いた。",translation:"Hôm qua công việc bận đến mức tôi làm việc mà không có cả thời gian để thở."},{sentence:"山頂からの星空は息をのむほど美しく、登山の疲れが一瞬で吹き飛んだ。",translation:"Bầu trời sao nhìn từ đỉnh núi đẹp đến mức nín thở, khiến mọi mệt mỏi của chuyến leo núi tan biến trong chốc lát."}],dialogue:{title:"Chuẩn bị thuyết trình",lines:[{speaker:"A",text:"明日のプレゼン、緊張して昨夜は一睡もできないほどだったよ。",translation:"Buổi thuyết trình ngày mai làm tôi căng thẳng đến mức đêm qua không chợp mắt được tí nào."},{speaker:"B",text:"毎日遅くまであれだけ練習を重ねてきたんだから、きっとうまくいくよ。",translation:"Cậu đã chăm chỉ luyện tập đến tận khuya mỗi ngày như thế rồi, chắc chắn sẽ suôn sẻ thôi."},{speaker:"A",text:"ありがとう。倒れそうになるほど不安だけど、全力を尽くしてみるね。",translation:"Cảm ơn cậu nhé. Dù lo lắng đến mức sắp gục ngã nhưng tôi sẽ cố gắng hết sức."}]},commonMistake:{wrong:"自分の名前を書くほどは、誰でもできるはずだ。",correct:"自分の名前を書くくらいは、誰でもできるはずだ。",why:'Khi diễn tả mức độ tối thiểu, tầm thường hoặc xem nhẹ sự việc ("chí ít thì...", "cỡ như...") phải dùng 「くらい／ぐらい」 chứ không dùng 「ほど」.'},note:"So với 「くらい」, 「ほど」 mang sắc thái trang trọng hơn và thường nhấn mạnh mức độ cao, nghiêm trọng hoặc cường điệu hơn hẳn."},{pattern:"～ように（様態）",meaning:"Như thể là, dường như (so sánh/tương tự)",priority:"common",explanation:'Mẫu「～ように」dùng để so sánh, ví von một sự vật, hiện tượng hoặc hành động có đặc điểm tương tự như một điều khác (mang nghĩa "như thể là", "giống như"). Cấu trúc này thường đi kèm với phó từ「まるで」ở đầu câu nhằm tăng tính hình tượng và nhấn mạnh mức độ tương đồng. Khi dùng để bổ nghĩa cho động từ hoặc tính từ ta dùng dạng「～ように」, còn khi bổ nghĩa cho danh từ đứng sau thì chuyển thành「～ような + N」.',examples:[{sentence:"彼女はまるでプロの歌手のように上手に歌を歌った。",translation:"Cô ấy đã hát rất hay, cứ như thể là một ca sĩ chuyên nghiệp vậy."},{sentence:"冬の北海道は、まるで冷凍庫の中にいるように厳しい寒さだ。",translation:"Mùa đông ở Hokkaido lạnh buốt giá, giống như đang ở trong một chiếc tủ đông vậy."}],dialogue:{title:"Khen bài thuyết trình",lines:[{speaker:"A",text:"昨日のプレゼン、まるでネイティブスピーカーのように流暢に話せていましたね。",translation:"Bài thuyết trình hôm qua cậu nói trôi chảy cứ như người bản xứ vậy đó."},{speaker:"B",text:"本当ですか？すごく緊張していたので、そう言ってもらえてホッとしました。",translation:"Thật vậy sao? Mình đã rất căng thẳng nên được cậu khen như vậy mình thấy nhẹ cả người."},{speaker:"A",text:"自信を持っていいですよ。堂々としていて素晴らしかったです。",translation:"Cứ tự tin lên nhé. Cậu trình bày rất đĩnh đạc và tuyệt vời lắm."}]},commonMistake:{wrong:"彼女の手は氷ように冷たくなっていた。",correct:"彼女の手は氷のように冷たくなっていた。",why:"Khi nối danh từ với mẫu so sánh ví von này, bắt buộc phải dùng「N + のように」chứ không nối trực tiếp「N + ように」."},note:"Mẫu này thường kết hợp với「まるで」để tạo hình ảnh ví von tượng trưng, cần tránh nhầm lẫn với「～らしい」(dùng khi đối tượng thực sự có đúng bản chất, đặc trưng vốn có của nó)."},{pattern:"まるで～ようだ／みたいだ",meaning:"Hoàn toàn như thể là, y chang như",priority:"common",explanation:'Mẫu 「まるで～ようだ／みたいだ」 dùng để ví von, so sánh một sự vật, hiện tượng hoặc trạng thái với một điều gì đó rất giống dù thực tế không phải như vậy. Phó từ 「まるで」 mang nghĩa "hoàn toàn / cứ như thể", giúp nhấn mạnh mức độ tương đồng sống động của phép so sánh. 「～ようだ」 mang sắc thái trang trọng và dùng nhiều trong văn viết, trong khi 「～みたいだ」 mang tính khẩu ngữ, thân mật và phổ biến trong hội thoại giao tiếp hàng ngày.',examples:[{sentence:"まだ5月なのに今日の暑さは異常で、まるで真夏のようだ。",translation:"Mới chỉ tháng 5 thôi mà hôm nay nóng bất thường, cứ như thể đang giữa mùa hè vậy."},{sentence:"あの兄弟は性格も声もそっくりで、まるで双子みたいだ。",translation:"Hai anh em nhà đó tính cách lẫn giọng nói đều giống hệt nhau, y chang như sinh đôi vậy."}],dialogue:{title:"Căn phòng mới dọn",lines:[{speaker:"A",text:"見て！部屋の掃除と模様替えが終わったよ。",translation:"Nhìn này! Tớ đã dọn dẹp và sắp xếp lại phòng xong rồi đấy."},{speaker:"B",text:"すごい、すごく綺麗になって、まるで新築のホテルの部屋みたいだね。",translation:"Tuyệt quá, phòng sạch đẹp đến mức y như phòng khách sạn mới xây vậy."},{speaker:"A",text:"ありがとう、頑張って家具を全部磨いた甲斐があったよ。",translation:"Cảm ơn cậu, công sức tớ nỗ lực lau chùi toàn bộ đồ đạc thật không uổng phí."}]},commonMistake:{wrong:"彼の日本語はとても上手で、まるで日本人のそうだ。",correct:"彼の日本語はとても上手で、まるで日本人のようだ。",why:"Phó từ 「まるで」 chỉ đi kèm với các dạng so sánh ví von như 「～ようだ／みたいだ」 chứ không kết hợp với 「～そうだ」 (dùng để phỏng đoán dáng vẻ hoặc dẫn lại thông tin)."},note:"Khi muốn bổ nghĩa cho danh từ đứng sau, cấu trúc chuyển thành 「まるで～ような＋N」 hoặc 「まるで～みたいな＋N」; còn bổ nghĩa cho động từ/tính từ thì dùng 「まるで～ように／みたいに」."},{pattern:"かのように／かのような",meaning:"Như thể (điều thực ra không phải vậy)",priority:"common",explanation:'Mẫu câu này dùng để diễn tả một hành động hoặc trạng thái diễn ra "cứ như thể là...", nhằm ví von sinh động một hiện tượng. Điểm mấu chốt là trên thực tế bản chất sự việc hoàn toàn không phải như vậy. Dạng 「〜かのように」 đứng trước để bổ nghĩa cho động từ, còn 「〜かのような」 đi kèm để bổ nghĩa cho danh từ phía sau, thường mang sắc thái miêu tả bóng bẩy hoặc châm biếm, phê phán.',examples:[{sentence:"まだ10月なのに、真冬がやってきたかのような厳しい寒さだ。",translation:"Mới chỉ là tháng 10 thôi mà trời đã lạnh buốt cứ như thể mùa đông thực sự đã đến rồi."},{sentence:"彼女はすべてを一人でやり遂げたかのように、得意げに話している。",translation:"Cô ấy đang nói chuyện đầy vẻ đắc ý cứ như thể chính mình đã tự tay hoàn thành tất cả mọi việc."}],dialogue:{title:"Thái độ của đồng nghiệp",lines:[{speaker:"A",text:"田中さん、昨日の重大なミスについて何も言わないね。",translation:"Anh Tanaka chẳng nói năng gì về lỗi nghiêm trọng hôm qua nhỉ."},{speaker:"B",text:"うん、まるで何事も起きなかったかのように平気な顔で仕事をしているよ。",translation:"Ừ, anh ấy đang làm việc với vẻ mặt thản nhiên cứ như thể chưa từng có chuyện gì xảy ra vậy."},{speaker:"A",text:"反省している様子が全く見られないのは困るよね。",translation:"Hoàn toàn không thấy có dáng vẻ kiểm điểm chút nào thì phiền thật đấy."}]},commonMistake:{wrong:"彼はお金持ちだかのように、高価な物ばかり買っている。",correct:"彼はお金持ちであるかのように、高価な物ばかり買っている。",why:"Với danh từ và tính từ đuôi な, không kết hợp ở dạng 「だ + かのように」 mà phải dùng 「であるかのように」 hoặc gắn trực tiếp danh từ 「N + かのように」."},note:"Cần phân biệt với 「〜ように」 thông thường: 「〜かのように」 nhấn mạnh sự việc thực tế hoàn toàn trái ngược hoặc không có thật, không dùng cho sự việc có thật hay so sánh tỉ dụ thực tế."}],136:[{pattern:"～てもらう・てあげる・てくれる",meaning:"Nhận/cho/được nhận hành động giúp đỡ (授受表現)",priority:"core",explanation:"Nhóm ngữ pháp này biểu thị các hành vi cho - nhận sự giúp đỡ kèm theo sắc thái tình cảm và lòng biết ơn. Trong đó,「～てあげる」dùng khi người nói làm việc gì giúp người khác,「～てくれる」dùng khi người khác làm việc gì giúp mình (hoặc người thuộc phe mình), còn「～てもらう」biểu thị người nói tiếp nhận hành động giúp đỡ từ người khác. Khi sử dụng, cần đặc biệt lưu ý đến hướng của hành động và quan hệ thứ bậc để tránh gây cảm giác ban ơn hay thất lễ.",examples:[{sentence:"日本語のメールの書き方が分からなかったので、同僚にチェックしてもらった。",translation:"Vì không rõ cách viết email bằng tiếng Nhật nên tôi đã nhờ đồng nghiệp kiểm tra giúp."},{sentence:"道に迷っていたら、親切な地元の方が駅まで案内してくれました。",translation:"Khi tôi đang bị lạc đường thì một người dân địa phương tốt bụng đã dẫn đường giúp tôi đến tận ga."}],dialogue:{title:"Chuẩn bị tiệc liên hoan",lines:[{speaker:"A",text:"明日のパーティーの準備、大変そうだから手伝ってあげようか。",translation:"Chuẩn bị tiệc cho ngày mai trông có vẻ vất vả nhỉ, để mình giúp cậu một tay nhé?"},{speaker:"B",text:"本当？買い出しに行ってくれるとすごく助かるよ。",translation:"Thật sao? Cậu đi mua đồ giúp mình thì quý hóa quá."},{speaker:"A",text:"了解！じゃあ、必要な物のリストを送っておいてね。",translation:"Nhất trí! Vậy cậu gửi danh sách đồ cần mua qua cho mình nhé."}]},commonMistake:{wrong:"先生、重そうですね。その荷物を持ってあげましょうか。",correct:"先生、重そうですね。その荷物をお持ちしましょうか。",why:"Không dùng「～てあげる」với người bề trên vì tạo cảm giác ban ơn, kẻ cả; trường hợp này nên dùng cấu trúc khiêm nhường ngữ「お～します／しましょうか」."},note:"Lưu ý trợ từ: trong câu「～てくれる」thì người thực hiện hành động làm chủ ngữ (đi với が), còn câu「～てもらう」thì người nhận sự giúp đỡ là chủ ngữ và người làm hành động đi với trợ từ に."},{pattern:"～（ら）れる・～（さ）せる",meaning:"Thể thụ động (受け身) & sai khiến (使役) — bị/được làm; cho/bắt làm",priority:"common",explanation:"Mẫu ngữ pháp này bao gồm thể thụ động「～（ら）れる」(bị hoặc được tác động) và thể sai khiến「～（さ）せる」(cho phép hoặc bắt buộc ai đó làm việc gì). Thể thụ động được dùng để diễn đạt sự việc từ góc nhìn của người tiếp nhận hành động, bao gồm thụ động trực tiếp, thụ động gián tiếp (chỉ sự phiền toái) và thụ động khách quan. Thể sai khiến thể hiện quyền hạn hoặc sự cho phép của người có vị thế cao hơn đối với người dưới, hoặc dùng trong cấu trúc xin phép lịch sự「～させてください」. Khi sử dụng, cần lưu ý không dùng trực tiếp thể sai khiến đối với người bề trên để tránh gây cảm giác áp đặt, thiếu tôn trọng.",examples:[{sentence:"大事な書類を同僚に誤って捨てられるというトラブルが発生した。",translation:"Đã xảy ra sự cố tài liệu quan trọng bị đồng nghiệp vô tình vứt mất."},{sentence:"部長は若手社員の成長を促すため、大きなプロジェクトのリーダーを担当させることにした。",translation:"Trưởng phòng quyết định giao cho nhân viên trẻ đảm nhận vị trí trưởng dự án lớn nhằm thúc đẩy sự phát triển của họ."}],dialogue:{title:"Phân công công việc dự án",lines:[{speaker:"A",text:"今度の新規プロジェクト、新人の田中さんにリーダーを担当させるのはどうでしょうか。",translation:"Dự án mới lần này, để nhân viên mới Tanaka đảm nhận vị trí trưởng nhóm thì anh thấy thế nào?"},{speaker:"B",text:"いいアイデアですね。ただ、急に重い仕事を任せられると、本人がプレッシャーを感じてしまうかもしれませんよ。",translation:"Ý hay đấy. Nhưng nếu bất ngờ bị giao công việc nặng nề thì có thể cậu ấy sẽ cảm thấy áp lực đấy."},{speaker:"A",text:"大丈夫です。先輩社員がしっかりサポートして、安心して力を発揮させるようにします。",translation:"Không sao đâu. Các tiền bối sẽ hỗ trợ chu đáo để giúp cậu ấy yên tâm phát huy năng lực."}]},commonMistake:{wrong:"上司に新しい企画書を確認させました。",correct:"上司に新しい企画書を確認していただきました。",why:"Không dùng thể sai khiến「～（さ）せる」đối với cấp trên vì mang sắc thái áp đặt, sai bảo; khi nhờ người trên làm giúp việc gì thì phải dùng cấu trúc「～ていただく」."},note:"Cần phân biệt rõ thể thụ động「～（ら）れる」(bị/được làm), thể sai khiến「～（さ）せる」(cho/bắt làm) và thể sai khiến thụ động「～（さ）せられる」(bị ai đó bắt buộc phải làm điều bản thân không muốn)."},{pattern:"～ように言う／頼む／伝える",meaning:"Bảo, nhờ, truyền đạt cho ai đó làm gì (gián tiếp)",priority:"common",explanation:"Mẫu câu này dùng để trích dẫn gián tiếp một mệnh lệnh, yêu cầu hoặc lời dặn dò từ người này sang người khác với ý nghĩa 'bảo, nhờ, nhắn ai làm hoặc không làm việc gì'. Động từ đứng trước 「ように」 luôn chia ở thể từ điển (Vる) hoặc thể phủ định ngắn (Vない), kết hợp phía sau với các động từ truyền đạt như 言う, 頼む, 伝える. Cách nói này mang sắc thái lịch sự, mềm mỏng và tự nhiên hơn so với việc trích dẫn trực tiếp câu mệnh lệnh.",examples:[{sentence:"母は弟に、夜遅くまでゲームをしないで早く寝るように言いました。",translation:"Mẹ đã bảo em trai không được chơi game đến khuya mà hãy đi ngủ sớm."},{sentence:"山田さんに、明日の会議の資料を今日中にメールで送るように伝えてください。",translation:"Xin hãy nhắn anh Yamada gửi tài liệu cuộc họp ngày mai qua email trong ngày hôm nay giúp tôi."}],dialogue:{title:"Nhờ nhắn lời sếp",lines:[{speaker:"A",text:"山田さん、さっき課長から電話があって、午後の会議に遅れないように伝えてほしいと言っていましたよ。",translation:"Anh Yamada ơi, vừa nãy trưởng nhóm có gọi điện dặn tôi nhắn lại với anh là đừng đến muộn cuộc họp chiều nay đấy."},{speaker:"B",text:"わかりました。外出先から直行するので間に合うと思います。教えてくれてありがとうございます。",translation:"Tôi hiểu rồi. Tôi đi thẳng từ chỗ khách hàng về nên chắc kịp. Cảm ơn anh đã báo nhé."},{speaker:"A",text:"念のため、新しい企画書も持参するように言っていましたので準備しておいてくださいね。",translation:"Để cho chắc thì sếp cũng dặn nhớ mang theo cả bản kế hoạch mới nữa, nên anh chuẩn bị sẵn nhé."}]},commonMistake:{wrong:"先生は学生に静かにしてくださいように言いました。",correct:"先生は学生に静かにするように言いました。",why:"Trước 「ように」 bắt buộc phải là thể từ điển (Vる) hoặc thể phủ định (Vない), không được kết hợp trực tiếp với dạng sai khiến/nhờ vả 「～てください」."},note:"Khi chính bản thân là người nhận lời yêu cầu/dặn dò từ người khác, mẫu câu này thường được chuyển sang dạng bị động là 「～ように言われる／頼まれる」 (được/bị bảo làm gì)."},{pattern:"～ということだ",meaning:"Có nghĩa là, điều đó có nghĩa là (kết luận/tóm tắt)",priority:"common",explanation:"Mẫu câu 「～ということだ」 dùng để giải thích bản chất, tóm tắt hoặc rút ra kết luận mang tính logic từ một tình huống, sự việc cụ thể (mang nghĩa 'tức là / điều đó có nghĩa là'). Vế trước thường đi kèm với cụm 「～ということは」 hoặc phó từ 「つまり」 để dẫn dắt vấn đề. Cấu trúc này thể hiện sự suy luận khách quan, thường được sử dụng trong văn viết, công việc hoặc giải thích hàng ngày.",examples:[{sentence:"意見がないということは、現状の提案に賛成しているということだ。",translation:"Không có ý kiến gì điều đó có nghĩa là bạn đang tán thành với đề xuất hiện tại."},{sentence:"物価が上がって給料が変わらないのは、実質的に収入が減ったということだ。",translation:"Vật giá tăng trong khi lương không đổi điều đó đồng nghĩa với việc thu nhập thực tế đã bị giảm."}],dialogue:{title:"Kết quả phỏng vấn",lines:[{speaker:"A",text:"面接官から『来週の月曜日に手続きに来てください』と連絡がありました。",translation:"Người phỏng vấn vừa liên lạc bảo em là 'Thứ Hai tuần sau hãy đến làm thủ tục'."},{speaker:"B",text:"それは採用が決まったということだね。本当におめでとう！",translation:"Điều đó có nghĩa là em đã được nhận rồi đấy. Chúc mừng em nhé!"},{speaker:"A",text:"ありがとうございます。安心しました。",translation:"Em cảm ơn ạ. Em thở phào nhẹ nhõm rồi."}]},commonMistake:{wrong:"彼から返事がないということは、断られたという意味だ。",correct:"彼から返事がないということは、断られたということだ。",why:"Khi diễn giải ý nghĩa hoặc rút ra kết luận từ một sự việc thực tế, ta dùng 「～ということだ」 chứ không dùng 「～という意味だ」 (chỉ dùng khi giải thích định nghĩa của từ ngữ, ký hiệu)."},note:"Cần phân biệt với một cách dùng phổ biến khác của 「～ということだ」 là truyền đạt lại thông tin nghe ngóng được (tương đương với 「～そうだ / nghe nói là」)."},{pattern:"～という",meaning:"Được gọi là, cái mà (đưa ra tên/nội dung)",priority:"common",explanation:"Mẫu ngữ pháp 「～という」 được dùng để gọi tên, định nghĩa hoặc giải thích nội dung của một sự vật, sự việc, con người cụ thể mà người nói nghĩ rằng người nghe chưa biết. Ngoài việc gọi tên danh từ (Tên + という + N), mẫu này còn đi với thể thông thường (普通形 + という + N) để giải thích nội dung cho danh từ trừu tượng phía sau như tin đồn, kế hoạch, thông báo. Trong giao tiếp thân mật hằng ngày, 「～という」 thường được người bản xứ chuyển thành 「～っていう」.",examples:[{sentence:"駅の近くに「さくら」という美味しいラーメン屋が新しくできましたよ。",translation:'Ở gần nhà ga mới mở một quán mì ramen rất ngon tên là "Sakura" đấy.'},{sentence:"山田先生が来月退職されるという噂を聞きましたが、本当ですか。",translation:"Tôi nghe phong phanh tin đồn thầy Yamada tháng sau sẽ nghỉ hưu, điều đó có thật không?"}],dialogue:{title:"Món ăn Việt Nam",lines:[{speaker:"A",text:"昨日、友達と「バインミー」というベトナムのサンドイッチを食べに行きました。",translation:'Hôm qua mình đi ăn một loại bánh mì kẹp của Việt Nam gọi là "Bánh mì" cùng bạn.'},{speaker:"B",text:"へえ、初めて聞きました。美味しかったですか。",translation:"Ồ, lần đầu tiên tôi nghe tên món đó đấy. Ăn có ngon không?"},{speaker:"A",text:"はい、外はカリカリで中に具がたくさん入っていて、とても美味しかったですよ。",translation:"Vâng, vỏ ngoài giòn tan và bên trong có rất nhiều nhân, ngon tuyệt luôn ạ."}]},commonMistake:{wrong:"先週、「フォー」のベトナム料理を初めて食べました。",correct:"先週、「フォー」というベトナム料理を初めて食べました。",why:"Khi nêu tên gọi hoặc định nghĩa một sự vật cụ thể mà đối phương có thể chưa biết, phải dùng 「～という」 để nối thay vì dùng trợ từ sở hữu 「の」 theo thói quen dịch từng từ tiếng Việt."},note:"Trong hội thoại tự nhiên hằng ngày, 「～という」 thường được nói tắt thành 「～っていう」, và cần tránh nhầm lẫn cách dùng định nghĩa/gọi tên này với hành động phát ngôn thực tế của động từ 「言う」(nói)."},{pattern:"～によると／によれば",meaning:"Theo, dựa theo (nguồn thông tin)",priority:"common",explanation:'Mẫu ngữ pháp này dùng để dẫn xuất xứ hoặc nguồn của thông tin, mang ý nghĩa là "theo như..." hoặc "căn cứ vào...". Danh từ đứng trước thường là các nguồn tin đáng tin cậy như báo đài, kết quả khảo sát, chuyên gia hoặc lời kể của ai đó. Cuối câu hầu như luôn đi kèm các dạng biểu thị truyền đạt hoặc phỏng đoán như 「～そうだ」「～らしい」「～ということだ」 chứ không dùng kết thúc khẳng định dứt khoát.',examples:[{sentence:"今朝のニュースによれば、来月から電気料金が再び値上がりするそうだ。",translation:"Theo tin tức sáng nay, từ tháng sau giá tiền điện dường như sẽ lại tăng lên."},{sentence:"専門家の調査によると、睡眠不足は集中力の低下に大きく影響するということです。",translation:"Theo khảo sát của các chuyên gia, việc thiếu ngủ ảnh hưởng rất lớn đến sự suy giảm khả năng tập trung."}],dialogue:{title:"Tin đồn ở công ty",lines:[{speaker:"A",text:"田中さんから聞いた話によると、山田さんは来月会社を辞めるらしいよ。",translation:"Theo chuyện nghe được từ anh Tanaka thì có vẻ anh Yamada sẽ nghỉ việc vào tháng sau đấy."},{speaker:"B",text:"えっ、本当ですか？あんなに熱心にプロジェクトを進めていたのに。",translation:"Hả, thật vậy sao? Dù anh ấy đang phụ trách dự án nhiệt tình như thế mà."},{speaker:"A",text:"うん、どうやら海外の会社に転職する予定なんだって。",translation:"Ừ, nghe đâu là có dự định chuyển việc sang một công ty nước ngoài."}]},commonMistake:{wrong:"先生の話によると、来週のテストはとても難しいです。",correct:"先生の話によると、来週のテストはとても難しいそうです。",why:"Vì 「～によると」 dùng để trích dẫn thông tin gián tiếp nên cuối câu bắt buộc phải chia về dạng truyền đạt hoặc phỏng đoán như 「～そうだ / ～らしい」 chứ không dùng câu khẳng định trực tiếp."},note:"Hai dạng 「～によると」 và 「～によれば」 hoàn toàn có thể thay thế cho nhau, tuy nhiên 「～によれば」 thường mang sắc thái trang trọng, mang tính văn viết hơn."},{pattern:"～そうだ（伝聞）",meaning:"Nghe nói là, được biết là (thông tin nghe từ người khác)",priority:"common",explanation:"Mẫu「～そうだ」được dùng để truyền đạt lại thông tin mà người nói đã nghe hoặc đọc được từ một nguồn tin khác như báo chí, tin tức hay lời kể của ai đó. Khi dùng mẫu này, người nói chỉ thuật lại nguyên vẹn nội dung tiếp nhận được mà không thêm phán đoán hay cảm nhận chủ quan của bản thân. Cấu trúc này thường đi kèm với các cụm từ chỉ rõ nguồn thông tin như「～によると」(theo như...) hoặc「～の話では」(theo lời...).",examples:[{sentence:"ニュースによると、来週から全国的に気温がかなり下がるそうだ。",translation:"Theo tin tức, nghe nói từ tuần sau nhiệt độ trên toàn quốc sẽ giảm mạnh."},{sentence:"先輩の話では、新しく着任した部長は仕事にとても厳しい人だそうだ。",translation:"Theo lời tiền bối, nghe nói vị trưởng phòng mới nhậm chức là một người rất nghiêm khắc trong công việc."}],dialogue:{title:"Quán ăn mới mở",lines:[{speaker:"A",text:"駅前に新しくできたイタリア料理の店、もう行ってみた？",translation:"Cậu đã đi thử quán đồ Ý mới mở trước nhà ga chưa?"},{speaker:"B",text:"ううん、まだだけど、パスタが本格的でとても美味しいそうだよ。",translation:"Chưa, tớ chưa đi, nhưng nghe nói mì Ý ở đó chuẩn vị và ngon lắm đấy."},{speaker:"A",text:"そうなんだ。じゃあ今週の金曜日の夜に一緒に行ってみようよ。",translation:"Thế à. Vậy tối thứ Sáu tuần này tụi mình cùng đi nhé."}]},commonMistake:{wrong:"天気予報によると、明日はとても寒そうだ。",correct:"天気予報によると、明日はとても寒いそうだ。",why:"Khi truyền đạt lại thông tin nghe được (truyền văn), tính từ đuôi い phải giữ nguyên đuôi「い」rồi mới ghép với「そうだ」, nếu bỏ「い」sẽ bị đổi nghĩa thành phán đoán theo vẻ bề ngoài (様態)."},note:"Cần phân biệt rõ「～そうだ（伝聞）」(nghe nói: thể thông thường + そうだ, không đổi đuôi sang quá khứ/phủ định) với「～そうだ（様態）」(trông có vẻ: V-bỏます / A-i bỏい / A-na + そうだ)."},{pattern:"～とのことだ／とのこと",meaning:"Được biết là, nghe tin là (truyền đạt gián tiếp)",priority:"common",explanation:"Mẫu 「～とのことだ／とのこと」 dùng để truyền đạt lại thông tin mà người nói hoặc người viết tiếp nhận được từ nguồn khác (qua thư từ, điện thoại, email, thông báo...). Cấu trúc này mang sắc thái trang trọng, lịch sự và có tính truyền đạt khách quan hơn so với 「～そうだ」. Trong môi trường công sở hoặc văn bản trang trọng, mẫu này rất phổ biến khi báo cáo tin tức từ đối tác, khách hàng hoặc cấp trên.",examples:[{sentence:"先日の面接の結果につきましては、来週の月曜日にメールにてご連絡いただけるとのことです。",translation:"Về kết quả buổi phỏng vấn hôm trước, được biết phía công ty sẽ liên hệ lại qua email vào thứ Hai tuần tới."},{sentence:"大雪の影響により、一部の鉄道路線で運転が見合わされているとのことだ。",translation:"Được biết do ảnh hưởng của tuyết rơi dày đặc nên một số tuyến đường sắt đang tạm dừng hoạt động."}],dialogue:{title:"Tình hình sức khỏe đồng nghiệp",lines:[{speaker:"A",text:"田中さん、体調を崩して入院されたそうですね。ご様子はどうですか。",translation:"Nghe nói anh Tanaka bị ốm phải nhập viện đúng không? Tình hình anh ấy thế nào rồi?"},{speaker:"B",text:"ご家族からの連絡によると、手術は無事に終わって順調に回復されているとのことです。",translation:"Theo liên lạc từ gia đình thì được biết ca phẫu thuật đã thành công và anh ấy đang hồi phục rất tốt."},{speaker:"A",text:"それを聞いて安心しました。早く元気になって戻ってきてほしいですね。",translation:"Nghe vậy tôi an tâm rồi. Mong anh ấy sớm khỏe lại để quay lại làm việc."}]},commonMistake:{wrong:"佐藤さんから連絡があって、明日の会議室は変更なとのことです。",correct:"佐藤さんから連絡があって、明日の会議室は変更（だ）とのことです。",why:"Đứng trước 「とのこと」 là thể thông thường (普通形), đối với danh từ hoặc tính từ đuôi な không được dùng 「な」 mà phải nối trực tiếp hoặc dùng 「だ」."},note:"「～とのことだ」 có ý nghĩa truyền đạt tương tự 「～そうだ」 nhưng trang trọng, lịch sự và mang tính văn viết hơn, đặc biệt thường gặp trong email công việc hoặc bản tin báo chí."}],137:[{pattern:"～べきだ／べきではない",meaning:"Nên làm / Không nên làm (nghĩa vụ/đúng đắn)",priority:"core",explanation:"Mẫu ngữ pháp này dùng để biểu thị một việc đương nhiên nên làm hoặc không nên làm theo quy chuẩn đạo đức, lẽ thường hoặc tinh thần trách nhiệm. Đi sau động từ thể từ điển (đặc biệt 「する」 có thể dùng cả 「すべき」 và 「するべき」) để khẳng định tính đúng đắn của hành động. Mẫu câu mang sắc thái phán đoán khách quan và áp đặt nguyên tắc khá mạnh, do đó không dùng để đưa ra lời khuyên trực tiếp cho người có vị thế cao hơn mình.",examples:[{sentence:"若いうちは失敗を恐れず、興味のあることに積極的に挑戦するべきだ。",translation:"Khi còn trẻ, ta nên tích cực thử sức với những điều mình hứng thú mà không sợ thất bại."},{sentence:"いくら親しい間柄であっても、他人のプライバシーに過剰に干渉するべきではない。",translation:"Dù là mối quan hệ thân thiết đến đâu thì cũng không nên can thiệp quá mức vào đời tư của người khác."}],dialogue:{title:"Lời khuyên cho đồng nghiệp",lines:[{speaker:"A",text:"プロジェクトでミスをしてしまったのですが、部長にどう報告すべきでしょうか。",translation:"Tôi lỡ mắc sai lầm trong dự án rồi, tôi nên báo cáo với trưởng phòng thế nào đây?"},{speaker:"B",text:"言い訳を考える前に、起きた事実を正直にありのまま伝えるべきだよ。",translation:"Trước khi nghĩ đến chuyện biện minh, cậu nên trình bày sự thật đã xảy ra một cách trung thực."},{speaker:"A",text:"そうですね。隠さずにすぐ部長の席へ行って謝罪してきます。",translation:"Đúng vậy nhỉ. Tôi sẽ không giấu giếm mà đến bàn trưởng phòng xin lỗi ngay."}]},commonMistake:{wrong:"先生、風邪を引かれたのですから、今日は無理をせず休むべきです。",correct:"先生、風邪を引かれたのですから、本日はご無理なさらずお休みになったほうがよろしいかと思います。",why:"「～べきだ」 mang tính phán xét luân lý và áp đặt ý kiến của bản thân nên tuyệt đối không dùng để khuyên bảo người bề trên."},note:"Khi dùng ở dạng quá khứ 「～べきだった／べきではなかった」, mẫu câu thể hiện sự hối hận sâu sắc của bản thân hoặc sự chỉ trích, trách móc người khác vì đã không làm/đã làm điều đó."},{pattern:"～にほかならない",meaning:"Chính là, không gì khác ngoài (khẳng định mạnh mẽ)",priority:"common",explanation:"Mẫu ngữ pháp 「～にほかならない」dùng để khẳng định một cách mạnh mẽ rằng nguyên nhân, lý do hoặc bản chất của sự việc chính là điều đó, tuyệt đối không phải cái nào khác. Thường đi trực tiếp sau Danh từ hoặc dạng cấu trúc「～から／ため＋にほかならない」để nhấn mạnh lý do cốt lõi của vấn đề. Đây là cách diễn đạt mang tính văn viết, trang trọng, thể hiện sự phán đoán hoặc lập luận dứt khoát mang tính chủ quan của người nói.",examples:[{sentence:"彼がオリンピックで金メダルを獲得できたのは、日々の厳しい練習に耐え抜いたからにほかならない。",translation:"Việc anh ấy giành được huy chương vàng Olympic chính là vì đã kiên trì chịu đựng quá trình luyện tập khắc nghiệt mỗi ngày."},{sentence:"親が子供を厳しく叱るのは、子供の将来を心配し、深い愛情を持っているからにほかならない。",translation:"Việc cha mẹ nghiêm khắc la mắng con cái chính là vì lo lắng cho tương lai và chan chứa tình yêu thương sâu sắc dành cho con."}],dialogue:{title:"Đánh giá về tân giám đốc",lines:[{speaker:"A",text:"新しい社長が就任してから、社員のモチベーションが急激に上がりましたね。",translation:"Từ khi tân giám đốc nhậm chức, tinh thần làm việc của nhân viên tăng lên rõ rệt nhỉ."},{speaker:"B",text:"ええ、それは社長が現場の声に真摯に耳を傾けているからにほかならないと思いますよ。",translation:"Vâng, tôi nghĩ điều đó chính là vì giám đốc luôn chân thành lắng nghe ý kiến thực tế từ cấp dưới đấy."},{speaker:"A",text:"確かに、現場を大切にするリーダーシップがみんなに伝わっているんですね。",translation:"Đúng thật, phong cách lãnh đạo trân trọng thực tế đã truyền cảm hứng mạnh mẽ đến mọi người."}]},commonMistake:{wrong:"彼が試合に負けたのは、練習が足りなかったにほかならない。",correct:"彼が試合に負けたのは、練習が足りなかったからにほかならない。",why:"Khi giải thích lý do cho sự việc ở vế trước, phải chuyển thành dạng 「～からにほかならない」chứ không được gắn trực tiếp sau thể thông thường của động từ hay tính từ."},note:"Cần phân biệt với 「～にすぎない」(chỉ là... không hơn không kém, mang sắc thái coi nhẹ), trong khi 「～にほかならない」dùng để khẳng định chắc nịch bản chất/nguyên nhân duy nhất (chính là/không gì khác ngoài)."},{pattern:"～に違いない",meaning:"Chắc chắn là, không nghi ngờ gì (xác tín cao)",priority:"common",explanation:'Mẫu câu「～に違いない」dùng để diễn tả sự phán đoán mang tính xác tín rất cao của người nói, mang nghĩa "chắc chắn là..." hoặc "không nghi ngờ gì". Người nói dựa trên một manh mối, chứng cứ cụ thể hoặc trực giác mạnh mẽ để đưa ra nhận định tin chắc 100%. Mẫu này thường đi kèm với các phó từ chỉ mức độ chắc chắn như「きっと」(nhất định) hay「間違いなく」(không sai vào đâu được). Sắc thái biểu đạt mang tính phán đoán chủ quan từ góc nhìn của bản thân người nói.',examples:[{sentence:"部屋の明かりが消えて鍵も閉まっているから、田中さんはもう帰宅したに違いない。",translation:"Vì đèn trong phòng đã tắt và cửa cũng khóa rồi, nên chắc chắn anh Tanaka đã về nhà."},{sentence:"1年間毎日あれほど努力したのだから、彼女は今回の試験に合格するに違いない。",translation:"Đã nỗ lực nhiều đến mức đó mỗi ngày suốt cả năm qua thì cô ấy chắc chắn sẽ đỗ kỳ thi lần này."}],dialogue:{title:"Tìm chủ nhân chiếc ô",lines:[{speaker:"A",text:"会議室にこの高級そうな傘が置き忘れてあったんだけど、誰のか知ってる？",translation:"Có chiếc ô trông rất sang trọng này bị để quên trong phòng họp, cậu có biết của ai không?"},{speaker:"B",text:"このブランドと色からして、部長の傘に違いないよ。さっき探していらっしゃったし。",translation:"Nhìn thương hiệu và màu sắc này thì chắc chắn là ô của trưởng phòng rồi. Lúc nãy sếp cũng vừa đi tìm đấy."},{speaker:"A",text:"なるほど、じゃあ今すぐ部長のデスクへ届けておくね。",translation:"Ra là vậy, thế để tớ mang ngay qua bàn làm việc của trưởng phòng nhé."}]},commonMistake:{wrong:"彼は真面目だに違いないから、約束を破るはずがない。",correct:"彼は真面目に違いないから、約束を破るはずがない。",why:"Tính từ đuôi な và Danh từ khi kết hợp với「に違いない」phải bỏ đuôi「だ」(chỉ lấy thân từ hoặc dạng「である」), không được để nguyên「だ」."},note:"Khác với「～はずだ」dựa trên sự tính toán logic hoặc quy luật khách quan,「～に違いない」thể hiện niềm tin và phán đoán quyết đoán mang tính trực cảm, chủ quan của người nói."},{pattern:"～はずだ／はずがない",meaning:"Chắc phải là / Không thể nào là (phán đoán logic)",priority:"common",explanation:"Mẫu 「～はずだ」 dùng để diễn đạt phán đoán hoặc kỳ vọng có căn cứ vững chắc của người nói rằng một sự việc chắc chắn sẽ xảy ra hoặc đúng như vậy. Ngược lại, 「～はずがない」 biểu thị sự phủ định mang tính logic tuyệt đối, khẳng định sự việc không thể nào xảy ra dựa trên lý lẽ rõ ràng. Cấu trúc này thường dựa trên bằng chứng khách quan, quy luật hoặc thông tin đã biết trước chứ không dùng cho suy đoán cảm tính vô căn cứ.",examples:[{sentence:"田中さんは昨日何回も確認したから、書類にミスはないはずだ。",translation:"Anh Tanaka hôm qua đã kiểm tra nhiều lần rồi nên tài liệu chắc chắn không có lỗi sai."},{sentence:"パスワードを教えたのは家族だけだから、他人が知っているはずがない。",translation:"Mật khẩu chỉ có người nhà được biết nên người ngoài không thể nào biết được."}],dialogue:{title:"Tìm chìa khóa",lines:[{speaker:"A",text:"あれ？車の鍵が見当たらないんだけど、どこに置いたっけ。",translation:"Ơ? Không thấy chìa khóa xe đâu cả, mình để ở đâu rồi nhỉ."},{speaker:"B",text:"さっきカバンの中に入れていたよ。ちゃんと探せばあるはずだ。",translation:"Lúc nãy cậu bỏ vào túi xách mà. Nếu tìm kỹ thì chắc chắn phải có ở đó chứ."},{speaker:"A",text:"あ、ポケットの奥に入っていた！見つかってよかった。",translation:"A, nó nằm ở tận sâu trong túi áo! May mà tìm thấy rồi."}]},commonMistake:{wrong:"今日は日曜日だはずだから、市役所は休みだ。",correct:"今日は日曜日のはずだから、市役所は休みだ。",why:"Khi kết hợp với danh từ ở thì hiện tại khẳng định, phải nối bằng 「N + のはずだ」 chứ không dùng 「N + だはずだ」."},note:"「～はずだ」 biểu thị suy luận dựa trên căn cứ logic rõ ràng, còn 「～に違いない」 thiên về sự khẳng định mang tính trực giác chủ quan; ngoài ra không dùng 「～はずだ」 cho hành vi có chủ ý của chính bản thân người nói."},{pattern:"～わけだ／わけがない／わけにはいかない",meaning:"Có nghĩa là / Không thể nào / Không thể không làm",priority:"common",explanation:"Nhóm mẫu câu với「わけ」diễn đạt mối quan hệ logic, lý do hoặc quy chuẩn đạo đức xã hội. Trong đó,「～わけだ」dùng để giải thích kết quả tất yếu hoặc vỡ lẽ ra lý do ('thảo nào/hóa ra là').「～わけがない」thể hiện sự phủ định tuyệt đối dựa trên căn cứ xác thực ('tuyệt đối không có lý nào'). Còn「～わけにはいかない」biểu thị việc không thể làm do rào cản lương tâm, trách nhiệm hay quy tắc xã hội dù bản thân có muốn.",examples:[{sentence:"彼があんなに一生懸命勉強したんだから、試験に落ちるわけがない。",translation:"Cậu ấy đã học hành chăm chỉ đến thế cơ mà, tuyệt đối không có lý nào lại trượt kỳ thi được."},{sentence:"明日は大事なプレゼンがあるので、今夜は夜更かししてゲームをするわけにはいかない。",translation:"Ngày mai có buổi thuyết trình quan trọng nên tối nay tôi không thể thức khuya chơi game được."}],dialogue:{title:"Nghỉ làm đột xuất",lines:[{speaker:"A",text:"熱が39度もあるのに、無理して出勤するわけにはいかないよ。",translation:"Sốt đến tận 39 độ thế này thì không thể cố chấp đi làm được đâu."},{speaker:"B",text:"そうですね。今日はお休みをいただいて病院に行きます。",translation:"Vâng ạ. Hôm nay em xin phép nghỉ để đi bệnh viện khám."},{speaker:"A",text:"うん、仕事のことは心配しないで、ゆっくり休んでね。",translation:"Ừ, đừng lo lắng về công việc, cứ nghỉ ngơi cho lại sức nhé."}]},commonMistake:{wrong:"彼は日本に10年も住んでいるのだから、日本語が下手だわけがない。",correct:"彼は日本に10年も住んでいるのだから、日本語が下手なわけがない。",why:"Trước「わけ」, tính từ đuôi な ở thể khẳng định hiện tại phải đổi「だ」thành「な」(下手なわけがない)."},note:"Cần phân biệt「～わけがない」(tuyệt đối không có khả năng xảy ra) với「～わけではない」(không hẳn là/không nhất thiết là, mang nghĩa phủ định một phần)."}],138:[{pattern:"～ものの",meaning:"Tuy nhiên, dù vậy nhưng (nhượng bộ thực tế)",priority:"core",explanation:"Mẫu 「～ものの」 dùng để diễn đạt sự nhượng bộ dựa trên sự thật khách quan: dù công nhận vế trước là đúng sự thật, nhưng vế sau lại diễn ra trái với kỳ vọng thông thường. Cấu trúc này thường kết hợp với thể thông thường (tính từ đuôi な và danh từ thường đi với な/であるものの). Mẫu câu mang sắc thái trang trọng, dùng nhiều trong văn viết hoặc lời tự sự, và vế sau chỉ nêu hiện thực chứ không dùng câu mệnh lệnh hay rủ rê.",examples:[{sentence:"手術は無事に成功したものの、完全に回復するまでにはまだ時間がかかりそうだ。",translation:"Mặc dù ca phẫu thuật đã thành công tốt đẹp nhưng có vẻ vẫn cần thêm thời gian để hồi phục hoàn toàn."},{sentence:"新しい職場に転職したものの、業務内容が思っていたものと違って戸惑っている。",translation:"Dù đã chuyển sang chỗ làm mới nhưng nội dung công việc khác với những gì tôi nghĩ khiến tôi khá bỡ ngỡ."}],dialogue:{title:"Chiếc máy tính bảng mới",lines:[{speaker:"A",text:"新しいタブレットを買ったものの、使い方が難しくてほとんど触っていないんだ。",translation:"Dù tớ đã mua chiếc máy tính bảng mới nhưng cách dùng phức tạp quá nên hầu như chưa đụng vào."},{speaker:"B",text:"ええ、もったいないですね。画面が大きくて動画を見るだけでも便利ですよ。",translation:"Ủa vậy uổng quá. Màn hình to nên chỉ cần xem phim thôi cũng tiện lắm đấy."},{speaker:"A",text:"そうだね、せっかく買ったから少しずつ慣れるようにしてみるよ。",translation:"Ừ nhỉ, mất công mua rồi nên tớ sẽ thử làm quen dần dần xem sao."}]},commonMistake:{wrong:"この靴はデザインが好きものの、サイズが少し合わない。",correct:"この靴はデザインが好きなものの、サイズが少し合わない。",why:"Trước 「ものの」, tính từ đuôi な phải giữ 「な」 (hoặc dùng 「である」) chứ không được nối trực tiếp vào gốc từ."},note:"So với 「～のに」 hay 「～けれども」, 「～ものの」 mang sắc thái văn viết trang trọng hơn và vế sau tuyệt đối không dùng hình thức mệnh lệnh hay ý chí."},{pattern:"～ざるを得ない",meaning:"Không thể không làm, buộc phải làm (không có lựa chọn)",priority:"common",explanation:"Mẫu câu diễn tả ý nghĩa 'không thể không làm / đành phải, buộc phải làm' một việc gì đó dù trong lòng thực sự không muốn, vì tình thế hay hoàn cảnh khách quan ép buộc và không còn lựa chọn nào khác. Mẫu này gắn sau động từ thể ない bỏ ない (riêng する đổi thành せざるを得ない), mang sắc thái trang trọng, văn phong viết hoặc các quyết định nghiêm túc, bất đắc dĩ.",examples:[{sentence:"これほど赤字が続いている以上、不採算部門を縮小せざるを得ない。",translation:"Tình trạng thua lỗ kéo dài đến mức này thì chúng tôi đành phải thu hẹp các bộ phận kinh doanh không có lãi."},{sentence:"大型の台風が接近しており、安全面を考慮して明日の屋外イベントは中止せざるを得ない。",translation:"Cơn bão lớn đang tiến gần, xét về mặt an toàn thì chúng tôi buộc phải hủy sự kiện ngoài trời ngày mai."}],dialogue:{title:"Hoãn lịch công tác",lines:[{speaker:"A",text:"山田部長、現地の工場でシステム障害が発生したため、出張の日程を変更せざるを得なくなりました。",translation:"Trưởng phòng Yamada, do nhà máy tại hiện trường xảy ra sự cố hệ thống nên tôi đành phải thay đổi lịch công tác."},{speaker:"B",text:"そうか、それは大変だな。先方の担当者にはもう連絡を入れたのかい？",translation:"Vậy à, vất vả rồi đấy. Cậu đã liên lạc báo cho người phụ trách bên đối tác chưa?"},{speaker:"A",text:"はい、先ほど事情を説明して、来週への再調整をお願いいたしました。",translation:"Vâng, vừa rồi tôi đã giải thích tình hình và xin dời lại sang tuần sau rồi ạ."}]},commonMistake:{wrong:"原料が高騰しているため、商品の値上げをしざるを得ない。",correct:"原料が高騰しているため、商品の値上げをせざるを得ない。",why:"Động từ nhóm 3 「する」 theo ngữ pháp cổ phải chuyển thành 「せざるを得ない」 chứ không chia thành 「しざるを得ない」."},note:"Cần tránh nhầm với 「～ずにはいられない」 (không kìm nén được cảm xúc bộc phát từ bên trong), trong khi 「～ざるを得ない」 là buộc phải hành động theo lý trí do hoàn cảnh bên ngoài ép buộc."},{pattern:"～ことにする／ことになる",meaning:"Quyết định (ý chí) / Trở thành việc (quyết định bên ngoài)",priority:"common",explanation:"「～ことにする」biểu thị quyết định xuất phát từ ý chí chủ quan của chính người nói. Trong khi đó,「～ことになる」diễn tả một sự việc đã được định đoạt do hoàn cảnh khách quan, người khác hoặc tập thể quyết định mà người nói chỉ tiếp nhận kết quả. Cả hai mẫu đều đi sau động từ thể từ điển (Vる) hoặc thể phủ định (Vない). Khi dùng ở dạng「～ことにしている」sẽ chỉ thói quen tự giác của bản thân, còn「～ことになっている」dùng cho quy định, luật lệ hoặc lịch trình đã ấn định.",examples:[{sentence:"自分自身の将来を真剣に考えた末、今の会社を辞めて新しい分野へ転職することにする。",translation:"Sau khi suy nghĩ nghiêm túc về tương lai của bản thân, tôi quyết định sẽ nghỉ công ty hiện tại để chuyển sang lĩnh vực mới."},{sentence:"会社の組織再編に伴い、来期の初めから大阪支社へ異動することになった。",translation:"Cùng với việc tái cơ cấu của công ty, tôi được quyết định sẽ chuyển công tác về chi nhánh Osaka từ đầu kỳ tới."}],dialogue:{title:"Kế hoạch đi công tác",lines:[{speaker:"A",text:"山田さん、来月の海外出張の担当者はもう決まりましたか。",translation:"Anh Yamada, đã quyết định ai là người phụ trách chuyến công tác nước ngoài tháng sau chưa?"},{speaker:"B",text:"はい、部長と相談した結果、私が一人でベトナムへ行くことになりました。",translation:"Vâng, sau khi trao đổi với trưởng phòng, đã có quyết định là tôi sẽ đi Việt Nam một mình."},{speaker:"A",text:"そうなんですね。準備でいろいろ忙しくなると思いますが、頑張ってください。",translation:"Vậy à. Chắc việc chuẩn bị sẽ bận rộn lắm đây, anh cố gắng lên nhé."}]},commonMistake:{wrong:"会社の方針が決まって、来月から全員私服で勤務することにしました。",correct:"会社の方針が決まって、来月から全員私服で勤務することになりました。",why:"Quyết định bắt nguồn từ phương châm/chỉ thị của công ty (yếu tố khách quan, tập thể) nên phải dùng「～ことになる」thay vì「～ことにする」(chỉ ý chí cá nhân người nói)."},note:"Phân biệt dạng tiếp diễn:「～ことにしている」biểu thị thói quen hoặc nguyên tắc do bản thân tự đặt ra, còn「～ことになっている」chỉ quy tắc, tập quán hoặc lịch trình của tổ chức/xã hội."},{pattern:"～ことにしている",meaning:"Thói quen tự đặt ra, luôn luôn làm theo quyết định của mình",priority:"common",explanation:"Mẫu câu này dùng để diễn tả một thói quen, quy tắc hoặc nguyên tắc sống do chính bản thân tự đặt ra và đang duy trì thực hiện đều đặn theo ý chí của mình. Sắc thái của câu nhấn mạnh sự chủ động và quyết tâm cá nhân, không phải do ai ép buộc hay quy định bên ngoài áp đặt. Cấu trúc đi kèm là động từ thể từ điển hoặc thể phủ định (Vる / Vない) kết hợp với ことにしている.",examples:[{sentence:"健康を維持するために、どんなに忙しくても毎朝30分ジョギングすることにしている。",translation:"Để duy trì sức khỏe, dù bận rộn đến mấy tôi cũng tự đặt ra quy tắc chạy bộ 30 phút mỗi sáng."},{sentence:"日本語力を落とさないように、通勤電車の中では必ず日本のニュースを1本読むことにしている。",translation:"Để không bị mai một tiếng Nhật, tôi luôn duy trì thói quen đọc một bài báo tin tức Nhật Bản mỗi khi đi tàu đi làm."}],dialogue:{title:"Bí quyết giữ gìn sức khỏe",lines:[{speaker:"A",text:"田中さん、いつもお肌の調子が良さそうですね。何か特別なケアをしているんですか。",translation:"Chị Tanaka dạo này da dẻ nhìn đẹp thế. Chị có bí quyết chăm sóc đặc biệt nào không?"},{speaker:"B",text:"特に高価な化粧品は使っていませんが、毎晩寝る前に必ずストレッチをして、白湯を飲むことにしているんです。",translation:"Tôi không dùng mỹ phẩm đắt tiền gì đâu, nhưng tôi luôn duy trì thói quen giãn cơ và uống nước ấm trước khi đi ngủ mỗi tối."},{speaker:"A",text:"そうなんですね！手軽にできそうだから、私も今日からやってみます。",translation:"Vậy hả! Nghe có vẻ dễ làm, từ tối nay tôi cũng sẽ làm thử xem sao."}]},commonMistake:{wrong:"日本の法律では、車を運転するときシートベルトをしめることにしている。",correct:"日本の法律では、車を運転するときシートベルトをしめることになっている。",why:"Khi nói về quy định pháp luật, nội quy tập thể hay quy tắc xã hội áp đặt từ bên ngoài, phải dùng 「～ことになっている」 chứ không dùng 「～ことにしている」 (chỉ thói quen/quy tắc tự thân)."},note:"Phân biệt với 「～ことにした」 (vừa mới đưa ra quyết định một lần); 「～ことにしている」 biểu thị quyết định đó đã trở thành một thói quen hoặc nguyên tắc đang được duy trì đều đặn."},{pattern:"～ものだ／ものではない",meaning:"Là điều hiển nhiên / Không nên (lẽ thường tình, hồi tưởng)",priority:"common",explanation:"Mẫu ngữ pháp này dùng để biểu thị một chân lý, quy luật tự nhiên hoặc đạo lý, lẽ thường tình trong cuộc sống mà ai cũng coi là hiển nhiên. Dạng 「～ものだ」thể hiện điều nên làm hoặc bản chất vốn có theo chuẩn mực xã hội, còn 「～ものではない」mang sắc thái khuyên răn, cảnh báo không nên làm điều gì đó. Cần lưu ý mẫu này chỉ dùng để nói về các nguyên lý phổ quát chung, không dùng khi đưa ra lời khuyên hay mệnh lệnh trực tiếp cho một cá nhân trong tình huống cụ thể.",examples:[{sentence:"困っている人がいたら、親切にして助け合うものだ。",translation:"Khi thấy người gặp khó khăn thì nên đối xử tốt và giúp đỡ lẫn nhau, đó là lẽ thường tình."},{sentence:"人の悪口を本人のいないところで言うものではない。",translation:"Không nên nói xấu sau lưng người khác khi họ không có mặt."}],dialogue:{title:"Lời khuyên cho hậu bối",lines:[{speaker:"A",text:"先輩、大事なプレゼンで失敗してしまって、すごく落ち込んでいます。",translation:"Tiền bối ơi, em làm hỏng buổi thuyết trình quan trọng nên đang thấy nản lòng quá."},{speaker:"B",text:"誰でも初めての時は失敗するものだよ。落ち込まずに次へ活かそう。",translation:"Ai trong lần đầu tiên cũng đều dễ thất bại cả thôi, đó là chuyện bình thường mà. Đừng nản lòng mà hãy rút kinh nghiệm cho lần sau nhé."},{speaker:"A",text:"はい、アドバイスありがとうございます！気持ちを切り替えて頑張ります。",translation:"Vâng, em cảm ơn lời khuyên của tiền bối! Em sẽ vực dậy tinh thần và cố gắng ạ."}]},commonMistake:{wrong:"田中さん、熱があるなら今日は無理をせず早く帰るものですよ。",correct:"田中さん、熱があるなら今日は無理をせず早く帰ったほうがいいですよ。",why:"「～ものだ」chỉ nêu lên đạo lý hoặc quy tắc chung của xã hội, không dùng để đưa ra lời khuyên trực tiếp cho một cá nhân cụ thể trong hoàn cảnh nhất thời."},note:"Không dùng 「～ものだ／ものではない」để khuyên bảo hoặc ra lệnh cho cấp trên, đồng thời tránh nhầm với 「～べきだ」（thể hiện bổn phận, nghĩa vụ mang tính phán đoán chủ quan của người nói）."}],139:[{pattern:"～ものの",meaning:"Tuy là... nhưng (đã làm/đã xảy ra, nhưng kết quả trái với mong đợi)",priority:"core",explanation:'Mẫu 「～ものの」 dùng để diễn tả ý nghĩa "tuy... nhưng...", thừa nhận sự thật ở vế trước đã xảy ra nhưng vế sau lại là kết quả không tương xứng hoặc trái với kỳ vọng thông thường. Cấu trúc này thường đi kèm với những sự việc đã được xác thực, mang sắc thái tiếc nuối, bất mãn hoặc thừa nhận một sự thật có phần bất đắc dĩ. Ngữ pháp này hay được sử dụng trong văn viết hoặc phong cách giao tiếp trang trọng, lịch sự.',examples:[{sentence:"手術は成功したものの、完全に回復するまでにはまだ時間がかかりそうだ。",translation:"Tuy ca phẫu thuật đã thành công nhưng có vẻ vẫn cần thêm thời gian để hồi phục hoàn toàn."},{sentence:"日本語能力試験N1に合格したものの、実際のビジネス会話ではまだまだうまく話せない。",translation:"Tuy đã đỗ kỳ thi JLPT N1 nhưng trong giao tiếp công việc thực tế tôi vẫn chưa thể nói lưu loát được."}],dialogue:{title:"Học bằng lái xe",lines:[{speaker:"A",text:"運転免許を取ったものの、怖くて一度も一人で運転したことがないんだ。",translation:"Tuy đã lấy được bằng lái xe nhưng tớ sợ nên chưa từng tự lái một mình lần nào cả."},{speaker:"B",text:"せっかく取ったのにもったいないよ。今度一緒に練習しようか。",translation:"Uổng công thi lấy bằng thế. Hay bữa nào để tớ đi tập cùng cậu nhé?"},{speaker:"A",text:"本当？助手席に乗ってくれるとすごく助かるよ。",translation:"Thật sao? Nếu cậu chịu ngồi ghế phụ hướng dẫn thì giúp tớ nhiều lắm đấy."}]},commonMistake:{wrong:"休日のものの、仕事が山積みで休めない。",correct:"休日であるものの、仕事が山積みで休めない。",why:"Với danh từ, mẫu ～ものの phải kết hợp dạng 「N + であるものの」 chứ không được dùng 「N + のものの」."},note:"Vế sau của ～ものの luôn là một sự thật mang tính diễn tả thực tế, không dùng câu mang ý chí, mệnh lệnh hay rủ rê như ～てください, ～よう, ～つもりだ."},{pattern:"～とはいえ",meaning:"Nói vậy chứ..., tuy là... nhưng (thừa nhận P là đúng, rồi đưa ra hạn chế Q)",priority:"common",explanation:'Mẫu câu này dùng để diễn đạt ý nghĩa "dù sự thật đúng là như vậy, nhưng trên thực tế lại không hẳn đạt đến mức kỳ vọng đó". Người nói trước hết thừa nhận tiền đề/sự thật ở vế trước là đúng, sau đó đưa ra một đánh giá, hạn chế hoặc tình huống đối lập ở vế sau. Cấu trúc mang sắc thái khách quan, trang trọng, thường xuất hiện trong văn viết báo chí, xã luận hoặc các cuộc thảo luận nghiêm túc.',examples:[{sentence:"いくら便利になったとはいえ、すべての作業をAIに任せるのはリスクが大きい。",translation:"Dù nói là đã trở nên tiện lợi đến đâu đi nữa, việc phó mặc toàn bộ công việc cho AI vẫn tiềm ẩn rủi ro rất lớn."},{sentence:"熱が下がったとはいえ、まだ完治したわけではないので、今日も一日安静にしていてください。",translation:"Tuy nói là đã hạ sốt rồi nhưng chưa hẳn là đã khỏi hoàn toàn, vì vậy hôm nay anh hãy tiếp tục nghỉ ngơi tĩnh dưỡng cả ngày nhé."}],dialogue:{title:"Đánh giá sản phẩm mới",lines:[{speaker:"A",text:"新商品の売り上げ、滑り出しはかなり好調のようですね。",translation:"Doanh số của sản phẩm mới khởi đầu có vẻ khá thuận lợi anh nhỉ."},{speaker:"B",text:"ええ。とはいえ、まだ発売から1週間しか経っていませんから、今後の動向を慎重に見極める必要があります。",translation:"Vâng. Nói vậy chứ cũng mới chỉ ra mắt được một tuần thôi, nên chúng ta cần thận trọng theo dõi sát sao diễn biến sắp tới."},{speaker:"A",text:"そうですね。気を緩めずにプロモーションを続けましょう。",translation:"Đúng vậy. Chúng ta đừng lơ là mà hãy tiếp tục duy trì các hoạt động quảng bá nhé."}]},commonMistake:{wrong:"いくら静かなとはいえ、駅から徒歩30分の物件は不便すぎる。",correct:"いくら静か（だ）とはいえ、駅から徒歩30分の物件は不便すぎる。",why:"Tính từ đuôi な và Danh từ khi kết hợp với 「とはいえ」 phải nối trực tiếp hoặc đi với 「だ」, không kết hợp với 「な」 như mẫu 「ものの」."},note:"So với 「～ものの」 (thường dùng để tường thuật sự việc thực tế gắn với trải nghiệm cá nhân), 「～話し言葉 / 書き言葉」 của 「～とはいえ」 mang tính nhận định khách quan hơn và vế sau thường đi kèm lời khuyên, cảnh báo hoặc phán đoán."},{pattern:"～に限り／に限って",meaning:"Chỉ ~ mới / Chỉ dành cho ~ (giới hạn đặc biệt, nhấn mạnh tính ngoại lệ)",priority:"common",explanation:'Mẫu 「～に限り／に限って」 đi sau danh từ nhằm biểu thị sự giới hạn đặc biệt, mang ý nghĩa "chỉ riêng đối tượng N này mới...". Ngữ pháp này thường xuất hiện trong các văn bản thông báo, quy định hoặc quảng cáo trang trọng để nhấn mạnh trường hợp ngoại lệ hoặc điều kiện ưu đãi riêng biệt. Vế sau luôn là câu khẳng định thể hiện sự đối đãi đặc biệt, hành động hoặc quyền lợi được áp dụng, không đi với dạng phủ định triệt để.',examples:[{sentence:"初回ご利用のお客様に限り、1時間の無料体験レッスンをご提供しております。",translation:"Chỉ dành riêng cho khách hàng sử dụng dịch vụ lần đầu, chúng tôi cung cấp 1 giờ học thử miễn phí."},{sentence:"本コンテストは、日本国内の大学に在籍する留学生に限って応募資格が認められます。",translation:"Cuộc thi này chỉ công nhận tư cách dự thi dành riêng cho các bạn du học sinh đang theo học tại các trường đại học ở Nhật Bản."}],dialogue:{title:"Ưu đãi phòng chờ VIP",lines:[{speaker:"A",text:"ゴールド会員証をご提示いただいたお客様に限り、こちらの特別ラウンジをご利用いただけます。",translation:"Chỉ những quý khách xuất trình thẻ hội viên Gold mới có thể sử dụng phòng chờ đặc biệt này ạ."},{speaker:"B",text:"そうなんですね。同伴者は一緒に入れないのでしょうか。",translation:"Vậy à. Người đi cùng không được vào chung hả bạn?"},{speaker:"A",text:"申し訳ございませんが、ご同伴者様は1名様につき別途追加料金が必要となります。",translation:"Thành thật xin lỗi quý khách, người đi cùng sẽ cần trả thêm phụ phí cho mỗi người ạ."}]},commonMistake:{wrong:"未成年者に限り、店内でのお酒の購入はできません。",correct:"20歳以上の成人の方に限り、店内でのお酒の購入が可能です。",why:"Mẫu 「～に限り」 dùng để chỉ trường hợp ngoại lệ được hưởng quyền lợi hoặc đối đãi đặc biệt nên vế sau phải là câu khẳng định, không dùng với câu mang tính cấm đoán hay phủ định như 「～できません」."},note:'Cần chú ý 「～に限って」 ngoài nghĩa giới hạn giống 「～に限り」 thì trong văn nói thường ngày còn có nghĩa riêng biệt là "đúng vào lúc... thì lại gặp chuyện không may" hoặc "riêng ai đó thì tuyệt đối tin tưởng không làm chuyện xấu".'},{pattern:"～をもって",meaning:"Bằng ~, kể từ ~ (chỉ phương tiện hoặc thời điểm kết thúc — văn viết trang trọng)",priority:"common",explanation:"Mẫu 「～をもって」 là cấu trúc trang trọng trong tiếng Nhật, chủ yếu dùng trong văn viết hành chính, thông báo chính thức hoặc phát biểu trang nghiêm. Cấu trúc này có hai cách dùng chính: một là chỉ mốc thời gian hay giới hạn kết thúc của một sự việc (tính đến hết, kể từ...), hai là chỉ phương tiện hoặc phương thức thực hiện hành động (bằng, bằng cách...). Mẫu câu này mang sắc thái trang trọng nên không dùng cho các phương tiện cụ thể hàng ngày hay trong giao tiếp suồng sã.",examples:[{sentence:"3月31日をもって、長年勤めた会社を定年退職することになりました。",translation:"Kể từ ngày 31 tháng 3, tôi sẽ chính thức nghỉ hưu sau nhiều năm cống hiến cho công ty."},{sentence:"試験の結果につきましては、後日書面をもってお知らせいたします。",translation:"Về kết quả của kỳ thi, chúng tôi sẽ thông báo bằng văn bản vào một ngày sau."}],dialogue:{title:"Thông báo kết quả tuyển dụng",lines:[{speaker:"A",text:"先日の面接の結果は、どのように連絡が来るのでしょうか。",translation:"Kết quả buổi phỏng vấn hôm trước sẽ được liên lạc bằng hình thức nào vậy ạ?"},{speaker:"B",text:"合否の結果は、来週の月曜日にメールをもってお伝えする予定です。",translation:"Kết quả đỗ hay trượt dự kiến sẽ được chúng tôi thông báo bằng email vào thứ Hai tuần tới."},{speaker:"A",text:"承知いたしました。ご連絡をお待ちしております。",translation:"Tôi đã hiểu rồi ạ. Tôi sẽ đợi thông tin liên lạc từ phía công ty."}]},commonMistake:{wrong:"明日をもって新しいプロジェクトを始めます。",correct:"明日から新しいプロジェクトを始めます。",why:"Khi diễn đạt mốc thời gian, 「～をもって」 chỉ dùng để biểu thị thời điểm kết thúc một sự việc chứ không dùng cho thời điểm bắt đầu."},note:"Khi phát biểu trực tiếp trong các buổi lễ hoặc sự kiện trang trọng, mẫu này thường được biến chuyển thành dạng lịch sự hơn là 「～をもちまして」."},{pattern:"～や否や",meaning:"Ngay khi vừa ~ (liền ngay sau đó, không có khoảng cách)",priority:"common",explanation:"Mẫu ngữ pháp 「～や否や」 dùng để diễn tả một hành động hoặc sự việc xảy ra gần như ngay tức khắc sau khi hành động phía trước vừa hoàn thành. Cấu trúc này luôn kết hợp với động từ thể từ điển (V-る) ở vế trước, còn vế sau mô tả sự việc diễn biến chớp nhoáng, thường chia ở thì quá khứ. Đây là cách diễn đạt mang tính văn viết, trang trọng và mang sắc thái khách quan, thường xuất hiện trong phóng sự, tác phẩm văn học hoặc tin tức thời sự.",examples:[{sentence:"社長が会場に入るや否や、集まった大勢の記者たちから一斉にフラッシュがたかれた。",translation:"Giám đốc vừa bước vào hội trường là lập tức các phóng viên tập trung tại đó bấm đèn flash lia lịa."},{sentence:"息子は学校から帰ってくるや否や、ランドセルを玄関に放り投げて遊びに出かけた。",translation:"Con trai tôi vừa đi học về đến nhà là quẳng ngay cặp sách ở huyền quan rồi chạy tót ra ngoài chơi."}],dialogue:{title:"Tình hình mở bán vé",lines:[{speaker:"A",text:"昨日発売された人気バンドのコンサートチケット、取れた？",translation:"Vé xem hòa nhạc của ban nhạc nổi tiếng mở bán hôm qua, cậu săn được không?"},{speaker:"B",text:"全然だめだったよ。販売サイトがオープンするや否やアクセスが殺到して、一分もたたないうちに売り切れたんだ。",translation:"Hoàn toàn không thể luôn. Trang web vừa mở bán là lượt truy cập ồ ạt đổ dồn tới, chưa đầy một phút đã bán hết sạch."},{speaker:"A",text:"やっぱりすごい倍率だね。追加公演があることを祈るしかないよ。",translation:"Đúng là tỷ lệ chọi cao khủng khiếp thật. Đành cầu mong có thêm đêm diễn phụ thôi."}]},commonMistake:{wrong:"家に着くや否や、すぐに私に連絡してください。",correct:"家に着いたら、すぐに私に連絡してください。",why:"Vế sau của 「～や否や」 chỉ dùng để tường thuật sự việc mang tính khách quan đã xảy ra, tuyệt đối không dùng câu mang ý chí, nhờ vả hay mệnh lệnh như 「～てください」 hay 「～よう」."},note:"Khác với 「～とたんに」 dùng được phổ biến trong cả hội thoại hàng ngày, 「～や否や」 mang văn phong trang trọng hơn và tuyệt đối không đi kèm dạng quá khứ ở vế trước (không nói V-たや否や)."},{pattern:"～ゆえに／ゆえ",meaning:"Chính vì ~, do ~ mà (nguyên nhân — văn viết trang trọng)",priority:"common",explanation:'「～ゆえに／ゆえ」 mang ý nghĩa "chính vì... nên..." hoặc "do... mà...", dùng để nêu bật nguyên nhân dẫn đến một kết quả hay tình trạng nhất định. Mẫu câu này mang sắc thái trang trọng, đậm chất văn viết, thường xuất hiện trong văn nghị luận, thư từ chính thức, tác phẩm văn học hoặc lời trần tình, xin lỗi. Vế sau câu thường diễn tả kết quả tất yếu hoặc khó tránh khỏi, không dùng cho các câu cầu khiến hay rủ rê trong giao tiếp thân mật thường ngày.',examples:[{sentence:"国民の信頼を得ている指導者であるゆえに、彼の発言は常に大きな影響力を持つ。",translation:"Chính vì là nhà lãnh đạo nhận được sự tin tưởng của người dân, nên những phát ngôn của ông ấy luôn có sức ảnh hưởng to lớn."},{sentence:"不慣れな土地での一人暮らしゆえ、最初は不安で仕方がなかった。",translation:"Do sống một mình ở vùng đất xa lạ, nên ban đầu tôi cảm thấy vô cùng bất an."}],dialogue:{title:"Áp lực của người dẫn đầu",lines:[{speaker:"A",text:"彼は業界のトップランナーであるがゆえに、常に周囲からの過度な期待に苦しんでいるようだね。",translation:"Chính vì là người dẫn đầu ngành, dường như anh ấy luôn phải khổ sở vì những kỳ vọng quá mức từ xung quanh nhỉ."},{speaker:"B",text:"ええ、注目度が高い分、小さなミスも許されない重圧があるのでしょう。",translation:"Vâng, càng được chú ý nhiều thì áp lực không được phép mắc lỗi nhỏ càng lớn mà."},{speaker:"A",text:"その重圧を乗り越えてこそ真のプロと言えるのだろうが、見ていて胸が痛むよ。",translation:"Vẫn biết vượt qua được áp lực đó mới là dân chuyên nghiệp thực thụ, nhưng nhìn vào thấy xót xa thật."}]},commonMistake:{wrong:"有名だゆえに、プライベートの時間が全くない。",correct:"有名であるゆえに、プライベートの時間が全くない。",why:"Tính từ đuôi な khi kết hợp với 「ゆえに」 phải ở dạng 「～な／である」 chứ tuyệt đối không đi trực tiếp với 「だ」."},note:"Mẫu này còn có biến thể nhấn mạnh là 「～がゆえ（に）」 (như: 愛するがゆえに) và có thể đứng đầu câu như một liên từ nối 「それゆえ（に）」."},{pattern:"～ばこそ",meaning:"Chính vì ~ mới (nhấn mạnh nguyên nhân duy nhất — tích cực)",priority:"common",explanation:'Mẫu ngữ pháp 「～ばこそ」 dùng để nhấn mạnh lý do cốt lõi, mang tính quyết định dẫn đến một hành vi hay kết quả nào đó ("Chính vì... nên mới..."). Vế sau thường là những giải thích tích cực, lời thanh minh có thiện ý hoặc kết quả sau nhiều nỗ lực, hay kết thúc bằng 「～のだ/～のです」. Mẫu này mang sắc thái trang trọng, văn viết và không dùng cho các nguyên nhân ngẫu nhiên mang lại hậu quả xấu.',examples:[{sentence:"健康であればこそ、毎日のハードな仕事にも耐えられるのです。",translation:"Chính vì có sức khỏe tốt nên tôi mới có thể chịu đựng được khối lượng công việc vất vả mỗi ngày."},{sentence:"苦しい練習を重ねて乗り越えてくればこそ、優勝したときの喜びも大きい。",translation:"Chính nhờ kiên trì vượt qua quá trình luyện tập gian khổ mà niềm vui khi giành chức vô địch mới to lớn đến vậy."}],dialogue:{title:"Kỳ vọng của cấp trên",lines:[{speaker:"A",text:"新人の君にこんな重要な仕事を任せるのは、将来性を期待していればこそだよ。",translation:"Giao công việc quan trọng này cho người mới như cậu chính là vì tôi kỳ vọng vào tiềm năng tương lai của cậu đấy."},{speaker:"B",text:"ありがとうございます。ご期待に応えられるよう、全力を尽くします！",translation:"Em xin cảm ơn ạ. Em sẽ nỗ lực hết mình để không phụ sự kỳ vọng của anh!"},{speaker:"A",text:"プレッシャーを感じすぎず、思い切ってやってごらん。",translation:"Đừng quá áp lực, cứ tự tin mà làm hết sức mình nhé."}]},commonMistake:{wrong:"雨が激しく降ればこそ、電車が遅れて遅刻してしまった。",correct:"雨が激しく降ったせいで、電車が遅れて遅刻してしまった。",why:"「～ばこそ」chỉ dùng để nhấn mạnh lý do tích cực, giải thích thiện chí hoặc nỗ lực, tuyệt đối không dùng cho sự việc ngẫu nhiên dẫn đến hậu quả tiêu cực khách quan."},note:"So với 「～からこそ」 vốn dùng tự nhiên cả trong giao tiếp thân mật hằng ngày, 「～ばこそ」 mang giọng điệu trang trọng, nghiêm túc và đậm chất văn viết hơn."},{pattern:"～ないことには",meaning:"Trừ khi ~, nếu không ~ thì không thể (điều kiện tiên quyết)",priority:"common",explanation:"Mẫu ngữ pháp này biểu thị rằng hành vi hoặc trạng thái ở vế trước là điều kiện tiên quyết, nếu không thực hiện thì không thể đạt được kết quả ở vế sau. Vế sau của câu luôn bắt buộc đi kèm với các hình thức mang tính phủ định hoặc bất khả năng như 「～ない」「～できない」「～判断できない」. Mẫu câu thường được sử dụng khi người nói muốn nhấn mạnh tính tất yếu của điều kiện tiên quyết trước khi đưa ra phán đoán hay hành động tiếp theo.",examples:[{sentence:"詳しい予算案が決まらないことには、このプロジェクトを前に進めることはできません。",translation:"Trừ khi có dự toán ngân sách chi tiết, nếu không thì chúng ta không thể thúc đẩy dự án này tiến triển được."},{sentence:"本人に直接会って話を聞いてみないことには、採用するかどうか判断しかねます。",translation:"Nếu không gặp trực tiếp ứng viên để trao đổi thì khó mà phán đoán có nên tuyển dụng hay không."}],dialogue:{title:"Bàn kế hoạch du lịch",lines:[{speaker:"A",text:"来月の社員旅行、そろそろホテルの予約を取ったほうがいいんじゃない？",translation:"Chuyến du lịch công ty tháng sau, chẳng phải nên đặt phòng khách sạn dần đi sao?"},{speaker:"B",text:"そうですね。でも、参加人数が確定しないことには、部屋の数を決められませんよ。",translation:"Đúng thế nhỉ. Nhưng nếu số lượng người tham gia chưa chốt xong thì không thể quyết định số phòng được đâu."},{speaker:"A",text:"じゃあ、今日中に全員に出欠の確認を取りましょう。",translation:"Vậy thì trong ngày hôm nay chúng ta hãy đi xác nhận tham gia hay không với tất cả mọi người nhé."}]},commonMistake:{wrong:"詳しい事情を聞かないことには、すぐに対策を決めましょう。",correct:"詳しい事情を聞かないことには、対策を決められません。",why:"Vế sau của 「～ないことには」 bắt buộc phải là kết luận mang tính phủ định hoặc biểu thị sự bất khả năng, tuyệt đối không dùng câu khẳng định, mệnh lệnh hay rủ rê."},note:"Mẫu này rất gần nghĩa với 「～てからでないと」 nhưng 「～ないことには」 nhấn mạnh điều kiện giả định phủ định và tính bất khả năng ở vế sau mạnh mẽ hơn."}],140:[{pattern:"～一方だ",meaning:"Xu hướng chỉ tăng/giảm một chiều",priority:"core",explanation:"Mẫu câu 「～一方だ」 đi kèm với động từ thể từ điển (V-ru) biểu thị sự biến đổi, diễn tả một xu hướng hoặc tình trạng đang liên tục thay đổi theo một chiều không ngừng. Mẫu này mang ý nghĩa 'ngày càng...', 'chỉ toàn theo chiều hướng...', và thường dùng nhiều cho các biến chuyển mang tính bất lợi, tiêu cực (như vật giá tăng, bệnh tình xấu đi). Nó nhấn mạnh tính chất liên tục của sự thay đổi và hiện tại chưa có dấu hiệu dừng lại.",examples:[{sentence:"最近は物価が上がる一方だ。生活費を少しでも節約する工夫をしなければならない。",translation:"Dạo gần đây giá cả cứ ngày một tăng cao. Chúng ta phải tìm cách tiết kiệm chi phí sinh hoạt dù chỉ một chút."},{sentence:"祖父は退院した後も体力が落ちる一方だ。",translation:"Ông tôi sau khi xuất viện thể lực cứ ngày một giảm sút."}],dialogue:{title:"Tình hình công việc bận rộn",lines:[{speaker:"A",text:"最近、新規プロジェクトの担当になってから業務量が増える一方だよ。",translation:"Dạo này từ khi phụ trách dự án mới, khối lượng công việc của tớ cứ ngày một tăng lên đấy."},{speaker:"B",text:"無理しないでね。体を壊したら元も子もないから、休める時はちゃんと休んで。",translation:"Đừng cố quá sức nhé. Làm việc hại thân thì chẳng còn ý nghĩa gì đâu, lúc nghỉ được thì nghỉ ngơi tử tế vào."},{speaker:"A",text:"ありがとう。一段落したら有給休暇を取ってゆっくり休むつもりだよ。",translation:"Cảm ơn cậu. Khi mọi việc tạm ổn định, tớ tính sẽ xin nghỉ phép để nghỉ ngơi thư giãn."}]},commonMistake:{wrong:"最近忙しくて、毎日残業する一方だ。",correct:"最近忙しくて、残業時間が増える一方だ。",why:"「～一方だ」 chỉ đi cùng với động từ chỉ sự thay đổi, biến chuyển (như 増える, 減る, 悪化する...), không kết hợp trực tiếp với động từ hành động đơn thuần như 「残業する」."},note:"Mẫu này rất gần nghĩa với 「～ばかりだ」 nhưng 「～ばかりだ」 gần như chỉ dùng cho chiều hướng xấu tiêu cực, trong khi 「～一方だ」 đôi khi vẫn dùng cho các biến chuyển trung tính hoặc khách quan."},{pattern:"～一方で",meaning:"Mặt khác / Trong khi đó",priority:"common",explanation:"Mẫu câu 「～一方で」 dùng để diễn tả hai khía cạnh đối lập, tương phản cùng tồn tại trong một sự vật, sự việc hoặc một đối tượng. Bên cạnh đó, cấu trúc này còn được dùng để nêu lên hai hành động, sự việc diễn ra đồng thời nhưng mang tính chất hoặc chiều hướng trái ngược nhau. Mẫu thường xuất hiện trong văn viết, bài xã luận, tin tức và các bài phát biểu trang trọng nhằm phân tích vấn đề một cách khách quan, đa chiều.",examples:[{sentence:"リモートワークは通勤時間が省けて自由な時間が増える一方で、運動不足や孤立感に悩まされる人も多い。",translation:"Làm việc từ xa một mặt giúp tiết kiệm thời gian đi lại và tăng thời gian tự do, nhưng mặt khác cũng khiến nhiều người phải đau đầu vì thiếu vận động và cảm giác cô lập."},{sentence:"この製品は高い省エネ性能と便利さを誇る一方で、価格が従来のモデルよりかなり高めに設定されている。",translation:"Sản phẩm này một mặt sở hữu tính năng tiện lợi và khả năng tiết kiệm năng lượng vượt trội, nhưng mặt khác mức giá lại được ấn định cao hơn đáng kể so với các mẫu trước đây."}],dialogue:{title:"Đánh giá công nghệ AI",lines:[{speaker:"A",text:"AIの導入で業務効率が大幅に向上している一方で、個人の情報漏洩や著作権侵害といったリスクも懸念されていますね。",translation:"Việc ứng dụng AI một mặt giúp nâng cao đáng kể hiệu suất công việc, nhưng mặt khác những rủi ro như rò rỉ thông tin cá nhân hay vi phạm bản quyền cũng đang rất đáng lo ngại nhỉ."},{speaker:"B",text:"ええ、便利さばかりに目を奪われず、セキュリティ対策や利用ルールを早急に整える必要があります。",translation:"Vâng, chúng ta không thể chỉ mải nhìn vào sự tiện lợi mà cần nhanh chóng hoàn thiện các biện pháp bảo mật cũng như quy tắc sử dụng."},{speaker:"A",text:"そうですね。技術の進化を活かしつつ、課題にも慎重に向き合っていかなければなりませんね。",translation:"Đúng vậy. Chúng ta vừa phải tận dụng sự phát triển của công nghệ, vừa phải thận trọng đối mặt với các vấn đề phát sinh."}]},commonMistake:{wrong:"少子高齢化が進むにつれて、労働力不足は深刻になる一方で。",correct:"少子高齢化が進むにつれて、労働力不足は深刻になる一方だ。",why:"Mẫu 「～一方で」 dùng để liên kết hai vế đối lập hoặc song song, còn khi muốn diễn tả xu hướng đang liên tục biến đổi theo một chiều hướng (ngày càng...) ở cuối câu thì phải dùng 「～一方だ」."},note:"Cần phân biệt với 「～反面」 (nhấn mạnh hai mặt tích cực - tiêu cực vốn có của cùng một bản chất) và 「～一方だ」 (chỉ đứng cuối câu chỉ xu hướng biến đổi liên tục không ngừng)."},{pattern:"～に応じて",meaning:"Tùy theo / Theo đáp ứng với",priority:"common",explanation:"Mẫu ngữ pháp 「～に応じて」 đi sau danh từ, mang ý nghĩa 'tùy theo / tương ứng với / phù hợp với X mà thay đổi hoặc thực hiện hành động Y tương ứng'. Ngữ pháp này thường được dùng khi diễn đạt việc điều chỉnh hành động, dịch vụ hoặc đối sách sao cho thích ứng với các yếu tố biến đổi như năng lực, độ tuổi, thu nhập, yêu cầu hay tình hình thực tế. Dạng bổ nghĩa cho danh từ của mẫu này là 「～に応じた + N」, rất phổ biến trong văn viết trang trọng, công việc và các thông báo dịch vụ.",examples:[{sentence:"当ホテルでは、お客様のご予算やご要望に応じて、最適な宿泊プランをご提案いたします。",translation:"Khách sạn chúng tôi sẽ đề xuất gói lưu trú tối ưu nhất tùy theo ngân sách và nguyện vọng của quý khách."},{sentence:"体力や年齢に応じて無理のないトレーニングメニューを組むことが大切だ。",translation:"Việc xây dựng thực đơn tập luyện vừa sức tùy theo thể lực và độ tuổi là rất quan trọng."}],dialogue:{title:"Tư vấn khóa học",lines:[{speaker:"A",text:"すみません、プログラミング講座の受講を考えているのですが、初心者でもついていけますか。",translation:"Xin lỗi, tôi đang tính tham gia khóa học lập trình, nhưng người mới bắt đầu có theo kịp không ạ?"},{speaker:"B",text:"はい、当スクールでは受講生一人ひとりのレベルに応じてカリキュラムを柔軟に調整できますので、ご安心ください。",translation:"Vâng, quý học viên cứ yên tâm vì trường chúng tôi có thể điều chỉnh linh hoạt giáo trình tùy theo trình độ của từng người."},{speaker:"A",text:"それなら安心しました。まずはレベルチェックテストを受けてみます。",translation:"Nghe vậy thì tôi yên tâm rồi. Trước mắt tôi sẽ làm bài kiểm tra xếp lớp xem sao."}]},commonMistake:{wrong:"親の期待に応じて、医者を目指して一生懸命勉強している。",correct:"親の期待に応えて、医者を目指して一生懸命勉強している。",why:"Để diễn tả hành động nhằm 'đáp lại' kỳ vọng, mong mỏi (như 期待, 要望, 声援) thì phải dùng 「～に応えて」, còn 「～に応じて」 chỉ mang nghĩa 'tùy theo, tương ứng với' mức độ hoặc điều kiện."},note:"Cần phân biệt với 「～によって」 (chỉ sự phân loại khác nhau đơn thuần), còn 「～に応じて」 nhấn mạnh vào sự chủ động điều chỉnh hành động cho tương xứng, thích ứng với đối tượng ở vế trước."},{pattern:"～さえ～ば",meaning:"Chỉ cần ~ là / Miễn là ~",priority:"common",explanation:"Mẫu câu này diễn đạt ý nghĩa 'chỉ cần... là đủ / miễn là...', dùng để đưa ra một điều kiện tối thiểu mà khi điều kiện đó được thỏa mãn thì vế sau sẽ diễn ra thuận lợi hoặc giải quyết được vấn đề. Vế sau thường thể hiện kết quả tích cực, sự an tâm hoặc kỳ vọng, không dùng cho các câu mệnh lệnh hay yêu cầu áp đặt người nghe. Khi kết hợp, cần chú ý biến đổi linh hoạt theo từ loại: Danh từ đi với 'さえ～ば/なら', Động từ chuyển thành 'V-stem + さえすれば' hoặc 'V-て + さえいれば'.",examples:[{sentence:"どんなに辛いことがあっても、家族の笑顔さえあれば乗り越えられる気がする。",translation:"Dù có gặp chuyện khó khăn đến mức nào đi nữa, tôi vẫn cảm thấy chỉ cần có nụ cười của gia đình là có thể vượt qua."},{sentence:"この説明書を読みさえすれば、初心者でも簡単に組み立てることができます。",translation:"Chỉ cần đọc cuốn hướng dẫn này là ngay cả người mới bắt đầu cũng có thể lắp ráp dễ dàng."}],dialogue:{title:"Chuẩn bị đi du lịch",lines:[{speaker:"A",text:"海外旅行の荷造り、これで全部揃ったかな？何か忘れていないか心配だよ。",translation:"Hành lý đi du lịch nước ngoài thế này đã đủ hết chưa nhỉ? Tớ lo không biết có quên gì không nữa."},{speaker:"B",text:"パスポートとクレジットカードさえあれば、現地で何とでもなるから大丈夫だよ。",translation:"Chỉ cần có hộ chiếu và thẻ tín dụng là sang tới nơi kiểu gì cũng xoay xở được, yên tâm đi."},{speaker:"A",text:"確かにそうだね。そう言ってもらえると少し気が楽になったよ。",translation:"Đúng là vậy thật. Nghe cậu nói thế tớ cũng thấy nhẹ lòng hơn rồi."}]},commonMistake:{wrong:"時間さえば、もっと日本語の練習ができるのに。",correct:"時間さえあれば、もっと日本語の練習ができるのに。",why:"Khi đi sau Danh từ, không được ghép trực tiếp 'N + さえ + ば' mà bắt buộc phải có vị từ đi kèm chia ở thể điều kiện tương ứng (ở đây là あります chuyển thành あれば)."},note:"Khác với '～だけで' chỉ nêu phạm vi đơn thuần, '～さえ～ば' nhấn mạnh vào điều kiện mang tính quyết định, ngụ ý rằng ngoài điều kiện này ra thì các yếu tố khác đều không đáng lo ngại."},{pattern:"～てこそ",meaning:"Chính nhờ ~ mới có thể",priority:"common",explanation:"Mẫu ngữ pháp「～てこそ」dùng để nhấn mạnh rằng chỉ khi thực hiện hành động hoặc có điều kiện ở vế trước thì vế sau mới thực sự có giá trị, ý nghĩa hoặc thành hiện thực. Vế sau thường đi kèm với những đánh giá tích cực, sự công nhận hay nhận thức sâu sắc (như「～てこそ一人前だ」「～てこそ意味がある」). Người Nhật không sử dụng mẫu câu này để diễn tả những quy luật tự nhiên hiển nhiên hoặc các kết quả mang tính tiêu cực.",examples:[{sentence:"苦労を重ねて失敗を乗り越えてこそ、成功の本当の喜びを味わうことができる。",translation:"Chính nhờ trải qua nhiều gian khổ và vượt qua thất bại thì mới có thể nếm trải trọn vẹn niềm vui của thành công."},{sentence:"お互いに本音で率直に話し合ってこそ、真の信頼関係を築くことができる。",translation:"Chỉ khi thẳng thắn chia sẻ thật lòng với nhau thì mới có thể xây dựng được mối quan hệ tin cậy thực sự."}],dialogue:{title:"Lời khuyên của cấp trên",lines:[{speaker:"A",text:"自分で実際に現場を経験してこそ、この仕事の大変さとやりがいが分かるんだよ。",translation:"Chính nhờ tự mình trực tiếp trải nghiệm thực tế thì em mới thấu hiểu được nỗi vất vả cũng như ý nghĩa của công việc này đấy."},{speaker:"B",text:"はい、課長のおっしゃる通りです。頭で悩む前にまず現場に足を運んでみます。",translation:"Vâng, đúng như lời trưởng phòng dạy bảo ạ. Em sẽ đến tận hiện trường xem sao trước khi ngồi lo nghĩ trong đầu."},{speaker:"A",text:"その意気だ。失敗を恐れずにどんどんチャレンジしなさい。",translation:"Tinh thần như vậy là tốt. Đừng sợ thất bại mà hãy cứ mạnh dạn thử sức nhé."}]},commonMistake:{wrong:"昨日病院に行って薬を飲んでこそ、やっと熱が下がりました。",correct:"昨日病院に行って薬を飲んで初めて、やっと熱が下がりました。",why:"「～てこそ」nhấn mạnh giá trị và điều kiện tiên quyết mang tính chủ quan chứ không dùng để trần thuật lại chuỗi sự việc/kết quả thực tế đã xảy ra theo trình tự thời gian trong quá khứ."},note:"Khác với「～てはじめて」(thuần túy diễn tả việc nhận ra điều gì sau khi đã trải qua mốc sự kiện),「～てこそ」luôn mang sắc thái nhấn mạnh giá trị và đánh giá chủ quan của người nói."},{pattern:"～てはじめて",meaning:"Chỉ sau khi ~ mới lần đầu",priority:"common",explanation:"Mẫu câu「～てはじめて」diễn tả ý nghĩa: chỉ sau khi một sự việc nào đó xảy ra hoặc sau khi trải qua một biến cố thì mới nhận ra, thấu hiểu hay có được một trạng thái mà trước đó chưa từng có. Cấu trúc đi liền với động từ thể Te (V-て + はじめて). Vế sau thường là các biểu hiện thể hiện sự nhận thức mới, cảm xúc mới hoặc sự việc lần đầu tiên xảy ra, không dùng cho câu mệnh lệnh hay yêu cầu.",examples:[{sentence:"病気になってはじめて、健康でいられることのありがたさが身にしみてわかった。",translation:"Chỉ sau khi bị ốm, tôi mới thấm thía và nhận ra sự quý giá của việc có một cơ thể khỏe mạnh."},{sentence:"一人暮らしをしてはじめて、両親がどれほど苦労して自分を育ててくれたかを実感した。",translation:"Chỉ sau khi bắt đầu sống tự lập một mình, tôi mới thực sự cảm nhận được cha mẹ đã vất vả nuôi nấng mình đến nhường nào."}],dialogue:{title:"Trải nghiệm đi làm",lines:[{speaker:"A",text:"社会人になってはじめて、学生時代の自由な時間がどれほど貴重だったかに気づいたよ。",translation:"Chỉ sau khi đi làm rồi, tôi mới nhận ra khoảng thời gian tự do thời sinh viên quý giá đến mức nào."},{speaker:"B",text:"本当にそうだね。毎日仕事に追われていると、あの頃に戻りたくなるよね。",translation:"Thật sự đúng là như vậy. Mỗi ngày đều quay cuồng với công việc, chỉ muốn quay lại khoảng thời gian đó thôi."},{speaker:"A",text:"うん、だからこそ今は休日の過ごし方を大切にするようになったんだ。",translation:"Ừ, chính vì thế mà bây giờ tôi mới biết trân trọng hơn cách sử dụng các ngày nghỉ."}]},commonMistake:{wrong:"ご飯を食べてはじめて、歯を磨きます。",correct:"ご飯を食べてから、歯を磨きます。",why:"「～てはじめて」nhấn mạnh vào sự thay đổi nhận thức hoặc trải nghiệm mới phát sinh sau một sự việc, không dùng để biểu thị trình tự trước sau của các hành động sinh hoạt thông thường."},note:"Cần phân biệt với「～てからでないと」(nếu chưa hoàn thành A thì tuyệt đối không thể làm B) và lưu ý vế sau của「～てはじめて」không dùng các hình thức thể hiện mệnh lệnh, rủ rê hay ý chí trực tiếp."},{pattern:"～ものだ",meaning:"Lẽ thường / Cảm thán / Hồi tưởng",priority:"common",explanation:'「～ものだ」 là mẫu ngữ pháp đa nghĩa dùng để: (1) biểu thị chân lý, quy luật tự nhiên hoặc điều mang tính lẽ thường ("ai/cái gì cũng thường như thế"); (2) thể hiện cảm xúc, cảm thán sâu sắc về một sự việc ("thật là..."); (3) hồi tưởng lại thói quen, kỷ niệm trong quá khứ khi kết hợp với thể quá khứ 「～たものだ」. Mẫu này nhấn mạnh bản chất vốn có hoặc cảm xúc tự nhiên, không dùng để áp đặt mệnh lệnh hay chỉ dẫn cụ thể cho một cá nhân trong một tình huống tức thời.',examples:[{sentence:"誰だって失敗を重ねて成長するものだ。",translation:"Ai cũng vậy, phải trải qua nhiều lần thất bại mới trưởng thành được (đó là lẽ thường tình)."},{sentence:"子供の頃は夏休みになると、毎日暗くなるまで外で遊んだものだ。",translation:"Hồi còn nhỏ, cứ đến kỳ nghỉ hè là ngày nào tôi cũng chơi ở ngoài cho tới tận lúc trời tối mịt."}],dialogue:{title:"Nhớ lại thời sinh viên",lines:[{speaker:"A",text:"昔はこの喫茶店でよく朝まで語り合ったものだ。",translation:"Hồi xưa chúng mình hay ngồi tâm sự thâu đêm ở quán cà phê này nhỉ."},{speaker:"B",text:"本当ですね。あれからもう10年も経ったなんて信じられません。",translation:"Đúng vậy thật. Thật không thể tin là đã 10 năm trôi qua từ dạo ấy."},{speaker:"A",text:"時が経つのは本当に早いものだ。",translation:"Thời gian trôi qua nhanh thật đấy."}]},commonMistake:{wrong:"風邪を早く治したいなら、温かくしてよく寝るものだ。",correct:"風邪を早く治したいなら、温かくしてよく寝ることだ。",why:"「～ものだ」 biểu thị bản chất, đạo lý hoặc lẽ thường chung, không dùng để đưa ra lời khuyên hay chỉ dẫn trực tiếp cho đối phương trong hoàn cảnh cụ thể (trường hợp này phải dùng 「～ことだ」)."},note:"Cần phân biệt với 「～ことだ」 (lời khuyên, hướng dẫn trực tiếp) và 「～わけだ」 (kết luận hiển nhiên theo logic/nguyên nhân thực tế)."},{pattern:"～に違いない",meaning:"Chắc chắn là ~ / Không nghi ngờ",priority:"common",explanation:'Mẫu ngữ pháp này dùng để biểu thị sự khẳng định hoặc phán đoán có độ chắc chắn rất cao của người nói ("chắc chắn là...", "không còn nghi ngờ gì nữa"). Phán đoán này xuất phát từ niềm tin, cảm nhận hoặc trực giác chủ quan mạnh mẽ của người nói dựa trên một căn cứ nào đó. Về cách nối, mẫu đi với thể thông thường của động từ, tính từ đuôi -i, và nối trực tiếp với danh từ hoặc tính từ đuôi -na (bỏ だ/な).',examples:[{sentence:"夜遅くまで部屋の明かりがついているから、彼はまだ試験勉強をしているに違いない。",translation:"Đèn phòng vẫn sáng đến tận đêm muộn thế này thì chắc chắn anh ấy vẫn đang ôn thi."},{sentence:"あれほど熱心に練習を重ねてきたのだから、彼女なら今回のコンクールで優勝できるに違いない。",translation:"Vì đã kiên trì luyện tập chăm chỉ đến nhường ấy nên nếu là cô ấy thì chắc chắn có thể giành giải nhất trong cuộc thi lần này."}],dialogue:{title:"Tìm chìa khóa thất lạc",lines:[{speaker:"A",text:"あれ？ 自転車の鍵が見当たらないんだ。カバンにもポケットにも入っていないよ。",translation:"Ủa? Tớ không thấy chìa khóa xe đạp đâu cả. Trong túi xách lẫn túi quần áo đều không có."},{speaker:"B",text:"さっき立ち寄ったカフェのテーブルの上に置き忘れたに違いないよ。すぐに戻ってみよう。",translation:"Chắc chắn là cậu bỏ quên trên bàn ở quán cà phê ghé lúc nãy rồi. Mau quay lại đó xem sao đi."},{speaker:"A",text:"そうだね、まだそこにあるといいんだけど。急ごう！",translation:"Ừ nhỉ, mong là nó vẫn còn ở đó. Nhanh lên nào!"}]},commonMistake:{wrong:"こんな高級車を何台も持っているなんて、彼はお金持ちだに違いない。",correct:"こんな高級車を何台も持っているなんて、彼はお金持ちに違いない。",why:"Khi kết hợp với Danh từ (hoặc Tính từ đuôi な), ta nối trực tiếp với 「に違いない」 chứ không giữ lại 「だ」."},note:"So với 「～はずだ」 (suy đoán mang tính khách quan dựa trên quy luật, lịch trình, chứng cứ logic), 「～に違いない」 thể hiện niềm tin và phán đoán chủ quan, quả quyết mạnh mẽ hơn từ phía người nói."}],141:[{pattern:"～を余儀なくされる",meaning:"Bị buộc phải ~",priority:"core",explanation:"Mẫu câu này biểu thị ý nghĩa 'bị rơi vào tình thế buộc phải làm gì hoặc chịu một kết quả không mong muốn' do hoàn cảnh bên ngoài tác động. Ngữ pháp này đi trực tiếp sau Danh từ chỉ hành động mang tính biến động lớn (như hoãn lại, từ chức, thu hẹp, nhập viện...) do tình huống bất khả kháng, không còn sự lựa chọn nào khác. Đây là mẫu câu trang trọng, thường xuất hiện trong văn viết, báo chí và các bản tin thời sự.",examples:[{sentence:"業績の悪化により、同社は事業の縮小や人員削減を余儀なくされた。",translation:"Do tình hình kinh doanh sa sút, công ty đó đã buộc phải thu hẹp quy mô và cắt giảm nhân sự."},{sentence:"突然の怪我により、彼は長年目指していた全国大会への出場辞退を余儀なくされた。",translation:"Do chấn thương đột ngột, anh ấy đã buộc phải rút lui khỏi giải đấu toàn quốc mà mình ấp ủ bấy lâu."}],dialogue:{title:"Hoãn chuyến công tác",lines:[{speaker:"A",text:"大型の台風が接近しているため、明日の海外出張は延期を余儀なくされそうです。",translation:"Vì có cơn bão lớn đang đến gần nên chuyến công tác nước ngoài ngày mai có vẻ như buộc phải hoãn lại rồi."},{speaker:"B",text:"それは大変ですね。先方への連絡やチケットの変更手続きはもう済みましたか。",translation:"Vất vả quá nhỉ. Anh đã liên lạc với phía đối tác và làm thủ tục đổi vé xong chưa?"},{speaker:"A",text:"はい、先ほど先方に事情を説明し、日程の再調整をお願いしたところです。",translation:"Vâng, tôi vừa giải thích tình hình cho đối tác và nhờ họ sắp xếp lại lịch trình rồi."}]},commonMistake:{wrong:"長引く不況が、多くの企業に倒産を余儀なくされた。",correct:"長引く不況が、多くの企業に倒産を余儀なくさせた。",why:"Khi chủ ngữ là nguyên nhân hay hoàn cảnh tạo ra áp lực thì phải dùng dạng sai khiến 「〜を余儀なくさせる」, còn 「〜を余儀なくされる」 chỉ dùng khi chủ ngữ là người hoặc tổ chức bị ép buộc."},note:"Khác với 「〜ざるを得ない」 (người nói tự nhận thức theo lý trí/tâm lý rằng không còn cách nào khác ngoài làm việc đó), 「〜を余儀なくされる」 đi với Danh từ để nhấn mạnh hoàn cảnh khách quan bên ngoài ép buộc rơi vào tình thế bất lợi, mang phong cách văn viết trang trọng hơn."},{pattern:"～ならいざしらず",meaning:"Biết đâu với ~ nhưng không phải ~",priority:"common",explanation:'Mẫu ngữ pháp này mang ý nghĩa "Nếu là A (trường hợp đặc biệt, ngoại lệ, quá khứ...) thì còn có thể chấp nhận hoặc bỏ qua được, đằng này là B thì hoàn toàn không thể chấp nhận được / không thể có chuyện đó". Cấu trúc thường kết hợp trực tiếp với danh từ (Nならいざしらず / Nはいざ知らず) hoặc thể thông thường đi với の (〜のならいざしらず). Vế sau luôn đi kèm với đánh giá tiêu cực, sự bất mãn, ngạc nhiên hoặc chỉ trích mạnh mẽ của người nói.',examples:[{sentence:"新入社員ならいざしらず、10年も勤めているベテランがこんな初歩的なミスをするなんて信じられない。",translation:"Nếu là nhân viên mới thì không nói làm gì, đằng này là một người kỳ cựu đã làm việc 10 năm mà lại mắc lỗi cơ bản thế này thì thật không thể tin nổi."},{sentence:"何十年も前の昔ならいざしらず、インターネットが発達した現代でその情報を知らないのは不自然だ。",translation:"Nếu là chuyện mấy chục năm về trước thì còn hiểu được, chứ trong thời đại internet phát triển như ngày nay mà không biết thông tin đó thì thật bất thường."}],dialogue:{title:"Trách nhiệm trong công việc",lines:[{speaker:"A",text:"田中さん、また大事な会議に遅刻したらしいよ。",translation:"Nghe nói anh Tanaka lại đến muộn cuộc họp quan trọng nữa rồi đấy."},{speaker:"B",text:"電車の遅延ならいざしらず、単に寝坊しただけだなんて無責任すぎるよね。",translation:"Nếu là do tàu trễ thì còn châm chước được, đằng này chỉ là ngủ quên thì quá ư là vô trách nhiệm."},{speaker:"A",text:"本当だね。チーム全体に迷惑がかかることを自覚してほしいよ。",translation:"Thật vậy. Mong là anh ấy tự ý thức được việc đó gây ảnh hưởng xấu tới cả đội."}]},commonMistake:{wrong:"自分で料理を作るならいざしらず、冷凍食品を温めるだけなのに30分もかかった。",correct:"自分で料理を作るのならいざしらず、冷凍食品を温めるだけなのに30分もかかった。",why:"Khi kết hợp với động từ, bắt buộc phải danh từ hóa bằng cách thêm 「の」 thành dạng 「〜のならいざしらず」 chứ không ghép trực tiếp thể từ điển với 「ならいざしらず」."},note:"Mẫu câu này có thể dùng dạng biến thể 「〜はいざ知らず」 với ý nghĩa tương đương, và có nét nghĩa tương tự 「〜ならまだしも」「〜ならともかく」 nhưng mang sắc thái chỉ trích, bất bình ở vế sau gay gắt hơn."},{pattern:"～とあって",meaning:"Vì là hoàn cảnh đặc biệt ~ nên",priority:"common",explanation:'Mẫu câu 「～とあって」 dùng để diễn tả nguyên nhân, lý do với ý nghĩa "vì đang ở trong một hoàn cảnh/sự kiện đặc biệt, nên đương nhiên dẫn đến kết quả tương ứng...". Vế trước đưa ra tình huống hoặc điều kiện khác với thường lệ (như dịp lễ lớn, sự kiện hiếm có, ưu đãi đặc biệt), còn vế sau miêu tả trạng thái hoặc hiện tượng tất yếu nảy sinh từ hoàn cảnh đó. Cấu trúc này thường dùng trong văn phong tường thuật khách quan, vế sau không đi kèm các cách diễn đạt thể hiện ý chí cá nhân, lời mời mọc hay mệnh lệnh.',examples:[{sentence:"人気アイドルのラストコンサートとあって、会場周辺は朝早くから大勢のファンで埋め尽くされていた。",translation:"Vì là buổi hòa nhạc cuối cùng của nhóm thần tượng nổi tiếng, nên khu vực quanh hội trường đã chật kín đông đảo người hâm mộ từ sáng sớm."},{sentence:"久しぶりの大型連休とあって、空港や新幹線の駅は帰省客や旅行者で大混雑している。",translation:"Vì là kỳ nghỉ dài ngày hiếm hoi sau thời gian dài, nên các sân bay và ga tàu Shinkansen đều đông nghẹt người về quê và khách du lịch."}],dialogue:{title:"Quán ăn mới khai trương",lines:[{speaker:"A",text:"駅前に新しくできたラーメン屋、初日全品半額とあってすごい行列ができているよ。",translation:"Quán ramen mới mở trước ga, vì ngày đầu giảm nửa giá tất cả các món nên người ta đang xếp hàng dài khủng khiếp đấy."},{speaker:"B",text:"え、本当？並んででも食べてみたいけど、どのくらい待つかな。",translation:"Ơ, thật hả? Dù phải xếp hàng mình cũng muốn ăn thử, nhưng không biết phải đợi bao lâu nhỉ."},{speaker:"A",text:"少なくとも1時間はかかりそうだから、時間に余裕があるなら行ってみようか。",translation:"Có vẻ mất ít nhất một tiếng đấy, nếu cậu có dư dả thời gian thì chúng mình cùng đi xem sao."}]},commonMistake:{wrong:"有名なシェフが来日するとあって、ぜひそのレストランに食べに行ってください。",correct:"有名なシェフが来日するとあって、そのレストランの予約は一瞬で満席になった。",why:"Mẫu 「～とあって」 dùng để tường thuật sự việc khách quan phát sinh từ hoàn cảnh đặc biệt, nên vế sau không kết hợp với câu mệnh lệnh, nhờ vả hay rủ rê như 「～てください」."},note:"Khác với các từ chỉ nguyên nhân thông thường, 「～とあって」 chỉ dùng cho tình huống đặc biệt khác thường ngày và vế sau diễn tả sự việc xảy ra ở ngôi thứ ba, không dùng cho ý định chủ quan của bản thân người nói."},{pattern:"～をめぐって",meaning:"Xung quanh vấn đề ~ (tranh luận/tranh chấp)",priority:"common",explanation:'Mẫu ngữ pháp「～をめぐって」mang ý nghĩa "xung quanh vấn đề / chủ đề nào đó". Mẫu này thường nối trực tiếp với danh từ (N + をめぐって) để chỉ một vấn đề trọng tâm làm nảy sinh nhiều ý kiến trái chiều, sự tranh cãi, tranh chấp hoặc đối lập giữa nhiều người, nhiều phe phái. Vế sau thường đi kèm với các từ diễn đạt sự tương tác nhiều phía như 議論する (thảo luận), 対立する (đối lập), 争う (tranh chấp). Đây là cách diễn đạt mang tính trang trọng, thường xuất hiện trong tin tức, báo chí hoặc các cuộc họp, văn bản chính thức.',examples:[{sentence:"新空港の建設計画をめぐって、住民と行政の間で激しい議論が交わされている。",translation:"Xung quanh kế hoạch xây dựng sân bay mới, những cuộc thảo luận gay gắt đang diễn ra giữa người dân và chính quyền."},{sentence:"消費税の増税をめぐって、与党と野党の意見が激しく対立している。",translation:"Xung quanh việc tăng thuế tiêu dùng, ý kiến giữa đảng cầm quyền và đảng đối lập đang đối đầu kịch liệt."}],dialogue:{title:"Tranh luận về làm việc từ xa",lines:[{speaker:"A",text:"テレワークの継続をめぐって、社内で意見が真っ二つに分かれているそうだね。",translation:"Nghe nói trong công ty đang chia thành hai luồng ý kiến trái ngược xung quanh việc duy trì làm việc từ xa nhỉ."},{speaker:"B",text:"ええ、出社を義務づけたい経営陣と、在宅を続けたい社員の間で対立が起きています。",translation:"Vâng, đang xảy ra sự bất đồng giữa ban điều hành muốn bắt buộc đến công ty và nhân viên muốn tiếp tục làm việc tại nhà."},{speaker:"A",text:"双方が納得できる柔軟な働き方のルールを早く決めてほしいね。",translation:"Mong là công ty sớm đưa ra quy tắc làm việc linh hoạt mà cả hai bên đều thấy thỏa đáng."}]},commonMistake:{wrong:"私は卒論のテーマをめぐって、一人で図書館で調べています。",correct:"私は卒論のテーマについて、一人で図書館で調べています。",why:"「～をめぐって」chỉ dùng khi có nhiều phía tranh cãi, đối lập hoặc bàn tán về một chủ đề, không dùng cho hành động tìm hiểu, nghiên cứu đơn phương của một cá nhân."},note:"Khác với「～について」(chỉ đơn thuần nêu chủ đề tiếp nhận hành động),「～をめぐって」bắt buộc phải có yếu tố tranh luận đa chiều, bất đồng hoặc tranh chấp giữa nhiều đối tượng."},{pattern:"～ざるを得ない",meaning:"Không thể không / Buộc phải",priority:"common",explanation:"Mẫu câu này dùng để diễn tả ý nghĩa 'không muốn nhưng đành phải / buộc phải làm' do tình thế hoặc hoàn cảnh khách quan ép buộc, không còn sự lựa chọn nào khác. Đi sau động từ thể ない (bỏ ない thêm ざるを得ない, riêng する chuyển thành せざるを得ない). Ngữ pháp mang sắc thái miễn cưỡng, bất đắc dĩ và thường được dùng nhiều trong văn viết hoặc cách nói trang trọng.",examples:[{sentence:"これだけ決定的な証拠が揃っている以上、彼の不正を認めざるを得ない。",translation:"Một khi đã có đầy đủ bằng chứng mang tính quyết định như thế này thì đành phải thừa nhận hành vi sai trái của anh ấy."},{sentence:"台風の接近で飛行機が全便欠航となったため、出張の予定を延期せざるを得なかった。",translation:"Do bão đến gần khiến toàn bộ các chuyến bay bị hủy nên tôi buộc phải hoãn lịch công tác."}],dialogue:{title:"Hủy chuyến du lịch",lines:[{speaker:"A",text:"来週の温泉旅行なんだけど、急な仕事が入ってキャンセルせざるを得なくなっちゃったんだ。",translation:"Chuyến du lịch suối nước nóng tuần sau, do có công việc đột xuất nên tớ đành phải hủy mất rồi."},{speaker:"B",text:"えっ、本当？ずっと楽しみにしてたのに残念だけど、仕事なら仕方ないね。",translation:"Hả, thật á? Mong chờ mãi mà tiếc quá, nhưng nếu vì công việc thì đành chịu thôi."},{speaker:"A",text:"本当にごめんね。今回の案件が片付いたら、改めて計画を立て直そう。",translation:"Thật sự xin lỗi cậu nhé. Khi nào xử lý xong dự án này, chúng mình cùng lên kế hoạch lại nhé."}]},commonMistake:{wrong:"予算が大幅にオーバーしてしまったので、開発計画を変更しざるを得ない。",correct:"予算が大幅にオーバーしてしまったので、開発計画を変更せざるを得ない。",why:"Động từ nhóm 3 「する (変更する)」 khi đi với mẫu này phải biến đổi thành 「せざるを得ない」, không chia nhầm thành 「しざるを得ない」."},note:"Khác với 「～ずにいられない」 (bộc lộ cảm xúc hay phản xạ tự nhiên không kìm nén nổi), 「～ざるを得ない」 luôn mang tính lý trí và sắc thái miễn cưỡng do hoàn cảnh khách quan ép buộc."},{pattern:"～ものではない",meaning:"Không nên ~ (phê phán đạo đức)",priority:"common",explanation:"Mẫu ngữ pháp này dùng để đưa ra lời khuyên, lời răn dạy hoặc phê phán mang tính đạo đức và chuẩn mực xã hội rằng không nên làm một việc gì đó. Cấu trúc được kết hợp bởi động từ thể từ điển (V-る + ものではない). Vì mang sắc thái giáo huấn của bề trên đối với người dưới hoặc phát biểu về lẽ thường, mẫu này tuyệt đối không dùng để khuyên bảo người có vai vế cao hơn.",examples:[{sentence:"他人の悪口を陰で言うものではない。",translation:"Không nên nói xấu sau lưng người khác."},{sentence:"いくら親しい間柄でも、礼儀を忘れるものではない。",translation:"Dù là mối quan hệ thân thiết đến đâu cũng không nên quên đi phép lịch sự tối thiểu."}],dialogue:{title:"Lời khuyên của tiền bối",lines:[{speaker:"A",text:"仕事で一度失敗したからといって、そう簡単に諦めるものではないよ。",translation:"Không nên dễ dàng bỏ cuộc như vậy chỉ vì một lần thất bại trong công việc đâu."},{speaker:"B",text:"すみません、先輩。もう一度落ち着いて原因を確認してみます。",translation:"Em xin lỗi tiền bối. Em sẽ bình tĩnh kiểm tra lại nguyên nhân một lần nữa ạ."},{speaker:"A",text:"そうだね、失敗から学んで次に活かせばいいんだよ。",translation:"Đúng rồi, hãy học hỏi từ thất bại và áp dụng cho lần sau là được."}]},commonMistake:{wrong:"危ないから、道路に飛び出すものではない。",correct:"危ないから、道路に飛び出してはいけない。",why:"Mẫu ～ものではない dùng cho các quy tắc đạo đức, lẽ thường mang tính răn dạy chung, không dùng để cấm đoán một hành vi cụ thể mang tính cấp bách tức thời."},note:"Trong hội thoại giao tiếp thân mật hàng ngày, mẫu câu này thường được nói rút gọn thành ～もんじゃない."},{pattern:"～次第で",meaning:"Tùy thuộc vào ~",priority:"common",explanation:'Mẫu câu này mang ý nghĩa "tùy thuộc vào N mà...", diễn tả một sự việc, kết quả hay quyết định sẽ thay đổi hoặc phụ thuộc vào yếu tố đứng trước. Khi dùng dưới dạng 「～次第では」, vế sau thường nêu ra một khả năng hoặc tình huống cụ thể có thể xảy ra. Đây là cách diễn đạt mang tính trang trọng, xuất hiện phổ biến trong môi trường công sở, giao tiếp lịch sự và các thông báo bằng văn bản.',examples:[{sentence:"物事は考え方次第で、良くも悪くもなる。",translation:"Mọi sự việc tùy thuộc vào cách suy nghĩ mà có thể trở nên tốt hơn hoặc xấu đi."},{sentence:"明日の検査の結果次第では、再手術を受ける必要があります。",translation:"Tùy thuộc vào kết quả xét nghiệm ngày mai mà có thể sẽ phải phẫu thuật lại."}],dialogue:{title:"Kế hoạch đi cắm trại",lines:[{speaker:"A",text:"今週末のキャンプ、もし雨が降ったらどうするの？",translation:"Buổi cắm trại cuối tuần này nếu trời mưa thì tính sao?"},{speaker:"B",text:"当日の天気次第で、中止にするか場所を変更するか決めよう。",translation:"Tùy vào thời tiết hôm đó mà chúng ta sẽ quyết định hủy hay đổi địa điểm nhé."},{speaker:"A",text:"了解。じゃあ、前日の予報を見てまた相談しよう。",translation:"Hiểu rồi. Vậy hôm trước đó xem dự báo thời tiết rồi lại bàn tiếp nhé."}]},commonMistake:{wrong:"成功するかどうかは、君が努力する次第で決まる。",correct:"成功するかどうかは、君の努力次第で決まる。",why:"「～次第で」 chỉ kết hợp trực tiếp với Danh từ, không đứng sau động từ thể từ điển như 「努力する」."},note:"Cần phân biệt 「N + 次第で/次第では」(tùy thuộc vào...) với mẫu 「V-ます(bỏ ます) + 次第」(ngay sau khi... thì sẽ...) để tránh nhầm lẫn về ý nghĩa và cách nối."},{pattern:"～に伴って",meaning:"Cùng với ~ / Theo đà ~",priority:"common",explanation:"Mẫu 「～に伴って」 dùng để diễn tả rằng cùng với sự thay đổi, phát triển hoặc biến chuyển của một sự việc A thì sự việc B cũng đồng thời thay đổi hoặc xảy ra theo. Cấu trúc kết nối thường là Danh từ hoặc Động từ thể từ điển (V-る + の) đi trực tiếp với 「に伴って」. Mẫu câu này mang sắc thái trang trọng, khách quan, thường được sử dụng trong văn viết, bản tin thời sự hoặc báo cáo về các hiện tượng xã hội, tự nhiên.",examples:[{sentence:"少子高齢化が進むのに伴って、医療や介護にかかる費用が増加している。",translation:"Cùng với sự gia tăng của già hóa dân số và giảm tỷ lệ sinh, chi phí dành cho y tế và chăm sóc người cao tuổi cũng đang tăng lên."},{sentence:"都市開発が進むのに伴って、周辺の自然環境が失われつつある。",translation:"Cùng với việc phát triển đô thị được đẩy mạnh, môi trường tự nhiên ở các khu vực xung quanh đang dần biến mất."}],dialogue:{title:"Mở rộng quy mô công ty",lines:[{speaker:"A",text:"事業拡大に伴って、新しい社員を何人か採用する予定ですか。",translation:"Cùng với việc mở rộng kinh doanh, công ty có dự định tuyển thêm nhân viên mới không?"},{speaker:"B",text:"ええ、来月から開発チームを中心に5名ほど増員することになりました。",translation:"Có chứ, từ tháng sau chúng tôi quyết định sẽ tăng thêm khoảng 5 người, chủ yếu cho đội phát triển."},{speaker:"A",text:"そうですか。オフィスのスペースも少し手狭になりそうですね。",translation:"Vậy à. Thế thì không gian văn phòng có vẻ cũng sắp trở nên chật chội hơn rồi nhỉ."}]},commonMistake:{wrong:"会社が大きくなったに伴って、社員の数も増えました。",correct:"会社が大きくなるのに伴って、社員の数も増えました。",why:"Trước 「～に伴って」 chỉ kết hợp với Danh từ hoặc Động từ thể từ điển (V-る + の), không kết hợp trực tiếp với thể quá khứ V-た."},note:"So với 「～につれて」, 「～に伴って」 trang trọng hơn và ngoài biểu thị hai sự việc cùng biến đổi song hành, nó còn có thể chỉ quan hệ nhân quả (sự việc A phát sinh kéo theo B xảy ra)."}],142:[{pattern:"～につれて",meaning:"Dần dần khi A thay đổi thì B cũng thay đổi",priority:"core",explanation:'Mẫu 「～につれて」 diễn tả ý nghĩa "cùng với sự thay đổi của A thì B cũng dần dần biến đổi theo". Cả vế trước và vế sau đều phải chứa từ ngữ biểu thị sự chuyển biến, tiến triển theo thời gian (như tăng giảm, già đi, phát triển...). Vế sau diễn tả sự thay đổi diễn ra mang tính tự nhiên, không dùng với các cách diễn đạt thể hiện ý chí, nguyện vọng hay mệnh lệnh của người nói.',examples:[{sentence:"台風が近づくにつれて、風と雨がだんだん強くなってきた。",translation:"Càng tiến lại gần tâm bão, mưa và gió càng lúc càng mạnh dần lên."},{sentence:"年齢を重ねるにつれて、健康管理の大切さを実感するようになった。",translation:"Càng có tuổi, tôi càng thấm thía được tầm quan trọng của việc giữ gìn sức khỏe."}],dialogue:{title:"Thời tiết chuyển mùa",lines:[{speaker:"A",text:"秋が深まるにつれて、朝晩の冷え込みが厳しくなってきましたね。",translation:"Càng về sâu mùa thu thì cái lạnh vào sáng sớm và đêm muộn càng trở nên rõ rệt hơn nhỉ."},{speaker:"B",text:"そうですね。そろそろ厚手のコートを出したほうがいいかもしれません。",translation:"Đúng vậy thật. Có lẽ cũng sắp đến lúc nên lấy sẵn áo khoác dày ra rồi."},{speaker:"A",text:"風邪をひかないように、お互い体調管理には気をつけましょう。",translation:"Để không bị cảm lạnh, chúng ta hãy cùng chú ý giữ gìn sức khỏe nhé."}]},commonMistake:{wrong:"景気が回復するにつれて、家族と海外旅行に行こうと思う。",correct:"景気が回復するにつれて、海外旅行に行く人が増えてきた。",why:"Vế sau của 「～につれて」 phải là sự biến đổi tự nhiên, tuyệt đối không dùng các cấu trúc thể hiện ý chí, dự định hay nguyện vọng cá nhân như 「～と思う」 hay 「～たい」."},note:"So với 「～にしたがって」, mẫu 「～につれて」 chỉ dùng cho sự biến đổi tỉ lệ thuận mang tính tự nhiên và không dùng được với các câu văn mang tính chỉ thị hay quy tắc bắt buộc."},{pattern:"～ばかりに",meaning:"Chỉ vì ~ mà (hậu quả xấu)",priority:"common",explanation:"Mẫu ngữ pháp 「～ばかりに」 dùng để diễn tả ý nghĩa 'chỉ vì một lý do, nguyên nhân duy nhất nào đó mà dẫn đến kết quả xấu, tai hại không mong muốn'. Cấu trúc này thường kết hợp với thể thông thường của động từ (nhất là thể V-た hoặc V-たい), tính từ và danh từ + である. Mẫu câu thể hiện sâu sắc tâm trạng hối hận, tiếc nuối của người nói hoặc cảm giác cay đắng trước hậu quả đã xảy ra. Vế sau luôn là một sự việc bất lợi, tiêu cực và tuyệt đối không đi với các dạng câu cầu khiến, rủ rê hay mệnh lệnh.",examples:[{sentence:"嘘をついたばかりに、長年築いてきた友人との信頼関係を一瞬で失ってしまった。",translation:"Chỉ vì nói dối mà tôi đã đánh mất sự tin tưởng gầy dựng bấy lâu với người bạn thân trong chớp mắt."},{sentence:"お金がないばかりに、子どもの頃からの夢だった留学を諦めざるを得なかった。",translation:"Chỉ vì không có tiền mà tôi đành phải từ bỏ ước mơ đi du học ấp ủ từ thuở nhỏ."}],dialogue:{title:"Bỏ lỡ chuyến bay",lines:[{speaker:"A",text:"どうしてそんなに落ち込んでいるの？何かあった？",translation:"Sao trông cậu suy sụp thế? Có chuyện gì xảy ra à?"},{speaker:"B",text:"目覚まし時計をセットし忘れたばかりに、大事な飛行機に乗り遅れちゃったんだ。",translation:"Chỉ vì quên đặt chuông báo thức mà tớ bị lỡ mất chuyến bay quan trọng rồi."},{speaker:"A",text:"えっ、それは大変だったね。次の便は手配できたの？",translation:"Hả, thế thì gay go quá. Cậu đã đặt được chuyến bay kế tiếp chưa?"}]},commonMistake:{wrong:"毎日一生懸命勉強したばかりに、N1の試験に無事合格できました。",correct:"毎日一生懸命勉強したおかげで、N1の試験に無事合格できました。",why:"「～ばかりに」 luôn dẫn đến kết quả xấu, tiêu cực hoặc đáng tiếc, không được dùng cho kết quả tốt hay việc đáng mừng (phải dùng 「～おかげで」)."},note:"Khi đi kèm mong muốn 「～たいばかりに」 (chỉ vì muốn... mà làm chuyện quá mức), câu vẫn nhấn mạnh vào cái giá phải trả hoặc hành động bất thường phát sinh từ mong muốn đó."},{pattern:"～かねる",meaning:"Khó có thể ~ / Không tiện",priority:"common",explanation:'Mẫu 「～かねる」 kết hợp với động từ thể ます (bỏ ます), mang ý nghĩa "khó có thể..." hoặc "không tiện làm...". Mẫu câu này được dùng khi người nói muốn từ chối một yêu cầu, đề nghị một cách lịch sự, trang trọng vì lý do lập trường, đạo đức hoặc trách nhiệm công việc dù về mặt năng lực có thể làm được. Đây là cách diễn đạt phổ biến trong giao tiếp thương mại và dịch vụ khách hàng nhằm tránh dùng từ từ chối trực tiếp như 「できません」.',examples:[{sentence:"個人情報保護の観点から、他のお客様に関するお問い合わせにはお答えしかねます。",translation:"Dưới góc độ bảo mật thông tin cá nhân, chúng tôi khó có thể trả lời các thắc mắc liên quan đến khách hàng khác."},{sentence:"そのようなご提案は、弊社の現在の方針に合致しないため、受け入れかねます。",translation:"Đề xuất như vậy không phù hợp với định hướng hiện tại của công ty chúng tôi nên khó lòng chấp thuận được."}],dialogue:{title:"Yêu cầu đổi trả hàng",lines:[{speaker:"A",text:"すみません、先週購入したこの商品を返品して返金してもらえますか。",translation:"Xin lỗi, tôi có thể trả lại sản phẩm mua tuần trước này và nhận lại tiền được không?"},{speaker:"B",text:"申し訳ございません。一度ご使用になられた商品の返品・返金には応じかねます。",translation:"Thành thật xin lỗi quý khách. Chúng tôi khó lòng đáp ứng việc đổi trả và hoàn tiền đối với sản phẩm đã qua sử dụng."},{speaker:"A",text:"そうですか。タグを切ってしまったので仕方ないですね。",translation:"Vậy à. Tôi đã cắt mác rồi nên cũng đành chịu vậy."}]},commonMistake:{wrong:"私は英語が下手なので、英語で案内しかねます。",correct:"私は英語が下手なので、英語で案内できません。",why:"「～かねる」chỉ dùng để từ chối khéo vì lý do lập trường hoặc trách nhiệm trong bối cảnh trang trọng, không dùng để diễn đạt việc thiếu kỹ năng hay khả năng thể chất đơn thuần của bản thân."},note:"Cần tránh nhầm lẫn với 「～かねない」 (có nguy cơ/khả năng cao sẽ xảy ra kết quả xấu), và lưu ý rằng tuy mang hình thức khẳng định nhưng 「～かねる」 lại biểu thị ý nghĩa phủ định."},{pattern:"～かねない",meaning:"Có thể ~ (rủi ro tiêu cực)",priority:"common",explanation:'Mẫu 「～かねない」 đi sau động từ thể ます (bỏ ます), dùng để dự đoán hoặc cảnh báo về khả năng một kết quả xấu, nguy hiểm có thể xảy ra từ một nguyên nhân hay trạng thái hiện tại. Mẫu câu mang sắc thái "có nguy cơ/e rằng sẽ dẫn đến hậu quả tiêu cực", thể hiện sự lo lắng của người nói. Điểm đặc trưng là ngữ pháp này chỉ dùng riêng cho các tình huống bất lợi, tuyệt đối không dùng khi dự đoán sự việc tích cực hay may mắn.',examples:[{sentence:"あんなに無理な働き方を続けていたら、過労で倒れかねないよ。",translation:"Nếu cứ tiếp tục làm việc quá sức như thế thì có nguy cơ ngất xỉu vì kiệt sức đấy."},{sentence:"この大雨で川の水位が急激に上がっており、氾濫しかねない危険な状態だ。",translation:"Do trận mưa lớn này mà mực nước sông đang dâng lên nhanh chóng, rơi vào tình trạng nguy hiểm có thể bị tràn bờ."}],dialogue:{title:"Cảnh báo rò rỉ dữ liệu",lines:[{speaker:"A",text:"パスワードをそんな簡単な文字列にしておくと、アカウントを乗っ取られかねないよ。",translation:"Nếu cứ để mật khẩu đơn giản thế kia thì có nguy cơ bị chiếm đoạt tài khoản đấy."},{speaker:"B",text:"えっ、覚えるのが苦手でつい…。すぐに変更したほうがいいですね。",translation:"Hả, do tôi hay quên nên lỡ để vậy... Nên đổi lại ngay thì hơn nhỉ."},{speaker:"A",text:"うん、会社の重要データも入っているから、二段階認証も設定しておいてね。",translation:"Ừ, có cả dữ liệu quan trọng của công ty nữa nên cậu hãy cài đặt cả xác thực hai bước nhé."}]},commonMistake:{wrong:"毎日一生懸命勉強すれば、N1に合格しかねない。",correct:"毎日一生懸命勉強すれば、N1に合格できるかもしれない。",why:"「～かねない」 chỉ dùng cho rủi ro hoặc hậu quả tiêu cực, không dùng cho kết quả tích cực như thi đỗ."},note:"Cần tránh nhầm lẫn giữa 「～かねない」(có khả năng xảy ra việc xấu) với 「～かねる」(khó lòng mà làm được / từ chối một cách lịch sự)."},{pattern:"～どころか",meaning:"Không những không ~ mà còn",priority:"common",explanation:"Mẫu câu 「～どころか」 dùng để nhấn mạnh rằng thực tế hoàn toàn trái ngược hoặc cách xa so với dự đoán, kỳ vọng ban đầu, mang nghĩa 'không những không... mà ngược lại/thậm chí còn...'. Cấu trúc này kết hợp trực tiếp với danh từ hoặc thể thông thường của động từ, tính từ (tính từ đuôi な giữ nguyên hoặc bỏ な). Người nói thường sử dụng mẫu này để phủ định mạnh mẽ khả năng xảy ra của vế trước và đưa ra một thực tế ở mức độ cực đoan hơn ở vế sau.",examples:[{sentence:"薬を飲んだのに、風邪は治るどころか熱がさらに上がって悪化してしまった。",translation:"Dù đã uống thuốc nhưng bệnh cảm không những không khỏi mà sốt còn tăng cao và trở nặng hơn."},{sentence:"景気回復でボーナスが増えると思いきや、増えるどころかカットされてしまった。",translation:"Cứ tưởng kinh tế phục hồi thì tiền thưởng sẽ tăng, ai ngờ tăng đâu chẳng thấy mà còn bị cắt giảm."}],dialogue:{title:"Tình hình công việc mới",lines:[{speaker:"A",text:"新しい職場にはもう慣れた？残業は少ないって聞いてたけど、どう？",translation:"Cậu đã quen với chỗ làm mới chưa? Nghe bảo ở đó ít tăng ca lắm, thế nào rồi?"},{speaker:"B",text:"全然だよ。残業が少ないどころか、毎日終電ギリギリまで働かされているんだ。",translation:"Hoàn toàn không luôn. Ít tăng ca đâu chẳng thấy, ngày nào tớ cũng bị bắt làm đến sát giờ tàu cuối đây."},{speaker:"A",text:"えっ、それは大変だね。無理して体を壊さないように気をつけてね。",translation:"Hả, thế thì vất vả quá. Cậu cẩn thận đừng làm việc quá sức kẻo hại sức khỏe nhé."}]},commonMistake:{wrong:"彼は英語どころか、フランス語も流暢に話せます。",correct:"彼は英語ばかりか、フランス語も流暢に話せます。",why:"「～どころか」 mang sắc thái phủ định hoặc trái ngược mạnh mẽ với vế trước, không dùng để bổ sung thông tin cùng chiều tích cực (không chỉ A mà còn thêm B) như 「～ばかりか」 hay 「～だけでなく」."},note:"Cần phân biệt với 「～ばかりか」: 「～ばかりか」 dùng để lũy tiến thông tin cùng chiều (A đã tốt/xấu, B còn tốt/xấu hơn), còn 「～どころか」 biểu thị sự đảo ngược hoặc vế trước hoàn toàn không đạt được so với thực tế vế sau."},{pattern:"～はもとより",meaning:"Không chỉ ~ mà còn ~",priority:"common",explanation:"Mẫu ngữ pháp này dùng để diễn tả ý «A là điều hiển nhiên rồi, nhưng không chỉ A mà ngay cả B cũng...». Cấu trúc thường đi trực tiếp sau Danh từ (hoặc Danh từ + Trợ từ), vế sau thường đi kèm với trợ từ 「も」 để mở rộng thêm đối tượng khác. Đây là cách diễn đạt mang tính trang trọng, lịch sự và mang hơi hướng văn viết nhiều hơn so với 「～はもちろん」, thường được dùng trong các bài phát biểu, hội nghị hoặc báo cáo công việc.",examples:[{sentence:"このレストランは、料理の味はもとより、接客サービスの素晴らしさでも高く評価されている。",translation:"Nhà hàng này không chỉ có hương vị món ăn ngon (là đương nhiên) mà còn được đánh giá rất cao về sự tuyệt vời trong cung cách phục vụ."},{sentence:"新製品の開発には、国内市場はもとより、海外市場の動向も視野に入れる必要がある。",translation:"Trong việc phát triển sản phẩm mới, không chỉ thị trường trong nước mà chúng ta còn cần phải để mắt tới cả xu hướng của thị trường nước ngoài."}],dialogue:{title:"Đào tạo nhân viên mới",lines:[{speaker:"A",text:"今度の新入社員研修のカリキュラムはどうしますか。",translation:"Chương trình đào tạo cho nhân viên mới đợt tới này anh định thế nào?"},{speaker:"B",text:"業務の基礎知識はもとより、社会人としてのビジネスマナーもしっかり身につけさせたいと考えています。",translation:"Tôi dự định không chỉ giúp họ nắm vững kiến thức nghiệp vụ cơ bản mà còn phải trang bị kỹ cả tác phong làm việc của người đi làm nữa."},{speaker:"A",text:"賛成です。現場に出てすぐ即戦力になれるようサポートしましょう。",translation:"Tôi tán thành. Hãy hỗ trợ để họ có thể trở thành nhân lực làm việc được ngay khi bước vào thực tế nhé."}]},commonMistake:{wrong:"彼は英語を話すはもとより、フランス語も流暢に話せる。",correct:"彼は英語はもとより、フランス語も流暢に話せる。",why:"「～はもとより」chỉ kết hợp trực tiếp với Danh từ (hoặc Danh từ + Trợ từ), không được gắn trực tiếp vào sau động từ thể từ điển."},note:"So với 「～はもちろん」, mẫu 「～はもとより」 mang sắc thái trang trọng, văn phong viết cứng cáp hơn nhiều nên thường dùng trong văn bản, thuyết trình và tránh dùng trong giao tiếp thân mật hàng ngày."},{pattern:"～にほかならない",meaning:"Không gì khác chính là ~",priority:"common",explanation:'Mẫu câu này dùng để khẳng định mạnh mẽ và dứt khoát rằng một sự việc, hiện tượng chính là điều đó và không thể là bất cứ thứ gì khác (nghĩa là "chính là / không gì khác ngoài..."). Khi dùng để nhấn mạnh lý do cốt lõi, mẫu câu thường kết hợp thành dạng 「～から／～ため＋にほかならない」. Đây là cách diễn đạt trang trọng, mang tính văn viết, thường được sử dụng nhiều trong văn luận thuyết, xã luận, báo chí hoặc phát biểu chính thức.',examples:[{sentence:"今回のプロジェクトが成功したのは、チーム全員の献身的な協力があったからにほかならない。",translation:"Dự án lần này thành công không gì khác chính là nhờ có sự hợp tác đầy tận tụy của toàn thể thành viên trong đội ngũ."},{sentence:"彼が批判を恐れずに発言し続けるのは、この国の将来を真剣に憂えているからにほかならない。",translation:"Việc anh ấy tiếp tục lên tiếng mà không sợ bị chỉ trích chính là vì anh ấy thực sự lo lắng cho tương lai của đất nước này."}],dialogue:{title:"Bí quyết thi đỗ N1",lines:[{speaker:"A",text:"先輩、今回のN1で満点を取れた秘訣は何ですか。",translation:"Tiền bối ơi, bí quyết giúp anh đạt điểm tuyệt đối trong kỳ thi N1 lần này là gì vậy ạ?"},{speaker:"B",text:"特別なことは何もしていないよ。毎日の地道な積み重ねの結果にほかならないと思う。",translation:"Anh chẳng làm điều gì đặc biệt cả đâu. Anh nghĩ đó không gì khác chính là kết quả của việc kiên trì tích lũy từng ngày thôi."},{speaker:"A",text:"やはり日々の努力が一番大切なんですね。私も見習います。",translation:"Quả nhiên nỗ lực mỗi ngày vẫn là quan trọng nhất. Em cũng sẽ học tập theo anh."}]},commonMistake:{wrong:"彼が成功したのは、運がよかったにほかならない。",correct:"彼が成功したのは、運がよかったからにほかならない。",why:"Khi giải thích nguyên nhân/lý do cho cấu trúc 「～のは」 ở đầu câu, mệnh đề vị ngữ đứng trước 「にほかならない」 bắt buộc phải có 「から」 (dạng 「～からにほかならない」)."},note:'Cần phân biệt với 「～にすぎない」 mang sắc thái "chỉ là / chẳng qua chỉ là" (hạ thấp mức độ), trong khi 「～にほかならない」 mang tính khẳng định tuyệt đối bản chất của sự việc.'},{pattern:"～に過ぎない",meaning:"Chỉ là ~ mà thôi",priority:"common",explanation:'Mẫu ngữ pháp này mang ý nghĩa "chỉ là... không hơn", dùng để nhấn mạnh một sự việc, hành động hay trạng thái chỉ dừng lại ở mức độ thấp, đơn giản và không có gì to tát. Cấu trúc thường kết hợp với thể thông thường của động từ hoặc danh từ (V-thể thông thường / N + に過ぎない). Mẫu câu thường được sử dụng với thái độ đánh giá khách quan hoặc khiêm tốn khi tự nói về bản thân.',examples:[{sentence:"私が言ったことは単なる個人的な推測に過ぎない。",translation:"Những điều tôi vừa nói chỉ là suy đoán mang tính cá nhân mà thôi."},{sentence:"今回の合格は最初の第一歩に過ぎない。",translation:"Việc đỗ kỳ thi lần này chỉ là bước đi đầu tiên mà thôi."}],dialogue:{title:"Đánh giá kết quả thi",lines:[{speaker:"A",text:"コンテストで優勝したそうですね。本当に素晴らしい成果ですよ。",translation:"Nghe nói bạn đã giành giải nhất trong cuộc thi rồi nhỉ. Thật là một thành tích tuyệt vời đấy."},{speaker:"B",text:"ありがとうございます。でも、運が良かっただけに過ぎないと思っています。",translation:"Cảm ơn bạn. Nhưng tôi nghĩ đó chỉ là do may mắn mà thôi."},{speaker:"A",text:"そんなに謙遜しなくても、これまでの努力の成果ですよ。",translation:"Bạn không cần phải khiêm tốn thế đâu, đó là thành quả của sự nỗ lực bấy lâu nay mà."}]},commonMistake:{wrong:"これは単なる冗談にほかならないのに、彼は怒ってしまった。",correct:"これは単なる冗談に過ぎないのに、彼は怒ってしまった。",why:'Khi muốn diễn đạt sự việc chỉ ở mức độ nhẹ, không đáng kể ("chỉ là trò đùa"), phải dùng 「～に過ぎない」 thay vì 「～にほかならない」 (mang nghĩa khẳng định mạnh mẽ "chính là").'},note:'Cần phân biệt với 「～にほかならない」 vốn mang nghĩa khẳng định mạnh ("chính là / không gì khác ngoài"), trong khi 「～に過ぎない」 dùng để hạ thấp mức độ hoặc khiêm tốn ("chỉ là... không hơn").'}],143:[{pattern:"～というものだ",meaning:"Đó mới là ~ (bản chất/lẽ thường)",priority:"core",explanation:"Mẫu ngữ pháp này dùng để đưa ra nhận định, đánh giá dứt khoát mang tính tất yếu hoặc khẳng định bản chất của sự việc theo lẽ thường (dịch là: 'thật đúng là...', 'đó mới chính là...'). Phía trước thường kết hợp với các từ mang tính đánh giá, cảm thán mạnh mẽ như 無理 (vô lý), 贅沢 (xa xỉ), 不可能 (bất khả thi), 特権 (đặc quyền). Mẫu này mang sắc thái thuyết phục, đúc kết triết lý hoặc phê phán dựa trên chuẩn mực chung, thường xuất hiện trong văn viết hoặc phát biểu trang trọng.",examples:[{sentence:"たった一人でこの大規模なシステム障害を今日中に復旧させろというのは、無理というものだ。",translation:"Bắt một người duy nhất phải khắc phục xong sự cố hệ thống quy mô lớn này ngay trong ngày hôm nay thì thật đúng là quá vô lý."},{sentence:"失敗を恐れずに何度でも未知の領域へ挑戦することこそ、若者の特権というものだ。",translation:"Dám không sợ thất bại mà thử thách bản thân nhiều lần ở những lĩnh vực chưa biết, đó mới thực sự là đặc quyền của tuổi trẻ."}],dialogue:{title:"Kế hoạch đi du lịch",lines:[{speaker:"A",text:"今から明日の朝出発のハワイ行き航空券を格安で探すなんて、さすがに無茶というものだよ。",translation:"Giờ này mà còn đòi tìm vé máy bay giá rẻ đi Hawaii bay vào sáng mai thì thật đúng là chuyện không tưởng đấy."},{speaker:"B",text:"やっぱりそうかな。大型連休の直前だし、空席があるだけでも奇跡だよね。",translation:"Quả nhiên là vậy nhỉ. Ngay sát kỳ nghỉ lễ dài thế này thì còn ghế trống thôi cũng là kỳ tích rồi."},{speaker:"A",text:"うん、せめて1か月前から計画しておくべきだったね。",translation:"Ừ, đáng lẽ chúng ta nên lên kế hoạch trước ít nhất một tháng."}]},commonMistake:{wrong:"天気予報によると、明日は午後から激しい雷雨になるというものだ。",correct:"天気予報によると、明日は午後から激しい雷雨になるということだ。",why:"「～というものだ」dùng để biểu đạt nhận định, cảm thán về bản chất/lẽ thường của người nói chứ không dùng để truyền đạt lại thông tin nghe được từ nguồn khác (nghe nói/theo nguồn tin thì phải dùng「～ということだ」hoặc「～とのことだ」)."},note:"Cần chú ý dạng phủ định「～というものでもない／というものではない」(không hẳn là / không phải cứ... là được) rất hay xuất hiện trong đề thi N2, N1 để thể hiện quan điểm phủ định một phần."},{pattern:"～ものがある",meaning:"Có điều gì đó ~ (cảm nhận chủ quan)",priority:"common",explanation:'Mẫu ngữ pháp này dùng để diễn tả cảm nhận, cảm xúc hoặc đánh giá chủ quan sâu sắc của người nói về một sự vật, sự việc ("có cảm giác rất...", "có điều gì đó khiến ta thấy..."). Cấu trúc thường kết hợp với các từ ngữ thể hiện tâm trạng, ấn tượng như「感じる」「考えさせられる」「懐かしい」「寂しい」hoặc đi kèm「どこか」「何となく」. Thường được sử dụng trong văn viết hoặc cách nói trang trọng để bộc lộ sự xúc động, trăn trở hoặc đồng cảm.',examples:[{sentence:"彼の演奏には、聴く人の心を強く揺さぶるものがある。",translation:"Màn trình diễn của anh ấy có một điều gì đó lay động mạnh mẽ trái tim người nghe."},{sentence:"長年住み慣れた実家を離れるのは、やはりどこか寂しいものがある。",translation:"Rời xa ngôi nhà gắn bó bao năm quả thực có cảm giác gì đó rất buồn bã."}],dialogue:{title:"Đánh giá bài thuyết trình",lines:[{speaker:"A",text:"昨日の佐藤さんのプレゼン、とても説得力があったね。",translation:"Bài thuyết trình hôm qua của anh Sato thực sự rất có sức thuyết phục nhỉ."},{speaker:"B",text:"ええ、データだけじゃなく、彼の熱意には人を引きつけるものがありましたね。",translation:"Vâng, không chỉ số liệu đâu, mà sự nhiệt huyết của anh ấy có điều gì đó rất cuốn hút người khác."},{speaker:"A",text:"そうだね。若手であれだけの情熱を持って語れるのは見習うべきものがあるよ。",translation:"Đúng thế. Người trẻ mà có thể nói với niềm đam mê như vậy thì quả thực có điều đáng để chúng ta học hỏi."}]},commonMistake:{wrong:"彼の作品には、どこか人々の心を打つことがある。",correct:"彼の作品には、どこか人々の心を打つものがある。",why:'Mẫu「～ものがある」dùng để diễn tả giá trị, sức lay động hoặc cảm xúc ẩn chứa bên trong sự vật ("có điều gì đó chạm đến trái tim"), còn「～ことがある」chỉ biểu thị tần suất ("thỉnh thoảng/có lúc xảy ra").'},note:'Cần phân biệt「～ものがある」(bộc lộ cảm xúc, ấn tượng sâu sắc từ phía người nói) với「～というものだ」(khẳng định một chân lý, bản chất đương nhiên "đó thực sự chính là...").'},{pattern:"～とは限らない",meaning:"Không nhất thiết ~ / Không hẳn là",priority:"common",explanation:'Mẫu ngữ pháp này dùng để phủ định một phần quan niệm hoặc nhận định chung, mang ý nghĩa "không nhất thiết là..." hoặc "không hẳn là...". Mẫu câu diễn tả rằng sự việc không mang tính tuyệt đối 100% mà luôn tồn tại những trường hợp ngoại lệ. Thường đi kèm với các phó từ như 「必ずしも」(không hẳn/chưa chắc) hoặc 「いつも」(luôn luôn) và được sử dụng linh hoạt trong cả văn nói lẫn văn viết.',examples:[{sentence:"値段が高いものが、必ずしも質が良いとは限らない。",translation:"Đồ đắt tiền chưa chắc đã có chất lượng tốt."},{sentence:"日本語能力試験N1に合格したからといって、日本語が上手に話せるとは限らない。",translation:"Dù đã thi đỗ JLPT N1 nhưng không hẳn là có thể giao tiếp tiếng Nhật trôi chảy."}],dialogue:{title:"Tư vấn mua máy tính",lines:[{speaker:"A",text:"一番高いパソコンを買えば、作業が絶対に速くなるよね。",translation:"Cứ mua chiếc máy tính đắt nhất thì chắc chắn xử lý công việc sẽ nhanh hơn nhỉ."},{speaker:"B",text:"スペックが高くても、使いこなせるとは限らないから、用途に合わせて選んだほうがいいよ。",translation:"Dù cấu hình cao nhưng không hẳn là mình tận dụng hết được đâu, nên chọn theo nhu cầu thực tế thì hơn."},{speaker:"A",text:"確かにそうだね。自分に必要な性能をもう一度考えてみるよ。",translation:"Đúng là vậy nhỉ. Để mình cân nhắc lại hiệu năng cần thiết cho bản thân xem sao."}]},commonMistake:{wrong:"高いものが必ずしも質が良いに限らない。",correct:"高いものが必ずしも質が良いとは限らない。",why:"Người học hay nhầm lẫn giữa mẫu「～に限らない」(không chỉ giới hạn ở...) với「～とは限らない」(không hẳn/chưa chắc là...)."},note:"Mẫu này rất thường xuyên đi kèm phó từ「必ずしも」để nhấn mạnh ý phủ định một phần và nêu ra khả năng xảy ra ngoại lệ."},{pattern:"～上で",meaning:"Sau khi ~ xong / Về mặt ~",priority:"common",explanation:"Mẫu 「～上で」 được dùng để diễn tả việc hoàn thành hành động A như một tiền đề, bước chuẩn bị cần thiết trước khi tiến hành hành vi B (dạng Vた上で / Nの上で), hoặc mang nghĩa 'trong quá trình, khi làm V' (dạng Vる上で). Cấu trúc này nhấn mạnh mối liên hệ chặt chẽ và có chủ ý giữa hai hành động, vế sau thường là quyết định, hành vi có ý chí hoặc lời khuyên quan trọng. Mẫu câu mang sắc thái trang trọng, thường được dùng trong công việc, thủ tục hành chính hoặc các quyết định nghiêm túc.",examples:[{sentence:"契約内容を十分にご確認いただいた上で、こちらにご署名とご捺印をお願いいたします。",translation:"Sau khi đã kiểm tra kỹ lưỡng nội dung hợp đồng, xin quý khách vui lòng ký tên và đóng dấu vào đây."},{sentence:"異文化を理解する上で、相手の宗教や生活習慣を尊重することは極めて重要です。",translation:"Trong quá trình tìm hiểu một nền văn hóa khác, việc tôn trọng tôn giáo và tập quán sinh hoạt của đối phương là vô cùng quan trọng."}],dialogue:{title:"Quyết định chuyển việc",lines:[{speaker:"A",text:"転職の件、もうどちらにするか決めたの？",translation:"Chuyện chuyển việc, cậu đã quyết định chọn bên nào chưa?"},{speaker:"B",text:"いや、家族としっかり相談した上で、来週の月曜日に最終的な返事を出すつもりだよ。",translation:"Chưa, sau khi bàn bạc kỹ với gia đình, tớ dự định thứ Hai tuần tới mới đưa ra câu trả lời cuối cùng."},{speaker:"A",text:"そうだね。人生の大きな選択だから、納得いくまで話し合ったほうがいいよ。",translation:"Đúng vậy đấy. Vì là lựa chọn lớn của cuộc đời nên nên trao đổi cho đến khi thỏa đáng."}]},commonMistake:{wrong:"朝ご飯を食べた上で、学校へ行きました。",correct:"朝ご飯を食べてから、学校へ行きました。",why:"「～た上で」 chỉ dùng khi hành động trước là bước chuẩn bị hoặc điều kiện tiên quyết cho hành động có chủ ý phía sau, không dùng cho chuỗi hành động sinh hoạt thường ngày tự nhiên."},note:"Cần chú ý phân biệt: 「Vた上で」 mang nghĩa 'sau khi làm A rồi mới làm B' (vế sau là hành động có chủ đích), còn 「Vる上で」 mang nghĩa 'khi / trong quá trình làm A' (vế sau thường là điều quan trọng, cần thiết hoặc khó khăn)."},{pattern:"～からといって",meaning:"Chỉ vì ~ không có nghĩa là",priority:"common",explanation:'Mẫu câu 「～からといって」 dùng để diễn đạt ý nghĩa "dù có lý do A đi chăng nữa thì kết quả B cũng không hẳn sẽ xảy ra như lẽ thường". Vế sau hầu như luôn đi kèm với các dạng phủ định một phần như 「～わけではない」(không hẳn là) hoặc 「～とは限らない」(chưa chắc là). Mẫu này thường dùng để bác bỏ một nhận định phiến diện, hoặc đưa ra lời khuyên nhủ, phê phán nhẹ nhàng đối với người khác.',examples:[{sentence:"給料が高いからといって、その仕事が自分に合っているとは限らない。",translation:"Chỉ vì lương cao không có nghĩa là công việc đó chắc chắn phù hợp với bản thân."},{sentence:"日本に長く住んでいるからといって、誰もが日本語を流暢に話せるわけではない。",translation:"Không phải cứ sống ở Nhật lâu là ai cũng có thể nói tiếng Nhật lưu loát."}],dialogue:{title:"Lời khuyên mua sắm",lines:[{speaker:"A",text:"最新型で値段が高いからといって、必ずしも壊れにくいとは言えないよ。",translation:"Chỉ vì là đời mới nhất và đắt tiền thì không có nghĩa là chắc chắn sẽ khó hỏng đâu."},{speaker:"B",text:"えっ、そうなの？高いものを買っておけば安心だと思ってた。",translation:"Ơ, thế à? Mình cứ tưởng mua đồ đắt tiền thì sẽ yên tâm hơn chứ."},{speaker:"A",text:"使い方次第だから、値段の高さだけで決めるのは良くないよ。",translation:"Còn tùy vào cách dùng nữa, nên chỉ dựa vào giá cao để quyết định là không tốt đâu."}]},commonMistake:{wrong:"日本人だからといって、漢字を全部知っています。",correct:"日本人だからといって、漢字を全部知っているわけではない。",why:"Vế sau của 「～からといって」 không đi với câu khẳng định tuyệt đối mà bắt buộc phải dùng đuôi phủ định (như わけではない, とは限らない) để bác bỏ nhận định."},note:"Cấu trúc này rất hay kết hợp với các phó từ mang tính nhượng bộ/bác bỏ như 「必ずしも」「決して」「いくら」 để nhấn mạnh ý nghĩa."},{pattern:"～ようがない",meaning:"Không có cách nào để ~",priority:"common",explanation:"Mẫu ngữ pháp này đi sau động từ thể Masu (bỏ ます) nhằm diễn đạt ý 'dù rất muốn làm nhưng hoàn toàn không có cách nào hay phương tiện nào để thực hiện'. Cấu trúc này thể hiện sự bất lực, bế tắc của người nói trước một tình huống thực tế do thiếu thốn điều kiện, công cụ hoặc thông tin. Thường chỉ kết hợp với các động từ chỉ hành động có chủ ý (như liên lạc, sửa chữa, giải thích, cứu vãn).",examples:[{sentence:"連絡先も現住所も分からないのだから、こちらからは連絡のしようがない。",translation:"Vì không biết cả thông tin liên lạc lẫn địa chỉ hiện tại nên phía chúng tôi hoàn toàn không có cách nào để liên lạc được."},{sentence:"データのバックアップを取っていなかったため、パソコンが完全に壊れてしまっては復旧のしようがない。",translation:"Vì không sao lưu dữ liệu nên một khi máy tính đã hỏng hoàn toàn thì chẳng còn cách nào để khôi phục lại."}],dialogue:{title:"Hỏng xe giữa đường vắng",lines:[{speaker:"A",text:"車のエンジンが急に止まっちゃったよ。工具も知識もないから、自分たちでは直しようがないね。",translation:"Động cơ xe tự dưng bị chết máy rồi. Không có dụng cụ lẫn kiến thức chuyên môn nên tụi mình chẳng có cách nào tự sửa được đâu."},{speaker:"B",text:"ロードサービスに電話してみる？近くならすぐ来てくれるかもしれないし。",translation:"Hay là thử gọi cứu hộ đường bộ xem sao? Nếu ở gần có khi họ tới ngay được đấy."},{speaker:"A",text:"それが、山奥だから圏外になっていて電話の掛けようがないんだよ。",translation:"Khổ nỗi là đang ở trong vùng núi sâu nên mất sóng, chẳng có cách nào để gọi điện thoại được cả."}]},commonMistake:{wrong:"海の中に鍵を落としてしまったので、もう探すようがない。",correct:"海の中に鍵を落としてしまったので、もう探しようがない。",why:"Mẫu「～ようがない」bắt buộc phải kết hợp với động từ thể Masu bỏ ます (探しようがない), người học hay nhầm lẫn ghép trực tiếp với thể từ điển (探す)."},note:"Với danh từ động từ nhóm 3 thường dùng dạng「N + の + しようがない」(như 連絡のしようがない), và khi bổ nghĩa cho danh từ đi sau thì biến đổi thành「～ようのない + N」."},{pattern:"～まい",meaning:"Chắc không ~ / Quyết không",priority:"common",explanation:'「～まい」 là mẫu ngữ pháp trang trọng dùng để diễn đạt hai ý nghĩa chính: phủ định ý chí ("quyết không làm...") và phủ định suy đoán ("chắc là không..."). Về cách kết hợp, động từ nhóm 1 nối với thể từ điển + まい, động từ nhóm 2 dùng thể từ điển hoặc bỏ ない + まい, còn động từ nhóm 3 có dạng đặc biệt như すまい/するまい và こまい/くるまい. Mẫu câu này mang sắc thái văn viết đanh thép, thể hiện quyết tâm dứt khoát hoặc sự phán đoán mang tính logic cao của người nói.',examples:[{sentence:"あんなひどい目に遭ったのだから、二度とあの店には行くまい。",translation:"Đã gặp phải trải nghiệm tồi tệ như thế thì tôi quyết sẽ không bao giờ đến cửa hàng đó lần thứ hai."},{sentence:"彼ほどのベテラン社員なら、このような単純なミスは犯すまい。",translation:"Một nhân viên kỳ cựu cỡ như anh ấy thì chắc hẳn sẽ không phạm phải lỗi ngớ ngẩn như thế này đâu."}],dialogue:{title:"Quyết tâm bỏ đồ ngọt",lines:[{speaker:"A",text:"健康診断で引っかかったから、今日から甘いものは絶対に食べるまいと決めたんだ。",translation:"Vì bị cảnh báo trong đợt khám sức khỏe nên từ hôm nay tớ quyết không ăn đồ ngọt nữa."},{speaker:"B",text:"えっ、本当？でも君、目の前にケーキがあったら我慢できないんじゃない？",translation:"Hả, thật á? Nhưng nếu có bánh kem ngay trước mắt thì cậu có kiềm chế nổi không đấy?"},{speaker:"A",text:"今回は本気だよ。もう二度と後悔はしたくないからね。",translation:"Lần này tớ nghiêm túc đấy. Tớ không muốn phải hối hận thêm lần nào nữa đâu."}]},commonMistake:{wrong:"もう二度とお酒を飲まないまい。",correct:"もう二度とお酒を飲むまい。",why:"Bản thân「まい」đã mang nghĩa phủ định, nên động từ nhóm 1 phải đi trực tiếp từ thể từ điển (飲むまい) chứ không gắn vào thể「～ない」."},note:"Khi diễn đạt ý chí không làm gì của người thứ ba, không kết thúc câu bằng「～まい」trực tiếp mà phải dùng dạng「～まいと思っている」hoặc「～まいとしている」."},{pattern:"～に相違ない",meaning:"Chắc chắn là ~ (trang trọng)",priority:"common",explanation:'Mẫu 「～に相違ない」 dùng để đưa ra phán đoán hoặc khẳng định mang tính chắc chắn cao của người nói dựa trên chứng cứ hoặc lập luận rõ ràng, mang nghĩa "chắc chắn là / không sai được". Đây là cách diễn đạt mang sắc thái trang trọng, văn phong cứng hơn nhiều so với 「～に違いない」, thường được dùng trong văn viết, báo cáo, bài phát biểu hoặc các bối cảnh trang trọng. Khi kết hợp, động từ và tính từ đuôi い ở thể thông thường, còn danh từ và tính từ đuôi な sẽ đi trực tiếp (bỏ だ) hoặc dùng dạng 「である」 trước 「に相違ない」.',examples:[{sentence:"現場に残された指紋から判断すると、犯人は内部の事情に詳しい者に相違ない。",translation:"Phán đoán từ dấu vân tay để lại hiện trường, thủ phạm chắc chắn là người nắm rất rõ tình hình nội bộ."},{sentence:"この画期的な新技術の開発は、今後の医療業界に大きな変革をもたらすに相違ない。",translation:"Việc phát triển công nghệ mới mang tính đột phá này chắc chắn sẽ đem lại sự thay đổi lớn cho ngành y tế trong tương lai."}],dialogue:{title:"Phân tích kết quả kinh doanh",lines:[{speaker:"A",text:"今期の売上データを見る限り、今回の新規事業は大成功だったに相違ない。",translation:"Căn cứ vào số liệu doanh thu kỳ này, dự án kinh doanh mới lần này chắc chắn đã thành công rực rỡ."},{speaker:"B",text:"ええ、顧客からの評判も非常に高いので、来期も更なる成長が見込めますね。",translation:"Vâng, phản hồi từ khách hàng cũng rất tích cực, nên kỳ tới chúng ta hoàn toàn có thể kỳ vọng tăng trưởng hơn nữa."},{speaker:"A",text:"この勢いを維持できるよう、チーム全体でサポート体制を強化していきましょう。",translation:"Để duy trì đà phát triển này, chúng ta hãy cùng tăng cường hệ thống hỗ trợ trên toàn đội ngũ nhé."}]},commonMistake:{wrong:"彼が優秀な研究者だに相違ない。",correct:"彼が優秀な研究者に相違ない。（hoặc: 優秀な研究者であるに相違ない）",why:"Khi kết hợp với danh từ và tính từ đuôi な, phải bỏ 「だ」 để nối trực tiếp hoặc dùng dạng 「である」, không được giữ nguyên 「だ」."},note:"「～に相違ない」 đồng nghĩa với 「～に違いない」 nhưng trang trọng và mang tính học thuật, văn viết hơn, nên không dùng trong giao tiếp xuồng xã hàng ngày."}],144:[{pattern:"～はおろか",meaning:"Nói gì đến ~, đến ~ cũng không",priority:"core",explanation:'Mẫu câu dùng để diễn đạt ý nghĩa "nói gì đến A (mức độ cao/đương nhiên), ngay cả B (mức độ cơ bản/thấp hơn) cũng không thể/không có". Cấu trúc này thường đi trực tiếp sau Danh từ, vế sau thường kết hợp với các trợ từ nhấn mạnh như 「も」「さえ」「すら」 và đi với dạng phủ định. Mẫu câu mang sắc thái bất mãn, thất vọng hoặc nhấn mạnh tình trạng khó khăn, thiếu thốn vượt ngoài mức thông thường.',examples:[{sentence:"彼は大きな事故に遭い、走ることはおろか、一人で歩くことさえできない状態だ。",translation:"Anh ấy gặp tai nạn nghiêm trọng, nói gì đến chạy, ngay cả tự đi lại một mình cũng không thể làm được."},{sentence:"毎日の生活費を払うので精一杯で、海外旅行はおろか、外食すら滅多にできない。",translation:"Trả tiền sinh hoạt mỗi ngày đã chật vật lắm rồi, nói gì đến đi du lịch nước ngoài, ngay cả đi ăn ngoài tiệm tôi cũng hiếm khi."}],dialogue:{title:"Tình hình sức khỏe",lines:[{speaker:"A",text:"田中さん、風邪の具合はどうですか。明日の重要な会議に出席できそうですか。",translation:"Tanaka-san, tình hình cảm cúm thế nào rồi? Liệu anh ấy có thể tham gia cuộc họp quan trọng ngày mai không?"},{speaker:"B",text:"いえ、声が出ないのはおろか、高熱でベッドから起き上がることすらできないようです。",translation:"Không, nói gì đến chuyện mất tiếng không nói được, hình như anh ấy còn sốt cao đến mức không ngồi dậy khỏi giường nổi nữa."},{speaker:"A",text:"それは大変ですね。無理をしないでしっかり休むように伝えてください。",translation:"Vất vả quá nhỉ. Cậu nhắn anh ấy đừng cố quá mà hãy nghỉ ngơi cho lại sức nhé."}]},commonMistake:{wrong:"彼は英語はおろか、フランス語も流暢に話すことができる。",correct:"彼はフランス語はおろか、簡単な英語の挨拶すら話せない。",why:"「～はおろか」thường dùng cho vế sau có mức độ thấp hơn mang nghĩa tiêu cực hoặc bất khả thi (ngay cả... cũng không), không dùng để khen ngợi hay diễn tả sự gia tăng tích cực như「～ばかりか」."},note:"Khác với「～どころか」có thể dùng linh hoạt để phủ định hoặc đưa ra vế sau tích cực hơn thực tế,「～はおろか」gần như luôn đi kèm với「さえ・すら・も」ở vế sau và biểu thị tình trạng tiêu cực/thiếu sót."},{pattern:"～向き",meaning:"Tự nhiên phù hợp với ~",priority:"common",explanation:'Mẫu ngữ pháp 「～向き」 kết hợp trực tiếp sau danh từ, mang ý nghĩa "phù hợp, thích hợp với..." dựa trên đặc tính, bản chất tự nhiên vốn có của người hoặc vật. Cấu trúc thường gặp gồm 「N + 向きだ / 向きのN / 向きに」. Mẫu này dùng để đưa ra đánh giá khách quan rằng một đối tượng, môi trường hay công việc tự nhiên ăn khớp với tính cách, điều kiện hoặc thể trạng sẵn có, chứ không phải do cố tình tạo ra cho đối tượng đó.',examples:[{sentence:"彼女は人と話すのが好きで明るい性格だから、接客の仕事向きだと思う。",translation:"Cô ấy thích trò chuyện với mọi người lại có tính cách hoạt bát nên tôi nghĩ rất hợp với công việc chăm sóc khách hàng."},{sentence:"このアパートは静かで駅からも近いので、一人暮らしの社会人向きの物件だ。",translation:"Căn hộ này yên tĩnh lại gần ga nên là bất động sản rất phù hợp cho người đi làm sống một mình."}],dialogue:{title:"Chọn rượu cho bữa tiệc",lines:[{speaker:"A",text:"明日のパーティーに持っていくお酒を探しているんですが、何かおすすめはありますか。",translation:"Tôi đang tìm loại rượu để mang đến bữa tiệc ngày mai, bạn có gợi ý nào không?"},{speaker:"B",text:"この白ワインはいかがですか。フルーティーで甘口なので、お酒があまり強くない人向きですよ。",translation:"Chai vang trắng này thì sao? Vị ngọt thơm hương trái cây nên rất hợp với những người không uống được nhiều rượu đấy."},{speaker:"A",text:"いいですね！飲みやすそうなので、これに決めます。",translation:"Tuyệt quá! Trông có vẻ dễ uống, tôi sẽ chọn chai này."}]},commonMistake:{wrong:"彼は冷静で細かい作業が得意だから、研究職向けだ。",correct:"彼は冷静で細かい作業が得意だから、研究職向きだ。",why:"Khi nói về tố chất, tính cách tự nhiên của một người phù hợp với một ngành nghề thì phải dùng 「～向き」, còn 「～向け」 chỉ dùng cho sự vật được chủ đích thiết kế hoặc sản xuất nhắm tới đối tượng."},note:"Phân biệt với 「～向け」: 「～向き」 nhấn mạnh sự phù hợp tự nhiên do đặc tính vốn có (vừa vặn, hợp với), còn 「～向け」 biểu thị mục đích được cố ý làm ra, hướng tới đối tượng cụ thể (dành riêng cho)."},{pattern:"～をおいて",meaning:"Ngoài ~ ra không có ai/gì khác",priority:"common",explanation:'Mẫu 「～をおいて」 (thường đi với vế sau mang nghĩa phủ định như ～ない, ～ほかにいない) có nghĩa là "ngoài... ra thì không có ai/gì khác có thể sánh bằng hoặc làm được". Mẫu này được dùng khi người nói muốn đánh giá rất cao, khẳng định tính duy nhất hoặc năng lực vượt trội của một người, sự vật hay địa điểm cụ thể. Ngữ thái trang trọng, mang tính văn viết hoặc dùng trong các phát biểu mang tính tán dương, tiến cử.',examples:[{sentence:"次の大型プロジェクトのリーダーを務められるのは、経験豊富な彼をおいてほかにいない。",translation:"Người có thể đảm nhận vai trò trưởng dự án lớn tiếp theo, ngoài người giàu kinh nghiệm như anh ấy ra thì không có ai khác."},{sentence:"伝統的な日本庭園の美しさを心ゆくまで堪能できる場所は、京都のこの寺院をおいてない。",translation:"Nơi có thể thưởng thức trọn vẹn vẻ đẹp của khu vườn truyền thống Nhật Bản, ngoài ngôi chùa này ở Kyoto ra thì không có nơi nào khác."}],dialogue:{title:"Chọn diễn viên chính",lines:[{speaker:"A",text:"今度の新作映画の主役、誰に依頼するかもう決まりましたか。",translation:"Vai chính cho bộ phim mới lần này anh đã quyết định mời ai chưa?"},{speaker:"B",text:"この難しい役柄を演じ切れる実力派俳優は、佐藤さんをおいてほかには考えられませんね。",translation:"Diễn viên thực lực có thể đảm đương trọn vẹn vai diễn phức tạp này thì ngoài anh Sato ra không thể nghĩ tới ai khác được."},{speaker:"A",text:"確かにそうですね。早速事務所にオファーを出してみましょう。",translation:"Đúng là như vậy. Chúng ta hãy gửi lời mời tới công ty quản lý của anh ấy ngay thôi."}]},commonMistake:{wrong:"田中さんをおいて、全員が時間通りに会議室に集まりました。",correct:"田中さんを除いて、全員が時間通りに会議室に集まりました。",why:"「～をおいて」 bắt buộc đi với vế sau mang nghĩa phủ định để nhấn mạnh sự duy nhất/đánh giá cao, không dùng để biểu thị việc loại trừ một đối tượng thông thường như 「～を除いて / ～以外」."},note:"Mẫu này luôn dùng để đánh giá tích cực hoặc ca ngợi đối tượng đi trước, tuyệt đối không dùng khi nói về khuyết điểm hay các tình huống tiêu cực."},{pattern:"～きりだ",meaning:"Chỉ ~ thôi / Kể từ khi ~ (không còn)",priority:"common",explanation:'Mẫu 「～きりだ」 dùng sau danh từ mang nghĩa "chỉ duy nhất", hoặc đi sau động từ thể quá khứ (V-た) mang nghĩa "kể từ sau khi làm gì đó thì trạng thái kéo dài suốt và không xảy ra lần nào nữa". Mẫu câu thường diễn tả sự bặt vô âm tín, tiếc nuối, hoặc nhấn mạnh số lượng/số lần vô cùng ít ỏi. Trong văn nói thân mật hàng ngày, cấu trúc này thường được biến âm thành 「～っきりだ」.',examples:[{sentence:"高校時代の親友とは、卒業式の日に会ったきりだ。",translation:"Tôi và người bạn thân thời cấp ba chỉ mới gặp nhau vào ngày lễ tốt nghiệp, kể từ đó đến nay chưa gặp lại lần nào."},{sentence:"彼と直接話をしたのは、採用面接の時の一度きりだ。",translation:"Lần tôi nói chuyện trực tiếp với anh ấy chỉ duy nhất một lần vào lúc phỏng vấn tuyển dụng."}],dialogue:{title:"Hỏi thăm đồng nghiệp cũ",lines:[{speaker:"A",text:"そういえば、先月退職した田中さんから何か連絡はあった？",translation:"Nhắc mới nhớ, cậu có nhận được tin tức gì từ anh Tanaka - người vừa nghỉ việc tháng trước không?"},{speaker:"B",text:"ううん、最終日に挨拶メールをもらったきりだよ。",translation:"Không, kể từ hôm nhận được email chào tạm biệt vào ngày cuối cùng làm việc thì bặt vô âm tín luôn."},{speaker:"A",text:"そうなんだ。新しい職場でも元気に頑張っているといいね。",translation:"Vậy à. Mong là anh ấy vẫn khỏe mạnh và làm tốt ở chỗ làm mới."}]},commonMistake:{wrong:"息子は今朝「遊びに行く」と言って出かけるきりだ。",correct:"息子は今朝「遊びに行く」と言って出かけたきりだ。",why:"Khi diễn tả sự việc đã xảy ra rồi sau đó bặt tăm không có tin tức, động từ trước 「きりだ」 bắt buộc phải chia ở thể quá khứ (V-た) chứ không dùng thể từ điển."},note:"Cần phân biệt 「V-たきりだ」 (kể từ khi làm V thì không xảy ra lần nữa/bặt tăm) với 「V-たままだ」 (giữ nguyên trạng thái để làm việc khác, không mang nghĩa bặt vô âm tín)."},{pattern:"～てでも",meaning:"Dù phải ~ cũng nhất định",priority:"common",explanation:'Mẫu 「～てでも」 được dùng sau động từ thể て để diễn tả quyết tâm hoặc ý chí cực kỳ mạnh mẽ của người nói. Cấu trúc này mang nghĩa "dù phải dùng đến biện pháp cực đoan, bất đắc dĩ hay trả giá đắt thế nào thì cũng nhất định thực hiện". Vế trước thường là những hành vi khác thường, khó khăn hoặc không mong muốn (như vay nợ, quỳ lạy, thức trắng đêm...). Vế sau đi kèm các cách diễn đạt thể hiện ý chí, mong muốn hoặc mệnh lệnh như 「～たい」「～つもりだ」「～てみせる」「～なさい」.',examples:[{sentence:"借金をしてでも、自分の店を持つという長年の夢を諦めきれない。",translation:"Dù có phải vay nợ đi chăng nữa, tôi cũng không thể từ bỏ ước mơ mở một cửa hàng của riêng mình bấy lâu nay."},{sentence:"どんなに頭を下げてでも、この契約だけは必ず成立させなければならない。",translation:"Dù có phải hạ mình cúi đầu van nài thế nào đi nữa, tôi cũng nhất định phải ký được bản hợp đồng này."}],dialogue:{title:"Quyết tâm trước kỳ thi",lines:[{speaker:"A",text:"来週のN1試験、合格できそう？まだかなり不安そうだね。",translation:"Kỳ thi N1 tuần sau cậu thấy thế nào, đỗ nổi không? Trông cậu vẫn còn vẻ lo lắng lắm."},{speaker:"B",text:"うん、でも徹夜をしてでも、この1週間で過去問を全部解き切るつもりだよ。",translation:"Ừ, nhưng dù phải thức trắng đêm đi chăng nữa, tớ cũng quyết tâm làm hết toàn bộ đề thi các năm trong tuần này."},{speaker:"A",text:"その意気なら大丈夫だよ！でも体調だけは崩さないようにね。",translation:"Ý chí thế thì ổn thôi! Nhưng nhớ giữ gìn đừng để đổ bệnh đấy nhé."}]},commonMistake:{wrong:"家を売ってでも、母の病気が治ります。",correct:"家を売ってでも、母の病気を治したい。",why:"Vế sau của 「～てでも」 bắt buộc phải là hành động thể hiện ý chí, nguyện vọng hoặc quyết tâm chủ quan của người nói, không dùng cho sự việc diễn ra tự nhiên hay ngoài tầm kiểm soát."},note:'Khác với 「～ても」 chỉ biểu thị điều kiện nhượng bộ thông thường ("dù... nhưng..."), 「～てでも」 nhấn mạnh vào sự sẵn sàng chấp nhận một biện pháp phi thường/cực đoan để đạt bằng được mục đích.'},{pattern:"～てたまらない",meaning:"Cảm giác ~ đến mức không chịu được",priority:"common",explanation:"Mẫu câu「～てたまらない」diễn tả cảm xúc, mong muốn hoặc cảm giác cơ thể của người nói trào dâng mãnh liệt đến mức không thể kìm nén hay chịu đựng nổi (rất..., ...không chịu được). Cấu trúc thường kết hợp với tính từ chỉ cảm xúc (vui, buồn, lo lắng), cảm giác cơ thể (ngứa, đau, nóng) hoặc dạng mong muốn「～たくてたまらない」. Khi diễn tả cảm xúc của ngôi thứ ba, câu phải đi kèm với các yếu tố phỏng đoán hoặc trích dẫn như「～ようだ」「～らしい」「～そうだ」.",examples:[{sentence:"虫に刺されたところが痒くてたまらないので、早く薬を塗りたい。",translation:"Chỗ bị côn trùng đốt ngứa không chịu nổi nên tôi muốn bôi thuốc ngay lập tức."},{sentence:"面接の結果がなかなか届かないので、合否が気になってたまらない。",translation:"Mãi mà kết quả phỏng vấn chưa gửi về nên tôi bồn chồn lo lắng không chịu được."}],dialogue:{title:"Nỗi nhớ nhà",lines:[{speaker:"A",text:"日本に来て半年経つけど、最近お母さんの手料理が食べたくてたまらないんだ。",translation:"Sang Nhật được nửa năm rồi mà dạo này tớ thèm đồ ăn mẹ nấu không chịu được."},{speaker:"B",text:"わかるよ。私も最初の頃はずっとホームシックだったから。",translation:"Tớ hiểu mà. Hồi mới đầu tớ cũng bị nhớ nhà suốt."},{speaker:"A",text:"今度の連休、思い切って一時帰国しようと思っているんだ。",translation:"Đợt nghỉ lễ tới tớ đang tính quyết tâm về nước chơi một chuyến đây."}]},commonMistake:{wrong:"彼は合格発表を待つ間、不安でたまらない。",correct:"彼は合格発表を待つ間、不安でたまらないようだ。",why:"Vì「～てたまらない」diễn tả trực tiếp cảm giác nội tâm của người nói (ngôi thứ nhất), nên khi áp dụng cho chủ ngữ ngôi thứ ba phải thêm đuôi phỏng đoán hoặc quan sát như「～ようだ」「～そうだ」."},note:"So với「～てならない」(chủ yếu dùng cho cảm xúc trừu tượng tự nhiên trào dâng trong văn phong trang trọng),「～てたまらない」dùng được cho cả cảm giác thể xác (đói, khát, ngứa...) và mang sắc thái bức bách, khó kìm nén hơn trong đời sống hàng ngày."},{pattern:"～ほど～ない",meaning:"Không gì bằng ~ / Không ~ bằng",priority:"common",explanation:"Mẫu câu 「～ほど～ない」 dùng để diễn tả ý nghĩa 'không có gì/ai bằng...', khẳng định đối tượng được đưa ra đạt mức độ cao nhất về một tính chất nào đó. Cấu trúc thường gặp là [Danh từ + ほど + Tính từ/Động từ thể phủ định] hoặc [Danh từ + ほど～はない/いない]. Mẫu này thể hiện sự đánh giá, cảm nhận mang tính chủ quan của người nói chứ không dùng cho các phép so sánh dựa trên số liệu hay sự thật khách quan tuyệt đối.",examples:[{sentence:"仕事で疲れた日には、熱いお風呂に入ることほど気持ちのいいものはない。",translation:"Vào những ngày mệt mỏi vì công việc, không có gì dễ chịu bằng việc ngâm mình trong bồn nước nóng."},{sentence:"彼ほど責任感が強くて頼りになるリーダーは、このチームには他にいない。",translation:"Trong đội này, không có người nhóm trưởng nào có tinh thần trách nhiệm và đáng tin cậy bằng anh ấy."}],dialogue:{title:"Thư giãn ngày nghỉ",lines:[{speaker:"A",text:"休みの日に家で好きな音楽を聴きながらのんびりするほど、幸せな時間はないよね。",translation:"Không có khoảng thời gian nào hạnh phúc bằng việc thảnh thơi nghe bản nhạc yêu thích ở nhà vào ngày nghỉ nhỉ."},{speaker:"B",text:"本当にそうだね。平日の疲れが一気に吹き飛ぶ気がするよ。",translation:"Công nhận đấy. Cảm giác như bao mệt mỏi của ngày thường đều tan biến hết."},{speaker:"A",text:"うん、だから今週末はどこにも出かけずに家で過ごすつもりなんだ。",translation:"Ừ, thế nên cuối tuần này tớ định không đi đâu mà chỉ ở nhà thôi."}]},commonMistake:{wrong:"健康ほど大切なものがある。",correct:"健康ほど大切なものはない。",why:"Mẫu câu này bắt buộc phải đi với vị ngữ ở thể phủ định (ない/いない/はない) để nhấn mạnh mức độ cao nhất 'không có gì bằng', tuyệt đối không dùng thể khẳng định."},note:"Khác với 「一番」 có thể dùng cho số liệu và sự thật đo lường khách quan, 「～ほど～ない」 mang đậm cảm nhận và đánh giá chủ quan của người nói."},{pattern:"～上に",meaning:"Hơn nữa ~ (cộng thêm cùng chiều)",priority:"common",explanation:'Mẫu 「～上に」 mang ý nghĩa "không chỉ... mà còn...", dùng để bổ sung thêm thông tin cùng chiều hướng (tốt cùng tốt, xấu cùng xấu) với sự việc đã nêu ở vế trước. Mẫu này đi kèm với thể thông thường của động từ, tính từ đuôi -i, tính từ đuôi -na (chia thành ～な／である上に) và danh từ (chia thành ～の／である上に). Vế sau diễn tả sự việc làm tăng thêm mức độ thuận lợi hoặc bất lợi, tuyệt đối không dùng để nối hai vế mang tính chất đối lập nhau.',examples:[{sentence:"彼は仕事の手際が良い上に、周囲への気配りもできるので、チームのみんなから信頼されている。",translation:"Anh ấy không những thao tác công việc nhanh gọn mà còn biết chu đáo quan tâm người xung quanh, nên được cả đội tin tưởng."},{sentence:"昨夜は激しい雨が降った上に強い風も吹き荒れ、各地で停電などの被害が出た。",translation:"Đêm qua không những mưa to mà gió mạnh còn thổi giật dữ dội, gây ra thiệt hại như mất điện ở nhiều nơi."}],dialogue:{title:"Tìm phòng trọ",lines:[{speaker:"A",text:"このアパート、駅から徒歩3分と近い上に、家賃も相場より安いんだよ。",translation:"Căn hộ này không những gần ga chỉ 3 phút đi bộ mà tiền thuê còn rẻ hơn so với mặt bằng chung đấy."},{speaker:"B",text:"え、本当？でも、そんなに条件が良いと逆に何か問題があるんじゃない？",translation:"Hả, thật á? Nhưng điều kiện tốt thế thì khéo lại có vấn đề gì bất thường không?"},{speaker:"A",text:"不動産屋に聞いたら、建物が少し古いだけで防音もセキュリティも万全らしいよ。",translation:"Tớ hỏi bên môi giới rồi, chỉ là tòa nhà hơi cũ một chút thôi chứ cách âm và an ninh đều hoàn hảo cả."}]},commonMistake:{wrong:"このレストランは料理が美味しい上に、値段が高すぎる。",correct:"このレストランは料理が美味しい上に、サービスも素晴らしい。",why:"「～上に」 chỉ dùng để bổ sung các vế cùng chiều đánh giá (cùng tốt hoặc cùng xấu), không dùng để liên kết hai vế đối lập mang tính tương phản."},note:"Vế sau của 「～上に」 dùng để nêu sự thật hoặc tình trạng tiếp diễn, không đi kèm các câu biểu thị ý chí, yêu cầu hay mệnh lệnh như 「～てください」「～よう」."}],145:[{pattern:"～といっても",meaning:"Tuy nói là ~ nhưng thực ra",priority:"core",explanation:"Mẫu câu này dùng để đính chính hoặc bổ sung thông tin, mang ý nghĩa: tuy sự thật đúng là như vế trước nêu ra, nhưng thực tế mức độ không cao hoặc không ghê gớm như người nghe tưởng tượng. Vế sau thường đưa ra hiện thực khiêm tốn hơn, có giới hạn hoặc làm giảm bớt mức độ kỳ vọng so với vế trước. Cấu trúc này thường xuất hiện nhiều trong cả văn nói lẫn văn viết khi người nói muốn giải thích rõ thực chất sự việc.",examples:[{sentence:"今年の夏はボーナスが出たといっても、たったの3万円だけでした。",translation:"Tuy nói là mùa hè năm nay có tiền thưởng, nhưng thực ra chỉ vỏn vẹn có 3 vạn yên."},{sentence:"家から駅まで近いといっても、実際に歩けば15分はかかります。",translation:"Dù nói là từ nhà đến ga gần, nhưng đi bộ thực tế cũng mất tầm 15 phút."}],dialogue:{title:"Chuyện học nấu ăn",lines:[{speaker:"A",text:"田中さん、最近料理教室に通い始めたんだって？すごいね！",translation:"Tanaka này, nghe nói dạo này cậu bắt đầu đi học lớp nấu ăn hả? Giỏi thế!"},{speaker:"B",text:"うん、通っているといっても、まだ野菜の切り方を習っている程度だよ。",translation:"Ừ, tuy nói là đi học nhưng thực ra cũng mới ở mức đang học cách cắt tỉa rau củ thôi."},{speaker:"A",text:"そうなんだ。でも基礎からしっかり学べるのはいいね。",translation:"Ra là vậy. Nhưng được học bài bản từ căn bản cũng tốt mà."}]},commonMistake:{wrong:"彼はプロの料理人といっても、どんな高級料理でも完璧に作れる。",correct:"彼はプロの料理人といっても、まだ見習いなので簡単な料理しか作れない。",why:"Mẫu 「～といっても」 dùng để hạ thấp mức độ hoặc giới hạn lại kỳ vọng thực tế, do đó vế sau không được dùng để ca ngợi hay khẳng định một kết quả vượt trội, hoàn hảo."},note:"Khác với 「～とはいえ」 mang sắc thái văn viết trang trọng, 「～といっても」 rất phổ biến trong hội thoại thường ngày để đính chính nhằm tránh gây hiểu lầm hoặc để thể hiện sự khiêm tốn."},{pattern:"～にせよ",meaning:"Dù là ~ đi nữa",priority:"common",explanation:'Mẫu câu 「～にせよ」 dùng để diễn đạt ý nghĩa "cho dù là... / dẫu cho là...", thừa nhận một sự thật hay giả định ở vế trước nhưng khẳng định điều đó không làm thay đổi sự việc ở vế sau. Mẫu này mang sắc thái trang trọng, thuộc văn phong nghị luận hoặc phát biểu nghiêm túc, dùng khi người nói muốn bày tỏ quan điểm, lập luận rõ ràng. Vế sau thường đi kèm với những cách diễn đạt thể hiện phán đoán, nghĩa vụ hoặc lời khuyên mang tính nguyên tắc như 「～べきだ」「～なければならない」「～はいけない」.',examples:[{sentence:"どんなに時間が足りないにせよ、提出前の最終確認を怠ってはならない。",translation:"Cho dù có thiếu thời gian đến mức nào đi nữa, cũng tuyệt đối không được lơ là việc kiểm tra lần cuối trước khi nộp."},{sentence:"冗談であったにせよ、他人の容姿をからかうような発言は許されない。",translation:"Dù có là nói đùa đi chăng nữa, những phát ngôn trêu chọc ngoại hình của người khác là không thể tha thứ."}],dialogue:{title:"Nhắc nhở về hạn nộp",lines:[{speaker:"A",text:"田中さん、昨日の会議の議事録はまだですか。締め切りは今朝までだったはずですが。",translation:"Anh Tanaka, biên bản cuộc họp hôm qua vẫn chưa có sao? Hạn chót đáng lẽ là sáng nay rồi mà."},{speaker:"B",text:"すみません、急な来客の対応に追われてしまって、まだまとめきれていません。",translation:"Tôi xin lỗi, do bận xử lý việc tiếp khách đột xuất nên tôi vẫn chưa tổng hợp xong."},{speaker:"A",text:"突発的な業務があったにせよ、遅れるなら事前に連絡を入れるべきですよ。",translation:"Dù là có công việc đột xuất phát sinh đi nữa, nếu trễ thì anh cũng nên liên lạc báo trước chứ."}]},commonMistake:{wrong:"理由が何だにせよ、無断で会社を休むのはよくない。",correct:"理由が何であるにせよ、無断で会社を休むのはよくない。",why:"Khi đi kèm danh từ hoặc tính từ đuôi な, ta kết hợp trực tiếp hoặc thông qua 「である」 chứ không dùng dạng 「だにせよ」."},note:"「～にせよ」 đồng nghĩa với 「～にしても」「～にしろ」 nhưng mang sắc thái văn viết trang trọng nhất, trong khi 「～にしろ」 thường thiên về khẩu ngữ thân mật hơn."},{pattern:"～ないでもない",meaning:"Không hẳn là không ~ (thừa nhận yếu)",priority:"common",explanation:'Mẫu câu này mang ý nghĩa "không hẳn là không..." hoặc "nếu có điều kiện thì cũng có thể...", biểu thị sự khẳng định một cách yếu ớt, dè dặt. Người nói sử dụng dạng phủ định kép nhằm tránh khẳng định dứt khoát hoặc thể hiện thái độ miễn cưỡng, ngập ngừng, không hoàn toàn tự tin. Thường đi kèm với các mẫu câu giả định như 「～ば」「～なら」「～たら」 để diễn tả khả năng có thể làm được trong một hoàn cảnh cụ thể.',examples:[{sentence:"条件次第では、このプロジェクトのリーダーを引き受けないでもない。",translation:"Tùy thuộc vào điều kiện, không hẳn là tôi không thể nhận làm trưởng dự án này."},{sentence:"彼の言いたいことも分からないでもないが、今回のやり方はあまりに強引すぎる。",translation:"Không hẳn là tôi không hiểu điều anh ấy muốn nói, nhưng cách làm lần này quá mức gượng ép."}],dialogue:{title:"Rủ đi ăn mì cay",lines:[{speaker:"A",text:"今日、仕事の後に新しくできた激辛ラーメン屋に行かない？",translation:"Hôm nay sau giờ làm đi ăn thử quán mì ramen siêu cay mới mở không?"},{speaker:"B",text:"辛いのはあまり得意じゃないけど、みんなが行くなら行かないでもないよ。",translation:"Mình không giỏi ăn cay lắm, nhưng nếu mọi người đều đi thì không hẳn là mình không đi đâu."},{speaker:"A",text:"本当？じゃあ席を予約しておくね！",translation:"Thật hả? Vậy để mình đặt chỗ trước nhé!"}]},commonMistake:{wrong:"明日のパーティーにはぜひ参加したいので、行かないでもないです。",correct:"明日のパーティーにはぜひ参加したいので、必ず行きます。",why:"「～ないでもない」mang sắc thái miễn cưỡng, ngập ngừng hoặc khẳng định yếu, không được dùng khi muốn thể hiện ý chí chủ động, hào hứng hay quyết tâm (như đi kèm với「ぜひ」)."},note:"Mẫu này gần nghĩa với「～ないこともない」, nhưng「～ないでもない」thường mang sắc thái văn phong trang trọng hơn và nhấn mạnh hơn vào sự do dự, e dè của người nói."},{pattern:"～ないまでも",meaning:"Dù không ~ thì ít ra",priority:"common",explanation:"Mẫu câu này dùng để diễn đạt ý 'dù không đạt đến mức độ lý tưởng hoặc cao nhất là A, nhưng ít nhất/ít ra cũng đạt được mức độ B chấp nhận được'. Thường kết hợp với thể phủ định của động từ (V-ないまでも), hoặc các cụm cố định như「〜とはいかないまでも」「〜とは言わないまでも」. Vế sau biểu thị một kết quả, kỳ vọng hoặc hiện thực ở mức tối thiểu, thường đi kèm các phó từ như「せめて」「少なくとも」「少しは」.",examples:[{sentence:"満点は取れないまでも、せめて合格ラインの70点は超えたい。",translation:"Dù không đạt điểm tuyệt đối thì ít ra tôi cũng muốn vượt qua mức điểm đỗ là 70 điểm."},{sentence:"毎日運動するとはいかないまでも、週に2、3回は散歩するようにしている。",translation:"Dù chưa đến mức ngày nào cũng tập thể dục thì ít nhất tôi cũng cố gắng đi dạo 2 đến 3 lần một tuần."}],dialogue:{title:"Mục tiêu thi chạy marathon",lines:[{speaker:"A",text:"来月のマラソン大会、今の練習量だと優勝はちょっと厳しそうですね。",translation:"Giải marathon tháng tới, với lượng luyện tập hiện tại thì vô địch e là hơi khó nhỉ."},{speaker:"B",text:"そうですね。でも、優勝できないまでも、せめて途中で諦めずに完走したいです。",translation:"Đúng vậy. Nhưng dù không vô địch được thì ít ra tôi cũng muốn chạy hết chặng đua chứ không bỏ cuộc giữa chừng."},{speaker:"A",text:"素晴らしい目標です！最後まで無理せず頑張りましょう。",translation:"Mục tiêu tuyệt vời lắm! Hãy cùng cố gắng hết sức mà không quá sức nhé."}]},commonMistake:{wrong:"毎日ジョギングをするまでも、せめて週に1回は体を動かしたい。",correct:"毎日ジョギングをしないまでも、せめて週に1回は体を動かしたい。",why:"Mẫu câu này bắt buộc phải chia động từ ở thể phủ định (V-ない + までも) để diễn đạt ý nhượng bộ 'dù không đến mức...', không gắn trực tiếp vào thể từ điển."},note:"Cần phân biệt với mẫu「〜までもない」(không cần thiết phải làm đến mức...), còn「〜ないまでも」mang nghĩa nhượng bộ đi kèm phó từ「せめて」「少なくとも」ở vế sau."},{pattern:"～以上は",meaning:"Một khi đã ~ thì phải",priority:"common",explanation:'Mẫu 「～以上は」 mang ý nghĩa "Một khi đã... thì (đương nhiên/phải)...", dùng để diễn tả một sự việc đã trở thành hiện thực hoặc đã được quyết định. Đi sau thể thông thường của động từ, tính từ hoặc danh từ (thường ở dạng である), vế sau bắt buộc phải thể hiện nghĩa vụ, trách nhiệm, quyết tâm, lời khuyên hoặc yêu cầu (như ～べきだ, ～なければならない, ～つもりだ). Cấu trúc này mang sắc thái trang trọng, nhấn mạnh tinh thần trách nhiệm và tính tất yếu mang tính đạo lý hoặc logic.',examples:[{sentence:"一度このプロジェクトのリーダーを引き受けた以上は、最後まで責任を持ってやり遂げるべきだ。",translation:"Một khi đã nhận làm trưởng dự án này thì phải có trách nhiệm thực hiện đến cùng."},{sentence:"JLPT N1の合格を目指すと決めた以上は、毎日計画的に勉強しなければならない。",translation:"Một khi đã quyết định hướng tới mục tiêu đỗ N1 thì mỗi ngày đều phải học tập có kế hoạch."}],dialogue:{title:"Quyết tâm trước giải đấu",lines:[{speaker:"A",text:"大会に出場する以上は、絶対に優勝を目指して全力で戦いたいですね。",translation:"Một khi đã tham gia đại hội thì tôi muốn thi đấu hết mình để quyết tâm giành chức vô địch."},{speaker:"B",text:"そうですね。そのためにも、日々の練習を怠らないようにしましょう。",translation:"Đúng vậy. Để đạt được điều đó thì chúng ta đừng lơ là việc luyện tập hằng ngày nhé."},{speaker:"A",text:"はい！チーム全員で力を合わせて頑張りましょう。",translation:"Vâng! Toàn đội hãy cùng chung sức nỗ lực nào."}]},commonMistake:{wrong:"留学を決めた以上は、英語が上手に話せるようになりました。",correct:"留学を決めた以上は、英語が上手に話せるように努力するべきだ。",why:"Vế sau của 「～以上は」 không dùng để diễn tả kết quả thực tế khách quan hay sự việc đã xảy ra, mà bắt buộc phải là biểu hiện thể hiện ý chí, quyết tâm, nghĩa vụ hoặc lời khuyên (như ～べきだ、～つもりだ)."},note:"「～以上は」 có nghĩa tương tự 「～からには」 và 「～上は」, nhưng thường mang tính trang trọng hơn và nhấn mạnh mạnh mẽ vào bổn phận, trách nhiệm gắn liền với tiền đề ở vế trước."},{pattern:"～ことなしに",meaning:"Không ~ thì không thể",priority:"common",explanation:'Mẫu「～ことなしに（は）」mang ý nghĩa "nếu không làm V thì không thể...", biểu thị một điều kiện bắt buộc, tiên quyết cần phải có để thực hiện hành động hoặc đạt được kết quả ở vế sau. Vế sau của câu hầu như luôn đi kèm với các biểu hiện phủ định hoặc biểu thị sự bất khả kháng như できない, 無理だ, あり得ない. Cấu trúc này mang sắc thái trang trọng, thường xuất hiện trong văn viết, văn nghị luận, diễn văn hoặc các tình huống giao tiếp công việc trang nghiêm.',examples:[{sentence:"過去の失敗から学ぶことなしに、企業の持続的な成長はあり得ない。",translation:"Nếu không học hỏi từ những thất bại trong quá khứ thì doanh nghiệp không thể có được sự tăng trưởng bền vững."},{sentence:"十分な臨床試験を行うことなしに、新しい薬を承認することはできない。",translation:"Không thể cấp phép cho loại thuốc mới nếu không tiến hành đầy đủ các thử nghiệm lâm sàng."}],dialogue:{title:"Đàm phán dự án",lines:[{speaker:"A",text:"相手企業の合意を得ることなしに、このプロジェクトを進めるのは危険すぎます。",translation:"Nếu không nhận được sự đồng thuận của công ty đối tác thì việc tiến hành dự án này là quá nguy hiểm."},{speaker:"B",text:"そうですね。まずは向こうの担当者と直接会って、条件を再確認しましょう。",translation:"Đúng vậy. Trước hết hãy gặp trực tiếp người phụ trách bên đó để xác nhận lại các điều kiện nhé."},{speaker:"A",text:"分かりました。すぐにアポイントを取り、来週中には話し合いの場を設けます。",translation:"Tôi hiểu rồi. Tôi sẽ liên hệ lấy hẹn ngay và sắp xếp một buổi thảo luận trong tuần tới."}]},commonMistake:{wrong:"先生の許可ことなしに、実験室を使ってはいけません。",correct:"先生の許可を得ることなしに、実験室を使ってはいけません。",why:"「～ことなしに」bắt buộc phải kết hợp với động từ thể từ điển (V-る); không ghép trực tiếp với danh từ (nếu đi với danh từ thì phải đổi thành「N + なしに」hoặc thêm động từ thích hợp như「許可を得ることなしに」)."},note:"Khi muốn nhấn mạnh tính tất yếu của điều kiện phủ định, ta có thể thêm trợ từ「は」thành「～ことなしには」; cấu trúc này gần nghĩa với「～ないで／～ずに」nhưng mang tính văn viết trang trọng và nhấn mạnh quan hệ điều kiện mạnh mẽ hơn."},{pattern:"～というわけだ",meaning:"Tức là ~ (kết luận logic)",priority:"common",explanation:"Mẫu câu này dùng để đưa ra kết luận mang tính logic hoặc giải thích nguồn cơn, lý do tất yếu của một sự việc dựa trên tiền đề, thông tin đã biết trước đó. Nó thường mang sắc thái 'hóa ra là thế', 'thảo nào mà' khi người nói vỡ lẽ ra điều gì, hoặc mang nghĩa 'tức là/nói cách khác là'. Cấu trúc này thường kết hợp với thể thông thường đứng trước và rất phổ biến trong cả hội thoại hàng ngày lẫn văn giải thích.",examples:[{sentence:"定価が1万円で30％引きだから、7000円で買えるというわけだ。",translation:"Giá niêm yết là 10.000 yên và được giảm 30%, tức là có thể mua với giá 7.000 yên."},{sentence:"彼は日本に10年以上住んでいるのか。だから日本語がペラペラというわけだね。",translation:"Anh ấy đã sống ở Nhật hơn 10 năm rồi cơ à. Thảo nào mà tiếng Nhật lại trôi chảy như vậy."}],dialogue:{title:"Hóa đơn tiền điện",lines:[{speaker:"A",text:"今月の電気代、いつもの倍近く請求が来ているよ。",translation:"Hóa đơn tiền điện tháng này bị tính gần gấp đôi bình thường đấy."},{speaker:"B",text:"先月はずっと猛暑で、24時間エアコンをつけっぱなしにしていたからね。",translation:"Tháng trước nắng nóng gay gắt suốt, lại bật điều hòa liên tục 24/24 mà."},{speaker:"A",text:"なるほど、それでこんなに高くなったというわけだ。",translation:"Ra là vậy, thảo nào mà tiền điện lại đắt đến thế này."}]},commonMistake:{wrong:"道が混んでいるから、電車で行くというわけだ。",correct:"道が混んでいるから、電車で行くことにする。",why:"「～というわけだ」 chỉ dùng để rút ra kết luận logic từ thực tế hoặc giải thích lý do, không dùng để diễn tả quyết định hay ý chí chủ quan của bản thân."},note:"Cần tránh nhầm lẫn mẫu này với 「～わけではない」(không hẳn là - phủ định một phần) hoặc 「～わけがない」(tuyệt đối không thể có chuyện - phủ định mạnh mẽ)."},{pattern:"～につき",meaning:"Vì ~ / Mỗi ~ (lý do lịch sự, đơn vị)",priority:"common",explanation:"「～につき」thường đi trực tiếp sau danh từ để nêu lý do một cách trang trọng, ngắn gọn trong các văn bản thông báo, bảng hiệu công cộng hoặc thư từ thương mại. Bên cạnh đó, mẫu này còn kết hợp với số từ để chỉ tỷ lệ hoặc đơn vị chuẩn (mỗi/cứ mỗi...). Cần lưu ý không dùng mẫu này để trình bày lý do mang tính cảm xúc cá nhân trong giao tiếp thân mật hàng ngày.",examples:[{sentence:"本日は悪天候につき、屋外イベントを中止とさせていただきます。",translation:"Hôm nay do thời tiết xấu, chúng tôi xin phép hủy sự kiện ngoài trời."},{sentence:"こちらの限定グッズのご購入は、お一人様につき2点までと限らせていただきます。",translation:"Đối với hàng giới hạn này, mỗi khách hàng chỉ được mua tối đa 2 món."}],dialogue:{title:"Hỏi mua vé sự kiện",lines:[{speaker:"A",text:"すみません、この記念入場券は1人何枚まで購入できますか。",translation:"Xin lỗi, vé vào cổng kỷ niệm này một người được mua tối đa mấy vé ạ?"},{speaker:"B",text:"好評につき残りわずかとなっておりますので、1名様につき1枚とさせていただいております。",translation:"Vì được đón nhận nồng nhiệt nên số lượng còn rất ít, do đó mỗi quý khách chỉ được mua 1 vé ạ."},{speaker:"A",text:"分かりました。では1枚購入します。",translation:"Tôi hiểu rồi. Vậy cho tôi mua 1 vé nhé."}]},commonMistake:{wrong:"熱があるにつき、今日の飲み会は休ませてください。",correct:"熱がありますので、今日の飲み会は休ませてください。",why:"「～につき」mang sắc thái thông báo trang trọng trên biển báo hoặc công văn, không dùng để giải thích lý do cá nhân trong giao tiếp hàng ngày."},note:"Khi dùng với nghĩa chỉ lý do,「～につき」chỉ đi trực tiếp với danh từ (như 工事中につき, 祭日につき) chứ không nối trực tiếp sau thể thông thường của động từ hay tính từ như「～から / ～ので」."}],146:[{pattern:"～に反して",meaning:"Trái với ~ / Ngược với kỳ vọng ~",priority:"core",explanation:"Mẫu ngữ pháp này mang ý nghĩa 'trái ngược với...' hoặc 'đi ngược lại với...', được dùng khi một kết quả hay sự việc diễn ra hoàn toàn trái với dự đoán, kỳ vọng ban đầu hoặc vi phạm quy định, luật lệ. Cấu trúc kết hợp trực tiếp sau Danh từ tạo thành 「N + に反して」, hoặc bổ nghĩa cho danh từ phía sau dưới dạng 「N + に反する / に反した + N」. Mẫu câu mang sắc thái trang trọng, khách quan, thường xuất hiện nhiều trong văn viết, thời sự, báo chí và các báo cáo phân tích.",examples:[{sentence:"専門家の予想に反して、今年の新商品の売り上げは大幅に伸びた。",translation:"Trái với dự đoán của các chuyên gia, doanh số của dòng sản phẩm mới năm nay đã tăng trưởng vượt bậc."},{sentence:"親の期待に反して、彼は大学へ進学せずに料理人の道を選んだ。",translation:"Trái với kỳ vọng của cha mẹ, anh ấy đã không học lên đại học mà lựa chọn con đường trở thành đầu bếp."}],dialogue:{title:"Kết quả trận đấu",lines:[{speaker:"A",text:"昨日の試合、周囲の予想に反してうちのチームが逆転勝利したね！",translation:"Trận đấu hôm qua, trái với dự đoán của mọi người, đội mình đã lội ngược dòng giành chiến thắng nhỉ!"},{speaker:"B",text:"本当に驚いたよ。相手は前年王者だったから、正直諦めかけていたんだ。",translation:"Thật sự bất ngờ luôn đấy. Vì đối thủ là nhà vô địch năm ngoái nên thành thật mà nói tớ đã suýt bỏ cuộc."},{speaker:"A",text:"最後まで諦めずに戦い抜いた選手たちの粘り勝ちだね。",translation:"Đúng là chiến thắng nhờ sự kiên cường của các cầu thủ đã nỗ lực chiến đấu đến cùng."}]},commonMistake:{wrong:"周囲の期待に対して、試験に落ちてしまった。",correct:"周囲の期待に反して、試験に落ちてしまった。",why:"「～に対して」 dùng để chỉ thái độ đối với đối tượng hoặc so sánh hai sự vật tương phản, còn khi diễn tả kết quả thực tế đi ngược lại kỳ vọng, dự tính ban đầu thì phải dùng 「～に反して」."},note:"Khi bổ nghĩa cho danh từ đi sau, mẫu câu chuyển thành dạng 「〜に反する＋N」 hoặc 「〜に反した＋N」; ngoài nghĩa trái với dự tính thì khi đi cùng các danh từ như 規則, 法律, 意志 nó còn mang nghĩa là 'vi phạm, làm trái'."},{pattern:"～にかかわらず",meaning:"Bất kể ~ / Không phân biệt ~",priority:"common",explanation:"Mẫu câu này có nghĩa là 「Bất kể... / Không phân biệt...」, biểu thị rằng sự việc ở vế sau luôn diễn ra hoặc được áp dụng đồng đều mà không bị chi phối hay ảnh hưởng bởi điều kiện ở vế trước. Thường đi cùng với các danh từ chỉ phạm vi, sự đối lập (tuổi tác, giới tính, thời tiết...) hoặc các cặp từ đối lập như 「Vる・Vない」「有無」「よしあし」. Mẫu mang sắc thái trang trọng, khách quan, thường được sử dụng phổ biến trong các thông báo, quy chế, văn bản quy định hoặc môi trường công việc.",examples:[{sentence:"このマラソン大会は、年齢や性別にかかわらず、健康な方ならどなたでも参加できます。",translation:"Giải chạy marathon này bất kỳ ai có sức khỏe tốt đều có thể tham gia, bất kể tuổi tác hay giới tính."},{sentence:"理由のいかんにかかわらず、提出期限を過ぎた申請書類は受理いたしかねます。",translation:"Bất kể lý do là gì, chúng tôi cũng không thể tiếp nhận hồ sơ xin nộp muộn sau thời hạn quy định."}],dialogue:{title:"Tiêu chí tuyển dụng mới",lines:[{speaker:"A",text:"来期の採用ですが、やはり業界での実務経験を必須条件にしますか。",translation:"Về đợt tuyển dụng kỳ tới, chúng ta có nên đặt kinh nghiệm thực tế trong ngành làm điều kiện bắt buộc không ạ?"},{speaker:"B",text:"いや、今回は経験の有無にかかわらず、熱意のある人材を幅広く募集しよう。",translation:"Không, lần này chúng ta hãy tuyển dụng rộng rãi những nhân sự có nhiệt huyết, bất kể có kinh nghiệm hay không."},{speaker:"A",text:"承知いたしました。では、学歴や国籍にかかわらず挑戦できる旨を募集要項に記載しておきます。",translation:"Tôi hiểu rồi ạ. Vậy tôi sẽ ghi rõ vào bản tin tuyển dụng rằng ứng viên có thể ứng tuyển bất kể học vấn hay quốc tịch."}]},commonMistake:{wrong:"昨日は大雨にかかわらず、多くのファンがスタジアムに集まった。",correct:"昨日は大雨にもかかわらず、多くのファンがスタジアムに集まった。",why:"Học viên hay nhầm 「～にかかわらず」 (bất kể / không phân biệt - đưa ra tiêu chí bao quát) với 「～にもかかわらず」 (mặc dù / thế nhưng - diễn tả kết quả thực tế xảy ra trái ngược với dự đoán thông thường)."},note:"Khác với mẫu gần nghĩa 「～を問わず」 chỉ kết hợp trực tiếp với danh từ, 「～にかかわらず」 linh hoạt hơn vì có thể đi được với cả cụm động từ/tính từ đối lập (như 「参加するしないにかかわらず」「好き嫌いにかかわらず」)."},{pattern:"～にもかかわらず",meaning:"Mặc dù ~ / Bất chấp ~",priority:"common",explanation:'Mẫu 「～にもかかわらず」 mang ý nghĩa "mặc dù / bất chấp sự thật là...", dùng để diễn tả một kết quả thực tế xảy ra trái ngược hoặc bất ngờ so với những gì được suy đoán từ vế trước. Mẫu câu thường đi sau thể thông thường (V/A-i), riêng danh từ và tính từ đuôi な có thể nối trực tiếp hoặc đi kèm 「である」. Cấu trúc này mang sắc thái trang trọng, khách quan hơn 「～のに」, hay xuất hiện trong văn viết, báo chí hoặc các bài phát biểu, và vế sau tuyệt đối không dùng các cách diễn đạt thể hiện ý chí, mệnh lệnh hay nhờ vả.',examples:[{sentence:"大雨が降っているにもかかわらず、多くのサポーターがスタジアムに駆けつけた。",translation:"Mặc dù trời đang mưa to, rất đông người hâm mộ vẫn đổ xô đến sân vận động."},{sentence:"彼は激しい痛みを抱えているにもかかわらず、最後まで笑顔でプレゼンをやり遂げた。",translation:"Bất chấp việc đang phải chịu đựng cơn đau dữ dội, anh ấy vẫn tươi cười hoàn thành bài thuyết trình đến cùng."}],dialogue:{title:"Đánh giá nhân viên mới",lines:[{speaker:"A",text:"田中さんは入社したばかりであるにもかかわらず、もう大きなプロジェクトを任されているそうですよ。",translation:"Nghe nói anh Tanaka mặc dù mới vào công ty nhưng đã được giao phụ trách hẳn một dự án lớn rồi đấy."},{speaker:"B",text:"ええ、ベテラン顔負けの成果を出していますからね。納得の抜擢ですよ。",translation:"Vâng, vì anh ấy mang lại thành quả chẳng kém gì người kỳ cựu cả. Được cất nhắc như vậy cũng dễ hiểu thôi."},{speaker:"A",text:"本当に頼もしいですね。私たちも刺激を受けます。",translation:"Quả thực rất đáng tin cậy. Chúng ta cũng có thêm động lực phấn đấu nhỉ."}]},commonMistake:{wrong:"雨が降っているにもかかわらず、一緒に買い物に行きましょう。",correct:"雨が降っているけれど、一緒に買い物に行きましょう。",why:"Vế sau của 「～にもかかわらず」 phải là sự việc thực tế, không được đi với câu rủ rê, mệnh lệnh hay ý chí của người nói như 「～ましょう」 hay 「～てください」."},note:'Cần phân biệt với 「～にかかわらず」 mang nghĩa "bất kể / không phân biệt tiêu chuẩn, điều kiện nào" (ví dụ: 年齢にかかわらず - bất kể tuổi tác), thay vì chỉ sự tương phản thực tế giữa hai vế.'},{pattern:"～ながらも",meaning:"Tuy ~ nhưng / Dù ~ mà vẫn",priority:"common",explanation:'Mẫu ngữ pháp 「～ながらも」 mang ý nghĩa "tuy... nhưng / mặc dù... nhưng vẫn", dùng để diễn tả sự đối lập giữa hai vế câu. Vế trước nêu lên một trạng thái, hoàn cảnh, cảm xúc hay tính chất, còn vế sau là một kết quả, hành động hoặc thực tế trái ngược với điều thông thường người ta suy đoán từ vế trước. Mẫu này thường đi với động từ thể ます (bỏ ます), tính từ đuôi い, tính từ đuôi な, và danh từ (có thể kèm である). Sắc thái của câu thường nhấn mạnh sự nỗ lực, bất ngờ hoặc sự mâu thuẫn nội tâm, và hai vế thường có cùng một chủ ngữ.',examples:[{sentence:"祖父は高齢でありながらも、毎朝欠かさずジョギングをして健康を維持している。",translation:"Ông tôi tuy đã cao tuổi nhưng mỗi sáng vẫn duy trì chạy bộ đều đặn để giữ gìn sức khỏe."},{sentence:"失敗の原因は自分にあると分かっていながらも、プライドが邪魔をして素直に謝れなかった。",translation:"Dù biết rõ nguyên nhân thất bại là do bản thân, nhưng vì lòng tự ái cản trở nên tôi đã không thể thành thật xin lỗi."}],dialogue:{title:"Đánh giá nhân viên mới",lines:[{speaker:"A",text:"田中さんは新入社員ながらも、難しい大型案件を見事に成功させましたね。",translation:"Tanaka tuy là nhân viên mới nhưng đã xuất sắc hoàn thành dự án lớn đầy khó khăn nhỉ."},{speaker:"B",text:"ええ、最初はプレッシャーを感じていたようですが、弱音を吐かずに最後までやり切ってくれました。",translation:"Vâng, ban đầu có vẻ cậu ấy chịu nhiều áp lực, nhưng không hề than vãn mà đã kiên trì làm đến cùng."},{speaker:"A",text:"彼の今後の成長がますます楽しみですね。私たちにとっても良い刺激になります。",translation:"Càng ngày càng mong chờ sự phát triển sau này của cậu ấy. Đây cũng là nguồn động lực lớn cho chúng ta."}]},commonMistake:{wrong:"彼女は足を怪我したながらも、最後まで諦めずに走り抜いた。",correct:"彼女は足を怪我していながらも、最後まで諦めずに走り抜いた。",why:"Khi kết hợp với động từ, 「ながらも」 phải đi với động từ thể ます (bỏ ます) hoặc dạng trạng thái 「～ていながらも」, tuyệt đối không kết nối trực tiếp với thể quá khứ 「～た」."},note:"Cần phân biệt rõ 「～ながらも」 (nhấn mạnh sự tương phản: tuy... nhưng) với cấu trúc 「V-ます + ながら」 cơ bản (diễn tả hai hành động diễn ra song song: vừa... vừa...)."},{pattern:"～を機に",meaning:"Nhân dịp ~ / Lấy ~ làm cơ hội",priority:"common",explanation:'Mẫu 「～を機に」 mang ý nghĩa "nhân cơ hội / lấy mốc sự kiện này làm bước ngoặt để bắt đầu một hành động hoặc thay đổi mới". Cấu trúc này thường đi kèm với các danh từ chỉ sự kiện quan trọng mang tính bước ngoặt của đời người hoặc tổ chức (như kết hôn, nghỉ hưu, chuyển nhà, thành lập chi nhánh...). So với cách nói thông thường, mẫu câu này mang sắc thái trang trọng, văn viết và nhấn mạnh vào tính thời cơ, sự chủ động tạo ra chuyển biến tích cực ở vế sau.',examples:[{sentence:"定年退職を機に、毎朝のウォーキングと野菜中心の食生活を始めました。",translation:"Nhân dịp nghỉ hưu, tôi đã bắt đầu đi bộ mỗi sáng và duy trì chế độ ăn uống nhiều rau củ."},{sentence:"海外支社の設立を機に、社内の公用語を英語に切り替えることになった。",translation:"Nhân cơ hội thành lập chi nhánh ở nước ngoài, công ty đã quyết định chuyển đổi ngôn ngữ sử dụng nội bộ sang tiếng Anh."}],dialogue:{title:"Quyết định bỏ thuốc lá",lines:[{speaker:"A",text:"田中さん、最近タバコを吸っているところを全然見かけませんね。",translation:"Anh Tanaka dạo này tôi không thấy anh hút thuốc lá nữa nhỉ."},{speaker:"B",text:"ええ、子供が生まれたのを機に、きっぱりやめることにしたんです。",translation:"Vâng, nhân dịp con chào đời, tôi đã quyết định dứt khoát từ bỏ thuốc lá đấy."},{speaker:"A",text:"それは素晴らしい決断ですね！ご家族もきっと喜んでいるでしょう。",translation:"Đó thật là một quyết định tuyệt vời! Chắc hẳn gia đình anh mừng lắm."}]},commonMistake:{wrong:"東京へ出張に行ったのを機に、大学時代の友人に会ってきた。",correct:"東京へ出張に行ったついでに、大学時代の友人に会ってきた。",why:"「～を機に」 chỉ dùng cho sự kiện mang tính bước ngoặt tạo ra khởi đầu hoặc sự thay đổi lâu dài, không dùng cho hành động tranh thủ làm việc gì tiện thể như 「～ついでに」."},note:"So với 「～をきっかけに」 (có thể dùng cho cả sự việc ngẫu nhiên hoặc dẫn đến kết quả tiêu cực), 「～を機に」 mang tính chủ động nắm bắt thời cơ và thường hướng đến kết quả tích cực, có tính định hướng hơn."},{pattern:"～にあたって",meaning:"Vào dịp / Khi thực hiện ~",priority:"common",explanation:'Mẫu 「～にあたって」 mang ý nghĩa "nhân dịp / vào thời điểm / khi tiến hành", diễn tả thời điểm bắt đầu một sự kiện, kế hoạch hay bước ngoặt quan trọng. Cấu trúc này thường kết hợp với Động từ thể từ điển (V-る) hoặc Danh từ chỉ hành vi (N). Đây là cách diễn đạt mang sắc thái trang trọng, tích cực, thường được dùng trong các bài phát biểu, văn bản thông báo hoặc giao tiếp trang trọng trong công việc.',examples:[{sentence:"新工場の設立にあたって、安全管理の徹底と環境への配慮を最優先事項といたしました。",translation:"Nhân dịp thành lập nhà máy mới, chúng tôi đã đặt việc quản lý an toàn tuyệt đối và bảo vệ môi trường lên làm ưu tiên hàng đầu."},{sentence:"新サービスの開始にあたって、利用規約をよくご確認くださいますようお願いいたします。",translation:"Khi triển khai dịch vụ mới, xin quý khách vui lòng kiểm tra kỹ các điều khoản sử dụng."}],dialogue:{title:"Chuẩn bị mở quán",lines:[{speaker:"A",text:"来月カフェを開店するにあたって、何かアドバイスをいただけますか。",translation:"Nhân dịp chuẩn bị mở quán cà phê vào tháng tới, anh có thể cho tôi xin vài lời khuyên được không?"},{speaker:"B",text:"まずは近隣の競合店をしっかりリサーチすることが大切ですよ。",translation:"Trước hết, việc nghiên cứu kỹ các cửa hàng đối thủ xung quanh là rất quan trọng đấy."},{speaker:"A",text:"ありがとうございます。早速周辺の店舗を回ってみます。",translation:"Cảm ơn anh. Tôi sẽ đi khảo sát các cửa hàng lân cận ngay."}]},commonMistake:{wrong:"毎朝、歯を磨くにあたって、鏡を見ます。",correct:"毎朝、歯を磨くとき、鏡を見ます。",why:"「～にあたって」chỉ dùng cho những dịp, sự kiện đặc biệt hoặc mang tính cột mốc quan trọng, không dùng cho các hành động sinh hoạt lặp đi lặp lại thường nhật."},note:"「～にあたって」mang tính trang trọng và hướng tới sự khởi đầu mang tính tích cực, tuyệt đối không dùng cho các sự kiện tiêu cực (như nhập viện, phá sản, tai nạn)."},{pattern:"～に先立って",meaning:"Trước ~ / Trước khi làm ~",priority:"common",explanation:'Mẫu câu này có nghĩa là "trước khi...", dùng để diễn tả việc thực hiện một hành động chuẩn bị quan trọng trước một sự kiện hoặc kế hoạch lớn. Cấu trúc đi kèm là Danh từ hoặc Động từ thể từ điển (V-る + に先立って). Mẫu mang sắc thái trang trọng, thường xuất hiện trong văn viết, thông báo chính thức, tin tức thời sự hoặc môi trường kinh doanh.',examples:[{sentence:"新商品の発売に先立って、関係者向けの記者会見が行われた。",translation:"Trước khi mở bán sản phẩm mới, một buổi họp báo dành cho những người liên quan đã được tổ chức."},{sentence:"映画の一般公開に先立って、特別試写会が開催された。",translation:"Trước khi bộ phim được công chiếu rộng rãi, một buổi chiếu thử đặc biệt đã được tổ chức."}],dialogue:{title:"Chuẩn bị khai mạc triển lãm",lines:[{speaker:"A",text:"明日の展示会の開催に先立って、会場の最終点検をお願いできますか。",translation:"Trước khi triển lãm diễn ra vào ngày mai, anh kiểm tra hội trường lần cuối giúp tôi được không?"},{speaker:"B",text:"はい、すでにスタッフ全員にチェックリストを配布して準備を進めています。",translation:"Vâng, tôi đã phát danh sách kiểm tra cho toàn bộ nhân viên và đang tiến hành chuẩn bị rồi ạ."},{speaker:"A",text:"ありがとうございます。万全の態勢でお客様をお迎えしましょう。",translation:"Cảm ơn anh. Chúng ta hãy chuẩn bị thật chu đáo để đón khách nhé."}]},commonMistake:{wrong:"ご飯を食べるに先立って、手を洗います。",correct:"ご飯を食べる前に、手を洗います。",why:"「～に先立って」mang sắc thái trang trọng dành cho sự kiện, dự án quan trọng nên không dùng cho sinh hoạt cá nhân đời thường."},note:"Khi bổ nghĩa trực tiếp cho danh từ phía sau, mẫu sẽ chuyển thành dạng「～に先立つ＋Danh từ」."},{pattern:"～において",meaning:"Ở ~ / Trong lĩnh vực / Tại",priority:"common",explanation:'Mẫu 「～において」 mang ý nghĩa là "ở, tại, trong (lĩnh vực / bối cảnh / thời đại...)", dùng để biểu thị địa điểm, thời gian, tình huống hoặc lĩnh vực diễn ra sự việc. Đây là cách diễn đạt trang trọng trong văn viết, báo chí, tin tức hoặc bài phát biểu, tương đương với trợ từ 「で」 trong văn nói hàng ngày. Khi muốn bổ nghĩa trực tiếp cho danh từ đứng phía sau, mẫu này sẽ chuyển thành dạng 「～における + Danh từ」.',examples:[{sentence:"今年の国際環境会議は東京において開催される予定です。",translation:"Hội nghị môi trường quốc tế năm nay dự kiến sẽ được tổ chức tại Tokyo."},{sentence:"AI技術は医療分野においても目覚ましい発展を遂げている。",translation:"Công nghệ AI đang đạt được những bước phát triển vượt bậc ngay cả trong lĩnh vực y tế."}],dialogue:{title:"Chuẩn bị lễ tốt nghiệp",lines:[{speaker:"A",text:"今度の卒業式は、大学の大講堂において行われることになりました。",translation:"Lễ tốt nghiệp lần này đã được quyết định tổ chức tại giảng đường lớn của trường đại học."},{speaker:"B",text:"分かりました。席の配置や案内係の手配を進めておきますね。",translation:"Tôi hiểu rồi. Tôi sẽ tiến hành sắp xếp chỗ ngồi và bố trí người hướng dẫn nhé."},{speaker:"A",text:"よろしくお願いします。式典における注意事項も事前に配っておきましょう。",translation:"Nhờ bạn nhé. Chúng ta cũng nên phát trước các lưu ý trong buổi lễ luôn."}]},commonMistake:{wrong:"昨日、駅前のカフェにおいて友達とコーヒーを飲んだ。",correct:"昨日、駅前のカフェで友達とコーヒーを飲んだ。",why:"「～において」 mang sắc thái trang trọng và dùng cho sự kiện, bối cảnh lớn chứ không dùng cho các hành động sinh hoạt đời thường cá nhân; trường hợp này chỉ dùng trợ từ 「で」."},note:"Khi bổ nghĩa trực tiếp cho một danh từ đứng liền sau, bắt buộc phải đổi sang dạng 「～における + Danh từ」 chứ không dùng nguyên dạng 「～において」."}],147:[{pattern:"～にわたって",meaning:"Suốt ~ / Trải qua toàn bộ ~",priority:"core",explanation:"Mẫu 「～にわたって」 kết hợp với danh từ chỉ thời gian, không gian, số lần hoặc quy mô để diễn tả một sự việc, hiện tượng trải rộng trên toàn bộ phạm vi hoặc kéo dài suốt khoảng thời gian đó. Ngữ pháp này mang sắc thái trang trọng, thường xuất hiện trong tin tức thời sự, văn bản báo cáo nhằm nhấn mạnh quy mô lớn và tính bao quát của sự kiện. Mẫu câu không dùng cho các hành động sinh hoạt cá nhân thông thường trong đời sống hàng ngày.",examples:[{sentence:"台風の影響により、この地域では3日間にわたって激しい雨が降り続いた。",translation:"Do ảnh hưởng của bão, mưa lớn đã liên tục trút xuống khu vực này suốt 3 ngày liền."},{sentence:"高速道路の補修工事は、約50キロの区間にわたって行われる予定です。",translation:"Công trình tu sửa đường cao tốc dự kiến sẽ được tiến hành trên toàn bộ đoạn đường dài khoảng 50 km."}],dialogue:{title:"Chuẩn bị hội nghị quốc tế",lines:[{speaker:"A",text:"来週の国際環境会議は、5日間にわたって開催されるそうですね。",translation:"Nghe nói hội nghị môi trường quốc tế tuần tới sẽ được tổ chức suốt 5 ngày đúng không?"},{speaker:"B",text:"ええ、世界各国から専門家が集まるので、準備もかなり大規模になっています。",translation:"Vâng, vì có các chuyên gia từ khắp thế giới tụ họp nên khâu chuẩn bị cũng rất quy mô."},{speaker:"A",text:"長丁場になりますが、万全の体制でサポートしましょう。",translation:"Sẽ là một đợt làm việc dài ngày đấy, chúng ta hãy hỗ trợ với sự chuẩn bị chu đáo nhất nhé."}]},commonMistake:{wrong:"台風の影響で、九州地方全体にかけて大雨警報が発令された。",correct:"台風の影響で、九州地方全体にわたって大雨警報が発令された。",why:"Khi muốn nhấn mạnh phạm vi bao phủ toàn bộ một khu vực rộng lớn phải dùng 「にわたって」, còn 「にかけて」 chỉ dùng để chỉ phạm vi mờ từ khoảng điểm này đến khoảng điểm kia."},note:"Cần phân biệt với 「～を通じて」 vốn nhấn mạnh sự liên tục xuyên suốt một chu kỳ thời gian tự nhiên (như cả năm, bốn mùa), trong khi 「～にわたって」 nhấn mạnh vào độ dài, số lượng hoặc quy mô phạm vi lớn của sự việc."},{pattern:"～ものを",meaning:"Lẽ ra ~ mà lại... (tiếc nuối/trách móc)",priority:"common",explanation:"Mẫu ngữ pháp này dùng để diễn tả tâm trạng tiếc nuối, hối hận hoặc trách móc khi một sự việc thực tế xảy ra không như mong đợi, trái ngược với điều lẽ ra nên xảy ra hoặc đã có thể làm tốt hơn. Vế trước thường đi kèm với các thể giả định như 〜ば / 〜たら mang nghĩa 'giá mà / lẽ ra... thì đã tốt rồi, vậy mà lại...'. Mẫu câu này thường dùng trong ngữ cảnh người nói phàn nàn về hành động của đối phương hoặc tự dằn vặt về kết quả đáng tiếc trong quá khứ.",examples:[{sentence:"一言相談してくれれば力になれたものを、どうして一人で抱え込んでしまったのですか。",translation:"Lẽ ra nếu nói trước với tôi một lời thì tôi đã có thể giúp đỡ rồi, sao lại cứ ôm đồm chịu đựng một mình như vậy chứ?"},{sentence:"早く病院に行っていれば手術をせずに済んだものを、放っておいたせいで悪化してしまった。",translation:"Giá mà đi bệnh viện sớm thì đâu đến mức phải phẫu thuật, đằng này do cứ để mặc nên bệnh mới trở nặng."}],dialogue:{title:"Lỡ chuyến bay",lines:[{speaker:"A",text:"もっと早く家を出れば渋滞に巻き込まれずに済んだものを、ギリギリまで準備していたから飛行機に乗り遅れちゃったよ。",translation:"Lẽ ra nếu rời nhà sớm hơn thì đã không bị kẹt xe rồi, đằng này cứ nấn ná chuẩn bị sát giờ nên lỡ mất chuyến bay rồi."},{speaker:"B",text:"だから前日のうちに荷物をまとめておこうって言ったじゃないですか。",translation:"Bởi vậy tôi mới bảo là chuẩn bị hành lý xong xuôi từ hôm trước đi mà không chịu nghe."},{speaker:"A",text:"本当に君の言う通りにしておけばよかったよ。次の便を予約し直すね。",translation:"Đúng là lẽ ra tôi nên nghe lời cậu. Để tôi đặt lại vé chuyến sau vậy."}]},commonMistake:{wrong:"彼は毎日一生懸命勉強しているものを、試験に落ちてしまった。",correct:"あんなに一生懸命勉強していたのだから合格できたものを、体調を崩したせいで落ちてしまった。",why:"「～ものを」không dùng để tường thuật sự thật đối lập đơn thuần như 「〜のに」, mà vế trước thường phải gắn với giả định một kết quả tốt đẹp lẽ ra đã đạt được kèm theo cảm xúc tiếc nuối, trách móc sâu sắc."},note:"So với 「〜のに」, 「〜ものを」mang sắc thái tiếc nuối và oán trách đậm nét hơn, thường đi sau các cấu trúc điều kiện (〜ば／〜たら...ものを) và có thể đứng ở cuối câu để bỏ lửng sự tiếc nuối."},{pattern:"～ことか",meaning:"Biết bao ~ / Cảm thán mức độ",priority:"common",explanation:'Mẫu ngữ pháp này dùng để bộc lộ cảm xúc cảm thán sâu sắc của người nói về một sự việc, mức độ hoặc tần suất nào đó ("biết bao", "xiết bao", "không biết bao nhiêu lần"). Cấu trúc này thường bắt buộc đi kèm với các từ nghi vấn biểu thị mức độ như 「どんなに」「どれほど」「なんと」 hoặc từ chỉ tần suất như 「何度」. Về cách nối, mẫu đi với thể thông thường của động từ và tính từ (riêng tính từ đuôi な đi kèm な hoặc である). Ngữ pháp mang sắc thái trang trọng, thường dùng trong văn viết, hồi tưởng, phát biểu hoặc độc thoại nội tâm.',examples:[{sentence:"異国の地で一人暮らしを始めた当初は、どんなに心細かったことか。",translation:"Hồi mới bắt đầu sống một mình ở nơi đất khách quê người, tôi đã cảm thấy cô đơn và bất an biết bao."},{sentence:"合格の知らせを聞いたとき、両親がどれほど喜んでくれたことか。",translation:"Khi nghe tin tôi thi đỗ, bố mẹ đã vui mừng biết nhường nào."}],dialogue:{title:"Ôn lại kỷ niệm",lines:[{speaker:"A",text:"高校時代、みんなで夜遅くまで文化祭の準備をしたのが、どれほど懐かしいことか。",translation:"Hồi cấp ba, việc mọi người cùng nhau chuẩn bị cho lễ hội văn hóa đến tận đêm muộn thật hoài niệm biết bao."},{speaker:"B",text:"本当にそうだね。あの時は大変だったけど、今振り返ると青春のいい思い出だよ。",translation:"Thật sự đúng là vậy nhỉ. Lúc đó tuy vất vả nhưng giờ nhìn lại toàn là kỷ niệm đẹp của tuổi thanh xuân."},{speaker:"A",text:"うん、あの仲間たちとまた集まってゆっくり語り合いたいな。",translation:"Ừ, tôi muốn lại được tụ họp với hội bạn đó để cùng nhau tâm sự ghê."}]},commonMistake:{wrong:"初めての一人暮らしは、とても大変だったことか。",correct:"初めての一人暮らしは、どんなに大変だったことか。",why:"Mẫu 「～ことか」 là cấu trúc cảm thán đi liền với phó từ nghi vấn chỉ mức độ như 「どんなに / どれほど」 chứ không đi với các phó từ chỉ mức độ thông thường như 「とても」 hay 「大変」."},note:"Cần lưu ý tính từ đuôi な khi kết hợp với mẫu này phải giữ nguyên đuôi 「な」 hoặc dùng 「である」 (ví dụ: 「大変なことか」), tuyệt đối không chia thành 「だことか」."},{pattern:"～だけあって",meaning:"Xứng với ~ / Đúng là ~ nên",priority:"common",explanation:'Mẫu「～だけあって」mang ý nghĩa "Quả đúng là... có khác" hoặc "Xứng danh là... nên...", dùng để bày tỏ sự khen ngợi, thán phục khi kết quả ở vế sau hoàn toàn tương xứng với năng lực, danh tiếng hay đặc điểm ở vế trước. Cấu trúc này nối trực tiếp với thể thông thường của động từ, tính từ (A-na giữ nguyên な hoặc である) và danh từ (N hoặc Nである). Lưu ý vế sau luôn diễn tả một thực tế khách quan theo hướng tốt/tích cực, không dùng cho câu phán đoán tương lai hay mang ý đồ, mệnh lệnh của người nói.',examples:[{sentence:"このレストランはミシュラン三つ星を獲得しただけあって、料理の味はもちろんサービスも完璧だ。",translation:"Nhà hàng này đúng là đã từng đạt ba sao Michelin có khác, không chỉ món ăn ngon mà cung cách phục vụ cũng hoàn hảo."},{sentence:"彼は10年間日本に住んでいただけあって、日本語の微妙なニュアンスまでよく理解している。",translation:"Anh ấy quả đúng là đã sống ở Nhật 10 năm có khác, hiểu rõ đến cả những sắc thái tinh tế trong tiếng Nhật."}],dialogue:{title:"Trải nghiệm khách sạn cao cấp",lines:[{speaker:"A",text:"このホテル、部屋からの景色も素晴らしいし、スタッフの対応もすごく丁寧ですね。",translation:"Khách sạn này cảnh nhìn từ phòng tuyệt đẹp, mà nhân viên ứng xử cũng chu đáo thật đấy."},{speaker:"B",text:"一流ホテルと評判なだけあって、細部までサービスが行き届いていますね。",translation:"Đúng là khách sạn có tiếng là hạng nhất có khác, dịch vụ chu đáo đến từng chi tiết nhỏ."},{speaker:"A",text:"ええ、少し高かったけれど、ここに泊まって本当によかったです。",translation:"Vâng, tuy có hơi đắt một chút nhưng ở đây đúng là xứng đáng thật."}]},commonMistake:{wrong:"このレストランは有名なだけあって、料理が全然美味しくなかった。",correct:"このレストランは有名なわりには、料理が全然美味しくなかった。",why:"「～だけあって」chỉ dùng cho kết quả tích cực tương xứng với danh tiếng/kỳ vọng ở vế trước; khi kết quả trái ngược hoàn toàn với kỳ vọng thì phải dùng「～わりに(は)」hoặc「～にしては」."},note:"Phân biệt với「～だけに」:「～だけあって」luôn mang hàm ý khen ngợi kết quả tốt, trong khi「～だけに」có thể dùng cho cả kết quả tiêu cực để nhấn mạnh tâm trạng thất vọng, tiếc nuối càng nhân lên gấp bội."},{pattern:"～だけに",meaning:"Chính vì ~ nên / Tương xứng với ~",priority:"common",explanation:"Mẫu ngữ pháp 「～だけに」 diễn tả ý nghĩa 'chính vì có lý do X nên mức độ hoặc cảm xúc ở vế sau càng tăng lên tương xứng'. Cấu trúc này được dùng khi người nói muốn nhấn mạnh rằng vì một tiền đề đặc biệt nên kết quả, tâm trạng (vui mừng, thất vọng, tiếc nuối) hay sự đánh giá ở vế sau diễn ra tự nhiên ở mức độ cao hơn bình thường. Vế sau là câu biểu thị trạng thái, cảm xúc hoặc đánh giá khách quan, tuyệt đối không dùng câu mệnh lệnh, nhờ vả hay ý chí rủ rê.",examples:[{sentence:"彼は長年この分野を研究してきただけに、今回の実験の失敗は相当ショックだったようだ。",translation:"Chính vì anh ấy đã nghiên cứu lĩnh vực này suốt nhiều năm nên có vẻ như thất bại của thí nghiệm lần này là một cú sốc rất lớn."},{sentence:"一流の高級ホテルだけに、客室の清潔感やスタッフの接客態度は非常に素晴らしい。",translation:"Xứng danh là khách sạn cao cấp hàng đầu, độ sạch sẽ của phòng ốc và thái độ phục vụ của nhân viên vô cùng tuyệt vời."}],dialogue:{title:"Kết quả kỳ thi",lines:[{speaker:"A",text:"山田さん、昨日のJLPTの結果はどうだった？",translation:"Yamada ơi, kết quả thi JLPT hôm qua thế nào rồi?"},{speaker:"B",text:"不合格だったよ。毎日何時間も必死に勉強しただけに、悔しくてたまらないんだ。",translation:"Tớ trượt rồi. Chính vì ngày nào cũng dốc sức học cả mấy tiếng đồng hồ nên tớ thấy tiếc nuối và cay cú vô cùng."},{speaker:"A",text:"そうか…ずっと頑張っていたのを知っているから、私もすごく残念だよ。",translation:"Vậy sao… Vì biết cậu đã nỗ lực suốt thời gian qua nên tớ cũng thấy tiếc lắm."}]},commonMistake:{wrong:"彼はまだ新人だけに、この仕事を優しく教えてあげてください。",correct:"彼はまだ新人だから、この仕事を優しく教えてあげてください。",why:"Vế sau của 「～だけに」 diễn tả trạng thái hoặc mức độ cảm xúc tự nhiên tương xứng với nguyên nhân, không được dùng các mẫu câu thể hiện sự nhờ vả, yêu cầu hay mệnh lệnh như 「～てください」."},note:"Khác với 「～ばかりに」 chỉ dùng cho kết quả tiêu cực kèm sắc thái hối hận vì một nguyên nhân duy nhất, 「～だけに」 có thể dùng cho cả đánh giá tích cực lẫn tiêu cực để nhấn mạnh mức độ vượt trội hoặc sâu sắc hơn bình thường."},{pattern:"～ばかりか",meaning:"Không chỉ ~ mà còn",priority:"common",explanation:'Mẫu câu 「～ばかりか」 diễn đạt ý nghĩa "không chỉ dừng lại ở A mà còn xảy ra hoặc kéo theo cả B", trong đó B thường là điều có mức độ cao hơn hoặc nằm ngoài dự tính ban đầu. Cả hai vế A và B phải đồng nhất về chiều hướng đánh giá (cùng tốt hoặc cùng xấu), vế sau thường kết hợp với các trợ từ nhấn mạnh như 「も」「さえ」「まで」. Mẫu này mang sắc thái trang trọng hơn so với 「～だけでなく」 và vế sau tuyệt đối không dùng các cách diễn đạt thể hiện ý chí, mệnh lệnh hay nhờ vả.',examples:[{sentence:"彼は仕事を無断で休んだばかりか、連絡さえ一切取ろうとしなかった。",translation:"Anh ấy không chỉ tự ý nghỉ việc mà đến cả liên lạc cũng hoàn toàn không buồn gọi lại."},{sentence:"そのレストランは料理が美味しいばかりか、接客サービスも非常に素晴らしい。",translation:"Nhà hàng đó không chỉ đồ ăn ngon mà chất lượng phục vụ cũng vô cùng tuyệt vời."}],dialogue:{title:"Về đồng nghiệp mới",lines:[{speaker:"A",text:"今度入社した田中さん、英語が堪能なばかりか、中国語まで流暢に話せるらしいよ。",translation:"Anh Tanaka mới vào công ty nghe nói không chỉ thành thạo tiếng Anh mà đến cả tiếng Trung cũng nói lưu loát lắm đấy."},{speaker:"B",text:"本当に？海外営業部にとっては頼もしい即戦力が入ってきたね。",translation:"Thật sao? Vậy là phòng kinh doanh quốc tế có thêm một nhân lực chủ chốt đáng tin cậy rồi."},{speaker:"A",text:"うん、しかも人柄もとても親しみやすいから、すぐにチームに馴染みそうだね。",translation:"Ừ, hơn nữa tính tình lại rất thân thiện nên chắc sẽ hòa nhập với nhóm nhanh thôi."}]},commonMistake:{wrong:"この資料は内容をチェックするばかりか、コピーもしてください。",correct:"この資料は内容をチェックするだけでなく、コピーもしてください。",why:"「～ばかりか」chỉ dùng để trần thuật sự việc khách quan ngoài dự tính nên vế sau không được dùng câu nhờ vả, sai khiến hay mệnh lệnh như「～てください」."},note:"So với 「～だけでなく」 dùng linh hoạt và trung tính, 「～ばかりか」 trang trọng hơn và nhấn mạnh rõ rệt cảm giác ngạc nhiên hoặc vượt quá mức độ bình thường của người nói."},{pattern:"～に際して",meaning:"Nhân dịp / Vào lúc thực hiện (trang trọng)",priority:"common",explanation:'Mẫu 「～に際して」 mang nghĩa "nhân dịp / vào lúc / khi bắt đầu thực hiện một sự kiện trọng đại nào đó". Đi sau danh từ hoặc động từ thể từ điển (V-る), mẫu câu này thường dùng trong các sự kiện mang tính dấu mốc, trang trọng như lễ khai trương, ký kết hợp đồng, nhập học hay khởi sự dự án mới. Đây là cách diễn đạt mang sắc thái trang trọng, thường xuất hiện trong văn viết chính thức hoặc các bài phát biểu nghi thức, không dùng cho sinh hoạt thường ngày.',examples:[{sentence:"新サービスの開始に際して、利用規約を改定いたしましたのでご確認ください。",translation:"Nhân dịp ra mắt dịch vụ mới, chúng tôi đã sửa đổi điều khoản sử dụng, xin quý khách vui lòng kiểm tra."},{sentence:"海外留学に出発するに際して、これまでお世話になった先生方や友人に挨拶をした。",translation:"Trước khi lên đường đi du học nước ngoài, tôi đã đến chào tạm biệt các thầy cô và bạn bè đã giúp đỡ mình suốt thời gian qua."}],dialogue:{title:"Chuẩn bị lễ khai trương",lines:[{speaker:"A",text:"来月の新店舗オープンに際して、特別セールの案内状を顧客に送付しましょう。",translation:"Nhân dịp khai trương chi nhánh mới vào tháng sau, chúng ta hãy gửi thư mời chương trình ưu đãi đặc biệt đến khách hàng nhé."},{speaker:"B",text:"承知いたしました。すぐに送付先リストを作成して印刷の手配を進めます。",translation:"Tôi hiểu rồi. Tôi sẽ lập danh sách gửi thư và tiến hành khâu in ấn ngay."},{speaker:"A",text:"よろしく頼むよ。オープン当日に向けて万全の準備をしておこう。",translation:"Nhờ anh nhé. Hãy chuẩn bị thật chu đáo để sẵn sàng cho ngày khai trương."}]},commonMistake:{wrong:"毎朝起きるに際して、いつもコップ一杯の水を飲む。",correct:"毎朝起きるとき（に）、いつもコップ一杯の水を飲む。",why:"「～に際して」chỉ dùng cho các dịp trọng đại, đặc biệt hoặc có tính dấu mốc, không dùng cho hành vi sinh hoạt thường nhật lặp đi lặp lại như việc thức dậy vào buổi sáng."},note:"So với mẫu tương đương 「～にあたって」 (thường mang sắc thái tích cực, chủ động hướng tới tương lai), 「～に際して」 mang tính nghi thức, hành chính hơn và có thể dùng cho cả các thông báo thủ tục hoặc sự kiện bất khả kháng."},{pattern:"～かたわら",meaning:"Trong khi ~ cũng làm / Song song ~",priority:"common",explanation:"Mẫu câu 「～かたわら」được dùng để diễn tả ý nghĩa bên cạnh công việc, vai trò chính (vế trước) thì chủ thể đồng thời cũng thực hiện một hoạt động hay nghề nghiệp khác (vế sau). Về mặt kết nối, mẫu đi trực tiếp với động từ thể từ điển (V-る) hoặc danh từ kèm trợ từ (Nの). Cấu trúc này chỉ áp dụng cho hai hoạt động mang tính liên tục, diễn ra song song trong một khoảng thời gian dài chứ không dùng cho các hành động tức thời. Sắc thái câu văn trang trọng, lịch sự, thường xuất hiện trong văn viết, báo chí hoặc khi giới thiệu về lý lịch, hoạt động của một người.",examples:[{sentence:"彼は大学で教鞭を執るかたわら、小説家としても精力的に執筆活動を続けている。",translation:"Bên cạnh công việc chính là giảng dạy tại trường đại học, anh ấy vẫn tích cực duy trì hoạt động viết lách với tư cách là một tiểu thuyết gia."},{sentence:"彼女は本業のデザインの仕事のかたわら、週末には趣味の陶芸教室を開いている。",translation:"Song song với công việc chính là thiết kế, cô ấy còn mở lớp dạy làm gốm theo sở thích vào dịp cuối tuần."}],dialogue:{title:"Nghề tay trái bận rộn",lines:[{speaker:"A",text:"田中さん、会社員として勤務するかたわら、夜はプログラミングスクールの講師もされているそうですね。",translation:"Anh Tanaka này, nghe nói bên cạnh việc làm nhân viên công ty thì buổi tối anh còn làm giảng viên ở trường dạy lập trình nữa đúng không?"},{speaker:"B",text:"ええ、時間は限られますが、人に教えることで自分自身の勉強にもなって充実していますよ。",translation:"Vâng, tuy thời gian eo hẹp nhưng việc giảng dạy cho người khác cũng giúp bản thân học hỏi thêm nên tôi thấy rất ý nghĩa."},{speaker:"A",text:"本業と両立されていて、本当にバイタリティがありますね。",translation:"Vừa duy trì tốt công việc chính vừa làm thêm được như vậy, anh thật sự rất tràn đầy năng lượng đấy."}]},commonMistake:{wrong:"テレビを見るかたわら、家族と一緒に晩ご飯を食べた。",correct:"テレビを見ながら、家族と一緒に晩ご飯を食べた。",why:"「～かたわら」chỉ dùng cho hai hoạt động mang tính công việc, vai trò xã hội kéo dài trong một giai đoạn thời gian, không dùng cho hai hành động tức thời, ngắn hạn như vừa xem TV vừa ăn cơm."},note:"Cần phân biệt với「～ながら」(dùng cho hai hành động diễn ra cùng một thời điểm trong chốc lát) và「～がてら」(nhân tiện, tiện thể ghé làm việc phụ trong khi đang đi làm việc chính)."}],148:[{pattern:"～ではあるまいし",meaning:"Không phải ~ đâu mà",priority:"core",explanation:'Mẫu câu dùng để diễn đạt ý "Đâu phải là... / Có phải là... đâu mà", nhằm nhấn mạnh lý do rằng vì thực tế không phải như thế nên đối phương không cần hoặc không nên có thái độ, hành động thái quá. Mẫu này thường đi trực tiếp sau danh từ hoặc thể thông thường của động từ (thường thêm 「の/ん」), với vế sau mang sắc thái nhắc nhở, khuyên nhủ hoặc phê phán, mỉa mai nhẹ nhàng. Trong đời sống hàng ngày, người Nhật rất hay sử dụng biến thể văn nói thân mật của mẫu này là 「～じゃあるまいし」.',examples:[{sentence:"子供ではあるまいし、ちょっと注射されたくらいで大声で泣くのはやめなさい。",translation:"Đâu còn là con nít nữa mà mới bị tiêm có một chút đã khóc toáng lên thế, thôi đi nào."},{sentence:"一生会えなくなるわけではあるまいし、そんなに悲しそうな顔をしないでよ。",translation:"Có phải là cả đời không gặp lại nhau nữa đâu mà cậu lại làm vẻ mặt buồn rầu đến thế."}],dialogue:{title:"Trước giờ phỏng vấn",lines:[{speaker:"A",text:"面接だからって、そんなにガチガチに緊張しなくてもいいじゃない。",translation:"Dù là phỏng vấn thì cậu cũng đâu cần phải căng thẳng đến cứng đờ người ra như thế."},{speaker:"B",text:"だって、もし失敗したらどうしようって思っちゃって…。",translation:"Nhưng mà cứ nghĩ nhỡ trượt thì biết làm sao..."},{speaker:"A",text:"命を取られるわけではあるまいし、リラックスしていつも通りに話せば大丈夫だよ。",translation:"Có phải bị lấy mất mạng đâu mà, cứ thả lỏng rồi nói chuyện tự nhiên như mọi khi là ổn thôi."}]},commonMistake:{wrong:"彼はプロの料理人ではあるまいし、とても美味しい料理を作った。",correct:"彼はプロの料理人ではないのに、とても美味しい料理を作った。",why:'「～ではあるまいし」 mang sắc thái chê trách hoặc khuyên bảo đừng làm quá, chứ không dùng như một liên từ tương phản thông thường mang nghĩa "mặc dù không phải là... nhưng" để khen ngợi.'},note:"Mẫu câu này chỉ dùng để nhắc nhở, phê phán hành vi hoặc thái độ của đối phương, không dùng cho hành động hay ý chí của chính bản thân người nói."},{pattern:"～にしたら",meaning:"Nếu đứng ở vị trí ~ / Từ góc nhìn ~",priority:"common",explanation:'Mẫu 「～にしたら」（hoặc にすれば、にしてみれば）mang nghĩa là "nếu đứng ở lập trường, góc nhìn của ai đó". Cấu trúc này dùng khi người nói thử đặt mình vào vị trí của người khác (thường là ngôi thứ ba hoặc đối phương) để suy đoán hoặc đồng cảm với tâm tư, cảm xúc của họ. Vế sau thường đi kèm với những đánh giá mang tính tâm lý, sự phiền toái hoặc nỗi khổ tâm của đối tượng đó.',examples:[{sentence:"親にしたら、子どもの将来のことを心配するのは当然だろう。",translation:"Nếu đứng ở vị trí của cha mẹ, việc lo lắng cho tương lai của con cái có lẽ là điều đương nhiên."},{sentence:"あなたには些細な冗談でも、彼にしたら深く傷つく言葉だったのかもしれない。",translation:"Dù đối với bạn chỉ là trò đùa vặt, nhưng nếu đặt vào vị trí của anh ấy thì có lẽ đó là lời nói gây tổn thương sâu sắc."}],dialogue:{title:"Áp lực của trưởng nhóm",lines:[{speaker:"A",text:"田中さん、最近少し厳しすぎない？新人の些細なミスでもすごく怒るし。",translation:"Anh Tanaka dạo này có hơi khắt khe quá không? Người mới chỉ mắc lỗi nhỏ thôi mà anh ấy cũng nổi giận dữ lắm."},{speaker:"B",text:"でも、リーダーの彼にしたら、納期が迫っていて焦る気持ちも分かるよ。",translation:"Nhưng nếu đứng ở vị trí trưởng nhóm như anh ấy, tôi cũng hiểu được cảm giác sốt ruột vì sắp đến hạn chót."},{speaker:"A",text:"確かにね。上の立場になると責任も重いから大変だよね。",translation:"Cũng đúng nhỉ. Ở vị trí cấp trên trách nhiệm nặng nề nên vất vả thật."}]},commonMistake:{wrong:"健康を維持することは、現代人にしたらとても大切です。",correct:"健康を維持することは、現代人にとってとても大切です。",why:"Khi đưa ra đánh giá, tiêu chuẩn khách quan về mức độ quan trọng hay cần thiết thì phải dùng 「～にとって」, còn 「～にしたら」chỉ dùng khi đặt mình vào vị trí của ai đó để suy đoán cảm xúc, tâm trạng chủ quan."},note:"So với 「～にとって」 (dùng để nêu nhận định/đánh giá giá trị khách quan), 「～にしたら」 mang đậm sắc thái đồng cảm, đặt mình vào tâm tư, cảm xúc hoặc nỗi khổ của người khác."},{pattern:"～にすれば",meaning:"Từ góc nhìn ~ (biến thể)",priority:"common",explanation:'Mẫu ngữ pháp「～にすれば」đi sau danh từ chỉ người hoặc tổ chức, có nghĩa là "nếu đứng trên lập trường/vị trí của ~ mà suy nghĩ thì...". Mẫu này thường dùng khi người nói đặt mình vào hoàn cảnh của người khác (ngôi thứ 2 hoặc ngôi thứ 3) để suy đoán cảm xúc, tâm trạng hoặc đưa ra nhận xét, đánh giá. Sắc thái biểu đạt thường thể hiện sự thấu hiểu, đồng cảm hoặc lý giải nguyên nhân vì sao đối phương lại có phản ứng hay suy nghĩ như vậy.',examples:[{sentence:"親にすれば、子どもの将来を心配しているからこそ厳しく言ってしまうのだろう。",translation:"Đứng ở góc độ của cha mẹ, có lẽ chính vì lo lắng cho tương lai của con cái nên họ mới nghiêm khắc như vậy."},{sentence:"あなたにとっては些細な冗談でも、言われた本人にすれば深く傷つく言葉だったかもしれない。",translation:"Đối với bạn có thể chỉ là trò đùa vặt vãnh, nhưng nếu đứng ở vị trí của người bị nói, đó có thể là những lời gây tổn thương sâu sắc."}],dialogue:{title:"Bàn về quy định cấm tăng ca",lines:[{speaker:"A",text:"会社が残業を全面禁止にしたせいで、納期に間に合わなくて本当に困っているよ。",translation:"Công ty cấm tăng ca hoàn toàn làm công việc không kịp tiến độ, tôi đang đau đầu lắm đây."},{speaker:"B",text:"でも、経営陣にすれば、社員の健康管理や人件費削減のために苦渋の決断だったんじゃないかな。",translation:"Nhưng nếu đứng ở vị trí ban lãnh đạo, có lẽ đó là quyết định đầy trăn trở vì sức khỏe nhân viên và cắt giảm chi phí đấy."},{speaker:"A",text:"そう言われれば理解できなくもないけど、現場の負担も少しは考えてほしいよ。",translation:"Nói vậy thì tôi cũng hiểu được phần nào, nhưng vẫn mong họ nghĩ cho gánh nặng của nhân viên hiện trường một chút."}]},commonMistake:{wrong:"彼は日本語を勉強し始めたばかりにすれば、発音がとても綺麗だ。",correct:"彼は日本語を勉強し始めたばかりにしては、発音がとても綺麗だ。",why:"「～にすれば」dùng để biểu thị lập trường/góc nhìn, còn khi muốn diễn tả sự việc xảy ra trái ngược hoặc vượt ngoài mức dự đoán so với một tiêu chuẩn (tuy... nhưng) thì phải dùng「～にしては」."},note:"「～にすれば」đồng nghĩa và có thể thay thế bằng「～にしたら」hoặc「～にしてみれば」, trong đó「～にすれば」thường tạo cảm giác lập luận mang tính giả định và trang trọng hơn「～にしたら」."},{pattern:"～てならない",meaning:"Cảm giác tự nhiên không kìm được",priority:"common",explanation:"Mẫu câu 「～てならない」 dùng để diễn tả cảm xúc, tâm trạng hoặc cảm giác tự nhiên trào dâng mà bản thân không thể nào kiềm chế được (mang nghĩa 'vô cùng...', 'hết sức...', 'không sao kìm được'). Mẫu này thường đi kèm với các từ chỉ cảm xúc (như lo lắng, tiếc nuối, buồn bã) hoặc các động từ thể tự phát như 「思える」「感じられる」. Đây là cách diễn đạt mang tính trang trọng, văn phong sâu sắc và thiên về nội tâm hơn so với 「～てたまらない」 hay 「～てしょうがない」.",examples:[{sentence:"一人暮らしを始めたばかりの頃は、夜になると実家の家族のことが心配でならなかった。",translation:"Hồi mới bắt đầu sống một mình, cứ hễ đêm xuống là tôi lại lo lắng cho gia đình ở quê không sao kìm được."},{sentence:"長年努力を重ねてきたプロジェクトが直前で中止になり、悔しくてならない。",translation:"Dự án bao năm nỗ lực lại bị hủy bỏ ngay trước phút chót khiến tôi cảm thấy cay đắng và tiếc nuối tột cùng."}],dialogue:{title:"Lo lắng về kết quả thi",lines:[{speaker:"A",text:"明日の合格発表のことが気になってならないんだ。昨夜も全然眠れなかったよ。",translation:"Tôi bồn chồn lo lắng về buổi công bố kết quả ngày mai không chịu nổi. Tối qua cũng chẳng chợp mắt được tí nào."},{speaker:"B",text:"あんなに一生懸命勉強したんだから、きっと大丈夫だよ。少しリラックスして待とう。",translation:"Cậu đã học hành chăm chỉ đến thế rồi cơ mà, chắc chắn sẽ ổn thôi. Thư giãn một chút rồi chờ xem sao."},{speaker:"A",text:"うん、ありがとう。でも、どうしても悪い結果ばかり頭に浮かんできちゃうんだ。",translation:"Ừ, cảm ơn cậu. Nhưng trong đầu tôi cứ tự nhiên hiện lên toàn những viễn cảnh xấu thôi."}]},commonMistake:{wrong:"暑い中をずっと走っていたので、喉が渇いてならない。",correct:"暑い中をずっと走っていたので、喉が渇いてたまらない。",why:"「～てならない」chủ yếu dùng cho cảm xúc tâm lý nội tâm hoặc cảm nhận tự phát, không dùng cho các nhu cầu sinh lý hay cảm giác thể xác trực tiếp như khát nước, buồn ngủ."},note:"So với 「～てたまらない」(dùng phổ biến cho cả cảm giác thể xác/ham muốn trực tiếp) và 「～てしょうがない」(khẩu ngữ đời thường), 「～てならない」 trang trọng hơn và đặc biệt hay đi kèm dạng tự phát 「～と思えてならない」(không hiểu sao cứ cảm thấy rằng...)."},{pattern:"～ずにはいられない",meaning:"Không thể không làm ~ / Không kìm được",priority:"common",explanation:"Mẫu câu này diễn tả cảm xúc, tâm trạng hoặc phản xạ tự nhiên xuất phát từ bên trong mạnh mẽ đến mức không thể kiềm chế hay nhịn được, buộc phải hành động. Đi với động từ thể phủ định ngắn (V-ない bỏ ない + ずにはいられない, riêng する chuyển thành せずにはいられない). Mẫu này chủ yếu mang tính bột phát tâm lý, không dùng cho các hành động bị ép buộc bởi quy tắc xã hội hay hoàn cảnh khách quan.",examples:[{sentence:"彼のあまりにも無責任な発言を聞いて、一言文句を言わずにはいられなかった。",translation:"Nghe những phát ngôn quá đỗi vô trách nhiệm của anh ta, tôi không thể kìm nén được mà phải buông lời phàn nàn."},{sentence:"夜中に甘いものを食べるのは体に良くないと分かっていても、つい手を伸ばさずにはいられない。",translation:"Dù biết ăn đồ ngọt vào nửa đêm không tốt cho sức khỏe, nhưng tôi vẫn không kìm lòng được mà tiện tay lấy ăn."}],dialogue:{title:"Cảm nhận về bộ phim",lines:[{speaker:"A",text:"きのう教えてもらった映画を見たんだけど、主人公のドジな行動に笑わずにはいられない場面ばかりだったよ。",translation:"Tớ đã xem bộ phim cậu giới thiệu hôm qua rồi, toàn những phân cảnh khiến tớ không thể nhịn được cười trước các pha xử lý ngớ ngẩn của nhân vật chính."},{speaker:"B",text:"面白かったでしょう？でも、ラストシーンはすごく感動的じゃなかった？",translation:"Hài hước đúng không? Nhưng mà cảnh kết phim cũng cảm động lắm phải không?"},{speaker:"A",text:"うん、最後は家族の絆の深さに胸を打たれて、思わず涙を流さずにはいられなかったよ。",translation:"Ừ, đoạn cuối tớ xúc động sâu sắc trước tình cảm gia đình gắn bó nên không kìm được nước mắt."}]},commonMistake:{wrong:"台風が近づいているので、明日のイベントは中止せずにはいられない。",correct:"台風が近づいているので、明日のイベントは中止せざるを得ない。",why:"「～ずにはいられない」chỉ dùng cho cảm xúc hoặc thôi thúc nội tâm không thể kìm nén, còn hành động bắt buộc phải làm do hoàn cảnh khách quan đưa đẩy thì phải dùng「～ざるを得ない」."},note:"Khi chủ ngữ là ngôi thứ ba, cuối câu thường phải đi kèm các cách diễn đạt phán đoán hoặc miêu tả gián tiếp như「～ようだ」「～らしい」「～ている」chứ không khẳng định trực tiếp."},{pattern:"～わけにはいかない",meaning:"Không thể ~ được / Không được phép ~",priority:"common",explanation:'Mẫu câu này dùng để diễn đạt rằng "không thể làm một việc gì đó" vì bị ràng buộc bởi đạo đức, trách nhiệm, luật lệ hoặc áp lực xã hội, dù bản thân có muốn hay có khả năng làm. Đi sau động từ thể từ điển (V-る + わけにはいかない). Khác với thể khả năng (V-れない), mẫu này không nói về năng lực thể chất hay kỹ năng, mà nhấn mạnh rằng về mặt lương tâm hoặc tình thế thì không được phép làm.',examples:[{sentence:"明日は大事なプレゼンがあるので、熱があっても仕事を休むわけにはいかない。",translation:"Ngày mai có buổi thuyết trình quan trọng nên dù bị sốt tôi cũng không thể nghỉ làm được."},{sentence:"親友から絶対に秘密にしてほしいと頼まれたので、誰にも話すわけにはいかない。",translation:"Vì được bạn thân nhờ tuyệt đối giữ bí mật nên tôi không thể kể cho bất kỳ ai được."}],dialogue:{title:"Hạn chót dự án",lines:[{speaker:"A",text:"顔色が悪いよ。今日はもう仕事を切り上げて帰ったらどう？",translation:"Sắc mặt cậu kém lắm đấy. Hay là hôm nay dừng việc rồi về nghỉ ngơi đi?"},{speaker:"B",text:"心配してくれてありがとう。でも、納品が明日だから今帰るわけにはいかないんだ。",translation:"Cảm ơn cậu đã lo lắng. Nhưng hạn giao hàng là ngày mai nên bây giờ tớ không thể về được."},{speaker:"A",text:"そうか。無理しないで、私に手伝えることがあったら何でも言ってね。",translation:"Vậy à. Đừng quá sức nhé, nếu có việc gì tớ giúp được thì cứ bảo."}]},commonMistake:{wrong:"辛いものが苦手なので、このカレーを食べるわけにはいかない。",correct:"辛いものが苦手なので、このカレーは食べられない。",why:"「～わけにはいかない」 không dùng cho sự bất khả năng về mặt thể chất, thói quen hay sở thích cá nhân, mà chỉ dùng khi bị rào cản bởi trách nhiệm, đạo lý hoặc phép tắc xã hội."},note:'Cần lưu ý phân biệt với dạng phủ định kép 「～ないわけにはいかない」 mang nghĩa ngược lại hoàn toàn là "không thể không làm / đành phải làm" vì nghĩa vụ hay đạo lý.'},{pattern:"～たびに",meaning:"Mỗi khi ~ / Mỗi lần ~",priority:"common",explanation:'Mẫu ngữ pháp này diễn tả ý nghĩa "cứ mỗi lần / mỗi khi" một hành động hay sự việc nào đó diễn ra thì lại xuất hiện một kết quả hoặc hành động tương tự lặp lại theo sau. Cấu trúc thường kết hợp với động từ thể từ điển (V-る) hoặc danh từ đi kèm の (N + のたびに). Mẫu câu nhấn mạnh tính quy luật lặp lại hoặc cảm xúc luôn nảy sinh mỗi khi có sự kiện đó, và không dùng cho các chu kỳ sinh hoạt hiển nhiên hàng ngày.',examples:[{sentence:"この曲を聴くたびに、学生時代の懐かしい思い出がよみがえってくる。",translation:"Mỗi lần nghe ca khúc này, những kỷ niệm hoài niệm thời học sinh lại ùa về trong tôi."},{sentence:"出張のたびに、家族や同僚のためにその土地の名物を買ってくる。",translation:"Mỗi lần đi công tác, tôi đều mua đặc sản địa phương về cho gia đình và đồng nghiệp."}],dialogue:{title:"Xem lại ảnh cũ",lines:[{speaker:"A",text:"この古いアルバムを見るたびに、故郷の家族や友達に会いたくなりますね。",translation:"Mỗi lần xem cuốn album cũ này, tôi lại thấy nhớ gia đình và bạn bè ở quê da diết."},{speaker:"B",text:"分かります。遠く離れて暮らしていると、ふとした瞬間に寂しくなりますよね。",translation:"Tôi hiểu mà. Sống xa quê thì nhiều lúc bất chợt thấy cô đơn lắm."},{speaker:"A",text:"ええ、今度の連休には久しぶりに実家に帰ろうと思います。",translation:"Vâng, kỳ nghỉ dài sắp tới tôi định sẽ về thăm nhà sau một thời gian dài."}]},commonMistake:{wrong:"毎朝起きるたびに、顔を洗って歯を磨きます。",correct:"毎朝起きたら、顔を洗って歯を磨きます。",why:"Không dùng「～たびに」cho các hành động sinh hoạt tự nhiên, tất yếu diễn ra hàng ngày mà nên dùng cấu trúc giả định tuần tự như「～たら」hoặc「～と」."},note:"Phân biệt với「～ごとに」:「～たびに」dùng cho sự kiện cụ thể kèm cảm xúc hoặc hành động lặp lại, còn「～ごとに」chuyên dùng để chỉ chu kỳ lặp lại đều đặn theo đơn vị thời gian hoặc số lượng (như 2時間ごとに: cứ mỗi 2 tiếng một lần)."},{pattern:"～に限り",meaning:"Chỉ trong trường hợp ~ (hạn chế)",priority:"common",explanation:'Mẫu 「～に限り」 đi sau danh từ nhằm biểu thị ý nghĩa "chỉ riêng đối tượng hoặc trường hợp này" mới được áp dụng một quy định đặc biệt hay nhận ưu đãi, đặc cách. Cấu trúc này mang sắc thái trang trọng, tính quy phạm cao, thường được dùng trong các thông báo chính thức, văn bản hướng dẫn hoặc điều khoản dịch vụ khách hàng. Vế phía sau thường là các nội dung mang tính khẳng định như tiếp nhận, cho phép, ưu đãi và không dùng với câu phủ định.',examples:[{sentence:"本日ご来店いただいたお客様に限り、全商品を20％割引でご提供いたします。",translation:"Chỉ riêng khách hàng đến cửa hàng trong ngày hôm nay mới được giảm giá 20% cho toàn bộ sản phẩm."},{sentence:"出席率が90％以上の学生に限り、奨学金の申請資格が与えられます。",translation:"Chỉ riêng những sinh viên có tỷ lệ chuyên cần từ 90% trở lên mới được cấp tư cách nộp đơn xin học bổng."}],dialogue:{title:"Hỏi thông tin giá vé",lines:[{speaker:"A",text:"すみません、この学割チケットは誰でも利用できますか。",translation:"Xin lỗi, vé giảm giá cho học sinh này ai cũng sử dụng được ạ?"},{speaker:"B",text:"いいえ、有効な学生証をご提示いただいた方に限り、割引が適用されます。",translation:"Dạ không, chỉ riêng những ai xuất trình thẻ học sinh/sinh viên còn hiệu lực mới được áp dụng giảm giá ạ."},{speaker:"A",text:"分かりました。学生証を持っているので、1枚お願いします。",translation:"Tôi hiểu rồi. Tôi có mang theo thẻ học sinh đây, cho tôi 1 vé nhé."}]},commonMistake:{wrong:"あなたに限り、この秘密を教えてあげます。",correct:"あなただけに、この秘密を教えてあげます。",why:"「～に限り」 là cách diễn đạt trang trọng dùng cho thông báo quy chế công cộng hoặc dịch vụ, không dùng cho giao tiếp thân mật hay việc mang tính cá nhân."},note:"Cần phân biệt với 「～に限って」 (dùng khi phàn nàn về sự trùng hợp xui xẻo hoặc khẳng định niềm tin tuyệt đối vào ai đó) và lưu ý vế sau của 「～に限り」 không đi với thể phủ định."}]});export{t};